"""Read the public discussion from one configured local swarm-board directory."""
from collections import deque
from contextlib import ExitStack
import fcntl
import json
import os
import stat

# A snapshot never reads session logs, runtime state, plans or engine output.
FILES = (('swarm.json', 65536), ('members.json', 512 * 1024), ('board.jsonl', 4 * 1024 * 1024))


def regular_file(stack, directory, name, limit):
    fd = os.open(name, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=directory)
    stream = stack.enter_context(os.fdopen(fd, 'rb'))
    info = os.fstat(fd)
    if not stat.S_ISREG(info.st_mode) or info.st_size > limit:
        raise ValueError('unsupported board file')
    return stream, (info.st_dev, info.st_ino, info.st_size, info.st_mtime_ns, info.st_ctime_ns)


def public_snapshot(meta, roster, lines):
    if meta['version'] != 1 or meta['backend'] != 'local' or not isinstance(roster, dict):
        raise ValueError('unsupported swarm board')
    members = []
    for name, row in roster.items():
        role = row['role']
        if not isinstance(role, str):
            raise ValueError('invalid member')
        name.encode('utf-8')
        role.encode('utf-8')
        members.append(dict(name=name, role=role))
    posts = deque(maxlen=20)
    for n, line in enumerate(lines.splitlines(keepends=True), 1):
        post = json.loads(line)
        if not line.endswith(b'\n') or type(post['seq']) is not int or post['seq'] != n:
            raise ValueError('incomplete board post')
        if post['channel'] == 'main' and post['kind'] == 'post':
            fields = {k: post[k] for k in ('time', 'agent', 'text')}
            for value in fields.values():
                if not isinstance(value, str):
                    raise ValueError('invalid board post')
                value.encode('utf-8')
            posts.append(dict(fields, seq=n))
    return dict(status='ready', members=members, posts=list(posts))


class Blackboard:
    def __init__(self, folder):
        self.folder = os.path.abspath(os.path.expanduser(folder))
        self.mark = self.snapshot = None

    def read(self):
        try:
            with ExitStack() as stack:
                directory = os.open(self.folder, os.O_DIRECTORY | os.O_RDONLY | os.O_NOFOLLOW)
                stack.callback(os.close, directory)
                lock, _ = regular_file(stack, directory, '.lock', 65536)
                fcntl.flock(lock.fileno(), fcntl.LOCK_SH | fcntl.LOCK_NB)
                streams, marks = zip(*(regular_file(stack, directory, name, limit) for name, limit in FILES))
                if self.mark != marks:
                    data = [stream.read(limit + 1) for stream, (_, limit) in zip(streams, FILES)]
                    if any(len(blob) != mark[2] for blob, mark in zip(data, marks)):
                        raise ValueError('board changed during read')
                    self.snapshot = public_snapshot(json.loads(data[0]), json.loads(data[1]), data[2])
                    self.mark = marks
                return self.snapshot
        except (OSError, KeyError, ValueError, TypeError, RecursionError):
            return dict(status='unavailable', members=[], posts=[])
