#!/usr/bin/env python3
"""The diary of one run: one entry per ledger row and one per envelope the backend sent that was refused or got no
answer, grouped by local day and by top order, each with a pointer to the line it was made from, and ten numbers per
order.

    python3 cockpit/diary.py RUN --out FOLDER [--tz local|+HH:MM]

Reads   RUN/ledger.jsonl, RUN/sent.jsonl (the backend's sender records, optional), RUN/launches.jsonl (optional).
Writes  FOLDER/diary.json and FOLDER/diary.md, each written beside itself and moved into place.
Exit    0 written; 2 usage, or a ledger that cannot be read (nothing is written then).
The same inputs give the same bytes: no wall clock goes into the diary.  `local` (the default) puts days and times in
the zone this process runs in, the TZ environment variable, which is what the calendar uses; GET /diary is this with
`local`.  cockpit/diary_check.py works every entry and number out again from the raw files."""
import argparse
import datetime
import hashlib
import json
import os
import re
import sys
import time

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)

import cli                          # noqa: E402
import dispatcher                   # noqa: E402

SENT = 'sent.jsonl'                 # serve.Writer appends one line per envelope it hands to the dispatcher
ENDS = ('order.succeeded', 'order.failed', 'order.dead', 'order.cancelled')
CLOSES = ('lease.released', 'lease.expired', 'report.submitted')
TZ = re.compile(r'([+-])(\d\d):(\d\d)')
DATE = re.compile(r'\d{4}-\d{2}-\d{2}')


class Unreadable(Exception):
    pass


def sha(data):
    return hashlib.sha256(data).hexdigest()


def read(path):
    """The bytes of an optional file; None when it is not there."""
    try:
        with open(path, 'rb') as f:
            return f.read()
    except FileNotFoundError:
        return None


def put(path, data):
    tmp = '%s.%d.tmp' % (path, os.getpid())
    with open(tmp, 'wb') as f:
        f.write(data)
    os.replace(tmp, path)


def dumps(v):
    return (json.dumps(v, ensure_ascii=False, sort_keys=True, indent=1) + '\n').encode('utf-8')


def lines_of(data):
    """The lines of a .jsonl file as bytes, without the newline that ends each; a last line with no newline counts."""
    if not data:
        return []
    out = data.split(b'\n')
    return out[:-1] if out[-1] == b'' else out


def ledger(run):
    """(bytes, rows).  The ledger must be whole: every line an event whose seq is its line number."""
    try:
        with open(os.path.join(run, cli.LEDGER), 'rb') as f:
            data = f.read()
    except OSError as e:
        raise Unreadable('the ledger cannot be read: %s' % e)
    if data and not data.endswith(b'\n'):
        raise Unreadable('the ledger does not end with a newline: its last line may be half written')
    rows = []
    for i, line in enumerate(lines_of(data), 1):
        try:
            r = json.loads(line.decode('utf-8'))
        except ValueError as e:
            raise Unreadable('ledger line %d is not JSON: %s' % (i, e))
        if not isinstance(r, dict) or r.get('seq') != i:
            raise Unreadable('ledger line %d: expected an event with seq %d' % (i, i))
        rows.append(r)
    return data, rows


def sender(data):
    """(sender records, lines by number) of the bytes of sent.jsonl.  A line that is not a JSON object whose `ok` is
    true, false or null and whose `at` is a number is nobody's record; its number is still used up."""
    sent, raw = [], {}
    for n, line in enumerate(lines_of(data), 1):
        raw[n] = line
        try:
            rec = json.loads(line.decode('utf-8'))
        except ValueError:
            continue
        if not isinstance(rec, dict) or 'ok' not in rec or not any(rec['ok'] is v for v in (True, False, None)):
            continue
        if isinstance(rec.get('at'), bool) or not isinstance(rec.get('at'), (int, float)):
            continue
        ok = rec['ok']
        sent.append({'n': n, 'id': rec.get('id'), 'at': rec['at'], 'from': rec.get('from'), 'kind': rec.get('kind'),
                     'order': rec.get('order') if isinstance(rec.get('order'), str) else None, 'ok': ok,
                     'code': rec.get('code') if ok is False else None, 'detail': rec.get('detail')})
    return sent, raw


def zone(tz):
    """'local', or a fixed offset written +HH:MM as a timezone; ValueError otherwise."""
    if tz == 'local':
        return None
    m = TZ.fullmatch(str(tz))
    if not m:
        raise ValueError(tz)
    d = datetime.timedelta(hours=int(m.group(2)), minutes=int(m.group(3)))
    return datetime.timezone(-d if m.group(1) == '-' else d)


def wall(t, tz, fmt):
    """Second t as a date or time of day in the diary's zone."""
    z = zone(tz)
    return time.strftime(fmt, time.localtime(t)) if z is None else datetime.datetime.fromtimestamp(t, z).strftime(fmt)


def date_of(text):
    """`text` when it is a real date written YYYY-MM-DD, else None."""
    if not isinstance(text, str) or not DATE.fullmatch(text):
        return None
    try:
        datetime.date.fromisoformat(text)
    except ValueError:
        return None
    return text


# ---- the entries ------------------------------------------------------------------------------------------------------

def subject(row, about):
    """The order a ledger row concerns.  `about`: {ask id: the `about` of its ask.raised row}."""
    if isinstance(row.get('order'), str):
        return row['order']
    if row['kind'] == 'order.issued':
        return (row.get('body') or {}).get('id')
    if row['kind'] == 'ask.raised':
        return row.get('about')
    if row['kind'] == 'ask.answered':
        return about.get(row.get('ask'))
    return None


def nums_of(r):
    """The numbers of one ledger row, per kind; a value the row does not carry leaves its key out."""
    k, b = r['kind'], r.get('body') or {}
    if k == 'order.issued':
        out = {'budget': b.get('budget'), 'priority': b.get('priority'),
               'writes': len(b['writes']) if isinstance(b.get('writes'), list) else None,
               'skills': len(b['skills']) if isinstance(b.get('skills'), list) else None}
    elif k in ('lease.granted', 'lease.renewed'):
        out = {'token': r.get('token'), 'ttl': r['expires'] - r['t'] if isinstance(r.get('expires'), (int, float)) else None}
    elif k in ('lease.released', 'lease.expired'):
        out = {'token': r.get('token')}
    elif k == 'artifact.rev':
        out = {'rev': r.get('rev'), 'token': r.get('token')}
    elif k == 'report.progress':
        out = {'pct': r.get('pct'), 'token': r.get('token')}
    elif k == 'report.submitted':
        out = {'outputs': len(r['outputs']) if isinstance(r.get('outputs'), list) else None, 'token': r.get('token')}
    elif k == 'order.failed':
        out = {'retry': 1 if r.get('retry') else 0}
    elif k == 'order.cancelled':
        out = {'cascade': 1 if r.get('cascade') else 0}
    elif k == 'ask.raised':
        out = {'blocking': 1 if r.get('blocking') else 0}
    elif k == 'pool.set':
        out = {'cap': r.get('cap')}
    elif k == 'notice.input-moved':
        out = {'rev': r.get('rev'), 'pinned': r.get('pinned')}
    else:
        out = {}
    return {a: v for a, v in out.items() if v is not None}


def cut(s, n=120):
    s = ' '.join(str(s).split())
    return s if len(s) <= n else s[:n] + '...'


def span(s):
    """Seconds in words: a duration, never a position in time."""
    s = int(s)
    if s < 60:
        return '%d s' % s
    if s < 3600:
        return '%d min %d s' % (s // 60, s % 60)
    return '%d h %d min' % (s // 3600, s % 3600 // 60)


def say(r, n, order):
    """One sentence about one ledger row, made only from the row's own fields."""
    k, by, o, b = r['kind'], r.get('by', '?'), order or '(no order)', r.get('body') or {}
    if k == 'org.set':
        return '%s placed %s under %s.' % (by, r.get('actor'), r.get('superior'))
    if k == 'pool.set':
        return '%s set the cap of pool %s to %s.' % (by, r.get('pool'), r.get('cap'))
    if k == 'order.issued':
        return '%s issued order %s "%s" to %s%s, budget %s, %s write scope(s)%s.' % (
            by, o, cut(b.get('title', ''), 60), b.get('to'), ' (under %s)' % b['parent'] if b.get('parent') else '',
            n.get('budget', 'not set'), n.get('writes', 0), ', with skills %s' % ', '.join(b['skills']) if b.get('skills') else '')
    if k == 'order.amended':
        return '%s amended order %s: %s.' % (by, o, ', '.join(sorted(r.get('patch') or {})) or '(no fields)')
    if k == 'order.cancelled':
        return '%s cancelled order %s%s%s.' % (by, o, ' (with the order above it)' if r.get('cascade') else '', ': ' + cut(r['reason']) if r.get('reason') else '')
    if k == 'lease.granted':
        return '%s took %s (lease %s, for %s).' % (by, o, n.get('token', '?'), span(n['ttl']) if 'ttl' in n else 'an unknown time')
    if k == 'lease.renewed':
        return '%s renewed %s (lease %s, %s more).' % (by, o, n.get('token', '?'), span(n['ttl']) if 'ttl' in n else 'an unknown time')
    if k == 'lease.released':
        return '%s let go of %s%s.' % (by, o, ': ' + cut(r['reason']) if r.get('reason') else '')
    if k == 'lease.expired':
        return 'Lease %s on %s ran out and nobody renewed it.' % (n.get('token', '?'), o)
    if k == 'artifact.rev':
        return '%s handed in %s revision %s for %s.' % (by, r.get('key'), n.get('rev', '?'), o)
    if k == 'notice.input-moved':
        return 'Notice to %s: %s, which it reads, moved from revision %s to %s.' % (o, r.get('key'), n.get('pinned', '?'), n.get('rev', '?'))
    if k == 'report.progress':
        return '%s reported on %s%s: %s' % (by, o, ' (%s%%)' % n['pct'] if 'pct' in n else '', cut(r.get('note', '')))
    if k == 'report.submitted':
        return '%s submitted %s with %s file(s)%s.' % (by, o, n.get('outputs', 0), '; evidence: ' + cut(r['evidence']) if r.get('evidence') else '')
    if k == 'order.succeeded':
        return '%s passed %s.' % (by, o)
    if k == 'order.failed':
        return '%s failed %s, %s%s.' % (by, o, 'sent back to be done again' if r.get('retry') else 'not to be done again', ': ' + cut(r['reason']) if r.get('reason') else '')
    if k == 'order.dead':
        return '%s used up its attempts and ended.' % o
    if k == 'ask.raised':
        return '%s asked %s (%s%s): %s' % (by, r.get('to'), 'about %s' % order if order else 'a proposal', ', blocking the order' if r.get('blocking') else '', cut(r.get('text', '')))
    if k == 'ask.answered':
        return '%s answered question %s: %s' % (by, r.get('ask'), cut(r.get('answer', '')))
    return '%s wrote a %s row (%s).' % (by, k, o)


def say_sent(s, kind):
    what, who = '%s (%s)' % (s['kind'], s['order'] or 'no order'), s['from'] or 'A sender with no name'
    if kind == 'sent.refused':
        return '%s sent %s and the dispatcher refused it: %s, %s' % (who, what, s['code'], cut(s['detail'] or ''))
    return '%s sent %s and got no answer from the dispatcher%s.' % (who, what, ': ' + cut(s['detail']) if s['detail'] else '')


def metrics(oid, issue, own, sent, launches):
    """The ten numbers of one order, from its own rows, the sender records and the launch records only."""
    mine = [r for r in own if r.get('order') == oid]
    grants = [r for r in mine if r['kind'] == 'lease.granted']
    first = grants[0] if grants else None
    word = next((r for r in mine if first and r['seq'] > first['seq'] and r['kind'] in ('report.progress', 'artifact.rev')), None)
    silence = None
    for g in grants:
        end = next((r for r in mine if r['seq'] > g['seq'] and r['kind'] in CLOSES), own[-1])
        inside = [r['t'] for r in own if g['seq'] <= r['seq'] <= end['seq']]
        silence = max([silence or 0] + [b - a for a, b in zip(inside, inside[1:])])
    judged = next((r for r in mine if r['kind'] in ('order.succeeded', 'order.failed')), None)
    ended = [r for r in mine if r['kind'] in ENDS and not (r['kind'] == 'order.failed' and r.get('retry'))]
    refused = {}
    for s in sent:
        if s['order'] == oid and s['ok'] is False:
            refused[str(s['code'])] = refused.get(str(s['code']), 0) + 1
    return {'claim_delay': first['t'] - issue['t'] if first else None,
            'first_word_delay': word['t'] - first['t'] if word else None,
            'max_silence': silence,
            'first_pass': judged['kind'] == 'order.succeeded' if judged else None,
            'refused': refused,
            'no_answer': sum(1 for s in sent if s['order'] == oid and s['ok'] is None),
            'expired': sum(1 for r in mine if r['kind'] == 'lease.expired'),
            'launches': None if launches is None else sum(1 for x in launches if x.get('order') == oid),
            'returned': sum(1 for r in mine if r['kind'] == 'order.failed' and r.get('retry')),
            'total_s': ended[-1]['t'] - issue['t'] if ended else None}


def build(run, tz='local'):
    """The diary of the run folder `run`.  Unreadable when its ledger cannot be read or replayed; ValueError for a tz
    that is neither 'local' nor +HH:MM."""
    zone(tz)
    ldata, rows = ledger(run)
    sdata = read(os.path.join(run, SENT))
    sent, raw = sender(sdata)
    day = lambda t: wall(t, tz, '%Y-%m-%d')
    clock = lambda t: wall(t, tz, '%H:%M:%S')

    issues = {r['body']['id']: r for r in rows if r['kind'] == 'order.issued' and isinstance(r.get('body'), dict) and 'id' in r['body']}
    about = {r.get('ask'): r.get('about') for r in rows if r['kind'] == 'ask.raised'}

    def top(oid):
        seen = set()
        while oid in issues and issues[oid]['body'].get('parent') in issues and oid not in seen:
            seen.add(oid)
            oid = issues[oid]['body']['parent']
        return oid if oid in issues else '_run'

    own = {oid: [] for oid in issues}
    entries = []
    for r in rows:
        o = subject(r, about)
        if o in own:
            own[o].append(r)
        under = (r.get('under') or {}).get('order') if r['kind'] == 'order.issued' else None
        if under in own and under != o:
            own[under].append(r)
        n = nums_of(r)
        entries.append({'id': 'L%06d' % r['seq'], 'day': day(r['t']), 'time': clock(r['t']), 'top': top(o), 'order': o, 't': r['t'],
                        'kind': r['kind'], 'by': r.get('by'), 'nums': n, 'text': say(r, n, o),
                        'ptr': [{'type': 'ledger', 'seq': r['seq'], 'h': r.get('h')}]})
    for s in sent:
        if s['ok'] is True:
            continue
        kind = 'sent.refused' if s['ok'] is False else 'sent.no-answer'
        e = {'id': 'S%06d' % s['n'], 'day': day(s['at']), 'time': clock(s['at']), 'top': top(s['order']), 'order': s['order'], 't': s['at'],
             'kind': kind, 'by': s['from'], 'nums': {}, 'text': say_sent(s, kind), 'ptr': [{'type': 'sent', 'n': s['n'], 'sha': sha(raw[s['n']])[:16]}]}
        if kind == 'sent.refused':
            e['code'] = s['code']
        entries.append(e)
    entries.sort(key=lambda e: (e['t'], e['id']))

    adata = read(os.path.join(run, 'launches.jsonl'))
    launches = None
    if adata is not None:
        launches = []
        for line in lines_of(adata):
            try:
                x = json.loads(line.decode('utf-8'))
            except ValueError:
                continue
            if isinstance(x, dict):
                launches.append(x)

    try:
        snap = dispatcher.Dispatcher(events=rows).snapshot()['orders']        # states only: the clock is not in them
    except Exception as e:                          # a ledger the dispatcher itself would not replay
        raise Unreadable('the dispatcher could not replay the ledger: %s: %s' % (type(e).__name__, e))
    orders = {}
    for oid, issue in sorted(issues.items()):
        b, now = issue['body'], snap.get(oid) or {}
        orders[oid] = {'id': oid, 'parent': b.get('parent'), 'top': top(oid), 'title': now.get('title', b.get('title', '')),
                       'to': now.get('to', b.get('to')), 'issuer': issue.get('by'),
                       'judge': (now.get('accept') or b.get('accept') or {}).get('judge'), 'state': now.get('state'),
                       'attempt': now.get('attempt'),
                       'given': {'skills': list(now.get('skills', b.get('skills')) or []), 'knowledge': list(now.get('knowledge', b.get('knowledge')) or [])},
                       'rows': [r['seq'] for r in own[oid]], 'metrics': metrics(oid, issue, own[oid], sent, launches)}

    days = {}
    for e in entries:
        fam = days.setdefault(e['day'], {}).setdefault(e['top'], {'orders': set(), 'entries': []})
        fam['entries'].append(e['id'])
        if e['order'] in issues:
            fam['orders'].add(e['order'])
    order_of = lambda t: (issues[t]['seq'] if t in issues else float('inf'), t)
    out_days = [{'date': d, 'families': [{'top': t, 'title': orders[t]['title'] if t in orders else '', 'orders': sorted(f['orders']), 'entries': f['entries']}
                                         for t, f in sorted(fams.items(), key=lambda kv: order_of(kv[0]))]} for d, fams in sorted(days.items())]
    cited = {p['seq'] for e in entries for p in e['ptr'] if p['type'] == 'ledger'}
    links = cli.chain(ldata)
    return {'v': 'cockpit-diary/1', 'run': os.path.basename(os.path.abspath(run)), 'tz': tz,
            'source': {'ledger': {'rows': len(rows), 'head': rows[-1]['seq'] if rows else 0, 'chain': links[-1] if links else None},
                       'sent': {'rows': len(lines_of(sdata)), 'sha256': sha(sdata) if sdata is not None else None},
                       'launches': {'rows': len(lines_of(adata)), 'sha256': sha(adata) if adata is not None else None}},
            'days': out_days, 'entries': entries, 'orders': orders,
            'counts': {'entries': len(entries), 'refused': sum(1 for e in entries if e['kind'] == 'sent.refused'),
                       'no_answer': sum(1 for e in entries if e['kind'] == 'sent.no-answer'),
                       'rows_total': len(rows), 'rows_cited': len(cited & {r['seq'] for r in rows})}}


def day_of(d, date):
    """What GET /diary answers for one day: that day's families with their entries written out, the orders they name
    with their ten numbers, and every day of the run with its entry count (for the month grid)."""
    by_id = {e['id']: e for e in d['entries']}
    got = next((x for x in d['days'] if x['date'] == date), {'date': date, 'families': []})
    families = [dict(f, entries=[by_id[i] for i in f['entries']]) for f in got['families']]
    named = sorted({o for f in families for o in f['orders']})
    return {'v': d['v'], 'run': d['run'], 'tz': d['tz'], 'day': date, 'source': d['source'],
            'days': [{'date': x['date'], 'entries': sum(len(f['entries']) for f in x['families'])} for x in d['days']],
            'families': families, 'orders': {o: d['orders'][o] for o in named}}


def show(v, unit=span):
    return '-' if v is None else unit(v)


def markdown(d):
    """The same diary for people.  Everything here is read off the diary's own fields."""
    c, by_id = d['counts'], {e['id']: e for e in d['entries']}
    out = ['# Diary of run %s' % d['run'], '',
           '%d day(s), %d order(s), %d entries; refused %d time(s), no answer %d time(s); %d of %d ledger rows are cited. Time zone %s.' % (
               len(d['days']), len(d['orders']), c['entries'], c['refused'], c['no_answer'], c['rows_cited'], c['rows_total'], d['tz']),
           '', 'The brackets after each entry are its source: `L` is a row of ledger.jsonl, `S` a line of sent.jsonl.', '']
    for dd in d['days']:
        out += ['## %s' % dd['date'], '']
        for f in dd['families']:
            out += ['### %s' % ('Not part of any order' if f['top'] == '_run' else '%s  %s' % (f['top'], f['title'])), '']
            if f['orders']:
                out += ['| Order | State | To | Taken after | First word after | Longest silence | First pass | Refused | No answer | Leases expired | Launches | Sent back | Total |',
                        '|---|---|---|---|---|---|---|---|---|---|---|---|---|']
                for oid in f['orders']:
                    o = d['orders'][oid]
                    m = o['metrics']
                    out.append('| %s |' % ' | '.join([
                        '`%s` %s' % (oid, o['title'].replace('|', '/')), str(o['state']), str(o['to']),
                        show(m['claim_delay']), show(m['first_word_delay']), show(m['max_silence']),
                        '-' if m['first_pass'] is None else ('yes' if m['first_pass'] else 'no'),
                        ', '.join('%s x%d' % kv for kv in sorted(m['refused'].items())) or '0', str(m['no_answer']), str(m['expired']),
                        show(m['launches'], str), str(m['returned']), show(m['total_s'])]))
                out.append('')
            for eid in f['entries']:
                e = by_id[eid]
                p = e['ptr'][0]
                out.append('- %s %s [%s]' % (e['time'], e['text'].replace('\n', ' '),
                                            'L%d %s' % (p['seq'], p['h']) if p['type'] == 'ledger' else 'S%d %s' % (p['n'], p['sha'])))
            out.append('')
    return ('\n'.join(out)).encode('utf-8')


def main(argv):
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument('run')
    ap.add_argument('--out', required=True)
    ap.add_argument('--tz', default='local')
    a = ap.parse_args(argv)                         # a usage error leaves with 2, argparse's own code
    try:
        zone(a.tz)
    except ValueError:
        print('diary: --tz is local, +HH:MM or -HH:MM, not %r' % a.tz, file=sys.stderr)
        return 2
    try:
        made = build(a.run, a.tz)
        book, page = dumps(made), markdown(made)
        os.makedirs(a.out, exist_ok=True)
    except (Unreadable, OSError) as e:
        print('diary: nothing was written: %s' % e, file=sys.stderr)
        return 2
    put(os.path.join(a.out, 'diary.json'), book)
    put(os.path.join(a.out, 'diary.md'), page)
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
