cat > 'cockpit/diary_check.py' <<'OC_EOF_9'
#!/usr/bin/env python3
"""Is every entry of a diary.json what the raw line it points at says?

    python3 cockpit/diary_check.py RUN --diary FOLDER/diary.json

Reads the run's ledger, its sender records (sent.jsonl) and its launch records itself and works everything out again;
it imports nothing from this repository (not diary.py, not the dispatcher).  Prints one JSON line:
    {entries, no_pointer, mismatch, coverage, rows_total, rows_cited, refused{diary,source}, no_answer{diary,source},
     metrics_mismatch, ok}
mismatch          entries whose pointer does not resolve (ledger seq + h, sender record line + sha256[:16]), or whose
                  id, kind, order, by, t, nums (and code, for a refusal) are not what the pointed line gives, or whose
                  day and time of day (in the diary's tz) or family (top) are not the ones the checker works out, or
                  whose sentence is empty or names neither the order nor the one who wrote the line
coverage          ledger rows some entry points at / ledger rows (1 for an empty ledger)
metrics_mismatch  orders whose ten metrics are not the checker's own, or that the diary lacks or invents, or whose
                  parent, top, title, to, issuer, judge, state, attempt, given or rows are not what the ledger gives
also              only printed when there is something to say: the days the diary draws from its entries and orders
                  that are not what the checker works out, or an entry id that stands twice.
                  `counts` is not read: what the diary says of itself is not evidence, the numbers above are
Exit 0 when no_pointer 0, mismatch 0, coverage 1, both pairs equal, metrics_mismatch 0 and nothing under `also`;
1 otherwise; 2 cannot run.
"""
import argparse
import datetime
import hashlib
import json
import os
import sys
import time

NUMS = {'order.issued': None,                       # worked out from the body, below
        'lease.granted': ('token', 'ttl'), 'lease.renewed': ('token', 'ttl'), 'lease.released': ('token',),
        'lease.expired': ('token',), 'artifact.rev': ('rev', 'token'), 'report.progress': ('pct', 'token'),
        'report.submitted': ('outputs', 'token'), 'pool.set': ('cap',), 'notice.input-moved': ('rev', 'pinned')}
FLAGS = {'order.failed': 'retry', 'order.cancelled': 'cascade', 'ask.raised': 'blocking'}


class CannotRun(Exception):
    pass


def split(data):
    parts = data.split(b'\n')
    if parts and parts[-1] == b'':
        parts.pop()
    return parts


def load(path, optional=False):
    try:
        with open(path, 'rb') as f:
            return f.read()
    except FileNotFoundError:
        if optional:
            return None
        raise CannotRun('no such file: %s' % path)
    except OSError as e:
        raise CannotRun('%s: %s' % (path, e))


def expect_nums(row):
    kind = row['kind']
    if kind in FLAGS:
        return {FLAGS[kind]: 1 if row.get(FLAGS[kind]) else 0}
    if kind == 'order.issued':
        body, got = row.get('body') or {}, {}
        for key in ('budget', 'priority'):
            if body.get(key) is not None:
                got[key] = body[key]
        for key in ('writes', 'skills'):
            if isinstance(body.get(key), list):
                got[key] = len(body[key])
        return got
    got = {}
    for key in NUMS.get(kind) or ():
        if key == 'ttl':
            if isinstance(row.get('expires'), (int, float)):
                got[key] = row['expires'] - row['t']
        elif key == 'outputs':
            if isinstance(row.get('outputs'), list):
                got[key] = len(row['outputs'])
        elif row.get(key) is not None:
            got[key] = row[key]
    return got


def expect_subject(row, asks):
    if isinstance(row.get('order'), str):
        return row['order']
    if row['kind'] == 'order.issued':
        return (row.get('body') or {}).get('id')
    if row['kind'] == 'ask.raised':
        return row.get('about')
    if row['kind'] == 'ask.answered':
        return asks.get(row.get('ask'))
    return None


def expect_sent(rec):
    """(kind, order, by, code) the diary should carry for one sender record line; None when it should carry none."""
    ok, at = rec.get('ok', 0), rec.get('at')
    if ok is True or not (ok is False or ok is None) or 'ok' not in rec:
        return None
    if isinstance(at, bool) or not isinstance(at, (int, float)):
        return None
    order = rec.get('order') if isinstance(rec.get('order'), str) else None
    if ok is None:
        return ('sent.no-answer', order, rec.get('from'), None)
    return ('sent.refused', order, rec.get('from'), rec.get('code'))


def expect_metrics(oid, rows, asks, records, launches):
    issue = None
    own = []
    for row in rows:
        if row['kind'] == 'order.issued' and (row.get('body') or {}).get('id') == oid:
            issue = row
        if expect_subject(row, asks) == oid or (row['kind'] == 'order.issued' and (row.get('under') or {}).get('order') == oid):
            own.append(row)
    of = [row for row in own if row.get('order') == oid]
    claim = first_word = silence = first_pass = total = None
    grant0 = None
    expired = returned = 0
    for i, row in enumerate(of):
        kind = row['kind']
        if kind == 'lease.granted':
            if grant0 is None:
                grant0, claim = row, row['t'] - issue['t']
            stop = own[-1]['seq']
            for later in of[i + 1:]:
                if later['kind'] in ('lease.released', 'lease.expired', 'report.submitted'):
                    stop = later['seq']
                    break
            times = [x['t'] for x in own if row['seq'] <= x['seq'] <= stop]
            widest = 0
            for k in range(1, len(times)):
                widest = max(widest, times[k] - times[k - 1])
            silence = widest if silence is None else max(silence, widest)
        elif kind in ('report.progress', 'artifact.rev'):
            if grant0 is not None and first_word is None:
                first_word = row['t'] - grant0['t']
        elif kind == 'lease.expired':
            expired += 1
        if kind in ('order.succeeded', 'order.failed') and first_pass is None:
            first_pass = kind == 'order.succeeded'
        if kind == 'order.failed' and row.get('retry'):
            returned += 1
        elif kind in ('order.succeeded', 'order.failed', 'order.dead', 'order.cancelled'):
            total = row['t'] - issue['t']
    refused, silent = {}, 0
    for kind, order, _, code in records:
        if order == oid and kind == 'sent.refused':
            refused[str(code)] = refused.get(str(code), 0) + 1
        elif order == oid and kind == 'sent.no-answer':
            silent += 1
    return {'claim_delay': claim, 'first_word_delay': first_word, 'max_silence': silence, 'first_pass': first_pass,
            'refused': refused, 'no_answer': silent, 'expired': expired,
            'launches': None if launches is None else sum(1 for x in launches if x.get('order') == oid),
            'returned': returned, 'total_s': total}


def expect_order(oid, rows, asks):
    """What the ledger alone says an order is: the fields the day view draws beside the metrics."""
    o, leased, own = None, False, []
    for row in rows:
        kind = row['kind']
        under = (row.get('under') or {}).get('order') if kind == 'order.issued' else None
        if expect_subject(row, asks) == oid or under == oid:
            own.append(row['seq'])
        if kind == 'order.issued' and (row.get('body') or {}).get('id') == oid:
            o = dict(row['body'], issuer=row.get('by'), state='PENDING', attempt=1)
        if o is None or row.get('order') != oid:
            continue
        if kind == 'order.amended':
            o.update(row.get('patch') or {})
        elif kind == 'lease.granted':
            o['state'], leased = 'LEASED', True
        elif kind in ('lease.released', 'lease.expired'):
            if leased or o['state'] == 'LEASED':
                o['state'], leased = 'PENDING', False
                o['attempt'] += 1 if kind == 'lease.expired' else 0
        elif kind == 'report.submitted':
            o['state'], leased = 'JUDGING', False
        elif kind == 'order.succeeded':
            o['state'] = 'SUCCEEDED'
        elif kind == 'order.failed':
            o['state'] = 'PENDING' if row.get('retry') else 'FAILED'
            o['attempt'] += 1 if row.get('retry') else 0
        elif kind == 'order.dead':
            o['state'] = 'DEAD'
        elif kind == 'order.cancelled':
            o['state'], leased = 'CANCELLED', False
    return {'id': oid, 'parent': o.get('parent'), 'title': o.get('title', ''), 'to': o.get('to'), 'issuer': o['issuer'],
            'judge': (o.get('accept') or {}).get('judge'), 'state': o['state'], 'attempt': o['attempt'],
            'given': {'skills': list(o.get('skills') or []), 'knowledge': list(o.get('knowledge') or [])}, 'rows': own}


def local(t, tz, fmt):
    """Second t written with fmt in a zone that is `local` (this process's) or +HH:MM; None when either is wrong."""
    try:
        if tz == 'local':
            return time.strftime(fmt, time.localtime(t))
        sign, (hh, mm) = (-1 if tz[0] == '-' else 1), tz[1:].split(':')
        if tz[0] not in '+-' or len(hh) != 2 or len(mm) != 2:
            return None
        zone = datetime.timezone(sign * datetime.timedelta(hours=int(hh), minutes=int(mm)))
        return datetime.datetime.fromtimestamp(t, zone).strftime(fmt)
    except (TypeError, ValueError, IndexError, OverflowError, OSError):
        return None


def check(run, diary_path):
    try:
        diary = json.loads(load(diary_path).decode('utf-8'))
        entries, told = diary['entries'], diary['orders']
        if not isinstance(entries, list) or not isinstance(told, dict):
            raise ValueError('entries is a list and orders an object')
    except (ValueError, KeyError, TypeError) as e:
        raise CannotRun('%s is not a diary: %s' % (diary_path, e))
    lines = split(load(os.path.join(run, 'ledger.jsonl')))
    try:
        rows = [json.loads(x.decode('utf-8')) for x in lines]
    except ValueError as e:
        raise CannotRun('the ledger is not JSON lines: %s' % e)
    log_lines = split(load(os.path.join(run, 'sent.jsonl'), optional=True) or b'')
    log = []
    for line in log_lines:
        try:
            rec = json.loads(line.decode('utf-8'))
        except ValueError:
            rec = None
        log.append(rec if isinstance(rec, dict) else {})
    launch_data = load(os.path.join(run, 'launches.jsonl'), optional=True)
    launches = None
    if launch_data is not None:
        launches = []
        for line in split(launch_data):
            try:
                x = json.loads(line.decode('utf-8'))
            except ValueError:
                continue
            if isinstance(x, dict):
                launches.append(x)
    asks = {r.get('ask'): r.get('about') for r in rows if r.get('kind') == 'ask.raised'}
    parents = {(r.get('body') or {}).get('id'): (r.get('body') or {}).get('parent') for r in rows if r.get('kind') == 'order.issued'}
    tz = diary.get('tz')

    def top_of(oid):
        seen = set()
        while oid in parents and parents[oid] in parents and oid not in seen:
            seen.add(oid)
            oid = parents[oid]
        return oid if oid in parents else '_run'

    def placed(e, t, order, names):
        """Is the entry filed under the right day, time and family, and does its sentence name one of `names` (None: any words)?"""
        text = e.get('text')
        return (e.get('day') == local(t, tz, '%Y-%m-%d') and e.get('day') is not None and e.get('time') == local(t, tz, '%H:%M:%S')
                and e.get('top') == top_of(order) and isinstance(text, str) and text.strip() != ''
                and (names is None or any(isinstance(x, str) and x and x in text for x in names)))

    no_pointer = mismatch = 0
    cited, where = set(), []
    for e in entries:
        ptr = e.get('ptr') if isinstance(e, dict) else None
        if not isinstance(ptr, list) or not ptr or not all(isinstance(p, dict) for p in ptr):
            no_pointer += 1
            continue
        p, good = ptr[0], False
        if p.get('type') == 'ledger' and isinstance(p.get('seq'), int) and 1 <= p['seq'] <= len(rows):
            row = rows[p['seq'] - 1]
            good = (p.get('h') == row.get('h') and e.get('id') == 'L%06d' % p['seq']
                    and e.get('kind') == row.get('kind') and e.get('order') == expect_subject(row, asks) and e.get('by') == row.get('by')
                    and e.get('t') == row.get('t') and e.get('nums') == expect_nums(row) and 'code' not in e)
            good = good and placed(e, row.get('t'), expect_subject(row, asks), (expect_subject(row, asks), row.get('by')))
            where.append((row.get('t') or 0, str(e.get('id')), local(row.get('t'), tz, '%Y-%m-%d'), top_of(expect_subject(row, asks)), expect_subject(row, asks)))
            if p.get('h') == row.get('h'):
                cited.add(p['seq'])
        elif p.get('type') == 'sent' and isinstance(p.get('n'), int) and 1 <= p['n'] <= len(log_lines):
            rec, want = log[p['n'] - 1], expect_sent(log[p['n'] - 1])
            good = (want is not None and p.get('sha') == hashlib.sha256(log_lines[p['n'] - 1]).hexdigest()[:16]
                    and e.get('id') == 'S%06d' % p['n'] and (e.get('kind'), e.get('order'), e.get('by')) == want[:3]
                    and e.get('t') == rec.get('at') and e.get('nums') == {} and e.get('code') == want[3]
                    and ('code' in e) == (want[0] == 'sent.refused'))
            good = good and placed(e, rec.get('at'), want[1], tuple(x for x in want[1:3] if isinstance(x, str) and x) or None)
            if want is not None:
                where.append((rec.get('at') or 0, str(e.get('id')), local(rec.get('at'), tz, '%Y-%m-%d'), top_of(want[1]), want[1]))
        if not good:
            mismatch += 1

    records = [x for x in (expect_sent(rec) for rec in log) if x]
    issued = [(r.get('body') or {}).get('id') for r in rows if r.get('kind') == 'order.issued']
    metrics_mismatch = len(set(told) ^ set(issued))
    worked = {}
    for oid in set(told) & set(issued):
        worked[oid] = dict(expect_order(oid, rows, asks), top=top_of(oid), metrics=expect_metrics(oid, rows, asks, records, launches))
        if not isinstance(told[oid], dict) or told[oid].get('metrics') != worked[oid]['metrics']:
            metrics_mismatch += 1
        elif {k: v for k, v in told[oid].items() if k != 'metrics'} != {k: v for k, v in worked[oid].items() if k != 'metrics'}:   # the other fields the day view draws for an order
            metrics_mismatch += 1

    # the parts built from the entries and the orders: the days and their families
    also = []
    ids = [e.get('id') for e in entries if isinstance(e, dict)]
    if len(set(ids)) != len(ids):
        also.append('an entry id stands twice')
    fams = {}                                               # by the day and family the checker worked out, not the entry's word
    for t, eid, day, top, order in sorted(where):
        f = fams.setdefault((day, top), {'orders': set(), 'entries': []})
        f['entries'].append(eid)
        if order in parents:
            f['orders'].add(order)
    drawn, listed = {}, 0
    for d in diary.get('days') if isinstance(diary.get('days'), list) else []:
        for f in (d.get('families') or []) if isinstance(d, dict) else []:
            listed += 1
            if isinstance(f, dict):
                drawn[(d.get('date'), f.get('top'))] = (sorted(f.get('orders') or []), f.get('entries'), f.get('title'))
    want_days = {k: (sorted(f['orders']), f['entries'], worked[k[1]]['title'] if k[1] in worked else '') for k, f in fams.items()}
    if drawn != want_days or listed != len(want_days):
        also.append('days: %d of %d families are not the entries of that day and family' % (
            sum(1 for k in set(drawn) | set(want_days) if drawn.get(k) != want_days.get(k)) or abs(listed - len(want_days)), len(want_days)))

    kinds = [e.get('kind') for e in entries if isinstance(e, dict)]
    refused = {'diary': kinds.count('sent.refused'), 'source': sum(1 for x in records if x[0] == 'sent.refused')}
    silent = {'diary': kinds.count('sent.no-answer'), 'source': sum(1 for x in records if x[0] == 'sent.no-answer')}
    full = len(cited) == len(rows)
    out = {'entries': len(entries), 'no_pointer': no_pointer, 'mismatch': mismatch,
           'coverage': 1 if full else round(len(cited) / len(rows), 4), 'rows_total': len(rows), 'rows_cited': len(cited),
           'refused': refused, 'no_answer': silent, 'metrics_mismatch': metrics_mismatch}
    if also:
        out['also'] = also
    out['ok'] = (no_pointer == 0 and mismatch == 0 and full and refused['diary'] == refused['source']
                 and silent['diary'] == silent['source'] and metrics_mismatch == 0 and not also)
    return out


def main(argv):
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument('run')
    ap.add_argument('--diary', required=True)
    a = ap.parse_args(argv)
    try:
        out = check(a.run, a.diary)
    except CannotRun as e:
        print('diary_check: cannot run: %s' % e, file=sys.stderr)
        return 2
    print(json.dumps(out, ensure_ascii=False))
    return 0 if out['ok'] else 1


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
