"""Read-only history of run ledgers, replayed by the dispatcher and cached by file metadata."""
import json
import datetime
import os
import re
import time

import cli
import dispatcher
import gitws
import live
import library as library_fields

RUN = re.compile(r'^[A-Za-z0-9._-]+$')
FAILED = ('FAILED', 'DEAD', 'CANCELLED')


def day(t):
    return time.strftime('%Y-%m-%d', time.localtime(t))


def wall_stamp(t):
    return datetime.datetime.fromtimestamp(t).astimezone().isoformat(timespec='seconds') if t is not None else None


def board_records(record, run):
    """One compact record per issued order, including nested orders and ask answers.

    Dates carry the backend's offset at that instant, including historical DST.
    The issue number counts orders, not unrelated rows in the ledger.
    """
    issued, ended, changed, holders, questions = {}, {}, {}, {}, {}
    for event in record['events']:
        kind = event['kind']
        if kind == 'ask.raised':
            questions[event['ask']] = event.get('about')
        oid = questions.get(event.get('ask')) if kind == 'ask.answered' else row_order(event)
        if oid is None:
            continue
        changed[oid] = event['t']
        if kind == 'order.issued':
            issued[oid] = (len(issued) + 1, event['t'])
        elif kind == 'lease.granted':
            holders[oid] = event.get('by')
        elif kind in ('order.succeeded', 'order.cancelled', 'order.dead') or kind == 'order.failed' and not event.get('retry'):
            ended[oid] = event['t']
    return [dict(order, run=run, number=issued[oid][0], top=record['tops'][oid],
                 top_title=record['orders'][record['tops'][oid]]['title'],
                 issued_at=wall_stamp(issued[oid][1]), ended_at=wall_stamp(ended.get(oid)),
                 changed_day=day(changed[oid]), last_holder=holders.get(oid))
            for oid, order in record['orders'].items() if oid in issued]


def row_order(e):
    return (e.get('body') or {}).get('id') if e['kind'] == 'order.issued' else e.get('order') or e.get('about')


def empty_day():
    return {'orders': [], 'planned': [], 'stats': dict.fromkeys(('issued', 'succeeded', 'failed', 'launches'), 0)}


def lead_seat(seats):
    """Both saved team formats put the run's lead first; never borrow the live team's seat."""
    seat = seats[0] if seats else {}
    return {key: seat.get(key, '') for key in ('actor', 'name', 'model', 'family')}


def progress(orders, oid):
    """Direct sub-orders are steps; a leaf order is its own single step."""
    steps = [o for o in orders.values() if o.get('parent') == oid] or [orders[oid]]
    return {'total': len(steps), 'succeeded': sum(o['state'] == 'SUCCEEDED' for o in steps)}


def order_problem(orders, events, launches, seats, board, family):
    """Explain an unresolved failure or the latest return, without counting an automatic retry as human work."""
    unfinished = [orders[k] for k in family if orders[k]['state'] != 'SUCCEEDED']
    failed = [o for o in unfinished if o['state'] in FAILED]
    returned = [e for e in events if e.get('order') in family and e['kind'] == 'order.failed']
    stopped = bool(unfinished and (board.get('halted') or board.get('fatal')))
    if not (failed or returned or stopped):
        return None
    event = next((e for e in reversed(returned) if orders[e['order']]['state'] in FAILED), returned[-1] if returned else None)
    held = next((h for h in reversed(board.get('held', [])) if h['order'] in family), None)
    oid = held['order'] if stopped and held else event['order'] if event else failed[0]['id'] if failed else unfinished[0]['id']
    launch = next((l for l in reversed(launches) if l['order'] == oid), {})
    actor = launch.get('agent') or orders[oid]['to']
    seat = next(({k: v for k, v in s.items() if k != 'outcomes'} for s in seats if actor in (s['actor'], s.get('team'))), {'actor': actor, 'name': 'Seat unavailable'})
    budget = stopped and bool(board.get('halted')) and board.get('launched', 0) >= board.get('limit', 1)
    reason = ('The run stopped because its launch allowance was used.' if budget else
              board.get('fatal') or board.get('halted') if stopped else
              event.get('reason') if event else None)
    if not reason:
        reason = launch.get('verdict', {}).get('reason') or launch.get('error') or next(
            (e.get('reason') or e.get('why') for e in reversed(events)
             if e.get('order') == oid and e['kind'] in ('order.dead', 'order.cancelled')), None)
    return {'kind': 'budget' if budget else 'failed' if failed or stopped else 'sent-back',
            'reason': reason or 'The order stopped before its work was accepted.', 'order': oid, 'seat': seat,
            'needs_attention': bool(failed or stopped), 'resolved': not unfinished,
            'retrying': bool(returned and not failed and not stopped and unfinished)}


class History:
    def __init__(self, root, current, clock):
        self.root, self.current, self.clock = os.path.abspath(root), current, clock
        self.cache = {}
        self.library = None

    def folder(self, run):
        if not isinstance(run, str) or not RUN.fullmatch(run) or run in ('.', '..', 'library'):
            raise FileNotFoundError('invalid run id')
        path = os.path.join(self.root, run)
        if os.path.islink(path) or not os.path.isdir(path) or os.path.dirname(os.path.realpath(path)) != os.path.realpath(self.root):
            raise FileNotFoundError('no such run folder')
        return path

    def read(self, run):
        path = self.folder(run)
        ledger = os.path.join(path, cli.LEDGER)
        if os.path.islink(ledger):
            raise ValueError('ledger must be a regular file')
        st = os.stat(ledger)
        mark = (st.st_size, st.st_mtime_ns, st.st_ino)
        if run not in self.cache or self.cache[run][0] != mark:
            events = cli.read_ledger(path)
            d = dispatcher.Dispatcher(events=events)
            snapshot = d.snapshot()
            orders = snapshot['orders']
            issued = {e['body']['id']: e for e in events if e['kind'] == 'order.issued'}
            tops = {}
            for oid in orders:
                top, seen = oid, set()
                while orders[top].get('parent'):
                    if top in seen:
                        raise ValueError('cyclic order ancestry')
                    seen.add(top)
                    top = orders[top]['parent']
                tops[oid] = top
            self.cache[run] = (mark, {'orders': orders, 'events': events, 'issued': issued, 'tops': tops, 'state': snapshot})
        return self.cache[run][1]

    def runs(self):
        good, skipped = {}, []
        for name in sorted(os.listdir(self.root)):
            if name == 'library':
                continue
            path = os.path.join(self.root, name)
            if not os.path.isdir(path) and not os.path.islink(path):
                continue
            try:
                good[name] = self.read(name)
            except (OSError, ValueError, KeyError, TypeError, AttributeError, cli.LedgerError) as e:
                skipped.append({'run': name, 'why': '%s: %s' % (type(e).__name__, str(e).replace(self.root + os.sep, ''))})
        return good, skipped

    def board(self, run):
        path = os.path.join(self.folder(run), 'logs', 'team.json')
        try:
            with open(path, encoding='utf-8') as f:
                return json.load(f)
        except FileNotFoundError:
            return {}

    def seats(self, run, board):
        path = os.path.join(self.folder(run), 'team.json')
        try:
            with open(path, encoding='utf-8') as f:
                team = json.load(f)
            return [dict(s, name=s.get('name') or s['id'], actor=('team:' if i == 0 else 'agent:') + s['id'],
                         team='team:' + s['id'], family=live.family(s['model']))
                    for i, s in enumerate([team['lead']] + team['seats'])]
        except FileNotFoundError:
            return [dict(s, id=s['actor'].split(':', 1)[-1]) for s in board.get('seats', [])]

    def launches(self, run):
        board = self.board(run)
        if 'launches' in board:
            rows = board['launches']
        else:
            try:
                with open(os.path.join(self.folder(run), 'launches.jsonl'), encoding='utf-8') as f:
                    rows = [json.loads(line) for line in f]
            except FileNotFoundError:
                rows = []
        out = []
        for row in rows:
            started = row.get('started', row.get('t0'))
            ended = row.get('ended', row.get('t1'))
            if ended is None and row.get('state') != 'running' and started is not None and 'secs' in row:
                ended = started + row['secs']
            out.append(dict(row, started=started, ended=ended))
        return out

    def summary(self, plans):
        runs, skipped = self.runs()
        now = self.clock()
        out = {'today': day(now), 'live_run': self.current, 'runs': [], 'days': {}, 'skipped': skipped, 'board': []}
        today = datetime.date.fromisoformat(out['today'])
        monday = today - datetime.timedelta(days=today.weekday())
        out['week'] = [(monday + datetime.timedelta(days=i)).isoformat() for i in range(7)]
        for run, r in runs.items():
            events, orders = r['events'], r['orders']
            run_day = day(events[0]['t']) if events else day(os.stat(self.folder(run)).st_mtime)
            out['runs'].append({'run': run, 'live': run == self.current, 'day': run_day})
            try:
                board = self.board(run)
                seats = self.seats(run, board)
                lead = lead_seat(seats)
            except (OSError, ValueError, KeyError, TypeError) as e:
                out['skipped'].append({'run': run, 'why': 'team records unreadable: ' + type(e).__name__})
                lead = lead_seat([])
                seats = []
                board = {}
            try:
                launches = self.launches(run)
            except (OSError, ValueError, TypeError) as e:
                out['skipped'].append({'run': run, 'why': 'launch records unreadable: ' + type(e).__name__})
                launches = []
            state = r.get('state', {})
            out['board'].append({'run': run, 'rows': len(events), 'now': now,
                                 'tasks': board_records(r, run), 'actors': seats,
                                 'leases': state.get('leases', {}) if run == self.current else {},
                                 'asks': state.get('asks', {})})
            for oid, o in orders.items():
                if o.get('parent'):
                    continue
                e = r['issued'][oid]
                target = out['days'].setdefault(day(e['t']), empty_day())
                family = {k for k, top in r['tops'].items() if top == oid}
                problem = order_problem(orders, events, launches, seats, board, family)
                attention = bool(problem and problem['needs_attention'])
                steps = [orders[k] for k in r['issued'] if orders[k].get('parent') == oid] or [o]
                actors = list(dict.fromkeys(l['agent'] for l in launches if l['order'] in family and l.get('agent')))
                participants = []
                for actor in actors:
                    member = next((dict(s, slot=i % 6 + 1) for i, s in enumerate(seats)
                                   if actor in (s['actor'], s.get('team'))),
                                  {'actor': actor, 'name': 'Seat unavailable'})
                    if not any(s['actor'] == member['actor'] for s in participants):
                        participants.append(member)
                target['orders'].append({'run': run, 'id': oid, 'title': o['title'], 'state': o['state'], 'to': o['to'], 't': e['t'], 'attention': attention, 'lead': dict(lead), 'progress': progress(orders, oid),
                                         'steps': [{k: step[k] for k in ('id', 'title', 'state')} for step in steps],
                                         'participants': participants, 'problem': problem, 'goal': o.get('goal', ''),
                                         'library_uses': self.library.order(run, oid, family)['uses'] if self.library else []})
                stats = target['stats']
                stats['issued'] += 1
                stats['succeeded'] += o['state'] == 'SUCCEEDED'
                stats['failed'] += o['state'] in FAILED
                stats['launches'] += sum(l['order'] in family for l in launches)
        for p in plans.values():
            out['days'].setdefault(p['day'], empty_day())['planned'].append(
                {k: p.get(k) for k in ('id', 'title', 'state', 'run', 'order')})
        return out

    def order(self, run, oid, include_answers=False):
        r = self.read(run)
        orders, events = r['orders'], r['events']
        if oid not in orders:
            raise FileNotFoundError('unknown order')
        # Index this replay once. Branches only visit their own rows, and answers
        # can be joined by ask id without another read of the run in the handler.
        by_order, answers = {}, {}
        latest = events[0]['t'] if events else 0
        for event in events:
            by_order.setdefault(row_order(event), []).append(event)
            if event['kind'] == 'ask.answered':
                answers.setdefault(event.get('ask'), []).append(event)
            latest = max(latest, event['t'])

        def rows_for(branch):
            return sorted((e for k in branch for e in by_order.get(k, ())), key=lambda e: e['seq'])

        family = {oid}
        while True:
            more = {k for k, o in orders.items() if o.get('parent') in family} - family
            if not more:
                break
            family.update(more)
        def node(k):
            o = orders[k]
            branch = {k}
            while True:
                children = {n for n in family if orders[n].get('parent') in branch} - branch
                if not children:
                    break
                branch.update(children)
            return dict(o, by=r['issued'][k]['by'], judge=o.get('accept', {}).get('judge', ''), day=day(r['issued'][k]['t']),
                        top=r['tops'][k], writes=', '.join(o.get('writes', [])), progress=progress(orders, k),
                        problem=order_problem(orders, rows_for(branch), launches, seats, board, branch))
        board = self.board(run)
        seats = self.seats(run, board)
        ledger = rows_for(family)
        outcomes, _ = live.outcome_counts({k: orders[k] for k in family}, ledger, seats)
        seats = [dict(s, outcomes=outcomes[s['actor']]) for s in seats]
        launches = self.launches(run)
        updated = self.clock() if run == self.current else max(
            [latest, board.get('updated', 0)] + [l['ended'] for l in launches if l['ended'] is not None])
        terminal = [e['t'] for e in by_order.get(oid, ()) if e.get('order') == oid and
                    (e['kind'] in ('order.succeeded', 'order.dead', 'order.cancelled') or
                     e['kind'] == 'order.failed' and not e.get('retry'))]
        started, ended = r['issued'][oid]['t'], terminal[-1] if terminal else None
        stopped = min([h['at'] for h in board.get('held', []) if h.get('at') is not None], default=board.get('updated', updated)) if board.get('halted') or board.get('fatal') else None
        nodes = {k: node(k) for k in orders if k in family}
        files = self.files(run, family, record=r, events=ledger)
        if include_answers:
            asks = {e['ask'] for e in ledger if e['kind'] == 'ask.raised'}
            ledger = sorted(ledger + [e for ask in asks for e in answers.get(ask, ())], key=lambda e: e['seq'])
        return {'run': run, 'live': run == self.current, 'lead': lead_seat(seats), 'order': nodes[oid],
                'run_started': events[0]['t'] if events else None, 'updated': updated,
                'timing': {'started': started, 'ended': ended, **({'stopped': stopped} if stopped is not None else {}), 'seconds': max(0, (ended if ended is not None else stopped if stopped is not None else updated) - started)},
                'children': [nodes[k] for k, o in orders.items() if o.get('parent') == oid],
                'nodes': list(nodes.values()),
                'seats': seats, 'launches': [l for l in launches if l['order'] in family],
                'files': files, 'ledger': ledger,
                'library': self.library.order(run, oid, family) if self.library else
                           {'workflow': None, 'uses': [], 'proposed': [], 'saved': {}}}

    def artifacts(self, run, family=None, events=None):
        newest = {}
        for e in self.read(run)['events'] if events is None else events:
            if e['kind'] == 'artifact.rev' and (family is None or e.get('order') in family):
                note = e.get('note', '')
                if re.fullmatch(r'git:[0-9a-f]{40,64}', note):
                    newest[e['key']] = (e, note[4:])
        return newest

    def files(self, run, family, record=None, events=None):
        git = gitws.Git(os.path.join(self.folder(run), 'repo.git'))
        try:
            accepted = git.tree('refs/tags/accepted/' + live.TOPIC)
        except RuntimeError:
            accepted = {}
        record = self.read(run) if record is None else record
        orders = record['orders']
        return [{'path': key, 'order': e['order'], 'rev': e['rev'], 'size': int(git('cat-file', '-s', sha)),
                 'keep_title': library_fields.keep_title(git.raw('cat-file', 'blob', sha)[:65536].decode('utf-8', 'replace'), orders[e['order']]['title']),
                 'accepted': accepted.get(key) == sha, 'by': e.get('by'), 'at': e['t'], 'seq': e['seq']}
                for key, (e, sha) in sorted(self.artifacts(run, family, record['events'] if events is None else events).items())]

    def read_file(self, run, path, limit=65536):
        if not path or path.startswith('/') or '\\' in path or any(p in ('', '.', '..') for p in path.split('/')):
            return None
        item = self.artifacts(run).get(path)
        if item is None:
            return None
        e, sha = item
        data = gitws.Git(os.path.join(self.folder(run), 'repo.git')).raw('cat-file', 'blob', sha)
        try:
            text, binary = data[:limit].decode('utf-8'), False
        except UnicodeDecodeError:
            text, binary = '', True
        return {'path': path, 'rev': e['rev'], 'size': len(data), 'text': text, 'binary': binary, 'truncated': len(data) > limit}

    def file_bytes(self, run, path, family):
        """The exact blob represented by a file in this order's GET /order result."""
        item = self.artifacts(run, family).get(path)
        if item is None:
            return None
        return gitws.Git(os.path.join(self.folder(run), 'repo.git')).raw('cat-file', 'blob', item[1])
