"""A durable, shared library. Call from the server lock; flock also serializes separate runs.

One atomic JSON snapshot holds bytes, entries and receipts together, so a review or a
replayed plan cannot leave half a change behind. Ledger-derived records are idempotent.
"""
import base64
import contextlib
import datetime
import difflib
import fcntl
import hashlib
import json
import os
import re
import tempfile
import uuid

LIMIT = 65536
KINDS = ('artifact', 'skill', 'workflow', 'lesson')
FINAL = ('SUCCEEDED', 'FAILED', 'DEAD', 'CANCELLED')
REPO = os.path.dirname(os.path.dirname(os.path.realpath(__file__)))


class Error(ValueError):
    def __init__(self, code, detail, status=400):
        super().__init__(detail)
        self.code, self.status = code, status


def outside_repo(root):
    if os.path.commonpath((os.path.realpath(root), REPO)) == REPO:
        raise ValueError('The runs root must be outside the repository; it holds the shared library.')


def encoded(doc):
    # Match the HTTP handler's serialization, including its byte limit.
    return json.dumps(doc, ensure_ascii=False).encode('utf-8')


def iso(t):
    return datetime.datetime.fromtimestamp(t, datetime.timezone.utc).isoformat()


def key(*parts):
    return json.dumps(parts)


def public(entry):
    return {k: v for k, v in entry.items() if not k.startswith('_')}


def preview(data):
    return data[:LIMIT].decode('utf-8', 'replace').encode('utf-8')[:LIMIT].decode('utf-8', 'ignore')


def utf8(value):
    if isinstance(value, str):
        try:
            return value.encode('utf-8')
        except UnicodeEncodeError:
            pass
    return None


def keep_title(text, order_title):
    """A readable default, derived from the handed-in bytes and source order."""
    lines = text.splitlines()
    fenced = False
    for i, line in enumerate(lines):
        if re.match(r'^\s*(```|~~~)', line):
            fenced = not fenced
        if fenced:
            continue
        heading = re.match(r'^\s{0,3}#{1,6}\s+(.+?)\s*#*\s*$', line)
        if heading:
            return heading[1].strip()[:200]
        if line.strip() and i + 1 < len(lines) and re.fullmatch(r'\s*(?:={3,}|-{3,})\s*', lines[i + 1]):
            return line.strip()[:200]
    return re.sub(r'^(?:(?:Draft|Review):\s*)+', '', order_title, flags=re.I).strip()[:200]


def first_sentence(text):
    lines = [line.strip() for line in text.splitlines() if line.strip() and not re.match(r'^\s*(?:#|```|~~~|={3,}|-{3,})', line)]
    return re.split(r'(?<=[.!?])\s+', ' '.join(lines), maxsplit=1)[0] if lines else ''


def lineage(entry, known):
    seen = set()
    while entry.get('replaces') in known and entry['id'] not in seen:
        seen.add(entry['id'])
        entry = known[entry['replaces']]
    return entry['id']


def difference(before, after):
    """A lossless line comparison, with equal spans kept for in-place expansion."""
    left, right = before.splitlines(), after.splitlines()
    groups = []
    for op, a, b, c, d in difflib.SequenceMatcher(None, left, right, autojunk=False).get_opcodes():
        if op == 'equal':
            groups.append({'kind': 'same', 'lines': left[a:b], 'before_line': a + 1, 'after_line': c + 1})
        else:
            if a != b:
                groups.append({'kind': 'remove', 'lines': left[a:b], 'before_line': a + 1, 'after_line': None})
            if c != d:
                groups.append({'kind': 'add', 'lines': right[c:d], 'before_line': None, 'after_line': c + 1})
    return {'groups': groups, 'added': sum(len(g['lines']) for g in groups if g['kind'] == 'add'),
            'removed': sum(len(g['lines']) for g in groups if g['kind'] == 'remove'),
            'before_final_newline': before.endswith('\n'), 'after_final_newline': after.endswith('\n')}


class Library:
    def __init__(self, root, clock):
        outside_repo(root)
        self.root, self.clock = os.path.join(root, 'library'), clock
        if os.path.islink(self.root):
            raise ValueError('The library must be a real folder, not a symlink.')
        os.makedirs(self.root, exist_ok=True)
        self.path = os.path.join(self.root, 'index.json')
        self.lock = os.path.join(self.root, 'writer.lock')
        with self.transaction():
            pass

    def read(self):
        try:
            with open(self.path, encoding='utf-8') as f:
                return json.load(f)
        except FileNotFoundError:
            return {'v': 'library-store/1', 'entries': [], 'plans': {}, 'next': 1}

    @contextlib.contextmanager
    def transaction(self):
        with open(self.lock, 'a+b') as lock:
            fcntl.flock(lock, fcntl.LOCK_EX)
            doc = self.read()
            before = encoded(doc)
            yield doc
            data = encoded(doc)
            if data == before and os.path.exists(self.path):
                return
            fd, path = tempfile.mkstemp(prefix='.library-', dir=self.root)
            try:
                with os.fdopen(fd, 'wb') as f:
                    f.write(data)
                    f.flush()
                    os.fsync(f.fileno())
                os.replace(path, self.path)
                directory = os.open(self.root, os.O_RDONLY)
                try:
                    os.fsync(directory)
                finally:
                    os.close(directory)
            finally:
                if os.path.exists(path):
                    os.unlink(path)

    def add(self, doc, receipt, kind, title, status, by, source, data=b'', at=None, **fields):
        old = next((e for e in doc['entries'] if e['_key'] == receipt), None)
        if old is not None:
            return old
        n = doc['next']
        suffix = '-' + str(n)
        slug = re.sub('[^a-z0-9]+', '-', title.lower()).strip('-') or 'entry'
        stem = (kind + '-' + slug)[:48 - len(suffix)].rstrip('-')
        e = {'id': stem + suffix, 'kind': kind, 'title': title, 'status': status, 'by': by,
             'at': iso(self.clock() if at is None else at), 'source': source, 'tags': [], 'replaces': None,
             'version': 1, 'used': 0, 'summary': ' '.join(preview(data).split())[:200],
             'sha256': hashlib.sha256(data).hexdigest(), 'bytes': len(data),
             'steps': [], 'metrics': {}, 'uses': [], 'reason': '',
             '_data': base64.b64encode(data).decode('ascii'), '_key': receipt, '_n': n}
        e.update(fields)
        doc['next'] += 1
        doc['entries'].append(e)
        return e

    def observations(self, doc, history):
        rows = {}
        if history is None:
            return rows
        for plan in doc['plans'].values():
            if not plan['uses']:
                continue
            marker = key(plan['run'], plan['order'])
            if marker in rows:
                continue
            detail = history.order(plan['run'], plan['order'])
            returned = sum(e['kind'] == 'order.failed' for e in detail['ledger'])
            order = detail['order']
            failed = order['state'] in FINAL[1:] or bool(order.get('problem', {}).get('needs_attention') if order.get('problem') else False)
            rows[marker] = {'run': plan['run'], 'order': plan['order'], 'title': order['title'],
                            'state': order['state'], 'outcome': 'failed' if failed else 'accepted' if order['state'] == 'SUCCEEDED' else 'running',
                            'sent_back': returned, 'launches': len(detail['launches']), 'seconds': detail['timing']['seconds'],
                            'at': iso(detail['timing']['started'])}
        return rows

    def describe(self, entry, doc, observations, history=None):
        known = {e['id']: e for e in doc['entries']}
        root = lineage(entry, known)
        uses = list(dict.fromkeys(key(p['run'], p['order']) for p in doc['plans'].values() if entry['id'] in p['uses']))
        observed = sorted([observations[k] for k in uses if k in observations], key=lambda row: row['at'])
        result = dict(public(entry), root=root, pending=sum(e['status'] == 'proposed' and lineage(e, known) == root for e in doc['entries']),
                      last_used=observed[-1] if observed else None, usage=observed,
                      search_text=base64.b64decode(entry['_data']).decode('utf-8', 'replace'))
        source_title = entry['title']
        if history is not None:
            source_title = history.read(entry['source']['run'])['orders'].get(entry['source']['order'], {}).get('title', source_title)
            seats = history.seats(entry['source']['run'], history.board(entry['source']['run']))
            result['author'] = next((dict(s, slot=i % 6 + 1) for i, s in enumerate(seats) if entry['by'] in (s['actor'], s.get('team'))),
                                    {'actor': entry['by'], 'name': 'You' if entry['by'] == 'human:ceo' else 'Library'})
        # Migrate only the presentation of legacy generated titles. A person's
        # explicit title remains theirs; stored titles and bytes never change.
        stem = os.path.splitext(os.path.basename(entry.get('source', {}).get('path', '')))[0]
        legacy = re.match(r'^[^/]+\s/\s(?:Draft:|Review:)', entry['title']) or bool(stem and entry['title'].startswith(stem + ' / '))
        previous = known.get(entry.get('replaces'))
        inherited = previous and entry['title'] == previous['title']
        result.update(display_title=keep_title(result['search_text'], source_title) if legacy or inherited or entry.get('title_origin') == 'file' else entry['title'],
                      source_title=source_title, first_sentence=first_sentence(result['search_text']),
                      current=entry['status'] == 'accepted' and not any(e['status'] == 'accepted' and e.get('replaces') == entry['id'] for e in doc['entries']),
                      history_group=key(entry['kind'], entry['title'], entry['by']) if entry['kind'] == 'lesson' else entry['id'])
        if entry['status'] == 'proposed':
            old = known.get(entry['replaces'])
            result['diff'] = difference(base64.b64decode(old['_data']).decode('utf-8', 'replace') if old else '', result['search_text'])
        return result

    def listing(self, history=None):
        doc = self.read()
        entries, observations = doc['entries'], self.observations(doc, history)
        described = {e['id']: self.describe(e, doc, observations, history) for e in entries}
        context = self.context()
        return {'entries': [described[e['id']] for e in sorted(entries, key=lambda e: (e['at'], e['_n']), reverse=True)],
                'popular': [described[e['id']] for e in sorted(entries, key=lambda e: (e['used'], e['at'], e['_n']), reverse=True)[:6]],
                'counts': {kind: sum(e['kind'] == kind for e in entries) for kind in KINDS},
                'available': {kind: [{k: e[k] for k in ('id', 'title')} for e in context[kind]] for kind in ('skills', 'artifacts')}}

    def item(self, eid, history=None):
        doc = self.read()
        entry = next((e for e in doc['entries'] if e['id'] == eid), None)
        if entry is None:
            raise Error('unknown-entry', 'No library entry has that id.', 404)
        observations = self.observations(doc, history)
        result = self.describe(entry, doc, observations, history)
        known = {e['id']: e for e in doc['entries']}
        result['versions'] = [dict(self.describe(e, doc, observations, history), text=preview(base64.b64decode(e['_data'])))
                              for e in doc['entries'] if lineage(e, known) == result['root']]
        return dict(result, text=preview(base64.b64decode(entry['_data'])))

    def compare(self, left, right):
        known = {e['id']: e for e in self.read()['entries']}
        if right not in known or left not in known or lineage(known[left], known) != lineage(known[right], known):
            raise Error('bad-comparison', 'Choose two versions of the same entry.')
        return dict(difference(*(base64.b64decode(known[e]['_data']).decode('utf-8', 'replace') for e in (left, right))),
                    before=left, after=right)

    def save(self, body, history, actor):
        run, oid, path = (body.get(k) for k in ('run', 'order', 'path'))
        # Resolve the exact same family and revision as GET /order, never a disk path.
        try:
            if not isinstance(path, str) or not path or path.startswith('/') or '\\' in path or any(
                    p in ('', '.', '..') for p in path.split('/')):
                raise FileNotFoundError()
            detail = history.order(run, oid)
            handed = next((f for f in detail['files'] if f['path'] == path), None)
            if handed is None:
                raise FileNotFoundError()
            data = history.file_bytes(run, path, {n['id'] for n in detail['nodes']})
            if data is None:
                raise FileNotFoundError()
        except (OSError, ValueError, KeyError, TypeError, RuntimeError):
            raise Error('not-a-handed-in-file', 'Choose a file listed for this run and order.') from None
        if body.get('revision', handed['rev']) != handed['rev']:
            raise Error('stale-revision', 'The file has a newer revision. Review it before keeping it.', 409)
        kind, title, tags = body.get('kind'), body.get('title'), body.get('tags', [])
        if (kind not in ('artifact', 'skill') or utf8(title) is None or not title.strip()
                or len(title) > 200 or not isinstance(tags, list) or any(utf8(t) is None for t in tags)):
            raise Error('bad-entry', 'Use artifact or skill, a title of 1 to 200 characters, and a list of text tags.')
        if kind == 'skill':
            try:
                data.decode('utf-8')
            except UnicodeDecodeError:
                raise Error('bad-entry', 'A skill must be UTF-8 text.') from None
        with self.transaction() as doc:
            # A changed revision is a new receipt; retries of the same keep are idempotent.
            receipt = key('save', run, oid, path, kind, handed['rev'])
            legacy = next((e for e in doc['entries'] if e['_key'] == key('save', run, oid, path, kind)
                           and e['sha256'] == hashlib.sha256(data).hexdigest()), None)
            entry = legacy or self.add(doc, receipt, kind, title.strip(), 'accepted', actor,
                                       {'run': run, 'order': oid, 'path': path}, data, tags=tags, revision=handed['rev'],
                                       title_origin='file' if title.strip() == handed.get('keep_title') else 'custom')
        return public(entry)

    def edit(self, body, actor):
        title, tags = body.get('title'), body.get('tags')
        if utf8(title) is None or not title.strip() or len(title) > 200 or not isinstance(tags, list) or any(utf8(t) is None for t in tags):
            raise Error('bad-entry', 'Use a title of 1 to 200 characters and text tags.')
        with self.transaction() as doc:
            entry = next((e for e in doc['entries'] if e['id'] == body.get('id')), None)
            if entry is None or not entry['_key'].startswith('["save",'):
                raise Error('not-editable', 'Only a kept file has editable title and tags.')
            entry.setdefault('metadata_history', []).append({'title': entry['title'], 'tags': entry['tags'], 'by': actor, 'at': iso(self.clock())})
            entry.update(title=title.strip(), title_origin='custom', tags=list(dict.fromkeys(t.strip() for t in tags if t.strip())))
        return public(entry)

    def review(self, body, actor):
        with self.transaction() as doc:
            entry = next((e for e in doc['entries'] if e['id'] == body.get('id')), None)
            if entry is None or entry['status'] != 'proposed':
                raise Error('not-reviewable', 'Only a proposed entry can be reviewed.')
            decision, reason = body.get('decision'), body.get('reason', '')
            if decision not in ('accept', 'reject', 'decline') or utf8(reason) is None:
                raise Error('bad-review', 'Use accept or reject and a text reason.')
            if decision == 'reject' and not reason.strip():
                raise Error('reason-needed', 'Rejecting a proposal needs a reason.')
            old = next((e for e in doc['entries'] if e['id'] == entry['replaces']), None)
            if decision == 'accept' and old is not None and old['status'] != 'accepted':
                raise Error('stale-proposal', 'The replaced version is no longer current. Review its latest version.', 409)
            now = self.clock()
            undo = {'token': uuid.uuid4().hex, 'until': now + 6, 'status': entry['status'], 'reason': entry['reason'],
                    'previous_status': old['status'] if old else None}
            entry.setdefault('proposal_reason', entry['reason'])
            entry.update(status='accepted' if decision == 'accept' else 'rejected', reason=reason.strip(),
                         reviewed_by=actor, reviewed_at=iso(now))
            entry.setdefault('review_history', []).append({'decision': decision, 'reason': reason.strip(), 'by': actor, 'at': iso(now)})
            if decision == 'accept':
                if old is not None:
                    old['status'] = 'superseded'
            else:
                lesson = self.add(doc, key('rejected', entry['id'], len(entry['review_history'])), 'lesson', 'Rejected: ' + entry['title'],
                         'recorded', actor, entry['source'], reason.strip().encode('utf-8'),
                         order=entry['source']['order'], seat=entry['by'], reason=reason.strip())
                undo['lesson'] = lesson['id']
            entry['_undo'] = undo
        return dict(public(entry), undo={k: undo[k] for k in ('token', 'until')})

    def undo(self, body, actor):
        with self.transaction() as doc:
            entry = next((e for e in doc['entries'] if e['id'] == body.get('id')), None)
            undo = entry.get('_undo') if entry else None
            if not undo or undo['token'] != body.get('token') or self.clock() > undo['until']:
                raise Error('undo-expired', 'The six-second undo window has ended.', 409)
            if any(e['replaces'] == entry['id'] and e['status'] == 'accepted' for e in doc['entries']):
                raise Error('undo-conflict', 'A newer accepted version depends on this decision.', 409)
            old = next((e for e in doc['entries'] if e['id'] == entry['replaces']), None)
            if old is not None and entry['status'] == 'accepted':
                old['status'] = undo['previous_status']
            entry.update(status=undo['status'], reason=undo['reason'])
            for e in doc['entries']:
                if e['id'] == undo.get('lesson'):
                    e['status'] = 'undone'
            entry['review_history'].append({'decision': 'undo', 'by': actor, 'at': iso(self.clock())})
            del entry['_undo']
        return public(entry)

    def _plan(self, doc, run, oid, token, actor, at, plan):
        receipt = key(run, oid, token)
        if receipt in doc['plans']:
            return
        known = {e['id']: e for e in doc['entries']}
        used, unknown = [], []
        values = plan.get('uses', [])
        for eid in values if isinstance(values, list) else []:
            if utf8(eid) is None or eid in used or eid in unknown:
                continue
            if eid in known:
                known[eid]['used'] += 1
                used.append(eid)
            else:
                unknown.append(eid)
        source = {'run': run, 'order': oid, 'path': '_dispatch/plan.json'}
        proposals = plan.get('propose', [])
        for i, p in enumerate(proposals[:3] if isinstance(proposals, list) else []):
            if not isinstance(p, dict) or p.get('kind') != 'skill':
                continue
            title, text, replaces, why = (p.get(k) for k in ('title', 'text', 'replaces', 'why'))
            data = utf8(text)
            if (utf8(title) is None or not title.strip() or len(title) > 200
                    or data is None or not text.strip() or len(data) > 8192
                    or utf8(why) is None or (replaces is not None and
                    (not isinstance(replaces, str) or replaces not in known or known[replaces]['kind'] != 'skill'))):
                continue
            self.add(doc, key('proposal', run, oid, token, i), 'skill', title.strip(), 'proposed', actor, source,
                     data, at=at, replaces=replaces,
                     version=known[replaces]['version'] + 1 if replaces else 1, reason=why, proposal_reason=why,
                     tags=known[replaces]['tags'][:] if replaces else [])
        doc['plans'][receipt] = {'run': run, 'order': oid, 'uses': used, 'unknown_uses': unknown}

    def record_plan(self, run, launch, plan, at):
        with self.transaction() as doc:
            self._plan(doc, run, launch['order'], launch['token'], launch['agent'], at, plan)

    @staticmethod
    def usage(doc, run, oid):
        receipts = [p for p in doc['plans'].values() if p['run'] == run and p['order'] == oid]
        return {k: list(dict.fromkeys(eid for p in receipts for eid in p[k])) for k in ('uses', 'unknown_uses')}

    def sync(self, history):
        """Backfill old runs and recover after a ledger append but before the library receipt."""
        runs, _ = history.runs()
        with self.transaction() as doc:
            for run, r in runs.items():
                leases = {}
                for event in r['events']:
                    kind, oid = event['kind'], event.get('order')
                    if kind == 'lease.granted':
                        leases[oid] = event
                    if kind == 'order.issued':
                        parent = event['body'].get('parent')
                        lease = leases.get(parent)
                        if lease and key(run, parent, lease['token']) not in doc['plans']:
                            # Only plans proven to have issued sub-orders may affect the library.
                            box = os.path.join(os.path.realpath(history.folder(run)), 'sandboxes', '%s.%d' % (parent, lease['token']))
                            path = os.path.join(box, '_dispatch', 'plan.json')
                            if not re.fullmatch(r'[a-z0-9][a-z0-9_.-]{0,63}', parent):
                                continue
                            if os.path.realpath(path) != os.path.abspath(path):
                                continue
                            try:
                                with open(path, encoding='utf-8') as f:
                                    plan = json.load(f)
                                if isinstance(plan, dict):
                                    self._plan(doc, run, parent, lease['token'], lease['by'], event['t'], plan)
                            except (OSError, ValueError):
                                pass
                    if kind in ('order.failed', 'order.dead'):
                        o = r['orders'][oid]
                        reason = event.get('reason', 'The lease expired too many times.')
                        self.add(doc, key('lesson', run, event['seq']), 'lesson', 'Review: ' + o['title'],
                                 'recorded', event['by'], {'run': run, 'order': oid, 'path': 'ledger.jsonl'},
                                 reason.encode('utf-8'), at=event['t'], order=oid,
                                 seat=leases.get(oid, {}).get('by', o['to']), reason=reason)
                for oid, o in r['orders'].items():
                    if o.get('parent') or o['state'] not in FINAL:
                        continue
                    ended = next(e for e in reversed(r['events']) if e.get('order') == oid and
                                 e['kind'] in ('order.succeeded', 'order.failed', 'order.dead', 'order.cancelled'))
                    family = {k for k, top in r['tops'].items() if top == oid}
                    counts = {k: 0 for k in family}
                    for e in r['events']:
                        if e['kind'] == 'lease.granted' and e['order'] in family:
                            counts[e['order']] += 1
                    steps = [{'order': k, 'seat': child['to'], 'title': child['title'], 'after': child['after'],
                              'reads': child['reads'], 'writes': child['writes']}
                             for k, issued in r['issued'].items() if k in family and k != oid
                             for child in [issued['body']]]
                    metrics = {'state': o['state'], 'launches': sum(counts.values()),
                               'sent_back': sum(max(0, n - 1) for n in counts.values()),
                               'seconds': ended['t'] - r['issued'][oid]['t']}
                    self.add(doc, key('workflow', run, oid), 'workflow', o['title'], 'recorded', 'program:library',
                             {'run': run, 'order': oid, 'path': 'ledger.jsonl'}, at=ended['t'], steps=steps,
                             metrics=metrics, **self.usage(doc, run, oid))

    def context(self):
        entries = self.read()['entries']
        known = {e['id']: e for e in entries}
        def chain(e):
            seen = set()
            while e['replaces'] in known and e['id'] not in seen:
                seen.add(e['id'])
                e = known[e['replaces']]
            return e['id']
        groups = {'skills': [], 'artifacts': [], 'workflows': [], 'lessons': []}
        fields = {'skills': ('id', 'title', 'version'), 'artifacts': ('id', 'title', 'summary', 'source'),
                  'workflows': ('id', 'title', 'steps', 'metrics', 'uses'), 'lessons': ('id', 'order', 'seat', 'reason')}
        roots, chosen = set(), []
        for e in sorted(entries, key=lambda e: (e['at'], e['_n']), reverse=True):
            group = e['kind'] + 's'
            if e['kind'] in ('skill', 'artifact') and e['status'] != 'accepted':
                continue
            if e['kind'] in ('workflow', 'lesson') and e['status'] != 'recorded':
                continue
            if group == 'skills':
                root = chain(e)
                if root in roots:
                    continue
                roots.add(root)
            if len(groups[group]) >= {'workflows': 10, 'lessons': 20}.get(group, len(entries) + 1):
                continue
            item = {k: e[k] for k in fields[group]}
            if group == 'skills':
                item['text'] = base64.b64decode(e['_data']).decode('utf-8')
            groups[group].append(item)
            chosen.append((group, item))
        out = dict(v='library/1', **groups)
        while len(encoded(out)) > LIMIT:
            group, item = chosen.pop()  # Oldest across all kinds, not just within one category.
            groups[group].remove(item)
        return out

    def efficiency(self):
        entries = sorted(self.read()['entries'], key=lambda e: (e['at'], e['_n']))
        return {'orders': [dict(run=e['source']['run'], order=e['source']['order'], title=e['title'],
                                ended=e['at'], uses=e['uses'], **e['metrics'])
                           for e in entries if e['kind'] == 'workflow']}

    def order(self, run, oid, family):
        doc = self.read()
        entries = doc['entries']
        related = [e for e in entries if e['source'] and e['source']['run'] == run and e['source']['order'] in family]
        uses = self.usage(doc, run, oid)['uses']
        return {'workflow': next((e['id'] for e in related if e['kind'] == 'workflow' and e['source']['order'] == oid), None),
                'uses': [{k: e[k] for k in ('id', 'kind', 'title', 'version')} for eid in uses for e in entries if e['id'] == eid],
                'proposed': [public(e) for e in related if e['status'] == 'proposed'],
                'saved': {e['source']['path']: e['id'] for e in related if e['_key'].startswith('["save",')},
                'saved_revisions': {e['source']['path'] + '@' + str(e.get('revision', 'legacy')): e['id'] for e in related if e['_key'].startswith('["save",')}}
