cat > 'cockpit/planning.py' <<'OC_EOF_17'
"""Human-triggered plans, kept outside the dispatcher ledger. Call while holding the server lock."""
import datetime
import json
import os
import re
import uuid

import history
import live

CRITERIA = 'Files are handed in under the write scope, are not empty and read as what they claim to be.'


def envelope(fields, oid, lead, message_id):
    """The same order.issue envelope used by the day form, sent through the ledger writer."""
    return {'v': 'dispatch/1', 'id': message_id, 'from': live.CEO, 'to': 'dispatcher', 'kind': 'order.issue',
            'body': {'id': oid, 'title': fields['title'], 'goal': fields['goal'], 'to': lead,
                     'writes': [fields['writes'] or oid + '/'], 'budget': fields['budget'],
                     'accept': {'judge': live.JUDGE, 'criteria': CRITERIA}}}


class Plans:
    def __init__(self, root, clock):
        self.path, self.clock = os.path.join(root, 'planned.jsonl'), clock

    def read(self):
        plans = {}
        try:
            with open(self.path, encoding='utf-8') as f:
                for line in f:
                    e = json.loads(line)
                    if e['kind'] == 'planned.added':
                        plans[e['id']] = dict(e, state='waiting', run=None, order=None)
                    elif e['kind'] == 'planned.cancelled':
                        plans[e['id']]['state'] = 'cancelled'
                    elif e['kind'] == 'planned.issued':
                        plans[e['id']].update(state='issued', run=e['run'], order=e['order'])
                    else:
                        raise ValueError('unknown planned event')
        except FileNotFoundError:
            pass
        today = history.day(self.clock())
        for p in plans.values():
            if p['state'] == 'waiting' and p['day'] <= today:
                p['state'] = 'due'
        return plans

    def append(self, kind, **fields):
        data = (json.dumps(dict(fields, kind=kind, t=self.clock()), ensure_ascii=False) + '\n').encode('utf-8')
        fd = os.open(self.path, os.O_WRONLY | os.O_APPEND | os.O_CREAT, 0o644)
        try:
            while data:
                data = data[os.write(fd, data):]
            os.fsync(fd)
        finally:
            os.close(fd)

    def add(self, fields):
        day = fields.get('day')
        if not isinstance(day, str) or not re.fullmatch(r'\d{4}-\d{2}-\d{2}', day):
            raise ValueError('day must be a real date written YYYY-MM-DD')
        datetime.date.fromisoformat(day)
        if day <= history.day(self.clock()):
            raise ValueError('plan a later day; issue today directly from its day page')
        values = {}
        for key, limit in (('title', 80), ('goal', 4000), ('writes', 120)):
            value = fields.get(key, '' if key == 'writes' else None)
            if not isinstance(value, str) or len(value) > limit or (key != 'writes' and not value.strip()):
                raise ValueError(key + ' must be text within its limit and title and goal cannot be empty')
            values[key] = value.strip()
        budget = fields.get('budget', 6)
        if type(budget) is not int or not 1 <= budget <= 99:
            raise ValueError('budget must be an integer from 1 to 99')
        scope = values['writes']
        if scope and (scope.startswith('/') or '\\' in scope or any(p in ('.', '..', '') for p in scope.rstrip('/').split('/'))):
            raise ValueError('writes must be a relative file key or folder scope')
        pid = 'plan-' + uuid.uuid4().hex
        self.append('planned.added', id=pid, day=day, budget=budget, **values)
        return {'id': pid, 'state': 'waiting'}

    def act(self, action, pid, server):
        p = self.read().get(pid)
        if p is None:
            return 404, {'cli': 'not-found'}
        if p['state'] == 'issued':
            return 409, {'cli': 'already-issued', 'run': p['run'], 'order': p['order']}
        if p['state'] == 'cancelled':
            return 409, {'cli': 'cancelled'}
        if action == 'issue' and p['state'] == 'waiting':
            return 409, {'cli': 'not-due'}
        # Repair a crash between the durable order row and planned.issued, even across a restart.
        runs, _ = server.history.runs()
        for run, r in runs.items():
            if any(e['kind'] == 'order.issued' and e['cause'] == pid for e in r['events']):
                self.append('planned.issued', id=pid, run=run, order=pid)
                return 409, {'cli': 'already-issued', 'run': run, 'order': pid}
        if action == 'cancel':
            self.append('planned.cancelled', id=pid)
            return 200, {'id': pid, 'state': 'cancelled'}
        result = server.writer.submit(envelope(p, pid, server.live.lead, pid), server.clock())
        if not result.get('ok'):
            return 409, result
        run = server.history.current
        self.append('planned.issued', id=pid, run=run, order=pid)
        return 200, {'id': pid, 'state': 'issued', 'run': run, 'order': pid}
OC_EOF_17
cat > 'cockpit/pro_data.py' <<'OC_EOF_18'
"""The data files of the /pro/ page, written for one run folder of this backend.

The page in pro/dist/ (see the README, "The pro page") loads events.js, audit.js, know.js, head.json, hq.json,
hq.head.json, diary.json and moments.json from its own folder, and opens files under raw/.  live.json (the backend
itself: run, state, launches) is answered by serve.py from the team document; see now().  The programs that write
them live in pro/data/ (they write Chinese text, so they stay under pro/ with the page):

    gen_live.py   events.js, moments.json, head.json      from ledger.jsonl and launches.jsonl
    gen_audit.py  audit.js, raw/                          copies of the ledger, launches, logs and named commits
    gen_know.py   know.js                                 what the agents could know (written once per start)
    diary.py      hq.json, diary.json, diary.md, hq.head.json

They run as separate processes (python -I) and only read the run folder; what they write goes into a private
temporary folder that this backend removes when it stops.  Page.refresh() rewrites the files when ledger.jsonl,
launches.jsonl or sent.jsonl changed size or time since the last pass, so a request costs one stat() per file
otherwise.  A program that fails is reported on stderr and the files it wrote before stay; the page then shows the
older data.

A copy without pro/ (the one-file script carries none) has no pro page: available() is False."""
import os
import re
import shutil
import subprocess
import sys
import tempfile

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
PRO = os.path.join(ROOT, 'pro')
DIST = os.path.join(PRO, 'dist')
DATA = os.path.join(PRO, 'data')
WATCH = ('ledger.jsonl', 'launches.jsonl', 'sent.jsonl')
FILES = ('events.js', 'audit.js', 'know.js', 'head.json', 'hq.json', 'hq.head.json', 'diary.json', 'diary.md', 'moments.json')
NAME = re.compile(r'^[A-Za-z0-9_][A-Za-z0-9._-]*(?:/[A-Za-z0-9_][A-Za-z0-9._-]*)*\Z')
TYPES = {'.html': 'text/html', '.js': 'text/javascript', '.mjs': 'text/javascript', '.css': 'text/css',
         '.json': 'application/json', '.md': 'text/plain', '.jsonl': 'text/plain', '.txt': 'text/plain', '.out': 'text/plain',
         '.svg': 'image/svg+xml', '.png': 'image/png', '.woff2': 'font/woff2'}
TIMEOUT = 120


def available():
    """True when this copy holds the built page and the programs that write its data."""
    return os.path.isfile(os.path.join(DIST, 'index.html')) and all(
        os.path.isfile(os.path.join(DATA, n)) for n in ('gen_live.py', 'gen_audit.py', 'gen_know.py', 'diary.py'))


def kind_of(name):
    return TYPES.get(os.path.splitext(name)[1].lower(), 'application/octet-stream')


def inside(root, name):
    """The path of `name` under `root` when it is a plain relative name of a file there that does not lead out
    (no .., no absolute path, no link that points elsewhere); None otherwise."""
    if not NAME.match(name) or '..' in name.split('/'):
        return None
    path = os.path.join(root, *name.split('/'))
    real, base = os.path.realpath(path), os.path.realpath(root)
    if not real.startswith(base + os.sep) or not os.path.isfile(real):
        return None
    return real


class Page:
    """The data files of one run folder, in a temporary folder of their own."""

    def __init__(self, run, python=None):
        self.run = run
        self.python = python or sys.executable
        self.out = tempfile.mkdtemp(prefix='oc-pro-')
        self.home = os.path.join(self.out, '.home')          # diary.py's optional inputs; none exist, so none are read
        self.seen = None
        self.know = False

    def stamp(self):
        out = []
        for n in WATCH:
            try:
                st = os.stat(os.path.join(self.run, n))
                out.append((st.st_size, st.st_mtime_ns))
            except OSError:
                out.append(None)
        return tuple(out)

    def tool(self, name, args):
        try:
            r = subprocess.run([self.python, '-I', '-B', os.path.join(DATA, name)] + args, cwd=DATA,
                               stdout=subprocess.DEVNULL, stderr=subprocess.PIPE, timeout=TIMEOUT)
        except (OSError, subprocess.TimeoutExpired) as e:
            return '%s: %s' % (name, type(e).__name__)
        if r.returncode:
            return '%s exit %d: %s' % (name, r.returncode, r.stderr.decode('utf-8', 'replace').strip()[-300:])
        return None

    def refresh(self):
        """Rewrite the data files when the run's files moved; [] when nothing failed (or nothing had to be done)."""
        now = self.stamp()
        if now == self.seen:
            return []
        steps = [('gen_live.py', [self.run, '-', self.out]), ('gen_audit.py', [self.run, self.out])]
        if not self.know:
            steps.append(('gen_know.py', [self.run, '-', self.out]))
        steps.append(('diary.py', ['--run', self.run, '--home', self.home, '--out', self.out]))   # last: hq.head.json
        bad = [b for b in (self.tool(n, a) for n, a in steps) if b]
        if not any(b.startswith('gen_know.py') for b in bad):
            self.know = True
        if bad:
            sys.stderr.write('cockpit: WARNING the pro page data was not fully rewritten: %s\n' % ' | '.join(bad))
        else:
            self.seen = now
        return bad

    def file(self, name):
        """(bytes, content type) of a data file or of a file under raw/; None when there is no such file."""
        if name in FILES:
            path = inside(self.out, name)
        elif name.startswith('raw/'):
            path = inside(os.path.join(self.out, 'raw'), name[4:])
        else:
            return None
        if path is None:
            return None
        with open(path, 'rb') as f:
            return f.read(), kind_of(name)

    def close(self):
        shutil.rmtree(self.out, ignore_errors=True)


def now(doc):
    """live.json for the page: the live backend in the shape the page reads (mode, run, backend, state, launches), from
    the team document (GET /team)."""
    return {'mode': 'live', 'run': doc.get('run'), 'backend': doc.get('backend'), 'state': doc.get('state') or 'running',
            'halted': doc.get('halted'), 'fatal': doc.get('fatal'), 'launched': doc.get('launched'), 'limit': doc.get('limit'),
            'judge': doc.get('judge'), 'team': doc.get('lead'), 'seat': doc.get('lead'), 'updated': doc.get('updated')}


def static(name):
    """(bytes, content type) of a file of the built page (index.html, replay.js, assets/...); None when there is none."""
    path = inside(DIST, name)
    if path is None:
        return None
    with open(path, 'rb') as f:
        return f.read(), kind_of(name)
OC_EOF_18
