{
 "$schema": "https://json-schema.org/draft/2020-12/schema",
 "$id": "dispatch/1/order",
 "title": "The body of order.issue: one piece of work, who does it, what it may touch, and who judges it",
 "type": "object",
 "required": [
  "id",
  "to",
  "accept"
 ],
 "additionalProperties": false,
 "properties": {
  "id": {
   "type": "string",
   "minLength": 1
  },
  "parent": {
   "type": [
    "string",
    "null"
   ]
  },
  "title": {
   "type": "string"
  },
  "goal": {
   "type": "string",
   "description": "the prompt, as typed; never changes after issue"
  },
  "to": {
   "type": "string",
   "pattern": "^(team|agent):.+",
   "description": "a team (any member may claim) or one agent"
  },
  "writes": {
   "type": "array",
   "items": {
    "type": "string",
    "minLength": 1
   },
   "description": "the only places the holder may write; \"a/b/\" is the subtree, \"a/b\" is that one thing"
  },
  "reads": {
   "type": "array",
   "items": {
    "type": "object",
    "required": [
     "key",
     "rev"
    ],
    "additionalProperties": false,
    "properties": {
     "key": {
      "type": "string",
      "minLength": 1
