cat > 'cockpit/serve.py' <<'OC_EOF_24'
#!/usr/bin/env python3
"""The cockpit: one process that keeps the ledger, starts the OpenCode agents and serves the page.

    python3 cockpit/serve.py RUNS [--team team.json] [--port 8800] [--max-launches 12] [--wall 600] [--judge FILE]

then open http://127.0.0.1:8800/ and issue an order.  Every start makes a new folder under RUNS (ledger, git
repository, sandboxes, logs); Ctrl-C stops it, and an agent that is still running then is ended without being collected.

It listens on 127.0.0.1 only.  What it answers:

    GET  /            the page (web/)
    GET  /state       the ledger, folded (see cli.py), and `sent`: the run's sender records
    GET  /team        seats and their models, every launch, the files handed in
    GET  /file?path=  the text of one handed-in file
    GET  /diary?run=&day=  one day of a run's diary (diary.py), worked out on request
    GET  /pro/        the pro page (pro/dist/, built from pro/src/), and its data files for the live run (pro_data.py);
                      it talks to this backend from the same origin.  Not in a copy without pro/.
    GET  /swarms?run= one run's coordination groups, members, tasks and skill catalog
    POST /swarms      create or edit a group in the current run; /swarms/note appends a note
    POST /message     one envelope for the dispatcher (the page sends order.issue)

Every envelope this backend hands to the dispatcher, and the answer, is one line of RUN/sent.jsonl (see Writer)."""
import argparse
import json
import os
import signal
import sys
import time
import uuid
from urllib.parse import parse_qs, urlsplit

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)

import cli                          # noqa: E402
import live as L                    # noqa: E402
import opencode_agent as A          # noqa: E402
import history as H                # noqa: E402
import planning as P               # noqa: E402
import library as B                # noqa: E402
import diary as D                  # noqa: E402
import pro_data as R               # noqa: E402
import workgroups                   # noqa: E402

WEB = os.path.join(os.path.dirname(HERE), 'web')
PAGE = {'index.html': 'text/html', 'app.css': 'text/css', 'look-home.css': 'text/css', 'look-calendar.css': 'text/css', 'look-order.css': 'text/css', 'look-team.css': 'text/css', 'look-records.css': 'text/css', 'colour.css': 'text/css', 'app.js': 'text/javascript', 'icons.js': 'text/javascript',
        'format.mjs': 'text/javascript', 'status.js': 'text/javascript', 'board.js': 'text/javascript',
        'swarm.js': 'text/javascript', 'swarm.css': 'text/css',
        'quality.html': 'text/html', 'quality.js': 'text/javascript', 'quality.css': 'text/css',
        'quality-data.json': 'application/json'}


class Writer(cli.Writer):
    """The ledger's writer, keeping the sender records: one JSON line in RUN/sent.jsonl for every envelope handed to the
    dispatcher (the lead loop and the agents through the adapter, the page, an issued plan all come through here).  A
    line holds the envelope's id, from and kind, `at` (the dispatcher's clock), the order it is about and the order it
    was sent `under`, then the answer: ok, the refusal's code and detail, the events it wrote.  ok is null when no
    answer came (the writer raised); detail then says why.  Appended under the server lock after the answer's ledger
    rows; never rewritten."""

    def submit(self, m, now, named=None):
        try:
            reply = cli.Writer.submit(self, m, now, named)
        except Exception as e:
            self.record(m, now, None, '%s: %s' % (type(e).__name__, e))
            raise
        self.record(m, now, reply)
        return reply

    def record(self, m, now, reply, error=None):
        m = m if isinstance(m, dict) else {}
        body = m.get('body') if isinstance(m.get('body'), dict) else {}
        lease = m.get('lease') if isinstance(m.get('lease'), dict) else None
        if m.get('kind') == 'order.issue':
            order, under = body.get('id'), lease.get('order') if lease else body.get('parent')
        else:
            order, under = body.get('order') if isinstance(body.get('order'), str) else (lease.get('order') if lease else None), None
        ok = None if reply is None else bool(reply.get('ok'))
        rec = {'id': m.get('id'), 'at': now, 'from': m.get('from'), 'kind': m.get('kind'),
               'order': order if isinstance(order, str) else None, 'under': under if isinstance(under, str) else None,
               'ok': ok, 'code': reply.get('code') if ok is False else None,
               'detail': error if reply is None else reply.get('detail') if ok is False else None,
               'events': list(reply.get('events') or []) if reply else []}
        data = (json.dumps(rec, ensure_ascii=False) + '\n').encode('utf-8')
        try:
            fd = os.open(os.path.join(self.run, L.SENT), os.O_WRONLY | os.O_APPEND | os.O_CREAT, 0o644)
            try:
                while data:
                    data = data[os.write(fd, data):]
                os.fsync(fd)
            finally:
                os.close(fd)
        except OSError as e:                            # the answer stands; only its record is missing, and that is said
            L.say('WARNING the sender record of %r could not be written: %s' % (rec['id'], e))


def sent_records(run):
    """The sender records of a run folder, oldest first, each with `n` (its line number); [] before the first."""
    try:
        with open(os.path.join(run, L.SENT), 'rb') as f:
            data = f.read()
    except OSError:                                     # none yet, or unreadable: the ledger's answer still stands
        return []
    out = []
    for n, line in enumerate(data.split(b'\n')[:-1], 1):
        try:
            rec = json.loads(line.decode('utf-8'))
        except ValueError:
            continue
        if isinstance(rec, dict):
            out.append(dict(rec, n=n))
    return out


class Handler(cli.Handler):
    server_version = 'opencode-cockpit/1'

    def _message_allowed(self, message):
        if not isinstance(message, dict) or message.get('kind') != 'order.issue':
            return True
        live = self.server.live
        if live is None:
            self._send(503, {'cli': 'starting'})
            return False
        body = message.get('body')
        if not isinstance(body, dict) or body.get('to') != live.lead:
            self._send(400, {'cli': 'not-through-lead',
                             'detail': 'Every order must go to the lead (%s), who dispatches the sub-orders.' % live.lead})
            return False
        return True

    def _state(self, since, limit, at):
        """GET /state as cli.py answers it, plus `sent`: every sender record of the live run, with `n`, its line number
        in RUN/sent.jsonl.  A line that is not a JSON object (or not yet ended) is left out; its number is not reused."""
        out = cli.Handler._state(self, since, limit, at)
        out['sent'] = sent_records(self.server.run)
        return out

    def _raw(self, code, data, kind):
        self.send_response(code)
        self.send_header('Content-Type', kind + '; charset=utf-8')
        self.send_header('Content-Length', str(len(data)))
        self.send_header('Cache-Control', 'no-store')
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.end_headers()
        self.wfile.write(data)

    def _pro(self, name):
        """GET /pro/<name>: a file of the built page, or a data file of the live run (rewritten first when the ledger,
        the launches or the sender records moved since the last pass)."""
        if name.startswith('ui/'):
            path = R.inside(os.path.join(R.PRO, 'ui'), name[3:])
            if path is not None and os.path.splitext(path)[1] in ('.css', '.js', '.mjs'):
                try:
                    with open(path, 'rb') as f:
                        return self._raw(200, f.read(), R.kind_of(name))
                except OSError:
                    pass
            return self._send(404, {'cli': 'not-found'})
        if not R.available():
            return self._send(404, {'cli': 'not-found', 'detail': 'this copy has no pro/ page'})
        name = name or 'index.html'
        got = R.static(name)
        if got is None:
            live = self.server.live
            if live is None:
                return self._send(503, {'cli': 'starting'})
            if name == 'live.json':                     # the page's "live backend" line: this backend, from the team document
                return self._send(200, R.now(json.loads(live.doc)))
            page = self.server.pro_page(live.run)
            if name in R.FILES or name.startswith('raw/'):
                page.refresh()
            try:
                got = page.file(name)
            except OSError:
                got = None
        if got is None:
            return self._send(404, {'cli': 'not-found'})
        return self._raw(200, got[0], got[1])

    def do_GET(self):
        u = urlsplit(self.path)
        if u.path == '/pro' or u.path.startswith('/pro/'):
            if not self._gate():
                return
            if u.path == '/pro':
                self.send_response(302)
                self.send_header('Location', '/pro/')
                self.send_header('Content-Length', '0')
                self.end_headers()
                return
            return self._pro(u.path[5:])
        name = 'index.html' if u.path == '/' else u.path[5:] if u.path.startswith('/web/') else None
        if name is None and u.path not in ('/team', '/poll', '/file', '/history', '/order', '/diary', '/swarms', '/library',
                                           '/library/item', '/library/context', '/library/efficiency', '/library/diff'):
            return cli.Handler.do_GET(self)             # /state, or not found
        if not self._gate():
            return
        if name is not None:
            if name not in PAGE:                        # only the files named above: a request never picks a path on disk
                return self._send(404, {'cli': 'not-found'})
            try:
                with open(os.path.join(WEB, name), 'rb') as f:
                    data = f.read()
                if name == 'index.html':
                    if R.available():
                        data = data.replace(b' id="pro-link" hidden', b' id="pro-link"', 1)
                    ui = os.path.join(R.PRO, 'ui')
                    features = [key for key in ('graph', 'board', 'motion', 'keys', 'hero')
                                if R.inside(ui, key + '.js') and R.inside(ui, key + '.css')]
                    head = []
                    if R.inside(ui, 'tokens.css'):
                        head.append('<link rel="stylesheet" href="/pro/ui/tokens.css">')
                    if features:
                        head.append('<meta name="cockpit-ui" content="%s">' % ' '.join(features))
                    data = data.replace(b'<!-- optional-local-styles -->', '\n'.join(head).encode('ascii'), 1)
                return self._raw(200, data, PAGE[name])
            except OSError:
                return self._send(404, {'cli': 'not-found'})
        live = self.server.live
        if live is None:
            return self._send(503, {'cli': 'starting'})
        if u.path == '/team':
            return self._raw(200, live.doc.encode('utf-8'), 'application/json')
        q = parse_qs(u.query, keep_blank_values=True)
        if u.path == '/poll':
            try:
                since = int((q.get('since') or ['0'])[0])
                if since < 0:
                    raise ValueError(since)
            except ValueError:
                return self._send(400, {'cli': 'bad-query', 'detail': 'since must be a non-negative integer'})
            # One writer gate covers the team, ledger, calendar and Library.
            # Refresh the launch clock here as well as on agent heartbeats.
            with live.gate:
                live.board()
                snapshot = cli.state(live.run, live.now(), since)
                # The UI applies a complete ledger tail together with its state.
                snapshot.update(log=live.ad.d.log[since:], next=len(live.ad.d.log), more=False)
                snapshot.pop('log_chain', None)  # This combined endpoint does not expose chain pagination.
                return self._send(200, {'team': json.loads(live.doc), 'state': snapshot,
                                       'history': self.server.history.summary(self.server.plans.read()),
                                       'library': self.server.library.listing(self.server.history)})
        try:
            if u.path == '/swarms':
                run = (q.get('run') or [self.server.history.current])[0]
                return self._send(200, self.server.workgroups.view(run))
            if u.path.startswith('/library') or u.path == '/order':
                self.server.library.sync(self.server.history)
            if u.path == '/library':
                return self._send(200, self.server.library.listing(self.server.history))
            if u.path == '/library/item':
                return self._send(200, self.server.library.item((q.get('id') or [''])[0], self.server.history))
            if u.path == '/library/diff':
                return self._send(200, self.server.library.compare((q.get('from') or [''])[0], (q.get('to') or [''])[0]))
            if u.path == '/library/context':
                return self._send(200, self.server.library.context())
            if u.path == '/library/efficiency':
                return self._send(200, self.server.library.efficiency())
            if u.path == '/history':
                return self._send(200, self.server.history.summary(self.server.plans.read()))
            run = (q.get('run') or [self.server.history.current])[0]
            if u.path == '/order':
                doc = self.server.history.order(run, (q.get('id') or [''])[0], include_answers=True)
                return self._send(200, doc)
            if u.path == '/diary':
                day = D.date_of((q.get('day') or [H.day(self.server.clock())])[0])
                if day is None:
                    return self._send(400, {'cli': 'bad-query', 'detail': 'day is a date written YYYY-MM-DD'})
                return self._send(200, D.day_of(D.build(self.server.history.folder(run)), day))
            path = (q.get('path') or [''])[0]
            got = self.server.history.read_file(run, path)
        except B.Error as e:
            return self._send(e.status, {'cli': e.code, 'detail': str(e)})
        except FileNotFoundError:
            return self._send(404, {'cli': 'not-found'})
        except (OSError, ValueError, KeyError, TypeError, RuntimeError, cli.LedgerError, D.Unreadable):
            return self._send(500, {'cli': 'unreadable-history', 'detail': 'The stored run or plans cannot be read.'})
        if got is None:
            return self._send(404, {'cli': 'not-found', 'detail': 'no file with that key was handed in'})
        self._send(200, got)

    def do_POST(self):
        path = urlsplit(self.path).path
        if path not in ('/plan', '/plan/issue', '/plan/cancel', '/swarms', '/swarms/note', '/library/save', '/library/review', '/library/undo', '/library/edit'):
            return cli.Handler.do_POST(self)
        if not self._gate():
            return
        n = self.headers.get('Content-Length')
        if n is None or not n.isdigit():
            return self._send(411, {'cli': 'length-required', 'detail': 'Send a Content-Length.'})
        if int(n) > cli.MAX_BODY:
            self.close_connection = True
            return self._send(413, {'cli': 'too-large', 'detail': 'The request body exceeds the size limit.'})
        try:
            body = json.loads(self.rfile.read(int(n)).decode('utf-8'))
            if not isinstance(body, dict):
                raise ValueError('send a JSON object')
        except ValueError:
            return self._send(400, {'cli': 'bad-json' if path.startswith(('/library/', '/swarms')) else 'bad-plan', 'detail': 'send a JSON object'})
        if path.startswith('/swarms'):
            try:
                return self._send(200, self.server.workgroups.change(path, body))
            except B.Error as e:
                return self._send(e.status, {'cli': e.code, 'detail': str(e)})
            except FileNotFoundError:
                return self._send(404, {'cli': 'not-found', 'detail': 'No run with this id.'})
            except (OSError, ValueError, KeyError, TypeError, cli.LedgerError):
                return self._send(500, {'cli': 'swarm-storage', 'detail': 'The swarm records could not be read or saved.'})
        if path.startswith('/library/'):
            try:
                if path.endswith('/save'):
                    entry = self.server.library.save(body, self.server.history, L.CEO)
                else:
                    action = {'/library/review': self.server.library.review, '/library/undo': self.server.library.undo,
                              '/library/edit': self.server.library.edit}[path]
                    entry = action(body, L.CEO)
                return self._send(200, {'entry': entry})
            except B.Error as e:
                return self._send(e.status, {'cli': e.code, 'detail': str(e)})
            except (OSError, ValueError, KeyError, TypeError, RuntimeError):
                return self._send(500, {'cli': 'library-storage', 'detail': 'The library could not be read or saved.'})
        if path == '/plan':
            try:
                return self._send(200, self.server.plans.add(body))
            except ValueError as e:
                return self._send(400, {'cli': 'bad-plan', 'detail': str(e)})
            except OSError:
                return self._send(500, {'cli': 'plan-storage', 'detail': 'The plan could not be saved.'})
        if not isinstance(body.get('id'), str):
            return self._send(400, {'cli': 'bad-plan', 'detail': 'id must be text'})
        try:
            code, result = self.server.plans.act(path.rsplit('/', 1)[1], body['id'], self.server)
            return self._send(code, result)
        except cli.Moved:
            return self._send(409, {'cli': 'moved'})
        except (OSError, ValueError, KeyError, TypeError):
            return self._send(500, {'cli': 'plan-storage', 'detail': 'Check history before trying this action again.'})


class Server(cli.Server):
    """The HTTP side takes the lock for every request, so it never reads the ledger in the middle of a step."""
    live = None
    writer_class = Writer

    def __init__(self, gate, run, port, clock, quiet=True):
        self.gate = gate
        cli.Server.__init__(self, run, port, (), clock=clock, quiet=quiet)
        self.RequestHandlerClass = Handler
        port = self.server_address[1]
        self.origins = {'http://%s:%d' % (cli.BIND, port), 'http://localhost:%d' % port}    # the page it serves, and nobody else

    def finish_request(self, request, client_address):
        with self.gate:
            cli.Server.finish_request(self, request, client_address)

    def pro_page(self, run):
        """The pro page's data for `run` (made on first use; called under the gate)."""
        page = getattr(self, '_pro', None)
        if page is None or page.run != run:
            if page is not None:
                page.close()
            page = self._pro = R.Page(run)
        return page

    def server_close(self):
        page = getattr(self, '_pro', None)
        if page is not None:
            page.close()
            self._pro = None
        cli.Server.server_close(self)


def start(runs, team, port=0, limit=A.MAX_TOTAL, wall=A.WALL, judge=None, exe=None, quiet=True, offset=0, skill_registry=None, swarm_board=None, **kw):
    """A started cockpit on a new run folder under `runs`."""
    B.outside_repo(runs)
    os.makedirs(runs, exist_ok=True)
    clock = lambda: time.time() + offset
    run = os.path.join(runs, time.strftime('%Y%m%d-%H%M%S', time.localtime(clock())) + '-' + uuid.uuid4().hex[:8])
    def server(gate, run, clock):
        srv = Server(gate, run, port, clock, quiet)
        srv.history = H.History(runs, os.path.basename(run), clock)
        srv.plans = P.Plans(runs, clock)
        try:
            srv.library = B.Library(runs, clock)
            srv.history.library = srv.library
            srv.workgroups = workgroups.Workgroups(srv.history, srv.library, skill_registry, swarm_board)
            srv.library.sync(srv.history)
        except BaseException:
            srv.server_close()
            raise
        return srv
    return L.Live(run, team, server, limit=limit, wall=wall, judge=judge, exe=exe, clock=clock, **kw).start()


def main(argv=None):
    a = argparse.ArgumentParser(prog='serve.py', description=__doc__.split('\n')[0])
    a.add_argument('runs', help='a folder for run folders; every start makes a new one inside it')
    a.add_argument('--team', default=os.path.join(os.path.dirname(HERE), 'team.example.json'), help='which seat runs which model (default: team.example.json)')
    a.add_argument('--port', type=int, default=8800)
    a.add_argument('--max-launches', type=int, default=A.MAX_TOTAL, help='how many agent processes this start may run in all (default %d)' % A.MAX_TOTAL)
    a.add_argument('--wall', type=int, default=A.WALL, help='seconds before one agent process is ended (default %d)' % A.WALL)
    a.add_argument('--judge', help='a judge file to use instead of the floor judge (cockpit/judge_floor.py)')
    a.add_argument('--opencode', help='the opencode executable (default: $OPENCODE_BIN, else `opencode` on PATH)')
    a.add_argument('--swarm-board', metavar='PATH', help='read public main-channel posts from this local swarm-board directory')
    a.add_argument('--skill-registry', metavar='PATH', help='read shared skill metadata from this registry.json')
    a.add_argument('--verbose', action='store_true', help='print every HTTP request')
    a.add_argument('--clock-offset', type=int, default=0, metavar='SECONDS', help='shift the local calendar and ledger clock for rehearsals (default 0)')
    o = a.parse_args(argv)
    if o.opencode and os.sep in o.opencode:             # a path: agents start in their own folders, so it must not be relative
        o.opencode = os.path.abspath(o.opencode)
    try:
        team = L.load_team(o.team)
    except (OSError, ValueError, KeyError, TypeError) as e:
        L.say('ERROR the team file %s cannot be used: %s' % (o.team, e))
        return 2
    try:
        live = start(os.path.abspath(o.runs), team, o.port, o.max_launches, o.wall, o.judge, o.opencode, quiet=not o.verbose, offset=o.clock_offset,
                     skill_registry=o.skill_registry, swarm_board=o.swarm_board)
    except (OSError, ValueError) as e:
        L.say('ERROR could not start: %s' % e)
        return 2
    L.say('run folder  %s' % live.run)
    for s in json.loads(live.doc)['seats']:
        L.say('seat        %-22s %s' % (s['actor'], s['model']))
    L.say('limits      %d launch(es) in all, %d per order, %d s each' % (o.max_launches, A.MAX_PER_ORDER, o.wall))
    L.say('open        %s/      (Ctrl-C stops)' % live.url)
    signal.signal(signal.SIGTERM, lambda *_: live.stop.set())
    try:
        while not live.stop.is_set():
            time.sleep(0.5)
    except KeyboardInterrupt:
        pass
    L.say('stopping')
    return 0 if live.close() and not live.fatal else 1


if __name__ == '__main__':
    sys.exit(main())
