"""Run-scoped coordination records. Only the current run's locked server writes its swarms."""
import json
import os
import re
import tempfile
import uuid

from blackboard import Blackboard
import library as B

REQUEST_ID = re.compile(r'[A-Za-z0-9][A-Za-z0-9_.-]{0,127}\Z')


def text_field(value, label, limit, required=False):
    if B.utf8(value) is None or len(value) > limit or (required and not value.strip()):
        raise B.Error('bad-swarm', 'Enter %s of %s to %d characters.' % (label, 1 if required else 0, limit))
    return value.strip()


def request_id(value):
    if not isinstance(value, str) or not REQUEST_ID.fullmatch(value):
        raise B.Error('bad-request-id', 'Use a short, unique request id of letters, digits, dots, dashes or underscores.')
    return value


def selections(value, choices, label):
    if not isinstance(value, list) or any(not isinstance(item, str) or item not in choices for item in value):
        raise B.Error('unknown-' + label, 'Choose %s entries from this run.' % label)
    return list(dict.fromkeys(value))


class Workgroups:
    def __init__(self, history, library, registry=None, board=None):
        self.history, self.library = history, library
        self.board = Blackboard(board) if board else None
        self.registry = os.path.abspath(os.path.expanduser(registry)) if registry else None

    def store(self, run):
        path = os.path.join(self.history.folder(run), 'swarms.json')
        if os.path.islink(path):
            raise B.Error('swarm-storage', 'The swarm record must be a regular file.', 500)
        try:
            with open(path, encoding='utf-8') as f:
                doc = json.load(f)
            if doc['version'] != 1 or not isinstance(doc['groups'], list) or not isinstance(doc['receipts'], dict):
                raise ValueError('unsupported swarm record')
        except FileNotFoundError:
            doc = {'version': 1, 'groups': [], 'receipts': {}}
        return path, doc

    @staticmethod
    def write(path, doc):
        # Each current run has a single writer. The same gate serializes all
        # server requests and the ledger lock prevents a second process owning that run.
        folder = os.path.dirname(path)
        fd, tmp = tempfile.mkstemp(prefix='.swarms-', dir=folder)
        try:
            with os.fdopen(fd, 'w', encoding='utf-8') as f:
                json.dump(doc, f, ensure_ascii=False)
                f.flush()
                os.fsync(f.fileno())
            os.replace(tmp, path)
            directory = os.open(folder, os.O_RDONLY)
            try:
                os.fsync(directory)
            finally:
                os.close(directory)
        finally:
            if os.path.exists(tmp):
                os.unlink(tmp)

    def catalog(self, entries):
        skills = [dict(id='library:' + e['id'], source_id=e['id'], source='library', title=e['title'],
                       version=e['version'], status=e['status'], domain='', category='')
                  for e in entries if e['kind'] == 'skill' and e['status'] == 'accepted']
        if not self.registry:
            return skills, 'unconfigured'
        try:
            with open(self.registry, encoding='utf-8') as f:
                rows = json.load(f)['skills']
            registry = []
            seen = set()
            if not isinstance(rows, list):
                raise ValueError('missing skills')
            for row in rows:
                sid, title = row['id'], row['title']
                if not isinstance(sid, str) or not sid.strip() or sid in seen or not isinstance(title, str):
                    raise ValueError('invalid skill')
                metadata = [row.get(key) for key in ('id', 'title', 'category', 'status', 'domain')]
                version = row.get('version')
                if type(version) is not int:
                    metadata.append(version)
                if any(v is not None and B.utf8(v) is None for v in metadata):
                    raise ValueError('invalid skill metadata')
                seen.add(sid)
                registry.append(dict(id='registry:' + sid, source_id=sid, source='registry', title=title,
                                     version=row.get('version'), status=row.get('status') or '',
                                     domain=row.get('domain') or '', category=row.get('category') or ''))
        except (ValueError, TypeError, KeyError, OSError):
            return skills, 'unavailable'
        return skills + registry, 'ready'

    def roster(self, run):
        record = self.history.read(run)
        board = self.history.board(run)
        seats = board.get('seats') or self.history.seats(run, board)
        members = [dict(actor=s['actor'], name=s.get('name') or s['actor'], model=s.get('model', ''),
                        role=s.get('role') or ('worker' if i else 'lead'), team=s.get('team') or s['actor'],
                        parent=s.get('parent') or (seats[0]['actor'] if i else 'human:ceo'))
                   for i, s in enumerate(seats)]
        tasks = [dict(id=o['id'], title=o['title'], state=o['state'], to=o['to'],
                      parent=o.get('parent'), skills=o.get('skills') or []) for o in record['orders'].values()]
        return members, tasks

    def view(self, run):
        members, tasks = self.roster(run)
        _, doc = self.store(run)
        library = self.library.read()
        skills, registry_status = self.catalog(library['entries'])
        # Plans are keyed by launch receipt. Attribute each skill to the exact run/order
        # that named it, retaining superseded versions in historical records.
        versions = {e['id']: dict(id='library:' + e['id'], title=e['title'], version=e['version'])
                    for e in library['entries'] if e['kind'] == 'skill'}
        uses = {}
        for plan in library['plans'].values():
            if plan['run'] == run:
                receipts = uses.setdefault(plan['order'], {})
                for eid in plan['uses']:
                    if eid in versions:
                        receipts[eid] = versions[eid]
        for task in tasks:
            task['skill_receipts'] = list(uses.get(task['id'], {}).values())
            task['used_skills'] = [r['id'] for r in task['skill_receipts']]
        return dict(run=run, writable=run == self.history.current, swarms=doc['groups'], members=members,
                    tasks=tasks, skills=skills, registry_status=registry_status,
                    board=self.board.read() if self.board and run == self.history.current else None)

    @staticmethod
    def group(doc, gid):
        group = next((g for g in doc['groups'] if g['id'] == gid), None)
        if group is None:
            raise B.Error('unknown-swarm', 'The selected swarm does not exist in this run.', 404)
        return group

    def change(self, action, body):
        run = body.get('run')
        if not isinstance(run, str) or not run:
            raise B.Error('bad-run', 'Choose a run before saving a swarm.')
        path, doc = self.store(run)
        if run != self.history.current:
            raise B.Error('historical-run', 'Past runs are read-only. Open the current run to make changes.', 409)
        if action == '/swarms/note':
            group = self.group(doc, body.get('swarm'))
            changed = self.add_note(group, body)
        else:
            group, changed = self.save_group(run, doc, body)
        if changed:
            self.write(path, doc)
        return {'swarm': group}

    def save_group(self, run, doc, body):
        members, tasks = self.roster(run)
        fields = dict(name=text_field(body.get('name'), 'a swarm name', 120, True),
                      goal=text_field(body.get('goal', ''), 'a goal', 2000),
                      members=selections(body.get('members', []), {s['actor'] for s in members}, 'member'),
                      tasks=selections(body.get('tasks', []), {t['id'] for t in tasks}, 'task'))
        if 'id' in body:
            group = self.group(doc, body['id'])
            if type(body.get('revision')) is not int or group['revision'] != body['revision']:
                raise B.Error('stale-revision', 'This swarm changed. Reload it before saving your edits.', 409)
            if all(group[k] == v for k, v in fields.items()):
                return group, False
            group.update(fields, revision=group['revision'] + 1)
        else:
            rid = request_id(body['request_id']) if 'request_id' in body else None
            if rid and rid in doc['receipts']:
                receipt = doc['receipts'][rid]
                if receipt['fields'] != fields:
                    raise B.Error('request-conflict', 'This request id was already used for another swarm.', 409)
                return self.group(doc, receipt['id']), False
            group = dict(fields, id=uuid.uuid4().hex, revision=1, notes=[])
            doc['groups'].append(group)
            if rid:
                doc['receipts'][rid] = dict(id=group['id'], fields=fields)
        return group, True

    def add_note(self, group, body):
        nid = request_id(body.get('id'))
        refs = {}
        for field in ('member', 'task', 'skill'):
            value = body.get(field)
            if value is not None and not isinstance(value, str):
                raise B.Error('bad-note', 'Choose a valid %s for this note.' % field)
            refs[field] = value or None
        fields = dict(refs, text=text_field(body.get('text'), 'a note', 4000, True))
        prev = next((n for n in group['notes'] if n['id'] == nid), None)
        if prev:
            if any(prev[k] != v for k, v in fields.items()):
                raise B.Error('request-conflict', 'This request id was already used for another note.', 409)
            return False
        for field in ('member', 'task'):
            if refs[field] and refs[field] not in group[field + 's']:
                raise B.Error('unknown-' + field, 'Choose a %s linked to this swarm.' % field)
        skill = {}
        if refs['skill']:
            skills, registry_status = self.catalog(self.library.read()['entries'])
            if refs['skill'].startswith('registry:') and registry_status == 'unavailable':
                raise B.Error('registry-unavailable', 'The configured skill registry could not be read.', 503)
            skill = next((s for s in skills if s['id'] == refs['skill']), None)
            if skill is None:
                raise B.Error('unknown-skill', 'Choose a skill from the current catalog.')
        group['notes'].append(dict(fields, id=nid, at=B.iso(self.history.clock()), skill_version=skill.get('version'),
                                   skill_title=skill.get('title')))
        group['revision'] += 1
        return True
