/* Table tests for the public mapping; no DOM or optional page is loaded. */
'use strict';
const assert = require('node:assert/strict');
const board = require('../web/board.js');
const question = {about: 'task', state: 'OPEN', blocking: true, to: 'human:owner'};
for (const [state, ask, expected] of [
  ['PENDING', null, 'pending'], ['LEASED', null, 'running'], ['JUDGING', null, 'waiting'],
  ['FAILED', null, 'failed'], ['DEAD', null, 'failed'], ['SUCCEEDED', null, 'done'], ['CANCELLED', null, 'done'],
  ['LEASED', question, 'waiting'], ['SUCCEEDED', question, 'waiting'],
  ['PENDING', {...question, blocking: false}, 'pending'], ['PENDING', {...question, state: 'ANSWERED'}, 'pending'],
  ['PENDING', {...question, to: 'agent:writer'}, 'pending'], ['PENDING', {...question, about: 'other'}, 'pending']
]) { assert.equal(board.column({id: 'task', state}, ask ? {ask} : {}), expected, state + ' ' + JSON.stringify(ask)); }
for (const [state, lease, now, expected] of [
  ['LEASED', {holder: 'agent:writer', expires: 101}, 100, 'agent:writer'],
  ['LEASED', {holder: 'agent:writer', expires: 100}, 100, null],
  ['LEASED', {holder: 'agent:writer', expires: 100}, 100.1, null],
  ['LEASED', {holder: 'agent:writer', expires: 101, expired: true}, 100, null],
  ['PENDING', {holder: 'agent:writer', expires: 101}, 100, null],
  ['SUCCEEDED', {holder: 'agent:writer', expires: 101}, 100, null], ['LEASED', null, 100, null]
]) { assert.equal(board.activeHolder({state}, lease, now), expected); }
const tasks = 'PENDING LEASED JUDGING FAILED DEAD SUCCEEDED CANCELLED'.split(' ').map((state, i) => ({
  id: 't' + i, title: 'Task ' + i, goal: i === 1 ? 'Find the needle' : 'Write a result', state, parent: i ? 't0' : null,
  number: i + 1, top: 't0', budget: i, issued_at: '2030-01-01T00:00:00+14:00', ended_at: null,
  changed_day: i < 3 ? '2030-01-02' : '2030-01-01', last_holder: i === 2 ? 'agent:writer' : null
}));
const history = {live_run: 'run', today: '2030-01-02', board: [{run: 'run', rows: 8, now: 100, tasks,
  leases: {t1: {holder: 'agent:writer', expires: 101}}, asks: {}, actors: [{actor: 'agent:writer', name: 'Writer'}]}]};
const input = {history};
const result = board.map(input);
assert.deepEqual(result.counts, {pending: 1, running: 1, waiting: 1, failed: 2, done: 2});
assert.equal(result.orders, 1); assert.equal(result.changed, 3); assert.equal(result.tasks[0].children, 6); assert.equal(result.tasks[0].done, 1);
assert.equal(result.tasks[1].holderName, 'Writer'); assert.equal(result.tasks[2].holder, null); assert.equal(result.tasks[2].lastHolderName, 'Writer');
assert.deepEqual(board.map(input, {seat: 'unclaimed'}).visible.map(t => t.id), ['t0', 't2']);
assert.deepEqual(board.map({...input, now: 101}, {seat: 'unclaimed'}).visible.map(t => t.id), ['t0', 't1', 't2']);
assert.deepEqual(board.map(input, {seat: 'agent:writer'}).visible.map(t => t.id), ['t1']);
assert.equal(board.map(input, {query: ' NEEDLE ', column: 'running'}).visible.length, 1);
assert.equal(board.map(input, {query: 'Task 4', column: 'done'}).visible.length, 0);
assert.equal(board.map(input, {column: 'failed'}).visible.length, 2);
assert.equal(result.tasks[0].issued, '2030-01-01T00:00:00+14:00', 'Backend date is retained, independent of browser zone');
// An older snapshot never replaces newer board metadata, and past runs have no current holder.
assert.equal(board.map({...input, snap: {rows: 7, state: {orders: {t1: {...tasks[1], state: 'PENDING'}}}}}).tasks[1].state, 'LEASED');
assert.equal(board.map({history: {...history, live_run: 'other'}}).tasks[1].holder, null);
const odd = {id: '__proto__', title: '<script>literal</script>', state: 'PENDING', parent: 'constructor'};
assert.equal(board.map({history: {live_run: 'run', board: [{run: 'run', tasks: [odd, {id: 'constructor', state: 'PENDING'}]}]}}).tasks[0].top, 'constructor');
console.log('Public board mapping passed: states, human asks, active leases, Unclaimed, counts, dates, children and filters.');
