  const {assert, q, all, byId, document, history, stateOrders, dispatcher, log, team, boardNetwork: network, timers, flush, navigate, refresh, statusTick} = env;
  Object.keys(stateOrders).forEach(id => delete stateOrders[id]); log.length = 0;
  dispatcher.fail = false; dispatcher.asks = {}; dispatcher.leases = {}; dispatcher.now = 1900000100;
  const tasks = Array.from({length: 80}, (_, i) => ({id: 'board-' + i, title: 'Board task ' + i, goal: i === 2 ? 'A searchable needle' : 'A recorded goal',
    state: i < 74 ? 'PENDING' : ['LEASED', 'JUDGING', 'FAILED', 'DEAD', 'SUCCEEDED', 'CANCELLED'][i - 74],
    parent: i ? 'board-0' : null, top: 'board-0', top_title: 'Board task 0', number: i + 1, budget: 6,
    issued_at: '2030-04-10T23:05:00+14:00', ended_at: i >= 76 ? '2030-04-10T23:06:00+14:00' : null,
    changed_day: i < 4 ? history.today : '2030-04-09', last_holder: i === 75 ? 'agent:writer' : null}));
  tasks.forEach((task, i) => { stateOrders[task.id] = {...task}; log.push({seq: i + 1, t: 1900000000 + i, kind: 'order.issued', body: task, by: 'human:ceo'}); });
  history.board = [{run: 'live-run', rows: log.length, now: dispatcher.now, tasks, actors: team.seats, leases: {}, asks: {}}];
  dispatcher.leases['board-74'] = {holder: 'agent:writer', expires: dispatcher.now + 500};
  dispatcher.asks.wait = {about: 'board-1', to: 'human:ceo', state: 'OPEN', blocking: true};
  await refresh(); await statusTick(); await navigate('#/board', 'board');
  const lane = name => q('[data-column="' + name + '"]');
  const card = id => q('[data-task-key][data-order="' + id + '"]');
  const action = (node, name) => node.querySelector('[data-board-action="' + name + '"]');
  assert.deepEqual(all('[data-column]').map(node => node.getAttribute('aria-label')), ['Not started', 'In progress', 'Waiting on you', 'Failed', 'Done']);
  assert.deepEqual(all('[data-column]').map(node => Number(node.getAttribute('data-count'))), [73, 1, 2, 2, 2]);
  assert.equal(q('[data-board-total]').textContent, '80 of 80 tasks · 1 orders');
  assert.equal(q('[data-board-changed]').textContent, '4 changed today');
  assert.equal(lane('pending').querySelectorAll('[data-task-key]').length, 72);
  assert.ok(card('board-0').textContent.includes('T-1')); assert.ok(card('board-0').textContent.includes('Budget 6'));
  assert.equal(card('board-0').querySelector('time').textContent, '2030-04-10 23:05', 'Backend wall time is never converted through the browser timezone');
  assert.equal(card('board-0').querySelector('[role="progressbar"]').getAttribute('aria-valuemax'), '79');
  assert.equal(card('board-0').querySelector('[role="progressbar"]').getAttribute('aria-valuenow'), '1');
  assert.ok(card('board-74').textContent.includes('Writer')); assert.equal(card('board-75').querySelector('.task-holder').getAttribute('title'), 'Last holder: Writer');
  assert.equal(card('board-75').querySelector('.task-avatar'), null);
  assert.equal(card('board-79').querySelector('.task-pill').getAttribute('data-state'), 'CANCELLED');
  assert.ok(action(card('board-74'), 'tree').getAttribute('href').endsWith('/board-0/tree'));
  const search = q('[data-board-search]'), column = q('[data-board-filter="column"]'), seat = q('[data-board-filter="seat"]');
  function searchFor(value) { search.value = value; search.dispatch('input'); }
  function choose(control, value) { control.value = value; control.dispatch('change'); }
  searchFor('needle'); assert.equal(all('[data-task-key]').length, 1); assert.equal(card('board-2').getAttribute('data-order'), 'board-2');
  assert.equal(q('[data-board-count="pending"]').textContent, 'Not started 1'); assert.equal(q('[data-board-changed]').textContent, '1 changed today');
  assert.equal(lane('done').querySelector('.task-empty').textContent, 'No orders here'); searchFor('');
  choose(seat, 'agent:writer'); assert.equal(all('[data-task-key]').length, 1); assert.ok(card('board-74'));
  choose(seat, 'unclaimed'); assert.equal(q('[data-board-total]').textContent, '75 of 80 tasks · 1 orders'); assert.equal(card('board-74'), null); assert.equal(card('board-79'), null);
  choose(seat, 'all'); choose(column, 'failed'); assert.equal(all('[data-column]').filter(node => !node.hidden).length, 1); assert.equal(all('[data-task-key]').length, 2);
  choose(column, 'all'); q('[data-board-action="list"]').click(); assert.equal(byId('board-columns').getAttribute('data-mode'), 'list'); q('[data-board-action="board"]').click();
  const scroll = lane('pending').querySelector('[data-list-window]'); scroll.scrollTop = 242;
