  stateOrders['board-2'].state = 'SUCCEEDED'; await refresh();
  assert.equal(card('board-2'), original, 'Moving a card retains its node'); assert.equal(document.activeElement, action(original, 'order'), 'The same action retains focus after moving lanes');
