  const detailText = q('[data-board-detail]').textContent; first.resolve(); await flush(); assert.equal(q('[data-board-detail]').textContent, detailText);
  assert.equal(byId('task-drawer-title').textContent, 'Board task 3'); assert.ok(detailText.includes('<script>Literal goal</script>'));
  for (const title of ['Goal', 'Direct steps', 'Participants', 'Library context', 'Handed-in result files']) { assert.ok(detailText.includes(title)); }
  assert.equal(q('[data-board-detail]').querySelector('script'), null);
  const requestsBeforeHandIn = network.pending.length;
  log.push({seq: log.length + 1, t: 1900000101, kind: 'artifact.rev', order: 'board-3', key: 'work/result.txt', by: 'agent:writer'});
  history.board[0].rows = log.length; await refresh();
  assert.equal(network.pending.length, requestsBeforeHandIn + 1, 'An open drawer refreshes on a ledger change even when card fields are unchanged');
  network.pending.at(-1).resolve(); await flush(); network.holdDetail = false;
  q('[data-board-action="next"]').click(); await flush(); assert.equal(byId('task-drawer-title').textContent, 'Board task 4');
  q('[data-board-action="previous"]').click(); await flush(); assert.equal(byId('task-drawer-title').textContent, 'Board task 3');
  document.dispatch('keydown', {key: 'Escape'}); assert.equal(q('[data-board-drawer]').hidden, true); assert.equal(document.activeElement, card('board-3'));
  network.failDetail = true; original.click(); await flush(); assert.ok(q('[data-board-detail]').textContent.includes('Could not load'));
  network.failDetail = false; q('[data-board-action="retry"]').click(); await flush(); assert.ok(q('[data-board-detail]').textContent.includes('Direct steps'));
  document.dispatch('keydown', {key: 'Escape'});
  env.setOffline(true); await refresh(); assert.equal(q('[data-board-offline]').hidden, false); assert.equal(card('board-2'), original);
  env.setOffline(false); await refresh(); await statusTick(); await refresh(); assert.equal(q('[data-board-offline]').hidden, true);
  // A poll that times out arrives after a newer snapshot: both summary and cards must stay new.
  env.setHoldPoll(true); await refresh(); const delayed = network.heldPoll.at(-1); timers.findLast(t => t.delay === 1500).f(); await flush();
  env.setHoldPoll(false); stateOrders['board-2'].title = 'A newer task title'; history.board[0].tasks[2].changed_day = '2030-04-09'; await refresh();
  const newest = byId('board-columns').textContent; delayed(); await flush(); assert.equal(byId('board-columns').textContent, newest); assert.ok(card('board-2').textContent.includes('A newer task title'));
  action(card('board-2'), 'status').click(); await statusTick(); await navigate('#/status', 'status');
  assert.equal(document.activeElement.getAttribute('data-status-card'), 'board-2');
  await navigate('#/board', 'board');
  history.board.push({run: 'past-run', rows: 1, tasks: [{id: 'archived', title: 'Archived order', state: 'CANCELLED', number: 1}], actors: []}); await refresh();
  action(card('archived'), 'status').click(); await navigate('#/status', 'status'); assert.equal(document.activeElement.getAttribute('data-past-status'), 'archived');
  console.log('Public board page checks passed: lanes, filters, children, dates, focus, drawer, abort/race/retry, pagination, offline and late summaries.');
};
