"""Frozen pre-index order assembly from 10041aa for response parity tests."""
from history import day, lead_seat, live, order_problem, progress, row_order


def legacy_order(self, run, oid):
    r = self.read(run)
    orders = r['orders']
    if oid not in orders:
        raise FileNotFoundError('unknown order')
    family = {oid}
    while True:
        more = {k for k, o in orders.items() if o.get('parent') in family} - family
        if not more:
            break
        family.update(more)
    def node(k):
        o = orders[k]
        branch = {k}
        while True:
            children = {n for n in family if orders[n].get('parent') in branch} - branch
            if not children:
                break
            branch.update(children)
        return dict(o, by=r['issued'][k]['by'], judge=o.get('accept', {}).get('judge', ''), day=day(r['issued'][k]['t']),
                    top=r['tops'][k], writes=', '.join(o.get('writes', [])), progress=progress(orders, k),
                    problem=order_problem(orders, r['events'], launches, seats, board, branch))
    board = self.board(run)
    seats = self.seats(run, board)
    outcomes, _ = live.outcome_counts({k: orders[k] for k in family}, [e for e in r['events'] if row_order(e) in family], seats)
    seats = [dict(s, outcomes=outcomes[s['actor']]) for s in seats]
    launches = self.launches(run)
    events = r['events']
    updated = self.clock() if run == self.current else max(
        [e['t'] for e in events] + [board.get('updated', 0)] + [l['ended'] for l in launches if l['ended'] is not None])
    terminal = [e['t'] for e in events if e.get('order') == oid and
                (e['kind'] in ('order.succeeded', 'order.dead', 'order.cancelled') or
                 e['kind'] == 'order.failed' and not e.get('retry'))]
    started, ended = r['issued'][oid]['t'], terminal[-1] if terminal else None
    stopped = min([h['at'] for h in board.get('held', []) if h.get('at') is not None], default=board.get('updated', updated)) if board.get('halted') or board.get('fatal') else None
    return {'run': run, 'live': run == self.current, 'lead': lead_seat(seats), 'order': node(oid),
            'run_started': events[0]['t'] if events else None, 'updated': updated,
            'timing': {'started': started, 'ended': ended, **({'stopped': stopped} if stopped is not None else {}), 'seconds': max(0, (ended if ended is not None else stopped if stopped is not None else updated) - started)},
            'children': [node(k) for k, o in orders.items() if o.get('parent') == oid],
            'nodes': [node(k) for k in orders if k in family],
            'seats': seats, 'launches': [l for l in launches if l['order'] in family],
            'files': self.files(run, family), 'ledger': [e for e in r['events'] if row_order(e) in family],
            'library': self.library.order(run, oid, family) if self.library else
                       {'workflow': None, 'uses': [], 'proposed': [], 'saved': {}}}
