/* Evaluate in the locally served page at 1280 × 900. No packages or writes.
 * The DOM stand-in cannot catch flex sizing regressions; these assertions use
 * the browser's rendered rectangles on every route, including partial fills.
 */
(async function () {
  'use strict';
  const measureBox = node => (node.getBoundingClientRect());
