function assertSeatWashes(view, doc, minimum) {
  doc.seats.forEach((seat, index) => {
    if (!seat.model || seat.model === 'No model' || /^(human:|program:)/.test(seat.actor)) { return; }
    const slot = index % 6 + 1, id = seat.id || seat.actor;
    assert.ok(view.querySelectorAll('[data-seat-wash="' + id + '"]').length >= minimum, seat.name + ' wash coverage');
    for (const selector of ['[data-seat="' + id + '"]', '[data-home-seat="' + id + '"]', '[data-org-node="' + seat.actor + '"]', '[data-handoff-seat="' + seat.actor + '"]', '[data-usage-row="' + seat.model + '"]']) {
      const container = view.querySelector(selector);
      if (container) { assertSeatWash(container, seat, slot); }
    }
    const timeline = view.querySelector('[data-timeline-row="' + seat.actor + '"]');
    if (timeline) { assertSeatWash(timeline, seat, slot, 28); }
    view.querySelectorAll('[data-launch-card]').forEach(card => {
      const launch = doc.launches.find(l => String(l.n || l.launch) === card.getAttribute('data-launch-card'));
      if (launch.agent === seat.actor) { assertSeatWash(card, seat, slot); }
    });
  });
  view.querySelectorAll('[data-bubble-group]').forEach(group => {
    const sender = group.getAttribute('data-sender'), seat = doc.seats.find(s => s.actor === sender || s.team === sender);
    // Recipient chips may name other seats; inspect only the group's sender icon.
    const frame = group.children[0];
    if (seat) { assertSeatWash(frame, seat, doc.seats.indexOf(seat) % 6 + 1, 28); }
    else { assert.equal(frame.querySelector('[data-seat-wash]'), null); }
  });
  for (const actor of [doc.ceo, doc.judge]) {
    const node = view.querySelector('[data-org-node="' + actor + '"]');
    if (node) { assert.equal(node.querySelector('[data-seat-wash]'), null); }
  }
  // Walk every icon viewport, including scaled SVG foreignObjects and table chips.
  view.querySelectorAll('[data-model-icon]').forEach(icon => {
    let p = icon.parentNode, frame = null, usage = false;
    while (p && p !== view) { if (p.getAttribute('class') === 'seat-icon') { frame = p; } if (p.getAttribute('data-usage-row') !== null) { usage = true; } p = p.parentNode; }
    // A usage row's extra logo identifies the aggregate model, not a seat.
    if (!usage) { assert.ok(frame, 'A seat model icon cannot bypass its wash viewport'); }
  });
  const icons = view.querySelectorAll('.seat-icon');
  assert.ok(icons.length);
  icons.forEach(frame => {
    const wash = frame.querySelector('[data-seat-wash]');
    assert.ok(wash && frame.querySelector('[data-model-icon]'), 'Each seat model has its own wash');
    const r = measureBox(wash);
    assert.ok(r.width >= 28 && r.height >= 28, 'Seat wash at least 28 px on screen: ' + wash.getAttribute('data-seat-wash') + ' ' + r.width + ' × ' + r.height);
  });
  view.querySelectorAll('[data-seat-wash]').forEach(wash => {
    const seat = doc.seats.find(s => (s.id || s.actor) === wash.getAttribute('data-seat-wash'));
    assert.ok(seat && seat.model && seat.model !== 'No model');
    assert.ok(!/^(human:|program:)/.test(seat.actor));
  });
}

// Resolve the actual focus CSS against rendered DOM. This deliberately audits
