}
const paintRules = [...css.replace(/\/\*[\s\S]*?\*\//g, '').matchAll(/([^{}]+)\{([^{}]*)\}/g)]
  .filter(m => /\[data-dim\]|diagram-edge|data-(?:org-edge|handoff-edge|flow-edge|edge-end)|flow-arrow|flow-dot/.test(m[1]))
