    const tag = part.match(/^[a-z]+/i);
    if (tag && tag[0] !== node.tagName) { return false; }
    const classes = [...part.matchAll(/\.([\w-]+)/g)];
    if (!classes.every(m => (node.getAttribute('class') || '').split(/\s+/).includes(m[1]))) { return false; }
    return [...part.matchAll(/\[([\w-]+)(?:="([^"]*)")?\]/g)].every(m => node.getAttribute(m[1]) !== null && (m[2] === undefined || node.getAttribute(m[1]) === m[2]));
  }
  if (!simple(e, parts.pop())) { return false; }
  for (let parent = e.parentNode; parts.length; parent = parent?.parentNode) {
