  const style = paintStyle(ring, paintRules);
  assert.equal(style.fill, 'var(--paper)'); assert.equal(style.stroke, 'var(--edge)'); assert.equal(style['stroke-width'], '2');
  assert.equal(style['pointer-events'], 'none', 'Rings leave connector tooltips reachable');
