function assertDimConnectors() {
  // Current selection keeps the connectors visible. Also exercise direct and
  // ancestor dimming so a dim attribute can never recolour a line or its ends.
  for (const name of ['org', 'handoff', 'flow']) {
    const group = new Element('g'), edge = group.appendChild(new Element('path'));
    edge.setAttribute('data-' + name + '-edge', '');
    if (name !== 'flow') { edge.setAttribute('class', 'diagram-edge'); }
    const rings = name === 'flow' ? [] : ['start', 'end'].map(end => {
      const ring = group.appendChild(new Element('circle')); ring.setAttribute('data-edge-end', end); return ring;
    });
