function pathPoints(edge) {
  const tokens = edge.getAttribute('d').match(/[MLQ]|-?\d+(?:\.\d+)?(?:e[+-]?\d+)?/g);
  const points = []; let last;
  for (let i = 0; i < tokens.length;) {
    const command = tokens[i++];
    if (command === 'M' || command === 'L') { last = [Number(tokens[i++]), Number(tokens[i++])]; points.push(last); }
    else {
