  assert.equal(rings.length, edges.length * 2, 'Each edge owns two rings, even on shared trunks');
  assert.equal(rings.filter(r => r.getAttribute('data-edge-end') === 'start').length, edges.length);
  assert.equal(rings.filter(r => r.getAttribute('data-edge-end') === 'end').length, edges.length);
  edges.forEach((edge, i) => {
    const points = pathPoints(edge), parent = edge.parentNode;
    assert.equal(parent.tagName, 'svg'); assertConnectorPaint(edge);
    assert.ok(edge.querySelector('title').textContent.includes('→'));
    rings.slice(i * 2, i * 2 + 2).forEach((ring, end) => {
      assert.equal(ring.tagName, 'circle'); assert.equal(ring.parentNode, parent);
      assert.equal(ring.getAttribute('data-edge-end'), end ? 'end' : 'start');
      for (const key of ['data-from', 'data-to', 'data-dim']) { assert.equal(ring.getAttribute(key), edge.getAttribute(key)); }
      const point = end ? points.at(-1) : points[0];
      near(Number(ring.getAttribute('cx')), point[0], 'Ring x meets the path');
      near(Number(ring.getAttribute('cy')), point[1], 'Ring y meets the path');
      assert.equal(ring.getAttribute('r'), '3.5'); assert.equal(ring.getAttribute('aria-hidden'), 'true');
      assert.equal(ring.textContent, ''); assertRingPaint(ring);
