function assertOrg(view, doc) {
  const tree = view.querySelector('[data-org]'), nodes = tree.querySelectorAll('[data-org-node]'), edges = tree.querySelectorAll('path[data-org-edge]');
  assertEdgeEnds(tree, 'org');
  assert.equal(nodes.length, doc.seats.length + 2); assert.equal(edges.length, nodes.length - 1);
  const boxes = Object.fromEntries(nodes.map(n => {
    const [x, y] = n.getAttribute('transform').match(/-?\d+(?:\.\d+)?/g).map(Number), rect = n.querySelector('rect');
    assert.ok(n.querySelector('title')); assert.ok(n.querySelector('svg')); assert.ok(n.textContent.includes('launch'));
    return [n.getAttribute('data-org-node'), {x, y, w: Number(rect.getAttribute('width')), h: Number(rect.getAttribute('height'))}];
  }));
  assert.deepEqual(edges.map(e => e.getAttribute('data-to')).sort(), Object.keys(boxes).filter(id => id !== doc.ceo).sort());
  for (const edge of edges) {
    const from = boxes[edge.getAttribute('data-from')], to = boxes[edge.getAttribute('data-to')], points = pathPoints(edge);
    assert.ok(edge.querySelector('title').textContent.includes('→'));
    near(points[0][0], from.x + from.w / 2, 'Parent middle'); near(points[0][1], from.y + from.h, 'Parent bottom');
    near(points.at(-1)[0], to.x + to.w / 2, 'Child middle'); near(points.at(-1)[1], to.y, 'Child top');
    assert.equal(edge.getAttribute('data-judge') !== null, edge.getAttribute('data-to') === doc.judge);
    // Sample every straight and rounded segment, including routes to lower rows.
    for (let i = 1; i < points.length; i++) {
      for (let step = 0; step <= 30; step++) {
