function assertHandoffs(view, doc) {
  const diagram = view.querySelector('[data-handoff]'), cards = diagram.querySelectorAll('[data-handoff-card]'), edges = diagram.querySelectorAll('[data-handoff-edge]'), seats = diagram.querySelectorAll('[data-handoff-seat]');
