    assert.equal(card.querySelector('a[data-order-link]').textContent, record.title);
    assert.equal(card.querySelector('a').getAttribute('data-order'), record.order);
    assert.ok(card.querySelector('[data-state="' + record.state + '"]'));
    assert.deepEqual(card.querySelectorAll('code').map(c => c.textContent), record.files);
    assert.equal(card.querySelectorAll('[data-model-icon]').length, 2);
    const [left, width] = [...source.getAttribute('style').matchAll(/([\d.]+)%/g)].map(m => Number(m[1]));
    assert.match(source.getAttribute('style'), /% \+ 6px\);width:calc\([\d.]+% - 12px\)/);
