    assert.equal(points.length, 4, 'One trunk, horizontal bus and drop per card');
    assert.equal(points[1][0], points[0][0]); assert.equal(points[2][1], bus); assert.equal(points[3][0], points[2][0]);
    peers.forEach(e => assert.deepEqual(pathPoints(e).slice(0, 2), points.slice(0, 2), 'Shared trunks coincide exactly'));
    for (const other of edges.filter(e => e.getAttribute('data-from') !== resolve(record.from))) {
