    near(points.at(-1)[0], (i+0.5)*960/cards.length, 'Handoff center'); near(points.at(-1)[1], handoffTop, 'Handoff top');
    assert.ok(points.every(p => p[1] >= 80 && p[1] <= handoffTop));
