}
function assertTimeline(view, doc) {
  const timeline = view.querySelector('[data-timeline]'), rows = timeline.querySelectorAll('[data-timeline-row]'), bars = timeline.querySelectorAll('[data-timeline-bar]');
  assert.equal(rows.length, new Set(doc.launches.map(l => l.agent)).size);
  assert.equal(bars.length, doc.launches.length);
  assert.ok(timeline.querySelectorAll('[data-timeline-tick]').length >= 3);
  const base = doc.order ? Math.min(...doc.launches.map(l => l.started)) : doc.run_started;
  assert.ok(timeline.textContent.includes(doc.order ? 'this order’s first launch' : 'the start of the run'));
  const duration = Math.max(0, ...doc.launches.map(l => (l.ended ?? doc.updated)-base));
  const ticks = timeline.querySelectorAll('[data-timeline-tick]');
  assert.equal(ticks[0].getAttribute('data-timeline-tick'), '0.0');
  assert.equal(ticks.at(-1).getAttribute('data-timeline-tick'), duration.toFixed(1), 'Axis ends at the last launch end');
  for (const row of rows) {
    assert.ok(row.querySelector('svg'));
    const mine = doc.launches.filter(l => l.agent === row.getAttribute('data-timeline-row')).sort((a,b) => a.started - b.started), rects = row.querySelectorAll('[data-timeline-bar]');
    const track = row.querySelector('[data-timeline-track]'), tx = Number(track.getAttribute('x')), tw = Number(track.getAttribute('width'));
    const previous = [];
    rects.forEach((bar, i) => {
      const l = mine[i], end = l.ended === null ? doc.updated : l.ended;
      assert.equal(bar.getAttribute('height'), '14'); assert.equal(bar.getAttribute('rx'), '4');
      assert.equal(Number(bar.getAttribute('y')), i * 24 + 5);
      assert.equal(bar.getAttribute('data-order'), l.order);
      assert.equal(bar.getAttribute('data-start'), (l.started-base).toFixed(1));
      assert.equal(bar.getAttribute('data-end'), (end-base).toFixed(1));
      assert.match(bar.querySelector('title').textContent, new RegExp(', ' + (end-l.started).toFixed(1).replace('.', '\\.') + ' s$'));
      assert.equal(bar.getAttribute('data-running') !== null, l.state === 'running');
      const x = Number(bar.getAttribute('x')), w = Number(bar.getAttribute('width')), y = Number(bar.getAttribute('y'));
      assert.ok(w >= 6 && x >= tx && x+w <= tx+tw + 0.01, 'Every bar stays in its track');
      previous.filter(p => p.y === y).forEach(p => assert.ok(p.x+p.w <= x, 'Short/overlapping launches get separate lanes'));
      previous.push({x,w,y});
    });
  }
  const plot = timeline.querySelector('.launch-timeline'); assert.equal(plot.getAttribute('style'), 'height:' + plot.getAttribute('height') + 'px');
  assert.equal(timeline.querySelectorAll('[data-timeline-duration]').length, bars.length, 'Every bar keeps its duration even near the axis end');
  timeline.querySelectorAll('[data-timeline-duration]').forEach(label => { assert.ok(label.textContent.endsWith(' s')); assert.ok(Number(label.getAttribute('x')) + label.textContent.length * 8 <= 936); });
  if (doc.order) { assertLaunchCards(view, doc); }
}
function assertLaunchCards(view, doc) {
  const timeline = view.querySelector('[data-timeline]'), bars = timeline.querySelectorAll('[data-timeline-bar]');
  const cards = view.querySelectorAll('[data-launch-card]');
  assert.equal(cards.length, bars.length, 'Every drawn launch has one card');
  assert.deepEqual(cards.map(c => c.getAttribute('data-launch-card')), bars.map(b => b.getAttribute('data-timeline-bar')), 'Card order follows seat rows, then launch start time');
  if (cards.length) {
    assert.equal(timeline.parentNode.children[1], cards[0].parentNode, 'Cards are directly below the timeline');
    assert.equal(timeline.parentNode.parentNode.querySelector('h3').textContent, 'How the team ran it');
  }
  cards.forEach((card, i) => {
    const l = doc.launches.find(l => String(l.n || l.launch) === card.getAttribute('data-launch-card'));
    const seat = doc.seats.find(s => s.actor === l.agent), stats = card.querySelectorAll('[data-launch-stat]');
    assert.ok(card.querySelector('svg')); assert.ok(card.textContent.includes(seat?.name || 'System'));
    assert.equal(card.querySelector('[class="launch-model"]').textContent, l.model || seat?.model || 'No model');
    const link = card.querySelector('a[data-order-link]');
    assert.equal(link.getAttribute('data-order'), bars[i].getAttribute('data-order')); assert.equal(link.getAttribute('data-run'), doc.run);
    assert.ok(card.querySelector('[class="badge"][data-state="' + (l.state || 'ended') + '"]'));
    assert.ok(stats.length >= 3); stats.forEach(s => assert.ok(Number.isFinite(Number(s.querySelector('strong').textContent.replace('$', '')))));
    const expect = (key, text) => assert.equal(card.querySelector('[data-launch-stat="' + key + '"]').textContent, text);
    expect('seconds', (l.secs ?? ((l.ended ?? doc.updated) - l.started)).toFixed(1) + ' seconds');
    expect('tools', Object.values(l.seen?.tools || {}).reduce((sum, n) => sum + n, 0) + ' recorded tool calls');
    expect('files', new Set(l.taken || []).size + ' files handed in');
    assert.equal(!!card.querySelector('[data-launch-stat="sent-back"]'), !!l.verdict && !l.verdict.pass);
    if (l.verdict && !l.verdict.pass) { expect('sent-back', '1 sent back'); }
    for (const [key, noun] of [['input', 'tokens in'], ['output', 'tokens out'], ['reasoning', 'reasoning tokens'], ['cache_read', 'cached tokens read'], ['cache_write', 'cached tokens written']]) {
      const n = l.seen?.tokens?.[key];
      assert.equal(!!card.querySelector('[data-launch-stat="' + key + '"]'), typeof n === 'number' && n > 0);
      if (typeof n === 'number' && n > 0) { expect(key, n + ' ' + noun); }
    }
    assert.equal(!!card.querySelector('[data-launch-stat="cost"]'), typeof l.seen?.cost === 'number' && l.seen.cost > 0);
    if (l.seen?.cost > 0) { expect('cost', '$' + l.seen.cost + ' cost'); }
    const result = card.querySelector('[class="launch-result"]');
    assert.ok(result.getAttribute('title')); assert.equal(result.textContent, result.getAttribute('title').split(/\r?\n/)[0]);
  });
  assert.equal(view.querySelectorAll('[data-launch]').length, doc.launches.length, 'The launch table still includes even untimed launches');
  view.querySelectorAll('[data-launch]').forEach(row => {
    const launch = doc.launches.find((l, i) => String(l.n || i + 1) === row.getAttribute('data-launch'));
    const tokens = launch.seen?.tokens || {}, cost = launch.seen?.cost;
    const cells = row.querySelectorAll('td');
    for (const [cell, value] of [[cells[7], tokens.input > 0 || tokens.output > 0 ? (tokens.input || 0) + ' / ' + (tokens.output || 0) : null], [cells[8], cost > 0 ? '$' + cost.toFixed(4) : null]]) {
      assert.equal(cell.textContent, value === null ? '—' : value);
      if (value === null) assert.equal(cell.querySelector('span').getAttribute('title'), 'Not recorded by this agent');
    }
  });
  assertLinks(view);
}
// The live team's seat words come from the leases the dispatcher holds (as the order status reads them).
function leaseWord(actor) {
  const held = Object.entries(dispatcher.leases).filter(([id, l]) => l.holder === actor && stateOrders[id] && stateOrders[id].state === 'LEASED');
  return held.some(([, l]) => l.expires > dispatcher.now) ? 'Working' : held.length ? 'Lease ran out' : 'Idle';
}
function assertSeatStates(view) {
  const isTeam = view.getAttribute('data-view') === 'team';
  team.seats.filter(s => s.model).forEach(seat => {
    const state = leaseWord(seat.actor || 'team:' + seat.id);
    const words = view.querySelectorAll('[data-seat-state="' + seat.id + '"]');
    assert.ok(words.length >= (isTeam ? 2 : 1), seat.name + ' appears in each seat block');
    words.forEach(word => assert.equal(word.textContent, state));
    const blocks = isTeam ? [view.querySelector('[data-org-node="' + seat.actor + '"]'), view.querySelector('[data-seat="' + seat.id + '"]')] : [view.querySelector('[data-home-seat="' + seat.id + '"]')];
    blocks.forEach(block => assert.equal(block.querySelector('[data-seat-state="' + seat.id + '"]').textContent, state));
  });
}
