  assert.equal(bar.getAttribute('role'), 'progressbar'); assert.equal(bar.getAttribute('aria-valuemin'), '0');
  assert.equal(Number(bar.getAttribute('aria-valuemax')), total); assert.equal(Number(bar.getAttribute('aria-valuenow')), done);
  const segmented = bar.querySelector('[data-order-steps]');
