      const x = Number(mark.getAttribute('cx')), y = Number(mark.getAttribute('cy')), rise = (pitch - 20) / 2;
      assert.ok(Math.abs(x - 76) / 64 + Math.abs(y - (rise + 4)) / rise < 1, 'Every disc sits on the top face');
      marks.slice(0, j).forEach(other => assert.ok(Math.hypot(x - Number(other.getAttribute('cx')), y - Number(other.getAttribute('cy'))) >= 10, 'Member rings do not overlap'));
    });
    assert.equal(slab.querySelector('[data-level-leader]').getAttribute('d'), 'M140 ' + pitch / 2 + ' H176', 'Leader reaches the row boundary at its midpoint');
  });
