}
function assertChart(home) {
  const chart = home.querySelector('[data-chart="activity"]'), plot = chart.querySelector('svg[class="run-chart"]'), line = chart.querySelector('path[data-chart-line]');
  const rows = eligibleRows(), start = rows[0].t, elapsed = Math.max(10, (team.launches.some(l => l.state === 'running') ? team.updated : rows.at(-1).t) - start), magnitude = Math.floor(Math.log10(elapsed)), step = Math.pow(10, magnitude) / 2, end = start + Math.ceil(elapsed / step) * step;
  assert.equal(Number(plot.getAttribute('data-start')), start); assert.equal(Number(plot.getAttribute('data-end')), end);
  const commands = [...line.getAttribute('d').matchAll(/([MLC]) ([\d.e+ -]+)/g)].map(m => ({cmd: m[1], p: m[2].trim().split(/\s+/).map(Number)}));
  const points = commands.slice(1, -1).map(c => c.p.slice(-2));
  assert.equal(points.length, 32); assert.equal(Number(line.getAttribute('data-points')), 32);
  assert.ok(chart.querySelector('[data-chart-area]'));
  const buckets = Array(32).fill(0);
  rows.forEach(e => { buckets[Math.min(31, Math.floor((e.t-start)/(end-start)*32))]++; });
  const maximum = Math.max(...buckets);
  assert.ok(chart.textContent.includes('Ledger rows'));
  points.forEach(([x, y], i) => {
    near(x, 40+(i+0.5)/32*880, 'Bucket centre');
    near(y, 196-buckets[i]/maximum*148, 'Ledger rows in bucket');
  });
  assert.equal(buckets.reduce((a,b) => a+b, 0), rows.length);
  assert.ok(chart.textContent.includes('as in Recent activity, excluding setup'));
  // Sample each cubic; its convex hull must stay within the neighbouring counts.
  commands.filter(c => c.cmd === 'C').forEach((c, i) => {
    const [x1,y1,x2,y2,x3,y3] = c.p, [x0,y0] = points[i];
    for (let step=0; step<=100; step++) {
      const t=step/100, y=(1-t)**3*y0+3*(1-t)**2*t*y1+3*(1-t)*t*t*y2+t**3*y3;
      assert.ok(y <= 196.000001 && y >= 47.999999, 'Curve never goes below the baseline or above the maximum');
      assert.ok(y >= Math.min(y0,y3)-0.01 && y <= Math.max(y0,y3)+0.01);
    }
    near(x1-x0, (x3-x0)/3, 'Linear cubic time'); near(x3-x2, (x3-x0)/3, 'Linear cubic time');
  });
  const terminal = new Map();
  log.forEach(e => { if (['order.succeeded','order.dead','order.cancelled'].includes(e.kind) || e.kind === 'order.failed' && !e.retry) { terminal.set(e.order, e); } });
  const marks = chart.querySelectorAll('circle[data-chart-mark]'); assert.equal(marks.length, terminal.size);
  // A: mark diameter is a screen-space contract, including after a resize.
  for (const widthScale of [.3, .55, 1.2]) {
    drawingScales['run-chart'] = widthScale;
    listeners.resize.forEach(f => f());
    marks.forEach(mark => {
      const m = mark.getScreenCTM(), r = Number(mark.getAttribute('r'));
      assert.ok(r * 2 * Math.hypot(m.a, m.b) >= 8, 'Chart mark screen width');
      assert.ok(r * 2 * Math.hypot(m.c, m.d) >= 8, 'Chart mark screen height');
    });
  }
  drawingScales['run-chart'] = .5; listeners.resize.forEach(f => f());
  for (const mark of marks) {
    const id = mark.getAttribute('data-chart-mark'), e = terminal.get(id);
    assert.ok(Number(mark.getAttribute('r')) >= 4); assert.ok(mark.querySelector('title').textContent.includes(stateOrders[id]?.title || id));
    near(Number(mark.getAttribute('cx')), 40+(e.t-start)/(end-start)*880, 'Order end time');
    const position = Math.max(0, Math.min(31, (Number(mark.getAttribute('cx'))-points[0][0])/(880/32)));
    const i = Math.min(30, Math.floor(position)), t = position-i;
    near(Number(mark.getAttribute('cy')), points[i][1]+(points[i+1][1]-points[i][1])*t*t*(3-2*t), 'Mark sits on the cubic');
    assert.equal(mark.getAttribute('data-tone'), e.kind === 'order.succeeded' ? 'done' : 'failed');
  }
  const counts = chart.querySelectorAll('[data-chart-count]'); assert.equal(counts.length, 3);
  assert.deepEqual(counts.map(c => Number(c.getAttribute('data-count'))), [1, 1, 1]);
  counts.forEach(c => assert.ok(c.querySelector('svg')));
  assert.equal(plot.querySelectorAll('text').filter(t => /^\d\d:\d\d:\d\d$/.test(t.textContent)).length, 5);
  assert.equal(plot.querySelectorAll('path[class="chart-grid"]').length, 8);
}
function assertSeatSummaries(view, attr = 'data-home-seat') {
  const cards = view.querySelectorAll('[' + attr + ']');
  assert.equal(cards.length, team.seats.length);
  cards.forEach(card => {
    const seat = team.seats.find(s => s.id === card.getAttribute(attr));
    const band = card.querySelector('.seat-band'); assert.ok(band);
    assert.equal(band.getAttribute('data-seat-tone'), String(team.seats.indexOf(seat) % 6 + 1));
    assert.ok(band.textContent.includes(seat.name)); assert.ok(band.textContent.includes(seat.model));
    const mine = team.launches.filter(l => l.agent === seat.actor), totals = card.querySelectorAll('[data-seat-summary]');
    assert.deepEqual(totals.map(e => e.getAttribute('data-seat-summary')), ['launches', 'seconds', 'accepted', 'sent-back']);
    assert.equal(totals[0].querySelector('strong').textContent, String(mine.length));
    const seconds = mine.reduce((sum, l) => sum + (l.secs ?? (typeof l.started === 'number' ? (l.ended ?? (l.state === 'running' ? team.updated : l.started)) - l.started : 0)), 0);
    assert.equal(totals[1].querySelector('strong').textContent, seconds.toFixed(1) + ' s');
    assert.equal(totals[2].querySelector('strong').textContent, String(seat.outcomes.accepted));
    assert.equal(totals[3].querySelector('strong').textContent, String(seat.outcomes.sent_back));
    totals.forEach(t => assert.ok(t.getAttribute('title')));
    if (!mine.length) { assert.ok(card.querySelector('[data-empty-inline]')); assert.equal(card.querySelector('[data-seat-spark]').querySelector('svg'), null); assert.ok(card.querySelector('[data-empty-title]')); assert.ok(card.querySelector('[data-empty-hint]')); assert.equal(card.querySelectorAll('[data-seat-spark-bar]').length, 0); return; }
    const spark = card.querySelector('[data-seat-spark]'); assert.equal(spark.getAttribute('width'), '104'); assert.equal(spark.getAttribute('height'), '24');
    const bars = spark.querySelectorAll('[data-seat-spark-bar]');
    const timed = mine.filter(l => typeof l.started === 'number' && (typeof l.ended === 'number' || l.state === 'running' || typeof l.secs === 'number'));
    assert.equal(bars.length, timed.length);
    bars.forEach((bar, i) => {
      const l = timed[i]; assert.equal(Number(bar.getAttribute('data-start')), l.started);
      assert.equal(Number(bar.getAttribute('data-end')), l.ended ?? (l.state === 'running' ? team.updated : l.started + l.secs));
      assert.ok(bar.querySelector('title').textContent.includes(' s'));
      assert.ok(Number(bar.getAttribute('x')) >= 0 && Number(bar.getAttribute('x')) + Number(bar.getAttribute('width')) <= 104.001);
    });
    assert.ok(spark.querySelector('.spark-track'));
    assert.equal(!!spark.querySelector('[data-seat-spark-line]'), timed.length > 0);
    if (timed.length) {
      assert.ok(spark.querySelector('.spark-area')); assert.ok(spark.querySelector('.spark-end'));
      const path = spark.querySelector('[data-seat-spark-line]').getAttribute('d');
      assert.ok(!/NaN|Infinity/.test(path));
      assert.equal([...path.matchAll(/ L /g)].length, timed.length - 1);
      const tip = spark.querySelector('.spark-end');
      assert.ok(Number(tip.getAttribute('cy')) >= 4 && Number(tip.getAttribute('cy')) <= 18);
    }
  });
}
function assertSplit(view, key, expected) {
  const plot = view.querySelector('[data-stat-chart="' + key + '"]'), total = expected.reduce((a, b) => a + b, 0);
  if (!total) { assert.equal(plot, null, key + ': no invented empty series'); return; }
  assert.ok(plot, key + ': real split is drawn');
  assert.equal(plot.getAttribute('data-chart-type'), 'split');
  const segments = plot.querySelectorAll('[data-stat-segment]');
  assert.deepEqual(segments.map(e => Number(e.getAttribute('data-value'))), expected, key + ': counts come from the fixture');
  segments.forEach((e, i) => {
    near(Number(e.getAttribute('width')), expected[i] / total * 160, key + ': proportional split');
    assert.ok(e.querySelector('title').textContent.endsWith(': ' + expected[i]));
  });
  assert.ok(plot.querySelector('title').textContent); assert.ok(plot.getAttribute('aria-label'));
}
function assertStatDrawings(view) {
  const kind = view.getAttribute('data-view');
  if (!['home', 'team'].includes(kind)) { return; }
  assertSplit(view, 'launches', [team.launched, Math.max(0, team.limit - team.launched)]);
  const working = team.seats.filter(s => leaseWord(s.actor || 'team:' + s.id) === 'Working').length;
  if (kind === 'home') {
    const orders = history.days[today]?.orders || [];
    assert.equal(view.querySelector('[data-stat="today"]').getAttribute('data-stat-alert') !== null, orders.some(o => ['FAILED', 'DEAD', 'CANCELLED'].includes(o.state)), 'Failure tint follows backend outcomes');
    const attention = view.querySelector('[data-stat="attention"]');
    assert.equal(attention.getAttribute('data-stat-alert') !== null, Number(attention.querySelector('[data-stat-value]').textContent) > 0, 'Attention tint follows the actual count');
    assertSplit(view, 'today', [orders.filter(o => o.state === 'SUCCEEDED').length, orders.filter(o => !['SUCCEEDED', 'FAILED', 'DEAD', 'CANCELLED'].includes(o.state)).length, orders.filter(o => ['FAILED', 'DEAD', 'CANCELLED'].includes(o.state)).length]);
    if (working) {
      assertSplit(view, 'running', [working, team.seats.length - working]);
      const seats = view.querySelectorAll('[data-seat-segment]');
      assert.deepEqual(seats.map(e => e.getAttribute('data-seat-segment')), team.seats.map(s => s.actor));
      seats.forEach((e, i) => {
        assert.equal(e.getAttribute('data-working'), String(leaseWord(team.seats[i].actor || 'team:' + team.seats[i].id) === 'Working'));
        near(Number(e.getAttribute('x')), i * 160 / team.seats.length, 'Fixed seat segment slot');
      });
    }
    else { assert.equal(view.querySelector('[data-stat-chart="running"]'), null, 'Zero working seats must not draw a filled bar'); }
    assert.equal(view.querySelector('[data-stat="attention"]').querySelector('[data-stat-chart]'), null, 'A scalar attention count has no invented trend');
  } else {
    const leads = team.seats.filter(s => s.actor === team.lead).length;
    assertSplit(view, 'seats', [leads, team.seats.length - leads]);
    assertSplit(view, 'working', [working, team.seats.length - working]);
    assertSplit(view, 'accepted', [team.order_totals.accepted, team.order_totals.steps_accepted]);
    assert.equal(view.querySelector('[data-team-stat="sent-back"]').querySelector('[data-stat-chart]'), null);
    const durations = team.launches.map(l => ({id: String(l.n || l.launch), seconds: typeof l.secs === 'number' ? l.secs : typeof l.started === 'number' && (typeof l.ended === 'number' || l.state === 'running' && typeof team.updated === 'number') ? (l.ended ?? team.updated) - l.started : null})).filter(p => p.seconds !== null);
    const plot = view.querySelector('[data-stat-chart="seconds"]');
    if (!durations.length) { assert.equal(plot, null, 'Missing timing draws no sparkline'); return; }
    assert.ok(plot.querySelector('title').textContent.startsWith('Launch durations in seconds:'));
    const points = plot.querySelectorAll('[data-stat-sample]');
    assert.deepEqual(points.map(p => ({id: p.getAttribute('data-stat-sample'), seconds: Number(p.getAttribute('data-value'))})), durations);
    assert.equal(!!plot.querySelector('path'), durations.length > 1, 'One real sample is a point, not a fabricated line');
    points.forEach(p => { assert.ok(p.querySelector('title')); assert.ok(Number(p.getAttribute('r')) * 2 >= 8); });
  }
}
function assertOrderDots(container, orders) {
