async function assertUnchangedPoll(view, lists) {
  lists.forEach((e, i) => { e.scrollTop = 37 + i * 13; });
  const nodes = view.querySelectorAll('*'), children = nodes.map(e => e.childNodes.slice()), attrs = nodes.map(e => e.attributeChanges.length), scrolls = lists.map(e => e.scrollTop);
  await refresh();
  assert.ok(view.querySelectorAll('*').every((e, i) => e === nodes[i]));
  assert.equal(view.querySelectorAll('*').length, nodes.length);
  assert.ok(nodes.every((e, i) => e.childNodes.length === children[i].length && e.childNodes.every((c, j) => c === children[i][j])), 'Unchanged polls retain every text node');
  assert.deepEqual(nodes.map(e => e.attributeChanges.length), attrs, 'Unchanged polls perform no attribute mutations');
  assert.deepEqual(lists.map(e => e.scrollTop), scrolls, 'Every inner list retains its scroll position');
}
async function assertReplayWorkspace(view) {
  const saved = JSON.parse(JSON.stringify({team, orders: stateOrders, log}));
  const base = 1900001000, issueTimes = [1, 4, 10, 13, 17, 23], starts = [2, 5, 11, 14, 18, 24];
  Object.keys(stateOrders).forEach(k => delete stateOrders[k]); log.splice(0); team.launches.splice(0); team.files.splice(0);
  team.run_started = base; team.updated = base + 29; team.ledger_updated = base + 29; team.launched = 6;
  log.push({kind: 'org.set', t: base, by: team.ceo});
  const actors = [team.lead, 'agent:writer', 'agent:reviewer'];
  for (let i = 0; i < 6; i++) {
    const actor = actors[i % 3], id = 'replay-' + i, order = {id, title: 'Recorded order ' + i, to: actor, state: 'SUCCEEDED', parent: i % 3 ? 'replay-' + (i < 3 ? 0 : 3) : null};
    stateOrders[id] = order;
    const end = starts[i] + (i === 1 ? 5 : 1.8), token = 500 + i;
    log.push({kind: 'order.issued', t: base + issueTimes[i], by: i % 3 ? team.lead : team.ceo, body: {...order}},
      {kind: 'lease.granted', t: base + starts[i], by: actor, order: id, token},
      {kind: 'report.submitted', t: base + end + .2, by: actor, order: id, token, outputs: [{key: id + '/one.txt', rev: 1}, {key: id + '/two.txt', rev: 1}]},
      {kind: 'order.succeeded', t: base + end + .3, by: team.judge, order: id, reason: 'Both files were handed in and passed the recorded checks.'});
