async function assertCanvasWorkspace(view) {
  const canvas = view.querySelector('[data-canvas]'), detail = () => view.querySelector('[data-seat-panel="selected"]');
  const nodes = () => canvas.querySelectorAll('[data-canvas-node]'), items = () => canvas.querySelectorAll('[data-canvas-item]');
  const pick = id => canvas.querySelector('[data-canvas-node="' + id + '"]').click();
  const tab = name => canvas.querySelector('[data-canvas-tab="' + name + '"]').click();
  const selected = id => {
    for (const key of ['node', 'item']) {
      const controls = canvas.querySelectorAll('[data-canvas-' + key + ']');
      assert.equal(controls.filter(b => b.getAttribute('aria-pressed') === 'true').length, 1);
      controls.forEach(b => assert.equal(b.getAttribute('aria-pressed'), String(b.getAttribute('data-canvas-' + key) === id)));
    }
  };
  assert.ok(canvas); assert.equal(byId('team-drawings').children[1].querySelector('[data-canvas]') === canvas, true);
  assert.equal(byId('team-drawings').children[2].querySelector('[data-seat-panel="selected"]') === detail(), true);
  assert.ok(byId('team-drawings').children[3].getAttribute('data-handoff') !== null);
  assert.equal(nodes().length, team.seats.length + 2 + Object.keys(stateOrders).length);
  assert.deepEqual(items().map(n => n.getAttribute('data-canvas-item')), nodes().map(n => n.getAttribute('data-canvas-node')));
  assert.deepEqual(canvas.querySelector('[data-timeline-legend]').querySelectorAll('.badge').map(b => b.textContent),
    ['Succeeded', 'Running', 'Needs attention', 'Failed', 'Planned']);
  const boxes = nodes().map(n => {
    assert.equal(n.tagName, 'button'); assert.equal(n.getAttribute('type'), 'button'); assert.ok(n.getAttribute('title'));
    const kind = n.getAttribute('data-kind'), id = n.getAttribute('data-canvas-node');
    assert.ok(['person','seat','program','order'].includes(kind));
    if (kind === 'order') {
      assert.equal(n.getAttribute('data-order'), id); assert.equal(n.getAttribute('data-run'), team.run); assert.ok(n.querySelector('.badge'));
      const listState = canvas.querySelector('[data-canvas-list-state="' + id + '"]');
      assert.equal(listState.textContent, n.querySelector('.badge').textContent);
      assert.equal(listState.getAttribute('data-state'), n.querySelector('.badge').getAttribute('data-state'));
    }
    else { assert.ok(view.querySelector('[data-org-node="' + id + '"]')); assert.ok(n.querySelector('[data-canvas-icon]')); assert.ok(n.querySelector('[data-seat-state]')); }
    const [x, y, w, h] = [...n.getAttribute('style').matchAll(/(?:left|top|width|height):([\d.]+)px/g)].map(m => Number(m[1]));
    assert.ok(w <= 176); assert.ok(h <= (kind === 'order' ? 44 : 68));
    if (kind !== 'order') { assert.equal(n.querySelector('[data-canvas-icon]').getAttribute('width'), '28'); assert.ok(n.querySelector('.hint').getAttribute('title')); }
    return {id, x, y, w, h};
  });
  boxes.forEach((a, i) => boxes.slice(i + 1).forEach(b => {
    assert.ok(a.x + a.w <= b.x || b.x + b.w <= a.x || a.y + a.h <= b.y || b.y + b.h <= a.y, 'Canvas nodes never overlap');
    if (a.x === b.x) { assert.ok(Math.max(a.y, b.y) - Math.min(a.y + a.h, b.y + b.h) >= 24, 'Column rows keep 24px clearance'); }
  }));
  const edges = canvas.querySelectorAll('[data-canvas-edge]'), rings = canvas.querySelectorAll('[data-edge-end]');
  assert.equal(edges.length, team.seats.length + Object.keys(stateOrders).length + 1);
  assert.equal(edges.filter(e => e.getAttribute('data-kind') === 'reports').length, team.seats.length);
  assert.equal(edges.filter(e => e.getAttribute('data-kind') === 'checks').length, 1);
  assert.equal(edges.filter(e => e.getAttribute('data-kind') === 'work').length, Object.keys(stateOrders).length);
  assert.equal(rings.length, edges.length * 2);
  edges.forEach((e, i) => {
    assertConnectorPaint(e); const points = pathPoints(e), from = boxes.find(n => n.id === e.getAttribute('data-from')), to = boxes.find(n => n.id === e.getAttribute('data-to'));
    const onBorder = (b, [x, y]) => ((x === b.x || x === b.x + b.w) && y >= b.y && y <= b.y + b.h) || ((y === b.y || y === b.y + b.h) && x >= b.x && x <= b.x + b.w);
    assert.ok(onBorder(from, points[0])); assert.ok(onBorder(to, points.at(-1)));
    rings.slice(i * 2, i * 2 + 2).forEach((r, end) => {
      assertRingPaint(r); assert.equal(r.getAttribute('data-from'), from.id); assert.equal(r.getAttribute('data-to'), to.id);
      const p = end ? points.at(-1) : points[0]; near(Number(r.getAttribute('cx')), p[0], 'Canvas ring x'); near(Number(r.getAttribute('cy')), p[1], 'Canvas ring y');
    });
