  search.value = ''; search.dispatch('input'); assert.ok(items().every(b => !b.hidden)); assert.equal(nodes().filter(b => b.getAttribute('data-search-dim') !== null).length, 0);
  const stage = canvas.querySelector('[data-canvas-stage]'), graph = canvas.querySelector('[data-canvas-view]'), scale = () => Number(graph.getAttribute('style').match(/scale\(([^)]+)\)/)[1]);
  const zoom = action => canvas.querySelector('[data-canvas-zoom="' + action + '"]').click();
  const transform = () => graph.getAttribute('style').match(/translate\(([-\d.]+)px,([-\d.]+)px\) scale\(([^)]+)\)/).slice(1).map(Number);
  assert.equal(stage.getAttribute('tabindex'), '0');
  assert.equal(canvas.querySelectorAll('[data-canvas-toolbar]').length, 1);
  assert.equal(canvas.querySelector('[data-canvas-toolbar]').querySelectorAll('[data-canvas-zoom]').length, 3);
  function fitBounds(factor) {
