async function assertKeyboardShortcuts() {
  const body = q('body');
  async function key(value, extra = {}) {
    document.dispatch('keydown', {key: value, target: document.activeElement || body, ...extra}); await flush(); finishEntrances();
  }
  body.focus(); await key('n'); assert.equal(document.activeElement, byId('compose-title'));
  const draft = 'Keep this draft'; byId('compose-title').value = draft;
  for (const field of [byId('compose-title'), byId('compose-goal'), byId('f-budget')]) {
    field.focus(); await key('g'); await key('t'); await key('?'); await key('n');
    assert.equal(location.hash, '#/'); assert.equal(document.activeElement, field);
  }
  const editor = document.createElement('div'); editor.setAttribute('contenteditable', 'true'); body.appendChild(editor); editor.focus();
  await key('?'); assert.equal(location.hash, '#/'); body.removeChild(editor); body.focus();
  for (const extra of [{ctrlKey: true}, {metaKey: true}, {altKey: true}, {isComposing: true}, {repeat: true}]) {
    await key('?', extra); assert.equal(location.hash, '#/');
  }
  for (const [letter, route] of Object.entries({t: 'team', c: 'calendar', b: 'board', f: 'files', l: 'ledger', h: ''})) {
    body.focus(); await key('g'); await key(letter); assert.equal(location.hash, '#/' + route);
    if (route === 'team') { assert.equal(q('[data-canvas-scale]').textContent, '80%', 'First load opens at 80%'); }
    assert.ok(q('[data-nav-to="' + (route || 'home') + '"]').getAttribute('title').includes('g then ' + letter));
  }
  body.focus(); await key('g'); await key('x'); await key('t'); assert.equal(location.hash, '#/');
  vm.runInContext('globalThis.savedNow = Date.now; Date.now = () => 1000;', context);
  await key('g'); vm.runInContext('Date.now = () => 2001;', context); await key('t'); assert.equal(location.hash, '#/');
  vm.runInContext('Date.now = savedNow;', context);
  await key('?'); assert.equal(location.hash, '#/help'); assert.equal(q('.shortcut-list').querySelectorAll('dd').length, 10);
  assert.ok(q('.shortcut-list').textContent.includes('Swarms'));
  await key('n'); assert.equal(location.hash, '#/'); assert.equal(document.activeElement, byId('compose-title')); assert.equal(byId('compose-title').value, draft);
  body.focus(); byId('preview').hidden = false; await key('?'); assert.equal(location.hash, '#/'); await key('Escape'); assert.equal(byId('preview').hidden, true);
  byId('compose-title').value = ''; body.focus();
}

