    assert.ok(edge.getAttribute('d').includes(' Q '), 'Flow routes have rounded bends');
    const segments = points.slice(1).map((p, i) => [...points[i], ...p]);
    assert.equal(edge.getAttribute('marker-end'), 'url(#flow-arrow-' + edge.getAttribute('data-kind') + ')');
    const from = nodes.find(n => n.id === edge.getAttribute('data-from')), to = nodes.find(n => n.id === edge.getAttribute('data-to'));
    assert.ok(Math.min(Math.abs(x1 - from.x), Math.abs(x1 - from.x - from.w)) < .001); assert.ok(y1 > from.y && y1 < from.y + from.h);
