    function checkText(e) {
      if (e.hidden || ['title', 'script', 'style'].includes(e.tagName)) { return; }
      for (const child of e.childNodes) {
        if (child.nodeType === 1) { checkText(child); }
        else {
          assert.ok(!/\b[A-Z]{4,}\b/.test(child.textContent), child.textContent);
          assert.ok(!/[a-f0-9]{16,}/i.test(child.textContent), child.textContent);
          if (child.textContent.includes('…')) {
            let parent = child.parentNode, found = false;
            while (parent) { if (parent.getAttribute && parent.getAttribute('title')) { found = true; break; } parent = parent.parentNode; }
            assert.ok(found, 'Ellipsized text must expose its full value.');
          }
        }
      }
    }
    checkText(view);
