  assert.equal(seat('team:lead').querySelector('[data-members]').getAttribute('data-members'), 'agent:writer');
  assert.ok(seat('team:lead').textContent.includes('A member is working: Writer (1 order)'));
  assert.ok(byId('team-holding').textContent.startsWith('2 people hold an order'));
  dispatcher.leases['main.part'].expires = dispatcher.now + 1; await statusTick();
  assert.equal(seat('agent:writer').getAttribute('data-busy'), 'true', 'One second left is still a lease.');
  dispatcher.leases['main.part'].expires = dispatcher.now; await statusTick();
  assert.equal(seat('agent:writer').getAttribute('data-busy'), 'false', 'A lease with no time left is not working.');
  assert.ok(seat('agent:writer').textContent.includes('Lease ran out on A renamed part'));
  assert.ok(seat('agent:writer').querySelector('[data-expired="main.part"]'));
  assert.ok(byId('team-holding').textContent.startsWith('1 person holds an order (1 lease ran out)'));
  assert.deepEqual([chip.getAttribute('data-held'), chip.getAttribute('data-attention')], ['1', '1']);
  status = await navigate('#/status', 'status');
  assert.deepEqual(flagsOf(status.querySelector('[data-status-card="main.part"]')), ['7a']);
  assert.equal(facts(status.querySelector('[data-status-card="main.part"]')).left, 0);
  assert.ok(status.querySelector('[data-status-card="main.part"]').querySelector('[data-flag="7a"]').textContent.includes('Lease ran out'));
  assert.equal(status.querySelector('[data-status-card="main.part"]').getAttribute('data-warn'), '');

  // Same fact, every place (skill same-fact-check): who holds an order now and how many orders are not ended, read from
  // the chip, the status view, the team view, Home and the day view, while orders are held and while none is.
  async function places() {
    const pairs = (root, tile) => root.querySelectorAll(tile).flatMap(t => { const e = t.querySelector('[data-holds]'); return e ? e.getAttribute('data-holds').split(' ').map(id => t.getAttribute('data-actor') + '>' + id) : []; }).sort();
    const read = {chip: {held: Number(chip.getAttribute('data-held')), notEnded: Number(chip.getAttribute('data-not-ended'))}};
    const s = await navigate('#/status', 'status'), cards = s.querySelectorAll('[data-status-card]');
    const openGroup = byId('status-open').querySelectorAll('[data-status-card]'), endedGroup = byId('status-ended').querySelectorAll('[data-status-card]');
    assert.deepEqual(openGroup.concat(endedGroup).map(c => c.getAttribute('data-status-card')).sort(), cards.map(c => c.getAttribute('data-status-card')).sort(), 'Every card once, in one group.');
    openGroup.forEach(c => assert.ok(c.getAttribute('data-case') === '1' || OPEN.includes(c.getAttribute('data-state'))));
    endedGroup.forEach(c => assert.ok(c.getAttribute('data-case') !== '1' && !OPEN.includes(c.getAttribute('data-state'))));
    read.status = {pairs: cards.filter(c => c.getAttribute('data-state') === 'LEASED' && !flagsOf(c).includes('7a')).map(c => facts(c).holder + '>' + c.getAttribute('data-status-card')).sort(),
      notEnded: cards.filter(c => OPEN.includes(c.getAttribute('data-state'))).length, words: Object.fromEntries(cards.map(c => [c.getAttribute('data-status-card'), [c.getAttribute('data-state'), c.querySelector('[data-situation]').textContent]]))};
    const t = await navigate('#/team', 'team');
    t.querySelectorAll('[data-seat]').forEach(e => assert.equal(e.getAttribute('data-busy'), String(!!e.querySelector('[data-holds]')), e.getAttribute('data-actor')));
    read.team = {pairs: pairs(t, '[data-seat]'), held: Number(byId('team-holding').getAttribute('data-held')), notEnded: Number(byId('team-holding').getAttribute('data-not-ended'))};
    const home = await navigate('#/', 'home');
    home.querySelectorAll('[data-home-seat]').forEach(e => assert.equal(e.getAttribute('data-busy'), String(!!e.querySelector('[data-holds]')), e.getAttribute('data-actor')));
    read.home = {pairs: pairs(home, '[data-home-seat]'), held: Number(byId('home-holding').getAttribute('data-held')), notEnded: Number(byId('home-holding').getAttribute('data-not-ended'))};
    const d = await navigate('#/day/' + today, 'day'), dayCards = byId('day-orders').querySelectorAll('a.order').filter(a => a.getAttribute('data-case'));
    read.day = {pairs: dayCards.flatMap(a => { const e = a.querySelector('[data-holder]'); return e && e.getAttribute('data-expired') === null ? [e.getAttribute('data-holder') + '>' + a.getAttribute('data-order')] : []; }).sort(),
      words: Object.fromEntries(dayCards.map(a => [a.getAttribute('data-order'), [a.getAttribute('data-state'), a.querySelector('[data-situation]').textContent]]))};
    const cal = await navigate('#/calendar/2030-04', 'calendar');
    read.calendar = {words: Object.fromEntries(cal.querySelectorAll('[data-day-order]').filter(e => e.getAttribute('data-case')).map(e => [e.getAttribute('data-day-order'), e.getAttribute('title').split(': ').pop()]))};
    const statusPairs = read.status.pairs;
    assert.deepEqual(read.team.pairs, statusPairs); assert.deepEqual(read.home.pairs, statusPairs);
    assert.deepEqual(read.day.pairs, statusPairs.filter(p => Object.keys(read.day.words).includes(p.split('>')[1])));
    for (const n of [read.chip.held, read.team.held, read.home.held]) { assert.equal(n, statusPairs.length); }
    for (const n of [read.chip.notEnded, read.team.notEnded, read.home.notEnded]) { assert.equal(n, read.status.notEnded); }
    for (const [id, word] of Object.entries(read.day.words)) { assert.deepEqual(word, read.status.words[id], id); }
    for (const [id, word] of Object.entries(read.calendar.words)) { assert.equal(word, read.status.words[id][1], id); }
    return read;
  }
  // An ended order and an unanswered issue are on the page too, and are not orders that have not ended.
  stateOrders['main.done'] = {id: 'main.done', title: 'A finished part', state: 'SUCCEEDED', parent: 'main', to: 'agent:writer', attempt: 1};
  dispatcher.sent = [{id: 'a00008', at: 1900000055, from: 'team:lead', kind: 'order.issue', order: 'main.lost', under: 'main', ok: null, code: null, detail: null, events: []}];
  dispatcher.leases['main.part'].expires = 1900003000; await statusTick();
  const whileHeld = await places();
  assert.equal(whileHeld.status.pairs.length, 2);
  const heldLeases = {...dispatcher.leases};
  for (const id of Object.keys(dispatcher.leases)) { delete dispatcher.leases[id]; stateOrders[id].state = 'PENDING'; }
  await statusTick();
  const whileNone = await places();
  assert.deepEqual(whileNone.status.pairs, []); assert.equal(whileNone.chip.held, 0);
  console.log('Same fact, every place: ' + JSON.stringify({whileHeld, whileNone}));
  delete stateOrders['main.done']; dispatcher.sent = [];
  Object.assign(dispatcher.leases, heldLeases); stateOrders.main.state = 'LEASED'; stateOrders['main.part'].state = 'LEASED'; delete dispatcher.leases['main.part']; stateOrders['main.part'].state = 'PENDING';
  await statusTick();

  // The diary the backend gives for today (read when the sender records change below).
  const entryAt = t => at8(t).slice(11, 19);
  diaries['live-run'] = {days: [{date: today, entries: 2}, {date: '2030-04-12', entries: 1}], byDay: {[today]: {families: [{top: 'main', title: 'Main order', orders: ['main'], entries: [
    {id: 'L000002', day: today, time: entryAt(1900000050), t: 1900000050, kind: 'report.progress', by: 'team:lead', nums: {pct: 40}, text: 'team:lead reported on main (40%): [draft] Writing the plan', ptr: [{type: 'ledger', seq: 2, h: 'abcdef0123456789'}]},
    {id: 'S000001', day: today, time: entryAt(1900000060), t: 1900000060, kind: 'sent.refused', by: 'team:lead', code: 'not-subset', nums: {}, text: 'team:lead sent order.issue (main.extra) and the dispatcher refused it: not-subset', ptr: [{type: 'sent', n: 1, sha: '0123456789abcdef'}]}]}],
  orders: {main: {title: 'Main order', metrics: {claim_delay: 2, first_word_delay: 48, max_silence: 48, first_pass: null, refused: {'not-subset': 1}, no_answer: 0, expired: 0, launches: 1, returned: 0, total_s: null}}}}}};
  // A refused issue is a card of its own (a ghost), first, and flags the order it was meant to go under.
  dispatcher.sent = [{id: 'a00009', at: 1900000060, from: 'team:lead', kind: 'order.issue', order: 'main.extra', under: 'main', ok: false, code: 'not-subset', detail: 'scope and budget stay inside the parent', events: []}];
  await statusTick();
  status = await navigate('#/status', 'status');
  const ghost = status.querySelector('[data-status-card]');
  assert.equal(ghost.getAttribute('data-status-card'), 'main.extra'); assert.equal(ghost.getAttribute('data-case'), '1'); assert.deepEqual(flagsOf(ghost), ['7b']);
  assert.equal(ghost.getAttribute('data-state'), 'NONE'); assert.equal(facts(ghost).reply, 'refused'); assert.equal(facts(ghost).code, 'not-subset');
  assert.ok(ghost.textContent.includes('Refused')); assert.ok(ghost.textContent.includes('No order page')); assert.equal(ghost.querySelector('a[data-order-link]'), null);
  assert.deepEqual(flagsOf(mainCard()), ['7b']); assert.equal(chip.getAttribute('data-attention'), '2');

  // The day view's diary, the month grid's entry counts, and times in the backend's zone (read off the diary).
  await navigate('#/day/' + today, 'day'); await flush();
  const diary = byId('day-diary');
  assert.equal(diary.getAttribute('data-diary-entries'), '2');
  assert.deepEqual(diary.querySelectorAll('[data-diary-entry]').map(e => e.getAttribute('data-diary-entry')), ['L000002', 'S000001']);
  const firstEntry = diary.querySelector('[data-diary-entry="L000002"]');
  assert.equal(firstEntry.getAttribute('data-ptr'), 'ledger:2:abcdef0123456789');
  assert.equal(firstEntry.querySelector('time').textContent, entryAt(1900000050));
  assert.ok(firstEntry.textContent.includes('reported on main')); assert.ok(firstEntry.textContent.includes('Ledger row 2'));
  assert.equal(diary.querySelector('[data-diary-entry="S000001"]').getAttribute('data-ptr'), 'sent:1:0123456789abcdef');
  const metrics = diary.querySelector('[data-diary-order="main"]').querySelectorAll('[data-metric]');
  assert.equal(metrics.length, 10);
