    ['refused', 'not-subset x1'], ['no_answer', '0'], ['expired', '0'], ['launches', '1'], ['returned', '0'], ['total_s', '-']]);
  assert.ok(diaryCalls.some(c => c.run === 'live-run' && c.date === today));
  assert.ok(firstEntry.querySelector('[class="what"]').textContent.startsWith('Lead reported on main'), 'The live run\'s diary names seats as the rest of the page does.');
  assert.ok(diary.querySelectorAll('th').some(th => th.textContent === 'Issue to end')); assert.ok(!diary.querySelectorAll('th').some(th => th.textContent === 'Total'));
  assert.equal(chip.getAttribute('data-last-ok'), stamp8(dispatcher.now), 'Times follow the backend\'s zone once the diary has shown it.');
  const month = await navigate('#/calendar/2030-04', 'calendar');
  assert.equal(month.querySelector('[data-day="' + today + '"]').getAttribute('data-diary-count'), '2');
  assert.ok(month.querySelector('[data-day="' + today + '"]').textContent.includes('2 diary entries'));
  assert.ok(month.querySelector('[data-day="2030-04-12"]').textContent.includes('1 diary entry'));
  assert.equal(month.querySelector('[data-day="2030-04-13"]').getAttribute('data-diary-count'), null);

  // No position in seconds anywhere: every time is a wall-clock time, durations stay durations.
  for (const route of ['#/', '#/status', '#/team', '#/day/' + today, '#/calendar/2030-04', '#/order/live-run/main', '#/ledger', '#/board']) {
    const view = await navigate(route, route === '#/' ? 'home' : route.split('/')[1]);
    (function walk(e) {
      if (e.hidden || ['title', 'script', 'style'].includes(e.tagName)) { return; }
      if (e.getAttribute && e.getAttribute('title')) { assert.ok(!/\b1\d{9}\b/.test(e.getAttribute('title')), route + ' title ' + e.getAttribute('title')); }
      for (const child of e.childNodes) {
        if (child.nodeType === 1) { walk(child); continue; }
        assert.ok(!/\b1\d{9}\b/.test(child.textContent), route + ': ' + child.textContent);
        assert.ok(!child.textContent.includes(String.fromCharCode(0x7b2c)), route + ': ' + child.textContent);   // the row-position word of the earlier page
        assert.ok(!/\b[A-Z]{4,}\b/.test(child.textContent), route + ': ' + child.textContent);
        assert.ok(!/[a-f0-9]{16,}/i.test(child.textContent), route + ': ' + child.textContent);
      }
    }(view));
    view.querySelectorAll('[data-status-card]').forEach(c => assert.doesNotThrow(() => JSON.parse(c.getAttribute('data-facts'))));
  }

  // What the chip counts as needing attention is listed under Home's attention too, with its words.
  const warnedCards = (await navigate('#/status', 'status')).querySelectorAll('[data-status-card]').filter(c => c.getAttribute('data-warn') === '').map(c => c.getAttribute('data-status-card'));
  assert.equal(warnedCards.length, Number(chip.getAttribute('data-attention'))); assert.ok(warnedCards.length > 0);
  await navigate('#/', 'home'); await refresh();
  assert.deepEqual(byId('attention').querySelectorAll('[data-status-warn]').map(e => e.getAttribute('data-status-warn')).sort(), warnedCards.sort(),
    'Every order the chip counts as needing attention is on Home.');
  assert.ok(byId('attention').querySelector('[data-status-warn="main"]').textContent.includes('The last envelope about it was refused.'));
  // A question that blocks a waiting order is a block, not a hold ("held" is the word of a valid lease), and a person is "you".
  dispatcher.asks.q1 = {id: 'q1', about: 'main.part', to: 'human:ceo', text: 'Which format?', blocking: true, state: 'OPEN', touched: 1900000090};
  await statusTick(); status = await navigate('#/status', 'status');
  const blocked = status.querySelector('[data-status-card="main.part"]');
  assert.equal(facts(blocked).blocked, 'ask'); assert.ok(blocked.textContent.includes('Blocked by an open question to you.'), blocked.textContent);
  assert.ok(!blocked.textContent.includes('Held by'), blocked.textContent);
  delete dispatcher.asks.q1; await statusTick();
  // A past run's order that never ended is stopped: Home does not count it with the live run's, and every place names it so.
  const homeView = await navigate('#/', 'home'), statOf = key => Number(homeView.querySelector('[data-stat="' + key + '"]').querySelector('[data-stat-value]').textContent);
  const beforeStale = [statOf('today'), statOf('running')], sentence = byId('hero-sentence').textContent;
  history.days[today].orders.push({...currentOrder, id: 'stale', title: 'Stale order', run: 'old-run', state: 'PENDING', lead: oldLead});
  await refresh();
  assert.deepEqual([statOf('today'), statOf('running')], [beforeStale[0] + 1, beforeStale[1]], 'The stopped order is one of today\'s orders, not one that is moving.');
  assert.equal(byId('hero-sentence').textContent, sentence);
  const staleCard = byId('home-orders').querySelector('a[data-order="stale"]');
  assert.ok(staleCard.querySelector('[data-stopped]')); assert.ok(staleCard.textContent.includes('Past run, stopped')); assert.ok(!staleCard.textContent.includes('Waiting'));
  const staleMonth = await navigate('#/calendar/2030-04', 'calendar');
  assert.equal(staleMonth.querySelector('[data-day-order="stale"]').getAttribute('title').split(': ').pop(), 'Past run, stopped');
  assert.equal(staleMonth.querySelector('[data-day-order="stale"]').getAttribute('data-status'), 'failed');
  for (const words of ['Waiting', 'Being worked on', 'Sub-orders open', 'With the judge', 'Past run, stopped']) { assert.ok(byId('calendar-legend').textContent.includes(words), words); }
  history.days[today].orders.pop(); await refresh();
  // The order page's own card does not link to the page it is on; its seats say working or idle by lease, as Team does;
  // its header says which seconds it adds up.
  const ownPage = await navigate('#/order/live-run/main', 'order');
  assert.equal(ownPage.querySelector('[data-order-status="main"]').querySelector('a[data-order-link][data-order="main"]'), null);
  ownPage.querySelectorAll('[data-seat]').forEach(e => assert.equal(e.getAttribute('data-busy'), String(!!e.querySelector('[data-holds]')), e.getAttribute('data-actor')));
  assert.ok(ownPage.querySelectorAll('[data-seat]').every(e => !e.textContent.includes('Waiting')));
  assert.ok(ownPage.querySelector('[data-order-metrics]').querySelector('[data-metric="seconds"]').getAttribute('title').startsWith('Wall time from order issue'), 'The header says which seconds it adds up.');
  assert.ok(chip.querySelector('[data-chip-count="not-ended"]').textContent.startsWith('· '), 'The link word stands apart from the first count.');

  // Paused while the tab is hidden, at once when it comes back.
  const stateReads = () => calls.filter(c => c.url.startsWith('/state')).length;
  document.hidden = true; let before = stateReads(); await statusTick(); assert.equal(stateReads(), before, 'A hidden tab does not poll.');
  document.hidden = false; document.dispatch('visibilitychange'); await flush(); assert.equal(stateReads(), before + 1, 'Coming back polls at once.');

  // The backend down: the chip says so with the last good time; cards keep their last situation with 7c, then 7d.
  status = await navigate('#/status', 'status');
  dispatcher.fail = true; await statusTick();
  assert.equal(chip.getAttribute('data-link'), 'down');
  assert.ok(chip.textContent.includes('No answer since ' + stamp8(dispatcher.now)), chip.textContent);
  assert.ok(status.querySelector('[data-status-banner="down"]').textContent.includes(stamp8(dispatcher.now)));
  status.querySelectorAll('[data-status-card]').forEach(c => { assert.ok(flagsOf(c).includes('7c')); assert.ok(!flagsOf(c).includes('7d')); });
  assert.equal(mainCard().getAttribute('data-case'), '4', 'The last known situation stays.');
  assert.ok(mainCard().querySelector('[data-flag="7c"]').textContent.includes(stamp8(dispatcher.now)));
  monoMs = 10000; await statusTick();
  status.querySelectorAll('[data-status-card]').forEach(c => assert.ok(!flagsOf(c).includes('7d'), 'Exactly two poll periods old is not out of date.'));
  monoMs = 10001; await statusTick();
  status.querySelectorAll('[data-status-card]').forEach(c => assert.ok(flagsOf(c).includes('7d')));
  assert.ok(mainCard().querySelector('[data-flag="7d"]').textContent.includes(stamp8(dispatcher.now)));
  const missingDay = await navigate('#/day/2030-04-13', 'day'); await flush();
  assert.ok(missingDay.querySelector('[data-diary-error]')); assert.equal(byId('day-diary').querySelector('[data-empty-title]').textContent, 'No diary for this day.');
  dispatcher.fail = false; await statusTick();
  assert.equal(chip.getAttribute('data-link'), 'up');
  // The top pill and the chip change together: the one-second refresh that finds the backend gone, or back, moves both.
  dispatcher.fail = true; await refresh();
  assert.deepEqual([byId('backend').getAttribute('data-state'), chip.getAttribute('data-link')], ['offline', 'down'], 'The chip does not wait for its own five-second timer.');
  dispatcher.fail = false; await refresh();
  assert.deepEqual([byId('backend').getAttribute('data-state'), chip.getAttribute('data-link')], ['running', 'up']);
  status = await navigate('#/status', 'status');
  status.querySelectorAll('[data-status-card]').forEach(c => { assert.ok(!flagsOf(c).includes('7c')); assert.ok(!flagsOf(c).includes('7d')); });

  // Another ledger behind the same address: the log is read again from row 0.
  dispatcher.ledger = 'another-ledger'; log.splice(0, log.length, {seq: 1, kind: 'order.issued', t: 1900000090, by: 'human:ceo', body: {id: 'main', title: 'Main order', to: 'team:lead'}});
