/* Pass 29: exercise both the completed Library loop and a pending review.
 * Run at 1280 x 900 after three orders through page_library_loop.js. Unlike the
 * old geometry check, this does not silently skip when history spans runs. */
(async function () {
  'use strict';
  const measureBox = node => (node.getBoundingClientRect());
  const check=(ok,msg)=>{if(!ok)throw Error(msg);}, pause=ms=>new Promise(r=>setTimeout(r,ms));
  location.hash='#/';await pause(1000);
  const home=document.querySelector('[data-view=home]'), snapshot=await(await fetch('/poll?since=0')).json();
  const line=home.querySelector('[data-chart-line]'), rect=line?.getBoundingClientRect();
  if(line){check(rect.width>=400,'Activity line width '+rect.width);check(rect.height>=65,'Activity line height '+rect.height);}
  const band=home.querySelector('[data-home-proposals]'), proposals=snapshot.library.entries.filter(e=>e.status==='proposed');
  check(band.hidden===!proposals.length,'Band only exists for pending proposals');
  check(!home.querySelector('#attention [data-attention-proposal]'),'Attention contains orders only');
  check(band.querySelectorAll('[data-attention-proposal]').length===proposals.length,'Every pending proposal remains');
  if(proposals.length){const r=measureBox(band),hero=measureBox(home.querySelector('[data-hero]')),overview=measureBox(home.querySelector('.home-overview'));check(r.width===hero.width&&r.top>=hero.bottom&&r.bottom<=overview.top,'Full-width band between hero and chart');for(const code of band.querySelectorAll('[data-diff-line] code'))check(getComputedStyle(code).overflowX==='visible'&&getComputedStyle(code).whiteSpace==='pre-wrap','Band diff never truncates');}
  if(proposals.length>1){
    const header=band.querySelector('.proposal-band-head'),toggle=header?.querySelector('[data-show-all="home-proposals"]');
    check(toggle&&toggle.classList.contains('link'),'Proposal toggle belongs to the header as a quiet link');
    check(toggle.textContent==='Show all '+proposals.length,'Proposal toggle includes its count');
    const button=measureBox(toggle),head=measureBox(header);
    check(Math.abs(button.right-head.right)<1&&button.top>=head.top&&button.bottom<=head.bottom,'Proposal toggle is right-aligned inside header');
    check(Math.abs(measureBox(home.querySelector('.home-overview')).top-measureBox(band).bottom-16)<1,'Proposal band ends 16 px above charts');
    toggle.click();check(toggle.getAttribute('aria-expanded')==='true','Header toggle expands all proposals');
    toggle.click();check(toggle.getAttribute('aria-expanded')==='false','Header toggle collapses again');
  }
  // Count actual card-like surfaces, not class names or undersized tiles.
  const cards=[...home.querySelectorAll('*')].filter(e=>{
    if(!e.getClientRects().length||e.closest('[hidden]')||e.matches('a,button,input,select,textarea,[role="button"]'))return false;
    const s=getComputedStyle(e),r=measureBox(e);
    const surface=s.backgroundColor!=='rgba(0, 0, 0, 0)'||s.backgroundImage!=='none'||parseFloat(s.borderTopWidth)>0;
    return r.width>=160&&r.height>=60&&parseFloat(s.borderTopLeftRadius)>=8&&surface;
  }).length;
  const orders=Object.values(snapshot.state.state.orders).filter(o=>!o.parent);
