/* Pass 33: render text separately from its actual painted backdrop. The local
 * CDP driver captures a PNG after prepareInk(), then supplies it to measureInk().
 * This includes gradients, nested alpha surfaces and glass in the contrast test.
 * Character centres sample the background, not antialiased foreground pixels. */
(function () {
  'use strict';
  const measureBox = node => (node.getBoundingClientRect());
  const visible = e => e.getClientRects().length && getComputedStyle(e).visibility !== 'hidden' && !e.closest('[hidden],details:not([open]) > :not(summary)');
  const colourCanvas = document.createElementNS('http://www.w3.org/1999/xhtml', 'canvas'); colourCanvas.width = colourCanvas.height = 1;
  const colourContext = colourCanvas.getContext('2d', {willReadFrequently: true}), colours = new Map();
  const colour = value => {
    if (!colours.has(value)) {
      colourContext.clearRect(0, 0, 1, 1); colourContext.fillStyle = value; colourContext.fillRect(0, 0, 1, 1);
      const pixels = [...colourContext.getImageData(0, 0, 1, 1).data]; colours.set(value, pixels.slice(0, 3).concat(pixels[3] / 255));
    }
    return colours.get(value).slice();
  };
  const luminance = rgb => rgb.map(n => { n /= 255; return n <= .04045 ? n / 12.92 : ((n + .055) / 1.055) ** 2.4; }).reduce((sum, n, i) => sum + n * [.2126, .7152, .0722][i], 0);
  const name = e => e.tagName.toLowerCase() + (e.id ? '#' + e.id : '') + (typeof e.className === 'string' && e.className ? '.' + e.className.trim().split(/\s+/).join('.') : '');
  let records, conceal;
  window.prepareInk = () => {
    records = [];
    const colours = new Set(), fonts = new Set();
    for (const e of [...document.querySelectorAll('body *')].filter(visible)) {
      if (e.matches('script,style,title,desc,option')) continue;
      const s = getComputedStyle(e), svg = e.namespaceURI.includes('svg');
      if (svg && !e.matches('text,tspan')) continue;
      const nodes = [...e.childNodes].filter(n => n.nodeType === 3 && n.textContent.trim());
      if (!nodes.length && !e.matches('input:not([type=range]),textarea,select')) continue;
      const isPlaceholder = e.matches('input,textarea') && !e.value && e.placeholder;
      const fg = colour(isPlaceholder ? getComputedStyle(e, '::placeholder').color : svg ? s.fill : s.color);
      let opacity = 1;
      for (let p = e; p; p = p.parentElement) opacity *= Number(getComputedStyle(p).opacity);
      fg[3] *= opacity;
      const clips = [];
      for (let p = e; p; p = p.parentElement) {
        const st = getComputedStyle(p), r = measureBox(p);
        if (st.overflowX !== 'visible' || st.overflowY !== 'visible') clips.push({r, x: st.overflowX !== 'visible', y: st.overflowY !== 'visible'});
      }
      const points = [];
      for (const n of nodes) {
        for (let i = 0; i < n.textContent.length; i++) {
          if (!n.textContent[i].trim()) continue;
          const range = document.createRange(); range.setStart(n, i); range.setEnd(n, i + 1);
          for (const r of range.getClientRects()) {
            if (!r.width || !r.height) continue;
            const x = r.x + r.width / 2, y = r.y + r.height / 2;
            if (clips.some(c => (c.x && (x < c.r.left || x > c.r.right)) || (c.y && (y < c.r.top || y > c.r.bottom)))) continue;
            points.push([Math.floor(x + scrollX), Math.floor(y + scrollY)]);
          }
        }
      }
      if (!nodes.length) {
        const r = measureBox(e);
        points.push([Math.floor(r.x + parseFloat(s.paddingLeft) + 8), Math.floor(r.y + r.height / 2)]);
      }
      if (!points.length) continue;
      colours.add(JSON.stringify(fg)); fonts.add(parseFloat(s.fontSize));
      const dimmed = !!e.closest('[data-dim]');
      records.push({element: name(e), text: (isPlaceholder || e.value || nodes.map(n => n.textContent).join('')).trim().slice(0, 80), fg, points, dimmed,
        minimum: !dimmed && (parseFloat(s.fontSize) >= 24 || (parseFloat(s.fontSize) >= 18.66 && Number(s.fontWeight) >= 700)) ? 3 : 4.5});
    }
    conceal = document.createElement('style');
    conceal.textContent = ':root body [data-dim], :root body [data-dim] *, body * { color:rgb(0 0 0 / 0) !important; text-shadow: none !important; caret-color:rgb(0 0 0 / 0) !important; } body *::placeholder { color:rgb(0 0 0 / 0) !important; } svg text, svg tspan { fill: transparent !important; }';
    document.head.appendChild(conceal);
    return {route: location.hash, records: records.length, colours: colours.size, fonts: [...fonts].sort((a, b) => a - b)};
  };
  window.measureInk = async png => {
    const picture = new Image(); picture.src = 'data:image/png;base64,' + png; await picture.decode();
    const canvas = document.createElementNS('http://www.w3.org/1999/xhtml', 'canvas'); canvas.width = picture.width; canvas.height = picture.height;
    const context = canvas.getContext('2d'); context.drawImage(picture, 0, 0);
    const pixels = context.getImageData(0, 0, canvas.width, canvas.height).data;
    const results = records.map(({points, ...record}) => {
      let ratio = Infinity, position, background;
      for (const [x, y] of points) {
        if (x < 0 || y < 0 || x >= canvas.width || y >= canvas.height) continue;
        const offset = (y * canvas.width + x) * 4, bg = [...pixels.slice(offset, offset + 3)];
