    }).filter(r => Number.isFinite(r.ratio)).sort((a, b) => a.ratio - b.ratio);
    conceal.remove();
    const failures = results.filter(r => r.ratio < r.minimum || (r.dimmed && r.ratio > 7));
    if (failures.length) throw Error(location.hash + ' painted text contrast: ' + JSON.stringify(failures));
    const dimmed = results.filter(r => r.dimmed);
    return {route: location.hash, measured: results.length, lowest: results[0], dimmed: dimmed.length ? {count: dimmed.length, minimum: Math.min(...dimmed.map(r => r.ratio)), maximum: Math.max(...dimmed.map(r => r.ratio))} : null, failures};
  };
}());
