/* Local browser contract. Run against an empty stand-in server with
   FAKE_OPENCODE_LIBRARY={"uses":"context","loop":true}. Every write uses the UI.
   The driver calls stages separately to capture and inspect each result. */
(function () {
  'use strict';
  if (location.hostname !== '127.0.0.1') throw new Error('Local rehearsal only');
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const read = async url => { const r = await fetch(url); if (!r.ok) throw new Error(url); return r.json(); };
  const check = (ok, message) => { if (!ok) throw new Error(message); };
  const wait = async (fn, label) => { for (let n=0;n<160;n++) { const value=await fn(); if(value)return value; await sleep(250); } throw new Error('Timed out: '+label); };
  const go = async hash => { location.hash=hash; await sleep(900); };
  const q = s => document.querySelector('[data-view]:not([hidden])').querySelector(s) || document.querySelector('#toast').querySelector(s) || document.querySelector(s), qa = s => [...document.querySelector('[data-view]:not([hidden])').querySelectorAll(s)];
  const data = {checks: 0, clicks: {}, orders: []};
  const assert = (ok, text) => { check(ok, text); data.checks++; };
  const order = async (title, goal) => {
    await go('#/'); const before=(await read('/poll?since=0')).state.state.orders;
    q('#compose-title').value=title; q('#compose-goal').value=goal; q('#compose-submit').click();
    const id=await wait(async()=>Object.keys((await read('/poll?since=0')).state.state.orders).find(id=>!before[id]),'order receipt');
    const doc=await wait(async()=>{const d=await read('/order?id='+id);return d.order.state==='SUCCEEDED'&&d.children.length===2?d:null;},'accepted two-step order');
    data.orders.push(doc.order.id); data.run=doc.run; await sleep(1400); return doc;
  };
  const item = id => read('/library/item?id='+id);
  window.libraryLoop = {
    data,
    async first() {
      assert(!(await read('/library')).entries.length,'Start with an empty Library');
      const doc=await order('Release review checklist','Read the goal.\nCheck the heading.\nRecord a concrete check.\nHand off the evidence.');
      data.first=doc.order.id; data.path=doc.files.find(f=>f.path.endsWith('notes.md')).path;
      await go('#/order/'+doc.run+'/'+doc.order.id);
      const row=qa('[data-order-files] [data-file]').find(e=>e.dataset.file===data.path);
      assert(row.dataset.accepted==='true','The kept revision was accepted');
