      assert(row.querySelector('[name=keep-tags]').value==='markdown','Tags are prefilled from file type');
      row.querySelector('[data-save-file][data-kind=skill]').click(); data.clicks.keep=1;
      await wait(()=>row.querySelector('[data-saved]'),'keep receipt');
      const saved=row.querySelector('[data-saved] a'); data.old=saved.dataset.libId;
      assert(saved.textContent==='In the Library','Quiet saved mark links to entry');
      assert(!row.querySelector('[data-save-file]'),'Same revision has no second Keep');
      assert(q('#toast [data-lib-id="'+data.old+'"]'),'Toast links to the kept entry');
      data.original=(await item(data.old)).text;
      await sleep(1400); assert(!row.querySelector('[data-save-file]'),'Saved mark survives polling');
      return data;
    },
    async available() {
      await go('#/');
      assert(q('[data-available-counts]').textContent==='The lead can use: 1 skill, 0 artifacts','Availability is visible before sending');
      assert(q('[data-available-entry="'+data.old+'"]'),'Available entry pill'); return data;
    },
    async inlineEdit() {
      const snapshot=await read('/poll?since=0'), root=Object.values(snapshot.state.state.orders).find(o=>!o.parent);
