      const row=qa('[data-order-files] [data-file]').find(e=>e.querySelector('[data-keep-edit]'));
      assert(row,'An accepted revision is available to keep');
      row.querySelector('summary').click();
      const title=row.querySelector('[name=keep-title]'), tags=row.querySelector('[name=keep-tags]');
      title.value='Release evidence checklist'; tags.value='markdown, release'; title.focus();
      // A changed response forces the same reconciliation as an arriving backend fact.
      const original=window.fetch; let updates=0;
      window.fetch=async(...args)=>{const r=await original(...args);if(String(args[0]).startsWith('/order?')){const d=await r.json();d.updated+=++updates;return new Response(JSON.stringify(d),{status:200,headers:{'Content-Type':'application/json'}});}return r;};
