      assert(q('[data-proposal-author] [data-seat-open]'),'Proposing seat is identified');
      assert(q('[data-lib-detail] [data-order="'+data.second+'"]'),'Source order is linked');
      const diff=q('[data-library-diff]');
      assert(diff.querySelector('[data-diff-line=add]')&&diff.querySelector('[data-diff-line=remove]'),'Real additions and removals');
      const unchanged=diff.querySelector('[data-unchanged]'); assert(unchanged&&!unchanged.open,'Unchanged spans start collapsed');
      unchanged.querySelector('summary').click(); assert(unchanged.open,'Unchanged lines expand in place');
      await sleep(1300); assert(q('[data-unchanged]').open,'Expanded lines survive polling');
      q('[data-unchanged] summary').click(); return data;
    },
    async decide() {
      q('[data-lib-accept]').click(); await wait(async()=>(await item(data.new)).status==='accepted','accept');
      assert(q('[data-review-undo]'),'Accept has undo'); q('[data-review-undo]').click();
      await wait(async()=>(await item(data.new)).status==='proposed','undo accept');
      assert((await item(data.old)).status==='accepted','Undo restores previous version');
      await wait(()=>q('[data-lib-accept]')&&!q('[data-lib-accept]').disabled&&q('[data-lib-detail]').dataset.libStatus==='proposed','accept control restored'); q('[data-lib-accept]').click();
      await wait(async()=>(await item(data.new)).status==='accepted','accept again');
      await go('#/library'); const weak=()=>q('[data-review-entry="'+data.weak+'"]');
      weak().querySelector('[data-lib-reject]').click(); await wait(async()=>(await item(data.weak)).status==='rejected','decline without reason');
      await wait(()=>weak()?.querySelector('[data-review-undo]'),'Decline receipt rendered');
      assert(weak().querySelector('[data-review-undo]'),'Decline has its own undo'); weak().querySelector('[data-review-undo]').click();
      await wait(()=>weak()?.querySelector('[data-lib-reject]')&&!weak().querySelector('[data-lib-reject]').disabled,'decline restored'); weak().querySelector('summary').click();
      weak().querySelector('[data-lib-reason]').value='Keep the evidence check.'; await sleep(1400);
      weak().querySelector('[data-lib-reject]').click(); await wait(async()=>(await item(data.weak)).status==='rejected','decline with reason');
      assert((await item(data.weak)).reason==='Keep the evidence check.','Optional reason survives a poll');
      assert((await item(data.new)).status==='accepted','Decline Undo never reverses a different acceptance');
      await sleep(6200); assert(q('#toast').hidden,'Undo toast expires after six seconds');
      const current=await item(data.new); assert(current.version===2&&current.versions.length===2,'Version list retains both versions');
      assert(current.versions.find(e=>e.version===1).text===data.original,'Version one bytes retained');
      data.clicks.decide={accept:1,decline:1,additionalUndoChecks:4};
