/* Pass 28 browser contracts. Run after libraryLoop.first/available/second with
 * the local fake agent's loop_long fixture; all decisions use page controls. */
(function () {
  'use strict';
  const measureBox = node => (node.getBoundingClientRect());
  if (location.hostname !== '127.0.0.1') throw Error('Local rehearsal only');
  const sleep=ms=>new Promise(r=>setTimeout(r,ms)), read=async u=>(await fetch(u)).json();
  const view=()=>document.querySelector('[data-view]:not([hidden])'), q=s=>view().querySelector(s);
  const go=async hash=>{location.hash=hash;await sleep(500);};
  const result={checks:0,components:[]};
  const assert=(ok,label)=>{if(!ok)throw Error(label);result.checks++;};
  const wait=async(fn,label)=>{for(let i=0;i<200;i++){if(await fn())return;await sleep(25);}throw Error(label);};
  const card=id=>q('[data-proposal-card="'+id+'"]');
  window.shelfChecks={result,
    async agreement(id){
      const source=await read('/library/item?id='+id); let first;
      for(const route of ['#/','#/library','#/library/'+id]){
        await go(route); await wait(()=>card(id),'Shared proposal loaded on '+route); const c=card(id); assert(c,'Shared proposal on '+route);
        const visible=[...c.querySelectorAll('[data-diff-line]')].filter(e=>e.dataset.diffLine!=='same'&&!e.closest('[data-diff-more]'));
        assert(visible.length===Math.min(6,source.diff.added+source.diff.removed),'First six changed lines');
        if(source.diff.added+source.diff.removed>6)assert(c.querySelector('[data-diff-more]'),'Remaining changes stay expandable');
        assert(c.querySelector('[data-proposal-author] [data-seat-open]'),'Proposer seat control');
        assert(c.querySelector('[data-order="'+source.source.order+'"]'),'Source order link');
        assert(c.querySelector('[data-lib-accept]')&&c.querySelector('[data-lib-reject]'),'Both direct decisions');
        const style=c.getAttribute('style'); c.style.width='440px';
