/* Verify real 1280px live recordings from the local CDP rehearsal.
   Usage: node tests/page_live_checks.js home-recording.json team-recording.json
   Each recording contains the DOM and backend snapshot captured every 500ms. */
'use strict';
const assert = require('node:assert/strict');
const fs = require('node:fs');
const records = process.argv.slice(2);
assert.ok(records.length >= 2, 'Supply Home and Team live recordings');
let homeSeen = false, teamSeen = false;
const results = records.map(file => {
  const {beforeSend, immediate, receipt, frames} = JSON.parse(fs.readFileSync(file, 'utf8'));
  assert.equal(immediate.busy, 'true');
  assert.equal(immediate.button, 'Sending to lead');
  assert.ok(immediate.text, 'Draft remains until success');
  assert.ok(immediate.ms <= 300 && receipt.ms <= 300, 'Busy state and local receipt within 300ms');
  assert.equal(receipt.hash, '#/'); assert.equal(receipt.focus, 'compose-title');
  assert.ok(receipt.toast.includes(immediate.text)); assert.equal(receipt.links.length, 1);
  assert.ok(Math.abs(receipt.formY - beforeSend.formY) <= 2, 'The first poll must not move the compose form');
  assert.ok(frames.length >= 20, 'Watch the whole delayed run');
  let maximumShift = 0;
  for (let i = 1; i < frames.length; i++) {
    assert.ok(frames[i].ms - frames[i - 1].ms <= 750, 'Capture at 500ms cadence, allowing rendering overhead');
    if (frames[i].poll === frames[i - 1].poll) continue;
    for (const heading of frames[i].headings) {
      const previous = frames[i - 1].headings.find(h => h.key === heading.key);
      if (previous) maximumShift = Math.max(maximumShift, Math.abs(heading.x - previous.x), Math.abs(heading.y - previous.y));
    }
  }
  assert.ok(maximumShift <= 2, 'Unchanged headings moved ' + maximumShift + 'px');
  const transitions = frames.map(f => f.activity).filter((state, i, all) => !i || state !== all[i - 1]);
  assert.deepEqual(transitions, ['Running', 'Succeeded'], 'One terminal transition, without flicker');
  assert.equal(frames.at(-1).root.state, 'SUCCEEDED');
  assert.ok(frames.at(-1).toast.includes('succeeded.')); assert.ok(frames.at(-1).toast.includes('Open'));
  for (const f of frames) {
    assert.equal(f.workPill, f.root.state === 'SUCCEEDED' ? 'done' : 'running');
    for (const seat of f.team.seats) {
      const busy = f.team.launches.some(l => l.agent === seat.actor && l.state === 'running');
      f.seatStates.filter(s => s.id === seat.id || s.id === seat.actor).forEach(s => assert.equal(s.text, busy ? 'Working' : 'Idle'));
      f.workingSegments.filter(s => s.actor === seat.actor).forEach(s => assert.equal(s.working, String(busy)));
    }
    const order = f.orderPills.find(o => o.id === f.root.id), dot = f.week.find(o => o.id === f.root.id);
    if (order) assert.equal(order.state, f.root.state);
    if (dot) assert.equal(dot.state, f.root.state);
  }
  if (frames[0].route === '#/') {
    homeSeen = true;
    assert.ok(frames.every(f => f.compose[0] === 'Draft retained during a run' && f.compose[1] === 'Keep this goal and focus'));
    assert.equal(new Set(frames.map(f => f.feed)).size, 1, 'Feed filter retained');
    assert.equal(new Set(frames.map(f => f.feedScroll)).size, 1, 'Reading position retained');
    const steps = frames.flatMap(f => f.steps.filter(s => s.id === f.root.id).map(s => s.text));
    ['0 of 2 steps', '1 of 2 steps', '2 of 2 steps'].forEach(label => assert.ok(steps.includes(label), label));
    assert.ok(new Set(frames.map(f => f.chart)).size > 1, 'Activity axis extends with the backend clock');
  } else {
    teamSeen = true;
    assert.equal(new Set(frames.map(f => f.zoom.split('transform:')[1])).size, 1, 'Canvas pan and zoom retained as the graph grows');
    assert.ok(frames.every(f => f.selected === 'agent:writer' && f.tab === 'events'));
    const growing = new Map();
    frames.forEach(f => f.bars.filter(b => b.running).forEach(b => {
      if (!growing.has(b.id)) growing.set(b.id, []);
      growing.get(b.id).push(b);
      assert.ok(f.stripes > 0, 'Running timeline has its striped end');
    }));
    assert.ok([...growing.values()].some(bars => new Set(bars.map(b => b.end)).size > 1), 'Backend launch duration grows');
    assert.ok([...growing.values()].some(bars => Math.max(...bars.map(b => b.width)) - Math.min(...bars.map(b => b.width)) > 1), 'A running bar visibly grows');
  }
  return {route: frames[0].route, frames: frames.length, maximumHeadingShift: maximumShift, receiptMs: receipt.ms, height: frames.at(-1).height};
});
assert.ok(homeSeen && teamSeen);
console.log(JSON.stringify({passed: true, results}));
