/* Verify real 500 ms recordings from the local stand-in order and Board. */
'use strict';
const assert = require('node:assert/strict');
const fs = require('node:fs');
const [orderPath, boardPath, reducedPath] = process.argv.slice(2);
const read = path => JSON.parse(fs.readFileSync(path, 'utf8'));
const order = read(orderPath), frames = order.frames;
assert.ok(frames.length >= 25, 'Observe the entire run');
assert.equal(frames.at(-1).state, 'SUCCEEDED');
const positions = new Map(), rowHeights = new Map(), elapsed = new Map(), widths = new Map();
let lastTicks, tickChanges = [], maximumShift = 0;
for (const f of frames) {
  for (const node of f.flow) {
    const before = positions.get(node.id);
    if (before) maximumShift = Math.max(maximumShift, Math.abs(node.x-before.x), Math.abs(node.y-before.y));
    positions.set(node.id, node);
    const working = f.doc.launches.some(l => l.order === node.id && l.state === 'running');
    assert.equal(node.working, working, 'Ring agrees with server launch state');
    if (working) assert.equal(node.stroke, 'rgb(29, 95, 208)');
  }
  for (const edge of f.edges.filter(e => e.working)) assert.equal(edge.stroke, 'rgb(29, 95, 208)');
  for (const row of f.launches) {
    const before = rowHeights.get(row.id);
    if (before) assert.ok(Math.abs(row.h-before) <= 1, 'Launch height stays fixed');
    rowHeights.set(row.id, row.h);
    const launch = f.doc.launches.find(l => String(l.n || l.launch) === row.id);
    if (launch.state === 'running') {
      assert.ok(Math.abs(Number(row.seconds) - (f.doc.updated-launch.started)) <= .11, 'Elapsed seconds use server start time');
      const series = elapsed.get(row.id) || []; series.push(Number(row.seconds)); elapsed.set(row.id, series);
    }
  }
  for (const bar of f.bars.filter(b => b.running)) {
    const key = bar.id + '/' + f.ticks.join(','), series = widths.get(key) || [];
    series.push(bar.width); widths.set(key, series);
  }
  if (f.ticks.length && lastTicks && JSON.stringify(f.ticks) !== lastTicks) tickChanges.push(f.ms);
  if (f.ticks.length) lastTicks = JSON.stringify(f.ticks);
}
assert.ok(maximumShift <= 2, 'Flow nodes remain in place');
assert.ok([...elapsed.values()].some(s => Math.max(...s)-Math.min(...s) >= 2), 'Running seconds visibly advance');
assert.ok([...widths.values()].some(s => Math.max(...s)-Math.min(...s) >= 10), 'Running timeline grows within a fixed scale');
for (let i=1;i<tickChanges.length;i++) assert.ok(tickChanges[i]-tickChanges[i-1] >= 4900, 'Tick changes are spaced at least five seconds apart');
for (let i=1;i<frames.length;i++) assert.deepEqual(frames[i].launches.slice(0,frames[i-1].launches.length).map(r=>r.id),frames[i-1].launches.map(r=>r.id),'Launch rows append');
const files = frames.at(-1).files;
assert.equal(files.length, 2); assert.ok(files.every(f => f.accepted === 'true'));
const arrivals = frames.at(-1).arrivals.filter(a => a.file);
assert.equal(arrivals.length, 2, 'Each handed-in file enters once');
assert.equal(new Set(arrivals.map(a => a.file)).size,2);
assert.ok(arrivals.every(a => a.duration === '0.15s'));
assert.equal(order.restored.after.scroll, order.restored.before.scroll);
assert.ok(order.restored.before.key, 'Exercise a real expanded list');
assert.equal(order.restored.after.expanded,'true');
function boardCheck(record, reduced) {
  const columns=[];
  for (const f of record.frames) {
    const heights=f.columns.map(c=>c.height);
    assert.ok(Math.max(...heights)-Math.min(...heights)<=1,'Board columns are equal height');
    const column=f.columns.find(c=>c.orders.includes(record.order.id))?.column;
    if(column&&columns.at(-1)!==column)columns.push(column);
  }
  assert.deepEqual(columns,['running','done']);
  const moves=record.frames.at(-1).moves;
  assert.equal(moves.length,reduced?0:1);
  if(!reduced)assert.equal(moves[0].duration,'0.16s');
}
boardCheck(read(boardPath),false);
if(reducedPath)boardCheck(read(reducedPath),true);
console.log(JSON.stringify({passed:true,frames:frames.length,maximumShift,rowHeights:[...rowHeights.values()],tickChanges,files:arrivals.length,restored:order.restored,reduced:!!reducedPath}));
