/* Rendered surface regression; Pass 35 keeps dimmed text opaque and AA. */
(async function () {
  'use strict';
  const measureBox = node => (node.getBoundingClientRect());
  const check = (ok, message) => { if (!ok) throw Error(message); };
  const pause = ms => new Promise(resolve => setTimeout(() => resolve(), ms));
  check(location.hostname === '127.0.0.1' && innerWidth === 1280, 'Local desktop fixture');
  const cards = view => [...view.querySelectorAll('*')].filter(e => {
    if (!e.getClientRects().length || e.closest('[hidden]') || e.matches('a,button,input,select,textarea,[role=button]')) return false;
    const s = getComputedStyle(e), r = measureBox(e);
    let left = r.left, right = r.right, top = r.top, bottom = r.bottom;
    // A row outside its scroll window does not contribute a painted surface.
    for (let p = e.parentElement; p && p !== document.body; p = p.parentElement) {
      const style=getComputedStyle(p), clip = measureBox(p);
      if (style.overflowX !== 'visible') { left = Math.max(left, clip.left); right = Math.min(right, clip.right); }
      if (style.overflowY !== 'visible') { top = Math.max(top, clip.top); bottom = Math.min(bottom, clip.bottom); }
    }
    if (right <= left || bottom <= top) return false;
    return r.width >= 160 && r.height >= 60 && parseFloat(s.borderTopLeftRadius) >= 8 &&
      (s.backgroundColor !== 'rgba(0, 0, 0, 0)' || s.backgroundImage !== 'none' || parseFloat(s.borderTopWidth) > 0);
  });
  const rows = [];
  for (const [route, minimum] of [['#/', 31], ['#/team', 43]]) {
    location.hash = route; await pause(1200);
    const view = document.querySelector('[data-view]:not([hidden])'), count = cards(view).length;
    check(count >= minimum, route + ' lost a rendered surface: ' + count);
    rows.push({route, cards: count});
  }
  const area = document.querySelector('.canvas-workarea');
  check(getComputedStyle(area).backgroundImage !== 'none', 'Canvas rail/stage backing remains painted');
  const state = await fetch('/poll?since=0').then(r => r.json()), seat = state.team.seats.find(s => s.actor !== state.team.lead);
  check(seat, 'Fixture has a worker to focus');
  const buttons = () => [...document.querySelectorAll('[data-view=team] button[data-select-seat]')];
  check(buttons().length >= 3 && buttons().every(e => !e.closest('svg')), 'HTML focus buttons exist for every seat');
  const key = seat.id || seat.actor;
  const button = () => buttons().find(e => e.dataset.selectSeat === key);
  button().click(); await pause(300);
  const focused = () => {
    const view = document.querySelector('[data-view=team]'), dim = [...view.querySelectorAll('[data-dim]')];
    check(dim.length > 10, 'Other seats, cards and edges are dimmed');
    check(buttons().filter(e => e.getAttribute('aria-pressed') === 'true').length === 1, 'Exactly one focus button is pressed');
    const nodes = [...view.querySelectorAll('[data-canvas-node]')];
    check(nodes.some(e => e.hasAttribute('data-dim')) && nodes.some(e => !e.hasAttribute('data-dim')), 'Some canvas nodes dim');
    for (const e of view.querySelectorAll('[data-dim] :is(img,path,rect,circle,line,[data-timeline-bar])')) {
      check(Number(getComputedStyle(e).opacity) > 0 && Number(getComputedStyle(e).opacity) <= .6, 'Drawings fade');
    }
    for (const e of dim.filter(e => e.querySelector('text,span,strong,a'))) check(Number(getComputedStyle(e).opacity) === 1, 'Text containers stay opaque');
    for (const key of ['org-node','timeline-row','handoff-seat','gantt-row','seat-reference']) {
      view.querySelectorAll('[data-' + key + ']').forEach(e => check(e.hasAttribute('data-dim') === (e.getAttribute('data-' + key) !== seat.actor), key + ' follows focus'));
    }
    view.querySelectorAll('[data-seat]').forEach(e => check(e.hasAttribute('data-dim') === (e.dataset.actor !== seat.actor), 'Seat cards follow focus'));
    for (const edge of view.querySelectorAll('[data-org-edge],[data-handoff-edge]')) {
      const actors = [edge.dataset.from, edge.dataset.to].map(id => { const to = state.state.state.orders[id]?.to || id; return state.team.seats.find(s => s.actor === to || s.team === to)?.actor || to; });
      check(edge.hasAttribute('data-dim') === !actors.includes(seat.actor), 'Unrelated edge follows focus');
    }
    check(Number(getComputedStyle(view.querySelector('[data-org-node="' + seat.actor + '"]')).opacity) === 1, 'Selected seat stays opaque');
    return dim.length;
  };
  const before = focused(), poll = Number(document.documentElement.dataset.poll);
  for (let i = 0; i < 80 && Number(document.documentElement.dataset.poll) < poll + 2; i++) await pause(100);
  check(Number(document.documentElement.dataset.poll) >= poll + 2, 'Two actual polls arrived');
  const after = focused(); check(after === before, 'Dimming survives polling');
  button().click(); await pause(300);
  check(!document.querySelector('[data-view=team] [data-dim]') && buttons().every(e => e.getAttribute('aria-pressed') === 'false'), 'Pressing again clears dimming and pressed state');
  button().click(); await pause(300);
