/* Local stand-in rehearsal: the recovery action prepares, then submits, a new
   order with the original title and goal. Never sends until Submit is pressed. */
(async function () {
  if(location.hostname!=='127.0.0.1')throw new Error('Local rehearsal only');
  const sleep=ms=>new Promise(r=>setTimeout(r,ms)), raw=fetch.bind(window);
  const before=await(await raw('/poll?since=0')).json();
  const original=Object.values(before.history.days).flatMap(d=>d.orders).find(o=>o.problem?.needs_attention&&o.problem.kind!=='budget');
  if(!original)throw new Error('Need a failed rehearsal order');
  location.hash='#/order/'+original.run+'/'+original.id;await sleep(700);
  const reason=document.querySelector('[data-order-problem] [data-problem-reason]');
  if(reason.title!==original.problem.reason)throw new Error('Header lost the judge reason');
  document.querySelector('[data-retry-order]').click();await sleep(500);
  const form=document.querySelector('#compose-form'),title=document.querySelector('#compose-title'),goal=document.querySelector('#compose-goal');
  if(location.hash!=='#/'||title.value!==original.title||goal.value!==original.goal)throw new Error('Recovery failed to prefill');
  const prepared=await(await raw('/poll?since=0')).json();
  if(Object.keys(prepared.state.state.orders).length!==Object.keys(before.state.state.orders).length)throw new Error('Prefill unexpectedly sent');
  form.requestSubmit();await sleep(900);
  const after=await(await raw('/poll?since=0')).json();
  const issued=Object.values(after.state.state.orders).find(o=>!o.parent&&!before.state.state.orders[o.id]);
  if(!issued||issued.title!==original.title||issued.goal!==original.goal||issued.id===original.id)throw new Error('New order was not accepted by backend');
  return {original:original.id,issued:issued.id,title:issued.title,goal:issued.goal,prefillOnly:true,backendAccepted:true};
}())
