/* Evaluate on the local stand-in page at 1280 x 900 after seeding orders.
 * Semantic colour assertions: no arbitrary distinct-colour quota. */
(async function () {
  'use strict';
  const check=(ok,message)=>{if(!ok)throw Error(message);};
  location.hash='#/team';await new Promise(resolve=>setTimeout(resolve,1200));
  const view=document.querySelector('[data-view="team"]');
  const ink=token=>{const probe=document.createElement('span');probe.style.color='var('+token+')';view.appendChild(probe);const colour=getComputedStyle(probe).color;probe.remove();return colour;};
  const expected={SUCCEEDED:'--ok',running:'--run',attention:'--attention',FAILED:'--bad',planned:'--wait'};
  const legend=view.querySelector('[data-timeline-legend]');check(legend,'Timeline explains the state colours');
  for(const [state,token] of Object.entries(expected)){
    const label=legend.querySelector('[data-state="'+state+'"]');
    check(label&&getComputedStyle(label).color===ink(token),state+' uses its state ink');
  }
  for(const label of view.querySelectorAll('[data-canvas-list-state]')){
    const node=view.querySelector('[data-canvas-node="'+label.dataset.canvasListState+'"] .badge');
    check(node&&label.textContent===node.textContent&&getComputedStyle(label).color===getComputedStyle(node).color,'List and canvas use the same state word and colour');
  }
  for(const label of view.querySelectorAll('[data-seat-state]')){
    const style=getComputedStyle(label),colour=label.namespaceURI.includes('svg')?style.fill:style.color;
    check(colour===ink(label.textContent==='Working'?'--run':'--wait'),'Seat state ink');
  }
  check(getComputedStyle(view.querySelector('h2')).color===ink('--ink-92'),'Primary heading ink');
  check(getComputedStyle(view.querySelector('[data-canvas-list] .seat-chip')).color===ink('--ink-2'),'Secondary seat name ink');
  check(getComputedStyle(view.querySelector('.eyebrow')).color===ink('--ink-3'),'Muted meta ink');
  check(getComputedStyle(view.querySelector('.seat-now a')).color===ink('--accent'),'Order link ink');
  check(document.documentElement.scrollHeight<=4200,'Team height stays within 4200 px');
  check(document.documentElement.scrollWidth===1280,'No sideways scrolling');
  return {passed:true,height:document.documentElement.scrollHeight,states:Object.keys(expected)};
}());
