/* Run in a 1280 x 900 local page after three two-step orders, proposals and a retry. */
(async function () {
  'use strict';
  const assert = (ok, message) => { if (!ok) throw new Error(message); };
  assert(location.hostname === '127.0.0.1' && innerWidth === 1280, 'Local desktop rehearsal only');
  const pause = ms => new Promise(r => setTimeout(r, ms));
  const visit = async route => { location.hash = route; await pause(950); };
  const original = location.hash, animations = [], result = {views:[], animations:{}};
  const record = event => animations.push({name:event.animationName, row:event.target.getAttribute('data-file') || event.target.getAttribute('class')});
  const stopRecording = document.removeEventListener.bind(document, 'animationstart', record);
  try {
    await visit('#/'); document.addEventListener('animationstart',record);
    for (const filter of ['failed','all']) { document.querySelector('[data-order-filter="'+filter+'"]').click(); await pause(200); }
    result.animations.orders=animations.splice(0);
    for(const filter of ['team:lead','all']) { document.querySelector('[data-feed-filter="'+filter+'"]')?.click(); await pause(200); }
    result.animations.feed=animations.splice(0);
    const poll=Number(document.documentElement.dataset.poll);
    while(Number(document.documentElement.dataset.poll)<poll+3)await pause(150);
    result.animations.polls=animations.splice(0);
    await visit('#/team'); animations.length=0;
    for(const tab of ['events','files','timeline']) {document.querySelector('[data-canvas-tab="'+tab+'"]').click();await pause(200);}
    result.animations.tabs=animations.splice(0);
    for(const [action,events] of Object.entries(result.animations)) assert(events.length===0,action+' replays animations');
    stopRecording();
    const history=await(await fetch('/history')).json(),roots=Object.values(history.days).flatMap(d=>d.orders).filter(o=>o.run===history.live_run);
    const orderRoute='#/order/'+history.live_run+'/'+roots[0].id;
    const selectors='.card,.stat,.summary-group,.ledger-group,.home-file,.file,.seat-run,.seat-launch,.home-entry,.week-day,.day-cell,.seat-reference-list > div,#backend,#run-activity';
    for(const route of ['#/','#/team',orderRoute,'#/board','#/files','#/ledger','#/library','#/calendar','#/day/'+history.today,'#/help']) {
      await visit(route); const view=document.querySelector('[data-view]:not([hidden])');
      const boxes=[...view.querySelectorAll(selectors),document.querySelector('#backend'),document.querySelector('#run-activity')].filter(e=>e.getClientRects().length);
      const without=boxes.filter(e=>getComputedStyle(e).boxShadow==='none').map(e=>e.className);
      assert(without.length===0,route+' has shadowless boxes: '+without.join(','));
      const height=document.documentElement.scrollHeight;
      if(roots.length===3 && route==='#/')assert(height<=3400,'Home too tall: '+height);
      if(roots.length===3 && route==='#/team')assert(height<=4200,'Team too tall: '+height);
      result.views.push({route,height,withShadow:boxes.length-without.length,withoutShadow:without.length});
    }
    await visit('#/');document.querySelector('[data-home-seat] [data-seat-open]').dispatchEvent(new MouseEvent('click',{bubbles:true}));await pause(150);
    assert(getComputedStyle(document.querySelector('#seat-drawer')).boxShadow!=='none','Floating drawer needs elevation');
    document.dispatchEvent(
    new KeyboardEvent('keydown',{key:'Escape',bubbles:true}));
    return {passed:true,...result};
  } finally {stopRecording();await visit(original);}
}());
