  };
  const nested = [...home.querySelectorAll('*')].filter(e => visible(e) && !e.matches('input,textarea,select') && boxed(e) && [...home.querySelectorAll('*')].some(parent => parent !== e && parent.contains(e) && boxed(parent)));
  check(nested.length === 0, 'Zero nested bordered boxes on Home, except inputs');
  const line = home.querySelector('[data-chart-line]');
  if (line) {
    check(getComputedStyle(line).strokeWidth === '2px', 'Activity line is 2px');
    const plot = line.closest('svg'), grid = [...plot.querySelectorAll('.chart-grid')];
    const bounds = measureBox(line), frame = measureBox(plot);
    check(bounds.width >= frame.width * .9 && bounds.height >= 110 && bounds.height <= 130, 'Plot spans inner card width and 110–130px in height');
    plot.querySelectorAll('.axis-label').forEach(label => check(getComputedStyle(label).fontSize === '12px' && Math.abs(label.getScreenCTM().d - 1) < .001, 'Axis labels stay 12 screen pixels'));
    check(grid.filter(p => / H/.test(p.getAttribute('d'))).length === 3, 'Three horizontal grid lines');
    check(grid.filter(p => !p.hasAttribute('data-axis-tick')).every(p => getComputedStyle(p).strokeDasharray !== 'none'), 'Grid is dotted');
    const stops = plot.querySelector('linearGradient').querySelectorAll('stop');
    check(stops[0].getAttribute('stop-opacity') === '0.25' && stops[1].getAttribute('stop-opacity') === '0', 'Area fades from 25% to clear');
