#!/usr/bin/env python3
"""Public board records and the Node mapping run in CI without optional assets."""
import os
from pathlib import Path
import shutil
import subprocess
import sys
import time
import unittest

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / 'cockpit'))
import history as H


class Board(unittest.TestCase):
    def test_mapping(self):
        if not shutil.which('node'):
            self.skipTest('Node is unavailable')
        subprocess.run(['node', str(ROOT / 'tests' / 'board_mapping.js')], check=True)

    def test_all_orders_issue_numbers_ask_answers_and_backend_dates(self):
        previous = os.environ.get('TZ')
        self.addCleanup(self.restore_zone, previous)
        os.environ['TZ'] = 'Pacific/Kiritimati'
        time.tzset()
        t = 1893492000
        orders = {'root': {'id': 'root', 'title': 'Root', 'state': 'PENDING'},
                  'child': {'id': 'child', 'title': 'Child', 'parent': 'root', 'state': 'SUCCEEDED'}}
        events = [dict(kind='org.set', t=t), dict(kind='order.issued', t=t, body=orders['root']),
                  dict(kind='order.issued', t=t + 1, body=orders['child']),
                  dict(kind='lease.granted', t=t + 2, order='child', by='agent:writer'),
                  dict(kind='order.failed', t=t + 3, order='child', retry=True),
                  dict(kind='ask.raised', t=t + 4, about='root', ask='q'),
                  dict(kind='ask.answered', t=t + 86400, ask='q'),
                  dict(kind='order.succeeded', t=t + 5, order='child')]
        record = {'orders': orders, 'events': events, 'tops': {'root': 'root', 'child': 'root'}}
        root, child = H.board_records(record, 'run')
        self.assertEqual((root['number'], child['number']), (1, 2))
        self.assertEqual(child['top_title'], 'Root')
        self.assertEqual(child['last_holder'], 'agent:writer')
        self.assertTrue(root['issued_at'].endswith('+14:00'))
        self.assertEqual(root['changed_day'], H.day(t + 86400))
        self.assertEqual(child['changed_day'], H.day(t + 5))
        self.assertIsNone(root['ended_at'])
        self.assertEqual(child['ended_at'], H.wall_stamp(t + 5))
        self.assertNotEqual(root['issued_at'][:10], time.strftime('%Y-%m-%d', time.gmtime(t)))

    @staticmethod
    def restore_zone(previous):
        if previous is None:
            os.environ.pop('TZ', None)
        else:
            os.environ['TZ'] = previous
        time.tzset()


if __name__ == '__main__':
    unittest.main()
