#!/usr/bin/env python3
"""Calendar endpoints and stand-in runs without sockets, a browser, or a model."""
import concurrent.futures
import datetime
import io
import json
import os
import shutil
import sys
import tempfile
import time
import unittest
from email.message import Message
from unittest import mock
from urllib.parse import quote

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
sys.path.insert(0, os.path.join(ROOT, 'cockpit'))
sys.path.insert(0, HERE)                                   # test_cockpit, also when the script folder is not on the path (python -I)

import cli
import history
import live
import planning
import serve
from test_cockpit import TEAM, FAKE


class MemoryServer(serve.Server):
    """Use the production handlers and writer; no listening socket or HTTP thread."""
    def __init__(self, gate, run, port, clock, quiet=True):
        self.gate, self.run, self.clock, self.quiet = gate, run, clock, quiet
        self.server_address = ('127.0.0.1', port)
        self.origins = {'http://127.0.0.1:%d' % port}
        self.writer = cli.Writer(run, {'mode': 'test'})

    def server_close(self):
        self.writer.close()


def request(instance, method, path, body=None, origin=None):
    handler = serve.Handler.__new__(serve.Handler)
    handler.server, handler.path = instance.srv, path
    handler.request_version, handler.command, handler.requestline = 'HTTP/1.1', method, method + ' ' + path + ' HTTP/1.1'
    handler.headers = Message()
    raw = json.dumps(body).encode() if body is not None else b''
    handler.headers['Content-Length'] = str(len(raw))
    handler.headers['Host'] = '127.0.0.1:0'
    if origin:
        handler.headers['Origin'] = origin
    handler.rfile, handler.wfile = io.BytesIO(raw), io.BytesIO()
    with instance.gate:
        getattr(handler, 'do_' + method)()
    head, data = handler.wfile.getvalue().split(b'\r\n\r\n', 1)
    return int(head.split()[1]), json.loads(data)


class Calendar(unittest.TestCase):
    def setUp(self):
        # Runs include a shared library, which must never live in the source repository.
        self.tmp = tempfile.mkdtemp(prefix='calendar-')
        self.instances = []
        self.addCleanup(self.cleanup)
        self.patch_server = mock.patch.object(serve, 'Server', MemoryServer)
        self.patch_start = mock.patch.object(live.Live, 'start', lambda instance: instance)
        self.patch_server.start()
        self.patch_start.start()
        self.addCleanup(self.patch_server.stop)
        self.addCleanup(self.patch_start.stop)

    def cleanup(self):
        for instance in self.instances:
            instance.srv.server_close()
        shutil.rmtree(self.tmp, ignore_errors=True)

    def start(self, date, team=TEAM, **options):
        for previous in self.instances:
            previous.srv.server_close()
        stamp = time.mktime(time.strptime(date + ' 12:00:00', '%Y-%m-%d %H:%M:%S'))
        instance = serve.start(self.tmp, team, exe=FAKE, offset=stamp - time.time(), every=0.1, pace=0.01, **options)
        self.instances.append(instance)
        return instance

    def get(self, instance, path):
        code, result = request(instance, 'GET', path)
        self.assertEqual(code, 200, result)
        return result

    def plan(self, instance, date='2030-04-12', **kw):
        fields = dict(title='A planned note', goal='Write and review a note.', writes='', budget=6, day=date)
        fields.update(kw)
        return request(instance, 'POST', '/plan', fields)

    def issue(self, instance, oid):
        fields = dict(title='Try ' + oid, goal='Write and review a note.', writes='', budget=6)
        code, result = request(instance, 'POST', '/message', planning.envelope(fields, oid, instance.lead, 'ui-' + oid))
        self.assertEqual((code, result.get('ok')), (200, True), result)

    def complete(self, instance, oid):
        for _ in range(20):
            instance.once()
            if instance.ad.d.snapshot()['orders'][oid]['state'] == 'SUCCEEDED':
                return
        self.fail('stand-in order did not succeed')

    def test_problem_records_share_judge_words_and_do_not_count_automatic_retries(self):
        judge = os.path.join(self.tmp, 'decisions.py')
        with open(judge, 'w', encoding='utf-8') as f:
            f.write("def reads(): return {}\n"
                    "def judged(order): return order['writes']\n"
                    "def judge(order, files, revs):\n"
                    "    if order['id'].endswith('.draft') and ('failed' in order['id'] or max(revs.values(), default=0) == 1):\n"
                    "        return False, 'Add the missing review evidence.'\n"
                    "    return True, 'Checked.'\n")
        instance = self.start('2030-04-10', judge=judge)
        self.issue(instance, 'retry')
        saw_retry = False
        for _ in range(20):
            instance.once()
            doc = self.get(instance, '/order?run=' + os.path.basename(instance.run) + '&id=retry')
            problem = doc['order']['problem']
            if problem and problem['retrying']:
                saw_retry = True
                self.assertFalse(problem['needs_attention'])
            if doc['order']['state'] == 'SUCCEEDED':
                break
        self.assertTrue(saw_retry)
        self.assertTrue(problem['resolved'])
        self.assertEqual(problem['reason'], 'Add the missing review evidence.')
        self.assertEqual(problem['seat']['actor'], 'agent:writer')
        self.assertFalse(problem['needs_attention'])
        self.issue(instance, 'failed')
        for _ in range(20):
            instance.once()
            if instance.ad.d.snapshot()['orders'].get('failed.draft', {}).get('state') in history.FAILED:
                break
        snapshot = self.get(instance, '/poll?since=0')
        summary = next(o for o in snapshot['history']['days']['2030-04-10']['orders'] if o['id'] == 'failed')
        doc = self.get(instance, '/order?run=' + os.path.basename(instance.run) + '&id=failed')
        self.assertTrue(summary['attention'])
        self.assertEqual(summary['problem'], doc['order']['problem'])
        self.assertEqual(summary['problem']['reason'], 'Add the missing review evidence.')
        self.assertEqual(summary['goal'], doc['order']['goal'])
        # Order seat counts cannot silently include another order in the run.
        accepted = sum(s['outcomes']['accepted'] for s in doc['seats'])
        self.assertEqual(accepted, sum(o['state'] == 'SUCCEEDED' for o in doc['nodes']))

    def test_budget_stop_has_a_reason_and_a_stopped_clock_in_poll_and_detail(self):
        instance = self.start('2030-04-10', limit=1)
        self.issue(instance, 'limited')
        for _ in range(12):
            instance.once()
            if instance.guard.halted:
                break
        snapshot = self.get(instance, '/poll?since=0')
        summary = snapshot['history']['days']['2030-04-10']['orders'][0]
        doc = self.get(instance, '/order?run=' + os.path.basename(instance.run) + '&id=limited')
        self.assertEqual((snapshot['team']['launched'], snapshot['team']['limit']), (1, 1))
        self.assertTrue(summary['attention'])
        self.assertEqual(summary['problem']['kind'], 'budget')
        self.assertEqual(summary['problem'], doc['order']['problem'])
        self.assertIn('allowance was used', summary['problem']['reason'])
        self.assertIsNotNone(doc['timing']['stopped'])
        with mock.patch.object(instance.srv.history, 'clock', return_value=doc['updated'] + 5):
            later = self.get(instance, '/order?run=' + os.path.basename(instance.run) + '&id=limited')
        self.assertEqual(later['timing']['seconds'], doc['timing']['seconds'])

    def test_message_orders_must_go_through_the_running_lead(self):
        team = json.loads(json.dumps(TEAM))
        team['lead']['id'] = 'planner'
        instance = self.start('2030-04-10', team)
        envelope = planning.envelope(dict(title='A note', goal='Write a note.', writes='', budget=6),
                                     'through-lead', instance.lead, 'ui-through-lead')
        ledger_path = os.path.join(instance.run, cli.LEDGER)
        with open(ledger_path, 'rb') as f:
            original = f.read()
        with mock.patch.object(instance.srv.writer, 'submit', wraps=instance.srv.writer.submit) as submit:
            for actor in ('agent:writer', 'team:writer', 'team:lead', '', None):
                with self.subTest(actor=actor):
                    envelope['body']['to'] = actor
                    code, result = request(instance, 'POST', '/message', envelope)
                    self.assertEqual((code, result['cli']), (400, 'not-through-lead'))
                    self.assertIn(instance.lead, result['detail'])
                    submit.assert_not_called()
                    with open(ledger_path, 'rb') as f:
                        self.assertEqual(f.read(), original)
            envelope['body']['to'] = instance.lead
            code, result = request(instance, 'POST', '/message', envelope)
            self.assertEqual((code, result['ok']), (200, True))
            submit.assert_called_once()
        self.complete(instance, 'through-lead')
        issued = [e for e in instance.ad.d.log if e['kind'] == 'order.issued']
        self.assertEqual([(e['by'], e['body']['to']) for e in issued],
                         [(live.CEO, instance.lead), (instance.lead, 'team:writer'), (instance.lead, 'team:reviewer')])

    def test_poll_is_one_locked_snapshot_with_a_fresh_launch_clock(self):
        instance = self.start('2030-04-10')
        self.issue(instance, 'watched')
        # The previous cached /team document has not seen this new order yet.
        with mock.patch.object(instance.srv.history, 'summary', wraps=instance.srv.history.summary) as summary:
            original = summary._mock_wraps
            def locked_summary(plans):
                self.assertTrue(instance.gate._is_owned())
                return original(plans)
            summary.side_effect = locked_summary
            first = self.get(instance, '/poll?since=0')
        self.assertEqual(first['team']['order_totals']['orders'], 1)
        order = first['history']['days']['2030-04-10']['orders'][0]
        self.assertEqual(order['state'], first['state']['state']['orders']['watched']['state'])
        self.assertEqual(first['state']['next'], len(instance.ad.d.log))
        self.assertEqual(first['state']['log'], instance.ad.d.log)
        self.assertFalse(first['state']['more'])
        start = instance.now()
        instance.guard.records.append(dict(n=1, order='watched', token='test', launch=1,
                                           agent=instance.lead, started=start, state='running'))
        instance.guard.skew += 3
        running = self.get(instance, '/poll?since=' + str(first['state']['next']))
        self.assertGreaterEqual(running['team']['updated'] - start, 3)
        self.assertIsNone(running['team']['launches'][0]['ended'])
        self.assertEqual(running['state']['log'], [])
        instance.guard.records.clear()
        self.complete(instance, 'watched')
        ended = self.get(instance, '/poll?since=' + str(first['state']['next']))
        self.assertEqual(ended['state']['state']['orders']['watched']['state'], 'SUCCEEDED')
        self.assertEqual(ended['history']['days']['2030-04-10']['orders'][0]['progress'], {'total': 2, 'succeeded': 2})
        self.assertEqual(ended['team']['order_totals']['accepted'], 1)
        self.assertTrue(all(l['state'] == 'ended' for l in ended['team']['launches']))
        self.assertEqual(len(first['state']['log']) + len(ended['state']['log']), ended['state']['next'])
        for invalid in ('-1', 'oops', ''):
            self.assertEqual(request(instance, 'GET', '/poll?since=' + invalid)[0], 400)

    def test_drawing_fields_follow_launches_dispatches_and_the_run_clock(self):
        instance = self.start('2030-04-10')
        first = self.get(instance, '/team')
        self.assertEqual(first['run_started'], instance.ad.d.log[0]['t'])
        self.assertEqual(first['ledger_updated'], instance.ad.d.log[-1]['t'])
        self.assertEqual(first['handoffs'], [])
        self.assertEqual([s['id'] for s in first['seats']], [TEAM['lead']['id']] + [s['id'] for s in TEAM['seats']])
        self.issue(instance, 'draw')
        pending = self.get(instance, '/order?id=draw')
        self.assertIsNone(pending['timing']['ended'])
        self.assertEqual(pending['order']['progress'], {'total': 1, 'succeeded': 0})
        self.assertEqual(pending['timing']['seconds'], pending['updated'] - pending['timing']['started'])
        # A published, still-running record carries a null end, never a guessed one.
        instance.guard.records.append(dict(n=1, order='draw', token='test', launch=1,
                                           agent=instance.lead, started=instance.now(), state='running'))
        instance.board()
        self.assertIsNone(self.get(instance, '/team')['launches'][0]['ended'])
        instance.guard.records.clear()
        self.complete(instance, 'draw')
        team = self.get(instance, '/team')
        self.assertEqual(team['ledger_updated'], instance.ad.d.log[-1]['t'])
        recorded = team['ledger_updated']
        instance.guard.skew += 30
        instance.board()
        self.assertEqual(self.get(instance, '/team')['ledger_updated'], recorded, 'Idle time does not extend the ledger duration')
        doc = self.get(instance, '/order?id=draw')
        self.assertEqual(doc['run_started'], first['run_started'])
        self.assertEqual(doc['order']['progress'], {'total': 2, 'succeeded': 2})
        self.assertTrue(all(c['progress'] == {'total': 1, 'succeeded': 1} for c in doc['children']))
        self.assertEqual([n['progress'] for n in doc['nodes']], [doc['order']['progress']] + [c['progress'] for c in doc['children']])
        summary = self.get(instance, '/history')
        self.assertEqual(summary['days']['2030-04-10']['orders'][0]['progress'], doc['order']['progress'])
        self.assertEqual(summary['week'], ['2030-04-%02d' % i for i in range(8, 15)])
        card = summary['days']['2030-04-10']['orders'][0]
        self.assertEqual(card['steps'], [{k: c[k] for k in ('id', 'title', 'state')} for c in doc['children']])
        self.assertEqual([s['actor'] for s in card['participants']], [s['actor'] for s in team['seats']])
        self.assertEqual([s['slot'] for s in card['participants']], [1, 2, 3])
        self.assertEqual(team['order_totals'], {'orders': 1, 'accepted': 1, 'steps': 2, 'steps_accepted': 2,
                                              'all_accepted': 3, 'sent_back': 0})
        self.assertEqual([s['outcomes'] for s in team['seats']], [{'accepted': 1, 'sent_back': 0}] * 3)
        self.assertEqual([s['outcomes'] for s in doc['seats']], [s['outcomes'] for s in team['seats']])
        for files in (team['files'], doc['files']):
            for file in files:
                receipt = next(e for e in instance.ad.d.log if e['kind'] == 'artifact.rev' and e['key'] == file['path'] and e['rev'] == file['rev'])
                self.assertEqual({k: file[k] for k in ('by', 'at', 'seq')},
                                 {'by': receipt['by'], 'at': receipt['t'], 'seq': receipt['seq']})
        self.assertEqual(len(team['launches']), 3)
        for launch in team['launches']:
            self.assertEqual(launch['ended'], launch['started'] + launch['secs'])
            self.assertGreaterEqual(launch['ended'], launch['started'])
            self.assertGreaterEqual(launch['started'], team['run_started'])
        self.assertEqual(doc['launches'], team['launches'])
        issued = next(e for e in instance.ad.d.log if e['kind'] == 'order.issued' and e['body']['id'] == 'draw')
        ended = next(e for e in instance.ad.d.log if e['kind'] == 'order.succeeded' and e['order'] == 'draw')
        self.assertEqual(doc['timing'], {'started': issued['t'], 'ended': ended['t'], 'seconds': ended['t'] - issued['t']})
        self.assertEqual(team['handoffs'], [
            {'order': c['id'], 'parent': c['parent'], 'from': c['by'], 'to': c['to'], 'title': c['title'],
             'state': c['state'], 'files': [f['path'] for f in doc['files'] if f['order'] == c['id']]}
            for c in doc['children']])
        child = self.get(instance, '/order?id=draw.draft')
        self.assertEqual(child['run_started'], doc['run_started'])
        self.assertEqual([l['order'] for l in child['launches']], ['draw.draft'])
        run = team['run']
        later = self.start('2030-04-12')
        past = self.get(later, '/order?run=' + run + '&id=draw')
        self.assertEqual(past['timing'], doc['timing'])
        with mock.patch.object(later.srv.history, 'clock', return_value=later.now() + 900):
            self.assertEqual(self.get(later, '/order?run=' + run + '&id=draw')['updated'], past['updated'])

    def test_old_launch_timing_is_normalized_without_inventing_missing_dates(self):
        h = history.History(self.tmp, 'current', lambda: 100)
        records = [{'started': 10, 'secs': 2.5, 'state': 'ended'}, {'t0': 12, 't1': 15},
                   {'started': 20, 'state': 'running'}, {'state': 'ended'}]
        with mock.patch.object(h, 'board', return_value={'launches': records}):
            got = h.launches('old')
        self.assertEqual([(l['started'], l['ended']) for l in got], [(10, 12.5), (12, 15), (20, None), (None, None)])
        self.assertNotIn('ended', records[0])
        events = [{'kind': 'order.issued', 'by': 'team:lead', 'body': {'id': 'child', 'parent': 'root'}},
                  {'kind': 'artifact.rev', 'order': 'child', 'key': 'work/a'},
                  {'kind': 'artifact.rev', 'order': 'child', 'key': 'work/a'},
                  {'kind': 'artifact.rev', 'order': 'child', 'key': 'work/b'}]
        self.assertEqual(live.handoffs(events, {'child': {'to': 'team:writer', 'title': 'Child', 'state': 'JUDGING'}})[0]['files'], ['work/a', 'work/b'])

    def test_rejected_message_does_not_tick_an_expired_lease(self):
        instance = self.start('2030-04-10')
        self.issue(instance, 'held')
        code, claim = request(instance, 'POST', '/message', {'v': 'dispatch/1', 'id': 'claim-held', 'from': instance.lead,
                             'to': 'dispatcher', 'kind': 'claim.request', 'basis': instance.srv.writer.d.s.head,
                             'body': {'order': 'held', 'ttl': 1}})
        self.assertEqual((code, claim['ok']), (200, True))
        with open(os.path.join(instance.run, cli.LEDGER), 'rb') as f:
            original = f.read()
        envelope = planning.envelope(dict(title='A note', goal='Write a note.', writes='', budget=6),
                                     'bypass', 'agent:writer', 'ui-bypass')
        with mock.patch.object(instance.srv, 'clock', return_value=instance.now() + 10):
            code, result = request(instance, 'POST', '/message', envelope)
        self.assertEqual((code, result['cli']), (400, 'not-through-lead'))
        with open(os.path.join(instance.run, cli.LEDGER), 'rb') as f:
            self.assertEqual(f.read(), original)
        self.assertEqual(instance.ad.d.snapshot()['orders']['held']['state'], 'LEASED')

    def test_two_dates_past_order_stats_files_and_pinned_models(self):
        first = self.start('2030-04-10')
        self.issue(first, 'first')
        self.complete(first, 'first')
        first_run = os.path.basename(first.run)
        ledger_path = os.path.join(first.run, cli.LEDGER)
        with open(ledger_path, 'rb') as f:
            original = f.read()
        changed_team = json.loads(json.dumps(TEAM))
        changed_team['lead']['id'] = 'planner'
        changed_team['lead']['name'] = 'New planner'
        changed_team['lead']['model'] = 'local/new-model'
        second = self.start('2030-04-11', changed_team)
        self.issue(second, 'second')
        self.complete(second, 'second')
        doc = self.get(second, '/history')
        self.assertEqual(doc['today'], '2030-04-11')
        self.assertEqual(len(doc['runs']), 2)
        self.assertEqual(doc['skipped'], [])
        original_lead = dict(actor='team:lead', name='Lead', model=TEAM['lead']['model'], family='deepseek')
        current_lead = dict(actor='team:planner', name='New planner', model='local/new-model', family='other')
        self.assertEqual(doc['days']['2030-04-10']['orders'][0]['lead'], original_lead)
        self.assertEqual(doc['days']['2030-04-11']['orders'][0]['lead'], current_lead)
        for date, oid in [('2030-04-10', 'first'), ('2030-04-11', 'second')]:
            self.assertEqual([o['id'] for o in doc['days'][date]['orders']], [oid])
            self.assertEqual(doc['days'][date]['stats'], dict(issued=1, succeeded=1, failed=0, launches=3))
        self.assertTrue(first_run.startswith('20300410-'))
        self.assertTrue(all(history.day(e['t']) == '2030-04-10' for e in first.ad.d.log))
        order = self.get(second, '/order?run=' + first_run + '&id=first')
        self.assertFalse(order['live'])
        self.assertEqual(order['lead'], original_lead)
        self.assertEqual(order['order']['by'], live.CEO)
        self.assertEqual([c['by'] for c in order['children']], ['team:lead', 'team:lead'])
        self.assertEqual(order['order']['day'], '2030-04-10')
        self.assertEqual(order['order']['top'], 'first')
        self.assertEqual(len(order['children']), 2)
        self.assertEqual(len(order['nodes']), 3)
        self.assertEqual(len(order['launches']), 3)
        self.assertEqual(len(order['files']), 2)
        self.assertEqual(order['seats'][0]['model'], TEAM['lead']['model'])
        self.assertTrue(all(history.row_order(e) in ('first', 'first.draft', 'first.review') for e in order['ledger']))
        child = self.get(second, '/order?run=' + first_run + '&id=first.review')
        self.assertEqual(child['lead'], original_lead)
        self.assertEqual(child['order']['by'], 'team:lead')
        self.assertEqual((child['order']['parent'], child['order']['top']), ('first', 'first'))
        self.assertEqual(child['children'], [])
        self.assertEqual(len(child['files']), 1)
        file = self.get(second, '/file?run=' + first_run + '&path=first/review/review.md')
        self.assertTrue(file['text'].startswith('# Review'))
        self.assertTrue(self.get(second, '/file?path=second/review/review.md')['text'].startswith('# Review'))
        with open(ledger_path, 'rb') as f:
            self.assertEqual(f.read(), original)
        current = self.get(second, '/order?id=second')
        self.assertEqual(current['lead'], current_lead)
        self.assertEqual(current['order']['by'], live.CEO)
        self.assertEqual([c['by'] for c in current['children']], ['team:planner', 'team:planner'])
        # Older runs have only the board's saved team; it must still be their own lead.
        os.remove(os.path.join(first.run, 'team.json'))
        self.assertEqual(self.get(second, '/order?run=' + first_run + '&id=first')['lead'], original_lead)
        self.assertEqual(self.get(second, '/history')['days']['2030-04-10']['orders'][0]['lead'], original_lead)

    def test_validation_waiting_restart_due_exactly_once_and_cancel(self):
        first = self.start('2030-04-10')
        for date in ('2030-04-09', '2030-04-10', '2030-02-30', '2030-4-12', '', None):
            code, result = self.plan(first, date)
            self.assertEqual((code, result['cli']), (400, 'bad-plan'))
        for fields in ({'title': ' '}, {'goal': ''}, {'budget': -1}, {'budget': True}, {'writes': '../bad/'}):
            self.assertEqual(self.plan(first, **fields)[0], 400)
        code, p = self.plan(first)
        self.assertEqual((code, p['state']), (200, 'waiting'))
        self.assertEqual(request(first, 'POST', '/plan/issue', {'id': p['id']}), (409, {'cli': 'not-due'}))
        for _ in range(3):
            first.once()
        self.assertEqual(first.guard.records, [])
        self.assertEqual(first.ad.d.snapshot()['orders'], {})
        second = self.start('2030-04-11')
        self.assertEqual(self.get(second, '/history')['days']['2030-04-12']['planned'][0]['state'], 'waiting')
        third = self.start('2030-04-12')
        self.assertEqual(self.get(third, '/history')['days']['2030-04-12']['planned'][0]['state'], 'due')
        for _ in range(3):
            third.once()
        self.assertEqual(third.guard.records, [])  # Arrival of the date still launches nothing.
        with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
            results = list(pool.map(lambda _: request(third, 'POST', '/plan/issue', {'id': p['id']}), range(4)))
        self.assertEqual(sorted(code for code, _ in results), [200, 409, 409, 409])
        issued = next(body for code, body in results if code == 200)
        self.assertEqual(issued['state'], 'issued')
        for code, body in results:
            if code == 409:
                self.assertEqual(body, {'cli': 'already-issued', 'run': issued['run'], 'order': issued['order']})
        self.assertEqual(len([e for e in third.ad.d.log if e['kind'] == 'order.issued']), 1)
        self.complete(third, issued['order'])
        fourth = self.start('2030-04-13')
        self.assertEqual(request(fourth, 'POST', '/plan/issue', {'id': p['id']})[0], 409)
        self.assertEqual(fourth.ad.d.snapshot()['orders'], {})
        record = self.get(fourth, '/history')['days']['2030-04-12']['planned'][0]
        self.assertEqual((record['run'], record['order'], record['state']), (issued['run'], issued['order'], 'issued'))
        self.assertEqual(request(fourth, 'POST', '/plan/cancel', {'id': p['id']})[0], 409)
        _, waiting = self.plan(fourth, '2030-04-15')
        self.assertEqual(request(fourth, 'POST', '/plan/cancel', {'id': waiting['id']})[0], 200)
        self.assertEqual(request(fourth, 'POST', '/plan/cancel', {'id': waiting['id']})[0], 409)
        _, due = self.plan(fourth, '2030-04-14')
        fifth = self.start('2030-04-14')
        self.assertEqual(request(fifth, 'POST', '/plan/cancel', {'id': due['id']})[0], 200)
        self.assertEqual(request(fifth, 'POST', '/plan/issue', {'id': due['id']})[0], 409)
        with open(os.path.join(self.tmp, 'planned.jsonl'), encoding='utf-8') as f:
            rows = [json.loads(line) for line in f]
        self.assertEqual([e['kind'] for e in rows].count('planned.issued'), 1)

    def test_bad_run_unknown_order_gate_skipped_and_cache(self):
        instance = self.start('2030-04-10')
        run = os.path.basename(instance.run)
        for bad in ('..', '.', '../escape', 'a/b', '/absolute', 'missing', 'space name', run + '/..'):
            self.assertEqual(request(instance, 'GET', '/order?run=' + quote(bad, safe='') + '&id=x')[0], 404)
            self.assertEqual(request(instance, 'GET', '/file?run=' + quote(bad, safe='') + '&path=x')[0], 404)
        self.assertEqual(request(instance, 'GET', '/order?run=' + run + '&id=missing')[0], 404)
        for path in ('/history', '/order?run=' + run + '&id=x', '/file?run=' + run + '&path=x'):
            self.assertEqual(request(instance, 'GET', path, origin='http://elsewhere.invalid')[0], 403)
        for path in ('/plan', '/plan/issue', '/plan/cancel'):
            self.assertEqual(request(instance, 'POST', path, {}, origin='http://elsewhere.invalid')[0], 403)
        h = instance.srv.history
        before = h.read(run)
        self.assertIs(h.read(run), before)
        self.issue(instance, 'new')
        self.assertIsNot(h.read(run), before)
        self.assertEqual(len(self.get(instance, '/history')['days']['2030-04-10']['orders']), 1)
        bad = os.path.join(self.tmp, 'broken')
        os.mkdir(bad)
        with open(os.path.join(bad, cli.LEDGER), 'w', encoding='utf-8') as f:
            f.write('broken\n')
        os.symlink(instance.run, os.path.join(self.tmp, 'linked'))
        self.assertEqual(request(instance, 'GET', '/order?run=linked&id=new')[0], 404)
        skipped = self.get(instance, '/history')['skipped']
        self.assertEqual({r['run'] for r in skipped}, {'broken', 'linked'})
        self.assertTrue(all(r['why'] for r in skipped))
        _, p = self.plan(instance, '2030-04-12')
        next_run = self.start('2030-04-12')
        self.assertEqual(request(next_run, 'POST', '/plan/issue', {'id': p['id']})[0], 200)

    def test_negative_offset_and_failed_top_level_counts(self):
        instance = self.start('2020-02-29')
        self.issue(instance, 'cancelled')
        head = instance.srv.writer.d.s.head
        code, result = request(instance, 'POST', '/message', {'v': 'dispatch/1', 'id': 'cancel-it', 'from': live.CEO, 'to': 'dispatcher', 'kind': 'order.cancel', 'basis': head, 'body': {'order': 'cancelled'}})
        self.assertEqual((code, result['ok']), (200, True))
        self.issue(instance, 'past')
        self.complete(instance, 'past')
        doc = self.get(instance, '/history')
        self.assertEqual(doc['today'], '2020-02-29')
        self.assertEqual(doc['days']['2020-02-29']['stats'], dict(issued=2, succeeded=1, failed=1, launches=3))
        self.assertTrue(all(history.day(e['t']) == '2020-02-29' for e in instance.ad.d.log))
        self.assertTrue(all(history.day(e['started']) == '2020-02-29' for e in instance.guard.records))

    def test_recover_issue_after_interruption_before_plan_receipt(self):
        first = self.start('2030-04-10')
        _, p = self.plan(first, '2030-04-11')
        second = self.start('2030-04-11')
        plan = second.srv.plans.read()[p['id']]
        second.srv.writer.submit(planning.envelope(plan, p['id'], second.lead, p['id']), second.now())
        third = self.start('2030-04-12')
        code, body = request(third, 'POST', '/plan/issue', {'id': p['id']})
        self.assertEqual((code, body['cli'], body['run']), (409, 'already-issued', os.path.basename(second.run)))
        self.assertEqual(third.ad.d.snapshot()['orders'], {})
        self.assertEqual(third.srv.plans.read()[p['id']]['state'], 'issued')

    def test_overdue_plan_stays_on_its_day_and_order_uses_issue_day(self):
        first = self.start('2030-04-10')
        _, p = self.plan(first, '2030-04-11')
        second = self.start('2030-04-13')
        code, result = request(second, 'POST', '/plan/issue', {'id': p['id']})
        self.assertEqual(code, 200)
        doc = self.get(second, '/history')
        self.assertEqual(doc['days']['2030-04-11']['planned'][0]['state'], 'issued')
        self.assertEqual(doc['days']['2030-04-11']['orders'], [])
        self.assertEqual(doc['days']['2030-04-13']['orders'][0]['id'], result['order'])
        self.assertEqual(doc['days']['2030-04-13']['stats']['issued'], 1)

    def test_local_calendar_date(self):
        if not hasattr(time, 'tzset'):
            self.skipTest('tzset is unavailable')
        previous = os.environ.get('TZ')
        try:
            os.environ['TZ'] = 'EST5'
            time.tzset()
            stamp = datetime.datetime(2030, 4, 11, 2, tzinfo=datetime.timezone.utc).timestamp()
            self.assertEqual(history.day(stamp), '2030-04-10')
        finally:
            if previous is None:
                os.environ.pop('TZ', None)
            else:
                os.environ['TZ'] = previous
            time.tzset()


if __name__ == '__main__':
    unittest.main()
