#!/usr/bin/env python3
"""The cockpit end to end, with a stand-in for the opencode executable (tests/fake_bin/opencode): no model, no cost."""
import json
import re
import os
import shutil
import subprocess
import sys
import tempfile
import time
import unittest
from unittest import mock
import urllib.error
import urllib.request

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
sys.path.insert(0, os.path.join(ROOT, 'cockpit'))

import gitws                        # noqa: E402
import live as L                    # noqa: E402
import opencode_agent as A          # noqa: E402
import serve                        # noqa: E402

FAKE = os.path.join(HERE, 'fake_bin', 'opencode')
MODELS = ['deepseek/deepseek-chat', 'moonshotai/kimi-k2', 'alibaba/qwen3-coder-plus']
TEAM = {'lead': {'id': 'lead', 'name': 'Lead', 'model': MODELS[0]},
        'seats': [{'id': 'writer', 'name': 'Writer', 'model': MODELS[1]}, {'id': 'reviewer', 'name': 'Reviewer', 'model': MODELS[2]}],
        'pass_env': ['FAKE_OPENCODE_SLEEP'], 'permission': {}}


def until(test, secs=30.0, every=0.05):
    end = time.time() + secs
    while time.time() < end:
        if test():
            return True
        time.sleep(every)
    return bool(test())


class Base(unittest.TestCase):
    def setUp(self):
        self.tmp, self.lives, self.n = tempfile.mkdtemp(prefix='cockpit-'), [], 0
        self.addCleanup(self.stop)

    def stop(self):
        for l in self.lives:
            l.close(20)
        shutil.rmtree(self.tmp, ignore_errors=True)

    def live(self, **kw):
        kw = dict(dict(exe=FAKE, every=0.1, pace=0.05, wall=30), **kw)
        l = serve.start(os.path.join(self.tmp, 'runs%d' % len(self.lives)), TEAM, **kw)
        self.lives.append(l)
        return l

    def get(self, l, path, origin=None):
        rq = urllib.request.Request(l.url + path, headers={'Origin': origin} if origin else {})
        try:
            with urllib.request.urlopen(rq, timeout=30) as r:
                return r.status, r.headers.get('Content-Type'), r.read()
        except urllib.error.HTTPError as e:
            return e.code, e.headers.get('Content-Type'), e.read()

    def post(self, l, body, origin=None):
        self.n += 1
        m = gitws.msg('h%05d' % self.n, L.CEO, 'order.issue', body)
        rq = urllib.request.Request(l.url + '/message', data=json.dumps(m).encode('utf-8'), headers={'content-type': 'application/json', 'Origin': origin or l.url})
        try:
            with urllib.request.urlopen(rq, timeout=30) as r:
                return r.status, json.load(r)
        except urllib.error.HTTPError as e:
            return e.code, json.load(e)

    def issue(self, l, oid='t1', budget=6):
        code, r = self.post(l, {'id': oid, 'title': 'Try ' + oid, 'goal': 'Write a short note, then review it.', 'to': l.lead, 'writes': [oid + '/'], 'budget': budget,
                                'accept': {'judge': L.JUDGE, 'criteria': 'files are handed in'}})
        self.assertEqual((code, r.get('ok')), (200, True), r)

    def states(self, l):
        with l.gate:
            return {k: o['state'] for k, o in l.ad.d.snapshot()['orders'].items()}

    def tagged(self, l):
        git = lambda *a: subprocess.run(['git', '--git-dir', os.path.join(l.run, 'repo.git')] + list(a), capture_output=True).stdout.decode()
        tags = git('for-each-ref', '--format=%(refname)', 'refs/tags/accepted').split()
        return {n: git('show', '%s:%s' % (t, n)) for t in tags for n in git('ls-tree', '-r', '--name-only', t).splitlines()}


class EndToEnd(Base):
    def test_one_order_is_cut_by_the_lead_and_done_by_two_other_models(self):
        l = self.live()
        self.issue(l)
        self.assertTrue(until(lambda: self.states(l) == {'t1': 'SUCCEEDED', 't1.draft': 'SUCCEEDED', 't1.review': 'SUCCEEDED'}), self.states(l))
        with l.gate:
            rows, recs = list(l.ad.d.log), [dict(r) for r in l.guard.records]
        self.assertEqual([(r['by'], r['body']['id'], r['body']['to']) for r in rows if r['kind'] == 'order.issued'],
                         [(L.CEO, 't1', 'team:lead'), ('team:lead', 't1.draft', 'team:writer'), ('team:lead', 't1.review', 'team:reviewer')])
        self.assertEqual([(r['agent'], r['seat'], r['order'], r['model']) for r in recs],
                         [('team:lead', 'planner', 't1', MODELS[0]), ('agent:writer', 'worker', 't1.draft', MODELS[1]), ('agent:reviewer', 'worker', 't1.review', MODELS[2])])
        for r, model in zip(recs, MODELS):               # the only command ever started: opencode run --format json ... -m <the seat's model>
            self.assertEqual((os.path.basename(r['argv'][0]), r['argv'][1:6], r['argv'][6], r['argv'][-1]), ('opencode', ['run', '--format', 'json', '-m', model], '--title', '<prompt>'))
            self.assertEqual((r['state'], r['rc'], r['outside_box']), ('ended', 0, [f for f in r['outside_box'] if f in L.OWN]))
        self.assertEqual([(r['by'], r['order']) for r in rows if r['kind'] == 'order.succeeded'], [(L.JUDGE, 't1.draft'), (L.JUDGE, 't1.review'), (L.JUDGE, 't1')])
        files = self.tagged(l)
        self.assertEqual(sorted(files), ['t1/draft/notes.md', 't1/review/review.md'])
        self.assertTrue(all(v.strip() for v in files.values()))
        self.assertEqual((l.guard.halted, sum(l.guard.n.values())), (None, 3))

    def test_the_team_endpoint_says_which_model_family_runs_which_seat_and_what_was_handed_in(self):
        l = self.live()
        self.issue(l)
        self.assertTrue(until(lambda: self.states(l).get('t1') == 'SUCCEEDED'), self.states(l))
        self.assertTrue(until(lambda: len([f for f in json.loads(self.get(l, '/team')[2])['files'] if f['accepted']]) == 2, 10))
        code, kind, raw = self.get(l, '/team')
        doc = json.loads(raw)
        self.assertEqual((code, kind), (200, 'application/json; charset=utf-8'))
        self.assertEqual([(s['actor'], s['family'], s['role']) for s in doc['seats']], [('team:lead', 'deepseek', 'lead'), ('agent:writer', 'kimi', 'worker'), ('agent:reviewer', 'qwen', 'worker')])
        self.assertEqual((doc['state'], doc['launched'], doc['limit']), ('running', 3, A.MAX_TOTAL))
        self.assertEqual([(f['path'], f['order'], f['accepted']) for f in doc['files']], [('t1/draft/notes.md', 't1.draft', True), ('t1/review/review.md', 't1.review', True)])
        self.assertEqual([(x['outcome'], x['seen']['steps'] >= 1) for x in doc['launches']], [('planned', True), ('submitted', True), ('submitted', True)])
        code, _, raw = self.get(l, '/file?path=t1/review/review.md')
        self.assertEqual((code, json.loads(raw)['text'].splitlines()[0]), (200, '# Review'))

    def test_an_agent_gets_a_clean_environment(self):
        os.environ['COCKPIT_TEST_SECRET'] = 'x'
        self.addCleanup(os.environ.pop, 'COCKPIT_TEST_SECRET')
        l = self.live()
        self.issue(l)
        self.assertTrue(until(lambda: self.states(l).get('t1') == 'SUCCEEDED'), self.states(l))
        with open(os.path.join(l.run, 'logs', '01-t1.err'), encoding='utf-8') as f:
            names = f.read().split()
        self.assertIn('OPENCODE_CONFIG_CONTENT', names)
        self.assertIn('OPENCODE_DISABLE_AUTOUPDATE', names)
        self.assertNotIn('COCKPIT_TEST_SECRET', names)

    def test_the_launch_limit_holds_and_nothing_more_is_started(self):
        l = self.live(limit=1)
        self.issue(l)
        self.assertTrue(until(lambda: l.guard.halted is not None), self.states(l))
        time.sleep(0.5)
        self.assertEqual(sum(l.guard.n.values()), 1)
        doc = json.loads(self.get(l, '/team')[2])
        self.assertEqual((doc['state'], doc['launched'], len(doc['held']) >= 1), ('halted', 1, True))
        self.assertNotIn('SUCCEEDED', (self.states(l)['t1.draft'], self.states(l)['t1']))

    def test_a_process_past_the_wall_clock_is_ended_and_what_it_left_is_not_taken(self):
        os.environ['FAKE_OPENCODE_SLEEP'] = '30'
        self.addCleanup(os.environ.pop, 'FAKE_OPENCODE_SLEEP')
        l = self.live(wall=1, limit=1)
        self.issue(l)
        self.assertTrue(until(lambda: [r['state'] for r in l.guard.records] == ['killed'], 30), [dict(r) for r in l.guard.records])
        self.assertTrue(until(lambda: self.states(l) != {} and 't1.draft' not in self.states(l), 5))
        self.assertEqual(self.tagged(l), {})


class Door(Base):
    def test_optional_ui_files_share_the_pro_gate_and_stay_inside_ui(self):
        l = self.live()
        private = os.path.join(self.tmp, 'optional')
        ui = os.path.join(private, 'ui')
        os.makedirs(ui)
        with mock.patch.object(serve.R, 'PRO', private), mock.patch.object(serve.R, 'available', return_value=False):
            # An absent layer leaves the normal page intact, even without a pro build.
            self.assertNotIn(b'href="/pro/ui/tokens.css"', self.get(l, '/')[2])
            self.assertEqual(self.get(l, '/pro/ui/tokens.css')[0], 404)
            for name, raw, kind in (('tokens.css', b':root { --fixture: 1; }', 'text/css'),
                                    ('example.js', b'void 0;', 'text/javascript'),
                                    ('example.mjs', b'export {};', 'text/javascript')):
                with open(os.path.join(ui, name), 'wb') as f:
                    f.write(raw)
                self.assertEqual(self.get(l, '/pro/ui/' + name), (200, kind + '; charset=utf-8', raw))
                self.assertEqual(self.get(l, '/pro/ui/' + name, origin='http://elsewhere.invalid')[0], 403)
            page = self.get(l, '/')[2]
            self.assertEqual(page.count(b'href="/pro/ui/tokens.css"'), 1)
            self.assertLess(page.index(b'href="/web/app.css"'), page.index(b'href="/pro/ui/tokens.css"'))
            outside = os.path.join(private, 'outside.css')
            with open(outside, 'wb') as f:
                f.write(b'private')
            os.symlink(outside, os.path.join(ui, 'escape.css'))
            with open(os.path.join(ui, 'notes.txt'), 'wb') as f:
                f.write(b'not a browser asset')
            for path in ('../outside.css', '%2e%2e/outside.css', '/tokens.css', 'escape.css', 'notes.txt', 'missing.css'):
                self.assertEqual(self.get(l, '/pro/ui/' + path)[0], 404, path)
            os.unlink(os.path.join(ui, 'tokens.css'))
            self.assertNotIn(b'href="/pro/ui/tokens.css"', self.get(l, '/web/index.html')[2])
            self.assertEqual(self.get(l, '/pro/ui/tokens.css')[0], 404)

    def test_the_page_is_served_and_no_other_path_on_disk_is(self):
        l = self.live()
        for path, kind in (('/', 'text/html'), ('/web/app.css', 'text/css'), ('/web/app.js', 'text/javascript'), ('/web/icons.js', 'text/javascript')):
            code, got, raw = self.get(l, path)
            self.assertEqual((path, code, got), (path, 200, kind + '; charset=utf-8'))
            self.assertTrue(raw.strip())
        for path in ('/web/../cockpit/serve.py', '/web/%2e%2e/team.example.json', '/web/nope.js', '/cockpit/serve.py', '/ledger.jsonl', '/file?path=../../team.example.json',
                     '/file?path=/etc/hosts', '/file'):
            self.assertEqual((path, self.get(l, path)[0]), (path, 404))

    @unittest.skipUnless(serve.R.available(), 'this copy has no pro/ page')
    def test_the_pro_page_and_its_data_for_the_live_run(self):
        l = self.live()
        code, kind, raw = self.get(l, '/')
        self.assertIn(b' id="pro-link" href="/pro/"', raw)
