        self.assertEqual((code, kind), (200, 'text/html; charset=utf-8'))
        self.assertIn(b'<meta name="oc-backend" content="same-origin">', raw)
        for name in ['assets/' + n for n in os.listdir(os.path.join(serve.R.DIST, 'assets'))] + ['replay.js']:
            self.assertEqual(self.get(l, '/pro/' + name)[0], 200, name)
        body = {'id': 'p1', 'title': 'x', 'goal': 'x', 'to': l.lead, 'writes': ['p1/'], 'budget': 4, 'accept': {'judge': L.JUDGE, 'criteria': 'x'}}
        self.assertEqual(self.post(l, body)[0], 200)
        self.assertTrue(until(lambda: self.states(l).get('p1') == 'SUCCEEDED', 60), self.states(l))
        with open(os.path.join(l.run, 'ledger.jsonl'), 'rb') as f:
            rows = sum(1 for _ in f)
        code, kind, raw = self.get(l, '/pro/head.json')
        self.assertEqual((code, json.loads(raw)['rows']), (200, rows))
        code, kind, raw = self.get(l, '/pro/hq.head.json')
        self.assertEqual((code, json.loads(raw)['ledger_rows']), (200, rows))
        for name in ('events.js', 'audit.js', 'know.js', 'hq.json', 'diary.json', 'moments.json', 'raw/ledger.jsonl'):
            self.assertEqual(self.get(l, '/pro/' + name)[0], 200, name)
        code, kind, raw = self.get(l, '/pro/live.json')
        self.assertEqual((code, json.loads(raw)['mode'], json.loads(raw)['run'], json.loads(raw)['backend']), (200, 'live', os.path.basename(l.run), l.url))
        code, kind, raw = self.get(l, '/pro/events.js')
        starts = [m.start() for m in re.finditer(rb'"type": "run\.start"', raw)]
        self.assertEqual(len(starts), 3)
        for n in (1, 2, 3):     # the stand-in returns in the second it starts: every launch's start comes before its end and ruling
            at = {k: raw.index(('"type": "%s", "run": "run%d"' % (k, n)).encode()) for k in ('run.start', 'run.done', 'run.judged')}
            self.assertLess(at['run.start'], at['run.done'], n)
            self.assertLess(at['run.done'], at['run.judged'], n)
        for path in ('/pro/../cockpit/serve.py', '/pro/%2e%2e/README.md', '/pro/raw/../../README.md', '/pro/raw//etc/hosts',
                     '/pro/nope.js', '/pro/.home/x', '/pro/assets'):
            self.assertEqual((path, self.get(l, path)[0]), (path, 404))
        self.assertEqual(self.get(l, '/pro/', origin='http://elsewhere.invalid')[0], 403)
        out = l.srv._pro.out
        l.close()
        self.assertFalse(os.path.exists(out))

    def test_only_the_page_it_serves_may_send(self):
        l = self.live()
        body = {'id': 'x1', 'title': 'x', 'goal': 'x', 'to': l.lead, 'writes': ['x1/'], 'budget': 2, 'accept': {'judge': L.JUDGE, 'criteria': 'x'}}
        self.assertEqual(self.post(l, body, origin='http://elsewhere.invalid')[0], 403)
        self.assertEqual(self.states(l), {})
        self.assertEqual(self.get(l, '/state', origin='http://elsewhere.invalid')[0], 403)
        self.assertEqual(self.get(l, '/state')[0], 200)


class Parts(unittest.TestCase):
    def test_family(self):
        self.assertEqual([L.family(m) for m in MODELS + ['openrouter/moonshotai/kimi-k2', 'ollama/qwen3:8b', 'opencode/big-pickle']], ['deepseek', 'kimi', 'qwen', 'kimi', 'qwen', 'other'])

    def test_clean_env_keeps_only_what_is_named(self):
        env = A.clean_env(['MY_KEY'], {'bash': 'deny'}, base={'PATH': '/bin', 'HOME': '/h', 'MY_KEY': 'k', 'GITHUB_TOKEN': 't', 'OTHER': 'o'})
        self.assertEqual(sorted(env), ['HOME', 'MY_KEY', 'OPENCODE_CONFIG_CONTENT', 'OPENCODE_DISABLE_AUTOUPDATE', 'OPENCODE_DISABLE_CLAUDE_CODE', 'OPENCODE_DISABLE_SHARE', 'PATH'])
        self.assertEqual(json.loads(env['OPENCODE_CONFIG_CONTENT']), {'permission': {'external_directory': 'deny', 'doom_loop': 'deny', 'bash': 'deny'}})

    def test_the_command_line(self):
        self.assertEqual(A.opencode_argv('a/b', 't1#1', exe='/x/opencode'), ['/x/opencode', 'run', '--format', 'json', '-m', 'a/b', '--title', 't1#1', A.PROMPT])

    def test_reading_what_opencode_printed(self):
        tmp = tempfile.mkdtemp(prefix='cockpit-')
        self.addCleanup(shutil.rmtree, tmp, True)
        rows = [{'type': 'step_start', 'part': {}}, {'type': 'tool_use', 'part': {'tool': 'write', 'state': {'status': 'completed'}}},
                {'type': 'tool_use', 'part': {'tool': 'bash', 'state': {'status': 'error', 'error': 'The user rejected permission to use this specific tool call.'}}},
                {'type': 'step_finish', 'part': {'cost': 0.25, 'tokens': {'input': 10, 'output': 5, 'reasoning': 1, 'cache': {'read': 7, 'write': 2}}}},
                {'type': 'step_finish', 'part': {'cost': 0.5, 'tokens': {'input': 1, 'output': 1}}}, {'type': 'error', 'error': {'name': 'X'}}]
        with open(os.path.join(tmp, 'a.out'), 'w', encoding='utf-8') as f:
            f.write('not json\n' + ''.join(json.dumps(r) + '\n' for r in rows))
        got = A.read_opencode(os.path.join(tmp, 'a'))
        self.assertEqual((got['events'], got['steps'], got['tools'], got['tool_errors'], got['refused'], got['cost'], len(got['errors'])), (6, 2, {'write': 1, 'bash': 1}, 1, 1, 0.75, 1))
        self.assertEqual(got['tokens'], {'input': 11, 'output': 6, 'reasoning': 1, 'cache_read': 7, 'cache_write': 2})
        self.assertEqual(A.read_opencode(os.path.join(tmp, 'missing'))['events'], 0)

    def test_a_team_file_is_checked(self):
        tmp = tempfile.mkdtemp(prefix='cockpit-')
        self.addCleanup(shutil.rmtree, tmp, True)
        p = os.path.join(tmp, 'team.json')
        for bad in ({'lead': {'id': 'a', 'model': 'no-slash'}, 'seats': [{'id': 'b', 'model': 'p/m'}]}, {'lead': {'id': 'a', 'model': 'p/m'}, 'seats': []},
                    {'lead': {'id': 'a', 'model': 'p/m'}, 'seats': [{'id': 'a', 'model': 'p/m'}]}, {'lead': {'id': 'A b', 'model': 'p/m'}, 'seats': [{'id': 'b', 'model': 'p/m'}]}):
            with open(p, 'w', encoding='utf-8') as f:
                json.dump(bad, f)
            self.assertRaises(ValueError, L.load_team, p)
        self.assertEqual(L.load_team(os.path.join(ROOT, 'team.example.json'))['lead']['id'], 'lead')


if __name__ == '__main__':
    unittest.main()
