def fixture(root, full=True):
    """Write the run folder under root and return its path."""
    run = os.path.join(root, 'run')
    os.makedirs(run)
    with open(os.path.join(run, 'ledger.jsonl'), 'w', encoding='utf-8') as f:
        for i, (dt, kind, by, more) in enumerate(rows(), 1):
            r = {'seq': i, 't': T + dt, 'kind': kind, 'cause': 'c%05d' % i, 'n': 0, 'by': by, 'h': '%016x' % (i * 7919)}
            if kind == 'lease.expired':
                del r['h']
            f.write(json.dumps(dict(r, **more), ensure_ascii=False) + '\n')
    if full:
        with open(os.path.join(run, 'launches.jsonl'), 'w', encoding='utf-8') as f:
            f.write('{"order": "a", "launch": 1}\n{"order": "c", "launch": 1}\nnot json\n{"order": "a", "launch": 2}\n')
        with open(os.path.join(run, 'sent.jsonl'), 'w', encoding='utf-8') as f:
            f.write('\n'.join(log_lines()) + '\n')
    return run


def run_py(prog, *args, env=None):
    r = subprocess.run([sys.executable, '-I', '-B', prog] + list(args), capture_output=True, text=True, timeout=120,
                       env=None if env is None else dict(os.environ, **env))
    return r.returncode, r.stdout, r.stderr


def tampers():
    """(name, what it does to a diary, the field of the checker's line that must show it)."""
    def entry(d, eid):
        return next(e for e in d['entries'] if e['id'] == eid)

    def drop(eid):
        return lambda d: d['entries'].remove(entry(d, eid))

    def change(eid, key, value):
        return lambda d: entry(d, eid).__setitem__(key, value)

    def ptr(eid, key, value):
        return lambda d: entry(d, eid)['ptr'][0].__setitem__(key, value)

    def fake(d):
        d['entries'].append(dict(copy.deepcopy(entry(d, 'S000002')), id='S000001', ptr=[{'type': 'sent', 'n': 1, 'sha': hashlib.sha256(log_lines()[0].encode()).hexdigest()[:16]}]))

    def zero(eid, key, new):
        return lambda d: d['entries'].append(dict(copy.deepcopy(entry(d, eid)), id=new, ptr=[dict(entry(d, eid)['ptr'][0], **{key: 0})]))

    def no_record(n):
        return lambda d: d['entries'].append(dict(copy.deepcopy(entry(d, 'S000002')), id='S%06d' % n, ptr=[{'type': 'sent', 'n': n, 'sha': hashlib.sha256(log_lines()[n - 1].encode()).hexdigest()[:16]}]))

    return [
        ('an entry is deleted', drop('L000006'), 'coverage'),
        ('a number is changed', lambda d: entry(d, 'L000004')['nums'].__setitem__('ttl', 601), 'mismatch'),
        ('a number is dropped', lambda d: entry(d, 'L000005')['nums'].pop('pct'), 'mismatch'),
        ('a number is added', lambda d: entry(d, 'L000008')['nums'].__setitem__('token', 1), 'mismatch'),
        ('a seq is changed', ptr('L000006', 'seq', 7), 'mismatch'),
        ('a seq points past the ledger', ptr('L000041', 'seq', 42), 'mismatch'),
        ('a seq of 0', ptr('L000001', 'seq', 0), 'mismatch'),
        ('a line number of 0', ptr('S000002', 'n', 0), 'mismatch'),
        ('the last row told once more as row 0', zero('L000041', 'seq', 'L000000'), 'mismatch'),
        ('the last line told once more as line 0', zero('S000010', 'n', 'S000000'), 'mismatch'),
        ('a sent id is changed', change('S000004', 'id', 'S000099'), 'mismatch'),
        ('a line number past the records', ptr('S000010', 'n', 11), 'mismatch'),
        ('h is changed', ptr('L000004', 'h', '0' * 16), 'mismatch'),
        ('h is given to a row that has none', ptr('L000021', 'h', '0' * 16), 'mismatch'),
        ('the refused entry is dropped', drop('S000002'), 'refused'),
        ('the no-answer entry is dropped', drop('S000005'), 'no_answer'),
        ('a refusal is told as a silence', change('S000008', 'kind', 'sent.no-answer'), 'mismatch'),
        ('a refusal code is changed', change('S000002', 'code', 'stale'), 'mismatch'),
        ('an accepted envelope is told as refused', fake, 'mismatch'),
        ('a line with no ok is told as refused', no_record(3), 'mismatch'),
        ('a line whose ok is 1 is told as refused', no_record(6), 'mismatch'),
        ('a ledger entry gets a code', change('L000008', 'code', 'stale'), 'mismatch'),
        ('a silence carries a code field', change('S000005', 'code', None), 'mismatch'),
        ('the line sha is changed', ptr('S000004', 'sha', 'f' * 16), 'mismatch'),
        ('the line number is changed', ptr('S000005', 'n', 9), 'mismatch'),
        ('a sent entry gets numbers', change('S000009', 'nums', {'rows': 21}), 'mismatch'),
        ('a kind is changed', change('L000013', 'kind', 'order.succeeded'), 'mismatch'),
        ('an order is changed', change('L000011', 'order', 'b'), 'mismatch'),
        ('a sent order is changed', change('S000004', 'order', 'b'), 'mismatch'),
        ('by is changed', change('L000008', 'by', 'agent:w'), 'mismatch'),
        ('sent by is changed', change('S000009', 'by', 'team:lead'), 'mismatch'),
        ('t is changed', change('L000012', 't', T + 1001), 'mismatch'),
        ('sent t is changed', change('S000010', 't', T + 1), 'mismatch'),
        ('a time of day is changed', change('L000012', 'time', '22:16:41'), 'mismatch'),
        ('an id is changed', change('L000003', 'id', 'L000099'), 'mismatch'),
        ('a pointer is removed', change('L000009', 'ptr', []), 'no_pointer'),
        ('a pointer of an unknown type', ptr('L000010', 'type', 'memory'), 'mismatch'),
        ('a metric is changed', lambda d: d['orders']['b']['metrics'].__setitem__('max_silence', 300), 'metrics_mismatch'),
        ('a first pass is claimed', lambda d: d['orders']['b']['metrics'].__setitem__('first_pass', True), 'metrics_mismatch'),
        ('a refusal count is changed', lambda d: d['orders']['a']['metrics']['refused'].__setitem__('stale', 2), 'metrics_mismatch'),
        ('an order is invented', lambda d: d['orders'].__setitem__('zz', copy.deepcopy(d['orders']['d'])), 'metrics_mismatch'),
        ('an order is left out', lambda d: d['orders'].pop('d'), 'metrics_mismatch'),
    ]


class Diary(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.tmp = tempfile.TemporaryDirectory()
        cls.rundir = fixture(cls.tmp.name)
        cls.out = os.path.join(cls.tmp.name, 'out')
        cls.made = run_py(DIARY, cls.rundir, '--out', cls.out, '--tz', '+08:00')
        cls.d = cls.read(cls.out, 'diary.json') if cls.made[0] == 0 else None

    @classmethod
    def tearDownClass(cls):
        cls.tmp.cleanup()

    @staticmethod
    def read(folder, name):
        with open(os.path.join(folder, name), encoding='utf-8') as f:
            return json.load(f)

    @staticmethod
    def raw(folder, name):
        with open(os.path.join(folder, name), 'rb') as f:
            return f.read()

    def setUp(self):
        self.assertEqual(self.made[0], 0, self.made[2])

    def check(self, d=None, run=None):
        path = os.path.join(self.out, 'diary.json')
        if d is not None:
            path = os.path.join(self.tmp.name, 'tampered.json')
            with open(path, 'w', encoding='utf-8') as f:
                json.dump(d, f, ensure_ascii=False)
        code, out, err = run_py(CHECK, run or self.rundir, '--diary', path)
        return code, (json.loads(out) if out.strip() else None), err

    def entry(self, eid):
        return next(e for e in self.d['entries'] if e['id'] == eid)

    # ---- the diary
    def test_one_entry_per_row_with_the_row_s_own_numbers(self):
        led = [e for e in self.d['entries'] if e['id'].startswith('L')]
        self.assertEqual([e['id'] for e in sorted(led, key=lambda e: e['id'])], ['L%06d' % i for i in range(1, 42)])
        for i, (dt, kind, by, more) in enumerate(rows(), 1):
            e = self.entry('L%06d' % i)
            self.assertEqual((e['kind'], e['by'], e['t'], e['nums']), (kind, by, T + dt, NUMS[i]), i)
            self.assertEqual(e['order'], SUBJECT[i] if i in SUBJECT else more.get('order'), i)
            self.assertEqual(e['ptr'], [{'type': 'ledger', 'seq': i, 'h': None if i == 21 else '%016x' % (i * 7919)}])
            self.assertTrue(e['text'].strip() and '\n' not in e['text'], i)
        self.assertEqual(sorted(self.entry('L000001')), ['by', 'day', 'id', 'kind', 'nums', 'order', 'ptr', 't', 'text', 'time', 'top'])
        self.assertEqual((self.entry('L000001')['time'], self.entry('L000023')['time']), ('22:00:00', '00:01:40'))
        self.assertEqual(self.entry('L000004')['text'], 'agent:w took a (lease 1, for 10 min 0 s).')
        self.assertEqual(self.entry('L000013')['text'], 'program:judge failed b, sent back to be done again: again.')

    def test_refusals_and_silences_are_entries_and_nothing_else_from_the_records(self):
        sent = {e['id']: e for e in self.d['entries'] if e['id'].startswith('S')}
        self.assertEqual({k: (e['kind'], e['order'], e['by'], e['t'] - T, e['top'], e.get('code')) for k, e in sent.items()}, {
            'S000002': ('sent.refused', 'a', 'agent:w', 90, 'a', 'out-of-scope'),
            'S000004': ('sent.refused', 'x9', 'team:lead', 600, '_run', 'bad-order'),
            'S000005': ('sent.no-answer', 'c', 'agent:w', 2450, 'b', None),
            'S000008': ('sent.refused', 'a', 'agent:w', 7300, 'a', 'stale'),
            'S000009': ('sent.no-answer', 'y1', 'human:ceo', 7900, '_run', None),
            'S000010': ('sent.refused', None, 'agent:w', 7950, '_run', 'odd')})
        lines = log_lines()
        for k, e in sent.items():
            n = int(k[1:])
            self.assertEqual(e['ptr'], [{'type': 'sent', 'n': n, 'sha': hashlib.sha256(lines[n - 1].encode()).hexdigest()[:16]}])
            self.assertEqual((e['nums'], 'code' in e), ({}, e['kind'] == 'sent.refused'))
        self.assertEqual(sent['S000002']['text'], 'agent:w sent artifact.put (a) and the dispatcher refused it: out-of-scope, because out-of-scope')
        self.assertEqual(sent['S000005']['text'], 'agent:w sent report.progress (c) and got no answer from the dispatcher: Moved: the ledger changed.')
        self.assertEqual(self.d['counts'], {'entries': 47, 'refused': 4, 'no_answer': 2, 'rows_total': 41, 'rows_cited': 41})

