            for i, (dt, kind, more) in enumerate([(0, 'order.issued', {'body': body}), (5, 'report.progress', {'order': 'k', 'token': 0, 'note': 'early', 'pct': 1}),
                                                  (10, 'lease.granted', {'order': 'k', 'token': 1, 'expires': T + 70}),
