        for name, damage in (('no ledger', None), ('half a line', b'{"seq": 42, "t": 1'), ('a last line with no newline', b'{"seq": 42, "t": 1, "kind": "org.set", "cause": "x", "by": "human:ceo", "actor": "a", "superior": "b"}'), ('not JSON', b'nope\n'), ('a seq out of step', b'{"seq": 99, "t": 1, "kind": "org.set", "cause": "x", "by": "human:ceo", "actor": "a", "superior": "b"}\n'),
                             ('a row the dispatcher cannot replay', b'{"seq": 42, "t": 1, "kind": "org.set", "cause": "x"}\n')):
            root = os.path.join(self.tmp.name, 'bad-' + name.replace(' ', '-'))
            run = fixture(root)
            out = os.path.join(root, 'out')
            if damage is None:
                os.unlink(os.path.join(run, 'ledger.jsonl'))
