    def test_the_checker_reads_what_the_day_view_draws_too(self):
        def first(d, kind):
            return next(e for e in d['entries'] if e['kind'] == kind)

        def twice(d):
            d['entries'].append(copy.deepcopy(d['entries'][5]))

        def fam(d):
            d['days'][0]['families'] = []

        def moved(d):
            d['days'][0]['families'][0]['entries'].pop()

        changes = [
            ('a sentence of something else', lambda d: first(d, 'lease.granted').update(text='Nothing to see.'), 'mismatch'),
            ('an empty sentence', lambda d: first(d, 'sent.refused').update(text=''), 'mismatch'),
            ('the day of an entry', lambda d: first(d, 'report.progress').update(day='2026-01-01'), 'mismatch'),
            ('the family of an entry', lambda d: first(d, 'report.progress').update(top='zzz'), 'mismatch'),
            ('a day without its families', fam, 'also'),
            ('a family without its last entry', moved, 'also'),
            ('the same entry twice', twice, 'also'),
            ('the state of an order', lambda d: d['orders']['a'].update(state='FAILED'), 'metrics_mismatch'),
            ('the title of an order', lambda d: d['orders']['a'].update(title='Another title'), 'metrics_mismatch'),
            ('the skills an order was given', lambda d: d['orders']['a']['given'].update(skills=[]), 'metrics_mismatch'),
            ('the rows of an order', lambda d: d['orders']['c']['rows'].pop(), 'metrics_mismatch'),
        ]
        for name, do, field in changes:
            d = copy.deepcopy(self.d)
            do(d)
            code, line, err = self.check(d)
            self.assertEqual((code, line['ok']), (1, False), name)
            if field == 'also':
                self.assertTrue(line.get('also'), name)
                self.assertEqual((line['mismatch'], line['metrics_mismatch']), (0, 0), name)
            else:
                self.assertEqual(line[field], 1, name)
                self.assertNotIn('also', line, name)
        self.assertNotIn('also', self.check()[1])                 # the diary as written: nothing more to say

    def test_an_entry_taken_out_of_the_days_as_well_is_still_missed(self):
        for kind, field in (('lease.granted', 'coverage'), ('sent.refused', 'refused'), ('sent.no-answer', 'no_answer')):
            d = copy.deepcopy(self.d)
            gone = next(e for e in d['entries'] if e['kind'] == kind)['id']
            d['entries'] = [e for e in d['entries'] if e['id'] != gone]
            for day in d['days']:
                for f in day['families']:
                    f['entries'] = [x for x in f['entries'] if x != gone]
            code, line, err = self.check(d)
            self.assertEqual((code, line['ok'], line['mismatch'], line['metrics_mismatch']), (1, False, 0, 0), kind)
            self.assertNotIn('also', line, kind)
            if field == 'coverage':
                self.assertLess(line['coverage'], 1)
            else:
                self.assertEqual(line[field]['diary'], line[field]['source'] - 1, kind)

