# ---- the backend: sender records and GET /diary, with the real handlers and writer and no socket

class MemoryServer(serve.Server):
    """The production handlers and the production writer class (serve.Writer); no listening socket or HTTP thread."""
    def __init__(self, gate, run, port, clock, quiet=True):
        self.gate, self.run, self.clock, self.quiet = gate, run, clock, quiet
        self.server_address = ('127.0.0.1', port)
        self.origins = {'http://127.0.0.1:%d' % port}
        self.writer = self.writer_class(run, {'mode': 'test'})

    def server_close(self):
        self.writer.close()


def request(instance, method, path, body=None, headers=()):
    handler = serve.Handler.__new__(serve.Handler)
    handler.server, handler.path = instance.srv, path
    handler.request_version, handler.command, handler.requestline = 'HTTP/1.1', method, method + ' ' + path + ' HTTP/1.1'
    handler.headers = Message()
    raw = json.dumps(body).encode() if body is not None else b''
    handler.headers['Content-Length'] = str(len(raw))
    handler.headers['Host'] = '127.0.0.1:0'
    for k, v in headers:
        handler.headers[k] = v
    handler.rfile, handler.wfile = io.BytesIO(raw), io.BytesIO()
    with instance.gate:
        getattr(handler, 'do_' + method)()
    head, data = handler.wfile.getvalue().split(b'\r\n\r\n', 1)
    return int(head.split()[1]), json.loads(data)


def lines(path):
    with open(path, encoding='utf-8') as f:
        return [json.loads(x) for x in f]


def lines_raw(path):
    with open(path, encoding='utf-8') as f:
        return f.read().split('\n')[:-1]


class Backend(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.mkdtemp(prefix='diary-')
        self.instances = []
        self.addCleanup(self.cleanup)
        for p in (mock.patch.object(serve, 'Server', MemoryServer), mock.patch.object(live.Live, 'start', lambda instance: instance)):
            p.start()
            self.addCleanup(p.stop)

    def cleanup(self):
        for instance in self.instances:
            instance.srv.server_close()
        shutil.rmtree(self.tmp, ignore_errors=True)

    def start(self, date):
        stamp = time.mktime(time.strptime(date + ' 12:00:00', '%Y-%m-%d %H:%M:%S'))
        instance = serve.start(self.tmp, TEAM, exe=FAKE, offset=stamp - time.time(), every=0.1, pace=0.01)
        self.instances.append(instance)
        return instance

    def complete(self, instance, oid):
        for _ in range(20):
            instance.once()
            if instance.ad.d.snapshot()['orders'][oid]['state'] == 'SUCCEEDED':
                return
        self.fail('stand-in order did not succeed')

    def order(self, instance, oid, title='A note', mid=None):
        return planning.envelope(dict(title=title, goal='Write and review a note.', writes='', budget=6), oid, instance.lead, mid or 'ui-' + oid)

    def test_every_envelope_handed_to_the_dispatcher_is_one_sender_record(self):
        instance = self.start('2030-04-10')
        sent = os.path.join(instance.run, live.SENT)
        code, r = request(instance, 'POST', '/message', self.order(instance, 'one'))
        self.assertEqual((code, r['ok']), (200, True))
        code, r = request(instance, 'POST', '/message', self.order(instance, 'one', title='Another title'))        # the same id, other content
        self.assertEqual((code, r['ok'], r['code']), (200, False, 'id-reuse'))
        before = len(lines(sent))
        envelope = self.order(instance, 'stray', mid='ui-stray')
        envelope['body']['to'] = 'agent:writer'
        self.assertEqual(request(instance, 'POST', '/message', envelope)[1]['cli'], 'not-through-lead')
        self.assertEqual(len(lines(sent)), before)                                           # refused before the dispatcher: nothing was handed over
        leased = dict(self.order(instance, 'three'), lease={'order': 'one', 'token': 'nine'})     # under a lease, with no parent; refused at the door
        code, r = request(instance, 'POST', '/message', leased)
        self.assertEqual((code, r['ok'], r['code']), (200, False, 'bad-shape'))
        self.assertEqual({k: lines(sent)[-1][k] for k in ('id', 'order', 'under', 'ok')}, {'id': 'ui-three', 'order': 'three', 'under': 'one', 'ok': False})
        code, r = request(instance, 'POST', '/message', self.order(instance, 'two'), headers=[(cli.LEDGER_HEADER, '1:' + '0' * 16)])
        self.assertEqual((code, r['cli']), (412, 'other-ledger'))
        self.complete(instance, 'one')
        recs = lines(sent)
        self.assertTrue(all(sorted(x) == ['at', 'code', 'detail', 'events', 'from', 'id', 'kind', 'ok', 'order', 'under'] for x in recs))
        mine = {x['id']: x for x in recs if x['id'] in ('ui-one', 'ui-two')}
        self.assertEqual(mine['ui-two'], {'id': 'ui-two', 'at': mine['ui-two']['at'], 'from': live.CEO, 'kind': 'order.issue', 'order': 'two', 'under': None,
                                          'ok': None, 'code': None, 'detail': mine['ui-two']['detail'], 'events': []})
        self.assertTrue(mine['ui-two']['detail'].startswith('OtherLedger: '), mine['ui-two']['detail'])
        refused = [x for x in recs if x['ok'] is False]
        self.assertEqual([(x['id'], x['order'], x['code'], x['events']) for x in refused], [('ui-one', 'one', 'id-reuse', []), ('ui-three', 'three', 'bad-shape', [])])
        self.assertEqual(refused[0]['detail'], 'same id, different content')
        # every row a request caused is in the events of exactly one accepted record with that id, and nothing more
        events = cli.read_ledger(instance.run)
        caused = {}
        for e in events:
            if not e['cause'].startswith('clock:'):
                caused.setdefault(e['cause'], []).append(e['seq'])
        accepted = [x for x in recs if x['ok'] is True]
        self.assertEqual({x['id']: x['events'] for x in accepted}, caused)
        self.assertEqual(len(accepted), len(caused))
        self.assertLessEqual({'org.set', 'order.issue', 'claim.request', 'artifact.put', 'report.submit', 'verdict'}, {x['kind'] for x in accepted})
        issued = {x['order']: x['under'] for x in accepted if x['kind'] == 'order.issue'}
        self.assertEqual(issued, {'one': None, 'one.draft': 'one', 'one.review': 'one'})
        self.assertEqual([x['at'] for x in recs], sorted(x['at'] for x in recs))
        self.assertIn(live.SENT, live.OWN)                     # an agent's launch does not list it as a change outside its folder
        # the diary of this run, checked from the raw files
        out = os.path.join(self.tmp, 'out')
        code, _, err = run_py(DIARY, instance.run, '--out', out)
        self.assertEqual(code, 0, err)
        code, text, err = run_py(CHECK, instance.run, '--diary', os.path.join(out, 'diary.json'))
        line = json.loads(text)
        self.assertEqual((code, line['coverage'], line['refused'], line['no_answer'], line['mismatch'], line['metrics_mismatch']),
                         (0, 1, {'diary': 2, 'source': 2}, {'diary': 1, 'source': 1}, 0, 0), err)
        self.assertEqual(Diary.read(out, 'diary.json')['orders']['one']['metrics']['refused'], {'id-reuse': 1})

    def test_a_record_that_cannot_be_written_leaves_the_answer_standing_and_says_so(self):
        instance = self.start('2030-04-10')
        sent = os.path.join(instance.run, live.SENT)
        os.replace(sent, sent + '.kept')
        os.makedirs(sent)                                       # a folder where the file should be: it cannot be opened for appending
        with mock.patch.object(live, 'say') as say:
            code, r = request(instance, 'POST', '/message', self.order(instance, 'kept'))
        self.assertEqual((code, r['ok']), (200, True))
        self.assertIn("WARNING the sender record of 'ui-kept' could not be written", say.call_args[0][0])
        self.assertEqual(instance.ad.d.snapshot()['orders']['kept']['state'], 'PENDING')

    def test_get_diary(self):
        first = self.start('2030-04-10')
        code, r = request(first, 'POST', '/message', self.order(first, 'first'))
        self.complete(first, 'first')
        first_run = os.path.basename(first.run)
        first.srv.server_close()
        second = self.start('2030-04-11')
        code, today = request(second, 'GET', '/diary')
        self.assertEqual((code, today['day'], today['run'], today['tz']), (200, '2030-04-11', os.path.basename(second.run), 'local'))
        self.assertEqual([f['top'] for f in today['families']], ['_run'])                       # the org.set rows of this start
        code, past = request(second, 'GET', '/diary?run=%s&day=2030-04-10' % first_run)
        self.assertEqual(code, 200, past)
        self.assertEqual([f['top'] for f in past['families']], ['first', '_run'])        # orders in issue order, then the rest
        self.assertEqual(sorted(past['orders']), ['first', 'first.draft', 'first.review'])
        self.assertEqual(past['orders']['first']['state'], 'SUCCEEDED')
        self.assertEqual(past['days'], [{'date': '2030-04-10', 'entries': sum(len(f['entries']) for f in past['families'])}])
        expected = diary.day_of(diary.build(os.path.join(self.tmp, first_run)), '2030-04-10')
        self.assertEqual(past, json.loads(json.dumps(expected)))
        # the same order is on the same day in the calendar and in the diary
        doc = request(second, 'GET', '/history')[1]
        self.assertEqual([o['id'] for o in doc['days']['2030-04-10']['orders']], ['first'])
        issued = next(e for f in past['families'] for e in f['entries'] if e['kind'] == 'order.issued' and e['order'] == 'first')
        self.assertEqual(issued['day'], history.day(issued['t']))
        self.assertEqual(request(second, 'GET', '/diary?run=%s&day=2030-04-12' % first_run)[1]['families'], [])
        for path, code, cli_code in (('/diary?day=2030-02-30', 400, 'bad-query'), ('/diary?day=tomorrow', 400, 'bad-query'),
                                     ('/diary?run=nowhere', 404, 'not-found'), ('/diary?run=..', 404, 'not-found'),
                                     ('/diary?run=library', 404, 'not-found')):
            self.assertEqual(request(second, 'GET', path)[:1] + (request(second, 'GET', path)[1]['cli'],), (code, cli_code), path)
        os.makedirs(os.path.join(self.tmp, 'broken'))
        with open(os.path.join(self.tmp, 'broken', cli.LEDGER), 'w') as f:
            f.write('nope\n')
        self.assertEqual(request(second, 'GET', '/diary?run=broken'), (500, {'cli': 'unreadable-history', 'detail': 'The stored run or plans cannot be read.'}))
        code, r = request(second, 'GET', '/diary', headers=[('Origin', 'http://elsewhere.invalid')])
        self.assertEqual((code, r['cli']), (403, 'bad-origin'))

    def test_get_state_carries_the_sender_records_the_status_reads(self):
        instance = self.start('2030-04-10')
        sent = os.path.join(instance.run, live.SENT)
        self.assertEqual(request(instance, 'POST', '/message', self.order(instance, 'one'))[1]['ok'], True)
        self.assertEqual(request(instance, 'POST', '/message', self.order(instance, 'one', title='Another title'))[1]['code'], 'id-reuse')
        leased = dict(self.order(instance, 'three'), lease={'order': 'one', 'token': 'nine'})
        self.assertEqual(request(instance, 'POST', '/message', leased)[1]['code'], 'bad-shape')
        with open(sent, 'ab') as f:
            f.write(b'not a record\n')                      # skipped, and its line number is not given to another record
        self.assertEqual(request(instance, 'POST', '/message', self.order(instance, 'four'))[1]['ok'], True)
        on_disk = lines_raw(sent)
        expected = [dict(json.loads(x), n=n) for n, x in enumerate(on_disk, 1) if x != 'not a record']
        for path in ('/state', '/state?since=0'):
            code, answer = request(instance, 'GET', path)
            self.assertEqual(code, 200)
            self.assertEqual(answer['sent'], expected, path)
        refused = [(x['n'], x['id'], x['order'], x['code']) for x in answer['sent'] if x['ok'] is False]
        junk = on_disk.index('not a record') + 1             # the two refusals were the last two lines before it
        self.assertEqual(refused, [(junk - 2, 'ui-one', 'one', 'id-reuse'), (junk - 1, 'ui-three', 'three', 'bad-shape')])
        self.assertEqual(answer['sent'][-1]['n'], len(on_disk))
        node = shutil.which('node')
        if not node:
            self.skipTest('node is not installed, so the status of this answer cannot be worked out by web/status.js')
        script = ("const S = require(process.argv[1]); let raw = ''; process.stdin.on('data', d => { raw += d; });"
                  "process.stdin.on('end', () => { const a = JSON.parse(raw); process.stdout.write(JSON.stringify("
                  "S.classify({snap: a, log: a.log, sent: a.sent, nowS: a.now, live: true, lastOkS: a.now, pollS: 5}))); });")
        r = subprocess.run([node, '-e', script, os.path.join(ROOT, 'web', 'status.js')], input=json.dumps(answer),
                           capture_output=True, text=True, timeout=60)
        self.assertEqual(r.returncode, 0, r.stderr)
        cards = {c['id']: c for c in json.loads(r.stdout)}
        self.assertEqual((cards['three']['case'], cards['three']['facts']['reply'], cards['three']['facts']['code']), ('1', 'refused', 'bad-shape'))
        self.assertIn('7b', cards['one']['flags'])           # the last envelope about `one` (sent under it) was refused
        self.assertEqual(cards['one']['facts']['b_id'], 'ui-three')
        self.assertNotIn('7b', cards['four']['flags'])

    def test_the_page_file_of_the_status_is_served(self):
        self.assertEqual(serve.PAGE['status.js'], 'text/javascript')

    def test_a_relative_opencode_path_is_made_absolute_before_any_agent_starts(self):
        # agents start in folders of their own: the README's `--opencode tests/fake_bin/opencode` must not be read there
        seen = []
        def start(*a, **kw):
            seen.append(a[6])
            raise OSError('stopped here')
        with mock.patch.object(serve, 'start', start), mock.patch.object(live, 'say'):
            cwd = os.getcwd()
            os.chdir(ROOT)
            try:
                for exe in ('tests/fake_bin/opencode', 'opencode', None):
                    self.assertEqual(serve.main([self.tmp] + (['--opencode', exe] if exe else [])), 2)
            finally:
                os.chdir(cwd)
        self.assertEqual(seen, [os.path.join(ROOT, 'tests', 'fake_bin', 'opencode'), 'opencode', None])     # a bare name is still looked up on PATH
        self.assertTrue(os.path.isfile(seen[0]))


if __name__ == '__main__':
    unittest.main()
