#!/usr/bin/env python3
"""Small real-Writer regressions for the bounded state-space invariants.

The final expiry advances the next attempt beyond the allowed attempts, and
clock events survive a refused envelope without retaining any of its own rows.
"""
import copy
import json
import os
import sys
import tempfile
import unittest

sys.path.insert(0, os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), 'cockpit'))
import cli  # noqa: E402
import dispatcher  # noqa: E402


class DispatchStateRegressions(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory(prefix='dispatch-regression-')
        self.addCleanup(self.tmp.cleanup)
        self.writer = cli.Writer(self.tmp.name, {'mode': 'regression'})
        self.addCleanup(self.writer.close)
        self.steps, self.now = [], 0
        self.send('human:lead', 'org.set', {'actor': 'team:worker', 'superior': 'human:lead'})
        self.send('human:lead', 'org.set', {'actor': 'agent:worker/one', 'superior': 'team:worker'})
        self.body = {'id': 'top', 'to': 'team:worker', 'writes': ['work/'], 'budget': 2,
                     'accept': {'judge': 'program:judge', 'criteria': 'review the result'}}
        self.assertTrue(self.send('human:lead', 'order.issue', self.body)['ok'])

    def send(self, actor, kind, body=None, lease=None, now=None):
        if now is not None:
            self.now = now
        envelope = dispatcher.msg('m%d' % (len(self.steps) + 1), actor, kind, body,
                                  basis=self.writer.d.s.head, lease=lease)
        self.steps.append({'now': self.now, 'envelope': envelope})
        return self.writer.submit(envelope, self.now)

    def sequence(self):
        return '\nExact sequence:\n' + '\n'.join('%d. %s' % (n, json.dumps(step, sort_keys=True))
                                                 for n, step in enumerate(self.steps, 1))

    def test_final_expiry_records_exhausted_attempts(self):
        for _ in range(dispatcher.MAX_ATTEMPTS):
            claim = self.send('team:worker', 'claim.request', {'order': 'top', 'ttl': 2})
            self.assertTrue(claim['ok'], self.sequence())
            self.assertTrue(self.send('human:lead', 'state.query', now=claim['lease']['expires'] + 1)['ok'])
        witness = self.sequence()
        self.assertEqual(self.writer.d.s.orders['top']['state'], 'DEAD', witness)
        # DEAD is first reached at the BFS depth boundary. Exercise its outgoing
        # terminal guards here before checking the exhausted attempt count.
        dead = copy.deepcopy(vars(self.writer.d.s))
        for actor, kind, body in (('team:worker', 'claim.request', {'order': 'top'}),
                                  ('human:lead', 'order.issue', self.body),
                                  ('human:lead', 'order.cancel', {'order': 'top'})):
            self.assertFalse(self.send(actor, kind, body)['ok'], self.sequence())
            self.assertEqual(vars(self.writer.d.s), dead, self.sequence())
        self.assertEqual(self.writer.d.s.orders['top']['attempt'], dispatcher.MAX_ATTEMPTS + 1, witness)
        expiries = [e for e in self.writer.d.log if e['kind'] == 'lease.expired' and e.get('order') == 'top']
        self.assertEqual(len(expiries), dispatcher.MAX_ATTEMPTS, witness)

    def test_refused_expired_put_keeps_only_clock_row(self):
        claim = self.send('team:worker', 'claim.request', {'order': 'top', 'ttl': 2})
        self.assertTrue(claim['ok'], self.sequence())
        with open(self.writer.path, 'rb') as f:
            before = f.read()
        reply = self.send('team:worker', 'artifact.put', {'key': 'work/top/result', 'expect': 0},
                          lease=claim['lease'], now=claim['lease']['expires'] + 1)
        self.assertEqual((reply['ok'], reply.get('code')), (False, 'fenced'), self.sequence())
        with open(self.writer.path, 'rb') as f:
            after = f.read()
        self.assertTrue(after.startswith(before), self.sequence())
        rows = [json.loads(line) for line in after[len(before):].splitlines()]
        self.assertEqual(len(rows), 1, self.sequence())
        self.assertEqual((rows[0]['kind'], rows[0]['order'], rows[0]['by']),
                         ('lease.expired', 'top', 'dispatcher'), self.sequence())
        self.assertEqual(rows[0]['cause'], 'clock:%d' % (len(before.splitlines()) + 1), self.sequence())
        self.assertFalse(any(e['cause'] == self.steps[-1]['envelope']['id'] for e in rows), self.sequence())


if __name__ == '__main__':
    unittest.main()
