#!/usr/bin/env python3
"""Bounded BFS of the real dispatcher, through cli.Writer, with real ledger files.

Run: python3 tests/test_dispatch_states.py

The finite input domain is deliberately explicit: one lead, one team/member,
one program judge, one top order, two child slots, one artifact and one question
per order. Claims include all four actors (including forbidden ones). Work uses
the current/last token, even after release or termination. Verdicts include all
four pass/retry combinations. No action is filtered by its expected legality.

Every edge is submitted to Writer; no transition function is duplicated here.
Checkpoints contain only bytes/state produced by the real implementation. BFS
merges states modulo fresh envelope IDs, ledger positions and absolute time:
all decisions use the current head, retries are checked immediately at the same
time, and time is relative to outstanding leases. Token counters are retained.
Repeated puts use expect=0; questions have one stable ID per order. This is an
exhaustive check of this bounded input domain, not of arbitrary JSON envelopes.

Clock actions send state.query at an actual lease expiry + 1, using the same
explicit `now` argument as test_dispatch.py. A late put also arrives at expiry + 1
without an intervening query, testing clock events on a refused mutation.
Queries and duplicate retries are
not new mutations, so they need not append rows. Fresh accepted mutations must
append rows and refusals must append none of their own (clock rows may stay).
Hashes are cli's per-prefix hashes,
not the event's `h` (which is an envelope digest, not a ledger hash).

Failures are collected through the entire bound so one bug cannot hide another;
the first witness per invariant is shortest in BFS order and prints exact JSON
envelopes and dispatcher times. No expectedFailure or production-code patches.
Standard library only, Python 3.9+.
"""
import collections
import copy
import hashlib
import json
import os
import sys
import tempfile
import time
import unittest

sys.path.insert(0, os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), 'cockpit'))
import cli  # noqa: E402
import dispatcher  # noqa: E402

LEAD, TEAM, MEMBER, JUDGE = 'human:lead', 'team:worker', 'agent:worker/one', 'program:judge'
TOP, CHILDREN = 'top', ('child-a', 'child-b')
ORDERS = (TOP,) + CHILDREN
TERMINAL = frozenset(('SUCCEEDED', 'FAILED', 'DEAD', 'CANCELLED'))
DEPTH = 7  # issue + three claim/expiry pairs; measured below one minute on Python 3.9
TTL = 2
INVARIANTS = ('lease uniqueness', 'lease membership', 'terminal immutability',
              'terminal fencing', 'attempt bound', 'DEAD provenance',
              'children before submit', 'cancel cascade', 'envelope ledger writes',
              'ledger sequence', 'ledger hash chain', 'ledger replay', 'idempotent retry')
REQUIRED_COVERAGE = frozenset(
    ['accepted:' + kind for kind in 'order.issue claim.request lease.renew lease.release artifact.put report.submit verdict order.cancel ask.raise ask.answer state.query'.split()]
    + ['terminal:' + state for state in TERMINAL]
    + ['verdict:%s:%s' % (passed, retry) for passed in (True, False) for retry in (False, True)]
    + ['two children', 'children-open refusal', 'cascading cancellation', 'membership refusal',
       'simultaneous expiries', 'duplicate retry'])


def encoded(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=True)


def order_body(oid):
    return dict(id=oid, to=TEAM if oid == TOP else MEMBER,
                parent=None if oid == TOP else TOP, writes=['work/' if oid == TOP else 'work/%s/' % oid],
                budget=2 if oid == TOP else 1,
                accept={'judge': JUDGE, 'criteria': 'review the result'})


def key_for(oid):
    return 'work/%s/result' % oid


def state_key(s, now):
    """Hash a future-equivalent state for the input domain documented above.

    Nothing dispatch-affecting is dropped: answered questions, outputs, released
    revisions, attempts, tokens and lease time remaining all survive. `seen` is
    irrelevant to fresh IDs, except the stable question IDs represented in asks.
    Every accepted envelope is independently retried before any deduplication.
    """
    value = copy.deepcopy(vars(s))
    for field in ('head', 'now', 'seen'):
        value.pop(field)
    for o in value['orders'].values():
        o.pop('touched')
    for q in value['asks'].values():
        q.pop('touched')
    for lease in value['leases'].values():
        lease['expires'] -= now
    return hashlib.sha256(encoded(value).encode('ascii')).digest()


def actions(s, now, depth):
    """Enumerate candidates; only the dispatcher decides whether they succeed."""
    mid = 'step-%d' % depth

    def envelope(label, actor, kind, body=None, lease=None, ident=None, at=None):
        return (label, now if at is None else at,
                dispatcher.msg(ident or mid, actor, kind, body, basis=s.head, lease=lease))

    # Always try reissuing an existing ID too: terminal orders must not reset.
    yield envelope('issue top', LEAD, 'order.issue', order_body(TOP))
    parent = s.orders.get(TOP)
    if parent:
        parent_lease = s.leases.get(TOP, {})
        holder = parent_lease.get('holder', TEAM)
        token = {'order': TOP, 'token': max(1, parent['token'])}
        for oid in CHILDREN:
            yield envelope('issue %s' % oid, holder, 'order.issue', order_body(oid), token)

    # Prefer a pure tick as the representative when a late refused mutation
    # reaches the same state; this keeps the exhaustion witness independent.
    for expiry in sorted({le['expires'] for le in s.leases.values()}):
        yield envelope('tick past %d' % expiry, LEAD, 'state.query', at=expiry + 1)

    for oid in ORDERS:
        if oid not in s.orders:
            continue  # the bounded domain names an order only after it exists
        o = s.orders[oid]
        lease = {'order': oid, 'token': max(1, o['token'])}
        holder = s.leases.get(oid, {}).get('holder', o['to'])
        for actor in (TEAM, MEMBER, LEAD, JUDGE):
            yield envelope('claim %s by %s' % (oid, actor), actor, 'claim.request', {'order': oid, 'ttl': TTL})
        for name, kind, body in (
                ('renew', 'lease.renew', {'ttl': TTL + 1}),
                ('release', 'lease.release', {}),
                ('put', 'artifact.put', {'key': key_for(oid), 'expect': 0}),
                ('submit', 'report.submit', {'outputs': ([{'key': key_for(oid), 'rev': 1}]
                                                       if key_for(oid) in s.arts else [])})):
            yield envelope('%s %s' % (name, oid), holder, kind, body, lease)
        if oid in s.leases:
            yield envelope('late put %s' % oid, holder, 'artifact.put',
                           {'key': key_for(oid), 'expect': 0}, lease, at=s.leases[oid]['expires'] + 1)
        for passed in (True, False):
            for retry in (False, True):
                yield envelope('verdict %s pass=%s retry=%s' % (oid, passed, retry), JUDGE, 'verdict',
                               {'order': oid, 'pass': passed, 'retry': retry})
        yield envelope('cancel %s' % oid, LEAD, 'order.cancel', {'order': oid})
        qid = 'question-' + oid
        for blocking in (True, False):
            yield envelope('ask %s blocking=%s' % (oid, blocking), MEMBER, 'ask.raise',
                           {'order': oid, 'to': LEAD, 'text': 'Proceed?', 'blocking': blocking}, ident=qid)
        yield envelope('answer %s' % oid, LEAD, 'ask.answer', {'ask': qid, 'answer': 'Proceed.'})


class World:
    """A single temporary run, branching by restoring real checkpoints only."""
    def __init__(self, run):
        self.run = run
        self.writer = cli.Writer(run, {'mode': 'state-space-test'})
        self.now = 0
        self.setup = []
        for n, (actor, superior) in enumerate(((TEAM, LEAD), (MEMBER, TEAM))):
            m = dispatcher.msg('setup-%d' % n, LEAD, 'org.set', {'actor': actor, 'superior': superior})
            reply = self.writer.submit(m, self.now)
            if not reply['ok']:
                raise AssertionError('setup refused: %r' % reply)
            self.setup.append(('setup org', self.now, m))

    def bytes(self):
        with open(self.writer.path, 'rb') as f:
            return f.read()

    def checkpoint(self):
        return (self.bytes(), copy.deepcopy(self.writer.d.s),
                copy.deepcopy(self.writer.d.log), self.writer.chain[:], self.now)

    def restore(self, checkpoint):
        data, state, log, chain, self.now = checkpoint
        # Restoration is not a transition. Writer still owns the real file lock;
        # every explored edge goes through its unmodified submit/fsync path.
        with open(self.writer.path, 'wb') as f:
            f.write(data)
        self.writer.d.s = copy.deepcopy(state)
        self.writer.d.log = copy.deepcopy(log)
        self.writer.chain = chain[:]
        self.writer.mark = self.writer._stat()

    def send(self, action):
        _, now, envelope = action
        self.now = now
        return self.writer.submit(envelope, now)

    def close(self):
        self.writer.close()


def inspect(world, before, action, reply):
    """Independent assertions on actual state, events and persisted bytes."""
    problems = []

    def require(condition, invariant, detail):
        if not condition:
            problems.append((invariant, detail))

    old_bytes, old, old_log, old_chain, _ = before
    w, now = world.writer, world.now
    s, events = w.d.s, w.d.log[len(old_log):]
    _, _, envelope = action
    data = world.bytes()
    require(data.startswith(old_bytes), 'ledger hash chain', 'an existing ledger prefix was rewritten')
    own = [e['seq'] for e in events if e['cause'] == envelope['id']]
    if not reply['ok']:
        require(not own, 'envelope ledger writes', 'refused %s appended rows of its own: %s' % (reply, own))
    elif envelope['kind'] != 'state.query' and not reply.get('dup'):
        require(bool(own), 'envelope ledger writes', 'accepted mutation appended no rows of its own')
        require(own == reply['events'],
                'envelope ledger writes', 'acknowledged rows differ from the envelope rows')
    require(reply.get('code') != 'internal', 'envelope ledger writes', 'handler crashed: %r' % reply)

    # Count live grants independently of State.leases (a dict cannot expose an
    # accidental second grant that overwrote its first value).
    grants = collections.defaultdict(dict)
    for e in w.d.log:
        oid, kind = e.get('order'), e['kind']
        if kind == 'lease.granted':
            valid = [le for le in grants[oid].values() if le['expires'] > e['t']]
            require(not valid, 'lease uniqueness', 'overlapping grants for %s at row %d' % (oid, e['seq']))
            grants[oid][e['token']] = {'holder': e['by'], 'expires': e['expires']}
            allowed = {s.orders[oid]['to']}
            if TEAM in allowed:
                allowed.add(MEMBER)
            require(e['by'] in allowed, 'lease membership', 'grant to forbidden holder at row %d' % e['seq'])
        elif kind == 'lease.renewed' and e['token'] in grants[oid]:
            grants[oid][e['token']]['expires'] = e['expires']
        elif kind in ('lease.released', 'lease.expired'):
            grants[oid].pop(e['token'], None)
        elif kind in ('report.submitted', 'order.cancelled', 'order.succeeded', 'order.failed', 'order.dead'):
            grants[oid].clear()
    for oid, lease in s.leases.items():
        allowed = {s.orders[oid]['to']}
        # Fixed small org: membership is checked independently, not d.over().
        if TEAM in allowed:
            allowed.add(MEMBER)
        require(lease['holder'] in allowed, 'lease membership', '%s held by %s' % (oid, lease['holder']))
        require(s.orders[oid]['state'] not in TERMINAL, 'terminal fencing', '%s has a lease' % oid)
        valid = [le for le in grants[oid].values() if le['expires'] > now]
        require(len(valid) == 1 and valid[0] == {'holder': lease['holder'], 'expires': lease['expires']},
                'lease uniqueness', 'live lease differs from grant history for %s' % oid)

    for oid, o in s.orders.items():
        previous = old.orders.get(oid)
        # attempt names the next attempt, so the final expiry advances it once
        # past MAX_ATTEMPTS before the clock marks the order DEAD.
        require(1 <= o['attempt'] <= dispatcher.MAX_ATTEMPTS + 1, 'attempt bound',
                '%s is %s with attempt=%d outside 1..%d' % (oid, o['state'], o['attempt'], dispatcher.MAX_ATTEMPTS + 1))
        if o['state'] not in TERMINAL:
            require(o['attempt'] <= dispatcher.MAX_ATTEMPTS, 'attempt bound',
                    'open %s has attempt=%d > MAX_ATTEMPTS=%d' % (oid, o['attempt'], dispatcher.MAX_ATTEMPTS))
        if o['state'] == 'DEAD':
            require(o['attempt'] == dispatcher.MAX_ATTEMPTS + 1, 'attempt bound',
                    'DEAD %s has attempt=%d instead of %d' % (oid, o['attempt'], dispatcher.MAX_ATTEMPTS + 1))
            expiries = [e for e in w.d.log if e['kind'] == 'lease.expired' and e.get('order') == oid]
            require(len(expiries) == dispatcher.MAX_ATTEMPTS, 'DEAD provenance',
                    'DEAD %s has %d expiries instead of %d' % (oid, len(expiries), dispatcher.MAX_ATTEMPTS))
        if previous and previous['state'] in TERMINAL:
            require(o['state'] == previous['state'], 'terminal immutability', '%s: %s -> %s' % (oid, previous['state'], o['state']))
            require(not any(e['kind'] == 'lease.granted' and e.get('order') == oid for e in events),
                    'terminal fencing', 'terminal %s was granted a lease' % oid)
        if o['state'] == 'DEAD' and (not previous or previous['state'] != 'DEAD'):
            expired = [e for e in events if e['kind'] == 'lease.expired' and e.get('order') == oid]
            died = [e for e in events if e['kind'] == 'order.dead' and e.get('order') == oid]
            require(previous is not None and previous['attempt'] == dispatcher.MAX_ATTEMPTS
                    and len(expired) == len(died) == 1 and expired[0]['seq'] < died[0]['seq']
                    and oid in old.leases and old.leases[oid]['expires'] <= now
                    and expired[0]['cause'] == died[0]['cause'] and died[0]['cause'].startswith('clock:'),
                    'DEAD provenance', '%s died without an expiry at the maximum attempt' % oid)
    for e in events:
        if e['kind'] == 'report.submitted':
            children = [o['id'] for o in old.orders.values()
                        if o.get('parent') == e['order'] and o['state'] not in TERMINAL]
            require(not children, 'children before submit', '%s submitted with open children %s' % (e['order'], children))
        if e['kind'] == 'order.cancelled':
            children = [o['id'] for o in old.orders.values()
                        if o.get('parent') == e['order'] and o['state'] not in TERMINAL]
            wrong = [oid for oid in children if s.orders.get(oid, {}).get('state') != 'CANCELLED']
            require(not wrong, 'cancel cascade', '%s did not cancel open children %s' % (e['order'], wrong))

    links, rows, last = [], [], None
    require(data.endswith(b'\n'), 'ledger sequence', 'ledger has a partial final line')
    for number, line in enumerate(data.splitlines(), 1):
        row = json.loads(line)
        rows.append(row)
        require(row.get('seq') == number, 'ledger sequence', 'line %d has seq %r' % (number, row.get('seq')))
        last = hashlib.sha256((last.encode('ascii') + b'\n' if last else b'') + line).hexdigest()[:16]
        links.append(last)
    require(links == w.chain and links[:len(old_chain)] == old_chain,
            'ledger hash chain', 'writer chain does not match independently hashed bytes')
    replay = cli.state(world.run, now, since=0, at=len(rows))
    require(replay['state'] == w.d.snapshot() and replay['rows'] == s.head
            and replay['source']['t'] == s.now and replay['log'] == w.d.log == rows,
            'ledger replay', 'cli.state differs from the live dispatcher')
    require(replay['log_chain'] == links and replay['source']['at']['chain'] == last,
            'ledger hash chain', 'cli.state chain differs from independently hashed bytes')
    # cli.state intentionally omits answered asks, seen IDs and released inputs;
    # also compare the complete internal state folded from the written ledger.
    require(vars(dispatcher.Dispatcher(events=rows).s) == vars(s),
            'ledger replay', 'complete replay differs (including seen/answered/released)')
    return problems


def retry_check(world, action, reply):
    before = world.checkpoint()
    again = world.send(action)
    # Exact equality preserves all the invariants just checked, without folding
    # an identical file twice. If anything changes, inspect the new step too.
    unchanged = (world.bytes() == before[0] and vars(world.writer.d.s) == vars(before[1])
                 and world.writer.d.log == before[2] and world.writer.chain == before[3])
    problems = [] if unchanged else inspect(world, before, action, again)
    if (not again.get('ok') or not again.get('dup') or again.get('events') != reply.get('events')
            or not unchanged):
        problems.append(('idempotent retry', 'second delivery changed state/ledger or lost the original acknowledgement: %r' % again))
    for field in ('lease', 'rev'):
        if again.get(field) != reply.get(field):
            problems.append(('idempotent retry', 'second delivery changed %s' % field))
    return problems


def format_witness(name, detail, sequence):
    lines = ['%s: %s' % (name, detail)]
    for n, (label, now, envelope) in enumerate(sequence, 1):
        lines.append('%d. %s; now=%s; %s' % (n, label, now, encoded(envelope)))
    return '\n'.join(lines)


def explore(depth=DEPTH):
    started = time.monotonic()
    failures, counts, coverage = {}, collections.Counter(), set()
    with tempfile.TemporaryDirectory(prefix='dispatch-states-') as run:
        world = World(run)
        try:
            root = world.checkpoint()
            queue = collections.deque([(root, ())])
            seen = {state_key(world.writer.d.s, world.now)}
            layers = collections.Counter({0: 1})
            while queue:
                checkpoint, path = queue.popleft()
                if len(path) >= depth:
                    continue
                for action in actions(checkpoint[1], checkpoint[4], len(path) + 1):
                    sequence = tuple(world.setup) + path + (action,)
                    try:
                        world.restore(checkpoint)
                        reply = world.send(action)
                        problems = inspect(world, checkpoint, action, reply)
                        if reply['ok'] and reply.get('events') and not reply.get('dup'):
                            counts['retries'] += 1
                            coverage.add('duplicate retry')
                            for name, detail in retry_check(world, action, reply):
                                failures.setdefault(name, (detail, sequence + (action,)))
                    except Exception as exc:
                        raise AssertionError(format_witness('execution/replay error', repr(exc), sequence)) from exc
                    counts['transitions'] += 1
                    counts['accepted' if reply['ok'] else 'refused'] += 1
                    counts['action:' + action[2]['kind']] += 1
                    for name, detail in problems:
                        failures.setdefault(name, (detail, sequence))
                    kind, body = action[2]['kind'], action[2]['body']
                    if reply['ok'] and not reply.get('dup'):
                        coverage.add('accepted:' + kind)
                        if kind == 'verdict':
                            coverage.add('verdict:%s:%s' % (body['pass'], body['retry']))
                    if reply.get('code') == 'children-open':
                        coverage.add('children-open refusal')
                    if reply.get('code') == 'not-addressee':
                        coverage.add('membership refusal')
                    events = world.writer.d.log[len(checkpoint[2]):]
                    if sum(e['kind'] == 'order.cancelled' for e in events) > 1:
                        coverage.add('cascading cancellation')
                    if sum(e['kind'] == 'lease.expired' for e in events) > 1:
                        coverage.add('simultaneous expiries')
                    orders = world.writer.d.s.orders
                    if all(oid in orders for oid in CHILDREN):
                        coverage.add('two children')
                    coverage.update('terminal:' + o['state'] for o in orders.values() if o['state'] in TERMINAL)
                    key = state_key(world.writer.d.s, world.now)
                    if key not in seen:
                        seen.add(key)
                        layers[len(path) + 1] += 1
                        queue.append((world.checkpoint(), path + (action,)))
            elapsed = time.monotonic() - started
            return dict(states=len(seen), depth=depth, layers=dict(sorted(layers.items())),
                        transitions=counts['transitions'], retries=counts['retries'],
                        accepted=counts['accepted'], refused=counts['refused'],
                        actions={k[7:]: v for k, v in sorted(counts.items()) if k.startswith('action:')},
                        coverage=sorted(coverage), missing_coverage=sorted(REQUIRED_COVERAGE - coverage),
                        invariants=list(INVARIANTS), seconds=round(elapsed, 3)), failures
        finally:
            world.close()


class DispatchStates(unittest.TestCase):
    def test_bounded_breadth_first_state_space(self):
        stats, failures = explore()
        print('dispatch state space: ' + encoded(stats), flush=True)
        if stats['missing_coverage']:
            failures['coverage'] = ('not exercised: %s' % stats['missing_coverage'], ())
        self.assertFalse(failures, '\n\n' + '\n\n'.join(
            format_witness(name, detail, path) for name, (detail, path) in sorted(failures.items())))


if __name__ == '__main__':
    unittest.main()
