#!/usr/bin/env python3
"""Fixed formatter acceptance set and the actual static ES-module loading chain."""
import io
import json
from pathlib import Path
import re
import runpy
import shutil
import subprocess
import sys
from email.message import Message
from types import SimpleNamespace
import unittest
from urllib.parse import urljoin

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))


class Format(unittest.TestCase):
    @unittest.skipUnless(shutil.which('node'), 'Node is needed for the formatter acceptance set')
    def test_fixed_acceptance_cases(self):
        result = subprocess.run(['node', str(ROOT / 'tests/format/run.mjs'), str(ROOT / 'web/format.mjs')],
                                cwd=ROOT, capture_output=True, text=True, timeout=30)
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
        self.assertEqual(result.stdout.strip(), '569/569')

    def test_module_serving_without_a_script_entry_file(self):
        # Exercise the production handler with python -m/runpy module globals,
        # not an HTML mock or a __main__.__file__-relative asset path. No socket,
        # agent, run folder, or external page is needed to serve static assets.
        namespace = runpy.run_module('cockpit.serve', run_name='format_asset_test')
        handler_type = namespace['Handler']

        def get(path):
            handler = handler_type.__new__(handler_type)
            handler.server = SimpleNamespace(quiet=True, server_address=('127.0.0.1', 0), origins=set())
            handler.path, handler.command, handler.request_version = path, 'GET', 'HTTP/1.1'
            handler.requestline = 'GET ' + path + ' HTTP/1.1'
            handler.headers = Message()
            handler.headers['Host'] = '127.0.0.1:0'
            handler.wfile = io.BytesIO()
            handler.do_GET()
            headers, body = handler.wfile.getvalue().split(b'\r\n\r\n', 1)
            self.assertTrue(headers.startswith(b'HTTP/1.0 200'), headers)
            return headers, body.decode('utf-8')

        _, html = get('/')
        self.assertRegex(html, r'<script\b(?=[^>]*type="module")(?=[^>]*src="/web/app.js")')
        headers, app = get('/web/app.js')
        self.assertIn(b'Content-Type: text/javascript', headers)
        imports = re.findall(r"^import\s+\*\s+as\s+\w+\s+from\s+'([^']+)';", app, re.M)
        self.assertEqual(imports, ['./format.mjs'])
        headers, module = get(urljoin('/web/app.js', imports[0]))
        self.assertIn(b'Content-Type: text/javascript', headers)
        self.assertIn(b'X-Content-Type-Options: nosniff', headers)
        self.assertEqual(module, (ROOT / 'web/format.mjs').read_text())
        functions = re.findall(r'^export function (\w+)\(', module, re.M)
        cases = json.loads((ROOT / 'tests/format/cases.json').read_text())
        self.assertEqual(set(functions), {case['fn'] for case in cases})
        self.assertEqual(len(functions), 28)


if __name__ == '__main__':
    unittest.main()
