#!/usr/bin/env python3
"""Optional private graphics: pure geometry contracts and the same-origin file boundary."""
from pathlib import Path
import shutil
import subprocess
import sys
import unittest
from unittest.mock import patch

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / 'tests'))
from test_cockpit import Base, serve


class GraphicFiles(Base):
    def test_optional_files_use_the_pro_gate_and_confined_paths(self):
        live = self.live()
        for name, mime in [('graph.js', 'text/javascript'), ('graph.css', 'text/css')]:
            code, kind, data = self.get(live, '/pro/ui/' + name)
            exists = serve.R.available() and (ROOT / 'pro' / 'ui' / name).exists()
            self.assertEqual(code, 200 if exists else 404)
            if exists:
                self.assertIn(mime, kind)
                self.assertEqual(data, (ROOT / 'pro' / 'ui' / name).read_bytes())
            self.assertEqual(self.get(live, '/pro/ui/' + name, origin='http://elsewhere.invalid')[0], 403)
        for name in ['../src/main.tsx', '%2e%2e/dist/index.html', 'missing.js', 'graph.md', '/graph.js']:
            self.assertEqual(self.get(live, '/pro/ui/' + name)[0], 404)
        # pro/ui files do not need the built pro/ page (the hero, tokens and motion parts rely on that too)
        with patch.object(serve.R, 'available', return_value=False):
            self.assertEqual(self.get(live, '/pro/ui/graph.js')[0], 200 if (ROOT / 'pro' / 'ui' / 'graph.js').exists() else 404)


@unittest.skipUnless(shutil.which('node') and (ROOT / 'pro/ui/graph.js').exists(), 'optional graphics need node and pro/ui')
class GraphicMath(unittest.TestCase):
    def test_invalid_samples_unicode_identity_and_layout_coordinates(self):
        script = r"""
import assert from 'node:assert/strict';
import fs from 'node:fs';
const source = fs.readFileSync(process.argv[1], 'utf8');
const G = await import('data:text/javascript;base64,' + Buffer.from(source).toString('base64'));
for (const [name, expected] of [['Mara Lindqvist', 'ML'], ['Cher', 'C'], ['(Ana) Ruiz', 'AR'],
  ['Christopher Montgomery III', 'CM'], [' Sam  Lee ', 'SL'], ['e\u0301', '\u00c9'],
  ['\ud83d\udc69\ud83c\udffd\u200d\ud83d\udcbb Dev', '\ud83d\udc69\ud83c\udffd\u200d\ud83d\udcbb'], ['', '']]) {
  assert.equal(G.initials(name), expected);
}
assert.equal(G.paletteIndex('e\u0301'), G.paletteIndex('\u00e9'));
const ids = ['lead', 'writer', 'reviewer', 'judge'];
const palette = Object.fromEntries(ids.map(id => [id, G.paletteIndex(id)]));
for (const id of ids.reverse()) assert.equal(G.paletteIndex(id), palette[id]);
assert.ok(Object.values(palette).every(n => n >= 0 && n < 8));
for (const samples of [[], [5], [5, 5], [1, NaN, 3, Infinity, 2], [-Number.MAX_VALUE, Number.MAX_VALUE]]) {
  const points = G.sparkPoints(samples);
  assert.equal(points.length, samples.filter(Number.isFinite).length);
  for (const p of points) { assert.ok(Number.isFinite(p.x) && Number.isFinite(p.y)); assert.ok(p.y >= 3 && p.y <= 21); }
}
assert.equal(G.sparkPoints([5])[0].x, 52);
assert.equal(G.sparkPoints([5, 5])[0].y, 12);
assert.deepEqual(G.sparkPoints([NaN, 3, 2]).map(p => p.index), [1, 2]);
const root = {contains: () => true};
const parent = {offsetLeft: 20, offsetTop: 30, clientLeft: 2, clientTop: 3, offsetParent: root};
const child = {offsetLeft: 5, offsetTop: 7, offsetWidth: 100, offsetHeight: 40, offsetParent: parent};
assert.deepEqual(G.layoutBox(child, root), {x: 27, y: 40, width: 100, height: 40});
assert.equal(G.layoutBox({...child, offsetParent: null}, root), null);
for (const points of [[[1, 2], [1, 2], [1, 3]], [[0, 0], [1, 0], [1, 1]], [[0, 0], [0, 0]]]) {
  assert.ok(!/NaN|Infinity/.test(G.roundedPath(points)));
}
console.log('graphics math passed');
"""
        result = subprocess.run(['node', '--input-type=module', '-e', script, str(ROOT / 'pro/ui/graph.js')], capture_output=True, text=True)
        self.assertEqual(result.returncode, 0, result.stderr)


if __name__ == '__main__':
    unittest.main()
