#!/usr/bin/env python3
"""Optional Home assets share the private route gate and never expose adjacent files."""
import os
import unittest
from unittest import mock

from test_cockpit import Base, ROOT, serve


class HomeAssets(Base):
    def test_optional_assets_work_without_a_built_page_and_keep_the_gate(self):
        live = self.live()
        private = os.path.join(self.tmp, 'optional')
        os.makedirs(os.path.join(private, 'ui'))
        for name in ('hero.js', 'hero.css', 'private.txt'):
            with open(os.path.join(private, 'ui', name), 'w') as f:
                f.write('/* local optional asset */')
        outside = os.path.join(self.tmp, 'outside.js')
        with open(outside, 'w') as f:
            f.write('private')
        os.symlink(outside, os.path.join(private, 'ui', 'escape.js'))
        with mock.patch.object(serve.R, 'PRO', private), mock.patch.object(serve.R, 'available', return_value=False):
            for name, mime in (('hero.js', 'text/javascript'), ('hero.css', 'text/css')):
                code, kind, raw = self.get(live, '/pro/ui/' + name)
                self.assertEqual(code, 200)
                self.assertIn(mime, kind)
                self.assertEqual(raw, b'/* local optional asset */')
                self.assertEqual(self.get(live, '/pro/ui/' + name, origin='http://elsewhere.invalid')[0], 403)
            for name in ('missing.js', 'private.txt', 'escape.js', '../outside.js', '%2e%2e/outside.js', '/outside.js', ''):
                self.assertEqual(self.get(live, '/pro/ui/' + name)[0], 404, name)
            self.assertEqual(self.get(live, '/pro/')[0], 404)
            self.assertEqual(self.get(live, '/')[0], 200)
        with mock.patch.object(serve.R, 'PRO', os.path.join(self.tmp, 'missing')):
            self.assertEqual(self.get(live, '/pro/ui/hero.js')[0], 404)
            self.assertEqual(self.get(live, '/pro/ui/hero.css')[0], 404)
            self.assertEqual(self.get(live, '/')[0], 200)

    @unittest.skipUnless(os.path.isfile(os.path.join(ROOT, 'pro', 'ui', 'hero.js')), 'optional Home assets are absent')
    def test_real_home_assets_are_served_as_written(self):
        live = self.live()
        for name in ('hero.js', 'hero.css'):
            with open(os.path.join(ROOT, 'pro', 'ui', name), 'rb') as f:
                self.assertEqual(self.get(live, '/pro/ui/' + name)[2], f.read())


if __name__ == '__main__':
    unittest.main()
