#!/usr/bin/env python3
"""Library contracts with real handlers, ledgers, git blobs and the stand-in; no sockets or models."""
import collections
import concurrent.futures
import datetime
import hashlib
import json
import os
import shutil
import sys
import tempfile
import unittest
from unittest import mock

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
sys.path.insert(0, os.path.join(ROOT, 'cockpit'))
sys.path.insert(0, HERE)

import cli
import library
import live
import opencode_agent
import planning
import serve
from test_calendar import MemoryServer, request
from test_cockpit import TEAM, FAKE


def read_json(path):
    with open(path, encoding='utf-8') as f:
        return json.load(f)


def bytes_in(folder):
    out = {}
    for root, _, names in os.walk(folder):
        for name in names:
            with open(os.path.join(root, name), 'rb') as f:
                out[os.path.relpath(os.path.join(root, name), folder)] = f.read()
    return out


class Library(unittest.TestCase):
    def test_heading_titles_preserve_bytes_custom_names_and_record_lineage(self):
        self.assertEqual(library.keep_title('```\n# Example\n```\n## Real heading ##\nBody.', 'Draft: Goal'), 'Real heading')
        self.assertEqual(library.keep_title('Release guide\n===\nBody.', 'Review: Goal'), 'Release guide')
        self.assertEqual(library.keep_title('No heading.', 'Review: Draft: Plain goal'), 'Plain goal')
        instance = self.start()
        self.handed(instance, 'one', b'# A useful heading\n\nFirst sentence. Another sentence.\n')
        doc = self.get(instance, '/order?id=one')
        self.assertEqual(doc['files'][0]['keep_title'], 'A useful heading')
        body = dict(run=os.path.basename(instance.run), order='one', path='shared/file.txt', kind='skill', title='file / Draft: Try one', tags=[])
        saved = self.post(instance, '/library/save', body)['entry']
        before = bytes_in(instance.srv.library.root)
        item = self.get(instance, '/library/item?id=' + saved['id'])
        self.assertEqual(item['display_title'], 'A useful heading')
        self.assertEqual(item['title'], body['title'])
        self.assertEqual(item['source_title'], 'Try one')
        self.assertEqual(item['first_sentence'], 'First sentence.')
        self.assertTrue(item['current'])
        self.assertEqual(bytes_in(instance.srv.library.root), before)
        self.post(instance, '/library/edit', dict(id=saved['id'], title='My chosen name', tags=[]))
        self.assertEqual(self.get(instance, '/library/item?id=' + saved['id'])['display_title'], 'My chosen name')
        with instance.srv.library.transaction() as store:
            source = dict(run=os.path.basename(instance.run), order='one', path='shared/file.txt')
            for n, status in enumerate(('recorded', 'undone')):
                instance.srv.library.add(store, library.key('repeated', n), 'lesson', 'Same lesson', status, live.CEO, source, b'Check evidence.', order='one', seat=instance.lead, reason='Check evidence.')
        lessons = [e for e in self.get(instance, '/library')['entries'] if e['kind'] == 'lesson']
        self.assertEqual(len(lessons), 2)
        self.assertEqual(lessons[0]['history_group'], lessons[1]['history_group'])
        self.assertNotEqual(lessons[0]['id'], lessons[1]['id'])

    def test_diff_line_numbers_reconstruct_both_versions(self):
        diff = library.difference('Keep\nOld\nTail\n', 'Keep\nNew\nExtra\nTail\n')
        self.assertEqual([(g['kind'], g['before_line'], g['after_line']) for g in diff['groups']],
                         [('same', 1, 1), ('remove', 2, None), ('add', None, 2), ('same', 3, 4)])

    def setUp(self):
        self.tmp = tempfile.mkdtemp(prefix='library-test-')
        self.instances, self.serial = [], 0
        self.addCleanup(self.cleanup)
        for patch in (mock.patch.object(serve, 'Server', MemoryServer),
                      mock.patch.object(live.Live, 'start', lambda instance: instance)):
            patch.start()
            self.addCleanup(patch.stop)

    def cleanup(self):
        for instance in self.instances:
            instance.srv.server_close()
        shutil.rmtree(self.tmp, ignore_errors=True)

    def start(self, extra=None, **kw):
        for previous in self.instances:
            previous.srv.server_close()
        team = json.loads(json.dumps(TEAM))
        team['pass_env'].append('FAKE_OPENCODE_LIBRARY')
        with mock.patch.dict(os.environ, {'FAKE_OPENCODE_LIBRARY': json.dumps(extra or {})}):
            instance = serve.start(self.tmp, team, exe=FAKE, every=0.1, pace=0.01,
                                   offset=len(self.instances) * 86400, **kw)
        self.instances.append(instance)
        return instance

    def get(self, instance, path):
        code, result = request(instance, 'GET', path)
        self.assertEqual(code, 200, result)
        return result

    def post(self, instance, path, body):
        code, result = request(instance, 'POST', path, body)
        self.assertEqual(code, 200, result)
        return result

    def issue(self, instance, oid, **kw):
        fields = dict(title='Try ' + oid, goal='Write and review a note.', writes='', budget=6)
        fields.update(kw)
        result = self.post(instance, '/message', planning.envelope(fields, oid, instance.lead, 'ui-' + oid))
        self.assertTrue(result['ok'], result)

    def complete(self, instance, oid):
        for _ in range(20):
            instance.once()
            if instance.ad.d.snapshot()['orders'][oid]['state'] == 'SUCCEEDED':
                return
        self.fail('stand-in order did not succeed')

    def save(self, instance, oid, kind='skill', **kw):
        body = dict(run=os.path.basename(instance.run), order=oid, path=oid + '/draft/notes.md',
                    kind=kind, title='Review checklist', tags=['review', 'text'])
        body.update(kw)
        return self.post(instance, '/library/save', body)['entry']

    def message(self, instance, kind, body, actor=None, lease=None):
        self.serial += 1
        doc = dict(v='dispatch/1', id='test-%d' % self.serial, to='dispatcher',
                   kind=kind, body=body, **{'from': actor or live.CEO})
        if lease:
            doc['lease'] = {k: lease[k] for k in ('order', 'token')}
        else:
            doc['basis'] = instance.srv.writer.d.s.head
        result = self.post(instance, '/message', doc)
        self.assertTrue(result['ok'], result)
        return result

    def handed(self, instance, oid, data, path='shared/file.txt'):
        self.issue(instance, oid, writes='shared/')
        lease = self.message(instance, 'claim.request', {'order': oid}, instance.lead)['lease']
        sha = instance.ad.git.blob(data)
        rev = instance.ad.d.snapshot()['artifacts'].get(path, 0)
        self.message(instance, 'artifact.put', {'key': path, 'expect': rev, 'note': 'git:' + sha}, instance.lead, lease)
        self.message(instance, 'report.submit', {'outputs': [{'key': path, 'rev': rev + 1}]}, instance.lead, lease)
        self.message(instance, 'verdict', {'order': oid, 'pass': True}, live.JUDGE)

    def test_keep_reuse_replace_decide_and_version_observations(self):
        first = self.start()
        self.issue(first, 'seed')
        self.complete(first, 'seed')
        old = self.save(first, 'seed', revision=1)
        old_text = self.get(first, '/library/item?id=' + old['id'])['text']
        second = self.start({'uses': 'context', 'loop': True})
        available = self.get(second, '/library')['available']
        self.assertEqual([e['id'] for e in available['skills']], [old['id']])
        self.issue(second, 'improve', title='Improve the release review')
        self.complete(second, 'improve')
        detail = self.get(second, '/order?id=improve')
        self.assertIn(old['id'], [e['id'] for e in detail['library']['uses']])
        summary = self.get(second, '/history')
        self.assertTrue(any(old['id'] in [e['id'] for e in o['library_uses']]
                            for day in summary['days'].values() for o in day['orders'] if o['id'] == 'improve'))
        proposed = detail['library']['proposed']
        new = next(e for e in proposed if e['replaces'])
        weak = next(e for e in proposed if not e['replaces'])
        comparison = self.get(second, '/library/diff?from=' + old['id'] + '&to=' + new['id'])
        current = self.get(second, '/library/item?id=' + new['id'])
        self.assertEqual(current['author']['actor'], second.lead)
        self.assertEqual(current['author']['slot'], 1)
        self.assertEqual(current['diff']['groups'], comparison['groups'])
        self.assertTrue(all(any(g['kind'] == kind for g in comparison['groups']) for kind in ('same', 'add', 'remove')))
        for kinds, text in ((('same', 'remove'), old_text), (('same', 'add'), current['text'])):
            self.assertEqual([line for g in comparison['groups'] if g['kind'] in kinds for line in g['lines']], text.splitlines())
        now = [second.srv.library.clock()]
        second.srv.library.clock = lambda: now[0]
        accepted = self.post(second, '/library/review', dict(id=new['id'], decision='accept'))['entry']
        self.assertEqual(accepted['undo']['until'], now[0] + 6)
        self.post(second, '/library/undo', dict(id=new['id'], token=accepted['undo']['token']))
        self.assertEqual(self.get(second, '/library/item?id=' + old['id'])['status'], 'accepted')
        accepted = self.post(second, '/library/review', dict(id=new['id'], decision='accept'))['entry']
        declined = self.post(second, '/library/review', dict(id=weak['id'], decision='decline'))['entry']
        self.assertEqual(declined['status'], 'rejected')
        self.post(second, '/library/undo', dict(id=weak['id'], token=declined['undo']['token']))
        self.assertEqual(self.get(second, '/library/item?id=' + weak['id'])['status'], 'proposed')
        self.post(second, '/library/review', dict(id=weak['id'], decision='decline', reason='Evidence is required.'))
        now[0] += 7
        self.assertEqual(request(second, 'POST', '/library/undo', dict(id=new['id'], token=accepted['undo']['token']))[0], 409)
        third = self.start({'uses': 'context', 'loop': True})
        self.assertEqual([e['id'] for e in self.get(third, '/library')['available']['skills']], [new['id']])
        self.issue(third, 'effect')
        self.complete(third, 'effect')
        used = self.get(third, '/order?id=effect')['library']['uses']
        self.assertIn(new['id'], [e['id'] for e in used])
        self.assertNotIn(old['id'], [e['id'] for e in used])
        item = self.get(third, '/library/item?id=' + new['id'])
        versions = {e['version']: e for e in item['versions']}
        self.assertEqual(versions[1]['text'], old_text)
        self.assertEqual(versions[1]['status'], 'superseded')
        self.assertEqual(versions[2]['reviewed_by'], live.CEO)
        for version, oid, instance in ((1, 'improve', second), (2, 'effect', third)):
            row = versions[version]['usage'][0]
            actual = self.get(third, '/order?run=' + os.path.basename(instance.run) + '&id=' + oid)
            self.assertEqual(row['order'], oid)
            self.assertEqual(row['launches'], len(actual['launches']))
            self.assertEqual(row['seconds'], actual['timing']['seconds'])
            self.assertEqual((row['outcome'], row['sent_back']), ('accepted', 0))
        self.assertEqual(request(third, 'GET', '/library/diff?from=' + old['id'] + '&to=' + weak['id'])[0], 400)

    def test_version_observations_distinguish_failure_returns_and_running(self):
        instance = self.start()
        lib = instance.srv.library
        plans = {str(n): dict(run='run', order=str(n), uses=['skill']) for n in range(3)}
        def detail(run, oid):
            n = int(oid)
            return dict(order=dict(title='Order ' + oid, state=['FAILED', 'SUCCEEDED', 'PENDING'][n]),
                        ledger=[dict(kind='order.failed')] * [2, 1, 0][n], launches=[{}] * (n + 1),
                        timing=dict(started=1000 + n, seconds=5.5 + n))
        history = mock.Mock()
        history.order.side_effect = detail
        rows = lib.observations({'plans': plans}, history)
        self.assertEqual([(e['outcome'], e['sent_back'], e['launches'], e['seconds']) for e in rows.values()],
                         [('failed', 2, 1, 5.5), ('accepted', 1, 2, 6.5), ('running', 0, 3, 7.5)])

    def test_revision_receipts_and_metadata_keep_the_original_bytes(self):
        instance = self.start()
        self.handed(instance, 'one', b'First revision\n')
        body = dict(run=os.path.basename(instance.run), order='one', path='shared/file.txt',
                    title='First', kind='skill', tags=['text'], revision=1)
        entry = self.post(instance, '/library/save', body)['entry']
        self.assertEqual(self.post(instance, '/library/save', body)['entry']['id'], entry['id'])
        self.assertEqual(self.get(instance, '/order?id=one')['library']['saved_revisions'], {'shared/file.txt@1': entry['id']})
        self.assertEqual(request(instance, 'POST', '/library/save', dict(body, revision=0))[0], 409)
        self.post(instance, '/library/edit', dict(id=entry['id'], title='Edited title', tags=['release', 'release', ' ']))
        edited = self.get(instance, '/library/item?id=' + entry['id'])
        self.assertEqual((edited['text'], edited['title'], edited['tags']), ('First revision\n', 'Edited title', ['release']))
        self.assertEqual(edited['metadata_history'][0]['title'], 'First')
        self.handed(instance, 'two', b'Second revision\n')
        new = self.post(instance, '/library/save', dict(body, order='two', revision=2))['entry']
        self.assertNotEqual(new['id'], entry['id'])
        self.assertEqual(self.get(instance, '/library/item?id=' + entry['id'])['text'], 'First revision\n')

    def test_empty_context_matches_every_launch_rules_and_excluded_channel(self):
        instance = self.start()
        empty = dict(v='library/1', skills=[], artifacts=[], workflows=[], lessons=[])
        self.assertEqual(self.get(instance, '/library/context'), empty)
        self.assertEqual(self.get(instance, '/library'), {'entries': [], 'popular': [], 'counts': dict.fromkeys(library.KINDS, 0), 'available': {'skills': [], 'artifacts': []}})
        self.assertEqual(self.get(instance, '/library/efficiency'), {'orders': []})
        self.assertEqual(request(instance, 'GET', '/library/item?id=missing')[1]['cli'], 'unknown-entry')
        checked, launch = [], opencode_agent.launch
        def check_launch(argv, box, *args, **kw):
            expected = self.get(instance, '/library/context')
            self.assertEqual(read_json(os.path.join(box, '_dispatch', 'LIBRARY.json')), expected)
            doc = read_json(os.path.join(box, '_dispatch', 'ORDER.json'))
            self.assertIn('LIBRARY.json', doc['rules'])
            if doc['seat'] == 'planner':
                for text in ('before planning', 'Reuse what fits', '"uses"', '"propose"'):
                    self.assertIn(text, doc['rules'])
            else:
                self.assertIn('follow the listed skills that fit', doc['rules'])
            checked.append(doc['seat'])
            return launch(argv, box, *args, **kw)
        self.issue(instance, 'first')
