        self.assertEqual(sum(e['kind'] == 'workflow' for e in entries), 2)
        self.assertEqual(self.get(third, '/library/item?id=' + skill['id'])['used'], 1)
        self.assertEqual(self.get(third, '/library')['counts'], dict(artifact=1, skill=1, workflow=2, lesson=0))
        self.assertEqual([o['order'] for o in self.get(third, '/library/efficiency')['orders']], ['first', 'second'])

    def test_proposals_usage_accept_replace_reject_and_atomic_review(self):
        first = self.start()
        self.issue(first, 'seed')
        self.complete(first, 'seed')
        old = self.save(first, 'seed')
        proposal = lambda title, **kw: dict(kind='skill', title=title, text='Check the inputs before writing.',
                                           replaces=None, why='Avoid repeat launches.', **kw)
        replacement = proposal('Better checklist')
        replacement['replaces'] = old['id']
        second = self.start({'uses': [old['id'], 'missing-reference', old['id']],
                             'propose': [replacement, proposal('Unhelpful'), proposal('Third'), proposal('Fourth')]})
        self.issue(second, 'learn')
        self.complete(second, 'learn')
        detail = self.get(second, '/order?id=learn')['library']
        self.assertEqual(detail['uses'], [{'id': old['id'], 'kind': 'skill', 'title': old['title'], 'version': 1}])
        proposed = detail['proposed']
        self.assertEqual(len(proposed), 3)
        self.assertEqual([s['id'] for s in self.get(second, '/library/context')['skills']], [old['id']])
        workflow = self.get(second, '/library/item?id=' + detail['workflow'])
        self.assertEqual(workflow['uses'], [old['id']])
        self.assertEqual(workflow['unknown_uses'], ['missing-reference'])
        self.assertEqual(self.get(second, '/library/item?id=' + old['id'])['used'], 1)
        new, rejected = proposed[:2]
        self.assertEqual((new['by'], new['version'], new['replaces']), (second.lead, 2, old['id']))
        self.assertEqual(new['source'], dict(run=os.path.basename(second.run), order='learn', path='_dispatch/plan.json'))
        before = bytes_in(second.srv.library.root)
        for reason in ('', '  '):
            code, result = request(second, 'POST', '/library/review', dict(id=rejected['id'], decision='reject', reason=reason))
            self.assertEqual((code, result['cli']), (400, 'reason-needed'))
            self.assertEqual(bytes_in(second.srv.library.root), before)
        # A failed atomic replacement changes neither the accepted entry nor the proposal.
        with mock.patch.object(library.os, 'replace', side_effect=OSError('test interruption')):
            code, result = request(second, 'POST', '/library/review', dict(id=new['id'], decision='accept'))
        self.assertEqual((code, result['cli']), (500, 'library-storage'))
        self.assertEqual(bytes_in(second.srv.library.root), before)
        self.post(second, '/library/review', dict(id=new['id'], decision='accept', reason='Use it.'))
        self.assertEqual(self.get(second, '/library/item?id=' + old['id'])['status'], 'superseded')
        self.assertEqual([s['id'] for s in self.get(second, '/library/context')['skills']], [new['id']])
        self.post(second, '/library/review', dict(id=rejected['id'], decision='reject', reason='This repeats the existing skill.'))
        lesson = self.get(second, '/library/context')['lessons'][0]
        self.assertEqual((lesson['order'], lesson['seat'], lesson['reason']), ('learn', second.lead, 'This repeats the existing skill.'))
        for eid in (new['id'], rejected['id'], old['id'], 'missing'):
            code, result = request(second, 'POST', '/library/review', dict(id=eid, decision='accept'))
            self.assertEqual((code, result['cli']), (400, 'not-reviewable'))
        third = self.start()
        self.assertEqual([s['id'] for s in self.get(third, '/library/context')['skills']], [new['id']])
        self.assertEqual(len(self.get(third, '/library/context')['lessons']), 1)
        expected = self.get(third, '/library/context')
        self.issue(third, 'next')
        third.once()
        self.assertEqual(read_json(os.path.join(third.ad.launches[0]['box'], '_dispatch', 'LIBRARY.json')), expected)

