    def test_retry_metrics_are_counted_from_the_ledger_and_lessons_keep_judge_words(self):
        judge = os.path.join(self.tmp, 'retry.py')
        with open(judge, 'w', encoding='utf-8') as f:
            f.write("def reads(): return {}\n"
                    "def judged(order): return order['writes']\n"
                    "def judge(order, files, revs):\n"
                    "    if order['id'].endswith('.draft') and max(revs.values(), default=0) == 1:\n"
                    "        return False, 'Check the heading before handing this in.'\n"
                    "    return True, 'Checked.'\n")
        instance = self.start(judge=judge)
        self.issue(instance, 'retry')
        self.complete(instance, 'retry')
        run = os.path.basename(instance.run)
        ledger = cli.read_ledger(instance.run)
        family = {'retry', 'retry.draft', 'retry.review'}
        counts = collections.Counter(e['order'] for e in ledger if e['kind'] == 'lease.granted' and e['order'] in family)
        issued = next(e for e in ledger if e['kind'] == 'order.issued' and e['body']['id'] == 'retry')
        ended = next(e for e in ledger if e['kind'] == 'order.succeeded' and e['order'] == 'retry')
        metrics = dict(state='SUCCEEDED', launches=sum(counts.values()),
                       sent_back=sum(max(n - 1, 0) for n in counts.values()), seconds=ended['t'] - issued['t'])
        self.assertEqual((metrics['launches'], metrics['sent_back']), (4, 1))
        entry = self.get(instance, '/library')['entries'][0]
        self.assertEqual(entry['metrics'], metrics)
        self.assertEqual(entry['steps'], [dict(order=e['body']['id'], seat=e['body']['to'],
                         **{k: e['body'][k] for k in ('title', 'after', 'reads', 'writes')})
                         for e in ledger if e['kind'] == 'order.issued' and e['body'].get('parent') == 'retry'])
        lessons = self.get(instance, '/library/context')['lessons']
        self.assertEqual(len(lessons), 1)
        self.assertEqual(lessons[0]['reason'], next(e['reason'] for e in ledger if e['kind'] == 'order.failed'))
        self.assertEqual((lessons[0]['order'], lessons[0]['seat']), ('retry.draft', 'agent:writer'))
        self.assertEqual(self.get(instance, '/library/efficiency')['orders'],
                         [dict(run=run, order='retry', title='Try retry', ended=library.iso(ended['t']), uses=[], **metrics)])

    def test_old_runs_backfill_all_final_states_once_after_two_restarts(self):
        first = self.start()
        self.issue(first, 'success')
        self.complete(first, 'success')
        self.issue(first, 'cancelled')
        self.message(first, 'order.cancel', {'order': 'cancelled', 'reason': 'No longer needed.'})
        self.issue(first, 'failed')
        lease = self.message(first, 'claim.request', {'order': 'failed'}, first.lead)['lease']
        self.message(first, 'report.submit', {}, first.lead, lease)
        self.message(first, 'verdict', {'order': 'failed', 'pass': False, 'retry': False, 'reason': 'Missing evidence.'}, live.JUDGE)
        self.issue(first, 'dead')
        for _ in range(3):
            self.message(first, 'claim.request', {'order': 'dead', 'ttl': 1}, first.lead)
            first.guard.skew += 2
            first.ad.d.tick(first.now())
        self.assertEqual(first.ad.d.snapshot()['orders']['dead']['state'], 'DEAD')
        first.srv.server_close()
        shutil.rmtree(first.srv.library.root)  # Simulate an older installation, before the library existed.
        second = self.start()
        entries = self.get(second, '/library')['entries']
        workflows = [e for e in entries if e['kind'] == 'workflow']
        self.assertEqual({e['metrics']['state'] for e in workflows}, set(library.FINAL))
        self.assertEqual(len(workflows), 4)
        self.assertEqual(len([e for e in entries if e['kind'] == 'lesson']), 2)
        third = self.start()
        self.assertEqual(self.get(third, '/library')['entries'], entries)

    def test_historical_revision_binary_and_large_text_are_exact(self):
        instance = self.start()
        original = b'Original handed-in bytes.\r\n'
        self.handed(instance, 'old', original)
        self.handed(instance, 'new', b'New contents at the same path.\n')
        saved = self.save(instance, 'old', path='shared/file.txt')
        self.assertEqual(self.get(instance, '/library/item?id=' + saved['id'])['text'].encode(), original)
        self.assertEqual(saved['sha256'], hashlib.sha256(original).hexdigest())
        binary = bytes(range(256)) * 400
        self.handed(instance, 'binary', binary)
        entry = self.save(instance, 'binary', kind='artifact', path='shared/file.txt')
        self.assertEqual((entry['sha256'], entry['bytes']), (hashlib.sha256(binary).hexdigest(), len(binary)))
        self.assertLessEqual(len(self.get(instance, '/library/item?id=' + entry['id'])['text'].encode()), 65536)
        text = ('A paragraph. ' * 7000).encode()
        self.handed(instance, 'large', text)
        entry = self.save(instance, 'large', path='shared/file.txt')
        self.assertEqual(entry['sha256'], hashlib.sha256(text).hexdigest())
        self.assertEqual(len(self.get(instance, '/library/item?id=' + entry['id'])['text'].encode()), 65536)
        # A skill that cannot fit is omitted whole; its stored bytes are still intact.
        self.assertEqual(self.get(instance, '/library/context')['skills'], [])

    def test_context_limits_oldest_first_and_newest_accepted_chain(self):
        instance = self.start()
        store = instance.srv.library
        with store.transaction() as doc:
            source = dict(run='fixture', order='fixture', path=None)
            for n in range(12):
                store.add(doc, 'workflow-%d' % n, 'workflow', 'Flow %d' % n, 'recorded', 'program:library', source, at=n)
            for n in range(22):
                store.add(doc, 'lesson-%d' % n, 'lesson', 'Lesson %d' % n, 'recorded', 'program:library', source,
                          at=n, order='fixture', seat='team:lead', reason='A review note.')
            old = store.add(doc, 'old', 'skill', 'Old skill', 'accepted', live.CEO, source, b'Old', at=30)
            new = store.add(doc, 'new', 'skill', 'New skill', 'accepted', live.CEO, source, b'New', at=31, replaces=old['id'], version=2)
            for status in ('proposed', 'rejected', 'superseded'):
                store.add(doc, status, 'skill', status, status, live.CEO, source, b'Never given', at=32)
        context = store.context()
        self.assertEqual(len(context['workflows']), 10)
        self.assertEqual(len(context['lessons']), 20)
        self.assertEqual(context['workflows'][-1]['title'], 'Flow 2')
        self.assertEqual([e['id'] for e in context['skills']], [new['id']])
        with store.transaction() as doc:
            for n in range(10):
                store.add(doc, 'large-%d' % n, 'skill', 'Large %d' % n, 'accepted', live.CEO, None, b'x' * 8000, at=40 + n)
        context = store.context()
        self.assertLessEqual(len(library.encoded(context)), 65536)
        self.assertEqual([s['title'] for s in context['skills']], ['Large %d' % n for n in range(9, 1, -1)])
        self.assertEqual(context['workflows'], [])
        self.assertEqual(context['lessons'], [])
        # A second Library instance sees the same durable snapshot, without a process-local cache.
        self.assertEqual(library.Library(self.tmp, instance.now).context(), context)

