"""Optional private assets use the existing origin gate and never escape their folder."""
import os
import json
import unittest
from unittest.mock import patch
from pathlib import Path
from test_cockpit import Base, serve


class OptionalUI(Base):
    def test_page_advertises_only_complete_local_ui_components(self):
        live = self.live()
        root = Path(self.tmp, 'local-components')
        ui = root / 'ui'
        with patch.object(serve.R, 'PRO', str(root)), patch.object(serve.R, 'available', return_value=False):
            self.assertNotIn(b'name="cockpit-ui"', self.get(live, '/')[2])
            ui.mkdir(parents=True)
            for name in ('graph.js', 'board.css', 'keys.js', 'keys.css', 'motion.js', 'hero.js', 'hero.css'):
                (ui / name).touch()
            outside = root / 'outside.css'
            outside.touch()
            (ui / 'motion.css').symlink_to(outside)
            for path in ('/', '/web/index.html'):
                page = self.get(live, path)[2]
                self.assertIn(b'<meta name="cockpit-ui" content="keys hero">', page)
                self.assertIn(b' id="pro-link" hidden', page)
            (ui / 'board.js').touch()
            (ui / 'hero.js').unlink()
            self.assertIn(b'<meta name="cockpit-ui" content="board keys">', self.get(live, '/')[2])

    def test_order_history_includes_answers_to_its_asks_only(self):
        live = self.live()
        order = {'id': 'o1', 'title': 'Order', 'state': 'PENDING', 'to': 'team:lead'}
        rows = [{'seq': 1, 't': 1000, 'kind': 'order.issued', 'by': 'human:ceo', 'body': order},
                {'seq': 2, 't': 1001, 'kind': 'ask.raised', 'ask': 'q1', 'about': 'o1'},
                {'seq': 3, 't': 1002, 'kind': 'ask.answered', 'ask': 'unrelated'},
                {'seq': 4, 't': 1003, 'kind': 'ask.answered', 'ask': 'q1'}]
        record = {'orders': {'o1': order}, 'events': rows, 'issued': {'o1': rows[0]}, 'tops': {'o1': 'o1'}}
        # Exercise the real order assembly: it owns the indexed answer join.
        with patch.object(live.srv.history, 'read', return_value=record), \
                patch.object(live.srv.library, 'sync'):
            code, _, body = self.get(live, '/order?id=o1')
        self.assertEqual(code, 200)
        self.assertEqual([e['seq'] for e in json.loads(body)['ledger']], [1, 2, 4])

    def test_files_work_without_a_built_pro_page_and_missing_files_are_404(self):
        live = self.live()
        root = Path(self.tmp, 'optional')
        ui = root / 'ui'
        ui.mkdir(parents=True)
        (ui / 'sample.js').write_text('export const ready = true;\n')
        (ui / 'sample.css').write_text('.sample { color: inherit; }\n')
        (ui / 'private.txt').write_text('not a UI asset')
        outside = Path(self.tmp, 'outside.js')
        outside.write_text('outside')
        os.symlink(outside, ui / 'escape.js')
        with patch.object(serve.R, 'PRO', str(root)), patch.object(serve.R, 'available', return_value=False):
            for name, kind in [('sample.js', 'text/javascript'), ('sample.css', 'text/css')]:
                code, mime, body = self.get(live, '/pro/ui/' + name)
