            for name in ('missing.js', '../outside.js', '%2e%2e/outside.js', '/sample.js', 'escape.js', 'private.txt'):
                self.assertEqual(self.get(live, '/pro/ui/' + name)[0], 404, name)
            self.assertEqual(self.get(live, '/')[0], 200)
        with patch.object(serve.R, 'PRO', str(root / 'missing')):
            self.assertEqual(self.get(live, '/pro/ui/motion.js')[0], 404)
            self.assertEqual(self.get(live, '/')[0], 200)


