#!/usr/bin/env python3
"""Order response parity and cached-replay latency, without sockets or models."""
import json
import sys
import tempfile
import threading
import time
import types
import unittest
from pathlib import Path
from unittest import mock

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parent / 'cockpit'))
sys.path.insert(0, str(HERE))

import cli
import dispatcher
import gitws
import history
import library
from order_reference import legacy_order
from test_calendar import MemoryServer, request
from test_cockpit import TEAM


class Run:
    """All ledger rows come from accepted Dispatcher envelopes."""
    def __init__(self, root):
        self.path = Path(root) / 'fixture'
        self.path.mkdir()
        self.d = dispatcher.Dispatcher()
        self.n = 0
        self.now = 1800000000
        self.send('human:ceo', 'org.set', actor='team:lead', superior='human:ceo')
        self.send('human:ceo', 'org.set', actor='agent:writer', superior='team:lead')

    def send(self, sender, kind, lease=None, **body):
        self.n += 1
        m = dispatcher.msg('m%d' % self.n, sender, kind, body, basis=self.d.s.head, lease=lease)
        answer = self.d.submit(m, self.now)
        if not answer['ok']:
            raise AssertionError((m, answer))
        return answer

    def issue(self, oid, parent=None, lease=None, to='team:lead', budget=1000):
        self.send('human:ceo' if parent is None else self.d.s.leases[parent]['holder'], 'order.issue', lease,
                  id=oid, parent=parent, title='Order ' + oid, goal='Complete ' + oid, to=to,
                  writes=[oid.replace('.', '/') + '/'], budget=budget,
                  accept={'judge': 'program:judge', 'criteria': 'Review the work'})

    def claim(self, oid, actor='agent:writer'):
        return self.send(actor, 'claim.request', order=oid)['lease']

    def attach(self):
        (self.path / cli.LEDGER).write_text(''.join(json.dumps(e) + '\n' for e in self.d.log))
        (self.path / 'team.json').write_text(json.dumps(TEAM))
        gate = threading.RLock()
        server = MemoryServer(gate, str(self.path), 0, lambda: self.now)
        server.history = history.History(str(self.path.parent), self.path.name, lambda: self.now)
        server.library = library.Library(str(self.path.parent), lambda: self.now)
        server.history.library = server.library
        instance = types.SimpleNamespace(gate=gate, srv=server)
        server.live = instance
        return instance


class OrderIndex(unittest.TestCase):
    def setUp(self):
        tmp = tempfile.TemporaryDirectory(prefix='order-index-')
        self.addCleanup(tmp.cleanup)
        self.run = Run(tmp.name)

    def attach(self):
        instance = self.run.attach()
        self.addCleanup(instance.srv.server_close)
        return instance

    def get(self, instance, oid='root'):
        code, doc = request(instance, 'GET', '/order?run=fixture&id=' + oid)
        self.assertEqual(code, 200, doc)
        return doc

    def test_family_response_matches_before_indexing(self):
        r = self.run
        r.send('human:ceo', 'org.set', actor='agent:helper', superior='agent:writer')
        r.issue('root')
        root = r.claim('root', 'team:lead')
        for name in ('accepted', 'failed', 'cancelled', 'released', 'branch'):
            r.issue('root.' + name, 'root', root, 'agent:writer', budget=10)
        git = gitws.Git(str(r.path / 'repo.git'))
        base = git.init(r.now)
        blob = git.blob(b'# Finished work\nEvidence for the family.\n')
        key = 'root/accepted/note.md'
        lease = r.claim('root.accepted')
        r.send('agent:writer', 'artifact.put', lease, key=key, expect=0, note='git:' + blob)
        r.send('agent:writer', 'report.submit', lease, outputs=[{'key': key, 'rev': 1}], evidence='Ready')
        r.send('program:judge', 'verdict', order='root.accepted', **{'pass': False, 'retry': True, 'reason': 'Add evidence'})
        lease = r.claim('root.accepted')
        r.send('agent:writer', 'report.submit', lease, outputs=[{'key': key, 'rev': 1}], evidence='Added evidence')
        r.send('program:judge', 'verdict', order='root.accepted', **{'pass': True})
        commit = git.commit([base], {key: blob}, 'Accepted work', r.now)
        git('update-ref', 'refs/tags/accepted/' + history.live.TOPIC, commit)
        lease = r.claim('root.failed')
        r.send('agent:writer', 'report.submit', lease, outputs=[], evidence='No files')
        r.send('program:judge', 'verdict', order='root.failed', **{'pass': False, 'retry': False, 'reason': 'Missing files'})
        r.send('human:ceo', 'order.cancel', order='root.cancelled', reason='No longer needed')
        lease = r.claim('root.released')
        r.send('agent:writer', 'lease.release', lease, reason='Available again')
        branch = r.claim('root.branch')
        r.issue('root.branch.leaf', 'root.branch', branch, 'agent:helper', budget=1)
        leaf = r.claim('root.branch.leaf', 'agent:helper')
        r.send('agent:helper', 'report.submit', leaf, outputs=[], evidence='Review pending')
        r.issue('unrelated')
        for oid in ('root', 'root.accepted', 'root.branch.leaf', 'unrelated'):
            reply = r.send('agent:writer', 'ask.raise', order=oid, to='human:ceo', text='Which option?', blocking=False)
            r.send('human:ceo', 'ask.answer', ask=reply['re'], answer='First option')
        r.send('agent:writer', 'ask.raise', order='root.released', to='human:ceo', text='Still open', blocking=True)
        instance = self.attach()
        h = instance.srv.history
        instance.srv.library.sync(h)
        for current in ('fixture', 'another-run'):
            h.current = current
            for oid in ('root', 'root.branch', 'root.accepted', 'root.failed', 'root.cancelled'):
                with self.subTest(current=current, oid=oid):
                    expected = legacy_order(h, 'fixture', oid)
                    asks = {e['ask'] for e in expected['ledger'] if e['kind'] == 'ask.raised'}
                    answers = [e for e in h.read('fixture')['events'] if e['kind'] == 'ask.answered' and e.get('ask') in asks]
                    expected['ledger'] = sorted(expected['ledger'] + answers, key=lambda e: e['seq'])
                    self.assertEqual(self.get(instance, oid), expected)
        doc = self.get(instance)
        self.assertEqual(len(doc['children']), 5)
        self.assertEqual(len(doc['nodes']), 7)
        self.assertEqual(sum(e['kind'] == 'ask.answered' for e in doc['ledger']), 3)
        self.assertEqual(doc['files'][0]['path'], key)
        self.assertTrue(doc['files'][0]['accepted'])
        self.assertEqual(doc['order']['problem']['reason'], 'Missing files')

    def test_order_uses_one_run_read(self):
        self.run.issue('root')
        instance = self.attach()
        h = instance.srv.history
        class CountedEvents(list):
            scans = 0

            def __iter__(self):
                self.scans += 1
                return super().__iter__()

        record = h.read('fixture')
        events = record['events'] = CountedEvents(record['events'])
        # Library backfill is a separate preflight; this measures order assembly,
        # including its file lookup, rather than the shared library's run scan.
        with mock.patch.object(h, 'read', wraps=h.read) as read:
            h.order('fixture', 'root')
        self.assertEqual(read.call_count, 1, 'Order and files must share the same replay')
        self.assertEqual(events.scans, 1, 'The full ledger is indexed in one pass')

    def test_large_family_get_under_two_seconds(self):
        r = self.run
        r.issue('root')
        root = r.claim('root', 'team:lead')
        for i in range(400):
            oid = 'root.c%d' % i
            r.issue(oid, 'root', root, 'agent:writer', budget=1)
            lease = r.claim(oid)
            for j in range(200):
                r.send('agent:writer', 'report.progress', lease, note='Progress %d' % j, pct=j % 100)
            r.send('agent:writer', 'lease.release', lease, reason='Paused')
        self.assertEqual(len(r.d.log), 81204)
        instance = self.attach()
        instance.srv.history.read('fixture')  # Same cached-replay condition as the review repro.
        started = time.perf_counter()
        doc = self.get(instance)
        elapsed = time.perf_counter() - started
        print('GET /order: 400 children, 81204 events, %.3f s (bound 2.0 s)' % elapsed, flush=True)
        self.assertEqual(len(doc['nodes']), 401)
        self.assertEqual(len(doc['ledger']), 81202)
        self.assertLess(elapsed, 2.0, 'A family must not rescan the run for every node')


if __name__ == '__main__':
    unittest.main()
