#!/usr/bin/env python3
"""The page files and the icons, read as text (no browser): what is served exists, nothing is fetched from elsewhere,
there is one light theme, text only ever enters the page as text, and web/icons.js is what icons/ gives."""
import hashlib
import colorsys
import math
import datetime
import json
import os
from pathlib import Path
import re
import shutil
import subprocess
import sys
import tempfile
import unittest
from unittest import mock

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
sys.path.insert(0, os.path.join(ROOT, 'cockpit'))
sys.path.insert(0, os.path.join(ROOT, 'tools'))

import history as H
import live as L                    # noqa: E402
import library as B
import make_icons as M              # noqa: E402
import serve                        # noqa: E402

WEB = os.path.join(ROOT, 'web')
ICONS = os.path.join(ROOT, 'icons')
SVG_NS = 'http://www.w3.org/2000/svg'
WHITE = ('#fff', '#ffffff')


def text(*parts):
    with open(os.path.join(ROOT, *parts), encoding='utf-8') as f:
        source = f.read()
        return css_for_assertions(source) if parts[-1].endswith('.css') else source


def css_for_assertions(source):
    """Compare declaration values independently of units, tokens and spacing.

    Only fixed tokens from the first root rule are expanded; view-dependent
    colours and typography stay symbolic. Browser probes cover the cascade.
    """
    root_match = re.search(r':root\s*\{([^}]+)\}', source)
    root = root_match[1] if root_match else ''
    fixed_names = {'--track', '--weight-medium', '--weight-heading', '--number-style', '--code-font'}
    fixed_names.update('--space-' + str(n) for n in (1, 2, 3, 4, 5, 6, 8))
    fixed = {key: value.strip() for key, value in re.findall(r'(--[\w-]+):\s*([^;]+);', root) if key in fixed_names}

    def rule(match):
        declarations = []
        for declaration in match[1].split(';'):
            if ':' not in declaration:
                continue
            key, value = declaration.strip().split(':', 1)
            value = value.strip()
            if not key.startswith('--'):
                value = re.sub(r'var\((--[\w-]+)\)', lambda m: fixed.get(m[1], m[0]), value)
                value = re.sub(r'([\d.]+)pt\b', lambda m: '%gpx' % (float(m[1]) * 4 / 3), value)
                value = value.replace('#0000', 'transparent').replace('minmax(0px,', 'minmax(0,')
                value = re.sub(r'^solid ([\d.]+px) ', r'\1 solid ', value)
                if key == 'font-weight':
                    value = {'normal': '400', 'bold': '700'}.get(value, value)
                if key == 'flex' and value == '0 0 auto':
                    value = 'none'
                if key == 'grid-column':
                    value = re.sub(r'\s*/\s*', ' / ', value)
            value = re.sub(r'rgb\(([^ /]+) ([^ /]+) ([^ /]+) / ([^)]+)\)', r'rgba(\1, \2, \3, \4)', value)
            key = {'word-wrap': 'overflow-wrap', 'text-decoration-line': 'text-decoration'}.get(key, key)
            declarations.append(key + ': ' + value + ';')
        return '{ ' + ' '.join(declarations) + ' }'

    source = re.sub(r'\{([^{}]*)\}', rule, source)
    return re.sub(r'\[([\w-]+)=([a-zA-Z][\w-]*)\]', r'[\1="\2"]', source)


def css_value(body, property_name):
    return dict(item.strip().split(': ', 1) for item in body.split(';') if ': ' in item).get(property_name)


def icons():
    s = text('web', 'icons.js')
    return json.loads(s[s.index('{'):s.rindex('}') + 1])


def short_hex(value):
    """Unit-testable twin of shortHex: shorten each long hex run, not the surrounding path."""
    return re.sub(r'[a-f0-9]{16,}', lambda m: m.group(0)[:8] + '\u2026', str(value), flags=re.I)


def luminance(colour):
    channels = [int(colour[i:i + 2], 16) / 255 for i in (1, 3, 5)]
    linear = [c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4 for c in channels]
    return sum(c * w for c, w in zip(linear, (0.2126, 0.7152, 0.0722)))


def css_paints(css):
    """Resolve root colour tokens without losing alpha from the ink ramp."""
    root = re.search(r':root\s*\{([^}]+)\}', re.sub(r'/\*.*?\*/', '', css, flags=re.S)).group(1)
    values = dict(re.findall(r'(--[\w-]+):\s*([^;]+);', root))
    cache = {}
    def resolve(name):
        if name in cache:
            return cache[name]
        value = values[name].strip()
        if re.fullmatch(r'#[0-9a-f]{6}', value):
            colour = [int(value[i:i + 2], 16) for i in (1, 3, 5)] + [1]
        elif value.startswith(('rgb(', 'rgba(')):
            colour = list(map(float, re.findall(r'[\d.]+', value)))
            if len(colour) == 3:
                colour.append(1)
        elif value.startswith('oklch('):
            light, chroma, hue = map(float, re.findall(r'[\d.]+', value))
            a, b = chroma * math.cos(math.radians(hue)), chroma * math.sin(math.radians(hue))
            l, m, s = (light + .3963377774 * a + .2158037573 * b) ** 3, (light - .1055613458 * a - .0638541728 * b) ** 3, (light - .0894841775 * a - 1.291485548 * b) ** 3
            linear = (4.0767416621 * l - 3.3077115913 * m + .2309699292 * s, -1.2684380046 * l + 2.6097574011 * m - .3413193965 * s, -.0041960863 * l - .7034186147 * m + 1.707614701 * s)
            colour = [255 * max(0, min(1, 12.92 * c if c <= .0031308 else 1.055 * c ** (1 / 2.4) - .055)) for c in linear] + [1]
        elif re.fullmatch(r'var\(--[\w-]+\)', value):
            colour = resolve(value[4:-1])
        else:
            match = re.fullmatch(r'color-mix\(in srgb, var\((--[\w-]+)\) ([\d.]+)%, (transparent|var\((--[\w-]+)\))\)', value)
            if not match:
                raise ValueError(name)
            colour = resolve(match[1])[:]
            alpha = float(match[2]) / 100
            if match[3] == 'transparent':
                colour[3] *= alpha
            else:
                back = resolve(match[4])
                total = colour[3] * alpha + back[3] * (1 - alpha)
                colour = [(colour[i] * colour[3] * alpha + back[i] * back[3] * (1 - alpha)) / total for i in range(3)] + [total]
        cache[name] = colour
        return colour
    for name in values:
        try:
            resolve(name)
        except ValueError:
            pass
    return cache


def css_colours(css):
    # Existing hue and lightness checks concern colours painted on white cards.
    return {name: '#' + ''.join('%02x' % round(c * value[3] + 255 * (1 - value[3])) for c in value[:3])
            for name, value in css_paints(css).items()}


