    def test_dense_blocks_and_semantic_surfaces_have_explicit_contracts(self):
        js, css = text('web', 'app.js'), text('web', 'app.css')
        page = text('web', 'index.html') + js
        for name in ('run-meter', 'meter', 'week', 'week-day', 'seat-spark', 'order-steps', 'order-seats',
                     'home-library', 'home-entry', 'home-files', 'home-file', 'team-stats', 'team-stat',
                     'seat-chip', 'seat-tone', 'kind-chip', 'seat-summary', 'gantt-label'):
            self.assertIn('data-' + name, page)
        def rule(selector):
            return re.search(r'(?m)^' + re.escape(selector) + r'\s*\{([^}]+)\}', css).group(1)
        for selector in ('.home-row', '.team-overview'):
            self.assertEqual(css_value(rule(selector), 'display'), 'grid')
            self.assertEqual(css_value(rule(selector), 'grid-template-columns'), 'minmax(0, 2fr) minmax(0, 1fr)')
            self.assertEqual(css_value(rule(selector), 'gap'), '16px')
        self.assertEqual(css_value(rule('[data-activity]'), 'max-height'), '240px')
        self.assertEqual(css_value(rule('[data-activity]'), 'overflow-y'), 'auto')
        self.assertEqual(css_value(rule('[data-gantt-row]'), 'align-items'), 'center')
        self.assertEqual(css_value(rule('.seat-chip'), 'color'), 'var(--ink-2)')
        self.assertEqual(css_value(rule('.seat-chip'), 'background'), 'transparent')
        self.assertEqual(css_value(rule('.seat-chip'), 'max-width'), '100%')
        self.assertEqual(css_value(rule('.home-entry'), 'min-width'), '0')
        self.assertEqual(js.count('function seatSummary('), 1)
        self.assertEqual(js.count('function seatCard('), 1)
        self.assertEqual(js.count('function statTile('), 1)
        tokens = css_colours(css)
        pairs = [('seat-%d' % i) for i in range(1, 7)] + ['you', 'judge'] + ['kind-' + k for k in B.KINDS]
        inks = set()
        for name in pairs:
            ink, wash = tokens['--' + name + '-ink'], tokens['--' + name + '-wash']
            inks.add(ink)
            for bg in (wash, tokens['--paper']):
                self.assertGreaterEqual((luminance(bg) + .05) / (luminance(ink) + .05), 4.5, name)
        inks.update(tokens[k] for k in ('--time', '--mono-ink', '--ok', '--bad', '--wait', '--run'))
        self.assertGreaterEqual(len(inks), 14)

