    def test_seat_outcomes_count_orders_and_keep_returns_after_acceptance(self):
        seats = [{'id': 'lead', 'actor': 'team:lead'}, {'id': 'writer', 'actor': 'agent:writer'},
                 {'id': 'reviewer', 'actor': 'agent:reviewer'}]
        orders = {'root': {'to': 'team:lead', 'state': 'SUCCEEDED'},
                  'step': {'parent': 'root', 'to': 'team:writer', 'state': 'SUCCEEDED'},
                  'later': {'to': 'team:lead', 'state': 'PENDING'}}
        events = [{'kind': 'lease.granted', 'order': 'step', 'by': 'agent:writer'},
                  {'kind': 'report.submitted', 'order': 'step', 'by': 'agent:writer'},
                  {'kind': 'order.failed', 'order': 'step'}, {'kind': 'order.failed', 'order': 'step'},
                  {'kind': 'lease.granted', 'order': 'step', 'by': 'agent:reviewer'},
                  {'kind': 'order.succeeded', 'order': 'step'}]
        seats_before = json.dumps(seats)
        got, totals = L.outcome_counts(orders, events, seats)
        self.assertEqual(got, {'team:lead': {'accepted': 1, 'sent_back': 0},
                              'agent:writer': {'accepted': 0, 'sent_back': 1},
                              'agent:reviewer': {'accepted': 1, 'sent_back': 0}})
        self.assertEqual(totals, {'orders': 2, 'accepted': 1, 'steps': 1, 'steps_accepted': 1,
                                  'all_accepted': 2, 'sent_back': 1})
        self.assertEqual(json.dumps(seats), seats_before)
        self.assertTrue(all(v == 0 for v in L.outcome_counts({}, [], seats)[1].values()))

    def test_week_uses_server_date_across_month_and_year_boundaries(self):
        for today, monday in [('2030-04-10', '2030-04-08'), ('2028-03-01', '2028-02-28'),
                              ('2030-01-01', '2029-12-31'), ('2030-04-14', '2030-04-08')]:
            stamp = datetime.datetime.fromisoformat(today + 'T12:00:00').timestamp()
            history = H.History(ROOT, 'run', lambda: stamp)
            with mock.patch.object(history, 'runs', return_value=({}, [])):
                got = history.summary({})
            self.assertEqual(got['today'], today)
            self.assertEqual(got['week'], [(datetime.date.fromisoformat(monday) + datetime.timedelta(days=i)).isoformat() for i in range(7)])
            self.assertEqual(got['days'], {}, 'Week dates do not invent orders or day statistics')

