    def test_blue_accent_and_washes_have_aa_contrast(self):
        tokens = css_colours(text('web', 'app.css'))
        for name in ('--accent', '--accent-side', '--accent-edge'):
            colour = tokens[name]
            hue, _, saturation = colorsys.rgb_to_hls(*(int(colour[i:i + 2], 16) / 255 for i in (1, 3, 5)))
            hue *= 360
            self.assertGreaterEqual(hue, 212)
            self.assertLessEqual(hue, 226)
            self.assertGreaterEqual(saturation, .55)
            self.assertGreaterEqual(1.05 / (luminance(colour) + .05), 4.5)
        wash = tokens['--accent-wash']
        hue = colorsys.rgb_to_hls(*(int(wash[i:i + 2], 16) / 255 for i in (1, 3, 5)))[0] * 360
        self.assertGreaterEqual(hue, 212)
        self.assertLessEqual(hue, 226)
        self.assertGreaterEqual((luminance(wash) + .05) / (luminance(tokens['--accent']) + .05), 4.5)
        self.assertNotIn('--hero-violet', tokens)

    def test_quiet_borders_stay_close_to_their_surface(self):
        paints = css_paints(text('web', 'app.css'))
        for surface in ('--paper', '--canvas'):
            background = paints[surface][:3]
            lightness = colorsys.rgb_to_hls(*(v / 255 for v in background))[1]
            for token in ('--line', '--line-2'):
                colour = paints[token]
                painted = [v * colour[3] + b * (1 - colour[3]) for v, b in zip(colour, background)]
                border_lightness = colorsys.rgb_to_hls(*(v / 255 for v in painted))[1]
                self.assertLessEqual(abs(lightness - border_lightness), .06, (token, surface))

