    def test_connectors_share_blue_ink_and_white_ring_ends(self):
        css = text('web', 'app.css')
        tokens = css_colours(css)
        hue, lightness, saturation = colorsys.rgb_to_hls(*(int(tokens['--edge'][i:i + 2], 16) / 255 for i in (1, 3, 5)))
        self.assertGreaterEqual(hue * 360, 212)
        self.assertLessEqual(hue * 360, 226)
        self.assertGreaterEqual(saturation, .70)
        self.assertGreaterEqual(lightness, .45)
        self.assertLessEqual(lightness, .55)
        self.assertGreaterEqual(1.05 / (luminance(tokens['--edge']) + 0.05), 3)
        rules = re.findall(r'([^{}]+)\{([^{}]*)\}', re.sub(r'/\*.*?\*/', '', css, flags=re.S))

        def rule(selector):
            return next(body for head, body in rules if head.strip() == selector)

        for selector in ('.diagram-edge', '[data-flow-edge]'):
            body = rule(selector)
            for declaration in ('stroke: var(--edge)', 'stroke-width: 2', 'fill: none',
                                'stroke-linejoin: round', 'stroke-linecap: round'):
                self.assertIn(declaration, body)
        self.assertEqual(css_value(rule('.flow-arrow'), 'fill'), 'var(--edge)')
        for declaration in ('fill: var(--paper)', 'stroke: var(--edge)', 'stroke-width: 2', 'pointer-events: none'):
            self.assertIn(declaration, rule('[data-edge-end]'))
        self.assertEqual(css_value(rule('[data-org-edge][data-judge]'), 'stroke-dasharray'), '5 5')
        self.assertEqual(css_value(rule('[data-flow-edge][data-kind="waits-for"]'), 'stroke-dasharray'), '4 4')
        for selector, body in rules:
            if re.search(r'diagram-edge|data-(?:org-edge|handoff-edge|flow-edge|edge-end)|flow-arrow', selector):
                self.assertNotRegex(body, r'--(?:ink-3|line-2|accent)\b', selector)
            if 'var(--edge)' in body:
                self.assertIn(selector.strip(), ('.diagram-edge', '[data-flow-edge]', '.flow-arrow', '[data-edge-end]', '.flow-legend path', 'button[data-canvas-node][aria-pressed="true"]'))
                self.assertNotRegex(body, r'(?:^|;)\s*(?:color|background(?:-color)?)\s*:')
        # The bottom endpoint is on the SVG boundary; its ring must paint over
        # the positioned card border, with pointer events still reaching paths.
        self.assertEqual(css_value(rule('.handoff-wires'), 'overflow'), 'visible')
        self.assertEqual(css_value(rule('.handoff-wires'), 'z-index'), '1')
        self.assertEqual(css_value(rule('.handoff-wires .diagram-edge'), 'pointer-events'), 'stroke')
        dim = ':is([data-org-edge], [data-handoff-edge], [data-flow-edge], [data-edge-end])[data-dim]'
        self.assertEqual(css_value(rule(dim), 'opacity'), '0.4 !important')

    def test_second_pass_layout_and_focus_styles(self):
        css = text('web', 'app.css')
        def rule(selector):
            return re.search(r'(?m)^' + re.escape(selector) + r'\s*\{([^}]+)\}', css).group(1)
        self.assertEqual(css_value(rule('.handoff-card'), 'margin'), '0 6px')
        self.assertEqual(css_value(rule('.handoff-cards'), 'gap'), '0')
        # Equal slots inset by 6px per side leave exactly 12px between cards,
        # and keep the path endpoints centred at every container width.
        for width in (984, 1100):
            for count in (2, 3, 5):
                boxes = [(i * width / count + 6, (i + 1) * width / count - 6) for i in range(count)]
                for i, (left, right) in enumerate(boxes):
                    self.assertAlmostEqual((left + right) / 2, (i + 0.5) * width / count)
                    if i:
                        self.assertAlmostEqual(left - boxes[i - 1][1], 12)
        self.assertEqual(css_value(rule('.activity .bubble-items > [data-activity-item]'), 'display'), 'flex')
        self.assertEqual(css_value(rule('.activity .bubble-items time'), 'margin-left'), 'auto')
        self.assertEqual(css_value(rule('.activity .bubble-items time'), 'flex'), 'none')
        self.assertEqual(css_value(rule('.bubble-message'), 'min-width'), '0')
        self.assertEqual(css_value(rule('.activity time'), 'font-variant-numeric'), 'tabular-nums')
        self.assertEqual(css_value(rule('[data-dim], [data-dim] *'), 'opacity'), '1')
        self.assertRegex(css, r'\[data-org-node\][^{]+\{[^}]*transition: opacity var\(--motion\) var\(--ease\);')
        self.assertEqual(css_value(rule('[data-progress-fill]'), 'background'), 'var(--run)')
        self.assertEqual(css_value(rule('[data-progress][data-tone="done"] [data-progress-fill]'), 'background'), 'var(--ok)')
        self.assertEqual(css_value(rule('[data-progress][data-tone="failed"] [data-progress-fill]'), 'background'), 'var(--bad)')
        self.assertEqual(css_value(rule('[data-progress-fill]'), 'height'), '100%')
        self.assertEqual(css_value(rule('button.seat-select'), 'background'), 'transparent')
        self.assertIn('outline:', rule('button.seat-select:focus-visible'))
        self.assertIn('box-shadow:', rule('button.seat-select:hover'))
        self.assertNotIn('auto-fit', rule('.run-tiles'))

    def test_progress_fields_count_direct_children_and_leaf_success(self):
        orders = {'main': {'id': 'main', 'state': 'LEASED'},
                  'a': {'id': 'a', 'state': 'PENDING', 'parent': 'main'},
                  'b': {'id': 'b', 'state': 'PENDING', 'parent': 'main'},
                  'nested': {'id': 'nested', 'state': 'SUCCEEDED', 'parent': 'a'}}
        issued = {k: {'seq': i, 'kind': 'order.issued', 'by': 'human:ceo', 't': 10, 'body': o}
                  for i, (k, o) in enumerate(orders.items(), 1)}
        for o in orders.values():
            o.update(title=o['id'], to='team:lead', writes=[])
        record = {'orders': orders, 'issued': issued, 'events': list(issued.values()), 'tops': dict.fromkeys(orders, 'main')}
        history = H.History(ROOT, 'run', lambda: 20)
        with mock.patch.object(history, 'read', return_value=record), mock.patch.object(history, 'runs', return_value=({'run': record}, [])), \
             mock.patch.object(history, 'board', return_value={}), mock.patch.object(history, 'seats', return_value=[]), \
             mock.patch.object(history, 'launches', return_value=[]), mock.patch.object(history, 'files', return_value=[]):
            for states, expected in [(('PENDING', 'PENDING'), 0), (('SUCCEEDED', 'FAILED'), 1), (('SUCCEEDED', 'SUCCEEDED'), 2)]:
                orders['a']['state'], orders['b']['state'] = states
                wanted = {'total': 2, 'succeeded': expected}
                self.assertEqual(history.summary({})['days'][H.day(10)]['orders'][0]['progress'], wanted)
                doc = history.order('run', 'main')
                self.assertEqual(doc['order']['progress'], wanted)
                self.assertEqual(doc['nodes'][0]['progress'], wanted)
                self.assertEqual(doc['children'][0]['progress'], {'total': 1, 'succeeded': 1})
            for state, done in [('PENDING', 0), ('FAILED', 0), ('SUCCEEDED', 1)]:
                orders['b']['state'] = state
                self.assertEqual(history.order('run', 'b')['order']['progress'], {'total': 1, 'succeeded': done})

    def test_count_wording_is_shared_and_handles_one_and_many(self):
        js = text('web', 'app.js')
        self.assertEqual(js.count('function countText('), 1)
        self.assertNotIn('file(s)', js)
        cases = [(0, 'launch', '0 launches'), (1, 'launch', '1 launch'), (2, 'launch', '2 launches'),
                 (1, 'file', '1 file'), (3, 'file', '3 files'), (1, 'order', '1 order'), (2, 'order', '2 orders'),
                 (1, 'planned order', '1 planned order'), (1, 'sub-order', '1 sub-order'),
                 (1, 'second', '1 second'), (2, 'second', '2 seconds'), (1, 'part', '1 part'),
                 (1, 'sent back', '1 sent back'), (0, 'use', 'used 0 times'),
                 (0, 'file', '0 files'), (1, 'step', '1 step'), (2, 'step', '2 steps'),
                 (1, 'seat', '1 seat'), (2, 'seat', '2 seats'), (1, 'time', '1 time'), (2, 'time', '2 times'),
                 (1, 'use', 'used once'), (3, 'use', 'used 3 times')]
        if shutil.which('node'):
            helper = re.search(r'function countText\(number, noun\) \{.*?\n  \}', js, re.S).group(0)
            script = 'import * as F from ' + json.dumps(Path(WEB, 'format.mjs').as_uri()) + ';\n' + helper + '\nprocess.stdout.write(JSON.stringify(' + json.dumps(cases) + '.map(c => countText(c[0], c[1]))));'
            result = subprocess.run(['node', '--input-type=module', '-e', script], capture_output=True, text=True, check=True)
            self.assertEqual(json.loads(result.stdout), [c[2] for c in cases])

