    def test_every_text_colour_has_aa_contrast_on_every_surface_it_can_use(self):
        css = text('web', 'app.css')
        tokens = css_colours(css)
        # Audit all inherited text colours against all pale surfaces, a superset of
        # actual pairs, including gradient endpoints, hover, disabled and state pills.
        paints = css_paints(css)
        foregrounds = {'--ink-' + str(n) for n in (92, 86, 80, 76, 72, 70, 68, 66)} | {'--ink', '--ink-2', '--ink-3', '--accent', '--wait', '--run', '--ok', '--attention', '--bad'}
        surfaces = {'--canvas', '--well', '--paper', '--wash', '--accent-wash', '--hero-end', '--run-wash', '--ok-wash', '--attention-wash', '--bad-wash', '--wait-wash', '--nav-wash'}
        used_text = set(re.findall(r'(?:^|[;{])\s*(?:color|fill):\s*var\((--[\w-]+)\)', css))
        # These fills are confined to non-text slab faces and arrowheads.
        face_fills = {'--slab-top', '--slab-left', '--slab-right'}
        foregrounds |= {'--time', '--mono-ink', '--you-ink', '--judge-ink'} | {'--seat-%d-ink' % i for i in range(1, 7)} | {'--kind-%s-ink' % k for k in ('artifact', 'skill', 'workflow', 'lesson')}
        surfaces |= {'--mono-wash', '--you-wash', '--judge-wash'} | {'--seat-%d-wash' % i for i in range(1, 7)} | {'--kind-%s-wash' % k for k in ('artifact', 'skill', 'workflow', 'lesson')}
        dynamic = {'--seat-ink', '--seat-wash', '--kind-ink', '--kind-wash', '--stat-hue', '--seat-light', '--seat-accent', '--kind-light', '--stat-disc-wash'}
        marks = {'--tone-' + hue for hue in ('blue', 'green', 'red', 'indigo', 'amber')}
        self.assertLessEqual(used_text, foregrounds | surfaces | {'--accent-ink', '--edge', '--ink-38', '--ink-58'} | marks | face_fills | dynamic)
        for selector, body in re.findall(r'([^{}]+)\{([^{}]*)\}', css):
            if any('fill: var(' + name + ')' in body for name in face_fills):
                self.assertIn(selector.strip(), ('.level-step', '[data-level-face="left"]', '[data-level-face="right"]'))
            if 'fill: var(--edge)' in body:
                self.assertEqual(selector.strip(), '.flow-arrow')
        used_background = set(re.findall(r'background(?:-color)?:\s*var\((--[\w-]+)\)', css))
        self.assertLessEqual(used_background, surfaces | {'--accent', '--skeleton', '--wait', '--run', '--ok', '--bad', '--line', '--ink-3', '--mesh-base'} | marks | dynamic)
        self.assertNotRegex(re.sub(r'/\*.*?\*/', '', css, flags=re.S), r'oklch\(|color\(srgb|color-mix\(')
        pairs = [(fg, bg) for fg in foregrounds for bg in surfaces] + [('--accent-ink', '--accent')]
        for fg, bg in pairs:
            paint = paints[fg]
            background = [int(tokens[bg][i:i + 2], 16) for i in (1, 3, 5)]
            foreground = '#' + ''.join('%02x' % round(c * paint[3] + b * (1 - paint[3])) for c, b in zip(paint[:3], background))
            light, dark = sorted((luminance(foreground), luminance(tokens[bg])), reverse=True)
            self.assertGreaterEqual((light + 0.05) / (dark + 0.05), 4.5, (fg, bg))
        # Pass 32: sample the radial mesh, including more overlap than the
        # actual three centres. Audit the darkest/lightest colours and their
        # interiors, then the 55% glass after CSS saturate(1.4), including alerts.
        from itertools import product
        self.assertRegex(css, r'\.hero \.eyebrow\s*\{[^}]*color: var\(--ink\)')
        self.assertRegex(css, r'\.hero p:not\(\.eyebrow\)\s*\{[^}]*color: var\(--ink\)')
        hero = re.search(r'(?m)^\.hero::before\s*\{([^}]+)\}', css).group(1)
        self.assertEqual(hero.count('radial-gradient'), 3)
        for name in ('--mesh-blue', '--mesh-lilac', '--mesh-mint', '--mesh-base'):
            self.assertIn('var(' + name + ')', hero)
        def rgb(name):
            return [int(tokens[name][i:i + 2], 16) for i in (1, 3, 5)]
        def composite(back, name, alpha):
            return [c * alpha + b * (1 - alpha) for c, b in zip(rgb(name), back)]
        def check_pair(name, channels):
            bg = '#' + ''.join('%02x' % round(c) for c in channels)
            paint = paints[name]
            fg = '#' + ''.join('%02x' % round(c * paint[3] + b * (1 - paint[3])) for c, b in zip(paint[:3], channels))
            self.assertGreaterEqual((luminance(bg) + .05) / (luminance(fg) + .05), 4.5, (name, bg))
        def saturated(channels):
            grey = sum(c * w for c, w in zip(channels, (.213, .715, .072)))
            return [max(0, min(255, grey + 1.4 * (c - grey))) for c in channels]
        for blue, lilac, mint in product((0, .25, .5, .75, 1), repeat=3):
            mesh = rgb('--mesh-base')
            for name, alpha in (('--mesh-mint', mint), ('--mesh-lilac', lilac), ('--mesh-blue', blue)):
                mesh = composite(mesh, name, alpha)
            for fg in ('--ink', '--ink-2'):
                check_pair(fg, mesh)
            # The original faint decorative strokes may overlap the mesh too.
            patterned = composite(composite(mesh, '--accent', .18 * .28), '--seat-3-ink', .14 * .28)
            check_pair('--ink', patterned)
            glass = composite(saturated(patterned), '--paper', .55)
            for fg in foregrounds:
                check_pair(fg, glass)
            for hue in ('--accent', '--attention'):
                for alpha in (.03, .07):
                    tinted = composite(glass, hue, alpha)
                    for fg in ('--ink', '--ink-3', '--ok', '--bad'):
                        check_pair(fg, tinted)
        for blue, lilac, mint in product((0, .17, .34, .51, .68, .85), repeat=3):
            canvas = rgb('--canvas')
            for name, alpha in (('--glow-mint', mint), ('--glow-lilac', lilac), ('--glow-blue', blue)):
                canvas = composite(canvas, name, alpha)
            for fg in foregrounds:
                check_pair(fg, canvas)
            check_pair('--accent', composite(canvas, '--paper', .55))
        # White button labels across the entire new vertical blue gradient.
        top = composite(rgb('--accent'), '--paper', .06)
        for step in range(101):
            channels = [a * (1 - step / 100) + b * step / 100 for a, b in zip(top, rgb('--accent-side'))]
            bg = '#' + ''.join('%02x' % round(c) for c in channels)
            self.assertGreaterEqual((luminance(tokens['--accent-ink']) + .05) / (luminance(bg) + .05), 4.5)
        self.assertIn('rgba(255, 255, 255, 0.55)', css)
        self.assertIn(':root[data-transparency="on"] body .hero .stat', css)
        self.assertIn('backdrop-filter: blur(18px) saturate(1.4)', css)
        # New team tiles/status/time, used-entry pills, group headings and arrows
        # inherit only these audited pairs, including their hover surfaces.
        for pair in (('--ink', '--wash'), ('--ink-2', '--wash'), ('--ink-3', '--wash'),
                     ('--ink-2', '--paper'), ('--ink-3', '--paper'),
                     ('--accent', '--accent-wash'), ('--accent', '--wash')):
            self.assertIn(pair, pairs)

