    def test_seat_palette_marks_and_separate_dark_text_inks(self):
        css, js = text('web', 'app.css'), text('web', 'app.js')
        tokens = css_colours(css)
        seats = [tokens['--seat-' + str(i)] for i in range(1, 7)]
        states = [tokens[key] for key in ('--accent', '--run', '--ok', '--wait', '--attention', '--bad')]
        self.assertEqual(seats, [tokens['--tone-' + name] for name in ('violet', 'teal', 'amber', 'indigo', 'green', 'red')])
        for i, colour in enumerate(seats, 1):
            self.assertNotIn(colour, states)
            self.assertGreaterEqual(1.05 / (luminance(colour) + 0.05), 3)
            wash = tokens['--seat-' + str(i) + '-wash']
            self.assertNotEqual(wash, tokens['--paper'])
            # Each wash is the same source hue at 5% alpha over a white card.
            tint = '#' + ''.join('%02x' % round(int(colour[n:n + 2], 16) * .05 + 255 * .95) for n in (1, 3, 5))
            self.assertEqual(wash, tint)
            self.assertGreater(luminance(wash), 0.85)
            for ink in ('--ink', '--ink-2', '--ink-3'):
                self.assertGreaterEqual((luminance(wash) + 0.05) / (luminance(tokens[ink]) + 0.05), 4.5)
        self.assertNotRegex(css + js, r'(?<![\w-])color\s*:\s*[\'\"]?var\(--seat-[1-6]\)')
        self.assertIn('height: 8px; min-width: 8px; width: 8px;', css)
        edge = re.search(r'\.seat-edge\s*\{([^}]+)', css)[1]
        for property_name, size in (('height', 32), ('min-width', 3), ('width', 3)):
            self.assertEqual(css_value(edge, property_name), str(size) + 'px')

