        def rule(selector):
            return re.search(r'(?m)^' + re.escape(selector) + r'\s*\{([^}]+)\}', css).group(1)
        base = rule('[data-dim], [data-dim] *')
        self.assertIn('color: var(--ink-3) !important', base)
        self.assertIn('opacity: 1', base)
        self.assertIn('box-shadow: none !important', base)
        self.assertIn('filter: none !important', base)
        self.assertEqual(css_value(rule('[data-dim] text, [data-dim] tspan'), 'fill'), 'var(--ink-3)')
        art = '[data-dim] :is(rect, img, path, circle, ellipse, line, polyline, polygon, [data-model-icon], [data-seat-colour], [data-seat-wash], .activity-icon, .dot, .usage-track, [data-usage-bar], [data-timeline-bar])'
        self.assertEqual(css_value(rule(art), 'opacity'), '0.4 !important')
        self.assertEqual(css_value(rule('[data-dim]'), 'opacity'), '1')
        self.assertEqual(css_value(rule(art), 'transition'), 'opacity var(--motion) var(--ease)')
        for selector in (':is(.handoff-card, .handoff-seat)[data-dim]', '.usage-row[data-dim]', '[data-dim] :is(.pill, .badge)'):
            self.assertRegex(rule(selector), r'rgba\([^)]*, 0\.(?:4|032|016)\)')
        self.assertEqual(css_value(rule('[data-dim] a, [data-dim] a:hover, [data-dim] a:focus-visible'), 'color'), 'var(--ink-3)')
        tokens = css_colours(css)
        contrast = 1.05 / (luminance(tokens['--ink-3']) + .05)
        self.assertGreaterEqual(contrast, 4.5)
        self.assertLessEqual(contrast, 7)
        # No earlier important ink rule can beat the universal focus ink.
        before = css[:css.index('[data-dim], [data-dim] *')]
        self.assertNotRegex(before, r'(?:color|fill|opacity):[^;{}]*!important')

    def test_heading_chips_depth_and_full_last_launch_row(self):
        css = text('web', 'app.css')
        def rule(selector):
            return re.search(r'(?m)^' + re.escape(selector) + r'\s*\{([^}]+)\}', css).group(1)
        chip = rule('[data-card-icon]')
        for declaration in ('width: 28px', 'height: 28px', 'border-radius: var(--round-icon)', 'background: var(--wash)'):
            self.assertIn(declaration, chip)
        for tone in ('ok', 'attention', 'accent', 'run'):
            self.assertIn('background: var(--' + tone + '-wash)', rule('[data-icon-tone="' + tone + '"]'))
            self.assertIn('color: var(--' + tone + ')', rule('[data-icon-tone="' + tone + '"]'))
        for selector in ('.home-seat', '.seat', '.handoff-seat', '.handoff-card', '.launch-card', '.run-tile', '[data-seat-tile]'):
            body = rule(selector)
            self.assertIn('background: var(--paper)', body)
            self.assertIn('border: 1px solid var(--line)', body)
            self.assertIn('box-shadow: var(--shadow-small)', body)
        self.assertEqual(css_value(rule('.org-box'), 'fill'), 'var(--well)')
        self.assertEqual(css_value(rule('.org-box'), 'stroke'), 'none')
        self.assertEqual(css_value(rule('.org-box'), 'filter'), 'none')
        self.assertEqual(css_value(rule('.launch-card:last-child:nth-child(odd)'), 'grid-column'), '1 / -1')
        self.assertEqual(css_value(rule('.run-chart[data-empty-plot]'), 'height'), '64px')

    def test_motion_is_scoped_and_only_animates_composited_properties_or_the_line(self):
        css, js = text('web', 'app.css'), text('web', 'app.js')
        # Parse top-level balanced blocks: a regex alone can silently miss a nested
        # keyframe declaration and give a false pass for a layout animation.
        source = re.sub(r'/\*.*?\*/', '', css, flags=re.S)
        blocks, start = [], 0
        while start < len(source):
            opening = source.find('{', start)
            if opening < 0:
                break
            depth, end = 1, opening + 1
            while depth:
                depth += (source[end] == '{') - (source[end] == '}')
                end += 1
            blocks.append((source[start:opening].strip(), source[opening + 1:end - 1]))
            start = end
        frames = {selector.split()[1]: body for selector, body in blocks if selector.startswith('@keyframes ')}
        self.assertGreaterEqual(len(frames), 3)
        for name, body in frames.items():
            properties = re.findall(r'([\w-]+)\s*:', body)
            self.assertTrue(properties, name)
            self.assertLessEqual(set(properties), {'opacity', 'transform', 'stroke-dashoffset'}, name)
            if 'stroke-dashoffset' in properties:
                self.assertEqual(name, 'line-in')
        used = set()
        for selector, body in blocks:
            for declaration in re.findall(r'animation(?:-[\w-]+)?\s*:\s*([^;]+)', body):
                self.assertTrue(all(s.strip().startswith('[data-motion="on"]') for s in selector.split(',')), selector)
                self.assertNotRegex(declaration, r'\b(?:forwards|backwards|both)\b')
            match = re.search(r'animation:\s*([\w-]+)', body)
            if match:
                used.add(match[1])
                if match[1] == 'line-in':
                    self.assertIn('[data-enter="line"]', selector)
        self.assertEqual(used, set(frames))
        self.assertIn('card-in 200ms ease-out', css)
        self.assertIn('line-in 400ms ease-out', css)
        self.assertIn('bar-grow 300ms ease-out', css)
        self.assertIn('working-dot 2s ease-in-out infinite', css)
        self.assertIn('setTimeout(finish, 650)', js)
        self.assertIn("var motionPreference = '(prefers-reduced-motion)'", js)
        self.assertIn('window.matchMedia(motionPreference)', js)
        self.assertIn("addEventListener('change', motionChanged)", js)
        self.assertNotIn('route-enter', css + js)

    def test_state_words_and_long_hex_have_one_display_boundary(self):
        js = text('web', 'app.js')
        html = text('web', 'index.html')
        self.assertNotRegex(html, r'>\s*[A-Z]{4,}\s*<')
        for unsafe in ('LABEL[state] || state', "{'data-order-field': key}, o[key]", "? 'LIVE RUN' : 'PAST RUN'"):
            self.assertNotIn(unsafe, js)
        self.assertIn("key === 'state' ? attrs(badge(", js)
        self.assertIn("title: 'Ledger state: ' + stateLabel(o.state)", js)
        self.assertEqual(js.count('function shortHex('), 1)
        self.assertIn("/[a-f0-9]{16,}/gi", js)
        self.assertIn("F.truncate(hex, 9)", js)
        self.assertIn("e.setAttribute('title'", js)
        cases = [('abcdef012345678', 'abcdef012345678'), ('abcdef0123456789', 'abcdef01…'),
                 ('order-ABCDEF0123456789/note.txt', 'order-ABCDEF01…/note.txt'),
                 ('a' * 40 + ' / ' + '0' * 64, 'aaaaaaaa… / 00000000…')]
        for full, expected in cases:
            self.assertEqual(short_hex(full), expected)
        if shutil.which('node'):
            helper = re.search(r'function displayValue.*?\n', js).group(0) + re.search(r'function shortHex\(value, limit\) \{.*?\n  \}', js, re.S).group(0)
            script = 'import * as F from ' + json.dumps(Path(WEB, 'format.mjs').as_uri()) + ';\n' + helper + '\nprocess.stdout.write(JSON.stringify(' + json.dumps([c[0] for c in cases]) + '.map(value => shortHex(value))));'
            result = subprocess.run(['node', '--input-type=module', '-e', script], capture_output=True, text=True, check=True)
            self.assertEqual(json.loads(result.stdout), [c[1] for c in cases])
            limited = ['order-' + 'a' * 40, 'order-' + 'a' * 40 + '.a-very-long-step-name', 'w' * 90]
            script = 'import * as F from ' + json.dumps(Path(WEB, 'format.mjs').as_uri()) + ';\n' + helper + '\nprocess.stdout.write(JSON.stringify(' + json.dumps(limited) + '.map(value => shortHex(value, 22))));'
            shown = json.loads(subprocess.run(['node', '--input-type=module', '-e', script], capture_output=True, text=True, check=True).stdout)
            self.assertEqual(shown[0], 'order-aaaaaaaa…')
            for value in shown:
                self.assertLessEqual(len(value), 22)
                self.assertEqual(value.count('…'), 1)


class Icons(unittest.TestCase):
    def test_the_three_families_and_a_fallback_each_have_a_drawing(self):
        got = icons()
        self.assertEqual(sorted(got), ['deepseek', 'kimi', 'other', 'qwen'])
        self.assertEqual([got[k]['name'] for k in ('deepseek', 'kimi', 'qwen')], ['DeepSeek', 'Kimi', 'Qwen'])
        for family, icon in got.items():
            self.assertRegex(icon['box'], r'^0 0 \d+ \d+$', family)
            self.assertTrue(icon['paths'], family)
            for fill, d in icon['paths']:
                self.assertRegex(fill, M.FILL)
                self.assertRegex(d, M.D)
                self.assertGreater(len(d), 40, family)
        drawings = [json.dumps(i['paths']) for i in got.values()]
        self.assertEqual(len(set(drawings)), 4)

    def test_a_seat_s_model_picks_its_family(self):
        cases = {'deepseek/deepseek-chat': 'deepseek', 'openrouter/deepseek/deepseek-r1': 'deepseek', 'moonshotai/kimi-k2': 'kimi', 'moonshot/moonshot-v1-8k': 'kimi',
                 'alibaba/qwen3-coder-plus': 'qwen', 'ollama/qwen3:8b': 'qwen', 'dashscope/some-model': 'qwen', 'openai/gpt-x': 'other', '': 'other'}
        for model, family in cases.items():
            self.assertEqual(L.family(model), family, model)
            self.assertIn(L.family(model), icons())

    def test_icons_js_is_what_the_files_in_icons_give(self):
        self.assertEqual(M.build(ICONS), text('web', 'icons.js'))
        r = subprocess.run([sys.executable, os.path.join(ROOT, 'tools', 'make_icons.py'), '--check'], capture_output=True, text=True)
        self.assertEqual(r.returncode, 0, r.stdout + r.stderr)

    def test_a_changed_file_or_anything_but_plain_paths_is_refused(self):
        d = tempfile.mkdtemp(prefix='icons-')
        self.addCleanup(shutil.rmtree, d, True)
        for _, name, _, _ in M.SOURCES:
            shutil.copy(os.path.join(ICONS, name), d)
        self.assertEqual(M.build(d), M.build(ICONS))
        family, name, _, sha = M.SOURCES[0]
        good = text('icons', name)
        for bad in (good.replace('</svg>', '<script>alert(1)</script></svg>'), good.replace('<path ', '<path onload="x()" ', 1),
                    good.replace('fill="#', 'fill="url(//elsewhere.example/x)#', 1), good.replace('<path d="', '<path d="javascript:', 1)):
            self.assertNotEqual(bad, good)
            with open(os.path.join(d, name), 'w', encoding='utf-8') as f:
                f.write(bad)
            self.assertRaises(ValueError, M.build, d)                                   # not the file ICONS.md names
            own = hashlib.sha256(bad.encode('utf-8')).hexdigest()
            self.assertRaises(ValueError, M.read, d, name, own)                         # and refused for what it holds, too
        os.remove(os.path.join(d, name))
        self.assertRaises(OSError, M.build, d)

    def test_every_source_file_is_named_with_its_checksum_in_icons_md(self):
        doc = text('ICONS.md')
        for _, name, _, sha in M.SOURCES:
            self.assertIn(name, doc)
            self.assertIn(sha, doc)
            with open(os.path.join(ICONS, name), 'rb') as f:
                self.assertEqual(hashlib.sha256(f.read()).hexdigest(), sha)
        self.assertTrue(os.path.isfile(os.path.join(ICONS, 'LICENSE')))


if __name__ == '__main__':
    unittest.main()
