import copy
from pathlib import Path
import sys
import unittest

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / 'tools'))
import quality


class ScorecardTests(unittest.TestCase):
    def setUp(self):
        _, self.metrics, self.key = quality.rubric()
        self.rows = {m['id']: {'value': None, 'reason': 'Tool unavailable', 'evidence': {}} for m in self.metrics}

    def report(self):
        return quality.compile_report([dict(slot='gpt', revision='fixture', runtime_sha256='fixture',
                                             fixture='case', instruments_sha256='test-kit', captured='2000-01-01', criteria_sha256=self.key,
                                             observations=self.rows)])

    def test_missing_values_are_excluded_and_raw_output_is_required(self):
        m = self.metrics[0]
        self.rows[m['id']] = dict(value=m['worst'], evidence={'count': 0})
        report = self.report()
        score = report['axes'][0]['results']['gpt']
        self.assertEqual((score['score'], score['passed'], score['measured']), (0, 0, 1))
        self.assertIsNone(report['axes'][1]['results']['gpt']['score'])
        self.rows[m['id']] = dict(value=m['target'])
        with self.assertRaises(ValueError):
            self.report()

    def test_lower_boundaries_use_the_measured_raw_value(self):
        m = next(row for row in self.metrics if row['direction'] == 'lower')
        def test_value(v):
            return quality.grade(m, dict(value=v, evidence={}))
        self.assertTrue(test_value(m['target'])['passed'])
        self.assertEqual(test_value(m['worst'])['score'], 0)
        self.assertAlmostEqual(test_value((m['worst'] + m['target']) / 2)['score'], .5)

    def test_regression_and_missing_coverage_block_a_release(self):
        a, b = self.metrics[:2]
        for m in (a,b):
            self.rows[m['id']] = dict(value=m['worst'], evidence={})
        previous = self.report()
        self.assertFalse(quality.advancement(previous, previous, 'gpt')['passed'])
        self.rows[a['id']]['value'] = a['target']
        sealed = quality.seal(previous, self.report(), 'gpt')
        quality.verify(sealed)
        self.assertEqual(sealed['evolution']['improved'], [a['id']])
        tampered = copy.deepcopy(sealed)
        tampered['evolution']['previous_values'][a['id']] = a['target']
        with self.assertRaises(ValueError):
            quality.verify(tampered)
        self.rows[b['id']] = dict(value=None, evidence={}, reason='No new measurement')
        self.assertFalse(quality.advancement(previous, self.report(), 'gpt')['passed'])

    def test_modified_axis_table_fails_verification(self):
        report = self.report()
        report['axes'][0]['results']['gpt']['score'] = 1
        with self.assertRaises(ValueError):
            quality.verify(report)


if __name__ == '__main__':
    unittest.main()
