#!/usr/bin/env python3
"""web/status.js run by node on a table of hand-made situations: every situation of an order (1 to 6), every flag (7a to
7f), the boundaries on both sides (a lease with 0 s left has run out, 1 s has not; quiet equal to the threshold is not
too quiet, one more second is; a last good answer exactly two poll periods old is not out of date, a fraction more is),
ghosts, order ids that are names of Object.prototype, who holds what, and the merge of /state pages (overlapping pages,
another ledger, a shorter one).  Skips, saying so, only when node is not installed.
   python3 -B tests/test_status.py"""
import json
import os
import shutil
import subprocess
import unittest

HERE = os.path.dirname(os.path.abspath(__file__))
STATUS_JS = os.path.join(os.path.dirname(HERE), 'web', 'status.js')
NODE = shutil.which('node')
# Reads one JSON job from stdin, runs one function of status.js on it, prints the result as JSON.
DRIVER = """
const S = require(process.argv[1]);
let raw = '';
process.stdin.on('data', d => { raw += d; });
process.stdin.on('end', () => {
  const jobs = JSON.parse(raw);
  process.stdout.write(JSON.stringify(jobs.map(j => S[j.fn].apply(null, j.args))));
});
"""
NOW = 1000
RULES = {'default': {'first': 120, 'silence': 480}, 'fast@1': {'first': 4, 'silence': 8}}


def run(*jobs):
    """Each job is (function name, arguments); the results, in order."""
    r = subprocess.run([NODE, '-e', DRIVER, STATUS_JS], input=json.dumps([{'fn': f, 'args': a} for f, a in jobs]),
                       capture_output=True, text=True, timeout=60)
    if r.returncode:
        raise AssertionError(r.stderr)
    return json.loads(r.stdout)


def order(oid, state, **kw):
    return dict({'id': oid, 'state': state, 'title': 'Order ' + oid, 'to': 'team:lead', 'parent': None, 'attempt': 1,
                 'after': [], 'accept': {'judge': 'program:judge', 'criteria': 'files'}}, **kw)


def snap(orders, leases=None, asks=None):
    return {'now': NOW, 'state': {'orders': {o['id']: o for o in orders}, 'leases': leases or {}, 'asks': asks or {}}}


def issued(seq, t, oid, parent=None, under=None):
    row = {'seq': seq, 't': t, 'kind': 'order.issued', 'by': 'human:ceo', 'body': {'id': oid, 'parent': parent}}
    if under:
        row['under'] = {'order': under, 'token': 1}
    return row


def row(seq, t, kind, oid, by='team:lead', **kw):
    return dict({'seq': seq, 't': t, 'kind': kind, 'by': by, 'order': oid}, **kw)


def sent(id_, at, oid, ok, kind='order.issue', under=None, n=None, code=None, detail=None):
    return {'src': 'backend', 'n': n, 'id': id_, 'at': at, 'from': 'team:lead', 'kind': kind, 'order': oid, 'under': under,
            'ok': ok, 'code': code, 'detail': detail, 'events': []}


def classify(s, log=(), sent_=(), now=NOW, live=True, last_ok=None, rules=RULES):
    return {'fn': 'classify', 'args': [{'snap': s, 'log': list(log), 'sent': list(sent_), 'rules': rules, 'nowS': now, 'live': live,
                                        'lastOkS': last_ok, 'pollS': 5}]}


def cards(job):
    return {c['id']: c for c in run((job['fn'], job['args']))[0]}


# a held order: issued at 900, granted at 910 (lease until 1500), a note at 950
HELD_LOG = [issued(1, 900, 'h'), row(2, 910, 'lease.granted', 'h', token=1, expires=1500),
            row(3, 950, 'report.progress', 'h', note='[draft] Half way', pct=50, token=1)]


@unittest.skipUnless(NODE, 'node is not installed, so web/status.js cannot be run here (CI installs it)')
class Situations(unittest.TestCase):
    def test_1_a_ghost_per_issue_the_dispatcher_does_not_know(self):
        job = classify(snap([]), sent_=[sent('e1', 10, 'g1', False, code='not-subset', detail='scope', n=1), sent('e2', 20, 'g2', None, n=2), sent('e3', 30, 'g3', True, n=3)])
        got = cards(job)
        self.assertEqual([c['id'] for c in run((job['fn'], job['args']))[0]], ['g3', 'g2', 'g1'], 'latest ghost first')
        g1 = got['g1']
        self.assertEqual((g1['case'], g1['flags'], g1['state'], g1['parent'], g1['top'], g1['depth']), ('1', ['7b'], 'NONE', '', 'g1', 0))
        self.assertEqual(g1['facts'], {'reply': 'refused', 'code': 'not-subset', 'detail': 'scope', 'sent_at': 10, 'sent_id': 'e1',
                                       'sent_src': 'backend', 'from': 'team:lead', 'b_code': 'not-subset', 'b_detail': 'scope', 'b_at': 10, 'b_id': 'e1'})
        self.assertEqual((got['g2']['facts']['reply'], got['g2']['flags']), ('none', []))
        self.assertEqual((got['g3']['facts']['reply'], got['g3']['flags']), ('accepted', []))

    def test_1_the_latest_record_decides_and_a_tie_goes_to_the_greater_line(self):
        got = cards(classify(snap([]), sent_=[sent('e1', 10, 'g', False, code='x', n=1), sent('e2', 12, 'g', None, n=2)]))['g']
        self.assertEqual((got['facts']['reply'], got['flags']), ('none', []))
        tie = [sent('e1', 10, 'g', None, n=2), sent('e2', 10, 'g', False, code='x', n=1)]
        self.assertEqual(cards(classify(snap([]), sent_=tie))['g']['facts']['reply'], 'none')
        tie[1]['n'] = 3
        self.assertEqual(cards(classify(snap([]), sent_=tie))['g']['facts']['reply'], 'refused')

    def test_1_a_ghost_under_a_known_order_sits_under_it(self):
        got = cards(classify(snap([order('p', 'LEASED')], {'p': {'holder': 'team:lead', 'expires': 2000}}), HELD_LOG,
                             [sent('e1', 10, 'p.k', False, under='p', code='not-subset', n=1)]))
        self.assertEqual((got['p.k']['parent'], got['p.k']['top'], got['p.k']['depth']), ('p', 'p', 1))
        self.assertEqual(got['p']['flags'], ['7b'], 'a refusal about a child it issued flags the parent')

    def test_2_waiting(self):
        got = cards(classify(snap([order('w', 'PENDING')]), [issued(1, 940, 'w')]))
        self.assertEqual((got['w']['case'], got['w']['flags']), ('2', []))
        self.assertEqual(got['w']['facts'], {'to': 'team:lead', 'wait': 60, 'attempt': 1})

    def test_2_blocked_by_a_question_then_by_an_earlier_order(self):
        asks = {'q2': {'id': 'q2', 'to': 'agent:b', 'about': 'w', 'blocking': True, 'state': 'OPEN', 'touched': 9},
                'q1': {'id': 'q1', 'to': 'agent:a', 'about': 'w', 'blocking': True, 'state': 'OPEN', 'touched': 5}}
        asks['q0'] = {'id': 'q0', 'to': 'agent:z', 'about': 'w', 'blocking': False, 'state': 'OPEN', 'touched': 1}
        got = cards(classify(snap([order('w', 'PENDING', after=['e']), order('e', 'LEASED')], {'e': {'holder': 'x', 'expires': 2000}}, asks)))
        self.assertEqual((got['w']['facts']['blocked'], got['w']['facts']['ask_to']), ('ask', 'agent:a'), 'the lowest touched blocking question')
        got = cards(classify(snap([order('w', 'PENDING')], None, {'q0': asks['q0']})))
        self.assertNotIn('blocked', got['w']['facts'], 'a question that does not block does not hold the order')
        got = cards(classify(snap([order('w', 'PENDING', after=['e']), order('e', 'LEASED')], {'e': {'holder': 'x', 'expires': 2000}})))
        self.assertEqual(got['w']['facts']['blocked'], 'after')
        self.assertNotIn('ask_to', got['w']['facts'])
        got = cards(classify(snap([order('w', 'PENDING', after=['e']), order('e', 'SUCCEEDED')])))
        self.assertNotIn('blocked', got['w']['facts'])

    def test_2_a_waiting_order_with_open_children_is_still_2(self):
        got = cards(classify(snap([order('w', 'PENDING'), order('w.k', 'PENDING', parent='w')])))
        self.assertEqual((got['w']['case'], got['w']['facts']['kids_open']), ('2', 1))

    def test_3_held(self):
        got = cards(classify(snap([order('h', 'LEASED', note='[draft] Half way', pct=50)], {'h': {'holder': 'team:lead', 'expires': 1500, 'token': 1}}), HELD_LOG))
        self.assertEqual((got['h']['case'], got['h']['flags']), ('3', []))
        self.assertEqual(got['h']['facts'], {'holder': 'team:lead', 'left': 500, 'last_seq': 3, 'last_kind': 'report.progress', 'last_age': 50,
                                             'last_text': '[draft] Half way', 'label': 'draft', 'pct': 50, 'attempt': 1,
                                             'quiet': 50, 'threshold': 480, 'rule': 'default'})

    def test_3_the_holder_is_the_lease_s_not_the_addressee_s(self):
        # a subordinate may claim an order addressed to its superior: the seat that holds it is the lease's holder
        got = cards(classify(snap([order('h', 'LEASED', to='team:lead')], {'h': {'holder': 'agent:writer', 'expires': 1500, 'token': 1}}), HELD_LOG))
        self.assertEqual(got['h']['facts']['holder'], 'agent:writer')
        self.assertEqual(run(('holders', [[got['h']]]))[0], {'agent:writer': {'orders': [{'id': 'h', 'title': 'Order h'}], 'expired': []}})

    def test_3_a_label_is_only_a_leading_bracket_with_text_in_it(self):
        def label(note):
            s = snap([order('h', 'LEASED', note=note)], {'h': {'holder': 'team:lead', 'expires': 1500}})
            return cards(classify(s, HELD_LOG))['h']['facts'].get('label')
        self.assertEqual([label(n) for n in ('[a[b] text', '[] empty', 'plain] text', 'no bracket', '[open only')], ['a[b', None, None, None, None])

    def test_3_issuing_a_child_is_activity_on_the_parent(self):
        log = HELD_LOG + [issued(4, 990, 'h.k', parent='h', under='h')]
        got = cards(classify(snap([order('h', 'LEASED'), order('h.k', 'SUCCEEDED', parent='h')], {'h': {'holder': 'team:lead', 'expires': 1500}}), log))
        self.assertEqual((got['h']['case'], got['h']['facts']['last_seq'], got['h']['facts']['last_kind']), ('3', 4, 'order.issued'))

    def test_4_held_with_children_open(self):
        log = HELD_LOG + [issued(4, 960, 'h.a', 'h', 'h'), issued(5, 961, 'h.b', 'h', 'h'), issued(6, 962, 'h.c', 'h', 'h'),
                          row(7, 970, 'lease.granted', 'h.b', by='agent:w', token=1, expires=2000), row(8, 980, 'report.progress', 'h.b', by='agent:w')]
        s = snap([order('h', 'LEASED'), order('h.a', 'PENDING', parent='h'), order('h.b', 'LEASED', parent='h'), order('h.c', 'SUCCEEDED', parent='h')],
                 {'h': {'holder': 'team:lead', 'expires': 1500}, 'h.b': {'holder': 'agent:w', 'expires': 2000}})
        got = cards(classify(s, log))
        f = got['h']['facts']
        self.assertEqual(got['h']['case'], '4')
        self.assertEqual((f['kids_open'], f['kids'], f['quietest'], f['quietest_age']),
                         (2, [{'id': 'h.a', 'case': '2'}, {'id': 'h.b', 'case': '3'}, {'id': 'h.c', 'case': '6'}], 'h.a', 40))
        self.assertEqual((f['quiet'], f['threshold']), (20, 480), 'the family\'s rows after the grant count')
        self.assertEqual([c['id'] for c in run(('classify', classify(s, log)['args']))[0]], ['h', 'h.a', 'h.b', 'h.c'])
        self.assertEqual((got['h.b']['parent'], got['h.b']['top'], got['h.b']['depth']), ('h', 'h', 1))

    def test_4_quietest_tie_goes_to_the_lowest_id(self):
        log = [issued(1, 900, 'h'), row(2, 910, 'lease.granted', 'h', expires=1500), issued(3, 920, 'h.b', 'h', 'h'), issued(4, 920, 'h.a', 'h', 'h')]
        s = snap([order('h', 'LEASED'), order('h.b', 'PENDING', parent='h'), order('h.a', 'PENDING', parent='h')], {'h': {'holder': 'team:lead', 'expires': 1500}})
        self.assertEqual(cards(classify(s, log))['h']['facts']['quietest'], 'h.a')

    def test_5_with_the_judge(self):
        log = [issued(1, 900, 'j'), row(2, 910, 'lease.granted', 'j', by='agent:w', expires=1500), row(3, 970, 'report.submitted', 'j', by='agent:w', outputs=[], evidence='done')]
        got = cards(classify(snap([order('j', 'JUDGING', submitter='agent:w')]), log))
        self.assertEqual((got['j']['case'], got['j']['flags']), ('5', []))
        self.assertEqual(got['j']['facts'], {'submitter': 'agent:w', 'judge': 'program:judge', 'wait': 30})

    def test_6_each_way_an_order_ends(self):
        log = [issued(1, 900, 's'), row(2, 950, 'order.succeeded', 's', by='program:judge'),
               issued(3, 900, 'f'), row(4, 920, 'order.failed', 'f', by='program:judge', retry=True, reason='again'), row(5, 960, 'order.failed', 'f', by='program:judge', retry=False, reason='no'),
               issued(6, 900, 'd'), row(7, 990, 'order.dead', 'd', by='dispatcher'),
               issued(8, 900, 'c'), row(9, 930, 'order.cancelled', 'c', by='human:ceo', reason='', cascade=True)]
        got = cards(classify(snap([order('s', 'SUCCEEDED'), order('f', 'FAILED', attempt=2), order('d', 'DEAD', attempt=4), order('c', 'CANCELLED')]), log))
        self.assertEqual(got['s']['facts'], {'end': 'succeeded', 'end_seq': 2, 'by': 'program:judge', 'took': 50, 'attempt': 1})
        self.assertEqual(got['f']['facts'], {'end': 'failed', 'end_seq': 5, 'by': 'program:judge', 'reason': 'no', 'took': 60, 'attempt': 2})
        self.assertEqual(got['d']['facts'], {'end': 'dead', 'end_seq': 7, 'by': 'dispatcher', 'took': 90, 'attempt': 4})
        self.assertEqual(got['c']['facts'], {'end': 'cancelled', 'end_seq': 9, 'by': 'human:ceo', 'cascade': True, 'took': 30, 'attempt': 1})
        self.assertEqual({c['case'] for c in got.values()}, {'6'})


@unittest.skipUnless(NODE, 'node is not installed, so web/status.js cannot be run here (CI installs it)')
class Flags(unittest.TestCase):
    def held(self, expires, lease=True, now=NOW):
        s = snap([order('h', 'LEASED')], {'h': {'holder': 'team:lead', 'expires': expires}} if lease else {})
        return cards(classify(s, HELD_LOG, now=now))['h']

    def test_7a_a_lease_with_no_time_left_has_run_out(self):
        self.assertEqual((self.held(NOW)['flags'], self.held(NOW)['facts']['left']), (['7a'], 0))
        self.assertEqual((self.held(NOW + 1)['flags'], self.held(NOW + 1)['facts']['left']), ([], 1))
        self.assertEqual(self.held(NOW - 30)['facts']['left'], -30)
        self.assertNotIn('quiet', self.held(NOW)['facts'], 'quiet is for valid leases only')

    def test_7a_left_is_the_floor_of_expires_minus_the_clock_with_its_fraction(self):
        # the page's clock has a fraction; `left == 0 is 7a` holds only for a whole-second clock: half a second before
        # the end, 0 s are left and the lease is still valid; half a second after, it ran out 1 s ago (floor of -0.5)
        self.assertEqual((self.held(NOW, now=NOW - 0.5)['flags'], self.held(NOW, now=NOW - 0.5)['facts']['left']), ([], 0))
        self.assertEqual((self.held(NOW, now=NOW + 0.5)['flags'], self.held(NOW, now=NOW + 0.5)['facts']['left']), (['7a'], -1))
        self.assertEqual(self.held(None, lease=False, now=1499.5)['facts']['left'], 0, 'the same floor when the ledger gives the term')

    def test_7a_no_lease_in_the_state_reads_the_ledger(self):
        c = self.held(None, lease=False)
        self.assertEqual((c['flags'], c['facts']['holder'], c['facts']['left']), (['7a'], 'team:lead', 500))
        log = HELD_LOG + [row(4, 960, 'lease.renewed', 'h', expires=1700)]
        c = cards(classify(snap([order('h', 'LEASED')]), log))['h']
        self.assertEqual(c['facts']['left'], 700, 'the latest grant or renewal')

    def test_7b_the_latest_record_about_an_order(self):
        s = snap([order('h', 'LEASED')], {'h': {'holder': 'team:lead', 'expires': 1500}})
        refused = sent('m1', 960, None, False, kind='artifact.put', code='out-of-scope', detail='outside', n=1)
        refused['order'] = 'h'
        c = cards(classify(s, HELD_LOG, [refused]))['h']
        self.assertEqual(c['flags'], ['7b'])
        self.assertEqual({k: c['facts'][k] for k in ('b_code', 'b_detail', 'b_at', 'b_id')}, {'b_code': 'out-of-scope', 'b_detail': 'outside', 'b_at': 960, 'b_id': 'm1'})
        ok = dict(refused, id='m2', at=970, ok=True, code=None, detail=None, n=2)
        self.assertEqual(cards(classify(s, HELD_LOG, [refused, ok]))['h']['flags'], [], 'a later accepted envelope clears it')

    def test_7c_and_7d_go_on_every_card(self):
        s = snap([order('w', 'PENDING'), order('s', 'SUCCEEDED')])
        got = cards(classify(s, live=False))
        self.assertEqual({c['id']: c['flags'] for c in got.values()}, {'w': ['7c'], 's': ['7c']})
        self.assertEqual({tuple(c['flags']) for c in cards(classify(s, last_ok=NOW - 10)).values()}, {()}, 'exactly two poll periods old is not out of date')
        self.assertEqual({tuple(c['flags']) for c in cards(classify(s, now=NOW + 0.5, last_ok=NOW - 10)).values()}, {('7d',)})
        self.assertEqual({tuple(c['flags']) for c in cards(classify(s, live=False, last_ok=NOW - 11)).values()}, {('7c', '7d')})
        self.assertEqual({tuple(c['flags']) for c in cards(classify(snap([]), [], [sent('e', 1, 'g', None)], live=False)).values()}, {('7c',)}, 'ghosts too')

    def test_7e_a_question_to_a_person(self):
        asks = {'q': {'id': 'q', 'to': 'human:ceo', 'about': 'h', 'text': 'Which one?', 'blocking': False, 'state': 'OPEN', 'touched': 3},
                'r': {'id': 'r', 'to': 'team:lead', 'about': 'h', 'text': 'Not a person', 'state': 'OPEN', 'touched': 2}}
        c = cards(classify(snap([order('h', 'LEASED')], {'h': {'holder': 'team:lead', 'expires': 1500}}, asks), HELD_LOG))['h']
        self.assertEqual(c['flags'], ['7e'])
        self.assertEqual({k: c['facts'][k] for k in ('e_to', 'e_ask', 'e_text')}, {'e_to': 'human:ceo', 'e_ask': 'q', 'e_text': 'Which one?'})
        asks['q']['state'] = 'ANSWERED'
        self.assertEqual(cards(classify(snap([order('h', 'LEASED')], {'h': {'holder': 'team:lead', 'expires': 1500}}, asks), HELD_LOG))['h']['flags'], [])

    def test_7f_quiet_more_than_the_threshold(self):
        def at(now, log=HELD_LOG[:2], skills=None):
            o = order('h', 'LEASED', **({'skills': skills} if skills else {}))
            return cards(classify(snap([o], {'h': {'holder': 'team:lead', 'expires': 5000}}), log, now=now))['h']
        first = at(910 + 120)
        self.assertEqual((first['flags'], first['facts']['quiet'], first['facts']['threshold'], first['facts']['rule']), ([], 120, 120, 'default'))
        self.assertEqual(at(910 + 121)['flags'], ['7f'], 'no row since the grant: the first-word rule')
        self.assertEqual((at(950 + 480, HELD_LOG)['flags'], at(950 + 481, HELD_LOG)['flags']), ([], ['7f']), 'rows since the grant: the silence rule')
        self.assertEqual((at(914, skills=['other@1', 'fast@1'])['flags'], at(915, skills=['other@1', 'fast@1'])['flags']), ([], ['7f']))
        self.assertEqual(at(915, skills=['fast@1'])['facts']['rule'], 'fast@1')
        log = HELD_LOG[:2] + [issued(3, 1000, 'h.k', 'h', 'h')]
        s = snap([order('h', 'LEASED', skills=['fast@1']), order('h.k', 'SUCCEEDED', parent='h')], {'h': {'holder': 'team:lead', 'expires': 5000}})
        self.assertEqual(cards(classify(s, log, now=1008))['h']['flags'], [], 'a child\'s row is the family\'s')


@unittest.skipUnless(NODE, 'node is not installed, so web/status.js cannot be run here (CI installs it)')
class Edges(unittest.TestCase):
    def test_order_ids_named_after_object_prototype(self):
        names = ['constructor', '__proto__', 'toString', 'hasOwnProperty']
        orders = [order(n, 'PENDING', parent=None) for n in names] + [order('valueOf', 'LEASED', parent='constructor')]
        log = [issued(i + 1, 900 + i, n) for i, n in enumerate(names)] + [issued(9, 950, 'valueOf', 'constructor', 'constructor'),
                                                                        row(10, 960, 'lease.granted', 'valueOf', expires=2000)]
        s = snap(orders, {'valueOf': {'holder': 'team:lead', 'expires': 2000}})
        got = cards(classify(s, log, [sent('e', 5, 'prototype', False, under='__proto__', code='x')]))
        self.assertEqual(sorted(got), sorted(names + ['valueOf', 'prototype']))
        self.assertEqual((got['constructor']['facts']['kids_open'], got['valueOf']['parent'], got['valueOf']['top']), (1, 'constructor', 'constructor'))
        self.assertEqual(got['__proto__']['flags'], ['7b'])
        held = run(('holders', [list(got.values())]))[0]
        self.assertEqual(held, {'team:lead': {'orders': [{'id': 'valueOf', 'title': 'Order valueOf'}], 'expired': []}})
        self.assertEqual(run(('holders', [[{'id': 'x', 'state': 'LEASED', 'flags': [], 'title': '', 'facts': {'holder': '__proto__'}}]]))[0],
                         {'__proto__': {'orders': [{'id': 'x', 'title': ''}], 'expired': []}})

    def test_a_parent_loop_still_gives_every_order_a_card(self):
        got = cards(classify(snap([order('a', 'PENDING', parent='b'), order('b', 'PENDING', parent='a')])))
        self.assertEqual(sorted(got), ['a', 'b'])

    def test_no_snapshot_gives_only_ghosts(self):
        self.assertEqual(run(('classify', classify(None)['args']))[0], [])
        self.assertEqual([c['id'] for c in run(('classify', classify(None, sent_=[sent('e', 1, 'g', None)])['args']))[0]], ['g'])

    def test_holders_valid_and_expired_leases_in_card_order(self):
        got = run(('holders', [[
            {'id': 'a', 'state': 'LEASED', 'flags': [], 'title': 'A', 'facts': {'holder': 'agent:w'}},
            {'id': 'b', 'state': 'LEASED', 'flags': ['7a'], 'title': 'B', 'facts': {'holder': 'agent:w'}},
            {'id': 'c', 'state': 'LEASED', 'flags': ['7f'], 'title': 'C', 'facts': {'holder': 'agent:w'}},
            {'id': 'd', 'state': 'PENDING', 'flags': [], 'title': 'D', 'facts': {'to': 'agent:v'}},
            {'id': 'e', 'state': 'JUDGING', 'flags': [], 'title': 'E', 'facts': {'submitter': 'agent:v'}}]]))[0]
        self.assertEqual(got, {'agent:w': {'orders': [{'id': 'a', 'title': 'A'}, {'id': 'c', 'title': 'C'}], 'expired': [{'id': 'b', 'title': 'B'}]}})

    def test_subject(self):
        log = [{'seq': 1, 'kind': 'ask.raised', 'ask': 'q', 'about': 'x'}, {'seq': 2, 'kind': 'ask.answered', 'ask': 'q'}]
        got = run(('subject', [{'kind': 'lease.granted', 'order': 'o'}, []]), ('subject', [{'kind': 'order.issued', 'body': {'id': 'i'}}, []]),
                  ('subject', [log[0], log]), ('subject', [log[1], log]), ('subject', [{'kind': 'org.set'}, []]),
                  ('subject', [{'kind': 'ask.raised', 'ask': 'p', 'about': None}, []]))
        self.assertEqual(got, ['o', 'i', 'x', 'x', None, None])


@unittest.skipUnless(NODE, 'node is not installed, so web/status.js cannot be run here (CI installs it)')
class LogMerge(unittest.TestCase):
    @staticmethod
    def page(rows, nxt, ledger='L1', total=None):
        return {'rows': total if total is not None else nxt, 'next': nxt, 'source': {'ledger': ledger}, 'log': [{'seq': s, 't': s} for s in rows]}

    def test_overlapping_pages_add_each_row_once(self):
        first = run(('mergeLog', [None, self.page([1, 2, 3], 3)]))[0]
        self.assertEqual(([r['seq'] for r in first['log']], first['next'], first['ledger'], first['restart']), ([1, 2, 3], 3, 'L1', False))
        second = run(('mergeLog', [first, self.page([2, 3, 4, 5], 5)]))[0]
        self.assertEqual(([r['seq'] for r in second['log']], second['next']), ([1, 2, 3, 4, 5], 5))
        same = run(('mergeLog', [second, self.page([], 5)]))[0]
        self.assertEqual(([r['seq'] for r in same['log']], same['next']), ([1, 2, 3, 4, 5], 5))
        shuffled = run(('mergeLog', [None, self.page([3, 1, 2, 2], 3)]))[0]
        self.assertEqual([r['seq'] for r in shuffled['log']], [1, 2, 3])

    def test_another_ledger_starts_again_at_zero(self):
        held = run(('mergeLog', [None, self.page([1, 2, 3], 3)]))[0]
        moved = run(('mergeLog', [held, self.page([4], 4, ledger='L2')]))[0]
        self.assertEqual((moved['log'], moved['next'], moved['ledger'], moved['restart']), ([], 0, 'L2', True))
        again = run(('mergeLog', [moved, self.page([1, 2], 2, ledger='L2')]))[0]
        self.assertEqual(([r['seq'] for r in again['log']], again['restart']), ([1, 2], False))

    def test_a_shorter_ledger_starts_again(self):
        held = run(('mergeLog', [None, self.page([1, 2, 3], 3)]))[0]
        shorter = run(('mergeLog', [held, dict(self.page([], 3, total=1), source={'ledger': None})]))[0]
        self.assertEqual((shorter['restart'], shorter['next']), (True, 0))
        self.assertEqual(run(('mergeLog', [held, self.page([], 3, total=2)]))[0]['restart'], True)

    def test_an_answer_that_names_no_ledger_is_another_ledger(self):
        held = run(('mergeLog', [None, self.page([1], 1)]))[0]
        moved = run(('mergeLog', [held, dict(self.page([2], 2), source={})]))[0]
        self.assertEqual((moved['ledger'], moved['restart'], moved['log']), (None, True, []))
        first = run(('mergeLog', [None, dict(self.page([], 0), source={'ledger': None})]))[0]
        grown = run(('mergeLog', [first, self.page([1], 1)]))[0]
        self.assertEqual((grown['ledger'], grown['restart'], [r['seq'] for r in grown['log']]), ('L1', False, [1]), 'an empty ledger that gets its first row')

if __name__ == '__main__':
    unittest.main()
