#!/usr/bin/env python3
"""The scenes of the order status, built with the real dispatcher in this process (the way test_dispatch.py and sim.py
drive it, with an explicit clock), read back through the real GET /state code (cli.state on a run folder holding the
ledger), then classified twice: by web/status.js under node, and by expect() below, an independent Python reading of
the same rules that never reads status.js.  Case, flags, state and facts must be equal for every card, and every scene
must be the situation it was built to be.

Scenes that are not built here (they happen to a page that is open, not to a ledger):
  s7c-down, s7d-stale  the dispatcher stops answering, or answers late, while the page is open.  Here they appear only as
                       the `live` and last-good-answer inputs (test_7c_7d_*); the page side is in tests/page_harness.js.
  l1-claim             seconds until an open page shows a claim: a latency of the page, not a situation of the ledger.
s1-noanswer is built as a sender record with no reply: the backend tried to send and nothing came back, so nothing
reached the ledger.  Skips, saying so, only when node is not installed.
   python3 -B tests/test_status_scenes.py"""
import json
import math
import os
import re
import shutil
import subprocess
import sys
import tempfile
import unittest

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
sys.path.insert(0, os.path.join(ROOT, 'cockpit'))

import cli                                         # noqa: E402
from dispatcher import Dispatcher, msg             # noqa: E402

STATUS_JS = os.path.join(ROOT, 'web', 'status.js')
NODE = shutil.which('node')
POLL = 5
RULES = {'default': {'first': 120, 'silence': 480}, 'scene-fast@1': {'first': 4, 'silence': 8}}
TOP_JUDGE = {'judge': 'program:judge', 'criteria': 'files are handed in'}
LEAD_JUDGE = {'judge': 'team:lead', 'criteria': 'files are handed in'}
# scene -> (order id, situation, flags): the frozen scene list of the status work, for what can be built in process
SCENES = {
    's1-refused': ('s1p.wide', '1', ['7b']), 's1-noanswer': ('s1n', '1', []),
    's2-pending': ('s2', '2', []), 's2-blocked-ask': ('s2bp.a', '2', []),
    's3-held': ('s3', '3', []), 's3-held-by-subordinate': ('s3s', '3', []), 's4-children': ('s4', '4', []), 's4-parent-waits': ('s4w', '4', ['7b']),
    's5-judging': ('sp.judging', '5', []), 's6-pass': ('sp.pass', '6', []), 's6-fail': ('sp.fail', '6', []),
    's6-dead': ('sp.dead', '6', []), 's6-cancelled': ('sp.cancel', '6', []),
    's7b-refused': ('sp.refused', '3', ['7b']), 's7e-human-ask': ('s7e', '3', ['7e']),
    's7f-quiet': ('s7f', '3', ['7f']), 's7a-expired': ('s7a', '3', ['7a'])}
DRIVER = """
const S = require(process.argv[1]);
let raw = '';
process.stdin.on('data', d => { raw += d; });
process.stdin.on('end', () => { process.stdout.write(JSON.stringify(S.classify(JSON.parse(raw)))); });
"""


# ---- the stage: one dispatcher, one clock, and the backend's record of every envelope it sent ------------------------

def record(m, reply, at, n):
    """The sender record of one envelope and its reply (None: no reply came)."""
    b, lease = m.get('body') or {}, m.get('lease') or {}
    if m['kind'] == 'order.issue':
        order, under = b.get('id'), lease.get('order') or b.get('parent') or None
    else:
        order, under = b['order'] if isinstance(b.get('order'), str) else lease.get('order'), None
    ok = None if reply is None else reply.get('ok') is True
    return {'src': 'backend', 'n': n, 'id': m['id'], 'at': at, 'from': m['from'], 'kind': m['kind'], 'order': order, 'under': under,
            'ok': ok, 'code': reply.get('code') if ok is False else None, 'detail': reply.get('detail') if ok is False else None,
            'events': reply.get('events') or [] if ok else []}


class Stage:
    def __init__(self):
        self.d, self.t, self.n, self.sent = Dispatcher(), 1000, 0, []
        self.send('human:ceo', 'org.set', {'actor': 'team:lead', 'superior': 'human:ceo'})
        self.send('human:ceo', 'org.set', {'actor': 'agent:writer', 'superior': 'team:lead'})

    def send(self, frm, kind, body=None, lease=None, basis=None, dt=1, answer=True):
        self.t, self.n = self.t + dt, self.n + 1
        m = msg('s%04d' % self.n, frm, kind, body, basis, lease)
        reply = self.d.submit(m, self.t) if answer else None
        self.sent.append(record(m, reply, self.t, len(self.sent) + 1))
        return reply

    def top(self, oid, **kw):
        r = self.send('human:ceo', 'order.issue', dict({'id': oid, 'title': 'Scene ' + oid, 'to': 'team:lead', 'writes': [oid + '/'], 'budget': 100, 'accept': TOP_JUDGE}, **kw))
        assert r['ok'], r
        return oid

    def claim(self, who, oid, ttl=None):
        body = {'order': oid} if ttl is None else {'order': oid, 'ttl': ttl}
        r = self.send(who, 'claim.request', body, basis=self.d.s.head)
        assert r['ok'], r
        return r['lease']

    def child(self, lease, oid, writes=None, to='agent:writer', budget=5):
        parent = lease['order']
        return self.send('team:lead', 'order.issue', {'id': oid, 'parent': parent, 'title': 'Scene ' + oid, 'to': to,
                                                      'writes': writes or [oid.replace('.', '/') + '/'], 'budget': budget, 'accept': LEAD_JUDGE}, lease=lease)

    def hand_in(self, lease, key):
        r = self.send('agent:writer', 'artifact.put', {'key': key, 'expect': 0}, lease=lease)
        assert r['ok'], r
        r = self.send('agent:writer', 'report.submit', {'outputs': [{'key': key, 'rev': 1}], 'evidence': 'wrote ' + key}, lease=lease)
        assert r['ok'], r

    def verdict(self, oid, passed, reason=''):
        r = self.send('team:lead', 'verdict', {'order': oid, 'pass': passed, 'retry': False, 'reason': reason}, basis=self.d.s.head)
        assert r['ok'], r


def build():
    """Every scene on one stage, time-based ones last; returns (stage, now)."""
    st = Stage()
    st.top('s2')                                                            # s2-pending
    st.top('s3')                                                            # s3-held
    s3 = st.claim('team:lead', 's3')
    st.send('team:lead', 'report.progress', {'note': '[outline] Writing the outline', 'pct': 30}, lease=s3)
    st.top('s3s')                                                           # s3-held-by-subordinate: addressed to the lead,
    st.claim('agent:writer', 's3s')                                         # claimed by its subordinate: the holder is the writer
    st.top('s4')                                                            # s4-children
    s4 = st.claim('team:lead', 's4')
    for k in ('s4.a', 's4.b', 's4.c'):
        assert st.child(s4, k)['ok']
    st.claim('agent:writer', 's4.b')
    s4c = st.claim('agent:writer', 's4.c')
    st.hand_in(s4c, 's4/c/notes.md')
    st.verdict('s4.c', True)
    st.top('s4w')                                                           # s4-parent-waits
    s4w = st.claim('team:lead', 's4w')
    assert st.child(s4w, 's4w.a')['ok']
    r = st.send('team:lead', 'report.submit', {'outputs': [], 'evidence': 'done'}, lease=s4w)
    assert r['code'] == 'children-open', r
    st.top('s1p')                                                           # s1-refused: a child writing outside its parent
    s1p = st.claim('team:lead', 's1p')
    r = st.child(s1p, 's1p.wide', writes=['elsewhere/'])
    assert r['code'] == 'not-subset', r
    st.send('human:ceo', 'order.issue', {'id': 's1n', 'title': 'Scene s1n', 'to': 'team:lead', 'writes': ['s1n/'], 'budget': 1, 'accept': TOP_JUDGE},
            answer=False)                                                   # s1-noanswer
    st.top('s2bp')                                                          # s2-blocked-ask
    s2bp = st.claim('team:lead', 's2bp')
    assert st.child(s2bp, 's2bp.a')['ok']
    assert st.send('agent:writer', 'ask.raise', {'to': 'team:lead', 'text': 'Which format?', 'order': 's2bp.a', 'blocking': True})['ok']
    st.top('sp')                                                            # the children of situations 5 and 6, and 7b
    sp = st.claim('team:lead', 'sp')
    for k in ('sp.judging', 'sp.pass', 'sp.fail', 'sp.dead', 'sp.cancel', 'sp.refused'):
        assert st.child(sp, k)['ok']
    st.hand_in(st.claim('agent:writer', 'sp.judging'), 'sp/judging/a.md')
    st.hand_in(st.claim('agent:writer', 'sp.pass'), 'sp/pass/a.md')
    st.verdict('sp.pass', True)
    st.hand_in(st.claim('agent:writer', 'sp.fail'), 'sp/fail/a.md')
    st.verdict('sp.fail', False, 'The summary section is missing')
    for _ in range(3):                                                      # three leases of 1 s run out: the third ends it
        st.claim('agent:writer', 'sp.dead', ttl=1)
        st.send('team:lead', 'report.progress', {'note': 'still planning'}, lease=sp, dt=2)
    assert st.d.s.orders['sp.dead']['state'] == 'DEAD'
    assert st.send('team:lead', 'order.cancel', {'order': 'sp.cancel', 'reason': 'No longer needed'}, basis=st.d.s.head)['ok']
    held = st.claim('agent:writer', 'sp.refused')
    r = st.send('agent:writer', 'artifact.put', {'key': 'elsewhere/x.md', 'expect': 0}, lease=held)
    assert r['code'] == 'out-of-scope', r
    st.top('s7e')                                                           # s7e-human-ask
    st.claim('team:lead', 's7e')
    assert st.send('team:lead', 'ask.raise', {'to': 'human:ceo', 'text': 'May this be shared outside the team?', 'order': 's7e'})['ok']
    st.top('s7f', skills=['scene-fast@1'])                                  # s7f-quiet: nothing after the grant
    st.claim('team:lead', 's7f')
    st.top('s7a')                                                           # s7a-expired, last: nothing is posted after it
    st.claim('team:lead', 's7a', ttl=5)
    return st, st.t + 6


def state_answer(st, now):
    """What GET /state?since=0 answers at `now` for this stage's ledger: cli.state on a run folder holding it."""
    run = tempfile.mkdtemp(prefix='status-scenes-')
    try:
        with open(os.path.join(run, cli.LEDGER), 'w', encoding='utf-8') as f:
            f.writelines(json.dumps(e, ensure_ascii=False) + '\n' for e in st.d.log)
        return cli.state(run, now, since=0)
    finally:
        shutil.rmtree(run, True)


# ---- the independent expectation (the same section of the spec, written again; it never reads web/status.js) ----------

OPEN = ('JUDGING', 'LEASED', 'PENDING')
END = {'SUCCEEDED': 'succeeded', 'FAILED': 'failed', 'DEAD': 'dead', 'CANCELLED': 'cancelled'}
LABEL = re.compile(r'^\[([^\]]+)\]')


def expect(snap, log, sent, rules, now, live=True, last_ok=None, poll=POLL):
    """{id: {case, flags, state, facts}} for every order of the snapshot and every ghost."""
    clock, now = now, math.floor(now)
    st = (snap or {}).get('state') or {}
    orders, leases = st.get('orders') or {}, st.get('leases') or {}
    asks = [a for a in (st.get('asks') or {}).values() if a.get('state', 'OPEN') == 'OPEN']
    about = {r.get('ask'): r.get('about') for r in log if r.get('kind') == 'ask.raised'}

    def subject(r):
        if isinstance(r.get('order'), str):
            return r['order']
        return {'order.issued': (r.get('body') or {}).get('id'), 'ask.raised': r.get('about'), 'ask.answered': about.get(r.get('ask'))}.get(r.get('kind'))

    subj = [(subject(r), r) for r in log]
    kids = {}
    for oid, o in orders.items():
        kids.setdefault(o.get('parent'), []).append(oid)

    def desc(x):
        out, todo = set(), list(kids.get(x, []))
        while todo:
            k = todo.pop()
            if k not in out:
                out.add(k)
                todo += kids.get(k, [])
        return out

    def own(x):
        return [r for s, r in subj if s == x or (r.get('kind') == 'order.issued' and (r.get('under') or {}).get('order') == x)]

    def family(x):
        fam = desc(x) | {x}
        return [r for s, r in subj if s in fam]

    def of(x, *kinds):
        return [r for s, r in subj if s == x and r.get('kind') in kinds]

    def situation(x):
        s = orders[x]['state']
        if s == 'LEASED':
            return '4' if any(orders[k]['state'] in OPEN for k in kids.get(x, [])) else '3'
        return {'PENDING': '2', 'JUDGING': '5'}.get(s, '6')

    def latest(recs):
        return max(recs, key=lambda r: (r['at'], r['n'] or 0)) if recs else None

    cards = {}
    for x, o in orders.items():
        case, facts, flags = situation(x), {}, []
        open_kids = [k for k in kids.get(x, []) if orders[k]['state'] in OPEN]
        if case == '2':
            facts.update(to=o.get('to'), attempt=o.get('attempt'))
            issue = of(x, 'order.issued')
            if issue:
                facts['wait'] = now - issue[0]['t']
            if open_kids:
                facts['kids_open'] = len(open_kids)
            hold = sorted((a for a in asks if a.get('about') == x and a.get('blocking') is True), key=lambda a: a.get('touched', 0))
            if hold:
                facts.update(blocked='ask', ask_to=hold[0].get('to'))
            elif any(a in orders and orders[a]['state'] != 'SUCCEEDED' for a in o.get('after') or []):
                facts['blocked'] = 'after'
        elif case in ('3', '4'):
            grants, lease = of(x, 'lease.granted'), leases.get(x)
            if lease:
                facts.update(holder=lease.get('holder'), left=math.floor(lease['expires'] - clock))
            else:
                terms = of(x, 'lease.granted', 'lease.renewed')
                if grants:
                    facts['holder'] = grants[-1].get('by')
                if terms:
                    facts['left'] = math.floor(terms[-1]['expires'] - clock)
            mine = own(x)
            if mine:
                last = mine[-1]
                facts.update(last_seq=last['seq'], last_kind=last['kind'], last_age=now - last['t'])
                text = [last[k] for k in ('note', 'evidence', 'reason') if isinstance(last.get(k), str) and last[k]]
                if text:
                    facts['last_text'] = text[0]
            m = LABEL.match(o['note']) if isinstance(o.get('note'), str) else None
            if m:
                facts['label'] = m.group(1)
            if isinstance(o.get('pct'), (int, float)) and not isinstance(o.get('pct'), bool):
                facts['pct'] = o['pct']
            facts['attempt'] = o.get('attempt')
            if case == '4':
                facts['kids_open'] = len(open_kids)
                facts['kids'] = [{'id': k, 'case': situation(k)} for k in sorted(kids.get(x, []))]
                ages = sorted((-(now - family(k)[-1]['t']), k) for k in open_kids if family(k))
                if ages:
                    facts.update(quietest=ages[0][1], quietest_age=-ages[0][0])
            if lease is None or lease['expires'] <= now:
                flags.append('7a')
            elif grants:
                after = [r['t'] for r in family(x) if r['seq'] > grants[-1]['seq']]
                name = next((s for s in o.get('skills') or [] if s in rules), 'default')
                facts.update(quiet=now - (max(after) if after else grants[-1]['t']), threshold=rules[name]['silence' if after else 'first'], rule=name)
                if facts['quiet'] > facts['threshold']:
                    flags.append('7f')
        elif case == '5':
            facts.update(submitter=o.get('submitter'), judge=(o.get('accept') or {}).get('judge'))
            subs = of(x, 'report.submitted')
            if subs:
                facts['wait'] = now - subs[-1]['t']
        else:
            facts.update(end=END[o['state']], attempt=o.get('attempt'))
            ends = [r for r in of(x, *('order.' + k for k in ('succeeded', 'failed', 'dead', 'cancelled'))) if r['kind'] != 'order.failed' or not r.get('retry')]
            if ends:
                e, issue = ends[-1], of(x, 'order.issued')
                facts.update(end_seq=e['seq'], by=e.get('by'))
                if e.get('reason'):
                    facts['reason'] = e['reason']
                if e.get('cascade'):
                    facts['cascade'] = True
                if issue:
                    facts['took'] = e['t'] - issue[0]['t']
        people = sorted((a for a in asks if a.get('about') == x and str(a.get('to', '')).startswith('human:')), key=lambda a: a.get('touched', 0))
        if people:
            flags.append('7e')
            facts.update(e_to=people[0].get('to'), e_ask=people[0].get('id'), e_text=people[0].get('text'))
        cards[x] = {'case': case, 'flags': flags, 'state': o['state'], 'facts': facts}

    for x in sorted({r['order'] for r in sent if r['kind'] == 'order.issue' and isinstance(r['order'], str)} - set(orders)):
        r = latest([r for r in sent if r['kind'] == 'order.issue' and r['order'] == x])
        facts = {'reply': {True: 'accepted', False: 'refused', None: 'none'}[r['ok']], 'sent_at': r['at'], 'sent_id': r['id'], 'sent_src': r['src'], 'from': r['from']}
        if r['ok'] is False:
            facts.update(code=r['code'], detail=r['detail'])
        cards[x] = {'case': '1', 'flags': [], 'state': 'NONE', 'facts': facts}

    for x, c in cards.items():
        r = latest([r for r in sent if r['order'] == x or r['under'] == x])
        if r is not None and r['ok'] is False:
            c['flags'].append('7b')
            c['facts'].update(b_code=r['code'], b_detail=r['detail'], b_at=r['at'], b_id=r['id'])
        if not live:
            c['flags'].append('7c')
        if last_ok is not None and clock - last_ok > 2 * poll:
            c['flags'].append('7d')
        c['flags'].sort()
        c['facts'] = {k: v for k, v in c['facts'].items() if v is not None}
    return cards


def page(answer, sent, now, live=True, last_ok=None):
    """web/status.js on the same answer, log and records: {id: {case, flags, state, facts}}."""
    job = {'snap': answer, 'log': answer['log'], 'sent': sent, 'rules': RULES, 'nowS': now, 'live': live, 'lastOkS': last_ok, 'pollS': POLL}
    r = subprocess.run([NODE, '-e', DRIVER, STATUS_JS], input=json.dumps(job), capture_output=True, text=True, timeout=60)
    if r.returncode:
        raise AssertionError(r.stderr)
    return {c['id']: {'case': c['case'], 'flags': c['flags'], 'state': c['state'], 'facts': c['facts']} for c in json.loads(r.stdout)}


@unittest.skipUnless(NODE, 'node is not installed, so web/status.js cannot be run here (CI installs it)')
class Scenes(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.stage, cls.now = build()
        cls.answer = state_answer(cls.stage, cls.now)

    def test_the_answer_is_the_whole_ledger(self):
        self.assertEqual((self.answer['rows'], len(self.answer['log']), self.answer['more']), (len(self.stage.d.log), len(self.stage.d.log), False))

    def test_every_scene_is_what_it_was_built_to_be(self):
        want = expect(self.answer, self.answer['log'], self.stage.sent, RULES, self.now, True, self.now)
        for scene, (oid, case, flags) in sorted(SCENES.items()):
            self.assertIn(oid, want, scene)
            self.assertEqual((want[oid]['case'], want[oid]['flags']), (case, flags), scene)
        f = {oid: want[oid]['facts'] for oid, _, _ in SCENES.values()}
        self.assertEqual((f['s1p.wide']['reply'], f['s1p.wide']['code'], f['s1n']['reply']), ('refused', 'not-subset', 'none'))
        self.assertEqual((f['s2bp.a']['blocked'], f['s2bp.a']['ask_to']), ('ask', 'team:lead'))
        self.assertEqual((f['s3']['holder'], f['s3']['label'], f['s3']['rule']), ('team:lead', 'outline', 'default'))
        self.assertEqual((f['s3s']['holder'], self.stage.d.s.orders['s3s']['to']), ('agent:writer', 'team:lead'))
        self.assertEqual((f['s4']['kids_open'], [k['case'] for k in f['s4']['kids']]), (2, ['2', '3', '6']))
        self.assertEqual(f['s4w']['b_code'], 'children-open')
        self.assertEqual((f['sp.judging']['submitter'], f['sp.judging']['judge']), ('agent:writer', 'team:lead'))
        self.assertEqual([f[k]['end'] for k in ('sp.pass', 'sp.fail', 'sp.dead', 'sp.cancel')], ['succeeded', 'failed', 'dead', 'cancelled'])
        self.assertEqual((f['sp.fail']['reason'], f['sp.cancel']['reason'], f['sp.dead']['attempt']), ('The summary section is missing', 'No longer needed', 4))
        self.assertEqual(f['sp.refused']['b_code'], 'out-of-scope')
        self.assertEqual((f['s7e']['e_to'], f['s7e']['e_text']), ('human:ceo', 'May this be shared outside the team?'))
        self.assertEqual((f['s7f']['rule'], f['s7f']['threshold']), ('scene-fast@1', 4))
        self.assertGreater(f['s7f']['quiet'], 4)
        self.assertLessEqual(f['s7a']['left'], 0)

    def test_the_page_and_the_expectation_agree_on_every_card(self):
        want = expect(self.answer, self.answer['log'], self.stage.sent, RULES, self.now, True, self.now)
        got = page(self.answer, self.stage.sent, self.now, True, self.now)
        self.assertEqual(sorted(got), sorted(want))
        for oid in sorted(want):
            self.assertEqual(got[oid], want[oid], oid)

    def test_the_boundaries_seen_from_both_sides_agree(self):
        for now in (self.now - 1, self.now, self.now + 0.5, self.now + 120):
            want = expect(self.answer, self.answer['log'], self.stage.sent, RULES, now, True, self.now)
            self.assertEqual(page(self.answer, self.stage.sent, now, True, self.now), want, now)
        at = lambda now: expect(self.answer, self.answer['log'], self.stage.sent, RULES, now, True, None)['s7a']
        self.assertEqual((at(self.now - 1)['flags'], at(self.now - 1)['facts']['left']), (['7a'], 0), 'no time left is run out')
        self.assertEqual((at(self.now - 2)['flags'], at(self.now - 2)['facts']['left']), ([], 1), 'one second left is still a lease')
        for now in (self.now - 2, self.now - 1):
            self.assertEqual(page(self.answer, self.stage.sent, now)['s7a'], at(now))

    def test_7c_7d_when_the_dispatcher_does_not_answer(self):
        for live, last_ok, extra in ((False, self.now, ['7c']), (True, self.now - 10, []), (False, self.now - 11, ['7c', '7d'])):
            want = expect(self.answer, self.answer['log'], self.stage.sent, RULES, self.now, live, last_ok)
            self.assertEqual(page(self.answer, self.stage.sent, self.now, live, last_ok), want)
            for oid, _, flags in SCENES.values():
                self.assertEqual(want[oid]['flags'], sorted(flags + extra), oid)


if __name__ == '__main__':
    unittest.main()
