"""Exercise coordination through the same handlers as the page, without starting a model."""
import concurrent.futures
import fcntl
import json
import os
from pathlib import Path
import sys
import tempfile
import unittest
from unittest import mock

HERE = Path(__file__).resolve().parent
sys.path[:0] = [str(HERE.parent / 'cockpit'), str(HERE)]

import live
import planning
import serve
from test_calendar import MemoryServer, request
from test_cockpit import TEAM


class WorkgroupsTest(unittest.TestCase):
    def setUp(self):
        temp = tempfile.TemporaryDirectory()
        self.addCleanup(temp.cleanup)
        self.root = Path(temp.name)
        for patch in (mock.patch.object(serve, 'Server', MemoryServer),
                      mock.patch.object(live.Live, 'start', lambda instance: instance)):
            patch.start()
            self.addCleanup(patch.stop)
        self.registry = self.root / 'registry.json'
        self.start()

    def start(self, **options):
        self.live = serve.start(str(self.root / 'runs'), TEAM, skill_registry=str(self.registry), **options)
        self.addCleanup(self.live.srv.server_close)
        self.run = os.path.basename(self.live.run)

    def call(self, method, path, data=None, status=200, **kwargs):
        code, out = request(self.live, method, path, data, **kwargs)
        self.assertEqual(code, status, out)
        return out

    def test_task_skill_and_member_history_survives_restart_and_catalog_change(self):
        self.assertEqual(self.call('GET', '/swarms')['registry_status'], 'unavailable')
        order = planning.envelope(dict(title='Compile a checklist', goal='Check the files.', writes='', budget=2),
                                  'check', self.live.lead, 'send-check')
        order['body']['skills'] = ['required-review']
        self.assertTrue(self.call('POST', '/message', order)['ok'])
        worker = self.live.cast[1][0]
        lib = self.live.srv.library
        with lib.transaction() as doc:
            local = lib.add(doc, 'skill-receipt', 'skill', 'Review code', 'accepted', worker,
                            dict(run=self.run, order='check', path='check.txt'))
            old = lib.add(doc, 'old-skill', 'skill', 'Earlier review', 'superseded', worker, None, version=2)
            lib._plan(doc, self.run, 'check', 1, worker, 10, {'uses': [old['id'], local['id']]})
            lib._plan(doc, self.run, 'check', 2, worker, 12, {'uses': [old['id']]})
            lib._plan(doc, 'unrelated', 'check', 1, worker, 11, {'uses': []})
            lib.add(doc, 'proposal', 'skill', 'Experimental', 'proposed', worker, None)
        same_id = local['id']
        self.registry.write_text(json.dumps({'skills': [dict(id=same_id, title='Shared review', version='2.1',
                                                             category='review', status='testing')]}))
        view = self.call('GET', '/swarms')
        self.assertEqual(view['registry_status'], 'ready')
        self.assertEqual([s['actor'] for s in view['members']], [a for a, _ in self.live.cast])
        self.assertEqual(view['tasks'][0]['skills'], ['required-review'])
        self.assertEqual(view['tasks'][0]['used_skills'], ['library:' + old['id'], 'library:' + same_id])
        self.assertEqual(view['tasks'][0]['skill_receipts'][0]['version'], 2)
        self.assertEqual({s['id'] for s in view['skills']}, {'library:' + same_id, 'registry:' + same_id})

        create = dict(run=self.run, name='Review team', goal='Record reviews', members=[worker], tasks=['check'],
                      request_id='create-1')
        group = self.call('POST', '/swarms', create)['swarm']
        gid = group['id']
        self.assertEqual(self.call('POST', '/swarms', create)['swarm'], group)
        self.call('POST', '/swarms', dict(create, goal='Other goal'), 409)
        note = dict(run=self.run, swarm=gid, id='note-1', text='Verified the checklist.', task='check',
                    member=worker, skill='registry:' + same_id)
        updated = self.call('POST', '/swarms/note', note)['swarm']
        self.assertEqual(updated['notes'][0]['skill_version'], '2.1')
        self.assertEqual(updated['notes'][0]['skill_title'], 'Shared review')
        self.assertEqual(updated['revision'], group['revision'] + 1)
        self.registry.unlink()
        self.assertEqual(self.call('POST', '/swarms/note', note)['swarm'], updated)
        self.call('POST', '/swarms/note', dict(note, id='missing'), 503)
        self.call('POST', '/swarms/note', dict(note, text='Different'), 409)
        self.call('POST', '/swarms', dict(create, id=gid, revision=group['revision']), 409)
        latest = self.call('POST', '/swarms', dict(create, id=gid, revision=updated['revision'], members=[], tasks=[]))['swarm']
        self.assertEqual(latest['notes'], updated['notes'])
        self.call('POST', '/swarms/note', dict(note, id='other'), 400)
        self.assertEqual(self.call('POST', '/swarms/note', note)['swarm'], latest)
        self.assertEqual(self.call('POST', '/swarms', create)['swarm'], latest)
        final = self.call('POST', '/swarms/note', dict(run=self.run, swarm=gid, id='note-2', text='Done.',
                                                       skill='library:' + same_id))['swarm']
        self.assertEqual([n['id'] for n in final['notes']], ['note-1', 'note-2'])
        self.assertEqual(final['notes'][1]['skill_version'], 1)
        self.assertEqual(self.call('GET', '/team')['launched'], 0)

        past = self.run
        self.live.srv.server_close()
        self.start()
        self.assertEqual(self.call('GET', '/swarms')['swarms'], [])
        historical = self.call('GET', '/swarms?run=' + past)
        self.assertFalse(historical['writable'])
        self.assertEqual(historical['swarms'], [final])
        self.call('POST', '/swarms/note', note, 409)
        self.call('POST', '/swarms', create, 409)

    def test_public_blackboard_projection_and_live_run_isolation(self):
        board = self.root / 'board'
        board.mkdir()
        lock = board / '.lock'
        lock.touch()
        (board / 'swarm.json').write_text(json.dumps(dict(version=1, backend='local', swarm_id='board-id')))
        (board / 'members.json').write_text(json.dumps({'reviewer': dict(role='verifier', engine='codex',
                                                                        phase='WAITING', session_id='PRIVATE')}))
        posts = [dict(seq=i, time='2026-11-01T00:00:%02d+00:00' % i, agent='reviewer', channel='main',
                      text='Review %d' % i, kind='post') for i in range(1, 25)]
        posts += [dict(posts[-1], seq=i + 25, channel=channel, kind=kind, text='PRIVATE')
                  for i, (channel, kind) in enumerate([('private', 'post'), ('main', 'brief'), ('main', 'control')])]
        log = board / 'board.jsonl'
        log.write_bytes(b''.join(json.dumps(post).encode() + b'\n' for post in posts))
        (board / 'runtime.json').write_text('not readable as json')
        initial = {p.name: p.read_bytes() for p in board.iterdir()}
        self.assertIsNone(self.call('GET', '/swarms')['board'])
        old = self.run
        self.start(swarm_board=str(board))
        snapshot = self.call('GET', '/swarms')['board']
        self.assertEqual(snapshot['status'], 'ready')
        self.assertEqual(snapshot['members'], [dict(name='reviewer', role='verifier')])
        self.assertEqual([p['seq'] for p in snapshot['posts']], list(range(5, 25)))
        self.assertEqual(set(snapshot['posts'][0]), {'seq', 'agent', 'time', 'text'})
        self.assertNotIn('PRIVATE', json.dumps(snapshot))
        self.assertEqual(initial, {p.name: p.read_bytes() for p in board.iterdir()})
        self.assertIsNone(self.call('GET', '/swarms?run=' + old)['board'])
        with lock.open('r') as f:
            fcntl.flock(f.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
            self.assertEqual(self.call('GET', '/swarms')['board'], dict(status='unavailable', posts=[], members=[]))
        self.assertEqual(self.call('GET', '/swarms')['board'], snapshot)
        with log.open('ab') as f:
            f.write(json.dumps(dict(posts[0], seq=28, text='New result')).encode())
        self.assertEqual(self.call('GET', '/swarms')['board']['status'], 'unavailable')
        with log.open('ab') as f:
            f.write(b'\n')
        self.assertEqual(self.call('GET', '/swarms')['board']['posts'][-1]['text'], 'New result')
        with log.open('ab') as f:
            f.truncate(4 * 1024 * 1024 + 1)
        self.assertEqual(self.call('GET', '/swarms')['board']['status'], 'unavailable')
        log.unlink()
        log.symlink_to(self.registry)
        self.assertEqual(self.call('GET', '/swarms')['board']['status'], 'unavailable')

    def test_validation_atomic_failure_and_concurrent_appends(self):
        body = dict(run=self.run, name='Research')
        for patch in [dict(run=''), dict(name=' '), dict(members=[{}]), dict(tasks=['unknown']), dict(goal='a' * 2001)]:
            self.call('POST', '/swarms', dict(body, **patch), 400)
        self.call('GET', '/swarms?run=../unknown', status=404)
        self.call('POST', '/swarms', body, 403, origin='http://wrong.example')
        self.assertEqual(self.call('GET', '/swarms')['swarms'], [])
        group = self.call('POST', '/swarms', body)['swarm']
        record = Path(self.live.run) / 'swarms.json'
        before = record.read_bytes()
        note = dict(run=self.run, swarm=group['id'], id='same', text='An observation')
        with mock.patch('workgroups.os.replace', side_effect=OSError('disk error')):
            self.call('POST', '/swarms/note', note, 500)
        self.assertEqual(record.read_bytes(), before)
        self.assertFalse(list(record.parent.glob('.swarms-*')))
        for patch in [dict(skill='unknown'), dict(member='not-on-team'), dict(id='../bad'), dict(text=' ')]:
            self.call('POST', '/swarms/note', dict(note, **patch), 400)
        with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
            results = list(pool.map(lambda i: self.call('POST', '/swarms/note', dict(note, id='n%d' % (i % 3))),
                                    range(12)))
        stored = self.call('GET', '/swarms')['swarms'][0]
        self.assertEqual({n['id'] for n in stored['notes']}, {'n0', 'n1', 'n2'})
        self.assertEqual((len(results), len(stored['notes']), stored['revision']), (12, 3, 4))
        record.unlink()
        record.symlink_to(self.registry)
        self.call('POST', '/swarms', body, 500)
        self.assertFalse(self.registry.exists())


if __name__ == '__main__':
    unittest.main()
