#!/usr/bin/env python3
"""Measure cockpit editions, compile their scorecard and enforce advancement."""
import argparse
import hashlib
import json
import math
import os
import sys
import tempfile
from datetime import datetime, timezone
from pathlib import Path

HERE = Path(__file__).resolve().parent
SPECS = ('quality_checks_spec.json', 'quality_browser_spec.json')
LOCK = HERE / 'quality_v1.sha256'


def read(path):
    return json.loads(Path(path).read_bytes())


def canonical(value):
    return json.dumps(value, ensure_ascii=True, allow_nan=False, separators=(',', ':'), sort_keys=True).encode()


def digest(value):
    return hashlib.sha256(canonical(value)).hexdigest()


def store(path, value):
    path = Path(path)
    encoded = json.dumps(value, ensure_ascii=True, allow_nan=False, indent=1) + '\n'
    with tempfile.NamedTemporaryFile(dir=path.parent, mode='w', encoding='ascii', delete=False) as stream:
        tmp = Path(stream.name)
        stream.write(encoded)
    try:
        os.replace(tmp, path)
    finally:
        if tmp.exists():
            tmp.unlink()


def rubric():
    policy = read(HERE / 'quality_policy.json')
    metrics = sorted((m for src in SPECS for m in read(HERE / src)), key=lambda m: m['axis'])
    ids = {m['id'] for m in metrics}
    if len(ids) != len(metrics) or len(policy['axes']) != 12:
        raise ValueError('Invalid indicator registry')
    for axis in range(1, 13):
        if not 6 <= sum(m['axis'] == axis for m in metrics) <= 10:
            raise ValueError('Invalid indicator count on axis %s' % axis)
    for m in metrics:
        sign = {'higher': 1, 'lower': -1}[m['direction']]
        if sign * (m['target'] - m['worst']) <= 0:
            raise ValueError('Invalid bounds for ' + m['id'])
    identity = digest([policy, metrics])
    if LOCK.read_text().strip() != identity:
        raise ValueError('Criteria differ from the frozen v1 rubric')
    return policy, metrics, identity


def source_fingerprint(config):
    base = Path(config['root'])
    runtime = [(base, 'cockpit'), (base, 'web')]
    if config['id'] == 'paid' and (base / 'dist').is_dir():
        runtime = [(base, 'dist'), (base, 'data')]
        if config.get('app_root'):
            backend = Path(config['app_root'])
            runtime.extend([(backend, 'cockpit'), (backend, 'web/swarm.css'), (backend, 'web/swarm.js')])
    files = {}
    for parent, name in runtime:
        source = parent / name
        for p in ([source] if source.is_file() else sorted(source.rglob('*'))):
            if p.is_file() and '__pycache__' not in p.parts and p.name not in ('quality-data.json', 'quality.zh.json'):
                files[p.relative_to(parent).as_posix()] = hashlib.sha256(p.read_bytes()).hexdigest()
    if not files:
        raise ValueError('No runtime files under the edition root')
    return digest(files)


def instruments():
    names = ('quality_checks.py', 'quality_browser.py', 'quality_browser_probe.js')
    return digest({name: hashlib.sha256((HERE / name).read_bytes()).hexdigest() for name in names})


def capture(config, fixture, observations):
    _, metrics, key = rubric()
    expected = {m['id'] for m in metrics}
    if observations.keys() != expected:
        raise ValueError('Collector output does not match rubric: ' + ', '.join(sorted(expected ^ observations.keys())))
    return dict(slot=config['id'], revision=config['revision'], runtime_sha256=source_fingerprint(config),
                fixture=fixture, criteria_sha256=key, instruments_sha256=instruments(), captured=datetime.now(timezone.utc).isoformat(timespec='seconds'),
                observations=observations)


def grade(metric, observation):
    value = observation['value']
    evidence = observation.get('evidence')
    if value is None:
        reason = observation.get('reason')
        if not reason:
            raise ValueError('Missing measurement needs a reason for ' + metric['id'])
        return dict(value=None, score=None, passed=None, evidence=evidence, reason=reason)
    if type(value) not in (int, float) or not math.isfinite(value) or evidence is None:
        raise ValueError('Invalid measured value or evidence for ' + metric['id'])
    ratio = (value - metric['worst']) / (metric['target'] - metric['worst'])
    return dict(value=value, passed=ratio >= 1, score=min(1, max(0, ratio)), evidence=evidence)


def compile_report(samples):
    policy, metrics, key = rubric()
    index = {s['slot']: s for s in samples}
    allowed = {v['id'] for v in policy['versions']}
    if len(index) != len(samples) or not index or not index.keys() <= allowed:
        raise ValueError('Provide one sample per selected edition')
    if any(s['criteria_sha256'] != key for s in samples) or len({s['fixture'] for s in samples}) != 1:
        raise ValueError('Mixed criteria or fixture')
    instrument_ids = {s['instruments_sha256'] for s in samples}
    if len(instrument_ids) != 1:
        raise ValueError('Mixed measurement tools')
    versions = [dict(v, **{k: index[v['id']][k] for k in ('revision', 'runtime_sha256', 'captured')})
                for v in policy['versions'] if v['id'] in index]
    rows = [dict(m, results={slot: grade(m, sample['observations'][m['id']]) for slot, sample in index.items()})
            for m in metrics]
    axes = []
    for number, name in enumerate(policy['axes'], 1):
        selected = [row for row in rows if row['axis'] == number]
        summary = {}
        for slot in index:
            observed = [row['results'][slot] for row in selected if row['results'][slot]['score'] is not None]
            summary[slot] = dict(total=len(selected), measured=len(observed), passed=sum(v['passed'] for v in observed),
                                 score=sum(v['score'] for v in observed) / len(observed) if observed else None)
        axes.append(dict(id=number, name=name, results=summary))
    return dict(schema=1, rubric=policy['rubric'], criteria_sha256=key, instruments_sha256=instrument_ids.pop(), fixture=samples[0]['fixture'],
                measured_at=max(s['captured'] for s in samples), versions=versions, axes=axes, metrics=rows)


def verify(report):
    # Recompute from raw values so a hand-edited score, threshold or denominator is detected.
    samples = []
    for version in report['versions']:
        slot = version['id']
        observations = {m['id']: m['results'][slot] for m in report['metrics']}
        samples.append(dict(version, slot=slot, fixture=report['fixture'], criteria_sha256=report['criteria_sha256'],
                            observations=observations, instruments_sha256=report['instruments_sha256']))
    rebuilt = compile_report(samples)
    for k in rebuilt:
        if rebuilt[k] != report.get(k):
            raise ValueError('Report verification failed for ' + k)
    if 'evolution' in report:
        proof = report['evolution']
        result = compare_values(proof['previous_values'], report, proof['slot'])
        if not result['passed'] or any(proof[k] != value for k, value in result.items()):
            raise ValueError('Release did not meet the advancement gate')


def advancement(previous, candidate, slot):
    verify(previous)
    verify(candidate)
    if previous['instruments_sha256'] != candidate['instruments_sha256']:
        raise ValueError('Cannot compare different measurement tools')
    if previous['fixture'] != candidate['fixture']:
        raise ValueError('Cannot compare different fixtures')
    if slot not in {v['id'] for v in previous['versions']} & {v['id'] for v in candidate['versions']}:
        raise ValueError('Edition absent from comparison')
    old_versions = {v['id']: v['runtime_sha256'] for v in previous['versions']}
    for v in candidate['versions']:
        if v['id'] != slot and v['id'] in old_versions and old_versions[v['id']] != v['runtime_sha256']:
            raise ValueError('Reference edition changed: ' + v['id'])
    values = {row['id']: row['results'][slot]['value'] for row in previous['metrics']}
    return compare_values(values, candidate, slot)


def compare_values(values, candidate, slot):
    policy, _, _ = rubric()
    if values.keys() != {m['id'] for m in candidate['metrics']}:
        raise ValueError('Incomplete baseline')
    gains, losses = [], []
    for metric in candidate['metrics']:
        name = metric['id']
        a = grade(metric, dict(value=values[name], evidence={}, reason='Baseline'))
        b = metric['results'][slot]
        if a['score'] is None:
            continue
        if b['score'] is None:
            losses.append(name + ' lost its measurement')
        elif metric['axis'] == policy['variable_axis']:
            if a['passed'] and not b['passed']:
                losses.append(name + ' fell below target')
        elif b['score'] < a['score']:
            losses.append(name)
        elif b['score'] > a['score']:
            gains.append(name)
    return dict(slot=slot, improved=gains, regressed=losses, passed=bool(gains) and not losses)


def seal(previous, candidate, slot):
    gate = advancement(previous, candidate, slot)
    if not gate['passed']:
        raise ValueError('Advancement failed: ' + json.dumps(gate))
    build = next(v for v in previous['versions'] if v['id'] == slot)
    candidate['evolution'] = dict(gate, previous_revision=build['revision'],
                                  previous_report_sha256=digest(previous),
                                  previous_values={r['id']:r['results'][slot]['value'] for r in previous['metrics']})
    return candidate


def release_check(report, root):
    verify(report)
    proof = report['evolution']
    slot = proof['slot']
    if instruments() != report['instruments_sha256']:
        raise ValueError('Measurement tools changed since this report')
    current = source_fingerprint(dict(root=root, id=slot))
    edition = next(v for v in report['versions'] if v['id'] == slot)
    if edition['runtime_sha256'] != current:
        raise ValueError('Runtime differs from the measured edition; measure and seal the new report')



def main():
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest='command', required=True)
    measure = commands.add_parser('measure', help='collect one local edition')
    measure.add_argument('config')
    measure.add_argument('--fixture', required=True)
    measure.add_argument('--out', required=True)
    build = commands.add_parser('build', help='aggregate one to three captured samples')
    build.add_argument('samples', nargs='+')
    build.add_argument('--out', required=True)
    check = commands.add_parser('check', help='recalculate all published scores')
    check.add_argument('report')
    advance = commands.add_parser('advance', help='require a verified improvement over a previous report')
    advance.add_argument('previous')
    advance.add_argument('candidate')
    advance.add_argument('--slot', choices=['gpt','mine','paid'], default='gpt')
    seal_cmd = commands.add_parser('seal', help='store the baseline and advancement proof for packaging')
    seal_cmd.add_argument('previous')
    seal_cmd.add_argument('candidate')
    seal_cmd.add_argument('--slot', choices=['gpt','mine'], default='gpt')
    seal_cmd.add_argument('--out', required=True)
    args = parser.parse_args()
    if args.command == 'measure':
        import quality_browser
        import quality_checks
        rubric()
        config = read(args.config)
        observed = quality_checks.collect(config)
        browser = quality_browser.collect(config)
        quality_checks.attach_browser_records(observed, browser)
        observed.update(browser)
        store(args.out, capture(config, args.fixture, observed))
    elif args.command == 'build':
        store(args.out, compile_report([read(f) for f in args.samples]))
    elif args.command == 'check':
        verify(read(args.report))
        print('All scores and denominators verified.')
    elif args.command == 'seal':
        store(args.out, seal(read(args.previous), read(args.candidate), args.slot))
    else:
        result = advancement(read(args.previous), read(args.candidate), args.slot)
        print(json.dumps(result))
        return 0 if result['passed'] else 1
    return 0


if __name__ == '__main__':
    try:
        sys.exit(main())
    except (OSError, ValueError, KeyError, TypeError) as error:
        sys.exit('quality: %s' % error)
