"""Read the optional local browser toolkit and measure an isolated fixture.

collect(config) returns raw values and evidence. All thresholds live in the
versioned specification. Optional dependencies: Node 22+, Chromium, Pillow and
the local ui-anatomy, design-consistency and ui-harmony skills.
"""
from contextlib import contextmanager
import hashlib
import importlib.util
import json
import math
import os
from pathlib import Path
import statistics
import subprocess
import tempfile
import threading
from urllib import parse, request

HERE = Path(__file__).resolve().parent
SPEC = json.loads((HERE / 'quality_browser_spec.json').read_text())
VIEWS = ('home', 'board', 'team', 'calendar', 'status', 'files', 'ledger', 'swarms')
VISUAL = {
    'accent': 'accent share', 'tint': 'tint share', 'tiers': 'surface lightness tiers',
    'hues': 'hue families', 'hard': 'hard steps share', 'tone': 'tone spread L across hues',
    'type': 'type', 'density': 'density',
}


def missing(reason, **evidence):
    return {'value': None, 'reason': reason, 'evidence': evidence}


def observation(value, **data):
    return {'value': value, 'evidence': data}


def module(path, key):
    spec = importlib.util.spec_from_file_location(key, path)
    if spec is None:
        raise ImportError(key)
    loaded = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(loaded)
    return loaded


def fixture_day(url):
    """Use a recorded working day for the diary; never infer it from wall time."""
    origin = parse.urlsplit(url)
    api = parse.urlunsplit((origin.scheme, origin.netloc, '/history', '', ''))
    try:
        with request.urlopen(api, timeout=5) as reply:
            history = json.load(reply)
        choices = [row.get('day') for row in history['runs'] if row.get('day')]
        return max(choices, default=history.get('today'))
    except (ValueError, KeyError, TypeError, OSError):
        return None


def capture(config, base, paid, scratch, prefix, only_reference=False):
    parts = parse.urlsplit(base)
    if parts.scheme not in ('http', 'https') or parts.hostname not in ('localhost', '127.0.0.1', '::1'):
        return {}, {}, 'Browser measurements require a local isolated fixture'
    if not (config['driver'].is_file() and HERE.joinpath('quality_browser_probe.js').is_file()):
        return {}, {}, 'Optional Chromium driver missing'
    shot = Path(scratch) / (prefix + '.png')
    args = dict(url=base, edition='paid' if paid else 'public', driver=str(config['driver'].resolve()),
                referenceOnly=only_reference, shot=str(shot), day=None if paid else fixture_day(base),
                bandProbe=str(config['measure']) if config['measure'].is_file() else None)
    try:
        proc = subprocess.run(['node', str(HERE / 'quality_browser_probe.js')], input=json.dumps(args),
                              stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, timeout=200)
        if proc.returncode:
            return {}, {}, 'Chromium driver did not complete'
        raw = json.loads(proc.stdout)
    except (OSError, ValueError, subprocess.TimeoutExpired):
        return {}, {}, 'Browser output unavailable'
    viewport = raw.get('desktop', {}).get('home', {})
    summary = {name: viewport[name] for name in ('type', 'density') if name in viewport}
    if shot.is_file() and config['harmony'].is_file():
        try:
            from PIL import Image
            harmony = module(config['harmony'], 'quality_pixel_harmony')
            with Image.open(shot) as picture:
                summary.update(harmony.measure(picture))
        except (ImportError, OSError, ValueError):
            pass
    return raw, summary, None


def bands(output, raw, rules):
    baseline = raw.get('home', {}).get('band')
    judge = module(rules, 'quality_band_rules').judge if rules.is_file() else None
    for view in VIEWS:
        entry = raw.get(view,{})
        current = entry.get('band')
        if not (current and baseline and judge):
            why = 'No comparable first row of cards in this rendered view'
            if not entry.get('valid'):
                why = 'Requested view did not render on this edition'
            elif not baseline:
                why = 'Home has no measurable reference band'
            elif not judge:
                why = 'Optional design-consistency toolkit unavailable'
            output['band.'+view] = missing(why,view=view,routeMatched=bool(entry.get('valid')))
            continue
        problems = judge(baseline, current)
        checks = {rule: not any(p.startswith(rule+' ') for p in problems) for rule in ('R1', 'R2', 'R3', 'R4')}
        row, band = current['row'], current['band']
        output['band.'+view] = observation(sum(checks.values()), rules=checks, firstRowCards=len(row),
            radial=band['aurora'], minimumInside=min(card['inside'] for card in row),
            clearancePx=band['bottom']-max(card['bottom'] for card in row), radiusPx=band['radius'],
            insetPx=[min(card['left'] for card in row)-band['left'],band['right']-max(card['right'] for card in row)],
            diagnostics=problems)


def features(output, views):
    for name, view, key in [('lanes', 'board', 'lanes'),('sidebar', 'home', 'sidebar'),('filter','board','filter'),
                            ('calendar','calendar','days'),('team','team','members'),('diary','diary','diary'),
                            ('swarm','swarms','groups'),('skills','swarms','directory')]:
        entry = views.get(view,{})
        metric = 'feature.'+name
        if entry.get('app') and not entry.get('valid'):
            output[metric] = observation(0, view=view, available=False)
        elif key in entry:
            value = int(entry[key])
            if name == 'diary' and not value and not entry.get('hasDiary'):
                output[metric] = missing('No populated diary was available for this fixture')
            elif name == 'swarm' and not value and entry.get('widget'):
                output[metric] = missing('Group widget rendered without seeded groups')
            elif name == 'skills' and value == 1:
                output[metric] = missing('No seeded skill result was available to check alongside search')
            else:
                output[metric] = observation(value, view=view, observed=value, available=True)


def timings(output, raw):
    visits = raw.get('navigation',[])
    for name,key,factor in [('home','load',1),('paint','fcp',1),('bytes','bytes',1024),('requests','requests',1)]:
        values = [v[key]/factor for v in visits if v.get(key) is not None and v[key] > 0]
        if len(values) == 5:
            output['speed.'+name] = observation(statistics.median(values),samples=values,aggregate='median',cold=True)
    order = raw.get('orders',[])
    if len(order) == 5:
        output['speed.order'] = observation(statistics.median(order),samples=order,aggregate='median')
        output['speed.tail'] = observation(max(order),samples=order,aggregate='maximum')
    polling = raw.get('poll',{})
    if polling.get('repeat') and polling.get('seconds',0) >= 12:
        output['speed.pollbytes'] = observation(polling['bytes']/1024/polling['seconds'],**polling)
        output['speed.pollrate'] = observation(polling['requests']/polling['seconds'],**polling)


def local_origin(url):
    parsed = parse.urlsplit(url)
    if parsed.scheme not in ('http','https') or parsed.hostname not in ('localhost','127.0.0.1','::1'):
        raise ValueError('Visual fixtures must use local HTTP')
    return parse.urlunsplit((parsed.scheme, parsed.netloc, '', '', ''))


@contextmanager
def visual_fixture(edition_url, fixture_url, cache_dir):
    """Serve this edition's HTML/assets with replayable GETs from one recorded run."""
    from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
    from urllib.error import HTTPError

    assets, data = local_origin(edition_url), local_origin(fixture_url)
    history = read_json(data+'/history')
    team = read_json(data+'/team')
    if not history.get('live_run') or team.get('run') != history['live_run']:
        raise ValueError('Fixture run unavailable')
    # The board's wall clock advances while an idle ledger remains byte-identical.
    records = [{k:v for k,v in item.items() if k != 'now'} for item in history['board']]
    identity = [team['run'],team.get('ledger_updated'),team.get('launches'),records]
    digest = hashlib.sha256(json.dumps(identity,sort_keys=True).encode('utf8')).hexdigest()
    directory = Path(cache_dir) / digest
    directory.mkdir(mode=0o700,parents=True,exist_ok=True)
    generated = {'events.js','audit.js','know.js','diary.md','head.json','live.json','hq.json',
                 'hq.head.json','moments.json','diary.json'}
    class Reader(BaseHTTPRequestHandler):
        def log_message(self, *args):
            pass

        def do_GET(self):
            url = parse.urlsplit(self.path)
            if url.scheme or url.netloc or not url.path.startswith('/') or '..' in url.path.split('/'):
                self.send_error(400)
                return
            static = (url.path == '/' or url.path.startswith('/web/') or
                      (url.path.startswith('/pro/') and url.path[5:] not in generated and not url.path.startswith('/pro/raw/')))
            endpoint = assets if static else data
            query = parse.parse_qsl(url.query,keep_blank_values=True)
            if not static and url.path.startswith('/pro/'):
                query = [(k,v) for k,v in query if k != 'v']
            resource = url.path + ('?'+parse.urlencode(query) if query else '')
            entry = directory / hashlib.sha256(resource.encode()).hexdigest()
            try:
                if not static and entry.is_file():
                    content_type, payload = entry.read_bytes().split(b'\n',1)
                    content_type = content_type.decode('ascii')
                else:
                    with request.urlopen(endpoint+resource,timeout=10) as reply:
                        content_type = reply.headers.get('Content-Type','application/octet-stream')
                        payload = reply.read()
                    if not static:
                        with tempfile.NamedTemporaryFile(dir=directory,delete=False) as staged:
                            staged.write(content_type.encode('ascii')+b'\n'+payload)
                        try:
                            os.link(staged.name,entry)
                        except FileExistsError:
                            winner, payload = entry.read_bytes().split(b'\n',1)
                            content_type = winner.decode('ascii')
                        finally:
                            Path(staged.name).unlink()
                self.send_response(200)
                self.send_header('Content-Type',content_type)
                self.send_header('Content-Length',str(len(payload)))
                self.end_headers()
                self.wfile.write(payload)
            except HTTPError as error:
                self.send_error(error.code)
            except (OSError,ValueError):
                self.send_error(502)

    server = ThreadingHTTPServer(('127.0.0.1',0),Reader)
    thread = threading.Thread(target=server.serve_forever,daemon=True)
    thread.start()
    try:
        entry = 'http://127.0.0.1:%d%s' % (server.server_port,parse.urlsplit(edition_url).path or '/')
        yield entry,digest
    finally:
        server.shutdown()
        server.server_close()
        thread.join()


def read_json(url):
    with request.urlopen(url,timeout=5) as response:
        return json.load(response)


def sources_for(config):
    basedir = Path(config.get('skills') or os.environ.get('QUALITY_SKILLS') or Path.home()/'.agents'/'skills')
    def script(skill, file):
        return basedir / skill / 'scripts' / file
    return dict(driver=script('ui-anatomy','cdp.js'),measure=script('design-consistency','measure.js'),
                rules=script('design-consistency','check.py'),harmony=script('ui-harmony','harmony.py'))


def visuals(config, sources, scratch, initial=None):
    """Use the optional canonical visual fixture only for the eight home appearance checks."""
    url, paid = config['url'], config.get('id') == 'paid'
    canonical, cache = config.get('visual_fixture_url'), config.get('visual_cache_dir') or scratch
    def frame(base, is_paid, label):
        if canonical:
            with visual_fixture(base,canonical,cache) as (proxy,digest):
                _, values, _ = capture(sources,proxy,is_paid,scratch,label,True)
                return values,digest
        _, values, _ = capture(sources,base,is_paid,scratch,label,True)
        return values,None

    why = 'Comparable paid and edition home viewports unavailable'
    out = {'visual.'+name: missing(why) for name in VISUAL}
    try:
        if canonical or initial is None:
            measured, digest = frame(url,paid,'paired')
        else:
            measured,digest = initial,None
        ref = measured if paid else {}
        source = config.get('paid_measurement')
        if not paid and source:
            prior = json.loads(Path(source).read_text())
            for name, field in VISUAL.items():
                item = prior.get('visual.'+name,{}).get('evidence',{})
                if item.get('fixtureDigest') == digest and isinstance(item.get('observed'), (int,float)):
                    ref[field] = item['observed']
        elif not paid and config.get('paid_url'):
            ref, ref_digest = frame(config['paid_url'],True,'reference')
            if ref_digest != digest:
                return out
        for key,field in VISUAL.items():
            if field in measured and field in ref and all(math.isfinite(v) for v in [measured[field],ref[field]]):
                cell = observation(abs(measured[field]-ref[field]),observed=measured[field],
                    reference=ref[field],viewport=[1440,900],theme='light')
                if digest:
                    cell['evidence'].update(fixture='Recorded GET replay; edition assets',fixtureDigest=digest)
                out['visual.'+key] = cell
    except (ImportError,KeyError,OSError,ValueError,TypeError):
        pass
    return out


def collect_visual(config):
    with tempfile.TemporaryDirectory(prefix='quality-visual-') as scratch:
        return visuals(config,sources_for(config),scratch)


def collect(config):
    output = {r['id']:missing('Required route, fixture records or measurement tool unavailable') for r in SPEC}
    url = config.get('url')
    if not url:
        return output
    sources = sources_for(config)
    paid = config.get('id') == 'paid'
    with tempfile.TemporaryDirectory(prefix='cockpit-quality-browser-') as temp:
        raw, measured, err = capture(sources,url,paid,temp,'version')
        if err:
            return {key:missing(err) for key in output}
        output.update(visuals(config,sources,temp,measured))
    views = raw.get('desktop',{})
    bands(output,views,sources['rules'])
    features(output,views)
    for name,view in [('search','board'),('filter','board'),('open','board'),('escape','board'),('focus','board'),
                      ('tab','home'),('month','calendar'),('group','swarms')]:
        route = views.get(view,{})
        if not route.get('valid'):
            reason = 'Required view did not render'
        elif view in raw.get('incompleteActions',[]):
            reason = 'Browser input sequence did not finish on this route'
        else:
            reason = 'Required controls or seeded rows could not be exercised'
        output['action.'+name] = missing(reason,view=view,routeMatched=bool(route.get('valid')))
    for id_, item in raw.get('actions',{}).items():
        output['action.'+id_] = observation(item['value'],**{k:v for k,v in item.items() if k!='value'})
    for view in VIEWS:
        phone = raw.get('mobile',{}).get(view,{}).get('phone',{})
        if not phone:
            output['mobile.'+view] = missing('Requested view did not render at phone width',view=view)
        if phone and phone.get('scale') is not None:
            fits = phone['width'] <= phone['viewport'] + 1
            natural = phone['device'] and abs(phone['viewport']-390)<=1 and phone['scale']>=.99
            output['mobile.'+view] = observation(int(fits)+int(natural),fits=bool(fits),natural=bool(natural),**phone)
    if not raw.get('orders'):
        for name in ('order','tail'):
            output['speed.'+name] = missing('No rendered link to a supported order detail API',view='board')
    timings(output, raw)
    return output


