// Chromium measurements for the release scorecard. Optional toolkit paths are supplied by the Python runner.
'use strict';
const fs = require('node:fs');
const cfg = JSON.parse(fs.readFileSync(0, 'utf8'));
const {openBrowser, runActions, sleep} = require(cfg.driver);
const routeNames = ['home', 'board', 'team', 'calendar', 'status', 'files', 'ledger', 'swarms'];
const raw = {desktop: {}, mobile: {}, actions: {}, navigation: [], orders: []};
const ui = (fn, ...args) => '(' + fn.toString() + ')(' + args.map(arg => JSON.stringify(arg)).join(',') + ')';

function inspect(view, edition, wanted) {
  const visible = element => Boolean(element?.getClientRects().length) && window.getComputedStyle(element).visibility === 'visible';
  const all = (sel, root = document) => Array.from(root.querySelectorAll(sel)).filter(visible);
  const count = sel => all(sel).length;
  const app = Boolean(document.querySelector('main') && count('nav button,nav a'));
  const v = all('main[data-view],main section[data-view]').find(el => el.dataset.view === wanted);
  const panel = edition === 'paid' && (view === 'status' || view === 'calendar');
  const panelSel = view === 'calendar' ? '[data-cal-month]' : '[data-hq-panel]';
  const valid = Boolean(app && v && (!panel || count(panelSel)));
  const result = {app, valid};
  if (!valid) return result;
  const {clientWidth: viewport} = document.documentElement;
  const meta = document.querySelector('meta[name=viewport]');
  result.phone = {viewport, width: document.documentElement.scrollWidth,
    device: !!meta && /width\s*=\s*device-width/i.test(meta.content), scale: window.visualViewport?.scale ?? null};
  if (view === 'home') {
    const navRegions = all('nav,[role=navigation]');
    result.sidebar = navRegions.some(node => {
      const items = all('a,button',node).map(item => item.getBoundingClientRect());
      const {left, width} = node.getClientRects().item(0);
      return left <= innerWidth * .25 && width < innerWidth * .45 && items.length >= 3 &&
        Math.max(...items.map(item => item.top)) - Math.min(...items.map(item => item.top)) > 48;
    });
    const sizes = new Set();
    let n = 0;
    const texts = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    for (let entry; (entry = texts.nextNode());) {
      if (!entry.textContent.trim() || !visible(entry.parentElement)) continue;
      const range = document.createRange();
      range.selectNodeContents(entry);
      const bounds = Array.from(range.getClientRects());
      if (bounds.some(r=>r.height && r.width && r.right>0 && r.bottom>0 && r.left<innerWidth && r.top<innerHeight)) {
        n += 1;
        sizes.add(getComputedStyle(entry.parentElement).fontSize);
      }
    }
    result.type = sizes.size;
    result.density = n * 1e6 / (innerWidth * innerHeight);
  }
  if (view === 'board') {
    result.lanes = new Set(all('[data-column]',v).map(node => node.dataset.column)).size;
    result.tasks = all('[data-task-key],[data-card]',v).length;
    result.filter = Number(all('input[type=search]',v).length > 0) +
      Number(all('select,button[aria-haspopup=menu]',v).length > 0);
  }
  if (view === 'calendar') result.days = count('[data-cal-day],.day-cell');
  if (view === 'diary') {
    result.diary = count('li[data-ptr]:not([data-ptr=""])');
    result.hasDiary = !!v.querySelector('[data-day-diary],[data-diary-entries],[data-obj^="family:"],table[data-day]');
  }
  if (view === 'team') {
    let members = [];
    for (const selector of ['[data-select-seat]','[data-org-node]','[data-agent]','[data-obj^="agent:"]']) {
      members = all(selector,v);
      if (members.length) break;
    }
    const ids = members.map(el => el.dataset.selectSeat || el.dataset.orgNode || el.dataset.agent ||
      (el.dataset.obj || '').replace(/^agent:/,'')).filter(Boolean);
    result.members = new Set(ids).size;
  }
  if (view === 'swarms') {
    result.groups = count('[data-swarm-id]');
    result.directory = Number(count('.sw-search input') > 0) + Number(count('.sw-skill') > 0);
    result.widget = count('.sw-catalog') > 0;
  }
  return result;
}

function route(name) {
  if (cfg.edition === 'paid') {
    const page = {status: 'home', calendar: 'home', ledger: 'diary'}[name] || name;
    return {fragment: '#view=' + page, page};
  }
  if (name === 'diary') return {fragment: '#/day/' + cfg.day, page: 'day'};
  return {fragment: name === 'home' ? '#/' : '#/' + name, page: name};
}
async function visit(b, name, delay = 850) {
  const spec = route(name);
  await b.goto('about:blank', 0);
  await b.goto(cfg.url.split('#')[0] + spec.fragment, delay);
  if (cfg.edition === 'paid' && ['calendar','status'].includes(name)) {
    const button = name === 'calendar' ? '[data-cal-open]' : '[data-hq-open="*"]';
    if (await b.evaluate(ui(sel => !!document.querySelector(sel),button))) await runActions(b,['click:' + button]);
  }
  return b.evaluate(ui(inspect,name,cfg.edition,spec.page));
}
async function technology(mobile) {
  const b = await openBrowser({width: mobile ? 390 : 1440, height: mobile ? 844 : 900,
    mobile, scale: mobile ? 2 : 1, scheme: 'light'});
  await b.send('Network.enable');
  await b.send('Network.setCacheDisabled',{cacheDisabled: true});
  await b.send('Emulation.setEmulatedMedia',{features: [
    {name: 'prefers-color-scheme',value:'light'},{name:'prefers-reduced-motion',value:'reduce'}]});
  return b;
}
function navTiming() {
  const nav = performance.getEntriesByType('navigation')[0];
  const ms = performance.getEntriesByName('first-contentful-paint')[0]?.startTime;
  const local = performance.getEntriesByType('resource').filter(row => new URL(row.name).origin === location.origin);
  return {load: nav.loadEventEnd - nav.startTime, fcp: ms ?? null,
    bytes: [nav,...local].reduce((sum,r) => sum + r.transferSize,0), requests: local.length + 1};
}
async function network(b) {
  const home = await visit(b,'home');
  if (!home.valid) return;
  for (let idx = 0; idx < 5; idx++) {
    if (idx) await visit(b,'home');
    raw.navigation.push(await b.evaluate(ui(navTiming)));
  }
  const start = await b.evaluate('performance.now()');
  await sleep(12000);
  raw.poll = await b.evaluate(ui(since => {
    const rows = performance.getEntriesByType('resource').filter(r =>
      ['fetch','xmlhttprequest'].includes(r.initiatorType) && r.startTime >= since && new URL(r.name).origin === location.origin);
    const paths = new Set();
    let repeat = false;
    for (const row of rows) {
      const path = new URL(row.name).pathname;
      if (paths.has(path)) repeat = true;
      paths.add(path);
    }
    return {seconds:(performance.now()-since)/1000, bytes:rows.reduce((n,r)=>n+r.transferSize,0), requests:rows.length, repeat};
  },start));
}
async function benchmarkOrder(b) {
  raw.orders = await b.evaluate(ui(async () => {
    const link = document.querySelector('a[data-order-link][data-order][data-run]');
    if (!link) return [];
    const query = new URLSearchParams({id:link.dataset.order,run:link.dataset.run});
    const samples = [];
    for (let n=0;n<5;n++) {
      const begin = performance.now();
      const reply = await fetch('/order?' + query,{cache:'no-store'});
      if (!reply.ok) return [];
      const body = await reply.json();
      if (body.order?.id !== link.dataset.order || body.run !== link.dataset.run) return [];
      samples.push(performance.now()-begin);
    }
    return samples;
  }),true);
}
async function actions(b, section) {
  const act = (...steps) => runActions(b,steps);
  const observation = (id,value,details) => { raw.actions[id] = {value: Number(value), ...details}; };
  const rows = '[data-task-key],[data-card]';
  const visibleCount = selector => b.evaluate(ui(s => [...document.querySelectorAll(s)].filter(n => n.getClientRects().length && !n.closest('[hidden]')).length,selector));
  const on = key => key === section && raw.desktop[key]?.valid;
  if (on('home')) {
    await visit(b,'home');
    await act('key:Tab');
    const state = await b.evaluate(ui(() => {
      const {activeElement: el} = document;
      const style = window.getComputedStyle(el);
      return {interactive:el.matches('a[href],button,input,select,[tabindex]'), keyboard:el.matches(':focus-visible'),
        indicator:(parseFloat(style.outlineWidth) > 0 && style.outlineStyle !== 'none') || style.boxShadow !== 'none'};
    }));
    observation('tab',state.interactive && state.keyboard && state.indicator,state);
  }
  if (on('board')) {
    await visit(b,'board');
    if (cfg.edition !== 'paid') await benchmarkOrder(b);
    const count = () => visibleCount(rows);
    let before = await count();
    const scope = 'main [data-view="board"],main[data-view="board"]';
    const search = ':is(' + scope + ') input[type=search]';
    if (before && await visibleCount(search)) {
      await act('click:' + search,'type:qz-nomatch-39df');
      const after = await count();
      observation('search',after===0,{before,after});
    } else if (before) observation('search',false,{before,controls:0});
    await visit(b,'board');
    before = await count();
    const filter = 'select[data-board-filter="column"]';
    if (before && await visibleCount(filter)) {
      const choice = await b.evaluate(ui((sel,total) => {
        const options = Array.from(document.querySelector(sel).options);
        return options.findIndex((o,i) => i>0 && document.querySelector('[data-column="'+CSS.escape(o.value)+'"]')?.querySelectorAll('[data-task-key]').length<total);
      },filter,before));
      if (choice>0) {
        await b.evaluate(ui(sel=>document.querySelector(sel).focus(),filter));
        for (let i=0;i<choice;i++) {
          for (const type of ['keyDown','keyUp']) {
            await b.send('Input.dispatchKeyEvent',{type,key:'ArrowDown',code:'ArrowDown',windowsVirtualKeyCode:40});
          }
        }
        const applied = await b.evaluate(ui(s=>document.querySelector(s).selectedIndex,filter));
        if (applied === choice) {
          const after = await count();
          observation('filter',after<before,{before,after,optionIndex:applied});
        }
      }
    } else if (before) observation('filter',false,{stateFilters:0});
    await visit(b,'board');
    if (await count()) {
      const target = await b.evaluate(ui(sel => {
        const task = [...document.querySelectorAll(sel)].find(el=>el.getClientRects().length>0);
        task.focus();
        return task.dataset.taskKey || task.dataset.card;
      },rows));
      await act('key:Enter','wait:300');
      const dialog = '[data-board-drawer]:not([hidden]),[role=dialog][aria-modal=true]:not([hidden]):not([inert]),aside[data-open=true]';
      const opened = await visibleCount(dialog)>0;
      observation('open',opened,{opened});
      if (opened) {
        await act('key:Escape','wait:300');
        const closed = await visibleCount(dialog)===0;
        observation('escape',closed,{closed});
        const restored = await b.evaluate(ui(id=> {
          const active=document.activeElement.closest('[data-task-key],[data-card]');
          return (active?.dataset.taskKey || active?.dataset.card) === id;
        },target));
        observation('focus',closed && restored,{closed,restored});
      }
    }
  }
  if (on('calendar')) {
    await visit(b,'calendar');
    const month = () => b.evaluate(ui(()=> document.querySelector('[data-cal-month]')?.dataset.calMonth ||
      document.querySelector('#calendar-grid [data-day]')?.dataset.day?.slice(0,7) || ''));
    const before=await month(), next='[data-cal-nav=next],button[data-cal=next]';
    if (before && await visibleCount(next)) {
      await act('click:'+next);
      const after=await month();
      observation('month',!!after && before!==after,{before,after});
    }
  }
  if (on('swarms')) {
    await visit(b,'swarms');
    const inactive = '[data-swarm-id][aria-pressed=false]';
    if (await visibleCount(inactive)) {
      const label = await b.evaluate(ui(s=>document.querySelector(s).firstChild.textContent.trim(),inactive));
      await act('click:'+inactive);
      const state = await b.evaluate(ui((label)=>({
        changed:document.querySelector('[data-swarm-id][aria-pressed=true]')?.firstChild.textContent.trim() === label,
        detail:[...document.querySelectorAll('.sw-stack h3')].some(n=>n.textContent.trim()===label)
      }),label));
      observation('group',state.changed && state.detail,state);
    }
  }
}
async function readViews(mobile) {
  const b = await technology(mobile);
  const data = mobile ? raw.mobile : raw.desktop;
  try {
    const routes = cfg.referenceOnly ? ['home'] : [...routeNames];
    if (!mobile && (cfg.edition==='paid' || cfg.day)) routes.push('diary');
    for (const name of routes) {
      try {
        const entry = await visit(b,name);
        data[name] = entry;
        if (mobile || !entry.valid) continue;
        if (name==='home') await b.shot(cfg.shot);
        if (!cfg.referenceOnly && cfg.bandProbe && !(cfg.edition==='paid' && ['calendar','status'].includes(name))) {
          const measured = await b.evaluate(fs.readFileSync(cfg.bandProbe,'utf8'));
          const band = typeof measured==='string' ? JSON.parse(measured) : measured;
          if (band?.band && band.row?.length) {
            delete band.band.cls;
            for (const card of band.row) card.what='card';
            entry.band = band;
          }
        }
      } catch { data[name] = {unavailable:true}; }
      if (cfg.referenceOnly) break;
    }
    if (!mobile && !cfg.referenceOnly) {
      for (const section of ['home','board','calendar','swarms']) {
        try { await actions(b,section); } catch { (raw.incompleteActions ||= []).push(section); }
      }
