"""Measure protocol, agreement, distribution, resilience, recording and verification.

Only the caller's explicitly selected local build and fixtures are measured.
Detailed evidence contains counts and check identifiers, never source lines or task payloads.
"""

import concurrent.futures
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path
from urllib.parse import urlsplit, urlunsplit
from urllib.request import urlopen

SPEC = Path(__file__).with_name("quality_checks_spec.json")
INVARIANTS = (
    "lease uniqueness",
    "lease membership",
    "terminal immutability",
    "terminal fencing",
    "attempt bound",
    "DEAD provenance",
    "children before submit",
    "cancel cascade",
    "envelope ledger writes",
    "ledger sequence",
    "ledger hash chain",
    "ledger replay",
    "idempotent retry",
)
ACTIONS = "order.issue claim.request lease.renew lease.release artifact.put report.submit verdict order.cancel ask.raise ask.answer state.query".split()
EDGES = (
    "two children",
    "children-open refusal",
    "cascading cancellation",
    "membership refusal",
    "simultaneous expiries",
    "duplicate retry",
)
# Ordered exactly as the historical questionnaire; stable item numbers survive translation.
ITEMS = {
    "rec": "Order and actor|Start and finish times|Known and unknown cost|Verdict and judge|Model ID|Token counts|Prompt|Transcript link|Self-check and refusals|Attempt number|Denied actions|Artifact revision",
    "true": "Unknown cost|No stale date labels|No invented zero usage|Duration text|Second-granularity clock and URL|Unverified work|Typed nodes|No example pool|No template context|Adaptive time window",
    "live": "Incremental feed|Automatic refresh|Streaming adapter|Lease expiry data|Source position and time",
    "ctl": "Four dispatch operations|Supported action kinds|Basis number|Submit action|Dispatcher entry point|Acceptance and refusal reason|Persistent outbox",
    "know": "Skill library|Tool inventory|Launch skill or tool usage|Project wiki|Lessons library|Assigned knowledge and skills",
    "onb": "Protocol documentation|Four schemas and validator|End-to-end sample ledger|One-prompt handoff|Verified first-pass run|Quick-start guide|Agent can query state|Cold onboarding run|Coordinator trial",
    "tree": "Task hierarchy|Three organization levels|Relationship graph|Project switching|Run switching|Hundred-agent exercise",
    "audit": "Time replay|Hashed numbered ledger|Event-to-source mapping|Independent checker|Since-last-visit view|Checker output displayed|Raw record link|Run export",
    "phone": "Home|Team|Timeline|Board|Findings|Results|Files|Ontology|Outer replay",
}


def observed(value, **evidence):
    return {"value": value, "evidence": evidence}


def missing(reason, **evidence):
    return dict(observed(None, **evidence), reason=reason)


def invoke(args, cwd, timeout=180, env=None):
    try:
        result = subprocess.run(
            list(map(str, args)),
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            env=dict(os.environ, PYTHONDONTWRITEBYTECODE="1", **(env or {})),
            timeout=timeout,
        )
    except (OSError, subprocess.TimeoutExpired):
        return None, ""
    return result.returncode, result.stdout.decode(errors="replace")


def output_json(text, marker):
    for line in text.splitlines():
        if line.startswith(marker):
            try:
                return json.loads(line[len(marker) :])
            except ValueError:
                return None


def match_path(config, key):
    value = config.get(key)
    return Path(value).resolve() if value else None


def run_test(file):
    # A verbose console line may be interrupted by a child process or a test's own output.
    # Capture the runner's structured case events in addition to its unmodified diagnostics.
    probe = """import importlib.util,unittest,sys,json
from pathlib import Path
path=Path(sys.argv[1]).resolve()
sys.path.insert(0,str(path.parent))
spec=importlib.util.spec_from_file_location('quality_target_tests',path)
mod=importlib.util.module_from_spec(spec);sys.modules[spec.name]=mod;spec.loader.exec_module(mod)
class Result(unittest.TestResult):
    def __init__(self):
        super().__init__();self.outcomes={}
    def startTest(self,test):
        super().startTest(test);self.outcomes[test.id()]='ok'
    def addSkip(self,test,reason):
        super().addSkip(test,reason);self.outcomes[test.id()]='skipped'
    def addError(self,test,err):
        super().addError(test,err);self.outcomes[test.id()]='ERROR'
    def addFailure(self,test,err):
        super().addFailure(test,err);self.outcomes[test.id()]='FAIL'
    def addSubTest(self,test,subtest,err):
        super().addSubTest(test,subtest,err)
        if err:self.outcomes[test.id()]='FAIL'
    def addUnexpectedSuccess(self,test):
        super().addUnexpectedSuccess(test);self.outcomes[test.id()]='FAIL'
    def addExpectedFailure(self,test,err):
        super().addExpectedFailure(test,err);self.outcomes[test.id()]='skipped'
suite=unittest.defaultTestLoader.loadTestsFromModule(mod)
count=suite.countTestCases()
result=Result();suite.run(result)
for _,error in result.errors+result.failures:
    print(error)
print('Radar tests '+json.dumps({'expected':count,'cases':result.outcomes}))
sys.exit(0 if result.wasSuccessful() else 1)"""
    rc, output = invoke([sys.executable, "-B", "-c", probe, file], file.parent.parent, 300)
    report = output_json(output, "Radar tests ")
    if not report:
        return rc, output, None, {}
    return rc, output, report["expected"], report["cases"]


def measure_tests(root, values, workers, backend_only=False):
    files = sorted((root / "tests").glob("test_*.py"))
    if backend_only:
        files = [
            f
            for f in files
            if f.stem
            in {"test_dispatch", "test_dispatch_states", "test_cockpit", "test_diary", "test_workgroups"}
        ]
    if not files:
        return {}
    with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as pool:
        batches = dict(zip([f.stem for f in files], pool.map(run_test, files)))
    total = passed = skipped = 0
    complete = True
    for rc, out, n, cases in batches.values():
        if n is None or rc not in (0, 1) or n != len(cases):
            complete = False
        passed += sum(v == "ok" for v in cases.values())
        skipped += sum(v == "skipped" for v in cases.values())
        total += len(cases)
    failures = []
    for name, batch in batches.items():
        for identifier, result in batch[3].items():
            method = identifier.rsplit(".", 1)[-1]
            if result in ("FAIL", "ERROR") and re.fullmatch(r"test_\w+", method, re.ASCII):
                failures.append(name + "." + method)
    evidence = dict(
        files=len(files), passed=passed, executed=total - skipped, skipped=skipped, failures=failures
    )
    values["correct.tests"] = (
        observed(passed / (total - skipped), **evidence)
        if complete and total > skipped
        else missing("Incomplete test enumeration.", **evidence)
    )
    if backend_only:
        values["correct.tests"] = missing(
            "The complete private frontend test suite was not supplied.", backend_files=len(files)
        )
    if "test_dispatch" in batches:
        rc, out, n, cases = batches["test_dispatch"]
        graded = [v for v in cases.values() if v != "skipped"]
        if n and len(cases) == n and graded:
            values["correct.replay"] = observed(
                graded.count("ok") / len(graded), passed=graded.count("ok"), executed=len(graded)
            )
    reg = {
        "robust.offline": ("test_status_scenes", "test_7c_7d_when_the_dispatcher_does_not_answer"),
        "robust.overlap": ("test_status", "test_overlapping_pages_add_each_row_once"),
        "robust.rewind": ("test_status", "test_a_shorter_ledger_starts_again"),
        "robust.corrupt": ("test_diary", "test_a_ledger_that_cannot_be_read_writes_nothing"),
        "robust.atomic": ("test_workgroups", "test_validation_atomic_failure_and_concurrent_appends"),
        "robust.timeout": (
            "test_cockpit",
            "test_a_process_past_the_wall_clock_is_ended_and_what_it_left_is_not_taken",
        ),
        "verify.numbers": ("test_diary", "test_the_checker_works_the_metrics_out_itself"),
        "verify.days": ("test_diary", "test_the_checker_reads_what_the_day_view_draws_too"),
        "verify.missing": ("test_diary", "test_an_entry_taken_out_of_the_days_as_well_is_still_missed"),
        "verify.hash": ("test_diary", "test_a_row_cited_with_the_wrong_h_is_not_covered"),
        "verify.raw": ("test_diary", "test_the_checker_reads_the_raw_files_not_the_diary_s_word"),
    }
    for id_, (module, test) in reg.items():
        if module in batches:
            matches = [v for identifier, v in batches[module][3].items() if identifier.endswith("." + test)]
            result = matches[0] if len(matches) == 1 else None
            if result in ("ok", "FAIL", "ERROR"):
                values[id_] = observed(int(result == "ok"), test=test, result=result)
    if "test_dispatch_states" in batches:
        rc, output, _, _ = batches["test_dispatch_states"]
        stats = output_json(output, "dispatch state space: ")
        if stats:
            coverage = set(stats["coverage"])
            for group, names in [
                ("actions", ["accepted:" + k for k in ACTIONS]),
                ("terminals", ["terminal:" + k for k in ("FAILED", "DEAD", "CANCELLED", "SUCCEEDED")]),
                (
                    "verdicts",
                    ["verdict:" + k for k in ("True:True", "True:False", "False:True", "False:False")],
                ),
                ("boundaries", EDGES),
            ]:
                counts = {k: k in coverage for k in names}
                values["correct." + group] = observed(sum(counts.values()), reached=counts)
            values["correct.depth"] = observed(
                stats["depth"], states=stats["states"], transitions=stats["transitions"]
            )
            # A crashing exploration has no stats line. A failed assertion prints shortest witnesses by invariant.
            failed = [
                k
                for k in INVARIANTS
                if re.search(r"^(?:AssertionError: )?" + re.escape(k) + r": ", output, re.M)
            ]
            if rc == 0 or failed or stats.get("missing_coverage"):
                seen = set(stats["invariants"]) & set(INVARIANTS)
                values["correct.invariants"] = observed(
                    len(seen - set(failed)), checked=len(seen), counterexamples=failed
                )
    return batches


def agreement(data, fields):
    outcomes = {}
    for name, sample in data.items():
        left, right = fields(sample)

        def count(value):
            return len(value) if isinstance(value, list) else value

        outcomes[name] = dict(
            agree=[x == right for x in left], observed=[count(x) for x in left], reference=count(right)
        )
    checks = [ok for row in outcomes.values() for ok in row["agree"]]
    return (
        observed(sum(checks) / len(checks), agreement=outcomes)
        if checks
        else missing("No comparable observations.")
    )


def measure_pages(root, values):
    harness = root / "tests/page_harness.js"
    if not harness.is_file():
        return
    # Observe the values supplied to the suite's assertions, keeping its original oracle active.
    tap = """const assert=require('node:assert/strict');
const original=assert.deepEqual;
assert.deepEqual=function(actual,expected,message){
  const counts=[73,1,2,2,2];
  const columns=Array.isArray(expected) && expected.length===counts.length && counts.every((n,i)=>n===expected[i]);
  const attention=typeof message==='string' && message.includes('chip counts as needing attention');
  if(columns || attention){
    const observed=Array.isArray(actual)?actual:[];
    const evidence=columns?{expected,actual:observed.map(Number)}:
      {expected:expected.length,actual:observed.length,matched:observed.filter(x=>expected.includes(x)).length};
    console.log('Radar assertion '+JSON.stringify({key:columns?'columns':'attention',evidence,
      passed:JSON.stringify(actual)===JSON.stringify(expected)}));
  }
  return original.apply(this,arguments);
};"""
    with tempfile.TemporaryDirectory() as temp:
        script = Path(temp) / "observe.cjs"
        script.write_text(tap)
        rc, out = invoke(["node", "--require", script, harness], root, 180)
    samples = output_json(out, "Same fact, every place: ")
    if samples and all(s in samples for s in ("whileHeld", "whileNone")):
        values["facts.holders"] = agreement(
            samples, lambda s: ([s["home"]["pairs"], s["team"]["pairs"]], s["status"]["pairs"])
        )
        values["facts.day"] = agreement(
            samples,
            lambda s: (
                [s["day"]["pairs"]],
                [p for p in s["status"]["pairs"] if p.split(">", 1)[-1] in s["day"]["words"]],
            ),
        )
        for key, metric in [("held", "held"), ("notEnded", "open")]:
            values["facts." + metric] = agreement(
                samples,
                lambda s: (
                    [s[r][key] for r in ("home", "team", "chip")],
                    len(s["status"]["pairs"]) if key == "held" else s["status"][key],
                ),
            )
        for view, name in [("day", "states"), ("calendar", "calendar")]:
            results = {}
            for state, s in samples.items():
                expected = s["status"]["words"]
                pairs = [
                    v == (expected.get(k) if view == "day" else expected.get(k, [None, None])[1])
                    for k, v in s[view]["words"].items()
                ]
                results[state] = [sum(pairs), len(pairs)]
            total = sum(n for _, n in results.values())
            if total and all(n for _, n in results.values()):
                values["facts." + name] = observed(
                    sum(y for y, _ in results.values()) / total, matched_by_scenario=results
                )
    for line in out.splitlines():
        if line.startswith("Radar assertion "):
            row = json.loads(line[len("Radar assertion ") :])
            key = row["key"]
            if key in ("columns", "attention"):
                values["facts." + key] = observed(int(row["passed"]), **row["evidence"])


def measure_newer_board(root, values):
    if not (root / "web/board.js").is_file():
        return
    probe = """const board = require('./web/board');
const task = {id:'a',state:'SUCCEEDED'};
const history={live_run:'sample', board:[{run:'sample', rows:8,tasks:[task]}]};
const snap={rows:2,state:{orders:{a:{id:'a',state:'PENDING'}}}};
console.log(JSON.stringify({state:board.map({history,snap}).tasks[0].state}));"""
    rc, out = invoke(["node", "-e", probe], root)
    if rc == 0:
        state = json.loads(out)["state"]
        values["robust.stale"] = observed(
            int(state == "SUCCEEDED"),
            current_rows=8,
            delayed_rows=2,
            retained=state if state in ("SUCCEEDED", "PENDING") else "other",
        )


def measure_diary(root, values):
    # Use the fixture builder, then call the shipped independent checker per altered input.
    test = root / "tests/test_diary.py"
    if not test.is_file():
        return
    probe = """import sys,json,copy
sys.path.insert(0,'tests')
import test_diary as t
t.Diary.setUpClass()
case=t.Diary('test_the_checker_catches_every_tampering')
try:
    case.setUp()
    rc,summary,_=case.check()
    results=[]
    for label,apply,field in t.tampers():
        bad=copy.deepcopy(case.d)
        apply(bad)
        code,details,_=case.check(bad)
        if field=='coverage': detected=details[field]<1
        elif field in ('refused','no_answer'): detected=details[field]['diary']!=details[field]['source']
        else: detected=details[field]>0
        results.append(code==1 and detected)
    print(json.dumps({'rc':rc,'total':summary['rows_total'],'cited':summary['rows_cited'],'samples':results}))
finally:
    case.doCleanups()
    t.Diary.tearDownClass()
"""
    rc, text = invoke([sys.executable, "-B", "-c", probe], root, 120)
    if rc == 0:
        output = json.loads(text.splitlines()[-1])
        if output["total"]:
            values["verify.ledger"] = observed(
                output["cited"] / output["total"], cited=output["cited"], ledger_rows=output["total"]
            )
        if output["rc"] == 0 and output["samples"]:
            results = output["samples"]
            values["verify.tamper"] = observed(
                sum(results) / len(results), killed=sum(results), applied=len(results), outcomes=results
            )


def measure_mutations(root, values, runner):
    if not runner or not (root / "tests/board_mapping.js").is_file():
        return
    if runner.is_dir():
        runner = runner / "scripts/mutate.py"
    if not runner.is_file():
        return
    # Mutations change business outcomes, leaving the test oracle untouched.
    changes = [
        ("closed-work", "'CANCELLED': 'done'", "'CANCELLED': 'failed'"),
        ("review-column", "'JUDGING': 'waiting'", "'JUDGING': 'running'"),
        ("expiry-boundary", "lease.expires > now", "lease.expires >= now"),
        ("past-run", "group.run === live", "group.run !== live"),
    ]
    with tempfile.TemporaryDirectory() as td:
        work = Path(td)
        fixture = work / "mapping"
        for path in ("tests/board_mapping.js", "web/board.js"):
            (fixture / path).parent.mkdir(parents=True)
            shutil.copyfile(root / path, fixture / path)
        spec = [dict(name=n, file="web/board.js", old=old, new=new) for n, old, new in changes]
        mutants = work / "changes.json"
        mutants.write_text(json.dumps(spec))
        rc, output = invoke(
            [
                sys.executable,
                runner,
                "--root",
                fixture,
                "--mutants",
                mutants,
                "--",
                "node",
                "tests/board_mapping.js",
            ],
            work,
        )
        outcomes = {n: status for status, n in re.findall(r"^(ALIVE|KILLED) ([a-z-]+)$", output, re.M)}
        if rc in (0, 1) and len(outcomes) == len(changes):
            values["verify.mutants"] = observed(
                sum(v == "KILLED" for v in outcomes.values()) / len(changes), mutants=outcomes
            )
        else:
            values["verify.mutants"] = missing(
                "Mutation baseline or a prescribed transformation was unavailable.",
                applied=len(outcomes),
                expected=len(changes),
            )


def checkout_matches(repo, revision, script):
    if not repo or not revision or not re.fullmatch("[0-9a-f]{40,64}", revision):
        return False
    rc, blob = invoke(["git", "rev-parse", revision + ":opencode-cockpit.sh"], repo)
    rc2, local = invoke(["git", "hash-object", script], repo)
    return rc == rc2 == 0 and blob.strip() == local.strip()


def scan_privacy(scanner, folder, history=False):
    cmd = [sys.executable, "-B", scanner] + (["--history"] if history else []) + [folder]
    rc, out = invoke(cmd, folder, 360)
    n = re.search(r"^(\d+) hit\(s\) in ", out, re.M)
    if rc in (0, 1) and n:
        return int(n[1]), sum(line.startswith("attribution ") for line in out.splitlines())


def measure_release(config, root, values):
    script = match_path(config, "installer")
    if not script or not script.is_file():
        return
    scanner = match_path(config, "privacy_scan") or Path(__file__).with_name("privacy_scan.py")
    checker = match_path(config, "copycheck")
    corpus = config.get("copy_roots") or []
    if isinstance(corpus, str):
        corpus = corpus.split(os.pathsep)
    with tempfile.TemporaryDirectory() as temp:
        work = Path(temp)
        extract = work / "release"
        rc, out = invoke(["bash", script, extract], work)
        n = re.search(r"Wrote (\d+) files into .* and checked each one\.", out)
        if rc is None:
            return
        values["public.integrity"] = observed(int(rc == 0 and bool(n)), exit=rc, checked=int(n[1]) if n else 0)
        if rc or not n:
            return
        files = [p for p in sorted(extract.rglob("*")) if p.is_file()]
        rel = [p.relative_to(extract) for p in files]
        values["public.private_files"] = observed(sum(p.parts[0] == "pro" for p in rel), examined=len(files))
        # The bytes being certified must be the inputs used to exercise this edition.
        # The runner may be newer than the target, so only require the target's payload files.
        if any(not (root / p).is_file() or (root / p).read_bytes() != (extract / p).read_bytes() for p in rel):
            for key in [k for k in values if k.startswith("public.")]:
                values[key] = missing("Installer payload differs from the edition under test.")
            return
        if scanner.is_file():
            bundle = work / "bundle"
            bundle.mkdir()
            shutil.copyfile(script, bundle / "opencode-cockpit.sh")
            for target, key in [(extract, "privacy"), (bundle, "installer_privacy")]:
                result = scan_privacy(scanner, target)
                if result:
                    values["public." + key] = observed(result[0], scope=key, scanner="privacy_scan")
                    if target == extract:
                        values["public.attribution"] = observed(
                            result[1], examined=len(files), scanner="privacy_scan"
                        )
        if checker and checker.is_file() and corpus and all(Path(p).is_dir() for p in corpus):
            text_files = []
            for f in files:
                try:
                    f.read_text(encoding="utf-8")
                    text_files.append(f)
                except UnicodeError:
                    pass
            paths = text_files + [script]
            rc, out = invoke(
                [sys.executable, "-B", checker, *paths],
                work,
                360,
                {"COPY_ROOTS": os.pathsep.join(map(str, corpus))},
            )
            reports = {
                Path(name): (int(hits), int(sources))
                for name, hits, sources in re.findall(
                    r"^(.+?): (\d+) copied runs \(.*?\), (\d+) source files$", out, re.M
                )
            }
            if rc in (0, 1) and len(reports) == len(paths) and all(p in reports for p in paths):
                for name, group in [("source_overlap", text_files), ("bundle_overlap", [script])]:
                    values["public." + name] = observed(
                        sum(reports[p][0] for p in group),
                        scanned=len(group),
                        reference_files=reports[group[0]][1],
                        scanner="copycheck",
                    )
        repo = match_path(config, "git_root")
        rev = config.get("commit", "")
        if not checkout_matches(repo, rev, script):
            return
        if scanner.is_file():
            pinned = work / "history"
            pinned.mkdir()
            commands = [
                ["git", "init", "-q"],
                ["git", "fetch", "-q", "--no-tags", repo, rev],
                ["git", "checkout", "-q", "--detach", "FETCH_HEAD"],
            ]
            if all(invoke(c, pinned, 300)[0] == 0 for c in commands):
                result = scan_privacy(scanner, pinned, history=True)
                if result:
                    values["public.history"] = observed(
                        result[0], revision=rev, scanner="privacy_scan", scope="reachable history"
                    )
        remote = config.get("ci_repo")
        if remote and re.fullmatch(r"[\w.-]+/[\w.-]+", remote):
            rc, out = invoke(
                ["gh", "api", "--paginate", "--slurp", f"repos/{remote}/commits/{rev}/check-runs?per_page=100"],
                work,
            )
            if rc == 0:
                runs = [r for page in json.loads(out) for r in page["check_runs"]]
                if not runs:
                    values["robust.ci"] = missing(
                        "No CI check runs were reported for this revision.", revision=rev
                    )
                elif not all(r["status"] == "completed" for r in runs):
                    values["robust.ci"] = missing("CI is incomplete for this revision.", revision=rev)
                else:
                    successes = sum(r["conclusion"] == "success" for r in runs)
                    values["robust.ci"] = observed(
                        successes / len(runs), revision=rev, successful=successes, checks=len(runs)
                    )


def feed(config, path):
    parts = urlsplit(config.get("url", ""))
    if parts.hostname not in ("localhost", "127.0.0.1", "::1") or parts.scheme not in ("http", "https"):
        return None
    url = urlunsplit((parts.scheme, parts.netloc, path, "", ""))
    try:
        with urlopen(url, timeout=15) as r:
            return r.read(16 * 1024 * 1024).decode()
    except (OSError, ValueError):
        return None


def load_feed(config, path):
    text = feed(config, path)
    try:
        return json.loads(text) if text else None
    except ValueError:
        return None


def js_event_list(text):
    for match in re.finditer(r"\[\s*\{", text or ""):
        try:
            rows = json.JSONDecoder().raw_decode(text[match.start() :])[0]
            if isinstance(rows, list) and rows and all(isinstance(r, dict) and "type" in r for r in rows):
                return rows
        except ValueError:
            continue
    return None


def original_source_items(grader, root):
    # Only these item functions depend exclusively on the view sources, or those sources plus
    # the actual dispatcher. The full historical context would otherwise silently read unrelated runs.
    if (
        not grader
        or not grader.is_file()
        or not all((root / "src" / n).is_file() for n in ("main.tsx", "model.ts", "outbox.tsx"))
    ):
        return {}
    probe = """import json,runpy,sys
from pathlib import Path
module=runpy.run_path(sys.argv[1])
root=Path(sys.argv[2]); src=root/'src'
files=[src/name for name in ('main.tsx','outbox.tsx','model.ts')]+list((src/'views').glob('*'))
inputs={'src':{str(f.relative_to(src)):f.read_text() for f in files if f.is_file()}}
subset={'true':set(range(1,11)),'live':{2,5},'ctl':{1,3,4,6,7},'know':{1,2,4,5},'tree':{1,3,4},'audit':{5,6,7,8}}
results={}; counters={}
for item in module['ITEMS']:
    key=item['axis']; counters[key]=counters.get(key,0)+1; n=counters[key]
    if n in subset.get(key,set()):
        try:
            answer=item['test'](inputs)
        except (KeyError,TypeError,IndexError):
            continue
        if answer is not None: results[key+'.'+str(n)]=bool(answer)
print(json.dumps(results))"""
    rc, text = invoke([sys.executable, "-B", "-c", probe, grader, root], root)
    return json.loads(text) if rc == 0 else {}


def record_items(config, root):
    inventory = {
        key: [
            {"id": f"{key}.{n + 1:02d}", "name": name, "got": None, "source": "No comparable probe"}
            for n, name in enumerate(group.split("|"))
        ]
        for key, group in ITEMS.items()
    }
    # Native mode only accepts the actual frontend tree under test. An archived score JSON is never
    # assigned to another build, even when the release name is the same.
    legacy = match_path(config, "legacy_radar")
    live = match_path(config, "legacy_live")
    run = match_path(config, "legacy_run")
    dispatch = match_path(config, "legacy_dispatch")
    if all([legacy, live, run, dispatch]) and legacy.is_file() and root in (live, live / "pro"):
        with tempfile.TemporaryDirectory() as temp:
            rc, _ = invoke([sys.executable, "-I", legacy, live, run, dispatch, temp], live)
            path = Path(temp) / "radar.json"
            if rc == 0 and path.is_file():
                doc = json.loads(path.read_text())
                if doc["facts"]["items"] == 72 and all(
                    sum(i["axis"] == key for i in doc["items"]) == len(group)
                    for key, group in inventory.items()
                ):
                    for key, group in inventory.items():
                        for row, item in zip(group, [i for i in doc["items"] if i["axis"] == key]):
                            row.update(got=item["got"], source="Original recording grader")
                    return inventory

    def record(group, n, result, source):
        inventory[group][n - 1].update(got=bool(result) if result is not None else None, source=source)

    paid = config.get("id") == "paid"
    team = load_feed(config, "/team")
    data = load_feed(config, "/poll?since=0")
    if not isinstance(team, dict) or not team.get("run") or not isinstance(data, dict):
        return inventory
    fixture = match_path(config, "run_dir")
    if fixture and (not fixture.is_dir() or fixture.name != team["run"]):
        return inventory
    if data.get("team", {}).get("run") != team["run"]:
        return inventory
    if paid:
        for item_id, answer in original_source_items(legacy, root).items():
            group, index = item_id.split(".")
            record(group, int(index), answer, "Original grader on the matched private view source")
        live_feed = load_feed(config, "/pro/live.json")
        if not live_feed or live_feed.get("run") != team["run"]:
            return inventory
    snapshot = data.get("state", {})
    log = snapshot.get("log") or []
    state = snapshot.get("state") or {}
    launches = team.get("launches") or []
    if paid:
        events = js_event_list(feed(config, "/pro/events.js"))
        if events:
            starts = [e for e in events if e["type"].startswith("run.start")]
            stops = [e for e in events if e["type"].startswith("run.done")]
            run_rows = [e for e in events if e["type"].startswith("run.")]

            def has(rows, *keys):
                return any(all(k in row for k in keys) for row in rows)

            if run_rows:
                for n, answer in [
                    (1, has(starts, "agent", "task")),
                    (2, has(starts, "t") and has(stops, "t")),
                    (3, has(stops, "cost", "cost_known")),
                    (5, has(run_rows, "model")),
                    (6, has(run_rows, "tokens") or has(run_rows, "usage")),
                    (7, has(run_rows, "prompt")),
                    (8, has(run_rows, "log") or has(run_rows, "transcript")),
                    (9, has(run_rows, "selfcheck") or has(run_rows, "refused")),
                    (10, has(run_rows, "attempt")),
                    (11, has(run_rows, "outside") or has(run_rows, "denials")),
                ]:
                    record("rec", n, answer, "Pro event feed")
                record("know", 3, has(run_rows, "skills") or has(run_rows, "tools"), "Pro event feed")
            verdicts = [e for e in events if e["type"].startswith("result.")]
            if verdicts:
                record("rec", 4, has(verdicts, "verified_by"), "Pro result events")
            files = [e for e in events if e["type"].startswith("file")]
            if files:
                record(
                    "rec", 12, any(has(files, k) for k in ("rev", "sha", "commit", "h")), "Pro artifact events"
                )
            record(
                "live",
                4,
                any(e["type"].startswith("lease.") or "expires" in e for e in events),
                "Pro event feed",
            )
            record("audit", 3, all("seq" in e or "launch" in e for e in events), "Pro event feed")
    else:
        if launches:

            def present(*keys):
                return any(all(k in row and row[k] is not None for k in keys) for row in launches)

            for n, valid in [
                (1, present("agent", "order")),
                (2, present("started", "ended")),
                (3, present("cost", "cost_known")),
                (5, present("model")),
                (6, present("usage") or present("tokens")),
                (7, present("prompt")),
                (8, present("transcript") or present("log")),
                (9, present("selfcheck") or present("refused")),
                (10, present("attempt")),
                (11, present("denials") or present("outside")),
            ]:
                record("rec", n, valid, "Team launch projection")
            record(
                "know",
                3,
                present("skills") or present("tools") or present("used_skills"),
                "Team launch projection",
            )
        judged = {"order.succeeded", "order.failed", "order.returned"}
        verdicts = [r for r in log if r.get("kind") in judged or r.get("kind", "").startswith("verdict.")]
        if verdicts:
            record(
                "rec",
                4,
                any(r.get("by") == team.get("judge") for r in verdicts),
                "Ledger verdict and judge identity",
            )
        artifacts = [r for r in log if r.get("kind") == "artifact.rev"]
        if artifacts:
            record("rec", 12, any("rev" in r or "sha" in r for r in artifacts), "Ledger artifact feed")
        if log:
            record(
                "live",
                4,
                any(r.get("kind") == "lease.granted" and "expires" in r for r in log),
                "Ledger lease feed",
            )
            record("audit", 3, all("seq" in r or "launch" in r for r in log), "Ledger event feed")
    if log:
        last = max(r.get("seq", 0) for r in log)
        tail = load_feed(config, "/poll?since=" + str(last))
        if tail and isinstance(tail.get("state", {}).get("log"), list):
            record(
                "live",
                1,
                all(r.get("seq", 0) > last for r in tail["state"]["log"]),
                "Incremental ledger request",
            )
        record("audit", 2, all("seq" in r and "h" in r for r in log), "Ledger feed")
        record("ctl", 5, True, "Dispatcher HTTP response")
        org = state.get("org", {})

        def depth(person):
            seen = set()
            while person and isinstance(person, str) and person not in seen:
                seen.add(person)
                person = org.get(person)
            return len(seen)

        if org:
            record("tree", 2, max(depth(actor) for actor in org) >= 3, "Organization state")
    if not paid and (root / "README.md").is_file():
        doc = (root / "README.md").read_text()
        record("onb", 6, bool(doc.strip()), "Edition quick-start document")
    return inventory


def attach_browser_records(checks, browser):
    """Fill four original phone questions using the same edition's browser run at 390px."""
    metric = checks.get("records.phone")
    if not metric:
        return checks
    details = metric["evidence"]
    items = details.get("items", [])
    routes = {"phone.01": "home", "phone.02": "team", "phone.04": "board", "phone.07": "files"}
    for item in items:
        route = routes.get(item["id"])
        if not route or item["got"] is not None:
            continue
        key = "mobile." + route
        probe = browser.get(key, {})
        evidence = probe.get("evidence", {})
        if probe.get("value") is None or not all(
            isinstance(evidence.get(k), (int, float)) for k in ("width", "viewport", "scale")
        ):
            continue
        width, viewport, scale = (evidence[k] for k in ("width", "viewport", "scale"))
        item.update(
            got=width <= viewport and viewport <= 390 and scale >= 0.99,
            source=key,
            phone={"deviceWidth": 390, "pageWidth": width, "viewport": viewport, "scale": scale},
        )
    measured = [row["got"] for row in items if row["got"] is not None]
    if measured:
        checks["records.phone"] = observed(
            sum(measured) / len(measured),
            items=items,
            yes=sum(measured),
            total=len(items),
            measured=len(measured),
        )
    return checks


def collect(config):
    """Return measurements for a pinned edition; settings may point to local optional graders."""
    root = Path(config["root"]).resolve()
    gaps = {
        1: "The bounded dispatcher test or runnable suite is unavailable.",
        2: "The paired view readings for the two required data states are unavailable.",
        3: "A matching release installer, reference corpus or publication history is unavailable.",
        10: "This release has no corresponding executed regression or revision-bound CI result.",
        11: "No equivalent input for the historical checklist was recorded.",
        12: "The required independent checker, fixture or mutation runner is unavailable.",
    }
    values = {d["id"]: missing(gaps[d["axis"]]) for d in json.loads(SPEC.read_text())}
    if not root.is_dir():
        return values
    workers = max(1, min(8, int(config.get("test_workers", 3))))
    if config["id"] != "paid":
        measure_tests(root, values, workers)
        measure_pages(root, values)
        measure_newer_board(root, values)
        measure_diary(root, values)
        measure_mutations(root, values, match_path(config, "mutation_root"))
        measure_release(config, root, values)
    else:
        backend = match_path(config, "app_root")
        if backend and (backend / "cockpit/serve.py").is_file():
            measure_tests(backend, values, workers, backend_only=True)
            measure_diary(backend, values)
            for row in values.values():
                if row["value"] is not None:
                    row["evidence"]["scope"] = "Serving backend"
    for key, rows in record_items(config, root).items():
        measured = [r["got"] for r in rows if r["got"] is not None]
        evidence = dict(items=rows, yes=sum(measured), measured=len(measured), total=len(rows))
        values["records." + key] = (
            observed(sum(measured) / len(measured), **evidence)
            if measured
            else missing("No matched observation for this checklist group.", **evidence)
        )
    return values


if __name__ == "__main__":
    import argparse

    cli = argparse.ArgumentParser(description=__doc__)
    cli.add_argument("config", type=Path)
    cli.add_argument("output", type=Path)
    options = cli.parse_args()
    options.output.write_text(json.dumps(collect(json.loads(options.config.read_text())), indent=2) + "\n")
