*{box-sizing:border-box;}
html{background:var(--canvas);}
body{background:var(--canvas); color:var(--ink); display:grid; font:var(--text-md)/var(--leading-sm) var(--font); font-variant-numeric:var(--number-style); grid-template-columns:184px var(--track); margin:0;}
[hidden]{display:none !important;}
a{color:var(--accent); text-decoration-line:none;}
a, button, input, select, textarea, summary{transition:color var(--motion) var(--ease), background-color var(--motion) var(--ease), border-color var(--motion) var(--ease), box-shadow var(--motion) var(--ease), transform var(--motion) var(--ease);}
a:hover{color:var(--accent); text-decoration-line:underline;}
button:hover, .button:hover{box-shadow:var(--shadow); transform:translateY(-1px);}
input:hover, select:hover, textarea:hover{background:var(--hero-end); border-color:var(--accent);}
summary:hover{background:var(--accent-wash); color:var(--accent);}
a:focus-visible, button:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible, summary:focus-visible{outline:solid 2px var(--accent); outline-offset:var(--space-1);}
h1{font-size:var(--text-xl); letter-spacing:-0.02em; line-height:var(--leading-lg); margin:0;}
h2{font-size:var(--text-display); font-weight:var(--weight-heading); letter-spacing:-0.025em; line-height:var(--leading-display); margin:0; word-wrap:anywhere;}
h3{font-size:var(--text-lg); font-weight:var(--weight-heading); line-height:var(--leading-md); margin:0 0 var(--space-4);}
.section-heading{font-size:var(--text-xl); font-weight:var(--weight-heading); letter-spacing:-0.015em; line-height:var(--leading-lg); margin:var(--space-section) 0 var(--space-4);}
p{margin:var(--space-2) 0;}
code, pre, .mono{font-family:var(--code-font); font-size:var(--text-xs); line-height:var(--leading-sm); word-wrap:anywhere;}
small, .sub, .hint{color:var(--ink-3); font-size:var(--text-xs); line-height:var(--leading-sm);}
.sub{margin:var(--space-1) 0 0;}
.eyebrow{color:var(--ink-3); font-size:var(--text-xs); font-weight:var(--weight-heading); line-height:var(--leading-xs); margin:0 0 var(--space-2);}
.rail{background:var(--canvas); min-height:100vh; min-width:0;}
nav[data-nav]{background:#0000; display:flex; flex-direction:column; height:100vh; top:0; overflow-y:auto; padding:var(--space-8) var(--space-4); position:sticky;}
.rail-brand{color:var(--accent); font-size:var(--text-display); font-weight:var(--weight-heading); line-height:var(--leading-display); padding:0 var(--space-4) var(--space-8);}
.rail-brand span{color:var(--ink-2); display:block; font-size:var(--text-sm); font-weight:var(--weight-heading); line-height:var(--leading-sm);}
.rail-note{color:var(--ink-3); font-size:var(--text-xs); line-height:var(--leading-sm); margin:auto var(--space-4) 0; padding-top:var(--space-6);}
#nav-links{display:grid; gap:var(--space-2);}
nav a{align-items:center; background:#0000; border-radius:var(--round-pill); box-shadow:none; color:var(--ink-2); display:flex; gap:var(--space-3); padding:var(--space-3) var(--space-4);}
nav a[aria-current=page]{background:var(--accent-wash); color:var(--accent); font-weight:var(--weight-heading);}
nav a:hover{background:var(--paper); text-decoration-line:none;}
nav a[aria-current=page]:hover{background:var(--accent-wash);}
.glyph, .logo{flex:0 0 auto; vertical-align:middle;}
.workspace{max-width:1800px; min-width:0; padding:var(--space-6) var(--space-8) var(--space-8);}
.top{align-items:center; border-bottom:solid 1px var(--line); display:flex; gap:var(--space-6); justify-content:space-between; margin-bottom:var(--space-8); padding-bottom:var(--space-6);}
.meters, .actions{align-items:center; display:flex; flex-wrap:wrap; gap:var(--space-3);}
.meter, .num, [data-metric], [data-stat-value], .stat strong{font-variant-numeric:var(--number-style);}
.meter{color:var(--ink-3); font-size:var(--text-xs);}
.icon-link{border-radius:var(--round-control); box-shadow:var(--shadow-small); color:var(--ink-2); display:inline-flex; padding:var(--space-2);}
.pill, .badge{align-items:center; background:var(--wash); border-radius:var(--round-pill); box-shadow:var(--shadow-small); color:var(--wait); display:inline-flex; font-size:var(--text-xs); font-weight:var(--weight-heading); gap:var(--space-2); line-height:var(--leading-xs); padding:var(--space-1) var(--space-2); white-space:nowrap;}
.pill::before, .badge::before{background:currentColor; border-radius:var(--round-pill); content:""; flex:0 0 auto; height:var(--space-1); width:var(--space-1);}
:is(.pill, .badge):is([data-state=running], [data-state=LEASED], [data-state=JUDGING]){background:var(--run-wash); color:var(--run);}
:is(.pill, .badge):is([data-state=SUCCEEDED], [data-state=ok], [data-state=accepted], [data-state=recorded]){background:var(--ok-wash); color:var(--ok);}
:is(.pill, .badge):is([data-state=due], [data-state=proposed], [data-state=attention]){background:var(--attention-wash); color:var(--attention);}
:is(.pill, .badge):is([data-state=halted], [data-state=fatal], [data-state=offline], [data-state=FAILED], [data-state=DEAD], [data-state=bad], [data-state=rejected]){background:var(--bad-wash); color:var(--bad);}
.notice, .readonly{background:var(--wash); border-radius:var(--round-control); color:var(--ink-2); margin:var(--space-3) 0; padding:var(--space-3) var(--space-4);}
.page-head{align-items:center; display:flex; gap:var(--space-6); justify-content:space-between; margin-bottom:var(--space-6);}
.page-head > div{min-width:0;}
.card{background:var(--paper); border:0; border-radius:var(--round-card); box-shadow:var(--lift-2); margin-bottom:var(--space-4); min-width:0; padding:var(--space-6);}
.two-col{align-items:start; display:grid; gap:var(--space-4); grid-template-columns:minmax(0, 1.2fr) var(--track);}
.stack{min-width:0;}
.team{display:grid; gap:var(--space-4); grid-template-columns:repeat(3, var(--track));}
.block-head{align-items:baseline; display:flex; gap:var(--space-4); justify-content:space-between; margin-bottom:var(--space-4);}
.block-head h3{margin:0;}
.block-head > a{font-size:var(--text-sm);}
.home-seat{align-content:start; background:var(--paper); border-radius:var(--round-control); border:solid 1px var(--line); box-shadow:var(--shadow-small); display:grid; gap:var(--space-2); grid-template-rows:auto 1fr auto auto; min-width:0; padding:var(--space-4); position:relative; transition:box-shadow var(--motion) var(--ease), transform var(--motion) var(--ease);}
.home-seat-status{align-items:center; color:var(--ink-3); display:flex; font-size:var(--text-xs); gap:var(--space-2); justify-content:space-between;}
.seat-status{align-items:center; color:var(--ink-2); display:inline-flex; gap:var(--space-2);}
.activity{list-style:none; margin:0; padding:0;}
.activity li{border-bottom:solid 1px var(--line); color:var(--ink-2); font-size:var(--text-sm); word-wrap:anywhere; padding:var(--space-3) 0;}
.activity li:last-child{border-bottom:0; padding-bottom:0;}
.activity li:first-child{padding-top:0;}
.activity-who{align-items:center; color:var(--ink); display:inline-flex; font-weight:var(--weight-heading); gap:var(--space-2); vertical-align:middle;}
.activity-icon{color:var(--ink-2); flex:0 0 auto;}
.activity time{color:var(--ink-3); font-size:var(--text-xs); font-variant-numeric:var(--number-style); white-space:nowrap;}
.seat{background:var(--paper); border:solid 1px var(--line); border-radius:var(--round-control); box-shadow:var(--shadow-small); display:flex; flex-direction:column; gap:var(--space-3); min-width:0; padding:var(--space-4); position:relative; transition:box-shadow var(--motion) var(--ease), transform var(--motion) var(--ease);}
.seat[data-busy=true]{box-shadow:var(--shadow-small);}
.seat-head, .who{align-items:center; display:flex; gap:var(--space-3);}
.seat-name{font-weight:var(--weight-heading);}
.seat-model, .seat-now{color:var(--ink-2); font-size:var(--text-xs); line-height:var(--leading-sm); word-wrap:anywhere;}
.seat-now [data-order-link]{display:inline-block; max-width:100%; overflow:hidden; text-overflow:ellipsis; vertical-align:bottom; white-space:nowrap;}
.lead-seat{align-items:center; color:var(--ink-2); display:flex; font-size:var(--text-xs); gap:var(--space-3); line-height:var(--leading-sm); min-width:0;}
.lead-details{min-width:0; word-wrap:anywhere;}
.lead-details strong, .lead-details .model{display:block;}
.lead-details .model{color:var(--ink-3); font-size:var(--text-xs);}
.orders, .files{display:grid; gap:var(--space-3);}
.order{background:var(--paper); border:0; border-radius:var(--round-card); box-shadow:var(--shadow); min-width:0; padding:var(--space-4);}
a.order{color:var(--ink); display:grid; gap:var(--space-2);}
a.order:hover, a[data-lib-entry]:hover{box-shadow:var(--lift-3); text-decoration-line:none; transform:translateY(-1px);}
.order-title{font-weight:var(--weight-heading); word-wrap:anywhere;}
.order small{word-wrap:anywhere;}
.order .badge{justify-self:start;}
.suborders{align-items:stretch; grid-template-columns:repeat(2, var(--track)); grid-auto-rows:1fr;}
.suborders a.order{align-content:start; grid-template-rows:auto auto 1fr;}
.suborders .order-title{overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}
.suborders .who{color:var(--ink-2); flex-wrap:wrap; font-size:var(--text-xs); gap:var(--space-2); min-width:0;}
.suborder-model{color:var(--ink-3); flex:1 1 0%; min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}
.suborder-origin{align-items:center; align-content:start; display:flex; flex-wrap:wrap; gap:var(--space-2);}
.suborder-origin > div{min-width:0;}
.suborder-origin .lead-seat{color:var(--ink-3); gap:var(--space-2);}
.suborder-origin .lead-details strong, .suborder-origin .lead-details .model{display:inline;}
.suborder-origin .lead-details strong{font-weight:normal; margin-right:var(--space-2);}
#attention{list-style:none; margin:0; padding:0;}
#attention li{border-top:solid 1px var(--line); padding:var(--space-3) 0;}
#attention li:first-child{border:0;}
#attention .empty{flex-direction:row; gap:var(--space-4); padding:0;}
form{display:grid; gap:var(--space-4);}
label{color:var(--ink-2); display:grid; font-size:var(--text-sm); font-weight:var(--weight-heading); gap:var(--space-2); line-height:var(--leading-sm);}
input, select, textarea{background:var(--paper); border:solid 1px var(--line-2); border-radius:var(--round-chip); color:var(--ink); font:var(--text-md)/var(--leading-md) var(--font); font-weight:normal; padding:var(--space-2) var(--space-4); width:100%;}
input::placeholder, textarea::placeholder{color:var(--ink-3); opacity:1;}
textarea{min-height:104px; resize:vertical;}
input:disabled, textarea:disabled{background:var(--wash); color:var(--ink-3);}
.pair{display:grid; gap:var(--space-3); grid-template-columns:var(--track) 100px;}
button, .button{align-items:center; background:var(--accent); border:0; border-radius:var(--round-button); box-shadow:var(--shadow-small); color:var(--accent-ink); cursor:pointer; display:inline-flex; font:600 var(--text-sm)/var(--leading-md) var(--font); gap:var(--space-2); justify-content:center; padding:var(--space-2) var(--space-4);}
.button:hover{color:var(--accent-ink); text-decoration-line:none;}
button:disabled{background:var(--wash); color:var(--ink-3); cursor:default; transform:none;}
button.quiet, .button.quiet{background:var(--wash); box-shadow:none; color:var(--ink-2);}
button.quiet:hover, .button.quiet:hover{background:var(--accent-wash); box-shadow:none; color:var(--accent); transform:none;}
button.link{background:var(--paper); border:0; box-shadow:none; color:var(--accent); display:inline; font-family:var(--code-font); word-wrap:anywhere; padding:var(--space-1) 0; text-align:left;}
button.link:hover{text-decoration-line:underline;}
.result{font-size:var(--text-xs); word-wrap:anywhere;}
.result[data-state=bad], .form-error{color:var(--ink-2);}
.result[data-state=ok]{color:var(--ok);}
.calendar-card{overflow:hidden; padding:0;}
.calendar-grid{display:grid; grid-template-columns:repeat(7, var(--track));}
[data-weekday]{border-bottom:solid 1px var(--line); color:var(--ink-3); font-size:var(--text-xs); padding:var(--space-4);}
.day-cell{border-right:solid 1px var(--line); border-bottom:solid 1px var(--line); color:var(--ink); display:flex; flex-direction:column; gap:var(--space-3); min-height:116px; padding:var(--space-4);}
.day-cell:nth-child(7n){border-right:0;}
.day-cell:hover{background:var(--accent-wash); text-decoration-line:none;}
.day-cell[data-outside]{background:var(--wash); color:var(--ink-3);}
.day-cell[data-today]{box-shadow:0 0 0 2px var(--accent) inset;}
.day-number{font-size:var(--text-md); font-weight:var(--weight-heading);}
.day-cell[data-today] .day-number{color:var(--accent);}
.day-count{color:var(--ink-3); font-size:var(--text-xs);}
.dots, .legend{align-items:center; display:flex; flex-wrap:wrap; gap:var(--space-2);}
.dot{background:var(--wait); border-radius:var(--round-pill); display:inline-block; height:var(--space-2); width:var(--space-2);}
.dot[data-status=running]{background:var(--run);}
.dot[data-status=done]{background:var(--ok);}
.dot[data-status=failed]{background:var(--bad);}
.legend{color:var(--ink-3); font-size:var(--text-xs); gap:var(--space-6);}
.legend span{align-items:center; display:inline-flex; gap:var(--space-2);}
.stats{display:grid; gap:var(--space-4); grid-template-columns:repeat(4, var(--track)); margin-bottom:var(--space-6);}
.stat{background:var(--paper); border-radius:var(--round-control); box-shadow:var(--lift-1); color:var(--ink-3); font-size:var(--text-sm); padding:var(--space-4);}
.stat strong{color:var(--ink); display:block; font-size:var(--text-stat); font-weight:var(--weight-heading); line-height:var(--leading-display); margin-top:var(--space-2);}
.hero{border-radius:var(--round-hero); isolation:isolate; margin-bottom:var(--space-4); padding:var(--space-8) var(--space-6) 0; position:relative;}
.hero::before{background:radial-gradient(ellipse at 0% 20%, var(--mesh-blue), #0000 75%), radial-gradient(ellipse at 50% 75%, var(--mesh-lilac), #0000 75%), radial-gradient(ellipse at 100% 10%, var(--mesh-mint), #0000 75%), var(--mesh-base); border-radius:inherit; content:""; inset:0 0 56px; position:absolute; z-index:-1;}
.hero .stats{margin:var(--space-8) 0 0;}
.hero [data-stat=today] [data-stat-value]{font-size:var(--text-headline); line-height:30pt;}
.hero .page-head{margin:0;}
.hero p:not(.eyebrow){color:var(--ink);}
.hero .eyebrow{color:var(--ink);}
[data-stat-note]{color:var(--ink-3); display:block; font-size:var(--text-xs); margin-top:var(--space-1); word-wrap:anywhere;}
.compose-card{padding:var(--space-6);}
.board{align-items:stretch; display:grid; gap:var(--space-4); grid-template-columns:repeat(4, var(--track));}
.board-column{background:var(--wash); border-radius:var(--round-card); box-shadow:var(--shadow-small); min-height:360px; padding:var(--space-4);}
.board-column h3{color:var(--ink-2); display:flex; justify-content:space-between;}
dl.facts{display:grid; font-size:var(--text-sm); gap:var(--space-3) var(--space-4); grid-template-columns:100px var(--track);}
dl.facts dt{color:var(--ink-3);}
dl.facts dd{margin:0; word-wrap:anywhere; white-space:pre-wrap;}
.scroll{min-width:0;}
[data-flow]{display:block; height:auto; margin:0 auto; max-width:100%;}
.flow-box{fill:var(--well); rx:var(--round-control); stroke:none;}
.flow-title{fill:var(--ink); font-size:var(--text-md); font-weight:var(--weight-heading);}
.flow-state{fill:var(--ink-2); font-size:var(--text-xs);}
[data-flow-edge]{fill:none; stroke:var(--edge); stroke-width:2; stroke-linecap:round; stroke-linejoin:round; vector-effect:non-scaling-stroke;}
[data-flow-edge][data-kind=waits-for]{stroke-dasharray:4 4;}
.flow-arrow{fill:var(--edge);}
.flow-box{transition:fill var(--motion) var(--ease), stroke var(--motion) var(--ease);}
.file{align-items:center; border-bottom:solid 1px var(--line); display:flex; flex-wrap:wrap; gap:var(--space-3); min-width:0; padding:var(--space-4) 0;}
.file > .link{max-width:100%;}
.file-actions{align-items:center; display:flex; flex-wrap:wrap; gap:var(--space-2); width:100%;}
.grow{flex:1 1 0%;}
.preview{background:var(--paper); border-radius:var(--round-card); box-shadow:var(--lift-3); inset:16% 8% auto 22%; max-height:68vh; overflow:auto; position:fixed; z-index:10;}
.preview-head{align-items:center; background:var(--canvas); border-bottom:solid 1px var(--line); display:flex; gap:var(--space-4); justify-content:space-between; padding:var(--space-4);}
.preview pre{margin:0; word-wrap:anywhere; padding:var(--space-6); white-space:pre-wrap;}
table{border-collapse:collapse; font-size:var(--text-xs); line-height:var(--leading-sm); table-layout:fixed; width:100%;}
th, td{border-bottom:solid 1px var(--line); word-wrap:anywhere; padding:var(--space-2) var(--space-2) var(--space-2) 0; text-align:left; vertical-align:middle;}
th{color:var(--ink-3); font-weight:var(--weight-heading);}
.num{text-align:right;}
.cell-text{display:block; line-height:var(--leading-sm); min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}
td .badge{line-height:var(--leading-sm); max-width:100%; padding:0 var(--space-1);}
.launch-table th:nth-child(1){width:4%;}
.launch-table th:nth-child(2){width:16%;}
.launch-table th:nth-child(3){width:18%;}
.launch-table th:nth-child(4){width:10%;}
.launch-table th:nth-child(5){width:18%;}
.launch-table th:nth-child(6){width:8%;}
.launch-table th:nth-child(7){width:6%;}
.launch-table th:nth-child(8){width:12%;}
.launch-table th:nth-child(9){width:8%;}
.launch-order{display:block; font-family:var(--code-font); line-height:var(--leading-sm); word-wrap:anywhere;}
.ledger{list-style:none; margin:var(--space-2) 0 0; padding:0;}
.ledger li{border-bottom:solid 1px var(--line); display:grid; font-size:var(--text-xs); gap:var(--space-3); grid-template-columns:40px 72px 144px var(--track); padding:var(--space-3) 0;}
.ledger .seq, .ledger time{color:var(--ink-3); font-variant-numeric:var(--number-style);}
.ledger .kind{font-size:var(--text-xs);}
.ledger .what{color:var(--ink-2); word-wrap:anywhere;}
.help-steps{margin:0; max-width:880px; padding-left:var(--space-6);}
.help-steps li{color:var(--ink-2); padding:var(--space-3) 0 var(--space-3) var(--space-2);}
.help-steps strong{color:var(--ink);}
.examples-heading{margin:var(--space-6) 0 var(--space-4);}
.foot{color:var(--ink-3); font-size:var(--text-xs); padding-top:var(--space-6);}
.empty{align-items:center; color:var(--ink-3); display:flex; gap:var(--space-4); padding:var(--space-6) 0;}
.empty svg{color:var(--ink-3); flex:0 0 96px; height:96px; width:96px;}
.empty svg.empty-art{color:var(--accent);}
.empty-tone{fill:var(--accent-wash);}
.empty strong{color:var(--ink); display:block; font-size:var(--text-lg); font-weight:var(--weight-heading);}
.empty-action{display:inline-flex; font-size:var(--text-sm); margin-top:var(--space-2);}
.empty p{font-size:var(--text-sm); margin:var(--space-1) 0 0;}
.board .empty{align-items:start; flex-direction:column; gap:var(--space-2); padding:var(--space-2) 0;}
.order-metrics{color:var(--ink-2); display:flex; font-size:var(--text-xs); gap:var(--space-6); margin-top:var(--space-4);}
.order-metrics strong{color:var(--ink); font-size:var(--text-xl); line-height:var(--leading-lg); margin-right:var(--space-1);}
.library-filters{display:flex; flex-wrap:wrap; gap:var(--space-3); margin-bottom:var(--space-6);}
[data-keep-form]{word-wrap:anywhere;}
[data-keep-form] .keep-kinds{border:0; margin:0; min-width:0; padding:0;}
[data-keep-form] .keep-kinds label{align-items:center; display:flex; margin:var(--space-2) 0;}
[data-keep-form] input[type=radio]{accent-color:var(--accent); height:var(--space-4); padding:0; width:var(--space-4);}
.library-filters [aria-pressed=true]{background:var(--accent-wash); color:var(--accent);}
.library-grid{display:grid; gap:var(--space-4); grid-template-columns:repeat(2, var(--track)); margin-bottom:var(--space-6);}
.library-entry{color:var(--ink); display:grid; gap:var(--space-3); margin:0;}
.library-entry h3{margin:0; word-wrap:anywhere;}
.library-meta{align-items:center; color:var(--ink-3); display:flex; flex-wrap:wrap; font-size:var(--text-xs); gap:var(--space-3);}
.kind-chip{align-items:center; color:var(--ink-2); display:inline-flex; font-size:var(--text-xs); gap:var(--space-2);}
.group-heading{color:var(--ink-2); font-size:var(--text-sm); font-weight:var(--weight-heading); line-height:var(--leading-sm); margin:0 0 var(--space-2);}
[data-order-proposed]{margin-top:var(--space-4);}
.library-use{align-items:center; background:var(--accent-wash); border-radius:var(--round-pill); color:var(--accent); display:inline-flex; font-size:var(--text-xs); gap:var(--space-2); max-width:100%; word-wrap:anywhere; padding:var(--space-1) var(--space-3);}
.library-use .glyph{height:var(--space-4); width:var(--space-4);}
.library-use:hover{background:var(--wash);}
.library-entry[data-lib-status=superseded], .library-entry[data-lib-status=rejected]{box-shadow:var(--shadow-small);}
.library-entry[data-lib-status=superseded] h3, .library-entry[data-lib-status=rejected] h3{color:var(--ink-3); font-weight:var(--weight-medium);}
.review-bar{background:var(--attention-wash); border-radius:var(--round-hero); box-shadow:var(--shadow); margin:var(--space-6) 0; padding:var(--space-6);}
.review-bar label{flex:1 1 0%; min-width:240px;}
[data-lib-text]{background:var(--wash); border-radius:var(--round-card); margin:var(--space-6) 0 0; word-wrap:anywhere; padding:var(--space-6); white-space:pre-wrap;}
[data-eff-chart]{display:block; height:auto; margin:var(--space-6) 0; width:100%;}
.chart-grid{stroke:var(--line); stroke-width:1;}
.chart-bar{fill:var(--accent);}
.chart-label{fill:var(--ink-2); font-size:var(--text-xs);}
.chart-value{fill:var(--ink); font-size:var(--text-md); font-variant-numeric:var(--number-style);}
.eff-table th:first-child{width:26%;}
.eff-table th:last-child{width:32%;}
.workflow-steps{padding-left:var(--space-6);}
.workflow-steps li{padding:var(--space-3) 0;}
.toast{background:var(--paper); border-radius:var(--round-card); box-shadow:var(--lift-3); color:var(--ink); right:var(--space-8); bottom:var(--space-8); max-width:400px; padding:var(--space-4) var(--space-6); position:fixed; z-index:20;}
.toast .badge{margin-right:var(--space-3);}
.skeleton{align-content:start; display:grid; gap:var(--space-4); min-height:240px; padding:var(--space-6);}
.skeleton span{background:var(--skeleton); border-radius:var(--round-control); display:block; height:var(--space-6);}
.skeleton span:first-child{height:36px; width:48%;}
.skeleton span:last-child{height:80px; width:72%;}
.flow-dot{fill:var(--wait);}
.flow-dot[data-state=LEASED], .flow-dot[data-state=JUDGING]{fill:var(--run);}
.flow-dot[data-state=SUCCEEDED]{fill:var(--ok);}
.flow-dot[data-state=FAILED], .flow-dot[data-state=DEAD]{fill:var(--bad);}
[data-flow] a:hover .flow-box{fill:var(--accent-wash); stroke:var(--accent);}
[data-flow] a:focus-visible .flow-box{stroke:var(--accent); stroke-width:3;}
body{font-variant-numeric:var(--number-style);}
.day-status{align-items:center; color:var(--ink-2); display:inline-flex; font-size:var(--text-xs); gap:var(--space-1); line-height:var(--leading-xs);}
.day-status .dot{box-shadow:var(--shadow-small); flex:0 0 auto;}

/* Run drawings use the same surfaces, type scale and state colours as the page. */
.drawing-card{position:relative;}
.drawing-card > h3{margin-bottom:var(--space-1);}
.drawing-caption{color:var(--ink-3); font-size:var(--text-sm); line-height:var(--leading-sm); margin:var(--space-2) 0 var(--space-4);}
.run-chart, .org-tree, .launch-timeline{display:block; height:auto; width:100%;}
.axis-label{fill:var(--ink-3); font-size:var(--text-xs);}
.diagram-name{fill:var(--ink); font-size:var(--text-md); font-weight:var(--weight-heading);}
.chart-counts{display:flex; gap:var(--space-4); top:var(--space-6); right:var(--space-6); justify-content:flex-end; position:absolute;}
.chart-counts > span{align-items:center; color:var(--ink-2); display:inline-flex; font-size:var(--text-xs); gap:var(--space-1);}
.chart-counts svg{color:var(--wait);}
.chart-counts [data-tone=done] svg{color:var(--ok);}
.chart-counts [data-tone=failed] svg{color:var(--bad);}
.chart-counts strong{color:var(--ink); font-size:var(--text-lg);}
.chart-grid{fill:none; stroke:var(--line); stroke-width:1.5;}
.chart-line{fill:none; stroke:var(--accent); stroke-width:2; stroke-linecap:round; stroke-linejoin:round;}
.chart-area{fill:var(--accent-wash);}
.chart-mark{stroke:var(--paper); stroke-width:2;}
.chart-mark, .timeline-bar, .status-mark{fill:var(--wait);}
:is(.chart-mark, .timeline-bar, .status-mark)[data-tone=running]{fill:var(--run);}
:is(.chart-mark, .timeline-bar, .status-mark)[data-tone=done]{fill:var(--ok);}
:is(.chart-mark, .timeline-bar, .status-mark)[data-tone=failed]{fill:var(--ink-3);}
.org-box{fill:var(--well); filter:none; rx:var(--round-control); stroke:none;}
.diagram-edge{fill:none; stroke:var(--edge); stroke-width:2; stroke-linecap:round; stroke-linejoin:round; vector-effect:non-scaling-stroke;}
[data-edge-end]{fill:var(--paper); pointer-events:none; stroke:var(--edge); stroke-width:2; vector-effect:non-scaling-stroke;}
[data-org-edge][data-judge]{stroke-dasharray:5 5;}
.handoff-stage{min-width:0; padding-top:0px; position:relative;}
.handoff-seat{align-items:center; background:var(--paper); border-radius:var(--round-control); border:solid 1px var(--line); box-shadow:var(--shadow-small); display:grid; column-gap:var(--space-2); grid-template-columns:32px minmax(0,1fr); grid-template-rows:32px 16px 20px; height:80px; top:0; padding:var(--space-1) var(--space-3); position:absolute; transition:box-shadow var(--motion) var(--ease), transform var(--motion) var(--ease);}
.handoff-seat > .hint, .handoff-counts{grid-column:1/-1;}
.handoff-counts{color:var(--ink-3); font-size:var(--text-xs); font-variant-numeric:var(--number-style);}
.cut-text{min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}
.handoff-wires{height:112px; top:0; left:0; overflow:visible; pointer-events:none; position:absolute; width:100%; z-index:1;}
.handoff-wires .diagram-edge{pointer-events:stroke;}
.handoff-cards{align-items:start; display:grid; gap:0;}
.handoff-card{align-items:start; background:var(--paper); border-radius:var(--round-card); border:solid 1px var(--line); box-shadow:var(--shadow-small); display:flex; flex-direction:column; gap:var(--space-3); margin:0 6px; min-width:0; word-wrap:anywhere; padding:var(--space-4) var(--space-2); position:relative; transition:box-shadow var(--motion) var(--ease), transform var(--motion) var(--ease);}
.handoff-card > a, .handoff-card > code{max-width:100%;}
.handoff-card > code{overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}
.handoff-card{gap:var(--space-2);}
.handoff-card .badge{max-width:100%; word-wrap:anywhere; white-space:normal;}
.handoff-direction{align-items:center; color:var(--ink-2); display:flex; flex-wrap:wrap; font-size:var(--text-xs); gap:var(--space-1);}
.handoff-direction > span{min-width:0;}
.timeline-track{fill:var(--wash);}
.running-stripes{fill:none; stroke:var(--paper); stroke-width:1.5;}
[data-timeline] h3{margin-bottom:var(--space-1);}
[data-timeline]{margin-bottom:var(--space-4);}
.usage-row{align-items:center; border-bottom:solid 1px var(--line); color:var(--ink-2); display:grid; font-size:var(--text-xs); gap:var(--space-4); grid-template-columns:28px var(--track) 100px 88px 160px; padding:var(--space-4) 0;}
.usage-row:last-child{border-bottom:0;}
.usage-model{min-width:0; word-wrap:anywhere;}
.usage-model strong{color:var(--ink); font-size:var(--text-sm);}
.usage-model p{margin:var(--space-1) 0 0;}
.usage-track{background:var(--wash); border-radius:var(--round-pill); height:6px;}
.usage-track > span{background:var(--accent); border-radius:var(--round-pill); display:block; height:6px;}
.run-tiles{display:grid; gap:var(--space-4); grid-auto-flow:column; grid-auto-columns:var(--track);}
.run-tile{background:var(--paper); border-radius:var(--round-card); border:solid 1px var(--line); box-shadow:var(--shadow-small); display:grid; gap:var(--space-2); min-width:0; padding:var(--space-4); position:relative; transition:box-shadow var(--motion) var(--ease), transform var(--motion) var(--ease);}
.run-tile > .glyph{color:var(--accent);}
.run-tile strong{color:var(--ink); font-size:var(--text-xl); line-height:var(--leading-lg); word-wrap:anywhere;}
.feed-filters{display:flex; flex-wrap:wrap; gap:var(--space-2); margin-bottom:var(--space-4);}
.feed-filters [aria-pressed=true]{background:var(--accent-wash); color:var(--accent);}
.activity > [data-bubble-group]{border:0; display:grid; gap:var(--space-3); grid-template-columns:32px minmax(0,1fr); margin:0 0 var(--space-4); padding:0;}
.bubble-content{min-width:0;}
.bubble-heading{align-items:center; color:var(--ink); display:flex; gap:var(--space-3); margin:0 0 var(--space-2);}
.bubble-items{display:grid; gap:var(--space-2); justify-items:start; list-style:none; margin:0; padding:0;}
.activity .bubble-items > [data-activity-item]{align-items:baseline; background:var(--wash); border:0; border-radius:var(--round-chip) var(--round-card) var(--round-card) var(--round-card); display:flex; gap:var(--space-4); max-width:100%; padding:var(--space-3) var(--space-4);}
.bubble-message{min-width:0;}
.activity .bubble-items time{flex:0 0 auto; margin-left:auto;}
.recipient-chip{align-items:center; background:var(--paper); border-radius:var(--round-pill); color:var(--ink-2); display:inline-flex; font-size:var(--text-xs); gap:var(--space-1); margin:0 0 0 var(--space-2); padding:var(--space-1) var(--space-2);}

.order-progress{align-items:center; color:var(--ink-2); display:flex; font-size:var(--text-xs); font-variant-numeric:var(--number-style); gap:var(--space-3); min-width:0;}
.progress-track{background:var(--wash); border-radius:var(--round-pill); flex:1 1 0%; height:6px; min-width:var(--space-6);}
[data-progress-fill]{background:var(--run); border-radius:inherit; display:block; height:100%;}
[data-progress][data-tone=done] [data-progress-fill]{background:var(--ok);}
[data-progress][data-tone=failed] [data-progress-fill]{background:var(--bad);}
.page-head [data-progress]{margin-top:var(--space-3);}
[data-org-node], [data-timeline-row], [data-handoff-card], [data-handoff-seat], [data-usage-row]{opacity:1; transition:opacity var(--motion) var(--ease);}
.seat-select-control{overflow:visible;}
button.seat-select{background:#0000; border:0; border-radius:var(--round-card); box-shadow:none; display:block; height:100%; padding:0; width:100%;}
button.seat-select:hover{box-shadow:0 0 0 2px var(--accent) inset; transform:none;}
button.seat-select[aria-pressed=true]{box-shadow:0 0 0 2px var(--accent) inset;}
button.seat-select:focus-visible{outline:solid 2px var(--accent); outline-offset:var(--space-1);}
.seat-totals{color:var(--ink-2); display:flex; flex-wrap:wrap; font-size:var(--text-sm); font-variant-numeric:var(--number-style); gap:var(--space-4); margin:var(--space-4) 0 var(--space-6);}
[data-seat-tile]{align-content:start; background:var(--paper); border-radius:var(--round-card); border:solid 1px var(--line); box-shadow:var(--shadow-small); display:grid; flex:1 1 0%; gap:var(--space-2); min-width:140px; padding:var(--space-4); position:relative; transition:box-shadow var(--motion) var(--ease), transform var(--motion) var(--ease);}
[data-seat-tile] strong{color:var(--ink); font-size:var(--text-xl); line-height:var(--leading-lg);}
.seat-relations{display:flex; flex-wrap:wrap; gap:var(--space-3); margin-top:var(--space-4);}
[data-seat-relation]{align-items:center; background:var(--wash); border-radius:var(--round-pill); color:var(--ink-2); display:inline-flex; flex-wrap:wrap; font-size:var(--text-xs); gap:var(--space-1); word-wrap:anywhere; padding:var(--space-2) var(--space-3);}
.seat-launches{margin-bottom:var(--space-6);}
.seat-launch{align-items:center; background:var(--paper); border:solid 1px var(--line); border-radius:var(--round-control); box-shadow:var(--shadow-small); display:grid; gap:var(--space-2) var(--space-4); grid-template-columns:var(--track) 80px 100px 100px; margin-bottom:var(--space-2); padding:var(--space-3); position:relative; transition:box-shadow var(--motion) var(--ease), transform var(--motion) var(--ease);}
.seat-launch > a{word-wrap:anywhere;}
.seat-launch time{color:var(--ink-3); font-size:var(--text-xs); white-space:nowrap;}
.seat-launch .badge{justify-self:start;}
.seat-launch-result{color:var(--ink-2); font-size:var(--text-xs); grid-column:1/-1; margin:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}
.order-filters{display:flex; flex-wrap:wrap; gap:var(--space-2); margin-bottom:var(--space-4);}
.order-filters button{font-size:var(--text-xs); padding:var(--space-1) var(--space-3);}
.order-filters [aria-pressed=true]{background:var(--accent-wash); color:var(--accent);}
.compact-empty{color:var(--ink-3); font-size:var(--text-xs); margin:0; padding:var(--space-2) 0;}
.results-summary{align-items:center; color:var(--ink-2); display:flex; flex-wrap:wrap; gap:var(--space-3);}
[data-results-count]{color:var(--ink); font-size:var(--text-display); line-height:var(--leading-display);}
.results-summary [data-progress]{flex:1 1 0%; margin-left:var(--space-3);}
.results-latest{align-items:baseline; color:var(--ink-2); display:flex; flex-wrap:wrap; font-size:var(--text-xs); gap:var(--space-2); margin:var(--space-4) 0;}
.results-latest a{word-wrap:anywhere;}
.results-file{align-items:center; border-top:solid 1px var(--line); display:grid; gap:var(--space-4); grid-template-columns:var(--track) minmax(0, 180px) 120px; padding:var(--space-3) 0;}
.result-author{align-items:center; color:var(--ink-2); display:flex; font-size:var(--text-xs); gap:var(--space-2); word-wrap:anywhere;}
.levels-body{align-items:stretch; display:grid; gap:0; grid-template-columns:176px var(--track);}
.level-steps{display:block; height:calc(4 * var(--level-row-height)); width:176px;}
.level-tone-0{--slab-left:var(--level-2); --slab-right:var(--level-3); --slab-top:var(--level-1);}
.level-tone-1{--slab-left:var(--level-3); --slab-right:var(--level-4); --slab-top:var(--level-2);}
.level-tone-2{--slab-left:var(--level-4); --slab-right:var(--level-5); --slab-top:var(--level-3);}
.level-tone-3{--slab-left:var(--level-5); --slab-right:var(--level-6); --slab-top:var(--level-4);}
.level-slab:not([data-working="0"]){--slab-left:var(--accent-side); --slab-right:var(--accent-edge); --slab-top:var(--accent);}
.level-step{fill:var(--slab-top);}
[data-level-face=left]{fill:var(--slab-left);}
[data-level-face=right]{fill:var(--slab-right);}
.level-member{fill:var(--ink-2); stroke:var(--paper); stroke-width:2;}
.level-leader{fill:none; stroke:var(--line-2); stroke-width:1;}
.level-row{align-items:center; color:var(--ink-2); display:grid; font-size:var(--text-xs); gap:var(--space-3); grid-template-columns:var(--track) 80px 120px 100px; height:var(--level-row-height); padding-left:var(--space-4); position:relative;}
.level-row::before{border-top:solid 1px var(--line-2); content:""; left:0; top:50%; position:absolute; width:var(--space-2);}
.level-row strong{color:var(--ink); font-size:var(--text-sm);}
.launch-cards{display:grid; gap:var(--space-4); grid-template-columns:repeat(2, var(--track)); margin:var(--space-4) 0 var(--space-6);}
.launch-card{background:var(--paper); border-radius:var(--round-card); border:solid 1px var(--line); box-shadow:var(--shadow-small); min-width:0; padding:var(--space-4); position:relative; transition:box-shadow var(--motion) var(--ease), transform var(--motion) var(--ease);}
.launch-card .who{min-width:0; word-wrap:anywhere;}
.launch-card .who svg{flex:0 0 auto;}
.launch-card > a{display:block; font-size:var(--text-sm); word-wrap:anywhere;}
.launch-model{color:var(--ink-2); font-size:var(--text-xs); margin:var(--space-2) 0; word-wrap:anywhere;}
.launch-stats{color:var(--ink-2); display:flex; flex-wrap:wrap; font-size:var(--text-xs); font-variant-numeric:var(--number-style); gap:var(--space-2) var(--space-4); margin:var(--space-4) 0 var(--space-3);}
[data-launch-stat]{word-wrap:anywhere;}
[data-launch-stat] strong{color:var(--ink); font-size:var(--text-lg);}
.launch-result{color:var(--ink-3); font-size:var(--text-xs); margin:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}

.seat-icon{flex:0 0 auto; overflow:visible; vertical-align:middle;}

/* Identity marks never contain visible text; status keeps its own palette. */
.seat-mark{border-radius:var(--round-pill); display:inline-block; flex:0 0 auto; height:var(--space-2); min-width:var(--space-2); width:var(--space-2);}
.seat-edge{border-radius:0 var(--round-chip) var(--round-chip) 0; height:var(--space-8); left:0; top:var(--space-4); min-width:3px; position:absolute; width:3px;}
.usage-seats, .usage-seats > span{align-items:center; display:flex; flex-wrap:wrap; gap:var(--space-2);}
.usage-seats{gap:var(--space-3);}
[data-card-icon]{align-items:center; background:var(--wash); border-radius:var(--round-icon); color:var(--ink-2); display:inline-flex; flex:0 0 28px; height:28px; justify-content:center; vertical-align:middle; width:28px;}
[data-card-icon] svg{flex:0 0 auto; height:var(--space-4); width:var(--space-4);}
[data-icon-tone=ok]{background:var(--ok-wash); color:var(--ok);}
[data-icon-tone=attention]{background:var(--attention-wash); color:var(--attention);}
[data-icon-tone=accent]{background:var(--accent-wash); color:var(--accent);}
[data-icon-tone=run]{background:var(--run-wash); color:var(--run);}
h3, .card-heading{align-items:center; display:flex; gap:var(--space-2); word-wrap:anywhere;}
.stat{position:relative;}
.hero .stat{padding-right:var(--space-8);}
.hero .stat > [data-card-icon]{top:var(--space-3); right:var(--space-3); position:absolute;}
.hero .stat > [data-stat-note]{margin-right:-32px;}
.run-chart[data-empty-plot]{height:64px;}
.launch-card:last-child:nth-child(odd){grid-column:1/-1;}
.empty svg.empty-art[data-empty-art=activity-line]{color:var(--run);}
.empty-art[data-empty-art=activity-line] .empty-tone{fill:var(--run-wash);}
.empty svg.empty-art[data-empty-art=accepted]{color:var(--ok);}
.empty-art[data-empty-art=accepted] .empty-tone{fill:var(--ok-wash);}
.org-surface{transition:transform var(--motion) var(--ease);}
[data-org-node]:has(button):hover .org-surface{transform:translateY(-1px);}
[data-org-node]:has(button):hover .org-box{filter:var(--shadow-svg);}
[data-org-node]:focus-within .org-box{stroke:var(--accent); stroke-width:2;}
:is(.seat, .home-seat, .handoff-card, .launch-card, .seat-launch):has(a):hover{box-shadow:var(--shadow); transform:translateY(-1px);}
:is(.seat, .home-seat, .handoff-card, .launch-card, .seat-launch):has(a):focus-within{box-shadow:var(--shadow); outline:solid 2px var(--accent); outline-offset:3px;}

/* Only navigation attaches these temporary attributes. No fill mode survives it. */
[data-motion=on] [data-enter]{--enter-delay:0ms; animation-delay:var(--enter-delay);}
[data-motion=on] [data-enter-step="1"]{--enter-delay:30ms;}
[data-motion=on] [data-enter-step="2"]{--enter-delay:60ms;}
[data-motion=on] [data-enter-step="3"]{--enter-delay:90ms;}
[data-motion=on] [data-enter-step="4"]{--enter-delay:120ms;}
[data-motion=on] [data-enter-step="5"]{--enter-delay:150ms;}
[data-motion=on] [data-enter-step="6"]{--enter-delay:180ms;}
[data-motion=on] [data-enter-step="7"]{--enter-delay:210ms;}
[data-motion=on] [data-enter=card]{animation:card-in 200ms ease-out var(--enter-delay); opacity:0; transform:translateY(8px);}
[data-motion=on] [data-enter=line]{animation:line-in 400ms ease-out; stroke-dasharray:1; stroke-dashoffset:1;}
[data-motion=on] [data-enter=grow]{animation:bar-grow 300ms ease-out; transform-origin:left center; transform:scaleX(0);}
[data-motion=on] [data-enter=bar]{animation:bar-in 200ms ease-out var(--enter-delay); opacity:0;}
[data-motion=on] .dot[data-working-dot], [data-motion=on] .status-mark[data-working-dot], [data-motion=on] .badge[data-working-dot]::before{animation:working-dot 2s ease-in-out infinite; transform-box:fill-box; transform-origin:center;}
[data-motion=on] [data-stripe-motion]{animation:stripe-drift 4s linear infinite;}
[data-motion=reduce] *, [data-motion=reduce] *::before, [data-motion=reduce] *::after{transition:none !important;}
[data-motion=reduce] :is(a, button, .seat, .home-seat, .handoff-card, .launch-card, .seat-launch):hover, [data-motion=reduce] [data-org-node]:hover .org-surface{transform:none;}
@keyframes card-in{ 0%{opacity:0; transform:translateY(8px);} 100%{opacity:1; transform:translateY(0);} }
@keyframes line-in{ 0%{stroke-dashoffset:1;} 100%{stroke-dashoffset:0;} }
@keyframes bar-grow{ 0%{transform:scaleX(0);} 100%{transform:scaleX(1);} }
@keyframes bar-in{ 0%{opacity:0;} 100%{opacity:1;} }
@keyframes working-dot{ 0%, 100%{opacity:1; transform:scale(1);} 50%{opacity:0.55; transform:scale(0.85);} }
@keyframes stripe-drift{ 0%{transform:translateX(0);} 100%{transform:translateX(6px);} }

/* Semantic surfaces: a seat or kind always has both its words and its ink. */
[data-seat-tone="1"]{--seat-ink:var(--seat-1-ink); --seat-wash:var(--seat-1-wash);}
[data-seat-tone="2"]{--seat-ink:var(--seat-2-ink); --seat-wash:var(--seat-2-wash);}
[data-seat-tone="3"]{--seat-ink:var(--seat-3-ink); --seat-wash:var(--seat-3-wash);}
[data-seat-tone="4"]{--seat-ink:var(--seat-4-ink); --seat-wash:var(--seat-4-wash);}
[data-seat-tone="5"]{--seat-ink:var(--seat-5-ink); --seat-wash:var(--seat-5-wash);}
[data-seat-tone="6"]{--seat-ink:var(--seat-6-ink); --seat-wash:var(--seat-6-wash);}
[data-seat-tone=you]{--seat-ink:var(--you-ink); --seat-wash:var(--you-wash);}
[data-seat-tone=judge]{--seat-ink:var(--judge-ink); --seat-wash:var(--judge-wash);}
[data-seat-tone=system]{--seat-ink:var(--ink-2); --seat-wash:var(--wash);}
.seat-chip{align-items:center; background:#0000; border-radius:var(--round-chip); color:var(--ink-2); display:inline-flex; font-size:var(--text-xs); gap:var(--space-1); line-height:15pt; max-width:100%; min-width:0; padding:0 var(--space-2) 0 var(--space-1); vertical-align:middle;}
.seat-chip > .cut-text{color:inherit;}
.recipient-chip{background:#0000; margin:var(--space-1) 0 0; max-width:100%; padding:0;}
.kind-chip{background:var(--kind-wash); border-radius:var(--round-chip); color:var(--kind-ink); padding:var(--space-1) var(--space-2);}
.kind-chip .glyph{height:var(--space-5); width:var(--space-5);}
[data-kind-chip=skill]{--kind-ink:var(--kind-skill-ink); --kind-wash:var(--kind-skill-wash);}
[data-kind-chip=artifact]{--kind-ink:var(--kind-artifact-ink); --kind-wash:var(--kind-artifact-wash);}
[data-kind-chip=workflow]{--kind-ink:var(--kind-workflow-ink); --kind-wash:var(--kind-workflow-wash);}
[data-kind-chip=lesson]{--kind-ink:var(--kind-lesson-ink); --kind-wash:var(--kind-lesson-wash);}
code, .mono, .launch-order, button.link{background:var(--mono-wash); border-radius:var(--round-chip); color:var(--mono-ink);}
.time, time, .activity time, .seat-launch time, .ledger time, [data-usage-seconds], [data-replay-clock], .seat-run-facts > span:first-child, .seat-run-facts > span:nth-child(2), .seat-summary [data-seat-summary=seconds] strong, [data-team-stat=seconds] strong{color:var(--time); font-variant-numeric:var(--number-style);}
.seat-summary [data-seat-summary=accepted] strong, [data-team-stat=accepted] strong, .accepted-count, [data-results-count]{color:var(--ok);}
.seat-summary [data-seat-summary=sent-back] strong, [data-team-stat=sent-back] strong, [data-seat-stat=sent-back] strong, [data-metric=sent_back]{color:var(--ink-2);}
[data-team-stat=working] strong, [data-stat=running] strong{color:var(--run);}
[data-stat=attention] strong{color:var(--attention);}
[data-chart-count=done] strong{color:var(--ok);}
[data-chart-count=waiting] strong{color:var(--wait);}
[data-chart-count=failed] strong{color:var(--ink-2);}
.badge{background:var(--wash);}
.badge[data-state=CANCELLED]{background:var(--bad-wash); color:var(--bad);}
.seat-band{color:var(--ink); margin:0; padding:0 0 var(--space-2);}
.seat .seat-band{margin:0; padding:0 0 var(--space-2);}
.seat-band .seat-model{color:var(--ink-3); display:block; margin-top:var(--space-2);}
.seat-band .seat-head{gap:var(--space-2);}
.seat-summary-block{min-width:0;}
.seat-spark{display:block; height:40px; margin:var(--space-2) 0; max-width:100%; overflow:visible; width:100%;}
.spark-track{fill:var(--well);}
.spark-bar{fill:var(--seat-ink); opacity:0.5;}
.spark-line{fill:none; stroke:var(--seat-ink); stroke-width:1.5; stroke-linecap:round; stroke-linejoin:round; vector-effect:non-scaling-stroke;}
.spark-area{fill:var(--seat-ink); fill-opacity:1;}
.spark-end{fill:var(--seat-ink); stroke:var(--well); stroke-width:1; vector-effect:non-scaling-stroke;}
.seat-summary{display:grid; gap:var(--space-2); grid-template-columns:repeat(4, var(--track));}
.seat-summary > div{background:var(--wash); border-radius:var(--round-chip); color:var(--ink-2); font-size:var(--text-xs); min-width:0; word-wrap:anywhere; padding:var(--space-1);}
.seat-summary strong{color:var(--ink); display:block; font-size:var(--text-lg); font-weight:var(--weight-heading); line-height:18pt;}
.home-seat .badge::before{display:none;}
.home-seat .badge .dot{background:currentColor; height:var(--space-1); width:var(--space-1);}
.home-row{align-items:start; display:grid; gap:var(--space-4); grid-template-columns:minmax(0px, 2fr) var(--track);}
.home-row > *, .team-overview > *, .team-comparison > *, .gantt-lanes{max-width:100%; min-width:0;}
[data-view=home] .card{margin-bottom:var(--space-4); padding:var(--space-6);}
[data-view=home] .hero{margin-bottom:var(--space-4); padding:var(--space-8) var(--space-6) 0;}
[data-view=home] .drawing-caption{margin-bottom:var(--space-2);}
[data-view=home] .chart-counts{justify-content:flex-start; margin:var(--space-3) 0; position:static;}
[data-view=home] .run-chart .axis-label{font-size:var(--text-xl);}
[data-view=home] .run-chart{height:160px;}
[data-view=home] .results-summary [data-progress]{flex-basis:100%; margin-left:0;}
[data-view=home] .results-file{gap:0 var(--space-2); grid-template-columns:var(--track) auto; padding:var(--space-2) 0;}
[data-view=home] .results-file .seat-icon{height:var(--space-6); width:var(--space-6);}
[data-view=home] .results-latest{margin:var(--space-2) 0;}
[data-view=home] .results-file > .mono{grid-column:1/-1;}
[data-view=home] .block-head{flex-wrap:wrap; gap:var(--space-2);}
[data-view=home] .empty{padding:var(--space-3) 0;}
[data-activity]{max-height:240px; overflow-y:auto; padding:var(--space-1);}
[data-run-meter] > svg{display:block; margin:0 auto;}
[data-view=home] [data-run-meter] > svg{height:112px;}
.meter-ring-track, .meter-ring-fill{fill:none; stroke-width:10;}
.meter-ring-track{stroke:var(--wash);}
.meter-ring-fill{stroke:var(--run);}
.ring-value{fill:var(--ink); font-size:var(--text-xl); font-weight:var(--weight-heading);}
[data-meter]{color:var(--ink-2); font-size:var(--text-xs); margin-top:var(--space-3);}
.meter-label{display:flex; gap:var(--space-2); justify-content:space-between;}
.thin-track, .week-track{background:var(--wash); border-radius:var(--round-chip); display:flex; height:6px; margin-top:6px;}
[data-meter-fill]{background:var(--ok); border-radius:inherit; display:block; height:100%;}
[data-meter=seats] [data-meter-fill]{background:var(--run);}
.week-strip{display:grid; gap:var(--space-2); grid-template-columns:repeat(7, var(--track));}
.week-day{border:solid 1px var(--line); border-radius:var(--round-control); color:var(--ink-2); font-size:var(--text-xs); min-width:0; padding:var(--space-2) var(--space-4); position:relative;}
.week-day > strong{color:var(--ink); display:block; font-size:var(--text-xl); line-height:21pt;}
.week-day[data-week-today]{background:var(--accent-wash); border-color:var(--accent);}
.week-day:hover{background:var(--accent-wash);}
.today-tag{color:var(--accent); display:block;}
.week-track{height:5px;}
.week-track > span{background:var(--wait); display:block; height:100%;}
.week-track [data-week-state=SUCCEEDED], .step-track [data-state=SUCCEEDED]{background:var(--ok);}
.week-track [data-week-state=running], .step-track [data-state=LEASED], .step-track [data-state=JUDGING]{background:var(--run);}
.week-track [data-week-state=FAILED], .step-track [data-state=FAILED], .step-track [data-state=DEAD], .step-track [data-state=CANCELLED]{background:var(--bad);}
.week-legend{display:flex; flex-wrap:wrap; gap:var(--space-3); margin-top:var(--space-3);}
.step-track{display:flex; gap:var(--space-1); height:6px; margin-bottom:var(--space-2);}
.step-track > span{background:var(--wait); border-radius:var(--round-chip); flex:1 1 0%; min-width:0;}
.order-step-caption{align-items:center; display:flex; font-size:var(--text-xs); gap:var(--space-3);}
.order-seat-stack{align-items:center; display:inline-flex; flex:0 0 auto;}
.order-seat-stack > span + span{margin-left:-6px;}
.order-seat-stack .seat-icon{border-radius:var(--round-chip); box-shadow:0 0 0 2px var(--paper);}
.home-library-grid{display:grid; gap:var(--space-4); grid-template-columns:repeat(auto-fit, minmax(144px, 1fr));}
.home-entry{align-content:start; border-radius:var(--round-control); border:solid 1px var(--line); color:var(--ink); display:grid; font-size:var(--text-sm); gap:var(--space-2); min-width:0; word-wrap:anywhere; padding:var(--space-3);}
.home-entry .kind-chip{justify-self:start;}
.home-entry:hover{box-shadow:var(--shadow); transform:translateY(-1px);}
.home-file{border-top:solid 1px var(--line); display:grid; font-size:var(--text-xs); gap:var(--space-1) var(--space-2); grid-template-columns:var(--track) auto; padding:var(--space-2) 0;}
.home-file > code{grid-column:1/-1;}
.home-file > .seat-chip{grid-column:1/-1; justify-self:start;}
.home-file .seat-chip .seat-icon{height:28px; width:28px;}
[data-team-stats]{gap:var(--space-4); grid-template-columns:repeat(6, var(--track)); margin-bottom:var(--space-4);}
[data-team-stats] .stat{min-width:0; padding:var(--space-2);}
[data-team-stats] .stat > [data-card-icon]{margin-bottom:var(--space-2);}
[data-team-stats] .stat-label{display:block;}
[data-team-stats] [data-stat-value]{font-size:var(--text-xl);}
[data-team-stats] [data-stat-note]{white-space:normal;}
[data-view=team] .card{margin-bottom:var(--space-4); padding:var(--space-6);}
[data-view=team] .card > h3{margin-bottom:var(--space-2);}
[data-view=team] .page-head{margin-bottom:var(--space-4);}
[data-view=team] .seat{gap:var(--space-2);}
[data-view=team] .card > [data-timeline]{margin-bottom:0;}
[data-view=team] .drawing-caption{margin-bottom:var(--space-2);}
.team-overview{align-items:start; display:grid; gap:var(--space-4); grid-template-columns:minmax(0px, 2fr) var(--track);}
.team-overview .org-tree{max-width:600px;}
.team-overview .usage-row{gap:var(--space-2); grid-template-columns:28px var(--track) auto; padding:var(--space-4);}
.team-overview .usage-row > .logo{grid-column:1; grid-row:1 / 4;}
.team-overview .usage-model{display:contents;}
.team-overview .usage-model > strong{grid-column:2 / -1;}
.team-overview .usage-model > p{grid-column:2; grid-row:2; margin:0;}
.team-overview .usage-seats .seat-icon{height:var(--space-5); width:var(--space-5);}
.team-overview .usage-row > [data-usage-launches]{grid-column:3; grid-row:2;}
.team-overview .usage-row > [data-usage-seconds]{grid-column:3; grid-row:3;}
.team-overview .usage-track{grid-column:2; grid-row:3;}
.team-overview .usage-seats{gap:var(--space-1);}
.team-overview [data-seat-panel]{margin-top:var(--space-4); padding:var(--space-3);}
.team-overview .seat-launch{grid-template-columns:var(--track) auto;}
.team-overview .seat-totals{gap:var(--space-2);}
.team-overview [data-seat-tile]{min-width:110px; padding:var(--space-2);}
.team-overview [data-seat-panel] .activity{max-height:400px; overflow-y:auto;}
.seat-reference-list{display:grid; gap:var(--space-3);}
.seat-reference-list > div{display:flex; gap:var(--space-3); justify-content:space-between;}
.launch-table .seat-chip{height:var(--space-5); padding:0 var(--space-1) 0 0;}
.launch-table td > :is(.seat-chip, .badge){display:flex; max-width:100%; width:max-content;}
.launch-table .seat-icon{height:28px; width:28px;}
.launch-table .launch-notes > .badge{overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}

[data-state-count=SUCCEEDED]{color:var(--ok);}
[data-state-count=FAILED]{color:var(--ink-2);}
.org-state-wash{fill:var(--wash);}
.org-state-wash[data-state=running]{fill:var(--run-wash);}
.org-state-word{fill:var(--wait);}
.org-state-word[data-state=running]{fill:var(--run);}
[data-stat-note] .badge{box-shadow:none; gap:var(--space-1); padding:0 var(--space-1);}
/* Focus keeps text opaque in the quiet AA ink; only drawings fade. */
[data-dim], [data-dim] *{box-shadow:none !important; color:var(--ink-3) !important; filter:none !important; opacity:1;}
[data-dim] text, [data-dim] tspan{fill:var(--ink-3); fill-opacity:1; stroke:none;}
[data-dim] :is(rect, img, path, circle, ellipse, line, polyline, polygon, [data-model-icon], [data-seat-colour], [data-seat-wash], .activity-icon, .dot, .usage-track, [data-usage-bar], [data-timeline-bar]){opacity:0.4 !important; transition:opacity var(--motion) var(--ease);}
:is([data-org-edge], [data-handoff-edge], [data-flow-edge], [data-edge-end])[data-dim]{opacity:0.4 !important; transition:opacity var(--motion) var(--ease);}
[data-dim]::before, [data-dim]::after, [data-dim] *::before, [data-dim] *::after{box-shadow:none !important; opacity:0.4 !important;}
:is(.handoff-card, .handoff-seat)[data-dim]{background:rgb(255 255 255 / 0.4); border-color:rgb(23 32 51 / 0.032);}
.usage-row[data-dim]{border-color:rgb(23 32 51 / 0.032);}
[data-dim] :is(.pill, .badge){background:rgb(23 32 51 / 0.016); color:var(--ink-3);}
[data-dim] a, [data-dim] a:hover, [data-dim] a:focus-visible{color:var(--ink-3);}

/* An interactive work surface; borders are reserved for nodes and launch cards. */
.canvas-card{display:grid; gap:var(--space-2); grid-template-rows:auto 480px auto auto; padding:var(--space-4);}
.canvas-head{align-items:center; display:grid; gap:var(--space-4); grid-template-columns:minmax(240px, 1fr) minmax(0, 1.35fr);}
.canvas-head h3{margin:0 0 var(--space-1);}
.canvas-head p{margin:var(--space-2) 0 0;}
.canvas-stats{display:flex; flex-wrap:wrap; gap:var(--space-2) var(--space-4); justify-content:flex-end;}
.work-stat{align-items:center; color:var(--ink-2); display:flex; font-size:var(--text-xs); gap:var(--space-1); min-width:0;}
.work-stat strong, .work-stat span{display:block;}
.work-stat strong{color:var(--ink); font-size:var(--text-md);}
.work-stat [data-card-icon]{flex-basis:var(--space-6); height:var(--space-6); width:var(--space-6);}
.canvas-workarea{display:grid; gap:var(--space-3); grid-template-columns:210px var(--track); min-height:0;}
[data-canvas-rail]{display:flex; flex-direction:column; gap:var(--space-3); height:480px; min-height:0;}
[data-canvas-search]{font-size:var(--text-xs); padding:var(--space-2);}
[data-canvas-list]{flex:1 1 0%; min-height:0; overflow-y:auto; padding:var(--space-1);}
[data-canvas-list] .group-heading{margin:var(--space-3) 0 6px;}
[data-canvas-list] .group-heading:first-child{margin-top:0;}
[data-canvas-item]{font-size:var(--text-xs); justify-content:start; margin-bottom:var(--space-1); padding:var(--space-1); width:100%;}
[data-canvas-item] .cut-text{flex:1 1 0%; text-align:left;}
[data-canvas-item] .dot{flex:0 0 auto; height:6px; width:6px;}
[data-canvas-item][aria-pressed=true]{background:var(--accent-wash); color:var(--accent);}
[data-canvas-stage]{background-color:var(--wash); background-image:radial-gradient(circle at center, var(--line) 1px, #0000 1px); background-size:16px 16px; border-radius:var(--round-hero); box-shadow:inset 0 0 0 1px var(--line); cursor:grab; height:480px; min-width:0; min-height:0; overflow:hidden; position:relative; touch-action:none; transition:box-shadow var(--motion) var(--ease);}
[data-canvas-stage]:hover{box-shadow:inset 0 0 0 1px var(--line-2);}
[data-canvas-stage]:focus-visible{outline:solid 2px var(--accent); outline-offset:3px;}
[data-canvas-stage][data-panning]{cursor:grabbing;}
[data-canvas-view]{left:0; top:0; position:absolute; transform-origin:0 0;}
.canvas-wires, .canvas-rings{inset:0; overflow:visible; pointer-events:none; position:absolute;}
.canvas-rings{z-index:2;}
[data-canvas-edge][data-kind=checks]{stroke-dasharray:5 5;}
.work-icon{color:var(--ink-2); flex:0 0 auto; vertical-align:middle;}
button[data-canvas-node]{background:var(--paper); border:solid 1px var(--line-2); border-radius:var(--round-card); box-shadow:var(--shadow-small); color:var(--ink); display:grid; font-size:var(--text-xs); column-gap:var(--space-2); row-gap:0; grid-template-columns:28px var(--track); grid-template-rows:18px 16px 18px; line-height:13.5pt; padding:var(--space-1); position:absolute; text-align:left;}
[data-canvas-node] .work-icon{grid-row:1 / 3;}
[data-canvas-node] strong, [data-canvas-node] > .hint{grid-column:2;}
[data-canvas-node] .badge{box-shadow:none; grid-column:2; justify-self:start; line-height:12pt; padding:0 var(--space-1);}
[data-canvas-node] > .hint{line-height:12pt;}
button[data-canvas-node][data-kind=order]{gap:0 var(--space-1); grid-template-columns:16px var(--track); grid-template-rows:16px 16px; padding:var(--space-1) var(--space-1);}
[data-canvas-node][data-kind=order] strong{font-size:var(--text-xs); line-height:12pt; width:100%;}
button[data-canvas-node]:hover{border-color:var(--accent); box-shadow:var(--shadow); transform:none;}
button[data-canvas-node][aria-pressed=true]{box-shadow:0 0 0 6px var(--accent-wash), var(--shadow); outline:solid 2px var(--edge); outline-offset:1px;}
button[data-canvas-node][data-search-dim]{background:var(--wash); border-color:var(--line); box-shadow:none; color:var(--ink-3);}
[data-canvas-node][data-search-dim] .work-icon{opacity:0.4; transition:opacity var(--motion) var(--ease);}
.canvas-tools{align-items:center; background:var(--paper); border-radius:var(--round-control); box-shadow:var(--lift-3); cursor:default; display:flex; gap:var(--space-1); right:var(--space-2); bottom:var(--space-2); padding:var(--space-1); position:absolute; z-index:3;}
.canvas-tools button{padding:var(--space-1) var(--space-3);}
[data-canvas-scale]{font-size:var(--text-xs); text-align:center; width:48px;}
[data-canvas-panel]{box-shadow:inset 0 1px var(--line); display:flex; flex-direction:column; min-height:0; padding-top:var(--space-1);}
.canvas-panel-head{align-items:center; display:flex; gap:var(--space-3); justify-content:space-between; min-height:40px;}
.canvas-panel-head > strong{font-size:var(--text-sm); max-width:40%;}
.canvas-tablist{display:flex; flex:0 0 auto; gap:var(--space-1);}
.canvas-tablist button{padding:var(--space-1) var(--space-3);}
.canvas-tablist [aria-selected=true]{background:var(--accent-wash); color:var(--accent);}
.canvas-tab-content{max-height:280px; min-height:0; overflow:auto; padding:var(--space-2) var(--space-4) var(--space-2) 0; position:relative;}
.canvas-tab-content:focus-visible{outline:solid 2px var(--accent); outline-offset:-2px;}
.gantt-ruler{color:var(--ink-3); display:flex; font-size:var(--text-xs); justify-content:space-between; margin-left:160px;}
.gantt-row{align-items:center; display:grid; font-size:var(--text-xs); gap:0; grid-template-columns:var(--track); height:var(--space-6); padding:0;}
.gantt-row .who{gap:var(--space-2); min-width:0;}
[data-gantt-row][data-selected]{background:var(--accent-wash); border-radius:var(--round-control);}
.gantt-track{background:var(--wash); border-radius:var(--round-chip); height:var(--space-6); min-width:0; position:relative;}
[data-gantt-bar]{background:var(--wait); border-radius:var(--round-chip); height:14px; min-width:6px; position:absolute;}
[data-gantt-bar][data-tone=running]{background:var(--run);}
[data-gantt-bar][data-tone=done]{background:var(--ok);}
[data-gantt-bar][data-tone=failed]{background:var(--ink-3); border-left:3px solid var(--bad);}
.gantt-cursor{background:var(--accent); top:28px; pointer-events:none; position:absolute; width:1px;}
.canvas-event{align-items:baseline; border-bottom:solid 1px var(--line); display:flex; font-size:var(--text-xs); gap:var(--space-4); padding:var(--space-2) 0;}
.canvas-event time{color:var(--ink-3); flex:0 0 auto;}
.canvas-event .work-sentence{display:block; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}
.canvas-file{align-items:center; border-bottom:solid 1px var(--line); display:grid; gap:var(--space-3); grid-template-columns:var(--track) 24px 170px; padding:var(--space-2) 0;}
.full-seat-panel{display:grid; grid-template-columns:var(--track) auto; word-wrap:anywhere;}
.full-seat-panel > :not(.seat-full-head):not(.seat-relations){grid-column:1/-1;}
.full-seat-panel > .seat-relations{align-items:center; grid-column:2; grid-row:1; margin:0; padding-left:var(--space-4);}
.seat-full-head{align-items:center; display:flex; gap:var(--space-3);}
.seat-full-head h3, .seat-full-head p{margin:0;}
.seat-full-head > .badge{margin-left:auto;}
.seat-full-stats{border-top:solid 1px var(--line); border-bottom:solid 1px var(--line); display:flex; flex-wrap:wrap; gap:var(--space-4) var(--space-8); margin:var(--space-2) 0; padding:var(--space-2) 0;}
.seat-full-stats strong{font-size:var(--text-xl);}
.seat-full-columns{display:grid; gap:var(--space-4); grid-template-columns:minmax(0, 1.1fr) var(--track);}
[data-seat-talk], [data-seat-runs]{display:flex; flex-direction:column; min-width:0;}
.seat-run-list{margin-top:auto; overflow-y:auto; padding:var(--space-1);}
.seat-full-columns{align-items:stretch; margin-bottom:var(--space-4);}
.seat-full-columns .list-window{margin-top:auto;}
[data-seat-talk] .feed-filters{gap:var(--space-1); margin-bottom:var(--space-3);}
[data-seat-talk-filter]{padding:var(--space-1) var(--space-3);}
.seat-messages{align-content:start; display:grid; gap:var(--space-3); margin:0; overflow:auto; padding:var(--space-1);}
.seat-message{background:var(--wash); border-radius:var(--round-chip) var(--round-control) var(--round-control) var(--round-control); color:var(--ink-2); font-size:var(--text-sm); justify-self:start; max-width:92%; min-width:0; padding:var(--space-3);}
.seat-message[data-own]{background:var(--accent-wash); border-radius:var(--round-control) var(--round-chip) var(--round-control) var(--round-control); justify-self:end;}
.seat-message .who{flex-wrap:wrap; gap:var(--space-1); margin-bottom:6px;}
.seat-message time{color:var(--ink-3); font-size:var(--text-xs); margin-left:auto;}
[data-seat-compose]{border-top:solid 1px var(--line); gap:var(--space-2) var(--space-4); grid-template-columns:var(--track) minmax(0px, 2fr) auto; padding-top:var(--space-4);}
[data-seat-compose] > label{align-content:start; min-width:0;}
[data-seat-compose] > p{grid-column:1/-1; margin:0;}
[data-seat-compose] textarea{min-height:64px;}
[data-seat-compose] button{align-self:end; grid-column:3; grid-row:1; justify-self:start;}
.seat-run{background:var(--paper); border:solid 1px var(--line); border-radius:var(--round-control); margin-bottom:var(--space-3); padding:var(--space-3);}
.seat-run-head{align-items:start; display:grid; font-size:var(--text-sm); gap:var(--space-2); grid-template-columns:auto var(--track) auto;}
.seat-run-head button{font-size:var(--text-xs); padding:var(--space-1) var(--space-2);}
.seat-run-facts{align-items:center; color:var(--ink-3); display:flex; flex-wrap:wrap; font-size:var(--text-xs); gap:var(--space-2) var(--space-3); margin-top:var(--space-3);}
.seat-run-facts .badge{max-width:100%; white-space:nowrap;}
.seat-run-reason{-webkit-line-clamp:2; -webkit-box-orient:vertical; display:-webkit-box; overflow:hidden; text-overflow:ellipsis;}
[data-seat-run-steps]{margin:var(--space-4) 0 0 var(--space-1);}
.seat-run-step{border-left:1px solid var(--line-2); font-size:var(--text-xs); padding:0 0 var(--space-4) var(--space-6); position:relative;}
.seat-run-step::before{background:var(--accent); border-radius:var(--round-pill); content:""; height:7px; left:-4px; top:6px; position:absolute; width:7px;}
.seat-run-step > .hint{display:block;}
.team-comparison{align-items:stretch; display:grid; gap:var(--space-4); grid-template-columns:repeat(2, var(--track));}
.team-comparison .level-row{gap:0 var(--space-2); grid-template-columns:repeat(2, var(--track)); padding-left:var(--space-2);}
.team-comparison .usage-row{gap:var(--space-2); grid-template-columns:28px var(--track) auto;}
.team-comparison [data-usage-seconds]{grid-column:2;}
.team-comparison .usage-track{grid-column:3; width:84px;}

/* Replay fades drawings only: future text keeps its audited contrast. */
button[data-canvas-node][data-replay=future]{border-style:dashed;}
[data-canvas-node][data-replay=future] .work-icon{opacity:0.4;}
[data-canvas-edge][data-replay=future]{opacity:0.4; stroke-dasharray:5 5;}
[data-gantt-bar][data-replay=future]{opacity:0.4;}
[data-canvas-content=timeline]{max-height:none; overflow:visible; padding-bottom:var(--space-4);}
.gantt-duration{color:var(--ink-3); font-size:var(--text-xs); top:var(--space-1); line-height:12pt; position:absolute; white-space:nowrap;}
.replay-bar{align-items:center; display:grid; gap:var(--space-3); grid-template-columns:auto minmax(80px, 1fr) auto auto; padding:var(--space-2) 0;}
[data-replay-range]{accent-color:var(--accent); min-width:0; width:100%;}
[data-replay-clock]{color:var(--ink-3); font-size:var(--text-xs); font-variant-numeric:var(--number-style);}

button[data-canvas-node]:not([data-kind=order]) .badge{background:var(--wash); padding:0;}

[data-gantt-row]{align-items:center; display:grid; gap:var(--space-4); grid-template-columns:144px var(--track);}
[data-gantt-label]{justify-self:start;}
[data-canvas-item] > .seat-chip{flex:1 1 0%;}
.seat-message time, .canvas-event time, [data-replay-clock]{color:var(--time);}
[data-seat-seconds], [data-seat-stat=seconds] strong, [data-canvas-stat=seconds] strong, [data-run-tile=duration] strong, [data-launch-stat=seconds], [data-metric=seconds], .seat-launch > .hint{color:var(--time); font-variant-numeric:var(--number-style);}
[data-seat-stat=accepted] strong, [data-canvas-stat=accepted] strong{color:var(--ok);}
[data-seat-sent-back], [data-launch-stat=sent-back] strong, [data-run-tile=sent-back] strong{color:var(--ink-2);}
[data-canvas-node]:not([data-kind=order]) .badge{background:var(--wash);}
[data-canvas-node]:not([data-kind=order]) .badge[data-state=running]{background:var(--run-wash);}

.home-row :is(form, label, input, textarea, .orders, .activity), .team-overview :is(.usage-model, .seat-relations){max-width:100%; min-width:0;}

/* Inset content shares a quiet well, while the outer card supplies elevation. */
.card :is(.order, .seat, .home-seat, .handoff-seat, .handoff-card, .launch-card, .run-tile, [data-seat-tile], .seat-launch, .seat-run, .home-entry, .week-day){background:var(--well); border:0; border-radius:var(--round-control); box-shadow:none;}
.card :is(a.order, .home-entry, .seat:has(a), .home-seat:has(a), .handoff-card:has(a), .launch-card:has(a), .seat-launch:has(a)):hover{box-shadow:var(--lift-1);}
.card .card{background:var(--paper); box-shadow:var(--lift-1); margin-bottom:0;}
.canvas-workarea, .canvas-tab-content{border-radius:var(--round-control);}
.canvas-tab-content{background:var(--well); padding:var(--space-2) var(--space-4);}
.canvas-tablist, .replay-bar{background:var(--canvas); border-radius:var(--round-control);}
.canvas-tablist{padding:var(--space-1);}
.replay-bar{padding:var(--space-2);}
[data-canvas-rail]{background:var(--canvas); border-radius:var(--round-control); padding:var(--space-2);}
.usage-row{background:var(--well); border:0; border-radius:var(--round-control); margin-top:var(--space-2); padding:var(--space-4);}
.order-title, .seat-name{color:var(--ink); font-size:var(--text-lg); font-weight:var(--weight-heading);}
.hero .stat{box-shadow:var(--lift-2);}
.hero .stat > [data-card-icon]{top:var(--space-4); right:var(--space-4);}
.hero .stat > [data-stat-note]{margin-right:0;}
.hero .stat{padding-right:var(--space-4);}
.hero .stat-label{display:block; padding-right:var(--space-8);}
.top{background:var(--canvas);}
.show-all{margin-top:var(--space-4);}
[data-list-window]{max-height:var(--list-height, 400px); overflow-y:auto; padding:var(--space-1);}
[data-list-window][data-expanded]{max-height:none; overflow:visible;}
[data-list-window]:focus-visible{outline:solid 2px var(--accent); outline-offset:2px;}

.hero-actions{align-items:center; display:flex; flex:0 0 auto; gap:var(--space-4);}
.hero-actions > a{color:var(--ink); font-size:var(--text-sm);}
[data-progress] > .step-track[data-progress-fill]{background:#0000; border-radius:0; height:6px;}
.step-label{color:var(--ink-2);}
#home-orders .order{align-items:center; grid-template-columns:var(--track) auto;}
#home-orders .order > .badge{grid-column:2; grid-row:1;}
#home-orders .order > :is(.lead-seat, .order-step-summary){grid-column:1/-1;}
[data-canvas-list] .empty{align-items:start; flex-direction:column;}

[data-activity][data-expanded]{max-height:none; overflow:visible;}
[data-activity]:focus-visible{outline:solid 2px var(--accent); outline-offset:2px;}

[data-motion=on] [data-list-window][data-expanded]{animation:card-in var(--motion) ease-out;}

#compose-form{align-items:start; grid-template-columns:var(--track) minmax(0px, 2fr);}
#compose-form > :not(label){grid-column:1/-1;}
#compose-lead{align-items:start; display:grid; gap:var(--space-4); grid-template-columns:repeat(2, var(--track));}
#compose-lead .hint{margin:0;}
[data-list-window], [data-activity]{transition:box-shadow var(--motion) var(--ease);}
[data-list-window]:hover, [data-activity]:hover{box-shadow:inset 0 -1px var(--line);}

[data-view=team] .seat .seat-band{padding-bottom:0;}
[data-view=team] .seat-summary > div{padding:0;}

/* Distinct blocks keep their own white surface and elevation. */
.card:is(.stat, .seat, .home-seat, .order, .usage-row, .handoff-seat, .handoff-card, .launch-card, .run-tile){background:var(--paper); box-shadow:var(--lift-1); margin-bottom:0; padding:var(--space-4);}
.card.stat{border-radius:var(--round-control);}
.card:is(.handoff-card, .handoff-seat){padding:var(--space-4) var(--space-2);}
.card.stat[data-team-stat]{padding:var(--space-2);}
.card.usage-row{border-radius:var(--round-control);}
.usage-track{background:var(--line); min-width:40px; width:100%;}
.card:has(> a):hover, a.card:hover{box-shadow:var(--lift-3);}
.card[data-dim]{background:var(--paper); box-shadow:var(--lift-1) !important;}
/* A coloured seat wash always has room for its 28 px mark. */
.seat-icon{min-width:28px; min-height:28px;}

/* Empty days need only a date; activity carries the emphasis. */
.week-day{align-items:center; display:grid; gap:0 var(--space-2); grid-template-columns:auto auto; padding:var(--space-2) var(--space-3);}
.week-day > strong{justify-self:end;}
.week-day > .hint, .week-track{grid-column:1/-1;}
.week-day[data-count="0"]{background:#0000;}
.week-day[data-week-today]{background:var(--accent-wash); box-shadow:0 0 0 1px var(--accent) inset;}
.today-tag{grid-column:2; grid-row:2; justify-self:end;}
.week-track{margin-top:var(--space-1);}
.week-legend{margin-top:var(--space-2);}

.hero::before{z-index:-2;}
#hero-art{border-radius:0 var(--round-hero) var(--round-hero) 0; inset:0 0 56px auto; overflow:hidden; pointer-events:none; position:absolute; width:46%; z-index:-1;}
.hero-art{fill:none; height:100%; stroke-width:2; width:100%;}
.hero-art-blue{opacity:0.18; stroke:var(--accent);}
.hero-art-warm{opacity:0.14; stroke:var(--seat-3-ink);}
.card[data-week]{display:grid; gap:var(--space-4); grid-template-columns:auto 1fr;}
[data-week] h3{margin:0;}
.week-strip{grid-column:1/-1; grid-row:2;}
.week-legend{align-items:center; grid-column:2; grid-row:1; justify-self:end; margin-top:0;}
.week-day{align-content:start;}
.week-day[data-count="0"] .week-track{background:#0000;}

/* Give facts the available width before adding another vertical row. */
.home-work-row, .home-feed-row{grid-template-columns:repeat(2, var(--track));}
#home-orders .order{gap:var(--space-2) var(--space-4); grid-template-columns:var(--track) var(--track);}
#home-orders .order > .order-title{grid-column:1/-1; padding-right:var(--space-8);}
#home-orders .order > .badge{grid-column:2; justify-self:end;}
#home-orders .order > .lead-seat{grid-column:1; grid-row:2;}
#home-orders .order > .order-step-summary{grid-column:2; grid-row:2;}
[data-view=home] .results-file{grid-template-columns:var(--track) auto;}
[data-view=home] .results-file > .mono{grid-column:1;}
[data-view=home] .results-file > .who{grid-column:1;}
.home-file{gap:var(--space-1) var(--space-2); grid-template-columns:var(--track) auto;}
.home-file > code{grid-column:1; grid-row:1; justify-self:start;}
.home-file > .seat-chip{grid-column:2; grid-row:1; justify-self:end;}
.home-file > [data-order-link]{grid-column:1; grid-row:2;}
.home-file > time{grid-column:2; grid-row:2;}
.home-seat{grid-template-rows:auto auto auto auto;}
.home-seat .seat-summary > div{background:#0000; padding:0;}
.home-seat .seat-spark{height:var(--space-8);}

#home-orders .order > .order-title{font-size:var(--text-md); grid-row:1;}
[data-view=home] .results-file{grid-template-columns:var(--track) 96px 96px;}
[data-view=home] .results-file > .mono{grid-column:1; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}
[data-view=home] .results-file > .result-author{grid-column:2;}
[data-view=home] .results-file > .hint{grid-column:3;}
.feed-filters button{padding:var(--space-1) var(--space-2);}
.home-file{align-items:center; gap:var(--space-2); grid-template-columns:80px 88px var(--track) 56px;}
.home-file > code{grid-column:1;}
.home-file > .seat-chip{grid-column:2; justify-self:start;}
.home-file > [data-order-link]{grid-column:3; grid-row:1;}
.home-file > time{grid-column:4; grid-row:1;}

.home-overview [data-chart]{display:grid; column-gap:var(--space-2); grid-template-columns:auto 1fr;}
.home-overview [data-chart] > h3{grid-column:1; margin:0;}
.home-overview [data-chart] .chart-counts{gap:var(--space-2); grid-column:2; grid-row:1; justify-content:end; margin:0;}
.home-overview [data-chart] .chart-counts > span{gap:var(--space-1);}
.home-overview [data-chart] > :is(.drawing-caption, .run-chart){grid-column:1/-1;}
.home-overview [data-chart] .drawing-caption{margin:var(--space-2) 0;}
[data-view=home] .home-overview .run-chart{height:128px;}
.home-overview [data-run-meter]{display:grid; gap:var(--space-2) var(--space-4); grid-template-columns:96px var(--track);}
.home-overview [data-run-meter] > h3{grid-column:1/-1; margin:0;}
.home-overview [data-run-meter] > svg{grid-row:2 / 5; height:112px; width:96px;}
.home-overview [data-meter]{grid-column:2; margin:0;}
.home-overview [data-meter] .meter-label{flex-wrap:wrap; gap:0 var(--space-2);}
.home-compose-row #compose-form{grid-template-columns:repeat(6, var(--track));}
.home-compose-row #compose-form > label:first-child{grid-column:span 2;}
.home-compose-row #compose-form > label:nth-child(2){grid-column:span 4;}
.home-compose-row #compose-form > #compose-lead{grid-column:span 4;}
.home-compose-row #compose-form > .actions{grid-column:span 2; justify-content:end;}
[data-view=home] .hero{padding-top:var(--space-6);}
.hero .stats{margin-top:var(--space-6);}
.top{margin-bottom:var(--space-4);}
.home-seat .seat-band{padding-bottom:0;}
.home-seat .seat-model{margin-top:0;}
.home-seat .seat-spark{margin:0 0 var(--space-2);}
.home-overview [data-week]{padding:var(--space-4);}
.home-overview .week-legend{gap:var(--space-1);}
.home-overview .week-day{padding:var(--space-2);}

#compose-goal{min-height:64px;}
.feed-filters .seat-chip{padding-right:0;}
.home-seat .seat-summary{grid-template-columns:repeat(2, var(--track));}
.home-seat .seat-summary > div{align-items:baseline; display:flex; gap:var(--space-2);}
.home-seat .seat-summary strong{flex:0 0 auto;}
.workspace{padding-top:var(--space-4);}
.top{padding-bottom:var(--space-4);}
.foot{padding-top:var(--space-4);}
.home-file{grid-template-columns:72px 104px var(--track) 56px;}

.team-overview .org-tree{margin:0 auto; max-width:624px;}
.team-overview .card.usage-row{gap:var(--space-1) var(--space-2); padding:var(--space-2);}

/* Section spacing counts from the card edge, without adding its row margin. */
.home-row:has(+ .section-heading) > .card, .home-row:has(+ .section-heading) > div > .card:last-child, .home-row:has(+ .section-heading) > div > div:last-child > .card{margin-bottom:0;}
.home-overview [data-chart]{padding:var(--space-4);}
.home-feed-row{grid-template-columns:minmax(0px, 2fr) var(--track);}
.home-feed-row .home-file{grid-template-columns:var(--track) auto;}
.home-feed-row .home-file > .seat-chip{grid-column:2;}
.home-feed-row .home-file > [data-order-link]{grid-column:1; grid-row:2;}
.home-feed-row .home-file > time{grid-column:2; grid-row:2;}

.team-comparison{align-items:start; grid-template-columns:var(--track) minmax(0, .65fr) minmax(0, 1.65fr);}
.team-comparison .levels-body{grid-template-columns:96px var(--track);}
.team-comparison .level-steps{width:96px;}
.team-comparison .level-row{gap:0 var(--space-1); grid-template-columns:1fr 1fr;}
.team-comparison .level-row strong{font-size:var(--text-xs);}
.team-comparison .card{padding:var(--space-4);}
.team-comparison .seat-reference-list > div{flex-wrap:wrap; gap:var(--space-1);}

.team-comparison{grid-template-columns:minmax(0, 1.2fr) minmax(0, .65fr) minmax(0, 1.55fr);}
.team-overview .card.usage-row{grid-template-columns:28px var(--track) auto;}
.team-overview .usage-row > .logo{grid-row:1 / 3;}
.team-overview .usage-model > strong{font-size:var(--text-xs);}
.team-overview .usage-model > p{grid-column:2;}
.team-overview .usage-row > [data-usage-launches]{grid-column:3;}
.team-overview .usage-row > [data-usage-seconds]{grid-column:3;}

/* Sparse views keep their content close and share width. */
.library-grid{grid-template-columns:repeat(3, var(--track));}
[data-efficiency]{align-items:start; display:grid; gap:var(--space-4); grid-template-columns:var(--track) minmax(0, 1.15fr);}
[data-efficiency] > :is(h3, p, .empty){grid-column:1/-1; margin:0;}
[data-eff-chart]{margin:0; width:100%;}
[data-efficiency] .eff-table{margin:0;}
.board{align-items:start; grid-template-columns:var(--track) var(--track) minmax(0, 1.6fr) var(--track);}
.board-column{min-height:0;}
.board .order{grid-template-columns:var(--track) auto;}
.board .order > .order-title{grid-column:1/-1;}
.board .order > .badge{grid-column:2; grid-row:2;}
.board .order > .lead-seat{grid-column:1; grid-row:2;}
.board .order > .order-step-summary{grid-column:1/-1;}
.day-cell{gap:var(--space-2); min-height:64px; padding:var(--space-3);}

.card.work-stat{border-radius:var(--round-control); box-shadow:var(--lift-1); margin:0; padding:var(--space-1) var(--space-2);}
.card.home-entry{margin:0; padding:var(--space-3);}
.home-feed-row .home-file{gap:var(--space-1) var(--space-2); padding:var(--space-1) 0;}
.home-feed-row .home-file .seat-icon{height:28px; width:28px;}
.team-overview .usage-model > strong{grid-column:2;}
.team-overview .usage-row > [data-usage-seconds]{grid-column:3; grid-row:1;}
.team-overview .usage-track{grid-column:2 / -1; grid-row:3;}
[data-view=team] .seat .seat-model{margin-top:0;}
[data-view=team] .seat .seat-spark{margin-top:0;}
[data-team-stats] .stat > [data-card-icon]{margin-bottom:0;}
.board .order > .badge{align-self:start;}
.order-facts-row{align-items:start; display:grid; gap:var(--space-4); grid-template-columns:repeat(2, var(--track));}
.order-facts-row .suborders{grid-template-columns:1fr;}
.order-execution{align-items:start; display:grid; gap:var(--space-4); grid-template-columns:var(--track) minmax(0, 1.25fr);}
.order-execution > :is([data-timeline], p){grid-column:1/-1;}
.order-execution .launch-cards{grid-template-columns:1fr; margin:0;}
.order-library-row{display:grid; gap:var(--space-6); grid-template-columns:repeat(2, var(--track));}
.order-library-row > [data-order-proposed]{margin-top:0;}

.shortcut-list{display:grid; gap:var(--space-4); grid-template-columns:120px var(--track) 120px var(--track); margin:var(--space-4) 0 0;}
.shortcut-list dd{margin:0;}
kbd{background:var(--well); border-radius:var(--round-chip); box-shadow:var(--lift-1); color:var(--ink-2); display:inline-block; font:var(--text-sm)/var(--leading-md) var(--mono); min-width:var(--space-6); padding:0 var(--space-1); text-align:center;}

[data-view=team] > section.card:last-child{margin-bottom:0;}
.full-seat-panel .seat-full-columns{margin-bottom:var(--space-2);}

[data-view=order] .files{gap:var(--space-6); grid-template-columns:repeat(2, var(--track));}
[data-view=order] .file{align-content:start;}

.duration-wash{fill:var(--well); stroke:none;}
[data-dim] .duration-wash{opacity:1 !important;}
.gantt-duration{background:var(--well); border-radius:var(--round-chip);}

/* Content groups own their surfaces; the links remain full-size controls. */
.card:is(.order-box, .home-entry-box, .week-cell){border-radius:var(--round-control); box-shadow:var(--lift-1); margin:0; padding:0;}
.order-box > .order, .home-entry-box > .home-entry{background:#0000; border:0; border-radius:inherit; box-shadow:none; height:100%;}
.card.order-box:has(> a):hover, .card.home-entry-box:has(> a):hover{box-shadow:var(--lift-3);}
.week-cell{align-self:start; min-width:0;}
.week-cell > .week-day{height:100%;}
.home-feed-row .home-file{background:var(--well); border:0; border-radius:var(--round-control); margin-top:var(--space-2); min-height:64px; padding:var(--space-2);}
[data-team-stats]{gap:var(--space-2);}
.handoff-card{margin-left:0; margin-right:0;}
.full-seat-panel .work-stat{min-width:160px; min-height:60px;}

/* Make room for distinct rows without shrinking the canvas or its timeline. */
.home-row > .card, .home-row > div > .card, .home-compose-row > .card, [data-view=home] > section.card{padding:var(--space-4);}
.home-overview > div > div > .card{padding:var(--space-4);}
.hero .card.stat{padding:var(--space-3);}
.hero .stats{margin-top:var(--space-4);}
[data-view=home] .hero{padding-top:var(--space-4);}
#home-orders .order{padding:var(--space-3);}
[data-view=team] .full-seat-panel{padding:var(--space-4);}
[data-view=team] .seat{gap:var(--space-2);}
[data-view=team] .seat .seat-summary{grid-template-columns:repeat(2, minmax(0,1fr));}
[data-view=team] .seat .seat-summary > div{align-items:baseline; background:#0000; display:flex; gap:var(--space-2);}
[data-view=team] .seat-summary strong{flex:0 0 auto;}
.card.handoff-card{gap:var(--space-2); padding-top:var(--space-3); padding-bottom:var(--space-3);}
[data-view=team] > section.card{padding:var(--space-4);}
.full-seat-panel .show-all{margin-top:var(--space-2);}

.home-feed-row{grid-template-columns:repeat(2, var(--track));}
[data-home-files]{align-content:start; display:grid; gap:var(--space-2); grid-template-columns:repeat(2, var(--track));}
[data-home-files] > :is(h3, .empty){grid-column:1/-1;}
.home-feed-row .home-file{margin:0;}
[data-home-files] .home-file{gap:var(--space-1); grid-template-columns:minmax(0,1fr);}
[data-home-files] .home-file > code, [data-home-files] .home-file > .seat-chip, [data-home-files] .home-file > [data-order-link], [data-home-files] .home-file > time{grid-column:1; grid-row:auto;}
[data-home-files] .home-file > .seat-chip{justify-self:start;}
.team-overview > .card, .card[data-handoff]{padding:var(--space-4);}
.handoff-cards{gap:var(--space-2);}
.seat-full-stats{padding-top:var(--space-1); padding-bottom:var(--space-1);}
[data-seat-talk] > h3, [data-seat-runs] > h3{margin-bottom:var(--space-2);}
[data-seat-compose]{padding-top:var(--space-2);}
[data-seat-compose] textarea{min-height:48px;}

[data-run-tiles]{border-radius:var(--round-hero);}
[data-team-stats] .stat{align-content:start; display:grid; gap:var(--space-1) var(--space-2); grid-template-columns:28px minmax(0,1fr);}
[data-team-stats] .stat > [data-card-icon]{grid-column:1; grid-row:1;}
[data-team-stats] .stat > .stat-label{align-self:center; grid-column:2; grid-row:1;}
[data-team-stats] .stat > :is(strong, [data-stat-note]){grid-column:1/-1;}

/* Balanced overview: the reporting tree and model summaries share a baseline. */
.team-overview{align-items:stretch;}
.team-overview > [data-usage]{display:grid; gap:var(--space-2); grid-template-rows:auto auto; grid-auto-rows:1fr;}
.team-overview > [data-usage] > :is(h3, .drawing-caption){margin:0;}
.team-overview .card.usage-row{align-content:center; gap:var(--space-2); margin:0; padding:var(--space-4);}

/* One shared time track per seat, with a separate baseline for duration labels. */
.gantt-row, .gantt-track{height:48px;}
[data-gantt-bar]{min-width:10px;}
.gantt-duration{top:28px;}

/* Inspector columns share heading, context and content rows. */
.seat-full-stats{display:grid; gap:var(--space-4); grid-template-columns:repeat(4, var(--track));}
.seat-full-columns{gap:var(--space-2) var(--space-4); grid-template-rows:auto auto 1fr;}
[data-seat-talk], [data-seat-runs]{display:grid; grid-row:span 3; grid-template-rows:subgrid;}
.seat-run-caption{align-self:center; margin:0;}
.seat-full-columns .list-window{margin-top:0;}
[data-seat-talk] .feed-filters{margin:0;}
.team-comparison{align-items:stretch;}
.team-seat-overview{display:flex; flex-direction:column;}
.team-seat-overview .seat-reference-list{flex:1 1 0%; gap:var(--space-2); grid-auto-rows:1fr;}
.team-seat-overview .seat-reference-list > div{align-content:center; background:var(--well); border-radius:var(--round-control); padding:var(--space-2);}
.team-seat-overview .seat-reference-list > div > .hint{width:100%;}

.team-comparison{grid-template-columns:minmax(0, 1.1fr) minmax(0, .9fr) minmax(0, 1.4fr);}
.team-seat-overview .seat-reference-list > div{display:grid; gap:var(--space-2) var(--space-1); grid-template-columns:var(--track) auto;}
.team-seat-overview .seat-reference-list > div > .hint{grid-column:1/-1;}
.team-comparison .levels-body{align-self:center;}
/* The same seat summaries remain legible in order details. */
[data-view=order] .seat-summary{grid-template-columns:repeat(2, var(--track));}
[data-view=order] .seat-summary > div{align-items:baseline; background:#0000; display:flex; gap:var(--space-2); padding:0;}
[data-view=order] .seat-summary strong{flex:0 0 auto;}
.order-facts-row{align-items:stretch;}
.order-execution{align-items:stretch;}
.order-execution > .scroll{align-items:center; background:var(--well); border-radius:var(--round-control); display:flex; padding:var(--space-2) var(--space-4);}
.order-execution [data-flow]{height:auto; width:100%;}
.order-execution .flow-box{fill:var(--paper);}

/* Other views use the same headers, stat tiles and quiet inset surfaces. */
.view-stats{grid-template-columns:repeat(3, var(--track));}
#swarm-stats{grid-template-columns:repeat(4, var(--track));}
.view-stats .stat, #day-stats .stat{align-items:center; display:grid; gap:var(--space-2) var(--space-4); grid-template-columns:28px var(--track) auto;}
.view-stats .stat > [data-card-icon], #day-stats .stat > [data-card-icon]{margin:0;}
.view-stats .stat > strong, #day-stats .stat > strong{grid-column:3; grid-row:1 / 3; margin:0;}
.view-stats .stat > [data-stat-note], #day-stats .stat > [data-stat-note]{grid-column:2;}
.calendar-card > h3{border-bottom:solid 1px var(--line); margin:0; padding:var(--space-4) var(--space-6);}
#day-orders .order{grid-template-columns:var(--track) auto;}
#day-orders .order > .badge{grid-column:2; grid-row:1;}
#day-orders .order > :is(.lead-seat, .order-step-summary){grid-column:1/-1;}
.board-column h3{justify-content:start;}
.board-column h3 > span:last-child{margin-left:auto;}
.board .order{background:var(--paper);}
.board .order > .order-title{padding-right:0;}
.board .order > .badge{grid-column:1/-1; grid-row:2; justify-self:start;}
.board .order > .lead-seat{grid-column:1/-1; grid-row:3;}
.file-column-head, [data-view=files] .file{align-items:center; display:grid; gap:var(--space-4); grid-template-columns:minmax(0, 1.4fr) 0 var(--track) 120px 120px;}
.file-column-head{color:var(--ink-3); font-size:var(--text-xs); padding:0 var(--space-4) var(--space-2);}
[data-view=files] .file{background:var(--well); border:0; border-radius:var(--round-control); padding:var(--space-4);}
[data-view=files] .file > :is(.link, [data-order-link]){justify-self:start; max-width:100%; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}
[data-view=files] .file > .badge{justify-self:start;}
.ledger li{gap:var(--space-4); grid-template-columns:32px 72px 152px var(--track); padding:var(--space-2) 0;}
.ledger .kind{align-self:start; background:var(--well); border-radius:var(--round-chip); justify-self:start; padding:0 var(--space-2);}
.ledger li:has(> .empty){display:block;}
.help-steps{display:grid; gap:var(--space-4) var(--space-8); grid-template-columns:repeat(2, var(--track)); max-width:none;}
.help-steps li{padding:var(--space-2);}
#examples > .card{border-radius:var(--round-card); display:flex; flex-direction:column; gap:var(--space-4);}
#examples > .card > :is(h3, p){margin:0;}
#examples > .card > button{margin-top:auto;}

.card.board-column{background:var(--paper); box-shadow:var(--lift-2);}
#examples > .card{padding:var(--space-6);}

.home-row:has(#home-library), .home-feed-row{align-items:stretch;}
#home-library, #home-files{display:flex; min-width:0;}
#home-library > .card, #home-files > .card{flex:1 1 0%;}
[data-home-files] > .drawing-caption{grid-column:1/-1; margin:0 0 var(--space-2);}
[data-home-files] > h3{margin-bottom:0;}

/* Empty runs keep the same drawings without stretching adjacent cards. */
.team-overview > [data-usage]:has(> .empty){align-content:start; grid-auto-rows:auto;}
.team-overview [data-usage]:has(> .empty) .usage-row{padding:var(--space-2);}
.team-overview [data-usage] > .empty{padding:var(--space-2) 0;}
[data-efficiency]:has(> .empty) > .empty{align-self:center; grid-column:1; grid-row:3 / 5;}
[data-efficiency]:has(> .empty) > [data-eff-chart]{grid-column:2; grid-row:3; height:auto;}
[data-efficiency]:has(> .empty) > .eff-table{grid-column:2; grid-row:4;}

/* A compact reading sequence: launches together, then their shared order flow. */
.order-execution{grid-template-columns:var(--track);}
.order-execution .launch-cards{grid-template-columns:repeat(3, var(--track));}
.order-execution .launch-card:last-child:nth-child(odd){grid-column:auto;}
.order-execution > .scroll{justify-content:center;}

[data-view=order] .page-head > div{display:grid; gap:var(--space-2) var(--space-6); grid-template-columns:minmax(240px, 1fr) auto;}
[data-view=order] .page-head :is(.eyebrow, h2){grid-column:1/-1; margin:0;}
[data-view=order] .page-head [data-progress]{margin:0;}
[data-order-metrics]{align-items:center; gap:var(--space-4); margin:0;}
[data-order-metrics] :is(strong, [data-metric]){color:var(--ink-3); font-size:var(--text-xs); font-weight:normal; line-height:var(--leading-sm);}

/* The overview uses the same compact value/label hierarchy as other stat rows. */
[data-run-tiles] .run-tile{align-items:center; gap:var(--space-2); grid-template-columns:20px var(--track);}
[data-run-tiles] .run-tile strong{grid-column:2; grid-row:1 / 3; justify-self:end;}
[data-run-tiles] .run-tile > .hint{grid-column:1/-1; grid-row:2; padding-right:var(--space-8);}
.order-facts-row .facts{gap:var(--space-2) var(--space-4); margin-bottom:0;}
.order-facts-row .suborders .order{gap:var(--space-2); padding:var(--space-3);}
[data-view=order] .seat{gap:var(--space-2);}
[data-view=order] .seat > p{margin:0;}
[data-view=order] .seat .seat-spark{margin:0;}
[data-view=order] .seat-summary{gap:var(--space-2) var(--space-4);}
[data-view=order] .seat-summary > div{display:block;}
[data-view=order] .seat-summary strong{display:inline; margin-right:var(--space-2);}
.order-execution .launch-card{align-content:start; display:grid; gap:var(--space-2);}
.order-execution .launch-card > *{margin:0;}
.order-execution .launch-stats{display:grid; gap:var(--space-2); grid-template-columns:repeat(3, var(--track));}
.order-execution [data-launch-stat] strong{display:block;}
[data-view=order] .files{gap:var(--space-2); grid-template-columns:var(--track);}
[data-view=order] .file{align-items:center; background:var(--well); border:0; border-radius:var(--round-control); display:grid; gap:var(--space-2); grid-template-columns:var(--track) 0 var(--track) 96px max-content auto; padding:var(--space-2) var(--space-4);}
[data-view=order] .file > :is(.link, [data-order-link]){max-width:100%; overflow:hidden; text-align:left; text-overflow:ellipsis; white-space:nowrap;}
[data-view=order] .file > .badge{justify-self:start;}
[data-view=order] .file-actions{flex-wrap:nowrap; width:auto;}
[data-view=order] .file-actions button{padding:var(--space-2);}
.order-library-row .empty{padding:0;}
[data-run-tiles]{align-items:center; display:grid; gap:var(--space-4); grid-template-columns:auto var(--track);}
[data-run-tiles] > :is(h3, .drawing-caption){margin:0;}
[data-run-tiles] .run-tiles, [data-run-tiles] > .empty{grid-column:1/-1;}
.order-execution > [data-timeline]{align-items:center; display:grid; gap:var(--space-4); grid-template-columns:auto var(--track);}
.order-execution > [data-timeline] > :is(h3, p){margin:0;}
.order-execution > [data-timeline] > :is(svg, .empty){grid-column:1/-1;}
.order-facts-row .order-step-summary{align-items:center; display:flex; gap:var(--space-4);}
.order-facts-row .order-step-summary > .step-track{flex:1 1 0%;}
.order-facts-row .order-step-caption{margin:0;}

/* Tiny charts show recorded splits or durations; unknown series have no drawing. */
.stat-chart{display:block; height:var(--space-4); margin-top:var(--space-2); overflow:visible; width:100%;}
[data-team-stats] .stat-chart{align-self:end; grid-column:1/-1; margin:0;}
[data-team-stats] .stat-series{height:var(--space-6);}
.stat-segment{fill:var(--ink-3); stroke:var(--paper); stroke-width:2; vector-effect:non-scaling-stroke;}
.stat-segment[data-tone=running]{fill:var(--run);}
.stat-segment[data-tone=done]{fill:var(--ok);}
.stat-segment[data-tone=failed]{fill:var(--bad);}
.stat-series-line{fill:none; stroke:var(--time); stroke-width:1.5; vector-effect:non-scaling-stroke;}
.stat-series-point{fill:var(--time); stroke:var(--paper); stroke-width:1; vector-effect:non-scaling-stroke;}
.hero .stat{display:flex; flex-direction:column;}
.hero .stat > .stat-chart{margin-top:auto;}
.hero .stat > [data-stat-note]{margin-bottom:var(--space-2);}
.week-track{background:#0000; gap:var(--space-1); height:auto;}
.week-track > [data-week-state]{background:#0000; display:flex; flex-wrap:wrap; gap:var(--space-1); height:auto;}
.order-dot{display:inline-block; flex:0 0 auto; height:var(--space-3); overflow:visible; vertical-align:middle; width:var(--space-3);}
.flow-dot[data-state=CANCELLED]{fill:var(--bad);}
.flow-dot[data-state=due]{fill:var(--attention);}

/* Completed area is measured against the rail, with segment dividers above it. */
.step-track{background:var(--well); border-radius:var(--round-pill); gap:0; position:relative;}
.step-track > .step-fill{background:var(--run); flex:0 0 auto; inset:0 auto 0 0; position:absolute;}
[data-progress] .step-track > [data-order-step]{background:#0000; border-radius:0; border-right:4px solid var(--paper); position:relative;}
.step-track > [data-order-step]:last-child{border-right:0;}
.order-facts-row .order-step-summary{display:block;}
.order-facts-row .order-step-caption{justify-content:space-between;}

.seat-launch-strip{height:auto; margin-bottom:var(--space-2) !important;}
.seat-launch-strip .spark-bar{opacity:1;}
.flow-legend{color:var(--ink-2); display:inline-flex; font-size:var(--text-xs); gap:var(--space-2);}
.flow-legend > span{align-items:center; background:var(--well); border-radius:var(--round-pill); display:inline-flex; gap:var(--space-2); padding:var(--space-1) var(--space-2);}
.flow-legend path{fill:none; stroke:var(--edge); stroke-width:1.5;}
.flow-legend .waits-for{stroke-dasharray:4 3;}
.not-recorded{color:var(--ink-3);}

.board-column > h3{border-bottom:2px solid var(--wait); padding-bottom:var(--space-4);}
.board-column[data-column=running] > h3{border-color:var(--run);}
.board-column[data-column=done] > h3{border-color:var(--ok);}
.board-column[data-column=failed] > h3{border-color:var(--bad);}
.column-count{background:var(--well); border-radius:var(--round-pill); font-size:var(--text-sm); padding:0 var(--space-2);}
.order-title > .order-dot{margin-right:var(--space-2);}
.summary-groups{display:grid; gap:var(--space-4); grid-template-columns:repeat(auto-fit, minmax(144px, 1fr));}
.summary-group{background:var(--well); border-radius:var(--round-control); min-width:0; padding:var(--space-4);}
.summary-group-head{align-items:center; color:var(--ink-2); display:flex; font-size:var(--text-sm); gap:var(--space-2); justify-content:space-between;}
.summary-group-head strong{color:var(--ink); font-size:var(--text-xl);}
.summary-rail{background:var(--line); border-radius:var(--round-pill); height:var(--space-1); margin-top:var(--space-4);}
.summary-rail > span{background:var(--accent); border-radius:inherit; display:block; height:100%;}
.file-column-head, [data-view=files] .file{grid-template-columns:minmax(0, 1.3fr) 112px var(--track) 96px 112px;}
.file-order{align-items:center; display:flex; gap:var(--space-2); min-width:0;}
.file-order > a{overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}

.ledger-groups{align-items:start; display:grid; gap:var(--space-4); grid-template-columns:repeat(2, var(--track));}
.ledger-groups > .ledger-group{background:var(--well); border:0; border-radius:var(--round-control); display:block; min-width:0; padding:var(--space-4);}
.ledger-group-head{align-items:center; display:flex; flex-wrap:wrap; gap:var(--space-2); margin-bottom:var(--space-4);}
.ledger-group-head > h4{flex:1 1 0%; font-size:var(--text-md); font-weight:var(--weight-heading); margin:0; min-width:160px;}
.ledger-group-head > h4 > a{display:block; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}
.ledger-group-head > .hint{margin-left:auto;}
.ledger-group .ledger{display:grid; gap:var(--space-2);}
.ledger-group [data-ledger-row]{background:var(--paper); border:0; border-radius:var(--round-control); gap:var(--space-2); grid-template-columns:24px 72px var(--track); padding:var(--space-2);}
.ledger-group .what{grid-column:1/-1;}

.library-source{align-items:baseline; display:flex; flex-wrap:wrap; gap:var(--space-1);}
.library-source > .order-dot{align-self:center;}
.eff-table{border-collapse:separate; border-spacing:0 var(--space-2);}
.eff-table td{background:var(--well); border:0; padding:var(--space-2);}
.eff-table td:first-child{border-radius:var(--round-control) 0 0 var(--round-control);}
.eff-table td:last-child{border-radius:0 var(--round-control) var(--round-control) 0;}
.calendar-layout{align-items:start; display:grid; gap:var(--space-4); grid-template-columns:minmax(0, 2.6fr) minmax(264px, 1fr);}
.calendar-layout .calendar-card{margin:0;}
.calendar-layout [data-weekday]{font-size:var(--text-xs); padding:var(--space-3) var(--space-1); text-align:center;}
#calendar-agenda > .card{padding:var(--space-4);}
.month-agenda{display:grid; gap:var(--space-4);}
.agenda-order{background:var(--well); border-radius:var(--round-control); display:grid; gap:var(--space-2); min-width:0; padding:var(--space-4);}
.agenda-title{align-items:baseline; display:flex; font-weight:var(--weight-heading); gap:var(--space-2);}
.agenda-title > .order-dot{flex:0 0 auto;}
.agenda-order .actions{font-size:var(--text-xs); gap:var(--space-2);}
.agenda-order .lead-seat{margin:0;}
.agenda-order .lead-details{min-width:0;}
.agenda-order .model{word-wrap:anywhere;}
.help-steps{gap:var(--space-4); list-style-position:inside; padding:0;}
.help-steps li{background:var(--well); border-radius:var(--round-control); padding:var(--space-4);}
#help-context .order{display:grid; grid-template-columns:var(--track) auto; margin:0;}
#help-context .order > .order-step-summary{grid-column:2; grid-row:2; min-width:240px;}
#day-plans .empty{padding:var(--space-2) 0;}

.ledger-group-head > h4{flex:1 0 calc(100% - 24px);}

#calendar-legend{margin-top:var(--space-4);}

.ledger-group[data-ledger-group=setup] .ledger-group-head > h4{flex:1 1 0%;}

/* Live receipts and work states share the existing surface and motion system. */
.toast{display:grid; gap:var(--space-2) var(--space-4); grid-template-columns:var(--track) auto; max-width:448px;}
.toast > span{grid-column:1/-1;}
.toast > a{align-self:center;}
.toast > button{justify-self:end;}
.seat-segment{fill:var(--well);}
.seat-segment[data-working=true]{fill:var(--run);}
[data-busy=true] .seat-head .seat-icon,
[data-canvas-node]:has(.badge[data-state=running]) > .work-icon,
[data-canvas-item]:has(.dot[data-status=running]) .seat-icon{border-radius:var(--round-chip); outline:solid 2px var(--accent); outline-offset:2px;}

/* Reserve changing text rows so live polls do not move the next section. */
:is([data-view=home], [data-view=team]) .seat-now{min-height:40px;}
.handoff-card > [data-order-link]{min-height:40px;}
[data-view=home] .section-heading{margin-top:var(--space-4);}
.home-work-row{min-height:480px;}
#home-orders{max-height:336px; overflow-y:auto; overflow-anchor:none; padding:var(--space-1);}
.home-library-grid{min-height:124px;}
[data-canvas-panel]{min-height:232px;}
.canvas-tab-content{min-height:0;}
[data-seat-talk] .feed-filters{align-content:start; min-height:72px;}
#feed-filters{align-content:start; min-height:84px;}
[data-activity]{min-height:240px; overflow-anchor:none;}
[data-list-window], .canvas-tab-content, .seat-messages{overflow-anchor:none;}
[data-motion=on] [data-live-enter]{animation:bar-in var(--motion) ease-out;}
/* Row boxes use the same elevation and focus treatment. Only links use a pointer. */
:is(.order, .file, .home-file, [data-ledger-row], .seat, .home-seat, .week-day, .day-cell){cursor:default; transition:color var(--motion) var(--ease), background-color var(--motion) var(--ease), box-shadow var(--motion) var(--ease);}
:is(.order, .file, .home-file, [data-ledger-row], .seat, .home-seat, .week-day, .day-cell):hover{box-shadow:var(--lift-1); transform:none;}
a:is(.order, .week-day, .day-cell), :is(.order, .file, .home-file, [data-ledger-row], .seat, .home-seat) a{cursor:pointer;}
:is(.order, .file, .home-file, [data-ledger-row], .seat, .home-seat, .week-day, .day-cell):focus-visible,
:is(.order, .file, .home-file, [data-ledger-row], .seat, .home-seat, .week-day, .day-cell):focus-within{outline:solid 2px var(--accent); outline-offset:var(--space-1) !important;}
[data-home-library]{min-height:208px;}

[data-seat-open]{border-radius:var(--round-chip); cursor:default; transition:box-shadow var(--motion) var(--ease), background-color var(--motion) var(--ease);}
[data-seat-open]:hover{background:var(--accent-wash); box-shadow:var(--lift-1);}
[data-seat-open]:focus-visible{outline:solid 2px var(--accent); outline-offset:var(--space-1);}
.seat-drawer{max-height:calc(100vh - 64px); width:560px;}
.seat-drawer h3{margin:0;}
#seat-drawer-content{overflow:auto; padding:var(--space-6);}
#seat-drawer-content .seat-launch{background:var(--well); border-radius:var(--round-control); display:grid; gap:var(--space-2); grid-template-columns:minmax(0,1fr) auto; margin-bottom:var(--space-4); padding:var(--space-4);}
#seat-drawer-content .seat-launch > p{grid-column:1/-1;}
#home-newest-files{font-size:var(--text-xs); white-space:nowrap;}
#home-orders[data-expanded]{max-height:none;}
[data-order-files]{scroll-margin-top:112px;}

.handoff-card > [data-order-link]{-webkit-line-clamp:2; -webkit-box-orient:vertical; display:-webkit-box; height:40px; overflow:hidden;}
:root body :is(.order, .file, .home-file, [data-ledger-row], .seat, .home-seat, .week-day, .day-cell):hover,
:root body .card.order-box:hover{box-shadow:var(--lift-1) !important; transform:none !important;}
button{cursor:default;}
#run-activity[data-work-state=done]{background:var(--ok-wash); color:var(--ok);}
#run-activity[data-work-state=failed]{background:var(--bad-wash); color:var(--bad);}
.seat-drawer .preview-head{top:0; position:sticky; z-index:1;}
/* Empty and live content occupy the same slots before the first hand-in. */
.home-overview [data-chart]:has([data-empty-plot]) > .empty{grid-column:1/-1; grid-row:3; min-height:128px; padding:0 0 var(--space-8);}
.home-overview [data-chart] .run-chart[data-empty-plot]{align-self:end; grid-column:1/-1; grid-row:3; height:var(--space-8);}
.home-overview [data-week]{min-height:176px;}
.handoff-direction{align-content:start; min-height:64px;}
.card[data-handoff]{min-height:408px;}
.canvas-tab-content[data-canvas-content=timeline]{min-height:180px;}
.seat-full-columns{grid-template-rows:auto 72px 236px;}
[data-view=order] [data-order-files]{padding:var(--space-4);}

.hero .stat{min-height:144px;}
.results-latest{display:grid; gap:0 var(--space-2); grid-template-columns:auto minmax(0,1fr); min-height:40px;}
.results-latest > [data-order-link]{overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}
.results-latest > time{margin:0;}

/* Only backend arrivals receive a live entrance, never a filter or tab redraw. */
[data-motion=on] [data-live-enter=file]{animation-duration:150ms;}

/* Compact content slots retain every row and reserve space for live updates. */
.home-library-grid{gap:var(--space-2); grid-template-columns:repeat(3, var(--track)); min-height:176px;}
.home-entry-box > .home-entry{gap:var(--space-1) var(--space-2); grid-template-columns:auto var(--track); padding:var(--space-2);}
.home-entry > .kind-chip{grid-column:1; grid-row:1;}
.home-entry > strong{grid-column:1/-1; grid-row:2; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}
.home-entry > .hint{align-self:center; grid-column:2; grid-row:1; text-align:right;}
[data-canvas-panel]{min-height:200px;}
.canvas-tab-content[data-canvas-content=timeline]{min-height:148px;}
.full-seat-panel.card{padding:var(--space-4);}
.seat-full-columns{grid-template-rows:auto 48px 204px;}
[data-seat-talk] .feed-filters{min-height:48px;}
.card[data-handoff]{min-height:384px;}
.team-comparison > .card{padding:var(--space-4);}
[data-view=team] > section.card{padding:var(--space-4);}
[data-view=team] .seat{padding:var(--space-4);}

/* Every raised box draws from the same elevation scale, including nested wells. */
:root body :is(.card, .summary-group, .ledger-group, .home-file, .file, .seat-run, .seat-launch, .home-entry, .week-day, .day-cell, .seat-reference-list > div){box-shadow:var(--lift-1);}
:root body .card:not(.order-box):not(.home-entry-box):not(.week-cell):not(.stat):not(.work-stat):not(.seat):not(.home-seat):not(.handoff-card):not(.handoff-seat):not(.launch-card):not(.usage-row){box-shadow:var(--lift-2);}
.toast, .preview{box-shadow:var(--lift-3);}
#backend, #run-activity{box-shadow:var(--lift-1);}
[data-team-stats] .card.stat{padding:var(--space-2);}

#team-drawings > .card, #team-canvas-slot > .card, #team-seat-slot > .card,
.team-overview > .card, .team-comparison > .card, [data-view=team] > section.card{margin-bottom:var(--space-2);}
[data-team-stats] .stat > strong{font-size:var(--text-stat); line-height:var(--leading-lg); margin-top:0;}
[data-team-stats] [data-stat-note]{margin-top:0;}

/* The current step changes paint, never the flow node's geometry. */
[data-flow-node][data-flow-working] .flow-box{fill:var(--accent-wash); stroke:var(--accent); stroke-width:2; vector-effect:non-scaling-stroke;}
[data-flow-node][data-flow-waiting] .flow-box{fill:var(--well);}
[data-flow-node][data-flow-waiting] :is(.flow-title, .flow-state){fill:var(--ink-3);}
.launch-table tbody tr{height:56px;}
[data-launch-seconds]{font-variant-numeric:var(--number-style);}
.board{align-items:stretch;}
[data-motion=on] [data-board-move]{animation:bar-in 160ms ease-out;}

[data-team-stats]{margin-bottom:var(--space-2);}
[data-view=team] > section.card > h3{margin-bottom:var(--space-2);}
[data-view=team] > section.card > .hint{margin-top:0;}

.card.handoff-card{padding-top:var(--space-2); padding-bottom:var(--space-2);}
.card[data-handoff] > .drawing-caption{margin-top:0;}
/* First-run space follows the content; work-filled layouts keep their stable slots. */
.compose-examples{gap:var(--space-2); margin-bottom:var(--space-4);}
.compose-examples button{font-size:var(--text-xs); padding:var(--space-1) var(--space-3);}
[data-first-run=true] > #compose-heading{margin-top:var(--space-2);}
[data-first-run=true] .home-overview{margin-top:var(--space-6);}
[data-first-run=true] .home-work-row{min-height:0;}
[data-first-run=true] #feed-filters{min-height:0;}
[data-first-run=true] [data-activity]{min-height:0;}
[data-first-run=true] .home-feed-row{align-items:start;}
[data-first-run=true] [data-results]{min-height:0;}
.card:has(> .empty){min-height:0;}
.card > .empty{padding:var(--space-2) 0;}
[data-efficiency]:has(> .empty){display:block;}
.home-overview [data-chart] > .empty{grid-column:1/-1; padding:var(--space-2) 0;}
[data-handoff]:has(> .empty){min-height:0;}
[data-first-run=true] .home-feed-row .card{min-height:0;}
[data-first-run=true] [data-results] .empty, [data-first-run=true] [data-activity] .empty{padding:0;}
[data-first-run=true] [data-results] .results-summary{margin-bottom:0;}
[data-first-run=true] [data-results] > .hint{margin:0;}
[data-first-run=true] [data-activity] > li{margin:0; padding:0;}
.team-comparison:has([data-empty]){align-items:start;}
.seat-summary-block > .empty{gap:var(--space-2); min-height:96px; padding:0;}
.seat-summary-block > .empty .empty-art{height:96px; width:96px;}
.seat-summary-block > .empty strong, .seat-summary-block > .empty p{font-size:var(--text-xs); line-height:var(--leading-xs);}
[data-canvas-list] > .empty{display:block; padding:var(--space-2);}
/* Decisions use a small edge and status pill; the explanation stays readable ink. */
.order-problem{border-left:3px solid var(--attention); color:var(--ink); padding:var(--space-2) 0 var(--space-2) var(--space-3);}
.order-problem[data-needs-person=true]{border-left-color:var(--bad);}
.order-problem p{color:var(--ink); font-size:var(--text-xs); line-height:var(--leading-sm); margin:var(--space-2) 0;}
.order-problem .who{flex-wrap:wrap; font-size:var(--text-xs); gap:var(--space-2);}
.order-problem .badge{white-space:normal;}
.order-problem .problem-action{color:var(--accent); font-size:var(--text-xs);}
.page-head .order-problem{margin-top:var(--space-4); max-width:680px;}
#attention .order-problem{margin-top:var(--space-2);}
#launches[data-budget-used=true]{color:var(--attention);}
#notice[data-stale-banner=true]{background:var(--well); border-left:3px solid var(--attention); color:var(--ink-2);}
#board-stats{grid-template-columns:repeat(4,minmax(0,1fr));}
.board:not(:has(.order)){grid-template-columns:repeat(2,minmax(0,1fr));}
.board:not(:has(.order)) .empty{display:flex; gap:var(--space-4); min-height:96px; padding:var(--space-2) 0;}
.board:not(:has(.order)) .board-column{min-height:0;}
#files .empty{padding:var(--space-2) 0;}
.board:not(:has(.order)) .empty{align-items:center; flex-direction:row;}
[data-first-run=true] [data-results]{padding:var(--space-4);}
[data-first-run=true] .results-summary [data-progress]{margin-top:0; margin-bottom:0;}
.order > .order-problem{grid-column:1/-1;}
.order > .order-problem p{margin:var(--space-1) 0;}
[data-flow-attention] .flow-dot{fill:var(--attention);}
.home-work-row > .card, .home-work-row > #home-results > .card{padding:var(--space-4);}
#orders-more{margin-top:var(--space-2);}
#home-orders{max-height:320px;}
#attention li{padding:var(--space-2) 0;}
[data-first-run=true] .results-summary [data-progress]{flex-basis:auto;}
[data-canvas-list]:has(> .empty:not([data-empty-search])) [data-canvas-item]{padding:var(--space-1);}
[data-canvas-list]:has(> .empty:not([data-empty-search])) .group-heading{margin:var(--space-2) 0 var(--space-1);}
[data-canvas-list] > .empty{align-items:center; display:flex; flex-direction:row; gap:var(--space-2); padding:0;}
[data-canvas-list] > .empty > div{min-width:0;}
[data-canvas-list] .empty strong{font-size:var(--text-md);}
[data-canvas-list] .empty :is(p, a){font-size:var(--text-xs);}

/* Library decisions and reuse share the same quiet surfaces as orders. */
.nav-count{background:var(--attention-wash); border-radius:var(--round-pill); color:var(--attention); font-size:var(--text-xs); margin-left:auto; padding:0 var(--space-1);}
#compose-library{grid-column:1/-1;}
.library-available{align-items:center; display:flex; flex-wrap:wrap; gap:var(--space-2);}
.library-available .library-use{background:var(--well); font-size:var(--text-xs); max-width:360px; overflow:hidden; padding:var(--space-1) var(--space-2); text-overflow:ellipsis; white-space:nowrap;}
.order-used{color:var(--ink-3); display:flex; flex-wrap:wrap; font-size:var(--text-xs); gap:var(--space-1); grid-column:1/-1;}
.order-used > span{background:var(--well); border-radius:var(--round-chip); padding:0 var(--space-1);}
[data-keep-edit]{flex-basis:100%;}
[data-keep-edit] summary{color:var(--ink-3); font-size:var(--text-sm);}
[data-keep-edit] label{display:block; margin-top:var(--space-2);}
[data-keep-edit] input{width:100%;}
.home-overview [data-chart] .chart-counts{gap:var(--space-2); grid-column:1/-1; grid-row:auto; justify-content:space-between;}
.home-overview .chart-counts > span{align-items:flex-start; flex:1 1 0%; font-size:var(--text-xs);}
.home-overview .chart-counts svg{flex:0 0 16px;}
#hero-stats [data-state-count] .badge{font-size:var(--text-xs);}
#attention > li > p{margin:var(--space-1) 0;}
#attention .seat-chip{font-size:var(--text-xs);}
.attention-card .list-window{margin-top:var(--space-2);}
#feed-filters{min-height:56px;}
[data-activity]:not([data-expanded]){max-height:208px; min-height:208px;}
.home-compose-row #compose-form > #compose-library{grid-column:1 / 5; grid-row:3;}
.home-compose-row #compose-form > .actions{align-self:center; grid-column:5 / 7; grid-row:2 / 4;}
.home-overview .chart-counts strong{font-size:var(--text-xs);}
.home-overview [data-chart] .run-chart{height:112px;}
.library-tools{align-items:end; display:flex; gap:var(--space-4); margin:var(--space-4) 0;}
.library-tools label{display:grid; flex:1 1 0%; gap:var(--space-2);}
.library-tools input, .library-tools select{width:100%;}
.library-filters{flex-wrap:wrap;}
.library-entry{display:flex; flex-direction:column; gap:var(--space-2); min-width:0;}
.library-entry h3, .library-entry p{margin:0;}
.library-entry h3{line-height:18pt;}
.library-entry h3 a{color:var(--ink);}
.library-tags{color:var(--ink-3); display:flex; flex-wrap:wrap; font-size:var(--text-xs); gap:var(--space-2);}
.library-tags span{background:var(--well); border-radius:var(--round-pill); padding:0 var(--space-2);}
.proposal-grid{grid-template-columns:repeat(2, var(--track));}
.proposal-body{display:grid; gap:var(--space-2); margin-top:var(--space-2);}
.proposal-body p{margin:0;}
.entry-diff{background:var(--well); border-radius:var(--round-control); font-size:var(--text-sm); padding:var(--space-2);}
.entry-diff > p{margin:0 0 var(--space-2);}
.diff-line{border-left:3px solid #0000; display:grid; grid-template-columns:20px var(--track); padding:var(--space-1) var(--space-2);}
.diff-line code{background:#0000; color:var(--ink); word-wrap:anywhere; padding:0; white-space:pre-wrap;}
.diff-line[data-diff-line=add]{background:var(--ok-wash); border-color:var(--ok);}
.diff-line[data-diff-line=remove]{background:var(--bad-wash); border-color:var(--bad);}
.diff-line[data-diff-line=add] > span{color:var(--ok);}
.diff-line[data-diff-line=remove] > span{color:var(--bad);}
.entry-diff summary{color:var(--ink-3); padding:var(--space-1) var(--space-2);}
.proposal-review{padding-top:var(--space-2);}
.proposal-review details{flex:1 1 0%;}
.proposal-review label{display:grid; gap:var(--space-2); margin-top:var(--space-2);}
[data-lib-detail] > section{margin-top:var(--space-6);}
.version-list{display:grid; gap:var(--space-2); list-style:none; padding:0;}
.version-list li{align-items:center; background:var(--well); border-radius:var(--round-control); display:flex; flex-wrap:wrap; font-size:var(--text-sm); gap:var(--space-2) var(--space-4); padding:var(--space-2);}
[data-version-chart]{display:block; height:176px; width:100%;}
.version-table{table-layout:fixed; width:100%;}
.version-table th:first-child{width:10%;}
.version-table th:nth-child(2){width:32%;}
[data-version-bar]{transition:opacity var(--motion) var(--ease);}
[data-version-bar]:hover{opacity:.8;}
[data-version-bar]:focus-visible{outline:solid 2px var(--accent); outline-offset:2px;}
.seat-full-columns{grid-template-rows:auto 48px 176px;}
[data-lib-detail] > h3{margin-top:var(--space-6);}
.version-compare{margin-top:var(--space-4);}
/* Leave room for longer titles without changing the canvas or losing rows. */
.home-work-row{min-height:432px;}
#home-orders:not([data-expanded]){max-height:272px;}
.nav-count[data-library-pending="0"]{background:var(--well); color:var(--ink-3);}
/* Read one complete attention item before choosing to expand the list. */
#attention[data-list-window]:has(> li:only-child){max-height:none;}
[data-view=home] > section.card:has(#home-team), .home-feed-row > .card, .home-feed-row #home-files > .card{padding:var(--space-4);}
.home-library-grid{min-height:144px;}
[data-first-run=true] [data-activity]:not([data-expanded]){min-height:0;}
.home-compose-row #compose-form{row-gap:var(--space-2);}
[data-view=home] .results-file{padding:var(--space-1) 0;}
[data-timeline-window]{width:100%;}
#order-detail > .card{padding:var(--space-4) var(--space-6);}
.order-library-row [data-order-proposed] > p{margin:var(--space-2) 0;}
[data-view=order] .file-actions:has([data-keep-edit][open]){align-items:end; display:grid; grid-column:1/-1; grid-template-columns:var(--track) auto auto;}
[data-view=order] [data-keep-edit][open]{display:grid; gap:0 var(--space-4); grid-template-columns:repeat(2, var(--track));}
[data-view=order] [data-keep-edit][open] > summary{grid-column:1/-1;}

/* Library shelf: current work, decisions, then the complete quieter record. */
.section-count{color:var(--ink-3); font-size:var(--text-sm); font-weight:normal; margin-left:var(--space-3);}
.version-chip{background:var(--well); border-radius:var(--round-chip); color:var(--ink-2); display:inline-flex; font-size:var(--text-xs); line-height:var(--leading-xs); padding:var(--space-1) var(--space-2);}
.shelf-entry.card{border-radius:var(--round-control); margin:0; padding:var(--space-4); transition:box-shadow var(--motion) var(--ease);}
:root body .shelf-entry.card{box-shadow:var(--lift-1);}
:root body .shelf-entry.card:hover{box-shadow:var(--lift-1);}
.shelf-entry .kind-chip{padding:var(--space-1) var(--space-2);}
.entry-path, .entry-sentence{color:var(--ink-3); display:block; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}
.shelf-source{border-top:solid 1px var(--line); display:grid; gap:var(--space-1); padding-top:var(--space-2);}
.usage-marks{display:flex; flex-wrap:wrap; gap:var(--space-1);}
.usage-mark{background:var(--run-wash); border-radius:var(--round-chip); color:var(--run); display:grid; font-size:var(--text-xs); height:var(--space-5); min-width:var(--space-5); place-items:center;}
.usage-mark[data-use-outcome=accepted]{background:var(--ok-wash); color:var(--ok);}
.usage-mark[data-use-outcome=failed]{background:var(--bad-wash); color:var(--bad);}
.usage-mark[data-use-outcome=returned]{background:var(--attention-wash); color:var(--attention);}
.library-history{border-top:solid 1px var(--line);}
.library-history-row{border-bottom:solid 1px var(--line); padding:var(--space-2) 0;}
.history-name, .history-record{align-items:center; display:flex; flex-wrap:wrap; gap:var(--space-2) var(--space-4);}
.history-name > a{color:var(--ink-2); font-weight:var(--weight-heading);}
.history-record{margin:var(--space-1) 0 0 var(--space-4);}
.history-record .badge{background:var(--well); box-shadow:none; color:var(--ink-3);}
.history-reason{max-width:360px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}
[data-library-section] > .empty{padding:var(--space-4);}
.proposal-card.card{border-radius:var(--round-card); margin:0; padding:var(--space-4);}
.proposal-card h3{line-height:18pt; margin:var(--space-2) 0;}
.proposal-card .proposal-body{gap:var(--space-2); margin:0;}
.proposal-card .proposal-why{-webkit-line-clamp:2; -webkit-box-orient:vertical; color:var(--ink-2); display:-webkit-box; font-size:var(--text-sm); overflow:hidden;}
.proposal-card .proposal-source{overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}
.proposal-card .proposal-source a{display:inline;}
.proposal-card .proposal-review{padding:0;}
.proposal-card .proposal-review .actions{gap:var(--space-2);}
.proposal-card .library-meta{gap:var(--space-2);}
.proposal-card .entry-diff{font-size:var(--text-xs);}
.diff-line{grid-template-columns:24px 24px 16px var(--track); padding:0 var(--space-1);}
.diff-number{color:var(--ink-3); font:var(--text-xs)/var(--leading-sm) var(--mono); padding-right:var(--space-1); text-align:right;}
#attention > li:has(.proposal-card){border:0; padding:0 0 var(--space-2);}
.proposal-card p{margin:0;}
.proposal-card .entry-diff > p{margin:0 0 var(--space-2);}
#attention .proposal-card .seat-chip{font-size:var(--text-sm);}
[data-motion=on] .proposal-card[data-proposal-phase=leaving]{animation:proposal-exit 150ms ease-out;}
@keyframes proposal-exit{ 0%{opacity:1; transform:translateY(0);} 100%{opacity:0; transform:translateY(-4px);} }

/* Entry pages share the order page's canvas, stat row and paired cards. */
.entry-header{align-items:start; margin-bottom:var(--space-4);}
.entry-header h2{margin-top:var(--space-2);}
.entry-actions{display:grid; flex:0 0 auto; gap:var(--space-2); grid-template-columns:auto auto;}
.entry-actions > a{font-size:var(--text-sm); grid-column:1/-1; justify-self:end;}
.entry-origin{align-items:center; display:flex; flex-wrap:wrap; gap:var(--space-2) var(--space-4); margin-bottom:var(--space-4);}
.entry-origin .entry-path{flex-basis:100%;}
.entry-stats{grid-template-columns:repeat(4, var(--track));}
.entry-columns{align-items:start; display:grid; gap:var(--space-4); grid-template-columns:minmax(0, 1.3fr) var(--track);}
[data-lib-detail] > section{margin-top:var(--space-4);}
.entry-detail > .proposal-card{margin-bottom:var(--space-4);}
.entry-text-card [data-lib-text]{background:var(--well); border-radius:var(--round-control); margin:0; max-height:520px; overflow:auto; padding:var(--space-4) var(--space-4) var(--space-4) var(--space-8);}
.text-line{position:relative;}
.text-line::before{color:var(--ink-3); content:attr(data-text-line); right:calc(100% + var(--space-4)); position:absolute; user-select:none;}
.entry-history .version-list{margin:0; padding-left:var(--space-4); position:relative;}
.entry-history .version-list::before{border-left:1px solid var(--line-2); content:""; left:3px; top:var(--space-2); bottom:var(--space-6); position:absolute; width:1px;}
.entry-history .version-list li{background:#0000; border-radius:0; display:grid; gap:var(--space-2); padding:0 0 var(--space-6) var(--space-2); position:relative;}
.entry-history .version-list li::before{background:var(--accent); border-radius:var(--round-pill); box-shadow:0 0 0 4px var(--paper); content:""; height:var(--space-2); left:-16px; top:6px; position:absolute; width:var(--space-2);}
.entry-history .version-list li > button{justify-self:start;}
.version-compare .library-tools{align-items:stretch; flex-direction:column; gap:var(--space-2);}
.version-compare select{appearance:none; box-shadow:var(--lift-1); padding-right:var(--space-8);}
.version-compare label{position:relative;}
.version-compare label::after{color:var(--ink-3); content:"⌄"; right:var(--space-3); bottom:10px; pointer-events:none; position:absolute;}
.version-outcome-layout{align-items:center; display:grid; gap:var(--space-6); grid-template-columns:minmax(0, .8fr) minmax(0, 1.2fr); margin-top:var(--space-4);}
[data-version-chart]{height:auto; max-width:400px; width:100%;}
.version-table{font-size:var(--text-xs);}
.version-table th:first-child{width:10%;}
.version-table th:nth-child(2){width:28%;}
.version-table th:nth-child(3){width:28%;}
.version-table :is(th, td){padding:var(--space-2) var(--space-1);}
.text-line::before{right:auto; left:-32px; text-align:right; white-space:nowrap; width:var(--space-6);}
.home-overview > div:first-child > #home-run-meter .card{margin-bottom:0;}
#attention[data-list-window]:not([data-expanded]){max-height:496px !important;}
.home-feed-row [data-activity]:not([data-expanded]){max-height:120px; min-height:120px;}
.home-feed-row [data-home-files]{grid-template-columns:repeat(2, var(--track));}
[data-library-section=history]{margin-bottom:var(--space-6);}

.home-overview [data-chart] .run-chart{height:112px;}
.proposal-card [data-diff-line] code{overflow:visible; white-space:pre-wrap;}
.proposal-card .entry-diff:has([data-diff-more][open]) [data-diff-line] code, .proposal-card [data-unchanged][open] code{overflow:visible; white-space:pre-wrap;}
.entry-text-card [data-lib-text]{transition:box-shadow var(--motion) var(--ease);}
.entry-text-card [data-lib-text]:hover{box-shadow:var(--lift-1);}
.entry-text-card [data-lib-text]:focus-visible{outline:solid 2px var(--accent); outline-offset:var(--space-1);}
.library-history-row{display:grid; gap:var(--space-2) var(--space-6); grid-template-columns:minmax(0, .8fr) minmax(0, 1.2fr);}
.history-name{align-content:start; align-items:start;}
.history-name > a{flex:1 1 0%;}
.history-records{min-width:0;}
.history-record{gap:var(--space-1) var(--space-3); margin:0;}
.history-record + .history-record{border-top:solid 1px var(--line); margin-top:var(--space-2); padding-top:var(--space-2);}
.history-record .entry-path{flex-basis:100%;}
.attention-card.card{padding:var(--space-4);}
#attention[data-list-window]:not([data-expanded]){max-height:184px !important;}

/* Full-width decisions leave the chart and order-attention columns stable. */
#home-proposals{margin:0 0 var(--space-4);}
.proposal-band-head{align-items:center; display:flex; gap:var(--space-4); justify-content:space-between; margin-bottom:var(--space-2);}
.proposal-band-head .section-heading, .proposal-band-head .show-all{margin:0;}
.proposal-band-head .show-all{background:#0000; color:var(--accent); font-family:var(--font); padding:var(--space-1) 0;}
.proposal-band-head .show-all:hover{background:var(--accent-wash);}
#home-proposals .proposal-card{margin-bottom:0;}
.home-proposal-list{display:grid; gap:var(--space-4);}
:root body .home-file.card{background:var(--paper); border-radius:var(--round-control); box-shadow:var(--lift-1); padding:var(--space-2);}

.proposal-card{align-items:start; display:flex; flex-wrap:wrap; gap:var(--space-4);}
.proposal-intro, .proposal-changes{flex:1 1 400px; min-width:0;}
.proposal-changes{display:grid; gap:var(--space-2);}

/* Geometry clearance is separate from component spacing. */
.handoff-stage{padding-top:0;}
.handoff-stage::before{content:""; display:block; height:var(--handoff-head, 104px);}
#home-orders .order > .order-title{max-width:calc(100% - 100px); padding-right:0;}
[data-run-tiles] .run-tile > .hint{max-width:calc(100% - 48px); padding-right:0;}
[tabindex]{transition:box-shadow var(--motion) var(--ease);}
[tabindex]:hover{box-shadow:var(--lift-1);}
[tabindex]:focus-visible{outline:solid 2px var(--accent); outline-offset:var(--space-1);}
button{cursor:pointer;}
button:disabled{cursor:default;}
.diff-line[data-diff-line=remove]{background:var(--well);}
.diff-line[data-diff-line=remove] > .diff-number{color:var(--ink-3);}
#home-proposals [data-list-window]:not([data-expanded]){max-height:320px;}

/* Keep the form below both independently scrollable conversation columns. */
.seat-full-columns .list-window{display:grid; gap:var(--space-2); grid-template-rows:var(--track) auto; min-height:0;}
.seat-full-columns .show-all{margin-top:0;}
.seat-full-columns [data-list-window]:not([data-expanded]){max-height:100%; min-height:0;}
.seat-full-columns:has([data-expanded]){grid-template-rows:auto 48px auto;}
.board-column[data-column=failed] > h3{border-bottom-width:3px;}

/* Explain the existing state palette beside the shared timeline. */
.timeline-legend{align-items:center; display:flex; flex:0 0 auto; gap:var(--space-2); margin-left:auto;}
.timeline-legend .badge{box-shadow:none; gap:var(--space-1); padding:0 var(--space-1);}
.canvas-panel-head > strong{min-width:0;}
[data-canvas-item]:has([data-canvas-list-state]){display:grid; gap:var(--space-1); grid-template-columns:24px var(--track) 6px;}
[data-canvas-list-state]{box-shadow:none; gap:var(--space-1); grid-column:2 / -1; justify-self:start; padding:0 var(--space-1);}

/* Pass 31: cool light, glass highlights and a shared soft elevation scale. */
body{background-image:radial-gradient(ellipse 450px 400px at 100% 0%, rgb(240 246 253 / 0.85), #0000 100%), radial-gradient(ellipse 400px 400px at 4% 48%, rgb(244 244 253 / 0.85), #0000 100%), radial-gradient(ellipse 450px 300px at 65% calc(100% - 300px), rgb(240 248 241 / 0.85), #0000 100%); background-attachment:fixed;}
body .rail, body .top{background:#0000;}
body nav a[aria-current=page]{background:var(--nav-wash); box-shadow:inset 1px 1px 0 var(--paper), var(--lift-1); color:var(--accent);}
.rail-note{color:var(--ink-3); font-weight:normal;}
.hero::before{background-color:var(--mesh-base);}
.hero-art{opacity:0.28;}
:root body .hero .stat{background:var(--paper); border:0; border-radius:var(--round-card); box-shadow:inset 1px 1px 0 rgb(255 255 255 / 0.85), 0 8px 24px rgb(23 32 51 / 0.08);}
:root[data-transparency=on] body .hero .stat{-webkit-backdrop-filter:blur(18px) saturate(1.4); backdrop-filter:blur(18px) saturate(1.4); background:rgb(255 255 255 / 0.55);}
:root body .hero [data-stat-value]{color:var(--ink); font-size:var(--text-hero-stat); font-weight:var(--weight-medium); letter-spacing:-0.025em; line-height:30pt;}
button:not(.quiet):not(.link):not([data-canvas-node]):not(.seat-select):not(.canvas-tools button):not(:disabled), .button:not(.quiet){background-image:linear-gradient(to bottom, #2567c5, var(--accent-side)); border-radius:var(--round-control); box-shadow:inset 0 1px 0 rgb(255 255 255 / 0.28), 0 6px 16px rgb(23 93 193 / 0.25); min-height:40px;}

.empty .empty-art{overflow:visible;}
.empty .empty-tone{stroke:var(--paper); stroke-opacity:0.7; stroke-width:1;}
.empty .empty-detail{stroke:var(--paper); stroke-opacity:0.9; stroke-width:2;}

/* Quiet nested surfaces keep all rows and their hit targets, without outlines. */
:root body .card :is(.card, .order, .seat, .home-seat, .home-entry, .home-file, .file, .handoff-card, .handoff-seat, .run-tile, .launch-card, .seat-run, .seat-launch, .week-day){border:0; box-shadow:var(--lift-1);}
:root body .card :is(.order-box, .home-entry-box, .home-file, .seat, .home-seat, .handoff-card, .handoff-seat, .run-tile, .launch-card, .seat-run, .seat-launch, .week-day){background:linear-gradient(var(--well), var(--well)) var(--paper);}
:root body .card :is(.order-box > .order, .home-entry-box > .home-entry){background:#0000;}
:root body :is(.pill, .badge){box-shadow:none;}
:root body :is(#backend, #run-activity){box-shadow:var(--lift-1);}
:root body .home-row > .card, :root body .home-row > div > .card,
:root body .home-compose-row > .card, :root body [data-view=home] > section.card,
:root body .home-overview > div > div > .card{padding:var(--space-6);}
[data-view=home] .section-heading{margin-top:var(--space-8); margin-bottom:var(--space-4);}
[data-view=home] .hero{margin-bottom:var(--space-6);}
.proposal-band-head .section-heading{margin:0;}
.home-compose-row{margin-bottom:var(--space-4);}
:root body :is(.thin-track, .week-track, .usage-track, .usage-track > span, .progress-track, .step-track){border-radius:var(--round-pill); height:var(--space-1);}
:root body :is(.thin-track, .week-track, .usage-track, .progress-track, .step-track){background:rgb(23 32 51 / 0.05);}
:root body [data-progress] > .step-track[data-progress-fill]{background:#0000; border-radius:var(--round-pill); height:var(--space-1);}
:root body [data-progress-fill], [data-meter-fill]{border-radius:inherit;}
.stat-chart[data-chart-type=split]{height:var(--space-1);}
.meter-ring-track, .meter-ring-fill{stroke-width:6; stroke-linecap:round;}

/* The existing bounded cubics retain every bucket and exact event position. */
.run-chart .chart-line{stroke-width:2; vector-effect:non-scaling-stroke;}
.run-chart .chart-grid{stroke:rgb(23 32 51 / 0.08); stroke-width:1; stroke-dasharray:2 5; vector-effect:non-scaling-stroke;}
.run-chart [data-axis-tick]{stroke-dasharray:none;}
.run-chart .chart-mark{vector-effect:non-scaling-stroke;}
.seat-summary-block .spark-track{fill:#0000;}
.seat-summary-block .spark-end{stroke:var(--paper);}

/* Team sections get air; the canvas coordinates and timeline scales stay fixed. */
#team-drawings > .card, #team-canvas-slot > .card, #team-seat-slot > .card,
.team-overview > .card, .team-comparison > .card, [data-view=team] > section.card{margin-bottom:var(--space-8); padding:var(--space-6);}
:root body .card .usage-row{background:linear-gradient(var(--well), var(--well)) var(--paper); border:0;}
:root body button[data-canvas-node]{border-color:var(--line); box-shadow:var(--lift-1);}
:root body button[data-canvas-node]:hover{border-color:var(--accent); box-shadow:var(--lift-2);}
:root[data-transparency=reduce] body nav a[aria-current=page]{backdrop-filter:none; background:var(--paper);}
.hero [data-stat=today] [data-card-icon]{background:var(--kind-skill-wash); color:var(--kind-skill-ink);}
.hero [data-stat=launches] [data-card-icon]{background:var(--kind-artifact-wash); color:var(--kind-artifact-ink);}

/* The same surfaces continue through the shelf, board and month grid. */
:root body .card .order{background:linear-gradient(var(--well), var(--well)) var(--paper);}
:root body .card .order-box > .order{background:#0000;}
.shelf-entry.card{border-radius:var(--round-card); padding:var(--space-6);}
.card.board-column{padding:var(--space-6);}
.calendar-grid:has(> .day-cell){gap:var(--space-1); padding:var(--space-2);}
:root body .day-cell{background:var(--well); border:0; border-radius:var(--round-chip);}
:root body .day-cell[data-today]{background:var(--accent-wash);}
:root body .day-cell[data-outside]{background:var(--wash);}
:root body .day-cell:hover{background:var(--accent-wash);}
[data-view=order] [data-order-files]{margin-bottom:var(--space-8);}

:root body .hero .stat{padding:var(--space-6);}

:root body .card.order-box{transition:box-shadow var(--motion) var(--ease);}
:root body .card.order-box:hover{box-shadow:var(--lift-2) !important;}

/* Keep the first-run illustration at its full 96px without an oversized card. */
.home-overview [data-chart] > .empty{padding:0;}

/* Hero colours belong to the small meaning marks, never to the numbers. */
.hero [data-stat=today]{--stat-disc-wash:#e5e8ec; --stat-hue:var(--accent); --stat-rgb:67, 90, 119;}
.hero [data-stat=running]{--stat-disc-wash:#e6e5ec; --stat-hue:var(--kind-skill-ink); --stat-rgb:73, 70, 119;}
.hero [data-stat=attention]{--stat-disc-wash:#e9e6e1; --stat-hue:var(--attention); --stat-rgb:95, 73, 41;}
.hero [data-stat=launches]{--stat-disc-wash:#dbe8e8; --stat-hue:var(--kind-artifact-ink); --stat-rgb:0, 90, 94;}
:root body .hero .stat > [data-card-icon]{background:var(--stat-disc-wash); border-radius:var(--round-pill); color:var(--stat-hue); height:var(--space-8); width:var(--space-8);}
:root[data-transparency=on] body .hero [data-stat-alert]{background-image:linear-gradient(rgba(var(--stat-rgb), 0.07), rgba(var(--stat-rgb), 0.03));}

body nav a[aria-current=page] .glyph{color:var(--accent);}

.seat-spark-empty{color:var(--ink-3); font-size:var(--text-xs); line-height:var(--leading-sm); margin:var(--space-2) 0;}

.hero .stat-chart[data-chart-type=split]{border-radius:var(--round-pill); overflow:hidden;}
.hero .stat-segment{fill:var(--stat-hue); height:var(--space-4); stroke:none; y:0;}
.hero .stat-segment[data-tone=neutral]{fill-opacity:0.15;}
.hero [data-stat=today] .stat-segment[data-tone=running]{fill-opacity:0.6;}
.hero [data-stat=today] .stat-segment[data-tone=failed]{fill-opacity:0.35;}
.hero [data-stat=today]:not(:has([data-stat-chart]))::after{background:rgba(var(--stat-rgb), 0.15); border-radius:var(--round-pill); content:""; display:block; height:var(--space-1); margin-top:auto;}

:root body [data-view=home] .home-overview .run-chart{height:168px; width:100%;}
[data-view=home] .run-chart .axis-label{font-size:var(--text-xs);}
.home-overview [data-chart] .drawing-caption{margin:var(--space-1) 0;}

/* An opacity ramp blends the same ink into the surface under each text role.
 * The low steps are decorative; informative text never drops below 66%. */
h1, h2, h3, .section-heading, .order-title, .stat strong{color:var(--ink-92);}
.card h3, .seat-name, .activity-who, .lead-details strong{color:var(--ink-86);}
label, .stat-label, .block-head > span, .canvas-panel-head > strong{color:var(--ink-80);}
.drawing-caption, .seat-model, .lead-details .model, .entry-sentence{color:var(--ink-76);}
[data-stat-note], .hint, .sub, .foot, .rail-note{color:var(--ink-72);}
[data-seat-summary] > span, [data-launch-stat] > span, .meter-label, .day-count{color:var(--ink-70);}
code, .mono, .entry-path, .diff-number, .file-column-head, th{color:var(--ink-68);}
time, .activity time, .home-file time, .seat-launch time{color:var(--ink-66);}
.axis-label:not([data-seat-state]){fill:var(--ink-68);}
input::placeholder, textarea::placeholder{color:var(--ink-66);}
button:disabled, input:disabled, textarea:disabled{color:var(--ink-70);}
:root body .hero [data-stat-value]{color:var(--ink-92);}

/* Nested wells blend with their containing card; every .card keeps its white base. */
:root body .card :is(.order, .seat, .home-seat, .home-entry, .home-file, .file, .handoff-card, .handoff-seat, .run-tile, .launch-card, .seat-run, .seat-launch, .week-day):not(.card){background:var(--well);}
:root body .card :is(.order-box > .order, .home-entry-box > .home-entry){background:#0000;}
:root body :is(.pill, .badge):not([data-state]){background:rgb(74 73 106 / 0.12);}
button:disabled .glyph, input:disabled + .glyph{color:var(--ink-38);}
tbody tr:nth-child(even){background:rgb(23 32 51 / 0.03);}
:root body .card.order-box{box-shadow:0 1px 2px rgb(23 32 51 / 0.02), 0 4px 12px rgb(23 32 51 / 0.02);}

/* Subordinate type keeps the same line boxes, so richer hierarchy adds no height. */
:root body :is(code, .mono, .entry-path, .file-column-head, th, .pill, .badge){font-size:var(--text-micro);}
:root body :is(.drawing-caption, .seat-model, .lead-details .model, .hint, .sub, .foot, [data-stat-note]){font-size:var(--text-caption);}
:root body :is(.entry-sentence, .empty p, .hero-summary){font-size:var(--text-copy);}
:root body :is(.seat-name, .order-title){font-size:var(--text-emphasis);}
:root body .number-unit{color:var(--ink-70); display:inline; font-size:var(--text-unit); font-weight:normal; margin:0;}

/* The canvas work area remains a surface around its rail and stage. */
.canvas-workarea{background:linear-gradient(var(--well), var(--well)) var(--paper);}

/* Shared hue families: marks use one tone, informative text its dark step. */
.hero [data-stat=today]{--stat-disc-wash:#e6f2e9; --stat-hue:var(--tone-green); --stat-rgb:80, 160, 100;}
.hero [data-stat=running]{--stat-disc-wash:#e7eff9; --stat-hue:var(--tone-blue); --stat-rgb:87, 142, 212;}
.hero [data-stat=attention]{--stat-disc-wash:#f5ede1; --stat-hue:var(--tone-amber); --stat-rgb:182, 128, 40;}
.hero [data-stat=launches]{--stat-disc-wash:#eeedf9; --stat-hue:var(--tone-indigo); --stat-rgb:133, 129, 210;}
:root body .hero .stat > [data-card-icon]{background:var(--stat-hue); color:var(--paper);}
:root body .hero .stat{background-image:linear-gradient(rgba(var(--stat-rgb), 0.08), rgba(var(--stat-rgb), 0.03));}
:root body .card:has(> .seat-band){--seat-accent:var(--tone-violet); --seat-light:var(--tone-violet-light);}
:root body .card:has(> .seat-band[data-seat-tone="2"]){--seat-accent:var(--tone-teal); --seat-light:var(--tone-teal-light);}
:root body .card:has(> .seat-band[data-seat-tone="3"]){--seat-accent:var(--tone-amber); --seat-light:var(--tone-amber-light);}
:root body .card:has(> .seat-band[data-seat-tone="4"]){--seat-accent:var(--tone-indigo); --seat-light:var(--tone-indigo-light);}
:root body .card:has(> .seat-band[data-seat-tone="5"]){--seat-accent:var(--tone-green); --seat-light:var(--tone-green-light);}
:root body .card:has(> .seat-band[data-seat-tone="6"]){--seat-accent:var(--tone-red); --seat-light:var(--tone-red-light);}
.seat-band{background:var(--seat-light); border-radius:var(--round-control); padding:var(--space-3);}
.seat-band .seat-icon{border-radius:var(--round-pill); box-shadow:0 0 0 2px var(--seat-accent);}
:is(.timeline-bar, .chart-mark, .status-mark)[data-tone=done], .stat-segment[data-tone=done]{fill:var(--tone-green);}
:is(.timeline-bar, .chart-mark, .status-mark)[data-tone=failed], .stat-segment[data-tone=failed]{fill:var(--tone-red);}
:is(.timeline-bar, .chart-mark, .status-mark)[data-tone=running], .stat-segment[data-tone=running]{fill:var(--tone-blue);}
.run-chart .chart-line{stroke:var(--tone-blue);}
:root body [data-progress][data-tone=done] [data-progress-fill]{background:var(--tone-green);}
:root body [data-progress][data-tone=failed] [data-progress-fill]{background:var(--tone-red);}
:root body [data-progress][data-tone=running] [data-progress-fill]{background:var(--tone-blue);}
.glyph, .activity-icon{color:var(--ink-58); stroke-width:1.5;}
:root body :is(.home-file, .home-entry, .seat-run, .seat-message, .library-entry, .seat-reference-list > div, .pill, .badge, .week-day){border:0;}
th, td{border-bottom-color:#0000;}

/* Three wide hue fields keep the hero light without mixing back to blue. */
.hero::before{background:linear-gradient(110deg, var(--mesh-blue) 0%, var(--mesh-blue) 20%, var(--mesh-lilac) 45%, var(--mesh-lilac) 60%, var(--mesh-mint) 85%, var(--mesh-mint) 100%);}
.glyph text{fill:var(--ink-66);}

[data-dim]{opacity:1; transition:opacity var(--motion) var(--ease);}

[data-seat-tone="1"]{--seat-accent:var(--tone-violet);}
[data-seat-tone="2"]{--seat-accent:var(--tone-teal);}
[data-seat-tone="3"]{--seat-accent:var(--tone-amber);}
[data-seat-tone="4"]{--seat-accent:var(--tone-indigo);}
[data-seat-tone="5"]{--seat-accent:var(--tone-green);}
[data-seat-tone="6"]{--seat-accent:var(--tone-red);}
[data-kind-chip=skill]{--kind-light:var(--tone-indigo-light);}
[data-kind-chip=artifact]{--kind-light:var(--tone-teal-light);}
[data-kind-chip=workflow]{--kind-light:var(--tone-amber-light);}
[data-kind-chip=lesson]{--kind-light:var(--tone-violet-light);}
.kind-chip{background:var(--kind-light);}
[data-timeline-row] .timeline-bar{fill:var(--seat-accent);}
[data-gantt-row] [data-gantt-bar]{background:var(--seat-accent); border:0;}
[data-gantt-bar]::after{background:var(--wait); border-radius:inherit; content:""; right:0; top:0; bottom:0; position:absolute; width:3px;}
.timeline-state-cap{fill:var(--wait);}
.timeline-state-cap[data-tone=done]{fill:var(--tone-green);}
.timeline-state-cap[data-tone=failed]{fill:var(--tone-red);}
.timeline-state-cap[data-tone=running]{fill:var(--tone-blue);}
[data-gantt-bar][data-tone=done]::after{background:var(--tone-green);}
[data-gantt-bar][data-tone=failed]::after{background:var(--tone-red);}
[data-gantt-bar][data-tone=running]::after{background:var(--tone-blue);}
.seat-summary-block .spark-line{stroke:var(--seat-accent);}
.seat-summary-block .spark-end, .seat-summary-block .spark-bar{fill:var(--seat-accent);}
body{-webkit-font-smoothing:antialiased;}
/* Secondary labels stay regular; the headings and headline values carry emphasis. */
:root body :is(.pill, .badge, .kind-chip, .library-meta, .file-column-head, th){font-weight:normal;}
:root body :is(button.quiet, .button.quiet, .show-all){font-weight:var(--weight-medium);}
:root body .card > .seat-band{padding:var(--space-2) var(--space-3) 0;}
:root body .seat-band .seat-model{margin-top:0;}
/* Paint the existing scroll regions and detail panel as wells, without extra outlines. */
.seat-messages, .seat-run-list, [data-canvas-panel]{background:linear-gradient(var(--well), var(--well)) var(--paper); border-radius:var(--round-control);}
[data-canvas-panel]{box-shadow:none;}
.replay-bar{min-height:64px;}
.chart-bar{fill:var(--tone-blue);}
.usage-row[data-seat-tone] [data-usage-bar]{background:var(--seat-accent, var(--tone-blue));}
:is(.pill, .badge):is([data-state=waiting], [data-state=wait], [data-state=planned], [data-state=PENDING], [data-state=READY]){background:var(--wait-wash);}
:is(.chart-mark, .timeline-bar, .status-mark)[data-tone=waiting]{fill:var(--tone-indigo);}
.flow-dot{fill:var(--tone-indigo);}
.flow-dot:is([data-state=LEASED], [data-state=JUDGING]){fill:var(--tone-blue);}
.flow-dot[data-state=SUCCEEDED]{fill:var(--tone-green);}
.flow-dot:is([data-state=FAILED], [data-state=DEAD], [data-state=CANCELLED]){fill:var(--tone-red);}
.flow-dot[data-state=due]{fill:var(--tone-amber);}
.step-track > span{background:var(--tone-indigo);}
.week-track [data-week-state=SUCCEEDED], .step-track [data-state=SUCCEEDED]{background:var(--tone-green);}
.week-track [data-week-state=running], .step-track [data-state=LEASED], .step-track [data-state=JUDGING]{background:var(--tone-blue);}
.week-track [data-week-state=FAILED], .step-track [data-state=FAILED], .step-track [data-state=DEAD], .step-track [data-state=CANCELLED]{background:var(--tone-red);}
.seat-focus-controls{display:flex; flex-wrap:wrap; gap:var(--space-2); margin-bottom:var(--space-2);}
.seat-focus-controls button{padding:var(--space-1) var(--space-3);}
.seat-focus-controls button[aria-pressed=true]{background:var(--accent-wash); box-shadow:0 0 0 2px var(--accent) inset;}
/* Existing row separation is carried by spacing and tint. */
:root body :is(.top, .activity li, .results-file, .shelf-source, .library-history, .library-history-row, .seat-full-stats, [data-seat-compose]){border-color:#0000;}
.status-chip:hover{background:var(--accent-wash); color:var(--accent); text-decoration-line:none;}
.status-chip[data-link=down]{background:var(--bad-wash); color:var(--bad);}
.status-chip strong{color:var(--ink);}
.status-cards{align-items:start; margin-bottom:0;}
.status-card{display:grid; gap:var(--space-3);}
.status-card .block-head{margin-bottom:0;}
.status-facts{color:var(--ink-2); display:grid; gap:var(--space-1); list-style:none; margin:0; padding-left:0;}
.status-facts [data-fact]{color:var(--ink);}
.status-card .notice{margin:0;}
.status-card .notice[data-flag="7a"], .status-card .notice[data-flag="7b"], .status-card .notice[data-flag="7e"], .status-card .notice[data-flag="7f"]{background:var(--attention-wash); color:var(--ink);}
.status-flags{display:grid; gap:var(--space-2);}
.status-rows th:first-child{width:8%;}
.holding{margin:0 0 var(--space-4);}
.seat-warn{color:var(--attention);}
.dot[data-status=attention]{background:var(--paper); border:2px solid var(--attention);}
.diary-family + .diary-family{margin-top:var(--space-6);}
.diary-family thead > tr > :first-child{width:18%;}

/* Aurora behind the home hero: three soft colour fields (orange, pink, blue) rising from the bottom, under a white veil
   that fades out downwards, so the headline sits on white and the colour gathers behind the stat cards. */
.hero::before{background:radial-gradient(48% 95% at 12% 100%, rgb(0 190 255 / 0.42), #0000 72%), radial-gradient(42% 90% at 38% 96%, rgb(255 119 0 / 0.34), #0000 70%), radial-gradient(50% 100% at 62% 100%, rgb(255 0 85 / 0.40), #0000 72%), radial-gradient(46% 95% at 90% 92%, rgb(0 115 255 / 0.40), #0000 72%), radial-gradient(ellipse 40% 70% at right 18% top 8%, rgb(255 0 85 / 0.22), #0000 70%), linear-gradient(.5turn, var(--paper) 0%, #fff7fb 100%);}
.hero::after{background:linear-gradient(.5turn, rgb(255 255 255 / 0.78) 0%, rgb(255 255 255 / 0.30) 48%, rgb(255 255 255 / 0) 100%); border-radius:inherit; content:""; inset:0 0 56px; pointer-events:none; position:absolute; z-index:-1;}
/* The colour shows in a band under the stat cards, as in the reference: the hero's background reaches the bottom,
   the cards stay solid white on top of it. */
[data-view=home] .hero{padding-bottom:56px;}
.hero::before, .hero::after{inset:0;}
.hero .stat, [data-view=home] .hero .stat{backdrop-filter:none; background:var(--paper) !important;}

/* Colour pairs instead of loud blocks: every seat band is a pale wash of its hue at the same lightness with the name in
   the darker ink of that hue and a thin accent bar; cards inside cards are white with a hairline ring, not grey. */
:root{--seat-1-light:#f7f0f9; --seat-2-light:#ecf7f8; --seat-3-light:#faf3e8; --seat-4-light:#f1f0fb; --seat-5-light:#edf7f0; --seat-6-light:#fbefee;}
:root body .card:has(> .seat-band[data-seat-tone="1"]){--seat-ink-strong:var(--seat-1-ink); --seat-light:var(--seat-1-light);}
:root body .card:has(> .seat-band[data-seat-tone="2"]){--seat-ink-strong:var(--seat-2-ink); --seat-light:var(--seat-2-light);}
:root body .card:has(> .seat-band[data-seat-tone="3"]){--seat-ink-strong:var(--seat-3-ink); --seat-light:var(--seat-3-light);}
:root body .card:has(> .seat-band[data-seat-tone="4"]){--seat-ink-strong:var(--seat-4-ink); --seat-light:var(--seat-4-light);}
:root body .card:has(> .seat-band[data-seat-tone="5"]){--seat-ink-strong:var(--seat-5-ink); --seat-light:var(--seat-5-light);}
:root body .card:has(> .seat-band[data-seat-tone="6"]){--seat-ink-strong:var(--seat-6-ink); --seat-light:var(--seat-6-light);}
:root body .seat-band{background:var(--seat-light); box-shadow:none;}
:root body .seat-band .seat-name, :root body .seat-band strong{color:var(--seat-ink-strong, var(--ink));}
:root body .seat-band .seat-model{color:var(--ink-3);}
:root body article.card.order-box{background:var(--paper); box-shadow:inset 0 0 0 1px rgb(0 0 0 / 0.07), 0 1px 2px rgb(0 0 0 / 0.04);}
:root body .card :is(.home-seat, .seat), :root body .card article.card.order-box{background:var(--paper); background-image:none;}
/* Type as in the reference: body weight 400, emphasis 500, headings 600 with light tracking. */
:root body :is(h1, h2, h3, h4){font-weight:var(--weight-heading); letter-spacing:-0.01em;}
:root body .page-head h1, :root body .hero h1{letter-spacing:-0.015em;}
:root body :is(.card h2, .card h3, .section-title){font-size:11.25pt; line-height:16.5pt;}
/* The day in the hero reads as the one coloured headline, a pink-to-violet gradient as in the reference. */
:root body .hero h2{-webkit-background-clip:text; background:linear-gradient(90deg, #e2297f 0%, #b33fd6 55%, #6a5cf2 100%); background-clip:text; color:#0000;}

/* The header and first card row share two content-sized tracks. The header spans both, so its aurora grows with
   the cards, including board lanes. Subgrid lets the heading size the first track without a fixed height.
   Match Home's 16px card inset, 48px below the cards and 12px gap to the next section; leave Home untouched. */
:root body [data-view]:not([data-view=home]):has(> .page-head){display:grid; grid-template-columns:var(--track);}
:root body [data-view]:not([data-view=home]):has(> .page-head) > *{grid-column:1; min-width:0;}
:root body [data-view]:not([data-view=home]) > .page-head{border-radius:var(--space-3); display:grid; gap:0 var(--space-3); grid-row:1 / 3; grid-template-columns:var(--track) auto; grid-template-rows:subgrid; isolation:isolate; margin:0 0 var(--space-3) !important; overflow:hidden; padding:var(--space-5) var(--space-4) 48px !important; position:relative;}
:root body [data-view]:not([data-view=home]) > .page-head > *{align-self:center; grid-row:1; margin-bottom:var(--space-3);}
:root body [data-view]:not([data-view=home]) > .page-head::before{background:radial-gradient(46% 120% at 10% 100%, rgb(0 190 255 / 0.30), #0000 72%), radial-gradient(40% 110% at 36% 100%, rgb(255 119 0 / 0.24), #0000 70%), radial-gradient(48% 120% at 62% 100%, rgb(255 0 85 / 0.28), #0000 72%), radial-gradient(44% 120% at 90% 100%, rgb(0 115 255 / 0.28), #0000 72%), radial-gradient(36% 90% at 84% 0%, rgb(255 0 85 / 0.14), #0000 70%), linear-gradient(.5turn, var(--paper) 0%, #fff8fc 100%); content:""; inset:0; pointer-events:none; position:absolute; z-index:-1;}
:root body [data-view]:not([data-view=home]) > .page-head::after{background:linear-gradient(.5turn, rgb(255 255 255 / 0.80) 0%, rgb(255 255 255 / 0.35) 50%, rgb(255 255 255 / 0) 100%); content:""; inset:0; pointer-events:none; position:absolute; z-index:-1;}
:root body [data-view]:not([data-view=home]) > .page-head h2{-webkit-background-clip:text; background:linear-gradient(90deg, #e2297f 0%, #b33fd6 55%, #6a5cf2 100%); background-clip:text; color:#0000;}
:root body [data-view]:not([data-view=home]) > :is(.stats, #status-summary, #board-columns){grid-column:1; grid-row:2; margin:0 var(--space-4) calc(48px + var(--space-3)); min-width:0; padding:0; position:relative; width:auto; z-index:1;}
:root body [data-view]:not([data-view=home]) > .page-head + :is(.stats, #status-summary) :is(.stat, .card){background:var(--paper); background-image:none;}
/* Links between cards are light blue, as in the reference; the stand-alone page (no pro/ui) gets the same colour. */
:root body{--edge:#83c7fe;}

/* Public board: five stable lanes, with independent bounded scrolling. */
#board-columns[data-public-board]{display:block;}
[data-view=board] :is(h2,h3,h4,strong,button,label){font-weight:500;}
.task-toolbar{align-items:end; display:flex; flex-wrap:wrap; gap:var(--space-3); margin-bottom:var(--space-5);}
.task-toolbar label{display:grid; gap:var(--space-1); color:var(--ink-3); font-size:var(--text-xs);}
.task-toolbar label:first-child{flex:1 1 220px;}
.task-toolbar :is(input,select){width:100%; min-height:36px; font-size:var(--text-sm);}
.task-toolbar .actions{gap:var(--space-1);}
.task-toolbar button[aria-pressed=true]{background:var(--accent-wash); color:var(--accent);}
.task-toolbar > a{align-self:center; font-size:var(--text-xs);}
.task-summary{display:flex; flex-wrap:wrap; gap:var(--space-3); color:var(--ink-3); font-size:var(--text-xs); margin-bottom:var(--space-5);}
.task-summary [data-board-total]{color:var(--ink); font-weight:500; margin-right:auto;}
.task-columns{display:grid; grid-template-columns:repeat(5,minmax(0,1fr)); align-items:start; gap:var(--space-3);}
.task-column{padding:0; background:var(--well); border-radius:var(--round-control); min-width:0;}
.task-column h3{align-items:center; display:flex; gap:var(--space-1); min-height:48px; padding:var(--space-2); margin:0; font-size:var(--text-xs); line-height:var(--leading-sm);}
.task-column h3 .card-icon{display:none;}
.task-column .column-count{margin-left:auto; background:var(--paper); color:var(--ink-2); font-weight:400;}
.task-items{display:flex; flex-direction:column; gap:var(--space-3); max-height:calc(100vh - 310px); min-height:130px; overflow:auto; scrollbar-gutter:stable; padding:var(--space-1) var(--space-2) var(--space-3);}
.task-card{background:var(--paper); border:1px solid var(--line-2); border-radius:var(--round-control); box-shadow:var(--lift-1); padding:var(--space-3); cursor:pointer; min-width:0; flex-shrink:0;}
.task-card:hover{border-color:var(--ink-16);}
.task-card:focus-visible{outline:2px solid var(--accent); outline-offset:1px;}
.task-card h4{font-size:var(--text-sm); font-weight:500; line-height:var(--leading-sm); margin:var(--space-3) 0; overflow-wrap:anywhere;}
.task-card-top,.task-card-meta{align-items:center; display:flex; gap:var(--space-2); justify-content:space-between;}
.task-pill,.task-size,.task-changed{font-size:var(--text-micro); font-weight:400; border-radius:var(--round-chip); padding:2px 6px; background:var(--wash); color:var(--ink-2);}
.task-pill[data-state=LEASED]{color:var(--run); background:var(--run-wash);}
.task-pill[data-state=JUDGING]{color:var(--attention); background:var(--attention-wash);}
.task-pill[data-state=SUCCEEDED]{color:var(--ok); background:var(--ok-wash);}
.task-pill:is([data-state=FAILED],[data-state=DEAD]){color:var(--bad); background:var(--bad-wash);}
.task-root{font-size:var(--text-micro); color:var(--ink-3); overflow:hidden; white-space:nowrap; text-overflow:ellipsis; margin:0 0 var(--space-3);}
.task-holder{align-items:center; display:flex; gap:var(--space-2); font-size:var(--text-xs); color:var(--ink-2); margin-bottom:var(--space-3); min-height:26px; overflow-wrap:anywhere;}
.task-avatar{display:inline-grid; place-items:center; width:26px; height:26px; flex:0 0 26px; background:var(--canvas); border:1px solid var(--ink-16); border-radius:var(--round-chip); color:var(--ink); font-weight:500;}
.task-ring{align-items:center; display:inline-flex; gap:var(--space-1); font-size:var(--text-micro); color:var(--ink-2);}
.task-ring-track{fill:none; stroke:var(--ink-16); stroke-width:2;}
.task-ring-done{fill:none; stroke:var(--ok); stroke-width:2;}
.task-dates{display:grid; grid-template-columns:auto minmax(0,1fr); gap:2px var(--space-1); font-size:var(--text-micro); line-height:var(--leading-sm); margin:var(--space-3) 0; color:var(--ink-3);}
.task-dates dd{margin:0; text-align:right; overflow-wrap:anywhere;}
.task-changed{display:inline-block; margin-bottom:var(--space-2); background:var(--accent-wash); color:var(--accent);}
.task-actions{display:flex; flex-wrap:wrap; gap:var(--space-2); border-top:1px solid var(--line-2); padding-top:var(--space-2); font-size:var(--text-micro);}
.task-empty{font-size:var(--text-xs); color:var(--ink-3); border:1px dashed var(--ink-16); border-radius:var(--round-control); text-align:center; padding:var(--space-6) var(--space-2); margin:0;}
.task-pages{align-items:center; display:flex; flex-wrap:wrap; justify-content:space-between; gap:var(--space-1); padding:var(--space-2);}
.task-pages button{font-size:var(--text-micro); padding:var(--space-1);}
[data-public-board][data-mode=list] .task-columns{grid-template-columns:minmax(0,1fr);}
[data-public-board][data-mode=list] .task-items{max-height:480px;}
[data-public-board][data-mode=list] .task-card{display:grid; grid-template-columns:120px minmax(120px,1fr) 140px 130px 180px; align-items:center; gap:var(--space-3);}
[data-public-board][data-mode=list] .task-card h4{margin:0;}
[data-public-board][data-mode=list] .task-card :is(.task-root,.task-actions){grid-column:2 / -1;}
.task-drawer{position:fixed; z-index:30; top:0; right:0; bottom:0; width:460px; max-width:100vw; overflow:auto; background:var(--paper); box-shadow:var(--lift-3); border-left:1px solid var(--ink-16); padding:var(--space-6);}
.task-drawer h2{font-size:var(--text-xl); line-height:var(--leading-lg); margin:var(--space-4) 0;}
.task-detail-section{border-top:1px solid var(--line-2); padding-top:var(--space-5); margin-top:var(--space-5); overflow-wrap:anywhere;}
.task-detail-section h3{font-size:var(--text-sm); margin-bottom:var(--space-2);}
.task-goal{white-space:pre-wrap;}
