/* Colour roles from the kit-color skill: every coloured block uses one of three lightness bands (wash, ink, mark); data colours keep saturation and lightness and change only the hue. Loaded last. */
html:root body {
  /* status: wash / ink / mark */
  --kc-run-wash: #eaf1ff;  --kc-run-ink: #2456d6;  --kc-run-mark: #0190fe;
  --kc-warn-wash: #fff1e0; --kc-warn-ink: #b25e00; --kc-warn-mark: #f28a2e;
  --kc-ok-wash: #e6f6ed;   --kc-ok-ink: #1e8a4f;   --kc-ok-mark: #5fc88a;
  --kc-bad-wash: #fdecea;  --kc-bad-ink: #c4320a;  --kc-bad-mark: #ff6b5f;
  /* bright marks only (dots, bars, rings, chart lines) */
  --kc-blue: #0190fe; --kc-green: #5fc88a; --kc-amber: #e8b000; --kc-orange: #f28a2e;
  --kc-pink: #ee3e9e; --kc-violet: #a651f0; --kc-teal: #13b3a0; --kc-sky: #14b3f0;
  /* data hues: fixed saturation and lightness, only the hue changes */
  --kc-h0: 214; --kc-h1: 152; --kc-h2: 40; --kc-h3: 22; --kc-h4: 330; --kc-h5: 268; --kc-h6: 174; --kc-h7: 196;
  /* sequential (heat) in one hue */
  --kc-seq-1: #eaf1ff; --kc-seq-2: #b9d7ff; --kc-seq-3: #7db7ff; --kc-seq-4: #3d93f5; --kc-seq-5: #0070d6;
}
html:root body {
  --accent: #0070d6; --accent-wash: rgba(0, 112, 214, .08); --edge: #83c7fe;
  /* marks (dots, bars, rings, chart lines) and their washes */
  --tone-blue: var(--kc-blue);     --tone-blue-light: var(--kc-run-wash);
  --tone-green: var(--kc-green);   --tone-green-light: var(--kc-ok-wash);
  --tone-amber: var(--kc-amber);   --tone-amber-light: var(--kc-warn-wash);
  --tone-red: var(--kc-bad-mark);  --tone-red-light: var(--kc-bad-wash);
  --tone-teal: var(--kc-teal);     --tone-teal-light: hsl(174 70% 93%);
  --tone-indigo: var(--kc-sky);    --tone-indigo-light: hsl(196 70% 93%);
  --tone-violet: var(--kc-violet); --tone-violet-light: hsl(268 70% 93%);
  /* status: ink on its own wash */
  --run: var(--kc-run-ink);        --run-wash: var(--kc-run-wash);
  --ok: var(--kc-ok-ink);          --ok-wash: var(--kc-ok-wash);
  --attention: var(--kc-warn-ink); --attention-wash: var(--kc-warn-wash);
  --bad: var(--kc-bad-ink);        --bad-wash: var(--kc-bad-wash);
  --wait: hsl(268 48% 36%);        --wait-wash: hsl(268 70% 95%);
  /* seats: hue table 268 violet, 174 teal, 40 amber, 214 blue, 152 green, 22 orange */
  --seat-1: var(--kc-violet); --seat-1-wash: hsl(268 70% 93%); --seat-1-light: hsl(268 70% 95%); --seat-1-ink: hsl(268 48% 36%);
  --seat-2: var(--kc-teal);   --seat-2-wash: hsl(174 70% 93%); --seat-2-light: hsl(174 70% 95%); --seat-2-ink: hsl(174 48% 30%);
