cat > 'web/index.html' <<'OC_EOF_94'
<!doctype html>
<html lang="en" data-motion="on">
<head>
<meta charset="UTF-8">
<meta content="width=1280" name="viewport" id="page-viewport">
<meta content="only light" name="color-scheme">
<title>OpenCode Cockpit</title>
<link href="data:," rel="icon">
<link rel="stylesheet" href="/web/app.css">
<link rel="stylesheet" href="/web/look-home.css">
<link rel="stylesheet" href="/web/look-calendar.css">
<link rel="stylesheet" href="/web/look-order.css">
<link rel="stylesheet" href="/web/look-team.css">
<link rel="stylesheet" href="/web/look-records.css">
<link rel="stylesheet" href="/web/colour.css">
<link rel="stylesheet" href="/web/swarm.css">
<!-- optional-local-styles -->
</head>
<body>
<div class="rail"><nav data-nav aria-label="Main navigation"><div class="rail-brand">Oc<span>Cockpit</span></div><div id="nav-links"></div><p class="rail-note">One team.<br>Work worth keeping.</p></nav></div>
<div class="workspace">
<header class="top">
  <div class="brand"><p class="eyebrow">Your agent workspace</p><h1>OpenCode Cockpit</h1><p class="sub">Live run <code id="run">Connecting</code></p></div>
  <div class="meters"><a id="status-chip" class="pill status-chip" href="#/status" data-status-chip data-link="checking">Checking the dispatcher</a><span id="backend" class="pill" data-state="connecting" title="Waiting for a response from the backend.">Connecting</span><span id="run-activity" class="pill" data-work-state="idle">Idle</span><span id="launches" class="meter">0 / 0 launches</span><span id="top-links" class="actions"></span><a id="pro-link" hidden href="/pro/" class="pill" title="The same live run in the pro page (private build).">Pro page</a></div>
</header>
<p id="notice" class="notice" hidden></p>
<main>
<section data-view="home" aria-labelledby="hero-date">
  <section data-hero class="hero"><div id="hero-art"></div><div class="page-head"><div><p id="home-h" class="eyebrow">Make room for good work.</p><h2 id="hero-date">Today</h2><p id="hero-sentence">Give your team a clear goal, then follow the work here.</p></div><div id="home-day-link" class="hero-actions"></div></div><div id="hero-stats" class="stats"></div></section>
  <section id="home-proposals" data-home-proposals hidden aria-label="Proposals waiting for you"></section>
  <div class="home-row home-overview"><div><div id="home-activity-chart"></div><div id="home-week"></div></div><div><div id="home-run-meter"></div><section class="card attention-card"><h3>Needs attention</h3><ul data-attention id="attention"></ul></section></div></div>
  <h3 id="compose-heading" class="section-heading">Plan the next result</h3>
  <div class="home-compose-row">
  <section class="card compose-card"><h3>What would you like the team to do?</h3>
    <div id="compose-examples" class="actions compose-examples" hidden></div>
    <form data-compose id="compose-form" autocomplete="off" novalidate>
      <label>Title <input id="compose-title" name="title" required maxlength="80" placeholder="Name this order"></label>
      <label>Goal <textarea id="compose-goal" name="goal" required rows="2" maxlength="4000" placeholder="Describe the result you want and who it helps."></textarea></label>
      <div id="compose-lead"></div>
      <div id="compose-library"></div>
      <p data-form-error id="compose-error" class="form-error" role="alert" hidden></p>
      <div class="actions"><button data-compose-submit type="submit" id="compose-submit">Send to lead</button><span class="hint">Cmd / Ctrl + Enter to send</span></div>
    </form>
  </section>
</div>
  <div class="home-row home-work-row"><section class="card"><div class="block-head"><h3>Today's orders</h3><span id="home-newest-files"></span></div><div id="order-filters" class="order-filters" aria-label="Filter today's orders"></div><div id="home-orders" class="orders"></div><button id="orders-more" type="button" class="quiet show-all" aria-controls="home-orders" aria-expanded="false" hidden>Show all</button></section><div id="home-results"></div></div>
  <h3 class="section-heading">Your team and its knowledge</h3>
  <section class="card"><div class="block-head"><h3>Team</h3><div class="actions"><a href="#/team">Open the team</a><a href="#/swarms">Open swarms</a></div></div><p id="home-holding" class="holding" data-holding></p><div data-home-team id="home-team" class="team"></div></section>
  <div class="home-row"><div id="home-library"></div><section class="card"><h3>Next planned days</h3><div id="home-plans" class="orders"></div></section></div>
  <h3 class="section-heading">The latest hand-ins</h3>
  <div class="home-row home-feed-row">
  <section class="card"><div class="block-head"><h3>Recent activity</h3><a href="#/ledger">Open the ledger</a></div><p class="drawing-caption">Latest ledger messages, grouped by sender.</p><div id="feed-filters" class="feed-filters" aria-label="Filter activity by sender"></div><ol data-activity id="activity" class="activity" tabindex="0" title="Recent activity. Scroll here or choose Show all."></ol><button id="activity-more" class="quiet show-all" type="button" aria-controls="activity" aria-expanded="false" hidden>Show all</button></section><div id="home-files"></div></div>
  <div id="history-warnings"></div>
</section>
<section data-view="calendar" hidden aria-labelledby="calendar-h">
  <div class="page-head"><div><p class="eyebrow">Plan the work. Follow the results.</p><h2 id="calendar-h">Calendar</h2></div><div class="actions"><button data-cal="prev" class="quiet" aria-label="Previous month">Previous</button><button data-cal="today" class="quiet">Today</button><button data-cal="next" class="quiet" aria-label="Next month">Next</button></div></div>
  <div id="calendar-stats" class="stats view-stats"></div>
  <div class="calendar-layout"><div class="card calendar-card"><h3>Orders and plans</h3><div id="weekdays" class="calendar-grid"></div><div id="calendar-grid" class="calendar-grid"></div></div>
  <div id="calendar-agenda"></div></div>
  <div id="calendar-legend" class="legend"></div>
</section>
<section data-view="day" hidden aria-labelledby="day-h">
  <div class="page-head"><div><p class="eyebrow">One day at a time</p><h2 id="day-h">Day</h2></div><div id="day-nav" class="actions"></div></div>
  <div id="day-stats" class="stats"></div>
  <div class="two-col"><div class="stack"><section class="card"><h3>Orders</h3><div id="day-orders" class="orders"></div></section><section class="card"><h3>Planned orders</h3><div id="day-plans" class="orders"></div><p id="plan-result" role="status"></p></section></div>
  <section class="card"><h3 id="form-heading">New order</h3>
    <form data-day-form id="order-form" data-mode="closed" autocomplete="off">
      <div data-form-lead id="form-lead" data-actor=""></div>
      <p data-readonly-why id="day-readonly" class="hint">Waiting for the backend's calendar.</p>
      <label>Title <input id="f-title" name="title" required maxlength="80" placeholder="Release notes for v0.3" disabled></label>
      <label>Goal <textarea id="f-goal" name="goal" required rows="4" maxlength="4000" placeholder="What should exist when this is done, and what it is for." disabled></textarea></label>
      <div class="pair"><label>Write scope <input id="f-writes" name="writes" maxlength="120" placeholder="auto: order folder" disabled></label><label>Budget <input id="f-budget" name="budget" type="number" min="1" max="99" value="6" required disabled></label></div>
      <p class="hint">Goes to the lead. The floor judge checks file presence, non-empty content and format. It does not judge quality.</p>
      <div class="actions"><button data-day-submit id="f-send" type="submit" disabled>Issue order</button><span data-day-result id="f-result" class="result" aria-live="polite" role="status"></span></div>
    </form>
  </section></div>
  <section class="card" data-day-diary><h3>Diary</h3><p class="hint">Every ledger row of the day and every envelope that was refused or got no answer, with where it came from. Times are the backend's.</p><div id="day-diary"></div></section>
</section>
<section data-view="status" hidden aria-labelledby="status-h"><div class="page-head"><div><p class="eyebrow">The live run</p><h2 id="status-h">Order status</h2></div></div><div id="status-summary"></div>
  <div id="status-selection"></div>
  <section class="card"><h3>Not ended <span id="status-open-count" class="hint"></span></h3><div id="status-open" class="library-grid status-cards"></div></section>
  <section class="card"><h3>Ended <span id="status-ended-count" class="hint"></span></h3><div id="status-ended" class="library-grid status-cards"></div></section>
</section>
<section data-view="order" hidden aria-label="Order details"><div id="order-detail"></div></section>
<section data-view="swarms" hidden aria-labelledby="swarms-h">
  <div class="page-head"><div class="swarm-head-options"><h2 id="swarms-h">Agent swarms</h2>
    <label>Run <select id="swarm-run"><option value="">Current run</option></select></label>
  </div></div>
  <div id="swarm-stats" class="stats view-stats"></div>
  <div id="swarm-workspace"></div>
</section>
<section data-view="library" hidden aria-label="Library"><div id="library-content"></div></section>
<section data-view="board" hidden aria-labelledby="board-h"><div class="page-head"><div><p class="eyebrow">Across all runs</p><h2 id="board-h">Board</h2></div></div><div id="board-stats" class="stats view-stats"></div><div id="board-columns" class="board"></div></section>
<section data-view="team" hidden aria-labelledby="team-h"><div class="page-head"><div><p class="eyebrow">The live run</p><h2 id="team-h">Team</h2></div></div><div data-team-stats id="team-stats" class="stats"></div><div id="team-drawings"></div><section class="card"><h3>Seats</h3><p class="hint">Each seat uses its own model. The lead plans; workers hand in files. Who is working comes from the leases the dispatcher holds.</p><p id="team-holding" class="holding" data-holding></p><div id="team" class="team"></div></section><section class="card"><h3>Launches</h3><div id="team-launches"></div></section></section>
<section data-view="files" hidden aria-labelledby="files-h"><div class="page-head"><div><p class="eyebrow">The live run</p><h2 id="files-h">Files handed in</h2></div></div><div id="files-stats" class="stats view-stats"></div><div id="files-overview"></div><section class="card"><h3>Files from this run</h3><div class="file-column-head" aria-hidden="true"><span>File</span><span>Seat</span><span>Order</span><span>Revision / size</span><span>Status</span></div><div id="files" class="files"></div></section></section>
<section data-view="ledger" hidden aria-labelledby="ledger-h"><div class="page-head"><div><p class="eyebrow">The live run</p><h2 id="ledger-h">Ledger</h2></div></div><div id="ledger-stats" class="stats view-stats"></div><div id="ledger-overview"></div><section class="card"><h3>Recorded activity</h3><p class="hint">An append-only record, grouped by order. Newest events first in each group.</p><ol id="ledger" class="ledger ledger-groups" reversed></ol></section></section>
<section data-view="help" hidden aria-labelledby="help-h"><div class="page-head"><div><p class="eyebrow">A short field guide</p><h2 id="help-h">From an idea to accepted files</h2></div></div>
  <div id="help-stats" class="stats view-stats"></div>
  <section class="card"><h3>How work moves through the team</h3><ol class="help-steps"><li><strong>Every order goes to the lead.</strong> The lead plans, the other seats do the parts, and the judge decides.</li><li><strong>Write an order.</strong> Give it a title and a goal: what should exist and why. The lead splits it into sub-orders for the team.</li><li><strong>Open the calendar.</strong> Choose a day to see its orders. Every order opens the same page with its flow, seats, launches, files and ledger.</li><li><strong>Plan ahead.</strong> Save an order on a future day. When it becomes due, press Issue now yourself. Dates never start agents automatically. Earlier days are read-only.</li><li><strong>Read the judge's decision.</strong> The default judge checks that files were handed in, are not empty and match their claimed format. It does not assess quality. Refused work can be sent back for another attempt.</li><li><strong>Know the limits.</strong> The top bar shows this backend's launch count and limit. Each order allows two launches; each process has a wall-time limit. Budget belongs to the order and its sub-orders. There is no separate money limit. Past runs are read-only.</li></ol></section>
  <section class="card"><h3>A library that stays with your team</h3><p>Keep a handed-in file as a skill or reference from an order. The Library holds these files, finished workflows, and lessons from work sent back. Each order shows what the lead reused; the cost chart compares launches, retries, and elapsed seconds.</p><p>People can keep files and review proposals. The program records workflows and lessons. The lead may propose a skill, but it reaches no seat until a person accepts it. Decline a proposal, optionally adding a reason so the team can learn from it.</p></section>
  <section class="card"><h3>Keyboard shortcuts</h3><p class="hint">Use these when you are outside an input or text field. Press the two navigation keys within one second.</p><dl class="shortcut-list"><dt><kbd>n</kbd></dt><dd>Home, then focus the new-order title</dd><dt><kbd>g</kbd> then <kbd>h</kbd></dt><dd>Home</dd><dt><kbd>g</kbd> then <kbd>c</kbd></dt><dd>Calendar</dd><dt><kbd>g</kbd> then <kbd>b</kbd></dt><dd>Board</dd><dt><kbd>g</kbd> then <kbd>t</kbd></dt><dd>Team</dd><dt><kbd>g</kbd> then <kbd>s</kbd></dt><dd>Swarms</dd><dt><kbd>g</kbd> then <kbd>f</kbd></dt><dd>Files</dd><dt><kbd>g</kbd> then <kbd>l</kbd></dt><dd>Ledger</dd><dt><kbd>l</kbd></dt><dd>Library</dd><dt><kbd>?</kbd></dt><dd>Help</dd></dl></section>
  <div id="help-context"></div>
  <h3 class="examples-heading section-heading">Start with an example</h3><div id="examples" class="team"></div>
</section>
</main>
<footer class="foot">Local workspace. Agent command: <code>opencode run --format json -m &lt;model&gt;</code>. <a href="/web/quality.html">Quality radar</a></footer>
</div>
<aside id="preview" class="preview" aria-modal="true" role="dialog" aria-label="File preview" tabindex="-1" hidden><div class="preview-head"><code id="preview-path"></code><button id="preview-close" type="button" class="quiet">Close</button></div><pre id="preview-text"></pre></aside>
<aside id="seat-drawer" class="preview seat-drawer" aria-modal="true" role="dialog" aria-labelledby="seat-drawer-heading" hidden><div class="preview-head"><h3 id="seat-drawer-heading">Seat launches</h3><button id="seat-drawer-close" type="button" class="quiet">Close</button></div><div id="seat-drawer-content"></div></aside>
<div data-toast id="toast" class="toast" aria-live="polite" role="status" hidden></div>
<script src="/web/icons.js"></script>
<script src="/web/status.js"></script>
<script src="/web/board.js"></script>
<script src="/web/swarm.js"></script>
<script src="/web/app.js" type="module"></script>
</body>
</html>
OC_EOF_94
cat > 'web/look-calendar.css' <<'OC_EOF_95'
/* Calendar and day: ui-foundation's ink, spacing, surface and motion hierarchy.
   The shell rules apply only while one of these two routes is visible. */
:root body:has([data-view=calendar]:not([hidden]), [data-view=day]:not([hidden])){--attention:#945000; --attention-wash:rgb(178 94 0 / .12); --bad:#b33c2d; --bad-wash:rgb(179 60 45 / .10); --canvas:#f8f8f8; --ease:ease; --ink:var(--lc-ink); --ink-2:var(--lc-copy); --ink-28:var(--lc-faint); --ink-3:var(--lc-meta); --ink-38:var(--lc-faint); --ink-58:var(--lc-meta); --ink-66:var(--lc-meta); --ink-68:var(--lc-meta); --ink-70:var(--lc-meta); --ink-72:var(--lc-meta); --ink-76:var(--lc-copy); --ink-80:var(--lc-copy); --ink-86:var(--lc-ink); --ink-92:var(--lc-ink); --lc-copy:rgb(0 0 0 / .61); --lc-faint:rgb(0 0 0 / .27); --lc-hover:rgb(0 0 0 / .03); --lc-ink:rgb(0 0 0 / .88); --lc-line:rgb(0 0 0 / .06); --lc-meta:rgb(0 0 0 / .45); --lc-raised:0 0 0 .5px rgb(0 0 0 / .10), 0 1px 1px -1px rgb(0 0 0 / .10), 0 2px 6px -1px rgb(0 0 0 / .08); --lc-selected:rgb(0 0 0 / .04); --lc-shadow:0 0 0 .5px rgb(0 0 0 / .06), 0 1px 1px -1px rgb(0 0 0 / .10), 0 1px 2px rgb(0 0 0 / .05); --lc-well:rgb(0 0 0 / .02); --lift-1:var(--lc-shadow); --lift-2:var(--lc-shadow); --lift-3:var(--lc-raised); --line:var(--lc-line); --line-2:rgb(0 0 0 / .10); --motion:140ms; --nav-wash:var(--lc-line); --ok:#197340; --ok-wash:rgb(25 115 64 / .10); --paper:#fff; --round-button:7px; --round-card:12px; --round-chip:4px; --round-control:8px; --run:#006dcb; --run-wash:rgb(0 109 203 / .10); --shadow:var(--lc-shadow); --shadow-small:var(--lc-shadow); --text-caption:12px; --text-copy:13.5px; --text-display:22px; --text-emphasis:13.5px; --text-lg:17px; --text-md:13.5px; --text-micro:11.5px; --text-sm:13.5px; --text-stat:22px; --text-unit:11.5px; --text-xs:12px; --tone-blue:var(--run); --tone-green:var(--ok); --tone-indigo:var(--wait); --tone-red:var(--bad); --ui-shadow-card:var(--lc-shadow); --ui-shadow-hover:var(--lc-raised); --wait:#7040a0; --wait-wash:rgb(112 64 160 / .10); --wash:var(--lc-selected); --well:var(--lc-well); background:#f8f8f8; color:var(--lc-copy); font:400 13.5px/20px var(--font); grid-template-columns:272px var(--track); letter-spacing:-.006em;}

/* One spacing value per layer: sections 20, cards 12, content 8, controls 6. */
:root body :is([data-view=calendar], [data-view=day]){color:var(--lc-copy); font-size:10.125pt; line-height:15pt;}
:root body :is([data-view=calendar], [data-view=day]) .page-head{gap:var(--space-3); margin-bottom:var(--space-5); min-height:48px;}
:root body :is([data-view=calendar], [data-view=day]) .eyebrow{color:var(--lc-meta); font-size:8.625pt; font-weight:normal; line-height:12pt; margin:0 0 var(--space-1);}
:root body :is([data-view=calendar], [data-view=day]) h2{color:var(--lc-ink); font-size:16.5pt; font-weight:var(--weight-heading); letter-spacing:-.01em; line-height:21pt;}
:root body :is([data-view=calendar], [data-view=day]) h3{color:var(--lc-ink); font-size:12.75pt; font-weight:var(--weight-medium); gap:6px; letter-spacing:0; line-height:18pt; margin:0 0 var(--space-2);}
:root body :is([data-view=calendar], [data-view=day]) :is(h4, strong, .order-title, .agenda-title, label){font-weight:var(--weight-medium); letter-spacing:0;}
:root body :is([data-view=calendar], [data-view=day]) :is(a, .order-title, strong){color:var(--lc-ink);}
:root body :is([data-view=calendar], [data-view=day]) :is(small, .hint, .model, [data-stat-note]){color:var(--lc-meta); font-size:9pt; line-height:12pt;}
:root body :is([data-view=calendar], [data-view=day]) .card{background:var(--paper); border:0; border-radius:var(--space-3); box-shadow:var(--lc-shadow); margin:0; padding:var(--space-4);}
:root body :is([data-view=calendar], [data-view=day]) .actions{gap:6px;}
:root body :is([data-view=calendar], [data-view=day]) :is(button, .button){background:var(--lc-ink); border:0; border-radius:7px; box-shadow:none; color:var(--paper); font:500 13.5px/20px var(--font); gap:6px; min-height:28px; padding:var(--space-1) 10px; transform:none; transition:0.14s ease background-color;}
:root body :is([data-view=calendar], [data-view=day]) :is(button, .button):not(:disabled):hover{background:rgb(0 0 0 / .80); box-shadow:none; color:var(--paper); text-decoration-line:none; transform:none;}
:root body :is([data-view=calendar], [data-view=day]) :is(button.quiet, .button.quiet){background:#0000; box-shadow:none; color:var(--lc-copy); font-weight:normal;}
:root body :is([data-view=calendar], [data-view=day]) :is(button.quiet, .button.quiet):not(:disabled):not([aria-selected=true]):hover{background:var(--lc-hover); box-shadow:none; color:var(--lc-ink);}
:root body :is([data-view=calendar], [data-view=day]) button:disabled{background:var(--lc-ink); box-shadow:none; color:var(--paper); opacity:.4; transform:none;}
:root body :is([data-view=calendar], [data-view=day]) button.quiet:disabled{background:#0000; color:var(--lc-copy);}
:root body :is([data-view=calendar], [data-view=day]) :is(a, summary){transition:0.14s ease background-color;}
:root body :is([data-view=calendar], [data-view=day]) :is(a, button, input, textarea, summary, [tabindex]):focus-visible{outline:solid 2px var(--lc-copy); outline-offset:2px !important;}
:root body [data-view=calendar] #calendar-grid .day-cell:focus-visible{outline-color:var(--lc-copy); outline-offset:-2px !important;}
:root body :is([data-view=calendar], [data-view=day]) [aria-selected=true]{background:var(--lc-selected); font-weight:normal;}

/* The existing subject glyph sits beside a fixed-width, tabular value. */
:root body :is([data-view=calendar], [data-view=day]) .stats{gap:var(--space-3); margin-bottom:var(--space-5);}
:root body [data-view=calendar] #calendar-stats{grid-template-columns:repeat(3, var(--track));}
:root body :is([data-view=calendar], [data-view=day]) :is(#calendar-stats, #day-stats) .stat{align-items:center; border-radius:10px; display:grid; gap:var(--space-1) var(--space-2); grid-template-columns:var(--track) 20px 56px; grid-template-rows:28px 16px; min-height:72px; padding:var(--space-3) var(--space-4);}
:root body :is([data-view=calendar], [data-view=day]) :is(#calendar-stats, #day-stats) .stat-label{color:var(--lc-copy); font-size:9pt; grid-column:1; grid-row:1;}
:root body :is([data-view=calendar], [data-view=day]) :is(#calendar-stats, #day-stats) [data-stat-value]{font-size:16.5pt; font-weight:var(--weight-medium); font-variant-numeric:var(--number-style); grid-column:3; grid-row:1; letter-spacing:-.01em; line-height:21pt; margin:0; text-align:right;}
:root body :is([data-view=calendar], [data-view=day]) :is(#calendar-stats, #day-stats) [data-stat-note]{font-size:8.625pt; grid-column:1/-1; grid-row:2; margin:0;}
:root body :is([data-view=calendar], [data-view=day]) [data-card-icon]{background:#0000; border-radius:5px; color:var(--lc-meta); flex-basis:var(--space-5); height:var(--space-5); width:var(--space-5);}
:root body :is([data-view=calendar], [data-view=day]) [data-card-icon] svg{height:var(--space-4); stroke-width:1.9; width:var(--space-4);}
:root body :is([data-view=calendar], [data-view=day]) :is(#calendar-stats, #day-stats) [data-card-icon]{grid-column:2; grid-row:1; margin:0;}

/* A quiet month sheet; today is a local 4% selection, not a coloured tile. */
:root body [data-view=calendar] .calendar-layout{gap:var(--space-3); grid-template-columns:var(--track) 288px;}
:root body [data-view=calendar] .calendar-card{overflow:visible; padding:var(--space-2);}
:root body [data-view=calendar] .calendar-card > h3{border:0; height:40px; margin:0; padding:0 var(--space-2);}
:root body [data-view=calendar] #weekdays{padding:0;}
:root body [data-view=calendar] [data-weekday]{border:0; color:var(--lc-meta); font-size:8.625pt; height:var(--space-8); padding:6px var(--space-2); text-align:left;}
:root body [data-view=calendar] #calendar-grid{gap:2px; min-height:442px; padding:0;}
:root body [data-view=calendar] .day-cell{align-content:start; background:#0000; border:0; border-radius:var(--space-2); box-shadow:none; color:var(--lc-ink); display:grid; gap:var(--space-1); grid-template-columns:var(--track) auto; min-height:72px; padding:var(--space-2); transition:0.14s ease background-color;}
/* Existing app.css uses important hover shadows; keep month cells flat. */
:root body [data-view=calendar] .day-cell:hover{box-shadow:none !important; color:var(--lc-ink); text-decoration-line:none;}
:root body [data-view=calendar] .day-cell:not([data-today]):not([aria-selected=true]):hover{background:var(--lc-hover);}
:root body [data-view=calendar] .day-cell[data-outside]{background:var(--lc-well); color:var(--lc-meta);}
:root body [data-view=calendar] .day-cell[data-today],
:root body [data-view=calendar] .day-cell[data-today]:hover{background:var(--lc-selected); box-shadow:none;}
:root body [data-view=calendar] .day-number{font-size:10.125pt; font-weight:normal; font-variant-numeric:var(--number-style); grid-column:1/-1; line-height:15pt;}
:root body [data-view=calendar] .day-cell[data-today] .day-number{color:var(--lc-ink); font-weight:var(--weight-medium);}
:root body [data-view=calendar] .day-count{color:var(--lc-meta); font-size:8.625pt; font-variant-numeric:var(--number-style); grid-column:1; grid-row:2; line-height:12pt;}
:root body [data-view=calendar] [data-diary-mark]{align-items:baseline; display:flex; gap:var(--space-1); grid-column:1/-1; grid-row:3;}
:root body [data-view=calendar] [data-diary-mark]::before{background:var(--lc-line); border-radius:2px; box-shadow:inset 0 0 0 .5px var(--lc-faint); content:""; flex:0 0 auto; height:10px; width:var(--space-2);}
:root body [data-view=calendar] .dots{gap:var(--space-1); grid-column:2; grid-row:2; max-width:40px;}
:root body [data-view=calendar] .day-cell:has(.day-status .badge) .dots{grid-column:1/-1; grid-row:3; max-width:none;}
:root body [data-view=calendar] .day-cell:has(.day-status .badge) [data-diary-mark]{grid-row:4;}
:root body [data-view=calendar] #calendar-agenda > .card{padding:var(--space-4);}
:root body [data-view=calendar] .month-agenda{gap:var(--space-3);}
:root body [data-view=calendar] .agenda-order{background:#0000; border-radius:var(--space-2); gap:var(--space-2); padding:var(--space-2) 0;}
:root body [data-view=calendar] .agenda-title{align-items:baseline; font-size:10.125pt; gap:6px; line-height:15pt;}
:root body [data-view=calendar] .agenda-title a{word-wrap:anywhere;}
:root body [data-view=calendar] .agenda-order .actions{font-size:9pt; justify-content:space-between;}
:root body [data-view=calendar] .agenda-order .actions > a{color:var(--lc-meta);}
:root body [data-view=calendar] #calendar-legend{gap:6px var(--space-3); margin-top:var(--space-3);}
:root body [data-view=calendar] #calendar-legend > span{gap:var(--space-1);}
:root body [data-view=calendar] #calendar-legend > span:has([data-state=PENDING]) > .dot{background:var(--wait);}
:root body [data-view=calendar] #calendar-legend > span:has([data-state=attention], [data-state=due]) > .dot{background:var(--attention);}

/* One signal, one hue: badges, marks and progress reuse these state tokens. */
:root body :is([data-view=calendar], [data-view=day]) :is(.badge, .pill){background:var(--wait-wash); border:0; border-radius:var(--space-1); box-shadow:none; color:var(--wait); font-size:8.625pt; font-weight:var(--weight-medium); gap:var(--space-1); line-height:12pt; min-height:18px; padding:1px 6px;}
:root body :is([data-view=calendar], [data-view=day]) .badge:is([data-state=LEASED], [data-state=JUDGING], [data-state=running]){background:var(--run-wash); color:var(--run);}
:root body :is([data-view=calendar], [data-view=day]) .badge:is([data-state=SUCCEEDED], [data-state=ok], [data-state=issued]){background:var(--ok-wash); color:var(--ok);}
:root body :is([data-view=calendar], [data-view=day]) .badge:is([data-state=attention], [data-state=due]){background:var(--attention-wash); color:var(--attention);}
:root body :is([data-view=calendar], [data-view=day]) .badge:is([data-state=FAILED], [data-state=DEAD], [data-state=CANCELLED], [data-state=cancelled], [data-state=bad]){background:var(--bad-wash); color:var(--bad);}
:root body :is([data-view=calendar], [data-view=day]) .order-dot{height:14px; width:14px;}
:root body :is([data-view=calendar], [data-view=day]) :is(.cp-graph-status, .cp-graph-progress){margin-right:0;}
:root body :is([data-view=calendar], [data-view=day]) .cp-graph-initials{font-weight:var(--weight-medium);}
:root body :is([data-view=calendar], [data-view=day]) .lead-seat{font-size:9pt; gap:6px; line-height:12pt;}
:root body :is([data-view=calendar], [data-view=day]) .lead-details strong{color:var(--lc-copy); font-size:9pt; font-weight:normal;}
:root body :is([data-view=calendar], [data-view=day]) .lead-details .model{font-size:8.625pt;}

/* Day: scan the work on the left, compose one order on the right. */
:root body [data-view=day] .two-col{gap:var(--space-3); grid-template-columns:minmax(0, 1.25fr) var(--track); margin-bottom:var(--space-5);}
:root body [data-view=day] .stack{display:grid; gap:var(--space-3);}
:root body [data-view=day] .orders{gap:var(--space-2);}
:root body [data-view=day] .card .order{background:#0000; border-radius:var(--space-2); box-shadow:none; padding:var(--space-3); transition:0.14s ease background-color;}
:root body [data-view=day] .card .order:hover{background:var(--lc-hover); box-shadow:none !important; transform:none !important;}
:root body [data-view=day] #day-orders .order{gap:var(--space-2) 10px;}
:root body [data-view=day] #day-orders .card.order{background:#0000; box-shadow:none;}
:root body [data-view=day] #day-orders .card.order:hover{background:var(--lc-hover);}
:root body [data-view=day] #day-orders .order-title{font-size:10.125pt; font-weight:var(--weight-medium); line-height:15pt;}
:root body [data-view=day] .order-title > .order-dot{margin-right:6px;}
:root body [data-view=day] .order-step-caption{color:var(--lc-meta); font-size:9pt; gap:6px;}
:root body [data-view=day] .step-track{background:var(--lc-line); border-radius:2px; height:var(--space-1); margin:0 0 var(--space-2);}
:root body [data-view=day] .step-track > .step-fill{border-radius:2px;}
:root body [data-view=day] .order-problem{background:var(--attention-wash); border:0; border-radius:var(--space-2); color:var(--lc-copy); grid-column:1/-1; padding:var(--space-2);}
:root body [data-view=day] .order-used{color:var(--lc-meta); font-size:9pt;}
:root body [data-view=day] #order-form{gap:var(--space-3);}
:root body [data-view=day] #order-form label{color:var(--lc-copy); font-size:9pt; font-weight:normal; gap:6px; line-height:12pt;}
:root body [data-view=day] #order-form p{margin:0;}
:root body [data-view=day] #form-lead{display:grid; gap:var(--space-2);}
:root body [data-view=day] #order-form :is(textarea, input){background:var(--paper); border:0; border-radius:var(--space-2); box-shadow:var(--lc-shadow); color:var(--lc-ink); font:400 13.5px/20px var(--font); min-height:var(--space-8); padding:6px var(--space-3); transition:0.14s ease box-shadow;}
:root body [data-view=day] #order-form textarea{min-height:80px;}
:root body [data-view=day] #order-form :is(textarea, input):enabled:hover,
:root body [data-view=day] #order-form :is(textarea, input):focus-visible{background:var(--paper); box-shadow:var(--lc-raised); outline:none;}
:root body [data-view=day] #order-form :is(textarea, input):disabled{background:var(--lc-well); box-shadow:inset 0 0 0 .5px var(--lc-line); color:var(--lc-meta);}
:root body [data-view=day] #order-form :is(textarea, input)::placeholder{color:var(--lc-meta); opacity:1;}
:root body [data-view=day] .pair{gap:var(--space-3); grid-template-columns:var(--track) 88px;}
:root body [data-view=day] #f-budget{font-variant-numeric:var(--number-style); text-align:right;}
:root body [data-view=day] #f-send{background:var(--lc-ink); border:0; border-radius:7px; box-shadow:none; color:var(--paper); font-size:10.125pt; font-weight:var(--weight-medium); line-height:15pt; min-height:28px; padding:var(--space-1) 10px;}
:root body [data-view=day] #f-send:enabled:hover{background:rgb(0 0 0 / .80); box-shadow:none; transform:none;}
:root body [data-view=day] #day-readonly{background:var(--lc-well); border-radius:var(--space-2); color:var(--lc-copy); padding:var(--space-2);}
:root body [data-view=day] #plan-result:empty{margin:0;}

/* Diary: fixed numeric columns, light row rhythm, full sentences and sources. */
:root body [data-view=day] [data-day-diary] > .hint{margin:0 0 var(--space-5);}
:root body [data-view=day] .diary-family + .diary-family{margin-top:var(--space-5);}
:root body [data-view=day] .diary-family .group-heading{align-items:baseline; display:flex; flex-wrap:wrap; font-size:10.125pt; font-weight:var(--weight-medium); gap:6px; line-height:15pt; margin:0 0 var(--space-2); min-height:var(--space-8);}
:root body [data-view=day] .diary-family .scroll{border-radius:var(--space-2); margin-bottom:var(--space-3); overflow-x:auto;}
:root body [data-view=day] .diary-family table{border-collapse:separate; border-spacing:0; font-size:9pt; line-height:15pt; min-width:1060px; table-layout:fixed; width:100%;}
:root body [data-view=day] .diary-family :is(th, td){border:0; border-radius:0; font-weight:normal; padding:var(--space-2) 6px; vertical-align:middle;}
:root body [data-view=day] .diary-family th{background:var(--lc-well); color:var(--lc-meta); font-size:8.625pt; height:48px; line-height:12pt;}
:root body [data-view=day] .diary-family :is(th, td):first-child{padding-left:var(--space-3); text-align:left; width:180px;}
:root body [data-view=day] .diary-family :is(th, td):not(:first-child){font-variant-numeric:var(--number-style); text-align:right; width:88px;}
:root body [data-view=day] .diary-family td{color:var(--lc-copy); height:40px;}
:root body [data-view=day] .diary-family tbody tr{background:#0000; transition:0.14s ease background-color;}
:root body [data-view=day] .diary-family tbody tr:nth-child(even){background:var(--lc-well);}
:root body [data-view=day] .diary-family tbody tr:hover{background:var(--lc-hover);}
:root body [data-view=day] .diary-family .cell-text{font-size:9pt; line-height:15pt; overflow:visible; word-wrap:anywhere; white-space:normal;}
/* These quiet glyphs identify the metric's unit, without inventing a trend. */
:root body [data-view=day] td[data-metric]::before{background:var(--lc-line); border-radius:2px; box-shadow:inset 0 0 0 .5px var(--lc-faint); content:""; display:inline-block; height:var(--space-2); margin-right:var(--space-1); vertical-align:baseline; width:var(--space-2);}
:root body [data-view=day] td:is([data-metric=claim_delay], [data-metric=first_word_delay], [data-metric=max_silence], [data-metric=total_s])::before{background:conic-gradient(from 0deg, var(--lc-faint) 0deg 90deg, #0000 90deg); border-radius:50%;}
:root body [data-view=day] td[data-metric=first_pass]::before{border-radius:50%;}
:root body [data-view=day] .diary-family .ledger{display:grid; gap:0; margin:0;}
:root body [data-view=day] .diary-family .ledger li{align-items:baseline; border:0; border-radius:var(--space-2); font-size:9pt; gap:var(--space-3); grid-template-columns:28px 72px 144px var(--track); line-height:15pt; min-height:40px; padding:10px var(--space-2); transition:0.14s ease background-color;}
:root body [data-view=day] .diary-family .ledger li:hover{background:var(--lc-hover);}
:root body [data-view=day] .diary-family .seq{color:var(--lc-faint); font-size:8.625pt; font-variant-numeric:var(--number-style); text-align:right;}
:root body [data-view=day] .diary-family time{color:var(--lc-meta); font-size:8.625pt; font-variant-numeric:var(--number-style);}
:root body [data-view=day] .diary-family .kind{color:var(--lc-meta); font-size:8.625pt; word-wrap:anywhere;}
:root body [data-view=day] .diary-family .what{color:var(--lc-copy); font-size:10.125pt; line-height:15pt; white-space:pre-line;}
:root body [data-view=day] .diary-family .what small{color:var(--lc-meta); display:block; font-size:8.625pt; line-height:12pt; margin-top:var(--space-1); word-wrap:anywhere;}

/* Empty, loading and error are deliberate fillings of the same content slots. */
:root body :is([data-view=calendar], [data-view=day]) .empty{background:var(--lc-well); border-radius:var(--space-2); flex-direction:column; gap:var(--space-2); justify-content:center; min-height:144px; padding:var(--space-4); text-align:center;}
:root body [data-view=day] #day-plans .empty{padding:var(--space-4);}
:root body :is([data-view=calendar], [data-view=day]) .empty .empty-art{background:var(--lc-selected); border-radius:10px; filter:none; flex:0 0 auto; height:42px; padding:0; width:42px;}
:root body :is([data-view=calendar], [data-view=day]) .empty-art .empty-tone{fill:var(--lc-faint) !important; stroke:none;}
:root body :is([data-view=calendar], [data-view=day]) .empty-art .empty-detail{stroke:var(--lc-copy); stroke-width:2.6;}
:root body :is([data-view=calendar], [data-view=day]) .empty-art ellipse{fill:var(--lc-faint); filter:none;}
:root body :is([data-view=calendar], [data-view=day]) .empty strong{color:var(--lc-copy); font-size:10.125pt; font-weight:var(--weight-medium); line-height:15pt;}
:root body :is([data-view=calendar], [data-view=day]) .empty p{color:var(--lc-meta); font-size:9pt; line-height:13.5pt; margin:var(--space-1) 0 var(--space-2);}
:root body :is([data-view=calendar], [data-view=day]) .empty-action{align-items:center; background:var(--paper); border-radius:7px; box-shadow:var(--lc-shadow); color:var(--lc-copy); display:inline-flex; font-size:9pt; min-height:28px; padding:var(--space-1) 10px; transition:0.14s ease box-shadow;}
:root body :is([data-view=calendar], [data-view=day]) .empty-action:hover{box-shadow:var(--lc-raised); color:var(--lc-ink); text-decoration-line:none;}
:root body :is([data-view=calendar], [data-view=day]) .skeleton{background:var(--lc-well); border-radius:var(--space-2); gap:var(--space-3); min-height:144px; padding:var(--space-4);}
:root body :is([data-view=calendar], [data-view=day]) .skeleton span{background:var(--lc-line); border-radius:6px; height:var(--space-4); width:100%;}
:root body :is([data-view=calendar], [data-view=day]) .skeleton span:first-child{height:var(--space-5); width:48%;}
:root body :is([data-view=calendar], [data-view=day]) .skeleton span:last-child{height:var(--space-4); width:72%;}
:root body :is([data-view=calendar], [data-view=day]) .skeleton span{overflow:hidden; position:relative;}
:root[data-motion=on] body :is([data-view=calendar], [data-view=day]) .skeleton span::after{animation:lc-skeleton 1.6s cubic-bezier(.22, 1, .36, 1) infinite; background:linear-gradient(90deg, #0000, rgb(255 255 255 / .6), #0000); content:""; inset:0; position:absolute;}
:root body [data-view=calendar] #calendar-grid > .skeleton{background:repeating-linear-gradient(.25turn, #0000 0, #0000 calc(100% / 7 - 2px), var(--paper) calc(100% / 7 - 2px), var(--paper) calc(100% / 7)), repeating-linear-gradient(.5turn, var(--lc-well) 0, var(--lc-well) 72px, var(--paper) 72px, var(--paper) 74px); grid-column:1/-1; min-height:442px;}
:root body [data-view=day] #day-stats:has(> .skeleton){grid-template-columns:1fr;}
:root body [data-view=day] #day-stats > .skeleton{align-items:center; grid-template-columns:repeat(4, 1fr); min-height:72px;}
:root body [data-view=day] #day-stats > .skeleton span{height:var(--space-4); width:100%;}
:root body [data-view=day] #day-stats > .skeleton::after{background:var(--lc-line); border-radius:6px; content:""; height:var(--space-4);}
:root body [data-view=day] #day-diary > .skeleton{min-height:240px;}
:root body [data-view=day] :is([data-diary-error], .result[data-state=bad], .form-error){background:var(--bad-wash); border:0; border-radius:var(--space-2); color:var(--bad); font-size:9pt; line-height:15pt; word-wrap:anywhere; padding:var(--space-2) var(--space-3);}
:root body [data-view=day] [data-diary-error]{margin:0 0 var(--space-3);}

/* Small objects fade; hover changes one paint property. Respect the existing
   runtime motion preference instead of adding another media query. */
@keyframes lc-arrive{ 0%{opacity:0;} 100%{opacity:1;} }
@keyframes lc-skeleton{ 0%{transform:translateX(-100%);} 60%, 100%{transform:translateX(100%);} }
:root body :is([data-view=calendar], [data-view=day]) [data-enter=card]{transform:none;}
:root[data-motion=on] body :is([data-view=calendar], [data-view=day]) [data-enter=card]{animation:lc-arrive 200ms ease both;}
:root body :is([data-view=calendar], [data-view=day]) .cp-motion-layer{transform:none !important;}
:root[data-motion=reduce] body :is([data-view=calendar], [data-view=day]) :is([data-enter], .cp-graph-status, .cp-motion-layer){animation:none;}
