cat > 'web/look-home.css' <<'OC_EOF_96'
/* Home: ui-foundation's ink, surface, spacing and interaction hierarchy.
   Shell overrides apply only while Home is visible. No route or data changes. */
:root body{--accent:#0070d6; --accent-wash:rgb(0 112 214 / .10); --attention:#b25e00; --attention-wash:rgb(242 138 46 / .16); --bad:#b53c35; --bad-wash:rgb(181 60 53 / .10); --canvas:#f8f8f8; --ease:cubic-bezier(.22, 1, .36, 1); --home-card:0 0 0 .5px rgb(0 0 0 / .06), 0 1px 1px -1px rgb(0 0 0 / .10), 0 1px 2px rgb(0 0 0 / .05); --home-faint:rgb(0 0 0 / .27); --home-hover:rgb(0 0 0 / .03); --home-ink:rgb(0 0 0 / .88); --home-line:rgb(0 0 0 / .06); --home-muted:rgb(0 0 0 / .45); --home-raised:0 0 0 .5px rgb(0 0 0 / .10), 0 1px 1px -1px rgb(0 0 0 / .10), 0 2px 6px -1px rgb(0 0 0 / .08); --home-selected:rgb(0 0 0 / .04); --home-text:rgb(0 0 0 / .61); --ink:var(--home-ink); --ink-16:var(--home-line); --ink-2:var(--home-text); --ink-28:var(--home-faint); --ink-3:var(--home-muted); --ink-38:var(--home-faint); --ink-58:var(--home-muted); --ink-66:var(--home-muted); --ink-68:var(--home-muted); --ink-70:var(--home-muted); --ink-72:var(--home-muted); --ink-76:var(--home-text); --ink-80:var(--home-text); --ink-86:var(--home-ink); --ink-92:var(--home-ink); --leading-display:28px; --leading-lg:24px; --leading-md:20px; --leading-sm:20px; --leading-xs:16px; --lift-1:var(--home-card); --lift-2:var(--home-card); --lift-3:var(--home-raised); --line:var(--home-line); --line-2:var(--home-line); --mono-ink:var(--home-text); --motion:140ms; --ok:#006dcb; --ok-wash:rgb(0 112 214 / .10); --paper:#fff; --round-button:6px; --round-card:12px; --round-chip:4px; --round-control:8px; --round-hero:12px; --round-icon:6px; --run:#006dcb; --run-wash:rgb(0 112 214 / .10); --shadow:var(--home-card); --shadow-small:var(--home-card); --skeleton:var(--home-line); --space-section:20px; --text-caption:12px; --text-copy:13.5px; --text-display:22px; --text-emphasis:13.5px; --text-headline:22px; --text-hero-stat:22px; --text-lg:17px; --text-md:13.5px; --text-micro:11.5px; --text-sm:13.5px; --text-stat:22px; --text-unit:11.5px; --text-xl:17px; --text-xs:12px; --time:var(--home-muted); --tone-amber:#f28a2e; --tone-blue:#4fb0fe; --tone-green:#0190fe; --tone-indigo:rgb(0 0 0 / .27); --tone-red:#ce625b; --wait:var(--home-text); --wait-wash:var(--home-selected); --wash:var(--home-selected); --well:rgb(0 0 0 / .02); background:var(--canvas); color:var(--home-text); font-size:10.125pt; font-weight:normal; grid-template-columns:272px var(--track); letter-spacing:0; line-height:15pt;}

/* A white sheet on a quiet rail; the status area has its own readable row. */
:root body .workspace{background:var(--paper); border-radius:var(--space-3); box-shadow:var(--home-card); margin:var(--space-2) var(--space-2) var(--space-2) 0; padding:var(--space-5);}
:root body nav[data-nav]{padding:var(--space-5) var(--space-3);}
:root body .rail-brand{color:var(--home-ink); font-size:16.5pt; font-weight:var(--weight-medium); padding:var(--space-2) var(--space-2) var(--space-5);}
:root body .rail-brand span{font-size:10.125pt; font-weight:normal;}
:root body #nav-links{gap:2px;}
:root body nav a{background:#0000; border-radius:var(--space-2); box-shadow:none; color:var(--home-text); font-weight:normal; gap:var(--space-2); min-height:var(--space-8); padding:6px var(--space-2); transition:0.14s ease background-color;}
:root body nav a:not([aria-current=page]):hover{background:var(--home-hover); color:var(--home-ink);}
:root body nav a[aria-current=page]{background:rgb(0 0 0 / .06); box-shadow:none; color:var(--home-ink); font-weight:var(--weight-medium);}
:root body nav a .glyph{color:inherit; height:var(--space-4); width:var(--space-4);}
:root body .rail-note{font-size:9pt; margin-inline:var(--space-2);}
:root body .top{border:0; box-shadow:inset 0 -.5px 0 var(--home-line); display:grid; gap:var(--space-3); grid-template-columns:var(--track); margin:0 0 var(--space-5); padding:0 0 var(--space-3);}
:root body .brand{align-items:baseline; display:flex; flex-wrap:wrap; gap:var(--space-2) var(--space-3);}
:root body .brand .eyebrow{color:var(--home-muted); font-weight:normal; margin:0;}
:root body .brand h1{color:var(--home-ink); font-size:12.75pt; font-weight:var(--weight-medium); line-height:18pt;}
:root body .brand .sub{font-size:8.625pt; margin:0 0 0 auto;}
:root body .meters{gap:var(--space-2);}
:root body .meters :is(.pill, .meter){border-radius:6px; box-shadow:none; font-size:8.625pt; font-weight:normal; line-height:12pt; min-height:var(--space-6); padding:var(--space-1) 6px;}
:root body .meters .pill:not([data-state]){background:var(--home-selected); color:var(--home-text);}
:root body #status-chip{background:var(--home-selected); color:var(--home-text); gap:6px; white-space:normal;}
:root body #status-chip:hover{background:var(--home-line); text-decoration-line:none;}
:root body #status-chip strong{color:var(--home-ink); font-weight:var(--weight-medium);}
:root body #status-chip[data-link=down]{background:var(--bad-wash); color:var(--bad);}
:root body:has([data-view=home]:not([hidden])) #run-activity[data-work-state=running]{background:var(--run-wash); color:var(--run);}
:root body:has([data-view=home]:not([hidden])) #run-activity[data-work-state=attention]{background:var(--attention-wash); color:var(--attention);}
:root body:has([data-view=home]:not([hidden])) #top-links{gap:6px; margin-left:auto;}
:root body:has([data-view=home]:not([hidden])) .icon-link{border-radius:6px; box-shadow:var(--home-card); color:var(--home-text); padding:6px;}
:root body .foot{color:var(--home-muted); font-size:8.625pt;}

/* Four ink tiers; emphasis changes one weight, never a new grey or heavy bold. */
:root body [data-view=home]:not([hidden]){color:var(--home-text); font-size:10.125pt; font-weight:normal; line-height:15pt;}
:root body [data-view=home]:not([hidden]) :is(strong, b, label, h3, h4, button, .button, .order-title, .seat-name){font-weight:var(--weight-medium);}
:root body [data-view=home]:not([hidden]) :is(h3, .section-heading){color:var(--home-ink); font-size:12.75pt; letter-spacing:0; line-height:18pt;}
:root body [data-view=home]:not([hidden]) h3{gap:var(--space-2); margin:0 0 var(--space-2);}
:root body [data-view=home]:not([hidden]) .section-heading{margin:var(--space-5) 0 var(--space-2);}
:root body [data-view=home]:not([hidden]) :is(p, .drawing-caption){margin:var(--space-2) 0;}
:root body [data-view=home]:not([hidden]) :is(.hint, small, .drawing-caption, .seat-model, .lead-details .model, [data-stat-note], .seat-now){color:var(--home-muted); font-size:9pt; line-height:12pt;}
:root body [data-view=home]:not([hidden]) :is(time, code, .mono, .number-unit, .step-label){color:var(--home-muted); font-size:8.625pt; font-variant-numeric:var(--number-style); line-height:15pt;}
:root body [data-view=home]:not([hidden]) :is(.order-title, .seat-name, .lead-details strong, .home-entry strong){color:var(--home-ink); font-size:10.125pt; line-height:15pt;}
:root body [data-view=home]:not([hidden]) a{color:var(--home-text); text-decoration-line:none; transition:color 140ms ease;}
:root body [data-view=home]:not([hidden]) a:hover{color:var(--home-ink);}
:root body [data-view=home]:not([hidden]) :is(.block-head, .actions, .hero-actions){gap:var(--space-2);}
:root body [data-view=home]:not([hidden]) .block-head{margin-bottom:var(--space-2);}
:root body [data-view=home]:not([hidden]) .block-head h3{margin:0;}
:root body [data-view=home]:not([hidden]) .block-head > :is(a, span){font-size:9pt;}

/* Twelve between cards, sixteen inside, eight within a content group. */
:root body [data-view=home]:not([hidden]) :is(.home-row, .team, .stats, .home-library-grid, .home-proposal-list){gap:var(--space-3);}
:root body [data-view=home]:not([hidden]) :is(.home-row, .home-compose-row){margin-bottom:var(--space-3);}
:root body [data-view=home]:not([hidden]) .home-work-row{min-height:0;}
:root body [data-view=home]:not([hidden]) .home-overview{margin-top:0;}
:root body [data-view=home]:not([hidden]) .card{background:var(--paper); background-image:none; border:0; border-radius:var(--space-3); box-shadow:var(--home-card); margin-bottom:var(--space-3); padding:var(--space-4);}
:root body [data-view=home]:not([hidden]) .home-row > .card,
:root body [data-view=home]:not([hidden]) .home-row > div > .card,
:root body [data-view=home]:not([hidden]) .home-overview > div > div > .card,
:root body [data-view=home]:not([hidden]) .home-compose-row > .card{margin-bottom:0; padding:var(--space-4);}
:root body [data-view=home]:not([hidden]) .home-overview > div{display:grid; gap:var(--space-3);}
:root body [data-view=home]:not([hidden]) .card .card{border-radius:var(--space-2);}

/* The hero keeps its aurora and the gradient date: the one place of colour on the page (owner, 2026-11-22). */
:root body [data-view=home]:not([hidden]) .hero{border-radius:var(--space-3); margin-bottom:var(--space-3); padding:var(--space-4) var(--space-4) 48px;}
:root body [data-view=home]:not([hidden]) .ui-gf-bleed{animation:none; will-change:auto;}
:root body [data-view=home]:not([hidden]) #hero-art{display:block; height:96px; inset:0 0 auto auto; width:32%;}
:root body [data-view=home]:not([hidden]) .hero-art{opacity:.27;}
:root body [data-view=home]:not([hidden]) .hero-art :is(.hero-art-blue, .hero-art-warm){stroke:var(--home-muted);}
:root body [data-view=home]:not([hidden]) .hero .page-head{gap:var(--space-3); margin:0 0 var(--space-3);}
:root body [data-view=home]:not([hidden]) .hero h2{font-size:16.5pt; font-weight:var(--weight-heading); letter-spacing:-.01em; line-height:21pt;}
:root body [data-view=home]:not([hidden]) .hero .eyebrow{color:var(--home-muted); font-size:9pt; font-weight:normal; line-height:12pt; margin:0 0 var(--space-2);}
:root body [data-view=home]:not([hidden]) #hero-sentence{color:var(--home-text); font-size:10.125pt; line-height:15pt; margin:var(--space-2) 0 0;}
:root body [data-view=home]:not([hidden]) .hero .stats{margin:0;}
:root body [data-view=home]:not([hidden]) .hero .stat{-webkit-backdrop-filter:none; align-content:start; backdrop-filter:none; border-radius:10px; box-shadow:var(--home-card); display:grid; gap:var(--space-2); grid-template-columns:var(--track) 48px; margin:0; padding:var(--space-4);}
:root body [data-view=home]:not([hidden]) .hero .stat-label{color:var(--home-muted); font-size:9pt; grid-column:1 / -1; line-height:12pt; padding:0;}
:root body [data-view=home]:not([hidden]) .hero [data-stat-value]{color:var(--home-ink); font-size:16.5pt; font-weight:var(--weight-medium); grid-column:1; grid-row:2; letter-spacing:-.01em; line-height:21pt; margin:0;}
:root body [data-view=home]:not([hidden]) .hero .stat > [data-card-icon]{grid-column:2; grid-row:2; justify-self:end; position:static;}
:root body [data-view=home]:not([hidden]) .hero [data-stat-note]{grid-column:1 / -1; margin:0; min-height:var(--space-8);}
:root body [data-view=home]:not([hidden]) .hero .stat-chart{border-radius:2px; grid-column:1 / -1; height:var(--space-1); margin:0; width:100%;}
:root body [data-view=home]:not([hidden]) .hero .stat::after{background:var(--home-line); border-radius:2px; grid-column:1 / -1; margin:0;}
:root body [data-view=home]:not([hidden]) [data-card-icon],
:root body [data-view=home]:not([hidden]) .hero .stat > [data-card-icon]{background:var(--home-selected); border-radius:6px; box-shadow:none; color:var(--home-muted); flex-basis:28px; height:28px; width:28px;}
:root body [data-view=home]:not([hidden]) [data-card-icon] svg{height:var(--space-4); stroke-width:1.9; width:var(--space-4);}
:root body [data-view=home]:not([hidden]) .hero [data-stat=attention][data-stat-alert=true] > [data-card-icon]{background:var(--attention-wash); color:var(--attention);}

/* Controls: one dark action, white secondary buttons, quiet flat segments. */
:root body [data-view=home]:not([hidden]) :is(button, .button){background:var(--paper); background-image:none; border:0; border-radius:6px; box-shadow:var(--home-card); color:var(--home-text); font-size:10.125pt; gap:6px; line-height:15pt; min-height:28px; padding:var(--space-1) 10px; transform:none; transition:0.14s ease box-shadow;}
:root body [data-view=home]:not([hidden]) :is(button, .button):enabled:hover{background:var(--paper); box-shadow:var(--home-raised); color:var(--home-ink); transform:none;}
:root body [data-view=home]:not([hidden]) #compose-submit{background:var(--home-ink); border-radius:6px; box-shadow:none; color:var(--paper); min-height:28px; transition:0.14s ease background-color;}
:root body [data-view=home]:not([hidden]) #compose-submit:enabled:hover{background:rgb(0 0 0 / .80); color:var(--paper);}
:root body [data-view=home]:not([hidden]) #home-day-link button{background:var(--paper); border-radius:6px; box-shadow:var(--home-card); color:var(--home-text); min-height:28px;}
:root body [data-view=home]:not([hidden]) #home-day-link button:hover{background:var(--paper); box-shadow:var(--home-raised); color:var(--home-ink);}
:root body [data-view=home]:not([hidden]) button:disabled{cursor:default; opacity:.4; transform:none;}
:root body [data-view=home]:not([hidden]) :is(.order-filters, .feed-filters){gap:2px; margin-bottom:var(--space-2);}
:root body [data-view=home]:not([hidden]) :is(button.quiet, .button.quiet, .show-all){background:#0000; box-shadow:none; color:var(--home-text); transition:0.14s ease background-color;}
:root body [data-view=home]:not([hidden]) :is(button.quiet, .button.quiet):not([aria-pressed=true]):not(:disabled):hover{background:var(--home-hover); box-shadow:none; color:var(--home-ink);}
:root body [data-view=home]:not([hidden]) :is(.order-filters, .feed-filters) button{font-size:9pt; font-weight:normal; line-height:15pt; padding:var(--space-1) var(--space-2);}
:root body [data-view=home]:not([hidden]) :is(.order-filters, .feed-filters) [aria-pressed=true],
:root body [data-view=home]:not([hidden]) :is(.order-filters, .feed-filters) [aria-pressed=true]:hover{background:var(--home-selected); box-shadow:none; color:var(--home-ink); font-weight:normal;}
:root body [data-view=home]:not([hidden]) :is(a, button, summary, [tabindex]):focus-visible{outline:solid 1.5px var(--home-text); outline-offset:2px;}
:root body [data-view=home]:not([hidden]) :is(input, textarea, select){background:var(--paper); border:0; border-radius:var(--space-2); box-shadow:var(--home-card); color:var(--home-ink); font:400 13.5px/20px var(--font); padding:6px var(--space-3); transition:0.14s ease box-shadow;}
:root body [data-view=home]:not([hidden]) :is(input, textarea, select):is(:focus-visible, :hover){background:var(--paper); box-shadow:var(--home-raised); outline:none;}
:root body [data-view=home]:not([hidden]) :is(textarea, input)::placeholder{color:var(--home-muted);}
:root body [data-view=home]:not([hidden]) #compose-form{align-items:start; gap:var(--space-3);}
:root body [data-view=home]:not([hidden]) label{color:var(--home-text); font-size:9pt; gap:var(--space-2);}
:root body [data-view=home]:not([hidden]) #compose-title{min-height:var(--space-8);}
:root body [data-view=home]:not([hidden]) #compose-goal{min-height:64px;}
:root body [data-view=home]:not([hidden]) #compose-lead{align-items:center; display:flex; gap:var(--space-3);}
:root body [data-view=home]:not([hidden]) #compose-lead > .hint{margin:0; max-width:300px;}
:root body [data-view=home]:not([hidden]) #compose-form > .actions{align-self:end; gap:var(--space-2);}
:root body [data-view=home]:not([hidden]) #compose-form > .actions .hint{color:var(--home-faint); font-size:8.625pt;}
:root body [data-view=home]:not([hidden]) .compose-examples{gap:6px; margin-bottom:var(--space-3);}
:root body [data-view=home]:not([hidden]) #compose-library{font-size:9pt; line-height:12pt;}
:root body [data-view=home]:not([hidden]) #compose-library :is(p, .hint){margin:0;}

/* State is one hue in two strengths, consistently across labels and marks. */
:root body [data-view=home]:not([hidden]) :is(.pill, .badge, .kind-chip){border:0; border-radius:var(--space-1); box-shadow:none; font-size:8.625pt; font-weight:normal; gap:var(--space-1); line-height:12pt; min-height:18px; padding:1px 6px;}
:root body [data-view=home]:not([hidden]) :is(.pill, .badge):not([data-state]){background:var(--home-selected); color:var(--home-text);}
:root body [data-view=home]:not([hidden]) :is(.pill, .badge):is([data-state=working], [data-state=running], [data-state=LEASED], [data-state=JUDGING], [data-state=SUCCEEDED], [data-state=ok], [data-state=accepted]){background:var(--run-wash); color:var(--run);}
:root body [data-view=home]:not([hidden]) :is(.pill, .badge):is([data-state=attention], [data-state=proposed], [data-state=due]){background:var(--attention-wash); color:var(--attention);}
:root body [data-view=home]:not([hidden]) :is(.pill, .badge):is([data-state=FAILED], [data-state=DEAD], [data-state=CANCELLED], [data-state=bad], [data-state=rejected]){background:var(--bad-wash); color:var(--bad);}
:root body [data-view=home]:not([hidden]) .kind-chip{background:var(--home-selected); color:var(--home-text);}
:root body [data-view=home]:not([hidden]) .seat-chip{background:#0000; color:var(--home-text); font-size:9pt; font-weight:normal; line-height:15pt;}
:root body [data-view=home]:not([hidden]) :is(.cp-graph-initials, .ring-value){font-weight:var(--weight-medium);}

/* Chart ink stays thin; values align in stable columns beside actual marks. */
:root body [data-view=home]:not([hidden]) .home-overview [data-chart]{display:grid; gap:var(--space-2); grid-template-columns:var(--track);}
:root body [data-view=home]:not([hidden]) .home-overview [data-chart] > *{grid-column:1; grid-row:auto; margin:0;}
:root body [data-view=home]:not([hidden]) .home-overview [data-chart] .chart-counts{display:grid; gap:var(--space-3); grid-column:1; grid-row:auto; grid-template-columns:repeat(3, var(--track)); margin:0; position:static;}
:root body [data-view=home]:not([hidden]) .chart-counts > span{align-items:center; color:var(--home-muted); font-size:8.625pt; gap:6px; line-height:12pt;}
:root body [data-view=home]:not([hidden]) .chart-counts strong{color:var(--home-ink); font-size:9pt; font-weight:normal; font-variant-numeric:var(--number-style); line-height:12pt;}
:root body [data-view=home]:not([hidden]) .chart-counts svg{flex:0 0 auto; height:14px; width:14px;}
:root body [data-view=home]:not([hidden]) .home-overview .run-chart{height:168px; width:100%;}
:root body [data-view=home]:not([hidden]) .run-chart .chart-line{stroke:var(--tone-blue); stroke-width:1.5px; vector-effect:non-scaling-stroke;}
:root body [data-view=home]:not([hidden]) .run-chart .chart-grid{stroke:var(--home-line); stroke-width:.5px; stroke-dasharray:none;}
:root body [data-view=home]:not([hidden]) .run-chart .axis-label{fill:var(--home-muted); font-size:8.625pt;}
:root body [data-view=home]:not([hidden]) .chart-area{opacity:.45;}
:root body [data-view=home]:not([hidden]) .home-overview [data-run-meter]{gap:var(--space-2) var(--space-3); grid-template-columns:112px var(--track);}
:root body [data-view=home]:not([hidden]) [data-run-meter] > h3{margin:0;}
:root body [data-view=home]:not([hidden]) .home-overview [data-run-meter] > svg{height:112px; width:112px;}
:root body [data-view=home]:not([hidden]) .meter-ring-track{stroke:var(--home-line);}
:root body [data-view=home]:not([hidden]) .meter-ring-fill{stroke:var(--tone-blue);}
:root body [data-view=home]:not([hidden]) .ring-value{fill:var(--home-ink); font-size:16.5pt;}
:root body [data-view=home]:not([hidden]) .meter-label{align-items:baseline; display:grid; font-size:8.625pt; gap:var(--space-1); grid-template-columns:var(--track) 48px; line-height:12pt;}
:root body [data-view=home]:not([hidden]) .meter-label strong{color:var(--home-ink); font-weight:normal; text-align:right;}
:root body [data-view=home]:not([hidden]) :is(.thin-track, .progress-track, .step-track){background:var(--home-line); border-radius:2px; height:var(--space-1);}
:root body [data-view=home]:not([hidden]) [data-meter-fill]{background:var(--tone-blue); border-radius:2px;}
:root body [data-view=home]:not([hidden]) [data-meter=seats] [data-meter-fill]{background:var(--tone-blue);}

/* The week is seven equal positions, selected lightly at the content level. */
:root body [data-view=home]:not([hidden]) [data-week]{display:grid; gap:var(--space-2); grid-template-columns:1fr;}
:root body [data-view=home]:not([hidden]) [data-week] h3{margin:0;}
:root body [data-view=home]:not([hidden]) .week-strip{gap:2px; grid-column:1; grid-row:auto; grid-template-columns:repeat(7, var(--track)) !important;}
:root body [data-view=home]:not([hidden]) .week-cell{background:#0000; box-shadow:none; margin:0; padding:0;}
:root body [data-view=home]:not([hidden]) .week-day{align-items:center; background:#0000; border:0; border-radius:var(--space-2); box-shadow:none; display:flex; flex-direction:column; font-size:8.625pt; gap:var(--space-1); min-height:96px; padding:var(--space-2) var(--space-1); transition:0.14s ease background-color;}
:root body [data-view=home]:not([hidden]) .week-day > strong{color:var(--home-ink); font-size:12.75pt; font-weight:var(--weight-medium); line-height:18pt;}
:root body [data-view=home]:not([hidden]) .week-day:not([aria-current=date]):hover{background:var(--home-hover);}
:root body [data-view=home]:not([hidden]) .week-day[aria-current=date],
:root body [data-view=home]:not([hidden]) .week-day[aria-current=date]:hover{background:var(--home-selected); box-shadow:none; color:var(--home-text);}
:root body [data-view=home]:not([hidden]) .week-day:hover{box-shadow:none !important;}
:root body [data-view=home]:not([hidden]) .today-tag{background:#0000; color:var(--home-muted); font-size:8.625pt; font-weight:normal; padding:0; position:static;}
:root body [data-view=home]:not([hidden]) .week-track{background:#0000; flex-wrap:wrap; gap:2px; height:auto; margin:0; min-height:var(--space-3);}
:root body [data-view=home]:not([hidden]) .week-track > span{background:#0000;}
:root body [data-view=home]:not([hidden]) .week-legend{gap:6px; grid-column:1; grid-row:auto; justify-self:start;}

/* Orders and results: flat rows, meaningful progress, no nested card grids. */
:root body [data-view=home]:not([hidden]) .orders{gap:2px;}
:root body [data-view=home]:not([hidden]) .card.order-box{background:#0000; border-radius:var(--space-2); box-shadow:none; margin:0; padding:0;}
:root body [data-view=home]:not([hidden]) .card.order-box:hover{background:var(--home-hover); box-shadow:none !important;}
:root body [data-view=home]:not([hidden]) .order-box > .order{background:#0000; border-radius:var(--space-2); box-shadow:none; gap:var(--space-2); padding:var(--space-3); transform:none;}
:root body [data-view=home]:not([hidden]) .order-box > .order:hover{box-shadow:none; transform:none;}
:root body [data-view=home]:not([hidden]) .order-step-caption{gap:var(--space-3);}
:root body [data-view=home]:not([hidden]) .step-label{min-width:92px; text-align:right;}
:root body [data-view=home]:not([hidden]) .results-summary{gap:var(--space-2);}
:root body [data-view=home]:not([hidden]) [data-results-count]{color:var(--home-ink); font-size:16.5pt; font-weight:var(--weight-medium); line-height:21pt; min-width:28px;}
:root body [data-view=home]:not([hidden]) .results-file{border:0; gap:var(--space-2); grid-template-columns:var(--track) 92px 92px; min-height:40px; padding:var(--space-2) 0;}
:root body [data-view=home]:not([hidden]) .results-file > .hint{font-size:8.625pt; font-variant-numeric:var(--number-style); text-align:right;}
:root body [data-view=home]:not([hidden]) .result-author .seat-chip{font-size:8.625pt;}
:root body [data-view=home]:not([hidden]) .result-author .seat-icon{height:var(--space-4); width:var(--space-4);}

/* Team identity is a small mark; neutral headers keep the model names legible. */
:root body [data-view=home]:not([hidden]) .card.home-seat{background:var(--paper); border-radius:var(--space-2); box-shadow:var(--home-card); gap:var(--space-2); margin:0; padding:var(--space-3); transition:0.14s ease box-shadow;}
:root body [data-view=home]:not([hidden]) .home-seat:has(a):hover{box-shadow:var(--home-raised) !important; transform:none;}
:root body [data-view=home]:not([hidden]) .home-seat:focus-within{outline:none;}
:root body [data-view=home]:not([hidden]) .card > .seat-band{background:#0000; box-shadow:none; padding:0;}
:root body [data-view=home]:not([hidden]) .seat-band :is(.seat-name, strong){color:var(--home-ink);}
:root body [data-view=home]:not([hidden]) .seat-band .seat-icon{border-radius:6px; box-shadow:none; height:28px; width:28px;}
:root body [data-view=home]:not([hidden]) .seat-band .seat-model{margin-top:var(--space-1);}
:root body [data-view=home]:not([hidden]) .seat-summary{gap:var(--space-2) var(--space-3); grid-template-columns:repeat(2, var(--track));}
:root body [data-view=home]:not([hidden]) .seat-summary > div{align-items:baseline; background:#0000; display:grid; font-size:8.625pt; gap:6px; grid-template-columns:48px var(--track); line-height:15pt; padding:0;}
:root body [data-view=home]:not([hidden]) .seat-summary strong{color:var(--home-faint); font-size:9pt; font-weight:normal; line-height:15pt; text-align:right;}
:root body [data-view=home]:not([hidden]) .seat-summary [data-seat-summary=seconds] strong{color:var(--home-muted);}
:root body [data-view=home]:not([hidden]) .seat-summary > div > span{color:var(--home-muted);}
:root body [data-view=home]:not([hidden]) .cp-graph-spark{margin-bottom:var(--space-2);}
:root body [data-view=home]:not([hidden]) .cp-graph-initials{font-size:9pt;}
:root body [data-view=home]:not([hidden]) .feed-filters .seat-icon{height:var(--space-5); width:var(--space-5);}
:root body [data-view=home]:not([hidden]) .home-entry-box{background:#0000; box-shadow:none; margin:0; padding:0;}
:root body [data-view=home]:not([hidden]) .home-entry-box:hover{background:var(--home-hover); box-shadow:none;}
:root body [data-view=home]:not([hidden]) .home-entry{background:#0000; border-radius:var(--space-2); box-shadow:none; gap:var(--space-2); padding:var(--space-3);}
:root body [data-view=home]:not([hidden]) .home-entry:hover{box-shadow:none; transform:none;}
:root body [data-view=home]:not([hidden]) .card .card.home-entry-box{background:#0000; box-shadow:none;}
:root body [data-view=home]:not([hidden]) .card .home-entry-box:has(a:hover){background:var(--home-hover);}
:root body [data-view=home]:not([hidden]) .home-library-grid{align-items:start; min-height:0;}
:root body [data-view=home]:not([hidden]) .home-entry{min-height:80px;}
:root body [data-view=home]:not([hidden]) #feed-filters{min-height:28px;}
:root body [data-view=home]:not([hidden]) .home-file.card{background:#0000; border-radius:var(--space-2); box-shadow:none; margin:0; padding:var(--space-2) 0;}
:root body [data-view=home]:not([hidden]) .home-file time{min-width:56px; text-align:right;}
:root body [data-view=home]:not([hidden]) .home-file .seat-icon{height:var(--space-5); width:var(--space-5);}
:root body [data-view=home]:not([hidden]) .activity li{border:0;}
:root body [data-view=home]:not([hidden]) .bubble-items{background:var(--well); border-radius:var(--space-2); box-shadow:none;}
:root body [data-view=home]:not([hidden]) :is(.order, .home-file, .home-entry-box){transition:0.14s ease background-color;}
:root body [data-view=home]:not([hidden]) .home-file:hover{background:var(--home-hover); box-shadow:none !important;}

/* Empty, loading and failure keep their space and their existing explanations. */
:root body [data-view=home]:not([hidden]) .empty,
:root body [data-view=home]:not([hidden]) #attention .empty{align-items:center; background:var(--well); border-radius:var(--space-2); flex-direction:column; gap:var(--space-2); justify-content:center; padding:var(--space-4); text-align:center;}
:root body [data-view=home]:not([hidden]) .empty :is(svg, svg.empty-art){color:var(--home-muted); flex-basis:42px; height:42px; width:42px;}
:root body [data-view=home]:not([hidden]) .empty .empty-tone{fill:var(--home-line);}
:root body [data-view=home]:not([hidden]) .empty .empty-detail{stroke:var(--home-muted); stroke-width:2;}
:root body [data-view=home]:not([hidden]) .empty strong{color:var(--home-ink); font-size:10.125pt; font-weight:var(--weight-medium); line-height:15pt;}
:root body [data-view=home]:not([hidden]) .empty p{color:var(--home-muted); font-size:9pt; line-height:12pt; margin:var(--space-1) 0 0;}
:root body [data-view=home]:not([hidden]) #attention li{border:0; padding:var(--space-2) 0;}
:root body [data-view=home]:not([hidden]) #attention li:first-child{padding-top:0;}
:root body [data-view=home]:not([hidden]) #attention li:last-child{padding-bottom:0;}
:root body [data-view=home]:not([hidden]) .skeleton{background:var(--paper); border-radius:10px; box-shadow:var(--home-card); gap:var(--space-2); min-height:144px; padding:var(--space-4);}
:root body [data-view=home]:not([hidden]) .skeleton span{animation:none; background:var(--home-line); border-radius:6px; height:var(--space-4); overflow:hidden; position:relative;}
:root body [data-view=home]:not([hidden]) .skeleton span:first-child{height:var(--space-5); width:48%;}
:root body [data-view=home]:not([hidden]) .skeleton span:last-child{height:64px; width:72%;}
:root body [data-view=home]:not([hidden]) #hero-stats > .skeleton{grid-column:1 / -1; min-height:144px;}
:root body [data-view=home]:not([hidden]) :is(#home-activity-chart, #home-run-meter, #home-week, #home-results, #home-library, #home-files):empty{background:var(--paper); border-radius:var(--space-3); box-shadow:var(--home-card); min-height:176px; padding:var(--space-4);}
:root body [data-view=home]:not([hidden]) :is(#home-activity-chart, #home-run-meter, #home-week, #home-results, #home-library, #home-files):empty::before{background:var(--home-line); border-radius:6px; content:""; display:block; height:var(--space-5); width:48%;}
:root body [data-view=home]:not([hidden]) :is(#home-activity-chart, #home-run-meter, #home-week, #home-results, #home-library, #home-files):empty::after{background:var(--home-line); border-radius:6px; content:""; display:block; height:96px; margin-top:var(--space-3); width:100%;}
:root body [data-view=home]:not([hidden]) :is(.form-error, .notice, .readonly),
:root body:has([data-view=home]:not([hidden])) #notice{background:var(--bad-wash); border:0; border-radius:var(--space-2); box-shadow:none; color:var(--bad); font-size:9pt; line-height:15pt; padding:var(--space-3);}
:root body [data-view=home]:not([hidden]) #compose-error{grid-column:1 / -1; margin:0;}
:root body [data-view=home]:not([hidden]) .proposal-card{gap:var(--space-3);}
:root body [data-view=home]:not([hidden]) .review-bar{background:var(--attention-wash); border-radius:var(--space-2); box-shadow:var(--home-card); padding:var(--space-3);}

/* Existing reduced-motion switch works without adding a media query.
   Entrance is one short opacity change; controls each transition one property. */
:root body [data-view=home]:not([hidden]) :is(.card, .stat, .order, .chart-line, .chart-mark, .spark-line, .cp-graph-spark-line){animation:none;}
:root body:has([data-view=home]:not([hidden])) :is(.cp-motion-layer, .ui-hero-roll-in, .ui-hero-roll-out){transform:none !important;}
:root[data-motion=on] body [data-view=home] > .hero{animation:home-enter 200ms ease;}
@keyframes home-enter{ 0%{opacity:.7;} 100%{opacity:1;} }
:root[data-motion=on] body [data-view=home] .skeleton span::after{animation:home-skeleton 1.6s var(--ease) infinite; background:linear-gradient(90deg, #0000, rgb(255 255 255 / .65), #0000); content:""; inset:0; position:absolute;}
@keyframes home-skeleton{ 0%{transform:translateX(-100%);} 60%, 100%{transform:translateX(100%);} }
:root[data-motion=reduce] body [data-view=home] *,
:root[data-motion=reduce] body [data-view=home] *::before,
:root[data-motion=reduce] body [data-view=home] *::after{animation:none !important;}

/* Keep the order form and the route from Home to a kept entry usable at actual device width. */
@media (max-width:900px){
  :root[data-route=home] [data-view=home] :is(.home-row, .home-compose-row, .home-library-grid, .home-proposal-list){
    grid-template-columns:var(--track);
  }
  :root[data-route=home] #home-team{
    grid-template-columns:repeat(auto-fit, minmax(min(100%, 250px), 1fr));
  }
  :root[data-route=home] [data-view=home] .home-compose-row #compose-form{
    display:flex;
    flex-flow:column;
    align-items:stretch;
  }
  :root[data-route=home] [data-view=home] #compose-form > .actions{
    align-self:stretch;
    justify-content:flex-start;
  }
  :root[data-route=home] body [data-view=home]:not([hidden]) .home-entry{
    min-height:44px;
    grid-template-columns:auto var(--track);
    align-items:center;
  }
  :root[data-route=home] .home-entry .hint{ grid-column:2; }
  :root[data-route=home] [data-home-library] .block-head a{
    display:inline-flex;
    align-items:center;
    min-block-size:44px;
  }
}
@media (min-width:761px) and (max-width:900px){
  :root[data-route=home] body{ grid-template-columns:140px var(--track); }
}
@media (max-width:760px){
  :root[data-route=home] [data-view=home] .hero .page-head{
    flex-flow:column;
    align-items:start;
  }
  :root[data-route=home] [data-view=home] #hero-stats{
    grid-template-columns:repeat(2, var(--track));
  }
  :root[data-route=home] [data-view=home] #hero-stats .stat{
    grid-template-columns:var(--track);
    padding:var(--space-2);
    gap:var(--space-1);
    min-height:0;
  }
  :root[data-route=home] #hero-stats .stat > [data-card-icon]{ display:none; }
  :root[data-route=home] [data-view=home] #hero-stats .stat > *{ grid-area:auto; }
  :root[data-route=home] :is(#compose-title, #compose-goal){ font-size:16px; }
  :root[data-route=home] body [data-view=home]:not([hidden]) :is(#compose-title, #compose-submit),
  :root[data-route=home] nav a[data-nav-to]{ min-height:44px; }
  :root[data-route=home] [data-view=home] .week-day{ padding-inline:2px; }
  :root[data-route=home] [data-view=home] :is(.home-file, .results-file){
    display:flex;
    flex-wrap:wrap;
  }
}
@media (max-width:520px){
  :root[data-route=home] #home-orders .order > .order-step-summary{
    grid-column:1 / -1;
    grid-row:auto;
  }
}
