cat > 'web/look-order.css' <<'OC_EOF_97'
/* Order and Status: ui-foundation's four inks, paper surfaces and role scale.
   The shell tokens only apply while one of these two routes is visible. */
:root:has([data-view=order]:not([hidden])),
:root:has([data-view=status]:not([hidden])){--attention:#945000; --attention-wash:rgb(178 94 0 / .12); --bad:#b23825; --bad-wash:rgb(178 56 37 / .10); --canvas:#f8f8f8; --ease:cubic-bezier(.22, 1, .36, 1); --edge:#0070d6; --ink:var(--lo-ink); --ink-16:rgb(0 0 0 / .06); --ink-2:var(--lo-body); --ink-28:var(--lo-faint); --ink-3:var(--lo-secondary); --ink-38:var(--lo-faint); --ink-58:var(--lo-secondary); --ink-66:var(--lo-secondary); --ink-68:var(--lo-secondary); --ink-70:var(--lo-secondary); --ink-72:var(--lo-secondary); --ink-76:var(--lo-body); --ink-80:var(--lo-body); --ink-86:var(--lo-ink); --ink-92:var(--lo-ink); --leading-display:28px; --leading-md:24px; --leading-sm:20px; --leading-xs:16px; --lift-1:var(--lo-paper); --lift-2:var(--lo-paper); --lift-3:var(--lo-hover); --line:rgb(0 0 0 / .06); --line-2:rgb(0 0 0 / .10); --lo-body:rgb(0 0 0 / .61); --lo-faint:rgb(0 0 0 / .27); --lo-hover:0 0 0 .5px rgb(0 0 0 / .10), 0 1px 1px -1px rgb(0 0 0 / .10), 0 2px 6px -1px rgb(0 0 0 / .08); --lo-ink:rgb(0 0 0 / .88); --lo-paper:var(--lo-ring), 0 1px 1px -1px rgb(0 0 0 / .10), 0 1px 2px rgb(0 0 0 / .05); --lo-ring:0 0 0 .5px rgb(0 0 0 / .06); --lo-secondary:rgb(0 0 0 / .45); --mono-ink:var(--lo-body); --mono-wash:rgb(0 0 0 / .04); --motion:140ms; --nav-wash:rgb(0 0 0 / .06); --ok:#197340; --ok-wash:rgb(30 138 79 / .10); --paper:#ffffff; --round-button:6px; --round-card:12px; --round-chip:4px; --round-control:8px; --round-icon:6px; --run:#006dcb; --run-wash:rgb(0 112 214 / .10); --shadow:var(--lo-paper); --shadow-small:var(--lo-paper); --shadow-small-svg:drop-shadow(0 1px 1px rgb(0 0 0 / .05)); --shadow-svg:drop-shadow(0 1px 2px rgb(0 0 0 / .05)); --skeleton:rgb(0 0 0 / .06); --text-caption:12px; --text-copy:13.5px; --text-display:22px; --text-emphasis:13.5px; --text-lg:17px; --text-md:13.5px; --text-micro:11.5px; --text-sm:13.5px; --text-stat:22px; --text-unit:11.5px; --text-xl:17px; --text-xs:12px; --time:var(--lo-secondary); --ui-card:var(--paper); --ui-chip:var(--wash); --ui-faint:var(--lo-faint); --ui-fill:var(--well); --ui-ink:var(--lo-ink); --ui-muted:var(--lo-secondary); --ui-page:var(--paper); --ui-press:rgb(0 0 0 / .06); --ui-ring:var(--lo-ring); --ui-ring-strong:0 0 0 .5px rgb(0 0 0 / .10); --ui-shadow-card:var(--lo-paper); --ui-shadow-hover:var(--lo-hover); --ui-text:var(--lo-body); --ui-track:rgb(0 0 0 / .06); --ui-tray:var(--well); --wait:var(--lo-body); --wait-wash:rgb(0 0 0 / .04); --wash:rgb(0 0 0 / .04); --well:rgb(0 0 0 / .02);}

/* Role typography. These selectors outrank the optional private style layer. */
:root body [data-view]:is([data-view=order], [data-view=status]){color:var(--lo-body); font-size:10.125pt; font-weight:normal; font-variant-numeric:var(--number-style); letter-spacing:-.006em; line-height:15pt;}
:root body [data-view]:is([data-view=order], [data-view=status]) :is(h3, h4, strong, b, th, .order-title, .seat-name, .flow-title, .cp-graph-initials){font-weight:var(--weight-medium);}
:root body [data-view]:is([data-view=order], [data-view=status]) h2{color:var(--lo-ink); font-size:16.5pt; font-weight:var(--weight-heading); letter-spacing:-.01em; line-height:21pt;}
:root body [data-view]:is([data-view=order], [data-view=status]) h3{color:var(--lo-ink); font-size:12.75pt; letter-spacing:0; line-height:18pt; margin:0 0 var(--space-2);}
:root body [data-view]:is([data-view=order], [data-view=status]) :is(h4, .order-title, .seat-name){color:var(--lo-ink); font-size:10.125pt; letter-spacing:0; line-height:15pt;}
:root body [data-view]:is([data-view=order], [data-view=status]) :is(.eyebrow, .hint, small, .drawing-caption, .launch-model, .launch-result, .suborder-model, .seat-model, .seat-now, [data-stat-note]){color:var(--lo-secondary); font-size:9pt; font-weight:normal; line-height:15pt;}
:root body [data-view]:is([data-view=order], [data-view=status]) :is(.eyebrow, time, th, code, .mono, .flow-state, .axis-label, .number-unit){font-size:8.625pt;}
:root body [data-view]:is([data-view=order], [data-view=status]) :is(.eyebrow, .drawing-caption){margin:0 0 var(--space-2);}
:root body [data-view]:is([data-view=order], [data-view=status]) :is(code, .mono){background:#0000; color:var(--lo-body);}
:root body [data-view]:is([data-view=order], [data-view=status]) :is(.section-count, #status-open-count, #status-ended-count){color:var(--lo-faint); font-size:9pt; font-weight:normal; margin-left:6px;}

/* One gap per layer: sections 20, peer cards 12, content 8, controls 6. */
:root body [data-view][data-view=order] #order-detail{display:grid; gap:var(--space-5);}
:root body [data-view][data-view=status]:not([hidden]){display:grid; gap:var(--space-5);}
:root body [data-view]:is([data-view=order], [data-view=status]) .page-head{align-items:start; gap:var(--space-3); margin:0;}
:root body [data-view]:is([data-view=order], [data-view=status]) .page-head > a{flex:0 0 auto; font-size:9pt; line-height:21pt;}
:root body [data-view]:is([data-view=order], [data-view=status]) :is(.card, .order, .file, .seat, .run-tile, .launch-card, .cp-graph-card){background:var(--paper); background-image:none; border:0; border-radius:var(--space-3); box-shadow:var(--lo-paper); margin:0; padding:var(--space-4); transform:none;}
:root body [data-view][data-view=order] #order-detail > .card{padding:var(--space-4);}
:root body [data-view]:is([data-view=order], [data-view=status]) :is(.run-tiles, .stats, .orders, .files, .team, .launch-cards, .order-facts-row, .order-library-row, .order-execution){gap:var(--space-3); margin:0;}
:root body [data-view]:is([data-view=order], [data-view=status]) :is(.block-head, .card-heading, .who, .lead-seat, .seat-head){gap:var(--space-2);}
:root body [data-view]:is([data-view=order], [data-view=status]) .block-head{margin-bottom:var(--space-2);}
:root body [data-view]:is([data-view=order], [data-view=status]) :is(.actions, .file-actions, .suborder-origin){gap:6px;}
:root body [data-view][data-view=order] .order-facts-row{grid-template-columns:var(--track) var(--track);}
:root body [data-view][data-view=order] .facts{font-size:10.125pt; gap:var(--space-2); grid-template-columns:92px var(--track); margin:var(--space-3) 0 0;}
:root body [data-view][data-view=order] .facts dt{color:var(--lo-secondary); font-size:9pt;}
:root body [data-view][data-view=order] .facts dd{color:var(--lo-body);}
:root body [data-view][data-view=order] [data-order-field=goal]{color:var(--lo-ink); white-space:pre-line;}
:root body [data-view][data-view=order] [data-order-files]{margin:0;}
:root body [data-view][data-view=order] .order-execution [data-timeline]{gap:var(--space-2);}
:root body [data-view][data-view=order] .order-execution > .scroll{background:var(--well); border-radius:var(--space-2); padding:var(--space-2);}

/* Status is a list to scan. In an order, the same card sits above its record. */
:root body [data-view][data-view=status] .status-cards{gap:2px; grid-template-columns:var(--track);}
:root body [data-view][data-view=status] .status-card{align-items:start; border-radius:var(--space-2); box-shadow:none; display:grid; gap:var(--space-2) var(--space-3); grid-template-columns:minmax(220px, 1fr) minmax(0, 1.5fr) 140px; padding:var(--space-3);}
:root body [data-view][data-view=status] .status-card + .status-card{box-shadow:none;}
:root body [data-view][data-view=status] .status-card > .block-head{flex-direction:column; gap:6px; margin:0;}
:root body [data-view][data-view=status] .status-card > .status-facts{grid-column:2; grid-row:1;}
:root body [data-view][data-view=status] .status-card > .actions{display:grid; grid-column:3; grid-row:1; justify-items:start;}
:root body [data-view][data-view=status] .status-flags{grid-column:2 / -1;}
:root body [data-view]:is([data-view=order], [data-view=status]) .status-card .block-head p{font-size:8.625pt; margin:0; word-wrap:anywhere;}
:root body [data-view]:is([data-view=order], [data-view=status]) .status-facts{font-size:10.125pt; gap:var(--space-1); line-height:15pt;}
:root body [data-view]:is([data-view=order], [data-view=status]) .status-facts [data-fact]{color:var(--lo-ink); font-weight:normal;}
:root body [data-view]:is([data-view=order], [data-view=status]) .status-card .actions{font-size:9pt;}
:root body [data-view][data-view=order] [data-order-status] > div{display:grid; gap:var(--space-3);}
:root body [data-view][data-view=order] [data-order-status] .status-card{background:var(--well); border-radius:var(--space-2); box-shadow:none; gap:var(--space-2); padding:var(--space-3);}
:root body [data-view][data-view=order] [data-order-status] .status-card .block-head{margin:0;}

/* Small factual graphics stay beside fixed-width, tabular numbers. */
:root body [data-view]:is([data-view=order], [data-view=status]) :is(.stat, .run-tile){align-content:start; display:grid; gap:6px var(--space-2); grid-template-columns:var(--track) 22px;}
:root body [data-view]:is([data-view=order], [data-view=status]) :is(.stat-label, .run-tile > .hint){color:var(--lo-secondary); font-size:9pt; grid-column:1; grid-row:1;}
:root body [data-view]:is([data-view=order], [data-view=status]) :is(.stat > [data-card-icon], .run-tile > .glyph){align-self:center; background:#0000; border-radius:0; color:var(--lo-faint); grid-column:2; grid-row:2; height:18px; padding:0; width:18px;}
:root body [data-view]:is([data-view=order], [data-view=status]) :is(.stat strong, .run-tile strong){color:var(--lo-ink); font-size:16.5pt; font-weight:var(--weight-medium); grid-column:1; grid-row:2; letter-spacing:-.01em; line-height:21pt; margin:0; min-width:5ch;}
:root body [data-view][data-view=order] .run-tile strong{justify-self:start;}
:root body [data-view][data-view=order] .run-tile > .hint{max-width:none; padding-right:0;}
:root body [data-view][data-view=order] .run-tile{background:var(--well); border-radius:var(--space-2); box-shadow:none; padding:var(--space-3);}
:root body [data-view][data-view=status] [data-stat-note]{font-size:8.625pt; grid-column:1 / -1; margin:0;}
:root body [data-view][data-view=status] .stat[data-stat-alert=true] > [data-card-icon]{color:var(--attention);}
:root body [data-view][data-view=order] .order-metrics{gap:var(--space-3); margin-top:var(--space-2);}
:root body [data-view][data-view=order] [data-metric]{align-items:baseline; color:var(--lo-secondary); display:inline-flex; gap:var(--space-1);}
:root body [data-view][data-view=order] [data-metric] strong{font-size:10.125pt; font-weight:var(--weight-medium); line-height:15pt; margin:0; min-width:4ch; text-align:right;}
:root body [data-view][data-view=order] [data-metric]::before{align-self:center; border-radius:2px; box-shadow:inset 0 0 0 1px var(--lo-faint); content:""; flex:0 0 auto; height:var(--space-2); width:var(--space-2);}
:root body [data-view][data-view=order] [data-metric=seconds]::before{border-radius:50%;}
:root body [data-view][data-view=order] .launch-stats{gap:var(--space-1); grid-template-columns:var(--track);}
:root body [data-view][data-view=order] [data-launch-stat]{color:var(--lo-secondary); display:grid; font-size:9pt; gap:6px; grid-template-columns:6ch var(--track); line-height:15pt;}
:root body [data-view][data-view=order] [data-launch-stat] strong{color:var(--lo-body); font-weight:normal; text-align:right;}
:root body [data-view][data-view=order] .seat-summary{gap:var(--space-2);}
:root body [data-view][data-view=order] .seat-summary > div{background:#0000; padding:0;}
:root body [data-view][data-view=order] .seat-summary strong{color:var(--lo-ink); font-size:12.75pt; font-weight:var(--weight-medium);}

/* Tables align by width and whitespace, without boxed cells. */
:root body [data-view][data-view=order] :is(th, td){border:0; font-size:9pt; line-height:15pt; padding:var(--space-2);}
:root body [data-view][data-view=order] th{background:var(--well); color:var(--lo-secondary); font-weight:normal; height:var(--space-8); padding-top:6px; padding-bottom:6px;}
:root body [data-view][data-view=order] tr{box-shadow:none;}
:root body [data-view][data-view=order] tbody tr:hover{background:rgb(0 0 0 / .03);}
:root body [data-view][data-view=order] .status-rows th:nth-child(1){text-align:right; width:48px;}
:root body [data-view][data-view=order] .status-rows th:nth-child(2){width:104px;}
:root body [data-view][data-view=order] .status-rows th:nth-child(3){width:172px;}
:root body [data-view][data-view=order] .status-rows th:nth-child(4){width:140px;}
:root body [data-view][data-view=order] .status-rows td:first-child{color:var(--lo-faint); text-align:right;}
:root body [data-view][data-view=order] .launch-table :is(th, td):nth-child(n+6){text-align:right; width:84px;}
:root body [data-view][data-view=order] .launch-table :is(th, td):nth-child(8){width:112px;}

/* Semantic labels use one hue twice: a wash and its darker ink. */
:root body [data-view]:is([data-view=order], [data-view=status]) :is(.badge, .pill, .kind-chip){border:0; border-radius:var(--space-1); box-shadow:none; font-size:8.625pt; font-weight:var(--weight-medium); gap:var(--space-1); line-height:12pt; min-height:18px; padding:1px 6px;}
:root body [data-view]:is([data-view=order], [data-view=status]) :is(.badge, .pill):not([data-state]){background:var(--wash); color:var(--lo-body);}
:root body [data-view]:is([data-view=order], [data-view=status]) .badge:is([data-state=CANCELLED], [data-state=ended], [data-state=finished], [data-state=waiting], [data-state=READY], [data-state=PENDING]){background:var(--wait-wash); color:var(--wait);}
:root body [data-view]:is([data-view=order], [data-view=status]) :is(.notice, .readonly, .order-problem, .form-error){background:var(--attention-wash); border:0; border-radius:var(--space-2); box-shadow:none; color:var(--lo-body); font-size:9pt; line-height:15pt; padding:var(--space-3);}
:root body [data-view]:is([data-view=order], [data-view=status]) .notice[data-flag="7e"]{color:var(--attention);}
:root body [data-view][data-view=order] .readonly{background:var(--well); margin:0;}
:root body [data-view][data-view=order] .seat-band{background:#0000; border-radius:0; padding:0;}
:root body [data-view][data-view=order] .seat-band .seat-icon{border-radius:6px; box-shadow:none;}
:root body [data-view][data-view=order] .kind-chip{background:var(--wash); color:var(--lo-body);}
:root body [data-view][data-view=order] .kind-chip .glyph{height:var(--space-3); width:var(--space-3);}
:root body [data-view]:is([data-view=order], [data-view=status]) h3 > [data-card-icon]{background:var(--wash); border-radius:6px; color:var(--lo-body); height:var(--space-6); padding:var(--space-1); width:var(--space-6);}

/* Controls: height determines radius; hover advances one neutral step. */
:root body [data-view]:is([data-view=order], [data-view=status]) :is(a, button, input, select, textarea, summary){transform:none;}
:root body [data-view]:is([data-view=order], [data-view=status]) a{color:var(--lo-body); transition:color 140ms ease;}
:root body [data-view]:is([data-view=order], [data-view=status]) a:not([aria-current]):not([aria-selected=true]):hover{color:var(--lo-ink);}
:root body [data-view]:is([data-view=order], [data-view=status]) :is(button, .button){border:0; border-radius:6px; font-size:9pt; font-weight:var(--weight-medium); line-height:15pt; min-height:28px; padding:var(--space-1) 10px; transition:0.14s ease background-color;}
:root body [data-view]:is([data-view=order], [data-view=status]) button:not(.quiet):not(.link){background:var(--lo-ink); box-shadow:none; color:white;}
:root body [data-view]:is([data-view=order], [data-view=status]) button:not(.quiet):not(.link):enabled:hover{background:rgb(0 0 0 / .80);}
:root body [data-view]:is([data-view=order], [data-view=status]) :is(button.quiet, .button.quiet){background:white; box-shadow:var(--lo-paper); color:var(--lo-body); transition:0.14s ease box-shadow;}
:root body [data-view]:is([data-view=order], [data-view=status]) button.quiet:enabled:not([aria-selected=true]):hover{background:white; box-shadow:var(--lo-hover); color:var(--lo-body);}
:root body [data-view]:is([data-view=order], [data-view=status]) button.link{background:#0000; box-shadow:none; color:var(--lo-body); font-weight:normal; min-height:28px; padding:0; transition:color 140ms ease;}
:root body [data-view]:is([data-view=order], [data-view=status]) button.link:enabled:hover{color:var(--lo-ink);}
:root body [data-view]:is([data-view=order], [data-view=status]) button:disabled{opacity:.4; transform:none;}
:root body [data-view]:is([data-view=order], [data-view=status]) :is(input, textarea, select){background:white; border:0; border-radius:var(--space-2); box-shadow:var(--lo-paper); color:var(--lo-ink); font:inherit; font-weight:normal; min-height:var(--space-8); padding:6px var(--space-3); transition:0.14s ease box-shadow;}
:root body [data-view]:is([data-view=order], [data-view=status]) label{font-weight:normal; font-size:9pt;}
:root body [data-view]:is([data-view=order], [data-view=status]) button.quiet:disabled:is(:hover, :active){background:white; box-shadow:var(--lo-paper); color:var(--lo-body);}
:root body [data-view]:is([data-view=order], [data-view=status]) :is(input, textarea, select):is(:focus-visible, :hover){background:white; box-shadow:var(--lo-hover); outline:none;}
:root body [data-view]:is([data-view=order], [data-view=status]) summary{border-radius:6px; color:var(--lo-body); font-size:9pt; min-height:28px; padding:var(--space-1) 6px; transition:0.14s ease background-color;}
:root body [data-view]:is([data-view=order], [data-view=status]) summary:hover{background:rgb(0 0 0 / .03); color:var(--lo-body);}
:root body [data-view]:is([data-view=order], [data-view=status]) :is(a, button, summary, [tabindex]):focus-visible{outline:solid 2px var(--lo-secondary); outline-offset:2px;}
:root body [data-view]:is([data-view=order], [data-view=status]) [aria-selected=true]{background:rgb(0 0 0 / .04); font-weight:normal;}
:root body [data-view]:is([data-view=order], [data-view=status]) [aria-selected=true]:hover{background:rgb(0 0 0 / .04); transform:none;}
:root body [data-view][data-view=order] a.order:hover{background:var(--paper); box-shadow:var(--lo-hover); text-decoration-line:none;}
:root body [data-view][data-view=order] a.order{transition:0.14s ease box-shadow;}

/* Charts keep their data colours; type and boundaries share the page's inks. */
:root body [data-view][data-view=order] :is(.axis-label, .timeline-seat, .timeline-duration, .flow-state){fill:var(--lo-secondary); font-size:8.625pt; font-weight:normal;}
:root body [data-view][data-view=order] .flow-title{fill:var(--lo-ink); font-size:10.125pt; font-weight:var(--weight-medium);}
:root body [data-view][data-view=order] .flow-box{fill:white; rx:8px; stroke:rgb(0 0 0 / .10); stroke-width:.5px; transition:fill 140ms ease;}
:root body [data-view][data-view=order] a:hover .flow-box{fill:rgb(0 0 0 / .03);}
:root body [data-view][data-view=order] [data-flow-edge]{stroke-width:1.5px;}
:root body [data-view][data-view=order] :is(.progress-track, .step-track, .thin-track){border-radius:2px; height:var(--space-1);}
:root body [data-view][data-view=order] :is([data-progress-fill], [data-meter-fill]){transition:200ms var(--ease) width;}

/* Empty, loading and unavailable are full layouts, with the existing next step. */
:root body [data-view]:is([data-view=order], [data-view=status]) .empty{align-items:center; background:var(--well); border-radius:var(--space-2); display:flex; flex-direction:column; gap:var(--space-2); justify-content:center; min-height:160px; padding:var(--space-5) var(--space-4); text-align:center;}
:root body [data-view]:is([data-view=order], [data-view=status]) .empty svg.empty-art{background:var(--wash); border-radius:var(--space-2); color:var(--lo-secondary); flex:0 0 42px; height:42px; width:42px;}
:root body [data-view]:is([data-view=order], [data-view=status]) .empty .empty-tone{fill:rgb(0 0 0 / .06) !important; stroke:var(--lo-faint);}
:root body [data-view]:is([data-view=order], [data-view=status]) .empty .empty-detail{stroke:var(--lo-secondary);}
:root body [data-view]:is([data-view=order], [data-view=status]) .empty-art > ellipse{fill:rgb(0 0 0 / .04); filter:none;}
:root body [data-view]:is([data-view=order], [data-view=status]) .empty strong{font-size:10.125pt; font-weight:var(--weight-medium); line-height:15pt;}
:root body [data-view]:is([data-view=order], [data-view=status]) .empty p{font-size:9pt; line-height:15pt; margin:var(--space-1) 0 0; max-width:56ch;}
:root body [data-view]:is([data-view=order], [data-view=status]) .empty-action{background:white; border-radius:6px; box-shadow:var(--lo-paper); font-size:9pt; min-height:28px; padding:var(--space-1) 10px; transition:0.14s ease box-shadow;}
:root body [data-view]:is([data-view=order], [data-view=status]) .empty-action:hover{box-shadow:var(--lo-hover);}
:root body [data-view][data-view=status] .status-cards > .empty{flex-direction:row; gap:var(--space-3); grid-column:1 / -1; min-height:96px; padding:var(--space-3); text-align:left; width:100%;}
:root body [data-view][data-view=order] .order-library-row .empty{min-height:160px;}
:root body [data-view]:is([data-view=order], [data-view=status]) .skeleton{background:white; border-radius:var(--space-3); box-shadow:var(--lo-paper); gap:var(--space-3); min-height:240px; padding:var(--space-4); width:100%;}
:root body [data-view]:is([data-view=order], [data-view=status]) .skeleton span{animation:none; background:rgb(0 0 0 / .06); border-radius:6px; height:var(--space-5);}
:root body [data-view]:is([data-view=order], [data-view=status]) .skeleton span:first-child{height:28px; width:32%;}
:root body [data-view]:is([data-view=order], [data-view=status]) .skeleton span:last-child{height:128px; width:100%;}
:root body [data-view][data-view=status][data-link=down] #status-summary .notice{margin:0 0 var(--space-2);}

/* Avoid inherited lifts and multi-property entrances. Reduced motion is owned
   by app.js; its data-motion attribute also gates this one-property shimmer. */
:root body [data-view]:is([data-view=order], [data-view=status]) :is(.card, .order, .seat, .run-tile, .launch-card, .empty-art){animation:none; transition:0.14s ease box-shadow;}
:root body [data-view]:is([data-view=order], [data-view=status]) :is(.card, .seat, .run-tile, .launch-card):hover{transform:none;}
:root body [data-view]:is([data-view=order], [data-view=status]) .skeleton span{overflow:hidden; position:relative;}
:root body [data-view]:is([data-view=order], [data-view=status]) .skeleton span::after{background:linear-gradient(90deg, #0000, rgb(255 255 255 / .6), #0000); content:""; inset:0; position:absolute; transform:translateX(-100%);}
:root[data-motion=on] body :is([data-view=order], [data-view=status]) .skeleton span::after{animation:lo-shimmer 1.6s var(--ease) infinite;}
@keyframes lo-shimmer{ 60%, 100%{transform:translateX(100%);} }
:root[data-motion=reduce] body :is([data-view=order], [data-view=status]) *{animation:none !important; transition:none !important;}

/* The status overview is four equal measures, followed by compact list rows. */
:root body [data-view][data-view=status] .view-stats{grid-template-columns:repeat(4, var(--track));}
:root body [data-view][data-view=status] .status-card:hover{background:rgb(0 0 0 / .03);}
:root body [data-view][data-view=status] .status-card{transition:0.14s ease background-color;}
:root body [data-view][data-view=order] tbody tr:nth-child(even){background:#0000;}
:root body [data-view][data-view=order] tbody tr:hover{background:rgb(0 0 0 / .03);}
:root body [data-view][data-view=order] .file-actions button{white-space:nowrap;}
:root body [data-view][data-view=order] .file-actions{flex-wrap:wrap;}
:root body [data-view][data-view=order] .file{gap:var(--space-2) var(--space-3); grid-template-columns:minmax(0, 1.5fr) 0 var(--track) 96px max-content;}
:root body [data-view][data-view=order] .file-actions{grid-column:1 / -1; justify-content:end;}
:root body [data-view][data-view=order] [data-keep-edit]:not([open]){flex-basis:auto; margin-right:auto;}
