cat > 'web/look-records.css' <<'OC_EOF_98'
/* Records: ui-foundation design core, including its density and restraint rules.
 * The shell changes only while one of these views is visible. Component rules
 * outrank both app.css and the optional pro/ui styles, regardless of load order.
 * 2 = adjacent choices; 6 = icon/label; 8 = content; 12 = peers; 20 = sections.
 */
:root body:has(main > :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]):not([hidden])){--attention:#945000; --attention-wash:rgb(178 94 0 / .12); --bad:#b33628; --bad-wash:rgb(179 54 40 / .1); --canvas:#f8f8f8; --ink:rgb(0 0 0 / .88); --ink-16:rgb(0 0 0 / .06); --ink-2:rgb(0 0 0 / .61); --ink-28:var(--records-faint); --ink-3:rgb(0 0 0 / .45); --ink-38:var(--records-faint); --ink-58:var(--ink-3); --ink-66:var(--ink-3); --ink-68:var(--ink-3); --ink-70:var(--ink-3); --ink-72:var(--ink-3); --ink-76:var(--ink-2); --ink-80:var(--ink-2); --ink-86:var(--ink); --ink-92:var(--ink); --kind-artifact-ink:var(--ink-2); --kind-artifact-wash:var(--wash); --kind-lesson-ink:var(--ink-2); --kind-lesson-wash:var(--wash); --kind-skill-ink:var(--ink-2); --kind-skill-wash:var(--wash); --kind-workflow-ink:var(--ink-2); --kind-workflow-wash:var(--wash); --leading-display:28px; --leading-md:24px; --leading-sm:20px; --leading-xs:16px; --lift-1:0 0 0 .5px rgb(0 0 0 / .06), 0 1px 1px -1px rgb(0 0 0 / .1), 0 1px 2px rgb(0 0 0 / .05); --lift-2:var(--lift-1); --lift-3:0 0 0 .5px rgb(0 0 0 / .1), 0 1px 1px -1px rgb(0 0 0 / .1), 0 2px 6px -1px rgb(0 0 0 / .08); --line:rgb(0 0 0 / .06); --line-2:rgb(0 0 0 / .1); --mono-ink:var(--ink-2); --mono-wash:var(--well); --motion:140ms; --nav-wash:rgb(0 0 0 / .06); --ok:#197340; --ok-wash:rgb(30 138 79 / .1); --paper:#fff; --round-button:6px; --round-card:12px; --round-chip:4px; --round-control:8px; --round-icon:8px; --records-faint:rgb(0 0 0 / .27); --run:#006dcb; --run-wash:rgb(0 112 214 / .1); --shadow:var(--lift-1); --shadow-small:var(--lift-1); --skeleton:rgb(0 0 0 / .06); --space-section:20px; --text-caption:12px; --text-copy:13.5px; --text-display:22px; --text-emphasis:13.5px; --text-lg:17px; --text-md:13.5px; --text-micro:11.5px; --text-sm:13.5px; --text-stat:22px; --text-unit:11.5px; --text-xl:22px; --text-xs:12px; --time:var(--ink-3); --ui-board:var(--well); --ui-card:var(--paper); --ui-chip:var(--wash); --ui-fill:var(--well); --ui-muted:var(--ink-3); --ui-press:var(--wash); --ui-shadow-card:var(--lift-1); --ui-shadow-hover:var(--lift-3); --ui-text:var(--ink-2); --ui-track:var(--line); --wait:var(--ink-2); --wait-wash:var(--wash); --wash:rgb(0 0 0 / .04); --well:rgb(0 0 0 / .02); background:var(--canvas); color:var(--ink-2); font-size:10.125pt; font-weight:normal; grid-template-columns:272px var(--track); letter-spacing:-.006em;}

/* A quiet rail and a white sheet, with a shallow header inside the sheet. */
:root body:has(main > :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]):not([hidden])) .workspace{background:var(--paper); border-radius:var(--space-3); box-shadow:var(--lift-1); margin:var(--space-2) var(--space-2) var(--space-2) 0; min-height:calc(100vh - var(--space-4)); padding:0 var(--space-5) var(--space-5);}
:root body:has(main > :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]):not([hidden])) :is(.top .pill, .nav-count){border-radius:var(--space-1); box-shadow:none; font-size:8.625pt; font-weight:normal; padding:2px 6px;}

/* Common type and surfaces. No content is removed or clamped by this layer. */
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]){color:var(--ink-2); font:400 13.5px/20px var(--font); letter-spacing:-.006em;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) :is(h2, h3, h4, strong, b, label, button, .button, .order-title, .group-heading){font-weight:var(--weight-medium);}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) h2{color:var(--ink); font-size:16.5pt; font-weight:var(--weight-heading); letter-spacing:-.01em; line-height:21pt;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) :is(h3, .section-heading){color:var(--ink); font-size:12.75pt; letter-spacing:-.006em; line-height:18pt;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) h3{margin-bottom:var(--space-2);}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .section-heading{margin:var(--space-5) 0 var(--space-2);}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .page-head{gap:var(--space-3); margin-bottom:var(--space-5);}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .eyebrow{color:var(--ink-3); font-size:9pt; font-weight:normal; margin-bottom:6px;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) :is(a, button.link){color:var(--ink);}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) :is(small, .hint, .drawing-caption, .library-meta, time, [data-stat-note]){color:var(--ink-3); font-size:9pt; font-weight:normal; line-height:15pt;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) :is(code, .mono, .entry-path){color:var(--ink-2); font-size:8.625pt; line-height:15pt;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) :is(.card, .stat){background:var(--paper); border:0; border-radius:var(--space-3); box-shadow:var(--lift-1); margin-bottom:var(--space-3); padding:var(--space-4);}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) :is(.actions, .block-head, .library-meta){gap:var(--space-2);}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .block-head{margin-bottom:var(--space-2);}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) :is(.glyph, .activity-icon){color:var(--ink-3); stroke-width:1.9;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) [data-card-icon]{background:var(--well); border-radius:7px; box-shadow:none; color:var(--ink-3); height:28px; margin:0; width:28px;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) [data-card-icon] .glyph{height:var(--space-4); width:var(--space-4);}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .card-heading{gap:6px;}

/* Numbers align in fixed columns. Existing icons and data bars do the explaining. */
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .view-stats{gap:var(--space-3); margin-bottom:var(--space-5);}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .stat{gap:0 6px; grid-template-columns:var(--track) 28px 56px; margin:0; min-height:76px;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .stat > [data-card-icon]{grid-column:2; grid-row:1 / 3;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .stat-label{color:var(--ink-2); font-size:9pt; grid-column:1; line-height:15pt;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .stat > strong{color:var(--ink); font-size:16.5pt; font-weight:var(--weight-medium); line-height:21pt; text-align:right; width:56px;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .stat > [data-stat-note]{font-size:8.625pt; grid-column:1; line-height:12pt; margin:0;}
:root body main :is([data-view=files], [data-view=ledger]) .summary-groups{gap:var(--space-3);}
:root body main :is([data-view=files], [data-view=ledger]) .summary-group{background:var(--well); border:0; border-radius:var(--space-2); box-shadow:none; padding:var(--space-2) var(--space-3);}
:root body main :is([data-view=files], [data-view=ledger]) .summary-group-head{font-size:9pt; gap:6px;}
:root body main :is([data-view=files], [data-view=ledger]) .summary-group-head strong{color:var(--records-faint); flex:0 0 auto; font-size:9pt; font-weight:normal; text-align:right; width:34px;}
:root body main :is([data-view=files], [data-view=ledger]) .summary-rail{background:var(--line); border-radius:2px; height:2px; margin-top:var(--space-2);}
:root body main :is([data-view=files], [data-view=ledger]) .summary-rail > span{background:rgb(0 0 0 / .27);}

/* Only status carries coloured ink. The same states use the same pair everywhere. */
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) :is(.badge, .pill, .kind-chip, .version-chip){background:var(--wash); border:0; border-radius:var(--space-1); box-shadow:none; color:var(--ink-2); font-size:8.625pt; font-weight:normal; gap:6px; line-height:12pt; min-height:18px; padding:1px 6px;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) :is(.badge, .pill):is([data-state=running], [data-state=LEASED], [data-state=JUDGING]){background:var(--run-wash); color:var(--run);}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) :is(.badge, .pill):is([data-state=SUCCEEDED], [data-state=ok], [data-state=accepted], [data-state=recorded]){background:var(--ok-wash); color:var(--ok);}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) :is(.badge, .pill):is([data-state=due], [data-state=proposed], [data-state=attention]){background:var(--attention-wash); color:var(--attention);}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) :is(.badge, .pill):is([data-state=FAILED], [data-state=DEAD], [data-state=bad], [data-state=rejected], [data-state=halted], [data-state=fatal]){background:var(--bad-wash); color:var(--bad);}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .seat-chip{background:#0000; color:var(--ink-2); font-size:9pt; font-weight:normal; gap:6px; padding:0;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .seat-icon{height:var(--space-5); min-width:var(--space-5); min-height:var(--space-5); width:var(--space-5);}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .cp-graph-avatar{color:var(--ink-2); height:var(--space-5); width:var(--space-5);}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .cp-graph-avatar-wash{fill:var(--wash); stroke:var(--line); stroke-width:.5;}
/* The avatar's 32-unit viewBox renders at 20px: keep its initials at 11.5px. */
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .cp-graph-initials{font-size:13.8pt; font-weight:var(--weight-medium);}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .kind-chip .glyph{color:inherit; height:var(--space-3); stroke-width:2; width:var(--space-3);}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) :is(.column-count, .section-count){background:#0000; box-shadow:none; color:var(--records-faint); font-size:9pt; font-weight:normal; line-height:15pt; min-width:28px; text-align:right;}

/* Controls change one property at a time; selection never changes on hover. */
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) :is(a, button, input, select, textarea, summary){transition:0.14s ease background-color;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) :is(button, .button){background:var(--ink); border-radius:6px; box-shadow:none; color:var(--paper); font-size:10.125pt; gap:6px; line-height:15pt; min-height:28px; padding:var(--space-1) 10px;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) :is(button, .button):hover{box-shadow:none; transform:none;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) button:not(.quiet):not(.link):enabled:hover{background:rgb(0 0 0 / .8);}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) :is(button.quiet, .button.quiet){background:var(--paper); box-shadow:var(--lift-1); color:var(--ink-2); transition:0.14s ease box-shadow;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) :is(button.quiet:enabled, .button.quiet):not([aria-pressed=true]):hover{background:var(--paper); box-shadow:var(--lift-3); color:var(--ink-2);}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) button.link{background:#0000; box-shadow:none; color:var(--ink); font-weight:normal; min-height:28px; padding:var(--space-1) 0;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) button:disabled{cursor:default; opacity:.4; transform:none;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) :is(input, select, textarea){background:var(--paper); border:0; border-radius:var(--space-2); box-shadow:var(--lift-1); color:var(--ink); font:400 13.5px/20px var(--font); min-height:var(--space-8); padding:6px var(--space-3); transition:0.14s ease box-shadow;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) :is(input, select, textarea):is(:focus-visible, :hover){background:var(--paper); box-shadow:var(--lift-3);}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) :is(a, button, input, select, textarea, summary, [tabindex]):focus-visible{outline:solid 2px var(--ink-2); outline-offset:2px;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) :is(input, select, textarea):focus-visible{box-shadow:var(--lift-3); outline:none;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) summary{border-radius:6px; color:var(--ink-2); font-size:9pt; padding:var(--space-1) var(--space-2);}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) summary:hover{background:rgb(0 0 0 / .03); color:var(--ink-2);}

/* Files: one aligned list, with 32px headings and 40px content rows. */
:root body main [data-view=files] :is(.file-column-head, .file){gap:var(--space-3); grid-template-columns:minmax(0, 1.3fr) 112px var(--track) 112px 132px;}
:root body main [data-view=files] .file-column-head{color:var(--ink-3); font-size:8.625pt; min-height:var(--space-8); padding:6px var(--space-3);}
:root body main [data-view=files] .files{gap:0;}
:root body main [data-view=files] .file{background:#0000; border-radius:var(--space-2); border:0; box-shadow:none; min-height:40px; padding:6px var(--space-3); transition:0.14s ease background-color;}
:root body main [data-view=files] .file:hover{background:rgb(0 0 0 / .03); box-shadow:none !important; transform:none;}
:root body main [data-view=files] .file:focus-within{box-shadow:none;}
:root body main [data-view=files] .file > .link{font-size:9pt; line-height:15pt;}
:root body main [data-view=files] .file > small{font-size:8.625pt; text-align:right; white-space:nowrap;}
:root body main [data-view=files] .file-column-head > :nth-child(4){text-align:right;}
:root body main [data-view=files] .file-order{gap:6px;}

/* Ledger: full-width groups, fixed number/time columns, no nested card grid. */
:root body main [data-view=ledger] .ledger-groups{display:grid; gap:var(--space-3); grid-template-columns:var(--track); margin:var(--space-3) 0 0;}
:root body main [data-view=ledger] .ledger-group{background:#0000; border:0; border-radius:var(--space-2); box-shadow:none; padding:0;}
:root body main [data-view=ledger] .ledger-group-head{background:var(--well); border-radius:var(--space-2); gap:6px; margin:0; min-height:var(--space-8); padding:var(--space-1) var(--space-3);}
:root body main [data-view=ledger] .ledger-group-head > h4{flex:1 1 0%; font-size:10.125pt; font-weight:var(--weight-medium); line-height:15pt; min-width:0;}
:root body main [data-view=ledger] .ledger-group-head > .hint{color:var(--records-faint); margin-left:6px; text-align:right; width:72px;}
:root body main [data-view=ledger] .ledger-group-head [data-card-icon]{background:#0000; height:var(--space-5); width:var(--space-5);}
:root body main [data-view=ledger] .ledger-group .ledger{gap:0; margin:0;}
:root body main [data-view=ledger] [data-ledger-row]{align-items:baseline; background:#0000; border:0; border-radius:var(--space-2); box-shadow:none; font-size:9pt; gap:var(--space-3); grid-template-columns:34px 72px 152px var(--track); line-height:15pt; min-height:40px; padding:10px var(--space-3); transition:0.14s ease background-color;}
:root body main [data-view=ledger] [data-ledger-row]:hover{background:rgb(0 0 0 / .03); box-shadow:none !important; transform:none;}
:root body main [data-view=ledger] [data-ledger-row]:focus-within{box-shadow:none;}
:root body main [data-view=ledger] .ledger .what{color:var(--ink-2); grid-column:auto;}
:root body main [data-view=ledger] .ledger .seq{color:var(--records-faint); text-align:right;}
:root body main [data-view=ledger] .ledger .seq::before{background:currentColor; border-radius:50%; content:""; display:inline-block; height:3px; margin-right:var(--space-1); vertical-align:middle; width:3px;}
:root body main [data-view=ledger] .ledger time{color:var(--ink-3); font-size:8.625pt;}
:root body main [data-view=ledger] .ledger .kind{background:#0000; color:var(--ink-2); font-size:8.625pt; padding:0;}

/* Library: a compact toolbar, clear shelves, and room around review decisions. */
:root body main [data-view=library] .library-tools{gap:var(--space-3); margin:0 0 var(--space-3);}
/* The legacy primary rule has seven exclusions; this ID beats its specificity. */
:root body main [data-view=library] #library-content button:not(.quiet):not(.link){background:var(--ink); border-radius:6px; box-shadow:none; min-height:28px;}
:root body main [data-view=library] #library-content button:not(.quiet):not(.link):enabled:hover{background:rgb(0 0 0 / .8); box-shadow:none;}
:root body main [data-view=library] .library-tools label{font-size:9pt; font-weight:normal; gap:6px;}
:root body main [data-view=library] #library-content > .library-tools label:last-child{flex:0 0 180px;}
:root body main [data-view=library] .library-filters{gap:2px; margin-bottom:var(--space-2);}
:root body main [data-view=library] .library-filters button.quiet{background:#0000; box-shadow:none; color:var(--ink-2); font-size:9pt; font-weight:normal; transition:0.14s ease background-color;}
:root body main [data-view=library] .library-filters button.quiet:enabled:not([aria-pressed=true]):hover{background:rgb(0 0 0 / .03); box-shadow:none;}
:root body main [data-view=library] .library-filters button.quiet[aria-pressed=true]{background:var(--wash); box-shadow:none; color:var(--ink);}
:root body main [data-view=library] .library-grid{gap:var(--space-3); grid-template-columns:var(--track); margin-bottom:var(--space-5);}
:root body main [data-view=library] .shelf-entry.card{align-items:start; border-radius:10px; box-shadow:var(--lift-1); display:grid; gap:var(--space-2) var(--space-3); grid-template-columns:var(--track) minmax(0, 1.5fr) 220px; margin:0; padding:var(--space-4); transition:0.14s ease box-shadow;}
:root body main [data-view=library] .shelf-entry > .library-meta:first-child{grid-column:1; grid-row:1;}
:root body main [data-view=library] .shelf-entry > h3{grid-column:1; grid-row:2;}
:root body main [data-view=library] .shelf-entry > .entry-path{grid-column:1; grid-row:3;}
:root body main [data-view=library] .shelf-entry > .entry-sentence{grid-column:2; grid-row:1 / 3;}
:root body main [data-view=library] .shelf-entry > .library-meta:not(:first-child){grid-column:3; grid-row:1;}
:root body main [data-view=library] .shelf-entry > p:not(.entry-sentence){grid-column:3; grid-row:2;}
:root body main [data-view=library] .shelf-entry > .library-tags{grid-column:3; grid-row:3;}
:root body main [data-view=library] .shelf-entry > .shelf-source{border:0; box-shadow:none; display:flex; flex-wrap:wrap; gap:var(--space-1) var(--space-3); grid-column:2; grid-row:3; padding:0;}
:root body main [data-view=library] .shelf-entry.card:hover{box-shadow:var(--lift-3);}
:root body main [data-view=library] :is(.shelf-entry, .proposal-card) h3{font-size:10.125pt; line-height:15pt; margin:0;}
:root body main [data-view=library] :is(.shelf-entry, .proposal-card) h3 [data-card-icon]{background:#0000; border-radius:5px; height:var(--space-5); width:var(--space-5);}
:root body main [data-view=library] :is(.entry-path, .entry-sentence, .history-reason, .proposal-source, .proposal-why){-webkit-line-clamp:unset; overflow:visible; word-wrap:anywhere; text-overflow:clip; white-space:normal;}
:root body main [data-view=library] .entry-sentence{color:var(--ink-2); font-size:9pt; line-height:15pt;}
:root body main [data-view=library] .shelf-source{border:0; box-shadow:inset 0 .5px 0 var(--line); gap:var(--space-1); padding-top:var(--space-2);}
:root body main [data-view=library] .library-tags{font-size:8.625pt; gap:6px;}
:root body main [data-view=library] .library-tags span{background:var(--well); border-radius:var(--space-1); color:var(--ink-3); padding:0 6px;}
:root body main [data-view=library] .library-history{border:0;}
:root body main [data-view=library] .library-history-row{border:0; border-radius:var(--space-2); gap:var(--space-3); grid-template-columns:var(--track) minmax(0px, 2fr); padding:var(--space-3);}
:root body main [data-view=library] .library-history-row:hover{background:rgb(0 0 0 / .03);}
:root body main [data-view=library] .history-name{gap:6px;}
:root body main [data-view=library] .history-name > a{font-weight:var(--weight-medium);}
:root body main [data-view=library] .history-record{gap:var(--space-1) var(--space-3);}
:root body main [data-view=library] .history-record + .history-record{border:0; box-shadow:inset 0 .5px 0 var(--line);}
:root body main [data-view=library] [data-library-uses]{color:var(--records-faint); display:inline-block; font-size:9pt; min-width:46px; text-align:right;}
:root body main [data-view=library] [data-library-uses]::before{border-radius:50%; box-shadow:inset 0 0 0 1px currentColor; content:""; display:inline-block; height:6px; margin-right:var(--space-1); vertical-align:1px; width:6px;}
:root body main [data-view=library] [data-entry-pending="0"]{color:var(--records-faint);}
:root body main [data-view=library] [data-library-section=waiting] > h3 .section-count{background:var(--attention-wash); border-radius:var(--space-1); color:var(--attention); padding:0 6px;}
:root body main [data-view=library] [data-library-section=waiting][data-section-count="0"] > h3 .section-count{background:#0000; color:var(--records-faint);}
:root body main [data-view=library] [data-library-section=history]{margin-bottom:var(--space-5);}
:root body main [data-view=library] .proposal-grid{grid-template-columns:var(--track);}
:root body main [data-view=library] .proposal-card.card{border-radius:var(--space-3); display:grid; gap:var(--space-5); grid-template-columns:var(--track) minmax(0, 1.4fr); margin:0; padding:var(--space-5);}
:root body main [data-view=library] :is(.proposal-intro, .proposal-changes, .proposal-body){align-content:start; display:grid; gap:var(--space-2);}
:root body main [data-view=library] .proposal-review{margin-top:var(--space-2);}
:root body main [data-view=library] .proposal-why{color:var(--ink-2); font-size:10.125pt; line-height:15pt;}
:root body main [data-view=library] :is(.entry-diff, [data-lib-text]){background:var(--well); border-radius:var(--space-2); color:var(--ink-2);}
:root body main [data-view=library] .diff-number{color:var(--records-faint);}
:root body main [data-view=library] :is(.entry-columns, .version-outcome-layout){gap:var(--space-3);}
:root body main [data-view=library] .entry-columns{grid-template-columns:var(--track) 320px;}
:root body main [data-view=library] .entry-origin{gap:6px var(--space-3); margin-bottom:var(--space-5);}
:root body main [data-view=library] .entry-text-card [data-lib-text]{padding:var(--space-3) var(--space-3) var(--space-3) 40px;}
:root body main [data-view=library] .text-line::before{color:var(--records-faint);}
:root body main [data-view=library] .entry-history .version-list{gap:var(--space-3);}
:root body main [data-view=library] .entry-history .version-list li{gap:var(--space-2); padding-bottom:0;}
:root body main [data-view=library] .entry-history .version-list::before{background:var(--line); border:0; width:.5px;}
:root body main [data-view=library] .entry-history .version-list li::before{background:var(--records-faint); height:6px; width:6px;}
:root body main [data-view=library] .version-list a[aria-current]{background:var(--wash); font-weight:normal;}
:root body main [data-view=library] .version-compare{margin-top:var(--space-5);}
:root body main [data-view=library] [data-keep-form]{gap:var(--space-5); margin:0 auto; max-width:720px; padding:var(--space-5);}
:root body main [data-view=library] .keep-kinds input{accent-color:var(--ink); box-shadow:none; min-height:var(--space-4);}
:root body main [data-view=library] [data-efficiency]{gap:var(--space-3); grid-template-columns:320px var(--track); margin-top:var(--space-5);}
:root body main [data-view=library] :is([data-eff-chart], [data-version-chart]){height:auto; margin:0; width:100%;}
:root body main [data-view=library] :is(.chart-label, .axis-label){fill:var(--ink-3); font-size:8.625pt;}
:root body main [data-view=library] .chart-value{fill:var(--ink); font-size:10.125pt;}
:root body main [data-view=library] .chart-grid{stroke:var(--line); stroke-width:.5;}
:root body main [data-view=library] .chart-bar{fill:var(--run); fill-opacity:.61;}
:root body main [data-view=library] :is(th, td){border:0; font-size:9pt; height:40px; line-height:15pt; padding:10px var(--space-2);}
:root body main [data-view=library] th{color:var(--ink-3); font-weight:normal; height:var(--space-8); padding:6px var(--space-2);}
:root body main [data-view=library] tbody tr{background:#0000;}
:root body main [data-view=library] .eff-table td{background:#0000;}
:root body main [data-view=library] tbody tr:hover{background:rgb(0 0 0 / .03);}
:root body main [data-view=library] .eff-table :is(th, td):nth-child(2),
:root body main [data-view=library] .eff-table :is(th, td):nth-child(3){text-align:right; width:88px;}
:root body main [data-view=library] .eff-table :is(th, td):nth-child(4){text-align:right; width:80px;}
:root body main [data-view=library] .eff-table th:last-child{width:20%;}
:root body main [data-view=library] .version-table :is(th, td):nth-child(n+4){text-align:right; width:80px;}

/* Board: equal lanes, quiet headings, status expressed on the orders themselves. */
:root body main [data-view=board] .board{align-items:stretch; gap:var(--space-3); grid-template-columns:repeat(4, var(--track));}
:root body main [data-view=board] .board-column.card{background:var(--well); border-radius:var(--space-3); box-shadow:none; margin:0; padding:var(--space-3);}
:root body main [data-view=board] .board-column > h3{align-items:center; border:0; display:flex; font-size:10.125pt; gap:6px; line-height:15pt; margin:0 0 var(--space-2); min-height:var(--space-8); padding:0;}
:root body main [data-view=board] .board-column > h3 [data-card-icon]{background:#0000; height:var(--space-5); width:var(--space-5);}
:root body main [data-view=board] .column-count{margin-left:auto; padding:0;}
:root body main [data-view=board] .orders{gap:var(--space-3);}
:root body main [data-view=board] .order.card{background:var(--paper); border-radius:var(--space-2); box-shadow:var(--lift-1); gap:var(--space-2); margin:0; padding:var(--space-3); transition:0.14s ease box-shadow;}
:root body main [data-view=board] .order.card:hover{background:var(--paper); box-shadow:var(--lift-3) !important; transform:none;}
:root body main [data-view=board] .order-title{font-size:10.125pt; font-weight:var(--weight-medium); line-height:15pt;}
:root body main [data-view=board] .lead-seat{gap:6px;}
:root body main [data-view=board] .lead-seat > :is(.logo, .seat-icon){height:var(--space-5); width:var(--space-5);}
:root body main [data-view=board] .lead-details strong{font-size:9pt; font-weight:normal;}
:root body main [data-view=board] .lead-details .model{font-size:8.625pt; line-height:12pt;}
:root body main [data-view=board] .order-step-summary{gap:var(--space-2);}
:root body main [data-view=board] .order-step-caption{color:var(--ink-3); font-size:8.625pt; gap:6px;}
:root body main [data-view=board] .order[data-state=SUCCEEDED] .cp-graph-progress{color:var(--ok);}
:root body main [data-view=board] .order:is([data-state=LEASED], [data-state=JUDGING]) .cp-graph-progress{color:var(--run);}
:root body main [data-view=board] .order:is([data-state=FAILED], [data-state=DEAD]) .cp-graph-progress{color:var(--bad);}
:root body main [data-view=board] :is(.progress-track, .step-track){border-radius:2px; height:var(--space-1);}
:root body main [data-view=board] [data-progress]{gap:6px;}

/* Empty, loading and failure are layouts, retaining every existing message/action.
 * Loading uses the actual three blocks and static row-shaped skeletons. */
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .empty{align-items:center; background:var(--well); border-radius:var(--space-2); display:flex; flex-direction:column; gap:var(--space-2); justify-content:center; min-height:120px; padding:var(--space-5); text-align:center;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .empty :is(svg, svg.empty-art){background:var(--wash); border-radius:10px; color:var(--ink-3); flex:0 0 42px; height:42px; width:42px;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .empty-tone{fill:rgb(0 0 0 / .06);}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .empty-art{--hero-blue:rgb(0 0 0 / .06); --hero-peach:rgb(0 0 0 / .12); --hero-sky:rgb(0 0 0 / .06);}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .empty-detail{stroke:var(--ink-3); stroke-opacity:1;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .empty strong{color:var(--ink); font-size:10.125pt; font-weight:var(--weight-medium); line-height:15pt;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .empty p{color:var(--ink-3); font-size:9pt; line-height:15pt; margin:var(--space-1) 0 0; max-width:480px;}
:root body main [data-view=board] .board .empty{background:#0000; min-height:160px; padding:var(--space-3) 0;}
:root body main [data-view=library] [data-library-section] > .empty{flex-direction:row; justify-content:start; min-height:80px; padding:var(--space-3) var(--space-4); text-align:left;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .skeleton{background:var(--paper); border-radius:var(--space-3); box-shadow:var(--lift-1); gap:var(--space-3); min-height:160px; padding:var(--space-3);}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .skeleton span{background:var(--skeleton); border-radius:6px; height:var(--space-5); max-width:100%;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .skeleton span:first-child{height:var(--space-4); width:28%;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) .skeleton span:last-child{height:var(--space-5); width:72%;}
:root body main [data-view=board] .board > .skeleton{grid-column:1 / -1;}
:root body main [data-view=ledger] .ledger-groups > li:has(> .skeleton){display:block; padding:0;}
:root body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) :is(.form-error, [role=alert], .notice){background:var(--bad-wash); border:0; border-radius:var(--space-2); color:var(--bad); font-size:9pt; line-height:15pt; padding:var(--space-3);}
:root body:has(main > :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]):not([hidden])) #notice{background:var(--attention-wash); border-radius:var(--space-2); color:var(--attention); margin:0 0 var(--space-5); padding:var(--space-3);}

/* Preview stays on its owning view and shares the same paper and ink. */
:root body:has(main > [data-view=files]:not([hidden])) .preview{background:var(--paper); border:0; border-radius:var(--space-3); box-shadow:0 0 0 .5px rgb(0 0 0 / .1), 0 12px 32px -8px rgb(0 0 0 / .16); color:var(--ink-2);}
:root body:has(main > [data-view=files]:not([hidden])) .preview-head{background:var(--well); border:0; box-shadow:0 -.5px 0 var(--line) inset; font-weight:var(--weight-medium); padding:var(--space-3);}
:root body:has(main > [data-view=files]:not([hidden])) #preview-close{background:#0000; border-radius:7px; box-shadow:none; color:var(--ink-2); height:28px; min-height:28px; padding:0; transform:none; width:28px;}
:root body:has(main > [data-view=files]:not([hidden])) #preview-close:hover{background:rgb(0 0 0 / .03);}

/* The existing data-motion switch also governs these single-property entrances. */
@keyframes records-reveal{ 0%{opacity:0;} 100%{opacity:1;} }
@keyframes records-leave{ 0%{opacity:1;} 100%{opacity:0;} }
:root[data-motion=on] body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) :is([data-enter], [data-live-enter], [data-board-move], [data-list-window][data-expanded]){animation:records-reveal 200ms ease; opacity:1; transform:none;}
:root[data-motion=on] body main [data-view=library] .proposal-card[data-proposal-phase=leaving]{animation:records-leave 150ms ease;}
:root[data-motion=reduce] body main :is([data-view=files], [data-view=ledger], [data-view=library], [data-view=board]) *{animation:none;}


/* The same proposal can appear on the Home page, its shelf and its version detail. */
:root body :is(#home-proposals, #library-content) [data-proposal-card]{
  display:grid;
  grid-template-columns:repeat(auto-fit, minmax(min(100%, 18rem), 1fr));
  align-items:start;
  gap:var(--space-3);
  padding:var(--space-4);
  border-radius:var(--round-card);
  font:400 13.5px/20px var(--font);
  letter-spacing:normal;
}
:root :is(#home-proposals, #library-content) [data-proposal-card] :is(.proposal-intro, .proposal-changes, .proposal-body){
  display:grid;
  align-content:start;
  gap:var(--space-2);
}
:root :is(#home-proposals, #library-content) [data-proposal-card] :is(h3, p){
  margin:0;
  line-height:20px;
}
:root :is(#home-proposals, #library-content) [data-proposal-card] h3{
  font-size:13.5px;
}
:root :is(#home-proposals, #library-content) [data-proposal-card] h3 [data-card-icon]{
  inline-size:20px;
  block-size:20px;
}
:root :is(#home-proposals, #library-content) [data-proposal-card] :is(.hint, time, .library-meta, .diff-line){
  font-size:12px;
  line-height:20px;
}
:root :is(#home-proposals, #library-content) [data-proposal-card] .proposal-review{
  margin-block-start:var(--space-2);
}
:root :is(#home-proposals, #library-content) [data-proposal-card] :is(.proposal-review button, .proposal-review summary){
  padding:4px 8px;
  min-block-size:36px;
}
:root :is(#home-proposals, #library-content) [data-proposal-card] :is(.kind-chip, .version-chip){
  padding:1px 6px;
  font-size:12px;
  line-height:16px;
}
:root :is(#home-proposals, #library-content) [data-proposal-card] .kind-chip svg{
  inline-size:12px;
  block-size:12px;
}
:root :is(#home-proposals, #library-content) [data-proposal-card] .seat-icon{
  max-inline-size:32px;
  max-block-size:32px;
}

/* On phones keep the five board lanes and the complete receipt in reading order. */
@media (max-width: 760px) {
  html[data-layout=responsive] body:has([data-view=board]:not([hidden]), [data-view=ledger]:not([hidden]), [data-view=files]:not([hidden]), [data-view=library]:not([hidden])) {
    grid-template: none / var(--track);
  }
  html[data-layout=responsive] body:has([data-view=board]:not([hidden]), [data-view=ledger]:not([hidden]), [data-view=files]:not([hidden]), [data-view=library]:not([hidden])) .workspace {
    margin: 0;
    padding: var(--space-3);
  }
  html[data-layout=responsive] :is([data-view=files], [data-view=ledger], [data-view=board]) {
    --receipt-span: 1 / -1;
    overflow-wrap: anywhere
  }
  html[data-layout=responsive] :is(#ledger-stats, #files-stats, #board-stats) {
    grid-template: none / repeat(2, var(--track));
  }
  html[data-layout=responsive] :is(#files-stats, #ledger-stats, #board-stats) .stat {
    grid-template: none / var(--track) auto;
    padding: var(--space-2);
  }
  html[data-layout=responsive] :is(#files-stats, #ledger-stats, #board-stats) .stat > [data-card-icon] { display: none; }
  html[data-layout=responsive] #board-columns .task-columns { grid-template: none / var(--track); }
  html[data-layout=responsive] #board-columns .task-toolbar {
    grid-template: none / var(--track) var(--track);
    display: grid;
  }
  html[data-layout=responsive] #board-columns .task-toolbar label { min-inline-size: 0; }
  html[data-layout=responsive] #board-columns .task-toolbar label:first-child { grid-column: var(--receipt-span); }
  html[data-layout=responsive] #board-columns .task-items { min-block-size: 0; }
  html[data-layout=responsive] #board-columns[data-mode=list] .task-card { grid-template: none / var(--track) auto; }
  html[data-layout=responsive] #board-columns[data-mode=list] .task-card :is(.task-actions, .task-root) { grid-column: var(--receipt-span); }
  html[data-layout=responsive] body main [data-view=files] .file { grid-template: none / var(--track) var(--track); }
  html[data-layout=responsive] body main [data-view=files] .file > button.link { grid-column: var(--receipt-span); }
  html[data-layout=responsive] body main [data-view=files] .file-column-head { display: none; }
  html[data-layout=responsive] body main [data-view=ledger] .ledger-group [data-ledger-row] {
    grid-template: none / auto auto var(--track);
  }
  html[data-layout=responsive] body main [data-view=ledger] .ledger-group .what { grid-column: var(--receipt-span); }
}

/* A single surface connects the collection to its measured totals. */
#library-content .library-overview{
  background:radial-gradient(ellipse at 72% -12%, #ee9aa4 4%, transparent 63%),
    radial-gradient(ellipse at 15% 100%, #9ac2f1, transparent 52%),
    linear-gradient(118deg, #faede3, #cfb5f0 59%, #d8edf0);
  border-radius:var(--space-3);
  padding:var(--space-4) var(--space-4) 28px;
  margin-block-end:var(--space-5);
}
#library-content .library-overview .page-head{ margin-block:0 18px; }
#library-content .library-overview h2{ font-size:clamp(26px, 2.6vw, 38px); letter-spacing:-.042em; line-height:1.1; }
#library-content .library-overview .view-stats{ grid-template-columns:repeat(4, var(--track)); margin-block-end:0; }
#library-content .library-overview .stat{ background-color:rgb(255 255 255 / .89); }
#library-content .library-primary{
  background-color:#263e74;
  color:white;
  font-weight:var(--weight-medium);
  border-radius:9px;
  padding:9px 15px;
  text-decoration-line:none;
}
#library-content .library-primary:hover{ background-color:#385655; }
#library-content .library-quiet-shelves{ display:flex; flex-wrap:wrap; column-gap:22px; margin-block:12px 20px; }
#library-content .library-quiet-shelves h3{ font:inherit; color:var(--ink-3); margin:0; }
#library-content .library-history-row{
  background:var(--paper); box-shadow:var(--lift-1);
  padding:16px 18px; grid-template-columns:minmax(13em,.9fr) minmax(0,1.3fr);
}
#library-content .history-name{ align-content:center; row-gap:5px; }
#library-content .history-name > a{ font-size:1.04rem; font-weight:620; }
#library-content .library-run-result{ color:var(--ink-3); font-variant-numeric:tabular-nums; }
#library-content .library-discovery{ border-block-end:1px solid var(--line); padding-block-end:var(--space-2); }
#library-content .library-tools{ display:grid; grid-template-columns:minmax(9em, 1fr) minmax(8em, 12em); }
#library-content .library-found{ display:flex; align-items:baseline; gap:12px; font-size:.85rem; }
#library-content .library-source-panel{ background-color:var(--paper); box-shadow:var(--lift-1); padding:18px; margin-block:14px; border-radius:12px; }
#library-content .library-source-panel h3{ margin-block:0 8px; }
#library-content .library-panel-head{ display:flex; flex-wrap:wrap; align-items:baseline; justify-content:space-between; gap:12px; }
#library-content .library-panel-head label{ font-size:.78rem; }
#library-content .library-scroll{ overflow-x:auto; margin-block:8px 14px; }
#library-content .library-scroll table{ inline-size:100%; text-align:start; border-collapse:collapse; }
#library-content .library-scroll :is(th,td){ padding:8px 10px; text-align:start; border-block-end:1px solid var(--line); }
#library-content .library-catalog-list{ padding-inline-start:0; list-style:none; display:grid; gap:8px; }
#library-content .library-catalog-list li{ display:grid; grid-template-columns:1fr 1fr 1fr; gap:8px; }
#library-content .library-jumps{ position:static; display:flex; flex-flow:row wrap; gap:4px; min-height:0; height:auto; margin-block:-3px 12px; padding:0; background:none; }
#library-content .library-jumps button{ color:#345555; border-radius:6px; background-color:#eaf2ef; }
#library-content .library-handins{ list-style:none; padding-inline:0; margin-block:0; }
#library-content .library-handins li{ display:grid; grid-template-columns:1fr 1fr auto; align-items:center; padding-block:9px; gap:16px; }
#library-content .library-handins :is(small,code){ display:block; color:var(--ink-3); overflow-wrap:anywhere; }
#library-content .library-lineage{ background:#eef4f3; border-radius:10px; padding:12px 16px; margin-block:12px; }
#library-content .library-lineage :is(h3,p){ margin-block:3px; }
@media (max-width:900px){
  html[data-route=library] .workspace{ min-inline-size:0; }
  #library-content{ overflow-wrap:anywhere; }
  #library-content :is(.library-history-row,.library-handins li,.entry-columns,.version-outcome-layout,.shelf-entry.card,.proposal-card,.library-catalog-list li){
    grid-template-columns:var(--track);
  }
  #library-content :is(.shelf-entry.card,.proposal-card) > *{ grid-area:auto; }
  #library-content .library-panel-head label{ min-width:0; max-inline-size:100%; }
  #library-content :is(.library-panel-head select,.entry-path){ max-inline-size:100%; }
  #library-content [data-efficiency]{ display:block; }
  #library-content :is(.eff-table,.version-table){ display:block; overflow-x:auto; }
  #library-content .entry-header{ align-items:start; flex-direction:column; }
}
@media (max-width:760px){
  html[data-route=library] .workspace{ margin-inline:0; padding:12px; }
  #library-content .library-overview{ padding:13px; }
  #library-content :is(.library-overview .view-stats,.entry-stats){ grid-template-columns:repeat(2,var(--track)); gap:7px; }
  #library-content .library-overview .stat{ padding:8px 10px; }
  #library-content .library-overview .stat > [data-card-icon]{ display:none; }
  #library-content .library-overview .page-head{ gap:7px; margin-block-end:12px; }
  #library-content .library-tools{ grid-template-columns:var(--track) minmax(6em,.48fr); gap:8px; }
  #library-content .library-tools label{ min-inline-size:0; }
  #library-content :is(.library-tools input,.library-tools select,.library-jumps button,.library-filters button){ min-height:40px; }
  #library-content .library-handins li{ row-gap:7px; }
  #library-content .history-records{ grid-column:1; }
  #library-content .library-panel-head{ display:grid; }
  #library-content :is(.library-source-panel,.library-history-row){ padding:12px; }
  #library-content .entry-stats .stat{ min-width:0; }
}
@media (min-width:761px) and (max-width:900px){
  html[data-route=library] body:has(#library-content){ grid-template-columns:140px var(--track); }
}
@media (max-width:760px){
  html[data-route=library] body:has(#library-content){ grid-template:auto 1fr / var(--track); }
  html[data-route=library] body:has(#library-content) .workspace{ padding:10px; margin:0; }
  html[data-route=library] .top .brand .eyebrow{ display:none; }
  html[data-route=library] .top .meters{ flex-wrap:wrap; }
  html[data-route=library] #status-chip{ white-space:normal; }
  #library-content .library-overview .stat{ display:grid; grid-template-columns:var(--track) auto; gap:2px; }
  #library-content .library-overview .stat > .stat-label{ grid-area:1 / 1; align-self:center; }
  #library-content .library-overview [data-stat-value]{ grid-area:1 / 2; }
  #library-content .library-overview [data-stat-note]{ grid-area:2 / 1 / auto / -1; }
}
#library-content .library-source-columns{ display:grid; grid-template-columns:repeat(auto-fit,minmax(min(100%,16rem),1fr)); gap:16px; }
#library-content .library-source-columns h4{ font-size:1rem; margin-block:8px; }
#library-content .library-source-columns input{ min-inline-size:0; max-inline-size:100%; }
#library-content .library-local-list{ padding-inline-start:17px; }
#library-content .library-local-list button{ white-space:normal; text-align:start; }
#library-content [data-local-preview]{ white-space:pre-wrap; max-block-size:20rem; overflow:auto; background-color:var(--well); padding:12px; }

#library-content .library-recent{ color:#3c4753; margin-block:4px 0; }
#library-content .library-primary{ max-inline-size:min(34ch,55%); }
#library-content .library-jumps summary{ cursor:pointer; border-radius:6px; padding:6px 10px; }
#library-content .library-jumps details[open]{ background:var(--well); border-radius:8px; }
#library-content .history-name{ flex-wrap:wrap; justify-content:start; }
#library-content .history-name .library-run-result{ flex-basis:100%; }
@media (max-width:760px){
  #library-content .library-overview [data-stat-note]{ display:none; }
  #library-content .library-overview .stat{ min-height:44px; align-content:center; }
  #library-content .library-primary{ padding:8px 11px; }
  #library-content .library-jumps summary{ min-block-size:40px; align-content:center; }
  html[data-route=library] .top .meters{ gap:4px; }
  html[data-route=library] .top{ padding-block-end:6px; margin-block-end:10px; }
}
