/* Team only. ui-foundation: four inks, quiet surfaces, one interval per layer.
   Keep the graph's coordinates, measured data and all native controls intact. */
:root body [data-view=team],
:root body:has([data-view=team]:not([hidden])) #seat-drawer{--attention:#945000; --attention-wash:rgb(148 80 0 / .12); --bad:#b73925; --bad-wash:rgb(183 57 37 / .10); --canvas:#f8f8f8; --ease:cubic-bezier(.22, 1, .36, 1); --ink:var(--team-ink); --ink-16:var(--line); --ink-2:var(--team-body); --ink-28:var(--team-faint); --ink-3:var(--team-secondary); --ink-38:var(--team-faint); --ink-58:var(--team-secondary); --ink-66:var(--team-secondary); --ink-68:var(--team-secondary); --ink-70:var(--team-secondary); --ink-72:var(--team-secondary); --ink-76:var(--team-body); --ink-80:var(--team-body); --ink-86:var(--team-ink); --ink-92:var(--team-ink); --leading-display:28px; --leading-lg:28px; --leading-md:24px; --leading-sm:20px; --leading-xs:16px; --lift-1:0 0 0 .5px rgb(0 0 0 / .06), 0 1px 1px -1px rgb(0 0 0 / .10), 0 1px 2px rgb(0 0 0 / .05); --lift-2:0 0 0 .5px rgb(0 0 0 / .10), 0 1px 1px -1px rgb(0 0 0 / .10), 0 2px 6px -1px rgb(0 0 0 / .08); --lift-3:0 0 0 .5px rgb(0 0 0 / .10), 0 12px 32px -8px rgb(0 0 0 / .16); --line:rgb(0 0 0 / .06); --line-2:rgb(0 0 0 / .10); --mono-ink:var(--team-body); --mono-wash:var(--well); --motion:140ms; --ok:#197340; --ok-wash:rgb(25 115 64 / .10); --paper:#ffffff; --round-button:6px; --round-card:12px; --round-chip:4px; --round-control:8px; --round-hero:12px; --round-icon:8px; --round-pill:4px; --run:#006dcb; --run-wash:rgb(0 109 203 / .10); --shadow:var(--lift-2); --shadow-small:var(--lift-1); --skeleton:var(--line); --team-body:rgb(0 0 0 / .61); --team-faint:rgb(0 0 0 / .27); --team-ink:rgb(0 0 0 / .88); --team-secondary:rgb(0 0 0 / .45); --text-caption:12px; --text-copy:13.5px; --text-display:22px; --text-emphasis:13.5px; --text-lg:17px; --text-md:13.5px; --text-micro:11.5px; --text-sm:13.5px; --text-stat:22px; --text-unit:11.5px; --text-xl:22px; --text-xs:12px; --time:var(--team-secondary); --wait:var(--team-body); --wait-wash:var(--wash); --wash:rgb(0 0 0 / .04); --well:rgb(0 0 0 / .02); color:var(--team-body); font-size:10.125pt; font-weight:normal; font-variant-numeric:var(--number-style); letter-spacing:0; line-height:15pt;}

/* Roles, not a separate size or weight for every component. */
:root body [data-view=team] :is(h3, h4, strong, b, th, .seat-name, .group-heading, .eyebrow){font-weight:var(--weight-medium);}
:root body [data-view=team] label{font-weight:normal;}
:root body [data-view=team] :is(h3, h4, strong, .seat-name, .order-title){color:var(--team-ink);}
:root body [data-view=team] h2{font-size:16.5pt; font-weight:var(--weight-heading); letter-spacing:-.01em; line-height:21pt;}
:root body [data-view=team] h3{font-size:12.75pt; letter-spacing:0; line-height:18pt; margin-bottom:var(--space-2);}
:root body [data-view=team] :is(.hint, .drawing-caption, .seat-model, .sub, time, [data-stat-note]){color:var(--team-secondary); font-size:9pt; line-height:12pt;}
:root body [data-view=team] :is(.eyebrow, .number-unit, .group-heading, th, .pill, .badge, .axis-label){font-size:8.625pt;}
:root body [data-view=team] :is(.eyebrow, .group-heading){color:var(--team-secondary); letter-spacing:0; text-transform:none;}
:root body [data-view=team] :is(.diagram-name, .cp-graph-initials){fill:var(--team-ink); font-weight:var(--weight-medium);}
:root body [data-view=team] .axis-label:not([data-seat-state]){fill:var(--team-secondary);}
:root body [data-view=team] .page-head{margin:0 0 var(--space-5);}
:root body [data-view=team] .eyebrow{margin:0 0 var(--space-1);}
:root body [data-view=team] .drawing-caption{margin:0 0 var(--space-3);}

/* 12 between cards; 16 inside them; 8 within a block; 6 in a control. */
:root body [data-view=team] :is(.card, .cp-graph-card){background:var(--paper); border:0; border-radius:var(--space-3); box-shadow:var(--lift-1);}
:root body [data-view=team] :is(#team-drawings > .card, #team-canvas-slot > .card, #team-seat-slot > .card, .team-overview > .card, .team-comparison > .card),
:root body [data-view=team] > section.card{margin-bottom:var(--space-3); padding:var(--space-4);}
:root body [data-view=team] :is(.team-overview, .team-comparison, .team, .handoff-cards){gap:var(--space-3);}
:root body [data-view=team] .team-overview{align-items:start; grid-template-columns:minmax(0, 1.65fr) var(--track);}
/* Beat the legacy card rule's chain of exclusions without changing other views. */
:root body [data-view=team] #team-drawings .drawing-card,
:root body [data-view=team] #team-drawings .full-seat-panel,
:root body [data-view=team] > section.card{box-shadow:var(--lift-1);}
:root body [data-view=team] :is(.block-head, .seat-head, .who, .seat-relations){gap:var(--space-2);}
:root body [data-view=team] :is(.seat-band, .seat-band .seat-icon){background:#0000; box-shadow:none;}
:root body [data-view=team] .card > .seat-band{padding:0;}
:root body [data-view=team] .seat-band .seat-name{color:var(--team-ink);}
:root body [data-view=team] .seat-band .seat-model{margin:var(--space-2) 0 0;}
:root body [data-view=team] .seat{gap:var(--space-3); padding:var(--space-4);}
:root body [data-view=team] :is(.seat-run, .seat-launch, .handoff-card, .handoff-seat){background:var(--paper); border:0; border-radius:10px; box-shadow:var(--lift-1);}
:root body [data-view=team] :is(.seat-reference-list > div, .seat-message){background:var(--well); border:0; border-radius:var(--space-2); box-shadow:none;}

/* Compact stat tiles keep their real, axis-free graphics beside the figures. */
:root body [data-view=team] [data-team-stats]{gap:var(--space-3); margin-bottom:var(--space-3);}
:root body [data-view=team] [data-team-stats] .stat{align-content:start; display:grid; gap:var(--space-2); grid-template-columns:var(--track) 28px; grid-template-rows:32px 28px auto; min-height:124px; padding:var(--space-3);}
:root body [data-view=team] [data-team-stats] .stat > .stat-label{color:var(--team-secondary); font-size:9pt; grid-column:1; grid-row:1; line-height:12pt;}
:root body [data-view=team] [data-team-stats] .stat > [data-card-icon]{align-self:center; grid-column:2; grid-row:2; margin:0;}
:root body [data-view=team] [data-team-stats] .stat > strong{color:var(--team-ink); font-size:16.5pt; font-weight:var(--weight-medium); grid-column:1; grid-row:2; letter-spacing:-.01em; line-height:21pt; margin:0; white-space:nowrap;}
:root body [data-view=team] [data-team-stats] [data-stat-note]{grid-column:1 / -1; grid-row:3; margin:0;}
:root body [data-view=team] [data-team-stats] .stat-chart{align-self:center; grid-column:1 / -1; grid-row:4; margin:0;}
:root body [data-view=team] [data-team-stats] .stat-series{height:var(--space-4);}
:root body [data-view=team] [data-card-icon]{background:var(--well); border-radius:7px; box-shadow:none; color:var(--team-secondary); height:28px; width:28px;}
:root body [data-view=team] [data-card-icon] > svg{height:var(--space-4); width:var(--space-4);}
:root body [data-view=team] :is(.glyph, .activity-icon){color:var(--team-secondary); stroke-width:1.9;}
:root body [data-view=team] :is(.usage-track, .usage-track > span, .stat-chart, .progress-track, .step-track){border-radius:2px;}
:root body [data-view=team] :is(.spark-line, .stat-series-line){stroke-width:1.5; stroke-linecap:round; vector-effect:non-scaling-stroke;}

/* The optional HTML tree and the original SVG share the same quiet hierarchy. */
:root body [data-view=team] .cp-graph-tree{padding:var(--space-2) 0;}
:root body [data-view=team] .cp-graph-card{border-radius:10px; display:grid; gap:2px var(--space-2); grid-template-columns:28px var(--track); max-width:100%; padding:var(--space-2); width:200px;}
:root body [data-view=team] .cp-graph-heading{gap:var(--space-2); grid-column:1 / -1;}
:root body [data-view=team] .cp-graph-heading strong{font-size:10.125pt; line-height:15pt;}
:root body [data-view=team] .cp-graph-card > .hint{font-size:8.625pt; grid-column:1 / -1; line-height:12pt; margin:0;}
:root body [data-view=team] .cp-graph-card > .badge{grid-column:1 / -1; justify-self:start;}
:root body [data-view=team] .cp-graph-card > button{font-size:9pt; bottom:6px; right:6px; line-height:12pt; min-height:var(--space-6);}
:root body [data-view=team] .cp-graph-children{align-items:flex-start; display:flex; flex-wrap:wrap; gap:var(--space-3); justify-content:center; margin-top:var(--space-5); padding-left:0;}
:root body [data-view=team] .cp-graph-children .cp-graph-children{display:grid; gap:var(--space-3); margin-top:var(--space-3); padding-left:var(--space-5);}
:root body [data-view=team] .cp-graph-tree[data-graph-wide=true] > .cp-graph-branch > .cp-graph-children{gap:var(--space-3); margin-top:var(--space-5);}
:root body [data-view=team] .cp-graph-children > .cp-graph-branch{flex:1 1 176px;}
:root body [data-view=team] .cp-graph-card{margin-inline:auto;}
:root body [data-view=team] .cp-graph-avatar-wash{stroke:none;}
:root body [data-view=team] .org-box{fill:var(--paper); rx:10px; stroke:var(--line); stroke-width:.5;}
:root body [data-view=team] [data-org-node]:has(button):hover .org-surface{transform:none;}
:root body [data-view=team] [data-org-node]:has(button):hover .org-box{filter:none; stroke:var(--line-2);}
:root body [data-view=team] .cp-graph-card:has(button):hover{box-shadow:var(--lift-2);}
:root body [data-view=team] [data-org]:has([data-select-clear]) .cp-graph-card:not([data-dim]),
:root body [data-view=team] [data-org]:has([data-select-clear]) .cp-graph-card:not([data-dim]):hover{background:var(--wash); box-shadow:var(--lift-1);}
:root body [data-view=team] [data-org]:has([data-select-clear]) [data-org-node]:not([data-dim]) .org-box{fill:var(--wash);}
:root body [data-view=team] button.seat-select:hover{box-shadow:inset 0 0 0 .5px var(--line-2);}

/* Model rows: aligned counts and time shares, no nested grey cards or rules. */
:root body [data-view=team] .team-overview [data-usage]{align-content:start; display:grid; gap:var(--space-3); grid-auto-rows:auto;}
:root body [data-view=team] [data-usage] > :is(h3, .drawing-caption){margin:0;}
:root body [data-view=team] .card .usage-row{background:#0000; border:0; border-radius:var(--space-2); box-shadow:none; gap:var(--space-2) var(--space-3); grid-template-columns:28px var(--track) 76px; margin:0; padding:var(--space-3) 0;}
:root body [data-view=team] .usage-model strong{font-size:10.125pt; font-weight:var(--weight-medium); line-height:15pt;}
:root body [data-view=team] :is([data-usage-launches], [data-usage-seconds]){color:var(--team-secondary); font-size:9pt; line-height:15pt; text-align:right; width:76px;}
:root body [data-view=team] .usage-track{align-self:center; background:var(--line);}
:root body [data-view=team] .usage-seats{gap:6px;}
:root body [data-view=team] .seat-chip{background:#0000; color:var(--team-body); font-size:9pt; font-weight:normal; gap:var(--space-1);}

/* Numerals align through fixed slots, with the existing sparkline or an icon. */
:root body [data-view=team] .seat .seat-summary{gap:0; grid-template-columns:var(--track); margin-top:var(--space-2);}
:root body [data-view=team] .seat .seat-summary > div{align-items:center; background:#0000; display:grid; gap:var(--space-2); grid-template-columns:14px 64px var(--track); min-height:var(--space-8); padding:0;}
:root body [data-view=team] .seat-summary strong{color:var(--team-body); font-size:10.125pt; font-weight:normal; line-height:15pt; min-width:64px; text-align:right;}
:root body [data-view=team] .seat-summary > div > span{color:var(--team-secondary); font-size:9pt; line-height:15pt;}
:root body [data-view=team] [data-seat-summary]::before{border-radius:50%; box-shadow:inset 0 0 0 1.2px var(--team-faint); content:""; height:var(--space-3); width:var(--space-3);}
:root body [data-view=team] [data-seat-summary=seconds]::before{background:conic-gradient(from 0deg, var(--team-faint) 0deg 90deg, #0000 90deg);}
:root body [data-view=team] [data-seat-summary=accepted]::before{background:var(--ok-wash); box-shadow:inset 0 0 0 1.2px currentColor; color:var(--ok);}
:root body [data-view=team] [data-seat-summary=sent-back]::before{border-radius:var(--space-1);}
:root body [data-view=team] .seat-full-stats{border:0; box-shadow:inset 0 -.5px var(--line); gap:var(--space-3); margin:var(--space-3) 0 var(--space-5); padding:var(--space-3) 0;}
:root body [data-view=team] .full-seat-panel .work-stat{min-width:140px; min-height:48px;}
:root body [data-view=team] :is(.work-stat strong, [data-seat-tile] strong){color:var(--team-ink); font-size:16.5pt; font-weight:var(--weight-medium); line-height:21pt; min-width:64px;}
:root body [data-view=team] .seat-totals{gap:var(--space-3); margin:var(--space-3) 0 var(--space-5);}
:root body [data-view=team] [data-seat-tile]{background:var(--well); border:0; border-radius:var(--space-2); box-shadow:none; font-size:9pt; min-width:110px; padding:var(--space-3);}
:root body [data-view=team] .seat-full-columns{gap:var(--space-5); grid-template-rows:auto 48px 176px; margin-bottom:var(--space-3);}
:root body [data-view=team] .seat-full-columns:has([data-expanded]){grid-template-rows:auto 48px auto;}
:root body [data-view=team] :is(.seat-messages, .seat-run-list){background:var(--well); border-radius:var(--space-2); padding:var(--space-2);}
:root body [data-view=team] .seat-messages{gap:var(--space-2);}
:root body [data-view=team] .seat-message{background:var(--paper); border-radius:var(--space-2); font-size:10.125pt; line-height:15pt; padding:var(--space-3);}
:root body [data-view=team] .seat-message[data-own]{background:var(--wash);}
:root body [data-view=team] .seat-run{margin-bottom:var(--space-2); padding:var(--space-3);}
:root body [data-view=team] .seat-run-facts{gap:var(--space-3); margin-top:var(--space-2);}
:root body [data-view=team] [data-seat-run-steps]{margin-top:var(--space-3);}
:root body [data-view=team] .seat-run-step{border:0; box-shadow:inset .5px 0 var(--line); padding-bottom:var(--space-3);}
:root body [data-view=team] [data-seat-compose]{border:0; box-shadow:inset 0 .5px var(--line); gap:var(--space-2) var(--space-3); padding-top:var(--space-3);}
:root body [data-view=team] :is(th, td){border:0; padding:var(--space-2) var(--space-3);}
:root body [data-view=team] tbody tr:nth-child(even){background:var(--well);}
:root body [data-view=team] .launch-table tbody td:first-child{color:var(--team-faint); text-align:right; width:28px;}

/* Controls rise one shade or one shadow step, without movement or hue changes. */
:root body [data-view=team] :is(a, button, input, select, textarea, summary){font-weight:normal; transition:0.14s ease background-color;}
:root body [data-view=team] :is(button.quiet, .button.quiet){background:#0000; border:0; border-radius:6px; box-shadow:none; color:var(--team-body); font-size:10.125pt; gap:6px; line-height:15pt; min-height:28px; padding:var(--space-1) 10px;}
:root body [data-view=team] :is(button, .button):hover{transform:none;}
:root body [data-view=team] :is(button.quiet, .button.quiet):not(:disabled):not([aria-pressed=true]):not([aria-selected=true]):hover{background:rgb(0 0 0 / .03); box-shadow:none; color:var(--team-ink);}
:root body [data-view=team] :is(button.quiet, .button.quiet):active{box-shadow:none; transform:none;}
:root body [data-view=team] a{color:var(--team-body); text-decoration-color:var(--team-faint); transition:color 140ms ease;}
:root body [data-view=team] a:hover{color:var(--team-ink);}
:root body [data-view=team] :is(input:not([type=range]), textarea, select){background:var(--paper); border:0; border-radius:var(--space-2); box-shadow:var(--lift-1); color:var(--team-ink); font-size:10.125pt; line-height:15pt; min-height:var(--space-8); padding:6px var(--space-3); transition:0.14s ease box-shadow;}
:root body [data-view=team] :is(input:not([type=range]), textarea, select):is(:focus-visible, :hover){background:var(--paper); box-shadow:var(--lift-2); outline:none;}
:root body [data-view=team] :is(textarea, input)::placeholder{color:var(--team-secondary); opacity:1;}
:root body [data-view=team] :is(a, button, summary, [tabindex]):focus-visible{outline:solid 1.5px var(--team-body); outline-offset:2px;}
:root body [data-view=team] button:disabled{opacity:.4; transform:none;}
:root body [data-view=team] #team-seat-slot [data-seat-compose] button[type=submit]{background:rgb(0 0 0 / .88); border:0; border-radius:6px; box-shadow:none; color:white; font-size:10.125pt; font-weight:var(--weight-medium); line-height:15pt; min-height:28px; padding:var(--space-1) 10px;}
:root body [data-view=team] #team-seat-slot [data-seat-compose] button[type=submit]:hover:enabled{background:rgb(0 0 0 / .80);}
:root body [data-view=team] :is(.seat-focus-controls, .feed-filters){gap:2px;}
:root body [data-view=team] :is([data-select-seat], [data-seat-talk-filter], [data-canvas-item])[aria-pressed=true],
:root body [data-view=team] :is([data-select-seat], [data-seat-talk-filter], [data-canvas-item])[aria-pressed=true]:hover{background:var(--wash); box-shadow:none; color:var(--team-ink); font-weight:normal;}
:root body [data-view=team] .canvas-tablist{background:var(--wash); border-radius:10px; gap:2px; padding:var(--space-1);}
:root body [data-view=team] .canvas-tablist button{border-radius:7px; min-height:28px;}
:root body [data-view=team] .canvas-tablist [aria-selected=true],
:root body [data-view=team] .canvas-tablist [aria-selected=true]:hover{background:var(--paper); box-shadow:var(--lift-1); color:var(--team-ink);}
:root body [data-view=team] :is(.canvas-workarea, [data-canvas-rail], [data-canvas-panel], .canvas-tab-content, .replay-bar){background:var(--well);}
:root body [data-view=team] [data-canvas-stage]{background-color:var(--well); border-radius:var(--space-2); box-shadow:inset 0 0 0 .5px var(--line);}
:root body [data-view=team] [data-canvas-stage]:hover{box-shadow:inset 0 0 0 .5px var(--line-2);}
:root body [data-view=team] [data-canvas-panel]{box-shadow:inset 0 .5px var(--line);}
:root body [data-view=team] [data-canvas-item]{border-radius:var(--space-2); margin:0; min-height:40px;}
:root body [data-view=team] button[data-canvas-node]{background:var(--paper); border:0; border-radius:var(--space-2); box-shadow:var(--lift-1); transition:0.14s ease box-shadow;}
:root body [data-view=team] button[data-canvas-node]:hover{box-shadow:var(--lift-2);}
:root body [data-view=team] button[data-canvas-node][aria-pressed=true],
:root body [data-view=team] button[data-canvas-node][aria-pressed=true]:hover{background:linear-gradient(var(--wash), var(--wash)) var(--paper); box-shadow:var(--lift-1); outline:none;}
:root body [data-view=team] button[data-canvas-node][aria-pressed=true]:focus-visible{outline:solid 1.5px var(--team-body); outline-offset:2px;}
:root body [data-view=team] .canvas-tools{border-radius:var(--space-2); box-shadow:var(--lift-1); gap:2px;}
:root body [data-view=team] :is(.canvas-event, .canvas-file){border:0; min-height:40px;}

/* A state uses the same ink/wash pair in the tree, list, canvas and panel. */
:root body [data-view=team] :is(.badge, .pill){border:0; border-radius:var(--space-1); box-shadow:none; font-size:8.625pt; font-weight:var(--weight-medium); line-height:12pt; min-height:18px; padding:1px 6px;}
:root body [data-view=team] :is(.badge, .pill):not([data-state]),
:root body [data-view=team] :is(.badge, .pill)[data-state=waiting],
:root body [data-view=team] :is(.badge, .pill)[data-state=idle]{background:var(--wash); color:var(--team-body);}
:root body [data-view=team] :is(.badge, .pill)[data-state=running]{background:var(--run-wash); color:var(--run);}
:root body [data-view=team] :is(.badge, .pill):is([data-state=ok], [data-state=done], [data-state=SUCCEEDED]){background:var(--ok-wash); color:var(--ok);}
:root body [data-view=team] :is(.badge, .pill):is([data-state=attention], [data-state=JUDGING]){background:var(--attention-wash); color:var(--attention);}
:root body [data-view=team] :is(.badge, .pill):is([data-state=bad], [data-state=failed], [data-state=FAILED]){background:var(--bad-wash); color:var(--bad);}
:root body [data-view=team] :is(.seat-mark, .dot){border-radius:50%;}
:root body [data-view=team] kbd{border:0; border-radius:var(--space-1); box-shadow:inset 0 0 0 .5px var(--line-2); color:var(--team-faint); font-size:8.625pt;}

/* Existing empty/error content remains visible, in the same calm containers. */
:root body [data-view=team] .empty{background:var(--well); border:0; border-radius:var(--space-2); box-shadow:none; color:var(--team-body); gap:var(--space-2); min-height:112px; padding:var(--space-4);}
:root body [data-view=team] .empty .empty-art{background:var(--wash); border-radius:10px; height:42px; padding:var(--space-1); width:42px;}
:root body [data-view=team] .empty svg.empty-art{color:var(--team-faint); flex:0 0 42px;}
:root body [data-view=team] [data-canvas-list] > .empty{align-items:center; flex-direction:column; padding:var(--space-3); text-align:center;}
:root body [data-view=team] .empty strong{color:var(--team-ink); font-size:10.125pt; font-weight:var(--weight-medium); line-height:15pt;}
:root body [data-view=team] .empty p{color:var(--team-secondary); font-size:9pt; line-height:12pt; margin:0;}
:root body [data-view=team] [data-empty-inline]{background:var(--well); border-radius:6px; min-height:var(--space-8); padding:var(--space-2);}
:root body [data-view=team] :is(.form-error, [role=alert]){background:var(--bad-wash); border:0; border-radius:var(--space-2); color:var(--bad); font-size:9pt; line-height:15pt; padding:var(--space-2) var(--space-3);}
:root body [data-view=team] .skeleton{background:var(--paper); border-radius:var(--space-3); box-shadow:var(--lift-1); padding:var(--space-4);}
:root body [data-view=team] .skeleton span{background:var(--line); border-radius:6px; overflow:hidden; position:relative;}
:root body [data-view=team] .skeleton span::after{animation:look-team-loading 1.6s cubic-bezier(.22, 1, .36, 1) infinite; background:linear-gradient(90deg, #0000, rgb(255 255 255 / .6), #0000); content:""; inset:0; position:absolute;}
@keyframes look-team-loading{ 0%{transform:translateX(-100%);} 60%, 100%{transform:translateX(100%);} }
:root body [data-view=team] #team-stats:empty::before{background:linear-gradient(90deg, #0000 12px, var(--line) 12px 88px, #0000 88px) 0 20px / calc((100% + 12px) / 6) 8px, linear-gradient(90deg, #0000 12px, var(--line) 12px 44px, #0000 44px) 0 58px / calc((100% + 12px) / 6) 20px, linear-gradient(90deg, #0000 12px, var(--line) 12px 108px, #0000 108px) 0 100px / calc((100% + 12px) / 6) 8px, var(--well); background-repeat:repeat-x; border-radius:var(--space-3); content:""; grid-column:1 / -1; height:142px;}
:root body [data-view=team] #team-drawings:empty::before{background:linear-gradient(var(--line), var(--line)) 16px 16px / 30% 16px, linear-gradient(var(--line), var(--line)) 16px 48px / 50% 8px, linear-gradient(var(--well), var(--well)) center 96px / 200px 98px, linear-gradient(var(--well), var(--well)) 20% 214px / 200px 98px, linear-gradient(var(--well), var(--well)) 80% 214px / 200px 98px, var(--paper); background-repeat:no-repeat; border-radius:var(--space-3); box-shadow:var(--lift-1); content:""; display:block; height:520px; margin-bottom:var(--space-3);}
:root body:has([data-view=team]:not([hidden])) #notice{background:rgb(148 80 0 / .12); border:0; border-radius:var(--space-2); color:#945000; font-size:9pt; line-height:15pt; padding:var(--space-3) var(--space-4);}
:root body:has([data-view=team]:not([hidden])) #seat-drawer :is(h3, strong){color:var(--team-ink); font-weight:var(--weight-medium);}
:root body:has([data-view=team]:not([hidden])) #seat-drawer h3{font-size:12.75pt; line-height:18pt;}
:root body:has([data-view=team]:not([hidden])) #seat-drawer :is(.hint, time){color:var(--team-secondary); font-size:9pt; line-height:12pt;}
:root body:has([data-view=team]:not([hidden])) #seat-drawer .preview-head{background:var(--well); border:0; box-shadow:inset 0 -.5px var(--line); padding:var(--space-4);}
:root body:has([data-view=team]:not([hidden])) #seat-drawer-content{padding:var(--space-4);}
:root body:has([data-view=team]:not([hidden])) #seat-drawer button{background:var(--paper); border:0; border-radius:6px; box-shadow:var(--lift-1); color:var(--team-body); font-size:10.125pt; font-weight:normal; min-height:28px; padding:var(--space-1) 10px; transition:0.14s ease box-shadow;}
:root body:has([data-view=team]:not([hidden])) #seat-drawer button:hover:enabled{background:var(--paper); box-shadow:var(--lift-2); transform:none;}

/* Only one property moves; the page's existing preference hook also covers
   the optional modules without a separate media query or another listener. */
:root body [data-view=team] :is(.card, .seat, .handoff-card, .handoff-seat, .seat-launch){transition:0.14s ease box-shadow;}
:root body [data-view=team] :is(.seat, .handoff-card, .handoff-seat, .seat-launch):hover{transform:none;}
:root body [data-view=team] :is([data-enter=card], [data-enter=bar]){animation:look-team-enter 200ms ease both; transform:none;}
@keyframes look-team-enter{ 0%{opacity:0;} 100%{opacity:1;} }
:root body [data-view=team] :is(.dot, .status-mark)[data-working-dot],
:root body [data-view=team] .badge[data-working-dot]::before{animation:look-team-working 1.6s ease infinite;}
@keyframes look-team-working{ 50%{opacity:.55;} }
:root[data-motion=reduce] body [data-view=team] *,
:root[data-motion=reduce] body [data-view=team] *::before,
:root[data-motion=reduce] body [data-view=team] *::after{animation:none !important; transition:none !important;}
/* Canvas, timeline and side list on white: grey fills only for the stage itself; the selected row is a pale blue wash. */
:root body [data-view=team] :is(.canvas-workarea, .canvas-workarea > aside){background:var(--paper);}
:root body [data-view=team] .canvas-workarea > aside{box-shadow:inset -0.5px 0 0 rgb(0 0 0 / .08);}
:root body [data-view=team] [data-gantt-row]{background:var(--paper); box-shadow:inset 0 -0.5px 0 rgb(0 0 0 / .06);}
:root body [data-view=team] [data-gantt-row][data-selected]{background:rgb(0 112 214 / .06);}
:root body [data-view=team] .gantt-track{background:#0000;}
:root body [data-view=team] [data-replay-range]{accent-color:#0070d6;}
OC_EOF_99
