cat > 'web/quality.css' <<'OC_EOF_101'
:root {
  --q-digits: tabular-nums;
  --q-soft: .65rem;
  --q-paper: #fff;
  --q-ground: #f5f6f9;
  --q-ink: #19283c;
  --q-muted: #536579;
  --q-link: #145fa2;
  --q-line: #dce3eb;
  --q-frame: 1px solid var(--q-line);
  --q-radius: 1.15rem;
  --q-gap: clamp(.85rem, 2vw, 1.55rem);
  --q-pad: clamp(.9rem, 2.4vw, 2rem);
  --q-track: minmax(0, 1fr);
  --q-small: .8rem;
  --q-leading: 1.48;
  --q-mid: 580;
  --q-screen: min(86rem, 100%);
  --q-ok-fill: #cde9da;
  --q-mid-fill: #fff0cb;
  --q-ok-ink: #215a45;
  --q-low-fill: #f6d4c4;
  --q-low-ink: #75412d;
  --q-none-fill: #edf0f3;
  --q-none-ink: #55616e;
}
html { scroll-padding-block-start: 1rem; }
body {
  background-color: var(--q-ground);
  color: var(--q-ink);
  font-family: "Inter", "Helvetica Neue", Arial, sans-serif;
  line-height: var(--q-leading);
  margin: 0;
}
*, ::after, ::before { box-sizing: inherit; }
html { box-sizing: border-box; }
[hidden] { display: none !important; }
a { color: var(--q-link); }
h1, h2, h3, p, dl { margin: 0; }
h1, h2, h3 { line-height: 1.16; }
h1 { font-size: clamp(2.15rem, 5vw, 4rem); letter-spacing: -.045em; }
h2 { font-size: clamp(1.24rem, 2vw, 1.55rem); letter-spacing: -.025em; }
h3 { font-size: 1rem; }
:is(input, select, button) { font: inherit; }
button, summary { cursor: pointer; }
:focus-visible { outline: solid 3px var(--q-link); outline-offset: 2px; }
.report-width { inline-size: var(--q-screen); margin-inline: auto; padding-inline: var(--q-pad); }
.skip-read { position: fixed; inset-block-start: -8rem; padding: .6rem; background: var(--q-paper); z-index: 2; }
.skip-read:focus { inset-block-start: .3rem; }
.report-bar { background: var(--q-paper); border-block-end: var(--q-frame); }
.report-nav, .report-nav nav, .trace-list, .heat-key, .matrix-head, .measurement-head {
  align-items: center;
  display: flex;
}
.report-nav { gap: var(--q-gap); min-block-size: 3.6rem; place-content: normal space-between; }
.report-nav nav { gap: var(--q-gap); }
.report-nav a { color: var(--q-muted); font-size: .86rem; padding-block: .65rem; text-decoration-line: none; }
.report-nav a:hover { color: var(--q-link); text-decoration-line: underline; }
.report-nav b { color: var(--q-ink); font-size: 1rem; }
.report-intro { padding-block: clamp(1.8rem, 4vw, 3.5rem) clamp(1.25rem, 3vw, 2.2rem); }
#report-description { margin-block: .55rem; color: var(--q-muted); max-inline-size: 64ch; }
#report-time, .section-note, .figure-note, #visible-count { font-size: var(--q-small); color: var(--q-muted); }
#report-time { font-variant-numeric: var(--q-digits); }
#report-status { padding: var(--q-pad); border: var(--q-frame); border-radius: var(--q-radius); }
.overview-grid { gap: var(--q-gap); display: grid; }
.report-card { background: var(--q-paper); border-radius: var(--q-radius); padding: var(--q-pad); border: var(--q-frame); min-inline-size: 0; }
.report-gate {
  padding: .85rem var(--q-pad);
  margin-block-end: var(--q-gap);
  border-inline-start: solid .28rem var(--cell-ink);
  background: var(--q-paper);
  border-radius: .6rem;
}
.report-gate h2 { color: var(--cell-ink); font-size: 1.08rem; }
#gate-source { color: var(--q-muted); font-size: var(--q-small); }
#gate-source, #report-meta dd { overflow-wrap: anywhere }
.gate-changes { display: flex; gap: .25rem .8rem; flex-wrap: wrap; margin-block-start: .4rem; font-size: .87rem; }
.radar-panel {
  background: radial-gradient(ellipse at 10% 0%, #e7f0ff 0%, transparent 47%),
              radial-gradient(ellipse at 95% 30%, #eff3fb 0%, transparent 50%), var(--q-paper);
  column-gap: var(--q-gap);
  grid-template: "heading chart" auto "keys chart" auto "note chart" 1fr / minmax(13rem, .8fr) minmax(0, 1.2fr);
  display: grid;
}
.radar-panel h2 { grid-area: heading; align-self: end; }
.radar-panel .trace-list { grid-area: keys; flex-flow: column nowrap; align-items: start; }
.radar-panel .figure-note { grid-area: note; }
.trace-meta { font-size: var(--q-small); color: var(--q-muted); display: block; }
.trace-list { flex-wrap: wrap; gap: .45rem; margin-block: 1rem .35rem; }
.trace-list label {
  align-items: baseline;
  padding: .26rem .55rem;
  background: var(--q-paper);
  font-size: var(--q-small);
  display: inline-flex;
  border: var(--q-frame);
  border-radius: .5rem;
  gap: .35rem;
  cursor: pointer;
}
.trace-list input { margin: 0; accent-color: var(--series); }
#radar-plot { grid-area: chart; block-size: 24rem; inline-size: 100%; overflow: visible; }
#radar-plot .grid-ring { stroke: #c7d4e0; fill: none; }
#radar-plot .grid-spoke { stroke: #d9e3ec; }
#radar-plot .axis-label { font-size: 12px; fill: var(--q-ink); font-weight: var(--q-mid); }
#radar-plot .ring-label { font-size: 10px; fill: var(--q-muted); paint-order: stroke; stroke: var(--q-paper); stroke-width: 3px; }
.figure-note, .section-note { margin-block-start: .45rem; }
.report-method { margin-block: var(--q-gap); padding: .8rem var(--q-pad); border: var(--q-frame); border-radius: .65rem; background-color: var(--q-paper); }
.report-method summary { color: var(--q-link); font-weight: var(--q-mid); }
.report-method p { margin-block: .7rem; max-inline-size: 80ch; }
:is(#report-meta, #measurement-fields) { grid-template: auto / max-content var(--q-track); gap: .5rem 1rem; display: grid; }
dt { font-size: var(--q-small); color: var(--q-muted); }
dd { margin-inline: 0; overflow-wrap: anywhere }
#report-meta dd { font-size: var(--q-small); }
.report-method a { margin-block-start: .7rem; display: inline-block; }
.axis-table, .heat-table { table-layout: fixed; inline-size: 100%; font-size: .88rem; border-spacing: 0; }
table caption { position: absolute; clip-path: inset(100%); }
:is(.axis-table, .heat-table) th { text-align: start; }
:is(.axis-table, .heat-table) :is(td, th) { overflow-wrap: anywhere }
:is(.axis-table, .heat-table) thead th { color: var(--q-muted); font-size: var(--q-small); vertical-align: bottom; border-block-end: var(--q-frame); }
:is(.axis-table, .heat-table) tr > :not(:first-child) { text-align: center; }
.axis-table { margin-block-start: .9rem; }
.axis-table :is(th, td) { padding: .32rem .2rem; }
.axis-table th:first-child { inline-size: 37%; }
.axis-table tbody th, .heat-table tbody th { font-weight: var(--q-mid); }
.axis-table tr:not(:last-child) > :is(th, td) { border-block-end: solid 1px #edf1f5; }
.metric-score { font-weight: var(--q-mid); font-variant-numeric: var(--q-digits); }
.axis-numbers, .series-rev { display: block; color: var(--q-muted); font-size: .7rem; font-weight: 450; }
.axis-numbers { font-variant-numeric: var(--q-digits); }
.missing-text { color: var(--q-none-ink); font-size: var(--q-small); }
.series-mark { inline-size: .56rem; block-size: .56rem; border-radius: 1rem; background-color: var(--series); margin-inline-end: .3rem; display: inline-block; }
.matrix-head, .measurement-head { gap: var(--q-gap); place-content: normal space-between; }
.heat-panel { margin-block-end: 3rem; }
.report-filters { display: grid; gap: .8rem; grid-template: auto / minmax(9rem, 1.4fr) var(--q-track) var(--q-track); margin-block: 1.15rem .85rem; }
.report-filters label { display: grid; gap: .32rem; font-size: var(--q-small); color: var(--q-muted); }
.report-filters :is(input, select), #close-measure {
  border: var(--q-frame);
  color: var(--q-ink);
  border-radius: .5rem;
  padding: .45rem .55rem;
  background: var(--q-paper);
  min-inline-size: 0;
  min-block-size: 2.4rem;
}
.heat-key { flex-wrap: wrap; gap: .65rem; margin-block: .65rem; color: var(--q-muted); font-size: var(--q-small); }
.heat-key span::before { inline-size: .65rem; block-size: .65rem; margin-inline-end: .25rem; display: inline-block; content: ""; background: var(--cell-fill); border: solid 1px #0002; }
.heat-table tr > :first-child { inline-size: 46%; }
.heat-table thead th { padding: .5rem .2rem; }
.heat-table tbody :is(th, td) { padding: .19rem .2rem; }
.heat-table .group-heading { color: var(--q-ink); padding: .85rem .2rem .35rem; border-block-start: var(--q-frame); font-size: 1rem; }
[data-tone=pass] { --cell-fill: var(--q-ok-fill); --cell-ink: var(--q-ok-ink); }
[data-tone=miss] { --cell-fill: var(--q-low-fill); --cell-ink: var(--q-low-ink); }
[data-tone=unknown] { --cell-fill: var(--q-none-fill); --cell-ink: var(--q-none-ink); }
.heat-value {
  display: block;
  inline-size: 100%;
  border-radius: .4rem;
  padding: .36rem .08rem;
  font-weight: var(--q-mid);
  font-size: var(--q-small);
  color: var(--cell-ink);
  background: var(--reading-fill, var(--cell-fill));
  border: solid transparent 1px;
  font-variant-numeric: var(--q-digits);
  min-block-size: 2.05rem;
}
.heat-value:hover { border-color: currentColor; }
#empty-results { padding-block: var(--q-gap); color: var(--q-muted); }
#measurement {
  inline-size: min(33rem, calc(100% - 2rem));
  border: var(--q-frame);
  border-radius: var(--q-radius);
  padding: var(--q-pad);
  max-block-size: calc(100dvh - 2rem);
  color: var(--q-ink);
  box-shadow: 0 1.5rem 4rem #203a5e35;
}
#measurement::backdrop { background: #19283c70; }
.measurement-head { align-items: start; }
#measurement-version { color: var(--q-muted); font-size: var(--q-small); margin-block-end: .3rem; }
#measurement-verdict { display: inline-block; background: var(--cell-fill); color: var(--cell-ink); padding: .22rem .6rem; border-radius: .4rem; margin-block: 1rem; }
#measurement-fields { margin-block-end: 1.2rem; }
#measurement-raw { background: var(--q-ground); padding: .75rem; border-radius: .45rem; white-space: pre-wrap; font-size: .78rem; overflow-wrap: anywhere }
@media (max-width: 58rem) {
  .radar-panel { display: block; }
  .trace-meta { display: none; }
  .radar-panel .trace-list { flex-flow: row wrap; }
  #radar-plot { display: block; max-block-size: 27rem; block-size: auto; }
}
@media (max-width: 35rem) {
  .report-filters { grid-template: auto / repeat(2, var(--q-track)); }
  .report-filters :first-child:is(label) { grid-column: 1 / -1 }
  .axis-table { font-size: .76rem; }
  .axis-table th:first-child { inline-size: 34%; }
  .axis-table :is(th, td) { padding-inline: .08rem; }
  .heat-table tr > :first-child { inline-size: 34%; }
  .matrix-head { gap: .25rem; flex-flow: column nowrap; align-items: start; }
  .heat-table { font-size: .8rem; }
  #radar-plot .axis-label { font-size: 15px; }
  #report-meta { grid-template: auto / var(--q-track); }
  #measurement-fields { gap: .45rem; }
}
OC_EOF_101
cat > 'web/quality.html' <<'OC_EOF_102'
<!doctype html>
<html lang="en">
<head>
  <meta charset=utf-8>
  <meta content="width=device-width,initial-scale=1" name="viewport">
  <meta content="light" name="color-scheme">
  <title>Release quality | OpenCode Cockpit</title>
  <link href="./quality.css" rel="stylesheet">
  <script defer src="./quality.js"></script>
</head>
<body>
  <a class="skip-read" href="#quality-main" data-words="skip">Skip to report</a>
  <header class="report-bar">
    <div class="report-width report-nav">
      <a id="return-home" href="./"><b>OpenCode Cockpit</b></a>
      <nav aria-label="Report sections">
        <a href="#radar" data-words="overview">Overview</a>
        <a href="#matrix" data-words="indicators">Indicators</a>
      </nav>
    </div>
  </header>
  <main class="report-width" id="quality-main">
    <header class="report-intro">
      <h1 data-words="title">Release quality</h1>
      <p id="report-description" data-words="description">Compare releases across twelve axes, then inspect the measurement behind each indicator.</p>
      <p id="report-time"></p>
    </header>
    <p id="report-status" role="status" data-words="loading">Loading measurements…</p>
    <div id="report-body" hidden>
      <section id="gate-panel" class="report-gate" aria-labelledby="gate-status" hidden>
        <h2 id="gate-status"></h2>
        <p id="gate-source"></p>
        <div id="gate-list"></div>
      </section>
      <div class="overview-grid" id="radar">
        <section class="report-card radar-panel" aria-labelledby="radar-heading">
