'use strict';

const labels = {
  skip: 'Skip to report', title: 'Release quality', overview: 'Overview', indicators: 'Indicators',
  description: 'Compare releases across twelve axes, then inspect the measurement behind each indicator.',
  radar: 'Quality radar', scores: 'Axis scores', heat: 'Indicator heatmap', method: 'How scores are calculated',
  coverage: 'Mean score and passed / measured. Coverage is shown for incomplete axes.',
  formula: 'Each reading is scaled from 0 to 1 using its frozen target, direction and lower scoring limit. An axis is the unweighted mean of its measured indicators. Missing readings are excluded.',
  inspect: 'Select a cell to see its reading, threshold and measurement output.',
  axis: 'Axis', allAxes: 'All axes', allStates: 'All outcomes', gaps: 'Missing readings', misses: 'Missed targets', show: 'Show rows with',
  search: 'Find an indicator', loading: 'Loading measurements…', noResults: 'No indicators match these filters.',
  unavailable: 'The report could not be opened.', retry: 'Try again', now: 'Measured', spec: 'Frozen criteria (SHA-256)',
  indicator: 'Indicator', missing: 'Not measured', pass: 'Passed', miss: 'Below target', close: 'Close',
  gateOk: 'Release gate passed', gateFail: 'Release gate not passed', better: 'Improved', fell: 'Regressions', previous: 'Compared with {revision}', gateInfo: 'Release gate', reportFile: 'Download measurement data', metricCount: '{shown} of {total} indicators', coverageShort: '{measured}/{total} measured',
  plotDetail: 'Each spoke is one axis, with 0 at the centre and 1 at the outer ring. Read the exact scores in the next table.',
  traceNote: 'Gaps indicate axes without measurements. Each ring spans 0.25.',
  emptyPlot: 'Select a version above to display its measurements.',
  priorReading: 'Previous reading', value: 'Raw reading', score: 'Score', target: 'Passing target', worst: 'Zero-score limit', higher: 'Higher is better',
  lower: 'Lower is better', rule: 'Measurement method', raw: 'Measurement output', reason: 'Reason', noRaw: 'No output was supplied.',
  revision: 'Revision', observed: 'Measured indicators', scope: 'Axis', totalCoverage: '{passed} passed out of {measured} measured, {total} indicators in total',
  graphKey: 'Version visibility', shape: 'Radar for {version}', zeroCoverage: 'No axes measured for {version}.',
  progress: 'Release comparison', where: 'Report sections'
};
const versionsOrder = ['paid', 'gpt', 'mine'];
const traceStyles = {
  paid: {color: '#813f83', dashes: '7 3', shape: 'square'},
  gpt: {color: '#005ea8', dashes: '2 2', shape: 'diamond'},
  mine: {color: '#28704f', dashes: '', shape: 'circle'}
