const compactAxis = ['Correctness', 'Consistency', 'Public release', 'Design fit', 'Visual quality', 'Features', 'Interaction', 'Mobile', 'Performance', 'Resilience', 'Records', 'Evidence'];
const element = document.getElementById.bind(document);
const el = (tag, words) => {
  const node = document.createElement(tag);
  if (words != null) node.textContent = words;
  return node;
};
const ns = 'http://www.w3.org/2000/svg';
function svgNode(tag, attrs, words) {
  const node = document.createElementNS(ns, tag);
