  if (words != null) node.textContent = words;
  return node;
}
let report, builds, locale = {}, opener;
const shown = new Set();
const t = (key, vars = {}) => (locale.words?.[key] || labels[key] || key)
  .replace(/\{(\w+)\}/g, (whole, slot) => String(vars[slot] ?? whole));
const buildName = version => locale.versions?.[version.id] || version.name;
const axisName = axis => locale.axes?.[axis.id] || axis.name;
const metricName = metric => locale.metrics?.[metric.id] || metric.name;
const readable = text => typeof text === 'string' ? text : JSON.stringify(text, null, 2);
const decimal = number => Number.isFinite(number) ? number.toFixed(3) : t('missing');
const actual = cell => cell != null && Number.isFinite(cell.score);
const mood = cell => !actual(cell) ? 'unknown' : cell.passed ? 'pass' : 'miss';
function options(select, rows) {
  select.replaceChildren(...rows.map(([value, name]) => new Option(name, value)));
}
function pair(parent, key, message) {
  parent.append(el('dt', key), el('dd', message));
}
function columnHeading(version, withRevision) {
  const head = el('th');
  head.scope = 'col';
  head.style.setProperty('--series', traceStyles[version.id].color);
  const dot = el('span');
  dot.className = 'series-mark';
  head.append(dot, buildName(version));
  if (withRevision && version.revision) {
