  row.append(head, ...builds.map(version => columnHeading(version, withRevision)));
}
function accessibleReport(doc) {
  if (doc.schema !== 1 || !Array.isArray(doc.metrics) || !Array.isArray(doc.versions)
      || doc.axes?.length !== 12 || !doc.axes.every((axis, index) => axis.id === index + 1)) {
    throw new Error('Unexpected quality report format.');
  }
  const ids = doc.versions.map(version => version.id);
