}
function keyForBuilds() {
  const list = element('traces');
  list.setAttribute('aria-label', t('graphKey'));
  for (const version of builds) {
    shown.add(version.id);
    const label = el('label');
    label.style.setProperty('--series', traceStyles[version.id].color);
    const input = el('input');
    input.type = 'checkbox';
    input.checked = true;
    input.dataset.version = version.id;
    input.addEventListener('change', () => {
      if (input.checked) shown.add(version.id);
      else shown.delete(version.id);
      plot();
    });
    const title = el('span', buildName(version));
    const measured = report.metrics.filter(metric => actual(metric.results[version.id])).length;
    const progress = el('small', t('coverageShort', {measured, total: report.metrics.length}));
    progress.className = 'trace-meta';
    title.append(progress);
    label.append(input, title);
    list.append(label);
  }
}
function coordinate(index, score) {
  const angle = index * Math.PI / 6 - Math.PI / 2;
  return [280 + Math.cos(angle) * 155 * score, 213 + Math.sin(angle) * 155 * score];
}
function marker(style, x, y) {
  if (style.shape === 'circle') return svgNode('circle', {cx: x, cy: y, r: 3.1});
  if (style.shape === 'square') return svgNode('rect', {x: x - 4.6, y: y - 4.6, width: 9.2, height: 9.2});
