function plot() {
  const svg = element('radar-plot');
  svg.replaceChildren(svgNode('title', {id: 'plot-label'}, t('radar')), svgNode('desc', {id: 'plot-detail'}, t('plotDetail')));
  for (const level of [.25, .5, .75, 1]) {
    const ring = report.axes.map((_, i) => coordinate(i, level).join(',')).join(' ');
    svg.append(svgNode('polygon', {class: 'grid-ring', points: ring}));
  }
  for (const [i, axis] of report.axes.entries()) {
    const [x, y] = coordinate(i, 1);
    const [lx, ly] = coordinate(i, 1.10);
    svg.append(svgNode('line', {class: 'grid-spoke', x1: 280, y1: 213, x2: x, y2: y}));
    const anchor = i === 0 || i === 6 ? 'middle' : i < 6 ? 'start' : 'end';
    svg.append(svgNode('text', {class: 'axis-label', x: lx, y: ly + 4, 'text-anchor': anchor}, locale.shortAxes?.[axis.id] || compactAxis[i]));
  }
  for (const tick of [.25, .5, .75, 1]) {
    const [x, y] = coordinate(0, tick);
    svg.append(svgNode('text', {class: 'ring-label', x: x + 5, y: y - 3}, String(tick)));
  }
  const empty = [];
  for (const version of builds.filter(build => shown.has(build.id))) {
    const style = traceStyles[version.id];
    const group = svgNode('g', {'data-trace': version.id, stroke: style.color, fill: 'none'});
    group.append(svgNode('title', {}, t('shape', {version: buildName(version)})));
    const points = report.axes.map((axis, i) => {
      const reading = axis.results?.[version.id];
      return actual(reading) ? coordinate(i, reading.score) : null;
    });
    if (!points.some(Boolean)) empty.push(t('zeroCoverage', {version: buildName(version)}));
    const segments = [];
    for (let i = 0; i < points.length; i++) {
      const here = points[i], next = points[(i + 1) % points.length];
      if (here && next) segments.push('M ' + here.join(' ') + ' L ' + next.join(' '));
    }
    group.append(svgNode('path', {d: segments.join(' '), 'stroke-width': 2.1, 'stroke-dasharray': style.dashes}));
    points.forEach((point, i) => {
      if (!point) return;
      const dot = marker(style, ...point);
      dot.setAttribute('stroke-width', '1.8');
      dot.append(svgNode('title', {}, axisName(report.axes[i]) + ' · ' + decimal(report.axes[i].results[version.id].score)));
      group.append(dot);
