  element('trace-note').textContent = shown.size ? [t('traceNote'), ...empty].join(' ') : t('emptyPlot');
}
function axisTable() {
  const table = element('axis-table');
  headings(table, t('axis'), false);
  for (const axis of report.axes) {
    const row = table.tBodies[0].insertRow();
    const header = el('th', axisName(axis));
    header.scope = 'row';
    row.append(header);
    for (const build of builds) {
      const data = axis.results[build.id];
      const td = row.insertCell();
      const score = el('span', decimal(data.score));
      score.className = actual(data) ? 'metric-score' : 'missing-text';
      td.append(score);
      const counts = el('span', data.passed + '/' + data.measured);
      counts.className = 'axis-numbers';
      td.append(counts);
      if (data.measured < data.total) {
        const coverage = el('span', t('coverageShort', data));
        coverage.className = 'axis-numbers';
        td.append(coverage);
