}
function evolution() {
  const change = report.evolution;
  if (typeof change?.passed !== 'boolean') return;
  const build = builds.find(version => version.id === change.slot);
  if (!build) return;
  const panel = element('gate-panel');
  element('gate-status').textContent = t(change.passed ? 'gateOk' : 'gateFail');
  panel.dataset.tone = change.passed ? 'pass' : 'miss';
  const previous = String(change.previous_revision || '');
  const brief = /^[0-9a-f]{40}$/i.test(previous) ? previous.slice(0, 10) : previous;
  const source = element('gate-source');
  source.textContent = buildName(build) + (brief ? ' · ' + t('previous', {revision: brief}) : '');
  source.title = previous;
  for (const [key, ids] of [['better', change.improved], ['fell', change.regressed]]) {
    if (!Array.isArray(ids) || !ids.length) continue;
    const group = el('div');
    group.className = 'gate-changes';
    group.append(el('strong', t(key)));
    for (const item of ids) {
      const metric = report.metrics.find(check => check.id === item);
      if (!metric) {
        group.append(el('span', readable(item)));
        continue;
      }
      const link = el('a', metricName(metric));
      link.href = '#matrix';
      link.addEventListener('click', event => {
        event.preventDefault();
        element('axis-filter').value = '';
        element('status-filter').value = '';
        element('metric-query').value = metric.id;
        heat();
        element('matrix').scrollIntoView();
