cat > 'web/status.js' <<'OC_EOF_104'
/* Where every order of the live run stands, worked out from one /state answer, the ledger rows and the records the
   backend keeps of the envelopes it sent. Nothing here reads the page, the network or a clock: the dispatcher's time
   comes in as nowS. The page loads this file with a script tag before app.js; node loads it with require(). */
(function () {
  'use strict';
  var LIVE_STATES = ['JUDGING', 'LEASED', 'PENDING'];
  var ENDED = /^(SUCCEEDED|FAILED|DEAD|CANCELLED)$/;
  // Until the backend sends rules of its own: a first row within 120 s of a grant, then a row at least every 480 s.
  var RULES = {'default': {first: 120, silence: 480}};
  var POLL_S = 5;

  function kindOf(v) { return v === null ? 'null' : Array.isArray(v) ? 'list' : typeof v; }
  function isText(v) { return kindOf(v) === 'string'; }
  function isNum(v) { return kindOf(v) === 'number' && isFinite(v); }
  function isMap(v) { return kindOf(v) === 'object'; }
  function textOrder(a, b) { if (a === b) { return 0; } return a < b ? -1 : 1; }
  function whole(n) { return Math.floor(n); }
  // Keyed by order id with no prototype behind them: ids such as constructor or __proto__ are plain keys.
  function bare() { return Object.create(null); }
  var hasOwn = {}.hasOwnProperty;
  function owns(map, key) { return hasOwn.call(map, key); }
  function add(map, key, value) { if (!map[key]) { map[key] = []; } map[key].push(value); }
  // The newest entry of a list (rows come oldest first) that passes `test`, or null.
  function newest(list, test) {
    for (var at = (list || []).length - 1; at >= 0; at--) { if (!test || test(list[at])) { return list[at]; } }
    return null;
  }
  function ofKind() { var kinds = Array.prototype.slice.call(arguments); return function (r) { return kinds.indexOf(r.kind) >= 0; }; }

  /* The order one ledger row is about: its `order`, the id it issues, what an ask is about, or (for an answer) what
     the answered ask was about. null when it is about no order. */
  function subject(row, log) {
    if (!isMap(row)) { return null; }
    if (isText(row.order)) { return row.order; }
    switch (row.kind) {
      case 'order.issued': var body = row.body; return isMap(body) && isText(body.id) ? body.id : null;
      case 'ask.raised': var on = row.about; return isText(on) ? on : null;
      case 'ask.answered':
        for (var k = 0; k < (log || []).length; k++) {
          var x = log[k];
