      default: return null;
    }
  }

  // Of two sender records, is `b` the one sent last? Later `at` wins; on equal `at` the higher line number (a record
  // without a line number has the lowest).
  function sentLater(a, b) {
    if (a.at !== b.at) { return b.at > a.at; }
    var na = isNum(a.n) ? a.n : -1, nb = isNum(b.n) ? b.n : -1;
    return nb >= na;
  }
  function stepLabel(note) {
    var found = isText(note) && note.charAt(0) === '[' ? note.slice(1, note.indexOf(']')) : '';
    return isText(note) && note.indexOf(']') > 1 ? found : null;
  }
  function rowWords(row) {
    if (isText(row.note) && row.note) { return row.note; }
    if (isText(row.evidence) && row.evidence) { return row.evidence; }
    return isText(row.reason) && row.reason ? row.reason : null;
  }

  /* Cards: one per order in the snapshot, and one "ghost" per id the backend tried to issue that the dispatcher does
     not hold. input = {snap, log, sent, rules, nowS, live, lastOkS, pollS}. They come out ghosts first (the newest
     first), then each top order (newest issue row first) followed by everything under it, children by id. */
  function classify(input) {
    var arg = isMap(input) ? input : {}, clock = Number(arg.nowS) || 0, now = whole(clock), period = isNum(arg.pollS) ? arg.pollS : POLL_S;
    var held = arg.snap && isMap(arg.snap.state) ? arg.snap.state : {}, rules = isMap(arg.rules) ? arg.rules : RULES;
    var all = isMap(held.orders) ? held.orders : {}, leaseMap = isMap(held.leases) ? held.leases : {};
    var questions = [];
    if (isMap(held.asks)) {
      Object.keys(held.asks).forEach(function (key) { var q = held.asks[key]; if (isMap(q) && q.state !== 'ANSWERED') { questions.push(q); } });
    }
    questions.sort(function (p, q) {
      var tp = isNum(p.touched) ? p.touched : 0, tq = isNum(q.touched) ? q.touched : 0;
      return tp !== tq ? tp - tq : textOrder(String(p.id), String(q.id));
    });
    function known(id) { return isText(id) && owns(all, id) && isMap(all[id]); }
    var ids = Object.keys(all).filter(known).sort(textOrder);
    var rows = (Array.isArray(arg.log) ? arg.log : []).filter(function (r) { return isMap(r) && isNum(r.seq); });
    rows.sort(function (p, q) { return p.seq - q.seq; });

    // One pass over the ledger: per order, its rows (`about`), those plus the sub-orders its holder issued (`busy`),
    // and its issue row.
