    });

    // The tree of orders.
    var children = bare();
    function up(id) { var p = all[id].parent; return known(p) && p !== id ? p : ''; }
    ids.forEach(function (id) { if (up(id)) { add(children, up(id), id); } });
    function lineage(id) {
