      if (!arg.live) { list.push('7c'); }
      if (isNum(arg.lastOkS) && Number(arg.nowS) - arg.lastOkS > 2 * period) { list.push('7d'); }
      var person = null;
      questions.some(function (q) { if (q.about === id && isText(q.to) && /^human:/.test(q.to)) { person = q; } return person !== null; });
      if (person) {
        list.push('7e');
