    // How long the order's family has been quiet since its newest grant, and the rule that says how long is too long.
    function quietness(id, o, f, list) {
      var grant = newest(about[id], ofKind('lease.granted'));
      var listed = o.skills, named = (Array.isArray(listed) ? listed : []).filter(function (s) { return isText(s) && owns(rules, s); })[0];
      var ruleName = named || 'default', rule = rules[ruleName];
      if (!grant || !isMap(rule)) { return; }
      var lastAt = null;
      subtree(id).forEach(function (member) {
        (about[member] || []).forEach(function (r) { if (r.seq > grant.seq && (lastAt === null || r.t > lastAt)) { lastAt = r.t; } });
