      if (isNum(o.attempt)) { f.attempt = o.attempt; }
      if (open.length) { f.kids_open = open.length; }
      var hold = questions.filter(function (q) { return q.about === id && q.blocking === true; })[0];
      var after = o.after, before = Array.isArray(after) ? after : [];
      if (hold) {
        f.blocked = 'ask';
