      if (isText(o.state) && ENDED.test(o.state)) { f.end = o.state.toLowerCase(); }
      var last = newest(about[id], function (r) {
        if (r.kind === 'order.failed') { return !r.retry; }
        return ofKind('order.succeeded', 'order.dead', 'order.cancelled')(r);
      });
      if (last) {
        f.end_seq = last.seq;
        if (isText(last.by)) { f.by = last.by; }
        if (isText(last.reason) && last.reason.length) { f.reason = last.reason; }
        if (last.cascade === true && last.kind === 'order.cancelled') { f.cascade = true; }
        if (issueRow[id]) { f.took = whole(last.t - issueRow[id].t); }
