        if (isMap(o.accept) && isText(o.accept.judge)) { f.judge = o.accept.judge; }
        var handed = newest(about[id], ofKind('report.submitted'));
        if (handed) { f.wait = whole(now - handed.t); }
      } else { ended(id, f); }
      var chain = lineage(id), card = {id: id, 'case': which, title: isText(o.title) ? o.title : ''};
      card.flags = addFlags(id, f);
