/* Shared by the cockpit and its replay page. The dispatcher owns task state. */
(function () {
  'use strict';

  function element(tag, cls, ...children) {
    const node = document.createElement(tag);
    if (cls) node.className = cls;
    node.append(...children.filter(child => child != null));
    return node;
  }
  function button(label, action, cls = 'sw-button') {
    const node = element('button', cls, label);
    node.type = 'button';
    node.addEventListener('click', action);
    return node;
  }
  function link(label, href) {
    const node = element('a', '', label);
    node.href = href;
    return node;
  }
  const hint = text => element('p', 'sw-hint', text);
  const heading = (title, action) => element('div', 'sw-heading', element('h3', '', title), action);
  const label = (title, control) => element('label', 'sw-field', element('span', '', title), control);
  const meta = (...parts) => parts.filter(Boolean).join(' · ');
  function requestId() {
    const random = window.crypto;
    if (random.randomUUID) return random.randomUUID();
    const words = new Uint32Array(4);
    random.getRandomValues(words);
    return Array.from(words, word => word.toString(16).padStart(8, '0')).join('');
  }
  async function json(path, body, signal) {
    const init = {signal, cache: 'no-store'};
    if (body) {
      init.method = 'POST';
      init.body = JSON.stringify(body);
      init.headers = [['Content-Type', 'application/json']];
    }
    const response = await fetch(path, init);
    const payload = await response.json();
    if (response.ok) return payload;
    throw new Error(payload?.detail || `Request failed (${response.status})`);
  }
  function textField(name, value, max, multiline, required) {
    const node = element(multiline ? 'textarea' : 'input');
    node.name = name;
    node.value = value || '';
    node.maxLength = max;
    node.required = required;
    if (multiline) node.rows = 3;
    return node;
  }
  function formActions(submitText, other) {
    const save = element('button', 'sw-button sw-primary', submitText);
    save.type = 'submit';
    return element('div', 'sw-actions', save, other);
  }
  function choices(title, name, options, chosen, empty) {
    const box = element('fieldset', 'sw-choices', element('legend', '', title));
    const list = element('div', 'sw-check-list');
    if (!options.length) list.append(hint(empty));
    options.forEach(([value, display, info]) => {
      const input = element('input');
      input.type = 'checkbox';
      input.name = name;
      input.value = value;
      input.checked = chosen.includes(value);
      const desc = element('span', 'sw-choice-caption', display, info ? element('small', '', info) : null);
      list.append(element('label', 'sw-check', input, desc));
    });
    box.append(list);
    return box;
  }
  const selectContents = new WeakMap();
  function updateSelect(select, options, none) {
    const key = JSON.stringify([none, options]);
    if (selectContents.get(select) === key) return;
    const value = select.value;
    select.replaceChildren(new Option(none, ''), ...options.map(([v, title]) => new Option(title, v)));
    if (options.some(([v]) => v === value)) select.value = value;
    selectContents.set(select, key);
  }

  function mount(root, options = {}) {
    const t = options.t || ((key, params = {}) => key.replace(/\{(\w+)\}/g, (token, name) => params[name] ?? token));
    function counted(n, singular, plural) { return t(n === 1 ? singular : plural, {count: n}); }
    const skillOrigin = skill => skill.source === 'registry' ? t('Shared registry') : t('Cockpit Library');
    const versionLabel = version => version == null || version === '' ? t('Version unrecorded') : t('Version {version}', {version});
    const requests = new AbortController();
    let doc = null, selected = '', busy = false, reading = null;
    let editor = null, noteForm = null, catalogLimit = 12;
    const drafts = new Map();
    const signatures = new Map();
    const pick = id => doc.swarms.find(g => g.id === id);
    const taskHref = id => '/#/order/' + encodeURIComponent(doc.run) + '/' + encodeURIComponent(id);
    const translateState = state => state ? t(state) : t('Unavailable');
    const byActor = id => doc.members.find(x => x.actor === id);
    const byTask = id => doc.tasks.find(x => x.id === id);
    function bySkill(id) {
      const exact = doc.skills.find(skill => skill.id === id);
      if (exact) return exact;
      const matches = doc.skills.filter(skill => skill.source_id === id);
      return matches.length === 1 ? matches[0] : null;
    }
    const skillHref = id => '/#/library/' + encodeURIComponent(id);
    const who = id => byActor(id)?.name || doc.members.find(member => member.team === id)?.name || id;

    root.classList.add('sw-workspace');
    const runLine = element('p', 'sw-run', t('Loading swarm records…'));
    const message = element('div', 'sw-message');
    message.role = 'status';
    const retry = button(t('Retry'), () => refresh());
    const readError = element('div', 'sw-error');
    readError.role = 'alert';
    readError.hidden = true;
    const add = button(t('New swarm'), () => openEditor(null), 'sw-button sw-primary');
    add.disabled = true;
    const groupList = element('div', 'sw-groups');
    const side = element('section', 'sw-card sw-sidebar', heading(t('Swarms'), add), groupList);
    const summary = element('section', 'sw-card');
    const editorSlot = element('div');
    const records = element('section', 'sw-card');
    const noteSlot = element('div');
    const detail = element('div', 'sw-stack', editorSlot, summary, records, noteSlot);
    const grid = element('div', 'sw-layout', side, detail);
    const search = element('input');
    search.type = 'search'; search.placeholder = t('Search by name, category or source');
    search.setAttribute('aria-label', t('Search skills'));
    const filter = element('select');
    filter.setAttribute('aria-label', t('Filter skill source'));
    filter.append(new Option(t('All sources'), ''), new Option(t('Cockpit Library'), 'library'), new Option(t('Shared registry'), 'registry'));
    const skillList = element('div', 'sw-skills');
    const skillInfo = element('p', 'sw-hint');
    const catalog = element('section', 'sw-card sw-catalog', heading(t('Skill directory'), link(t('Open Library'), '/#/library')),
      element('div', 'sw-search', search, filter), skillInfo, skillList);
    const newSearch = () => { catalogLimit = 12; renderSkills(); };
    search.addEventListener('input', newSearch);
    filter.addEventListener('change', newSearch);
    const board = element('details', 'sw-card sw-board');
    const boardContent = element('div', 'sw-board-content');
    board.append(element('summary', '', t('Shared board · main channel')), boardContent);
    board.hidden = true;
    root.replaceChildren(runLine, message, readError, grid, board, catalog);
    grid.hidden = catalog.hidden = true;

    function changed(key, value) {
      const str = JSON.stringify(value);
      if (signatures.get(key) === str) return false;
      signatures.set(key, str);
      return true;
    }
    function switchTo(id) {
      if (busy) return;
      selected = id;
      closeEditor();
      message.textContent = '';
      render();
    }
    function renderGroups() {
      if (!changed('groups', [doc.writable, selected, doc.swarms.map(g => [g.id, g.name, g.members, g.tasks])])) return;
      groupList.replaceChildren();
      for (const g of doc.swarms) {
        const choice = button(g.name, () => switchTo(g.id), 'sw-group');
        choice.dataset.swarmId = g.id;
        choice.setAttribute('aria-pressed', String(g.id === selected));
        choice.append(element('small', '', meta(counted(g.members.length, '{count} member', '{count} members'), counted(g.tasks.length, '{count} task', '{count} tasks'))));
        groupList.append(choice);
      }
      if (!doc.swarms.length) groupList.append(hint(t('No swarms in this run.')));
    }
    function renderSummary(group) {
      if (!changed('summary', [doc.run, doc.writable, group?.id, group?.name, group?.goal, group?.members.map(byActor), group?.tasks.map(byTask), doc.skills])) return;
      if (!group) {
        summary.replaceChildren(heading(t('Swarm overview')), hint(doc.writable ? t('Create a swarm to bring members, tasks and their work notes together.') : t('This run has no recorded swarms.')));
        return;
      }
      const edit = doc.writable ? button(t('Edit swarm'), () => openEditor(pick(group.id))) : null;
      summary.replaceChildren(heading(group.name, edit));
      if (group.goal) summary.append(element('p', 'sw-goal', group.goal));
      const roster = element('div', 'sw-roster');
      group.members.forEach(id => {
        const seat = byActor(id);
        const chip = element('span', 'sw-seat', element('strong', '', who(id)), element('small', '', meta(seat?.role && t(seat.role), seat?.model)));
        chip.title = id;
        roster.append(chip);
      });
      if (!roster.children.length) roster.append(hint(t('No members assigned.')));
      const tasks = element('ul', 'sw-task-list');
      group.tasks.forEach(id => {
        const task = byTask(id);
        const row = element('li', '', element('div', 'sw-task-caption', link(task?.title || id, taskHref(id)), element('small', '', meta(id, task?.to ? who(task.to) : ''))));
        const state = element('span', 'sw-state', translateState(task?.state));
        state.dataset.state = task?.state || 'unknown';
        row.append(state, link(t('Files'), taskHref(id) + '/files'));
        const usage = element('div', 'sw-task-skills');
        if (task?.skills?.length) {
          const assigned = element('div', '', t('Assigned skills'), ' · ');
          task.skills.forEach((value, i) => {
            const skill = bySkill(value);
            if (i) assigned.append(', ');
            assigned.append(skill?.source === 'library' ? link(skill.title, skillHref(skill.source_id)) : skill?.title || value);
          });
          usage.append(assigned);
        }
        if (task?.skill_receipts?.length) {
          const reported = element('div', '', t('Agent-reported use'), ' · ');
          task.skill_receipts.forEach((receipt, i) => {
            if (i) reported.append(', ');
            const id = receipt.id.replace(/^library:/, '');
            reported.append(link(meta(receipt.title, versionLabel(receipt.version)), skillHref(id)));
          });
          usage.append(reported);
        }
        if (usage.children.length) row.append(usage);
        tasks.append(row);
      });
      summary.append(element('h4', '', t('Members')), roster, element('h4', '', t('Linked tasks')), tasks.children.length ? tasks : hint(t('No tasks linked.')));
    }
    function renderNotes(group) {
      records.hidden = !group;
      if (!group || !changed('records', [group.id, group.notes, doc.members, group.tasks.map(byTask)])) return;
      const list = element('ol', 'sw-notes');
      for (const note of group.notes.slice().reverse()) {
        const date = new Date(note.at);
        const time = element('time', '', Number.isFinite(date.getTime()) ? date.toLocaleString() : note.at);
        time.dateTime = note.at;
        const attrs = element('div', 'sw-tags');
        if (note.member) attrs.append(element('span', '', who(note.member)));
        if (note.task) attrs.append(link(byTask(note.task)?.title || note.task, taskHref(note.task)));
        if (note.skill) {
          const caption = meta(note.skill_title || note.skill, versionLabel(note.skill_version));
          attrs.append(note.skill.startsWith('library:')
            ? link(caption, skillHref(note.skill.slice('library:'.length)))
            : element('span', '', caption));
        }
        list.append(element('li', '', time, element('p', '', note.text), attrs));
      }
      records.replaceChildren(heading(t('Collaboration log'), element('small', '', counted(group.notes.length, '{count} note', '{count} notes'))), list.children.length ? list : hint(t('Team updates and recorded skill use will appear here.')));
    }
    function renderBoard() {
      board.hidden = !doc.board;
      if (!doc.board || !changed('board', doc.board)) return;
      if (doc.board.status !== 'ready') {
        boardContent.replaceChildren(hint(t('Shared board is unavailable.')));
        return;
      }
      const members = element('div', 'sw-roster');
      for (const member of doc.board.members) {
        members.append(element('span', 'sw-seat', element('strong', '', member.name), element('small', '', member.role || '')));
      }
      const posts = element('ol', 'sw-notes');
      for (const post of doc.board.posts.slice().sort((a, b) => b.seq - a.seq)) {
        const time = element('time', '', post.time || '');
        if (post.time) time.dateTime = post.time;
        posts.append(element('li', '', element('div', 'sw-post-meta', element('strong', '', post.agent), time), element('p', '', post.text)));
      }
      boardContent.replaceChildren(element('h4', '', t('Board members')), members.children.length ? members : hint(t('No board members recorded.')),
        element('h4', '', t('Latest posts')), posts.children.length ? posts : hint(t('No posts in the main channel.')));
    }
    function renderSkills() {
      if (!doc) return;
      const term = search.value.toLowerCase().trim();
      const source = filter.value;
      const matches = doc.skills.filter(skill => {
        if (source && source !== skill.source) return false;
        if (!term) return true;
        const fields = [skill.title, skill.source_id, skill.category, skill.domain, skill.version, skillOrigin(skill)];
        return fields.join(' ').toLowerCase().includes(term);
      });
      const registry = {unconfigured: t('Shared registry is not configured.'), unavailable: t('Shared registry is unavailable.')};
      skillInfo.textContent = [counted(matches.length, '{count} skill', '{count} skills'), registry[doc.registry_status]].filter(Boolean).join(' · ');
      const uses = new Map();
      for (const g of doc.swarms) for (const n of g.notes) if (n.skill) {
        if (!uses.has(n.skill)) uses.set(n.skill, new Map());
        uses.get(n.skill).set(g.id, g.name);
      }
      skillList.replaceChildren();
      for (const skill of matches.slice(0, catalogLimit)) {
        const title = skill.source === 'library' ? link(skill.title, skillHref(skill.source_id)) : element('strong', '', skill.title);
        const origin = element('small', 'sw-origin', skillOrigin(skill));
        const card = element('article', 'sw-skill', origin, title, element('small', '', meta(versionLabel(skill.version), skill.domain, skill.category)), element('code', '', skill.source_id));
        const groups = uses.get(skill.id);
        if (groups) {
          const related = element('div', 'sw-related', t('Recorded by '));
          for (const [id, name] of groups) related.append(button(name, () => { switchTo(id); summary.scrollIntoView({block: 'center'}); }, 'sw-text-button'));
          card.append(related);
        }
        skillList.append(card);
      }
      if (!matches.length) skillList.append(hint(doc.skills.length ? t('No skills match this search.') : t('No available skills. Keep a skill in the Library or connect a shared registry.')));
      if (matches.length > catalogLimit) skillList.append(button(t('Show more skills'), () => { catalogLimit += 24; renderSkills(); }));
    }
    function closeEditor() {
      editor = null;
      editorSlot.replaceChildren();
      editorSlot.hidden = true;
    }
    function openEditor(group) {
      if (busy || !doc.writable) return;
      if (editor && editor.groupId === (group?.id || '')) { editor.name.focus(); return; }
      const name = textField('name', group?.name, 120, false, true);
      const goal = textField('goal', group?.goal, 2000, true, false);
      const memberList = choices(t('Members'), 'members', doc.members.map(s => [s.actor, s.name || s.actor, meta(s.role && t(s.role), s.model)]), group?.members || [], t('No seats in this run.'));
      const taskList = choices(t('Linked tasks'), 'tasks', doc.tasks.map(t => [t.id, t.title || t.id, meta(t.id, translateState(t.state))]), group?.tasks || [], t('No tasks in this run yet.'));
      const error = element('p', 'sw-error');
      error.role = 'alert';
      const fields = element('fieldset', 'sw-fields', label(t('Swarm name'), name), label(t('Goal'), goal), element('div', 'sw-columns', memberList, taskList),
        formActions(group ? t('Save changes') : t('Create swarm'), button(t('Cancel'), () => { closeEditor(); add.focus(); })));
      const form = element('form', 'sw-card sw-form', heading(group ? t('Edit swarm') : t('New swarm')), fields, error);
      let createId = requestId();
      form.addEventListener('input', () => { error.textContent = ''; createId = requestId(); });
      form.addEventListener('submit', event => {
        event.preventDefault();
        if (!name.value.trim()) { name.setCustomValidity(t('Enter a swarm name.')); name.reportValidity(); name.setCustomValidity(''); return; }
        const values = new FormData(form);
        const identity = group ? {id: group.id, revision: group.revision} : {request_id: createId};
        const data = {run: doc.run, name: name.value.trim(), goal: goal.value.trim(), members: values.getAll('members'), tasks: values.getAll('tasks'), ...identity};
        write('/swarms', data, fields, error, saved => {
          selected = saved.id;
          closeEditor();
          message.textContent = group ? t('Swarm updated.') : t('Swarm created.');
        });
