      editor = {groupId: group?.id || '', name};
      editorSlot.replaceChildren(form);
      editorSlot.hidden = false;
      name.focus();
    }
    function renderNoteForm(group) {
      noteSlot.hidden = !group || !doc.writable;
      if (noteSlot.hidden) { noteForm = null; noteSlot.replaceChildren(); return; }
      if (!noteForm || noteForm.groupId !== group.id) {
        const draft = drafts.get(group.id) || {text: '', member: '', task: '', skill: '', id: requestId()};
        drafts.set(group.id, draft);
        const body = textField('text', draft.text, 4000, true, true);
        const refs = {};
        const refRow = element('div', 'sw-note-refs');
        for (const field of ['member', 'task', 'skill']) {
          const select = element('select');
          select.name = field;
          refs[field] = select;
          refRow.append(label({member: t('Member (optional)'), task: t('Task (optional)'), skill: t('Skill (optional)')}[field], select));
        }
        const fields = element('fieldset', 'sw-fields', label(t('Work note'), body), refRow, formActions(t('Add note')));
        const error = element('p', 'sw-error'); error.role = 'alert';
        const form = element('form', 'sw-card sw-form', heading(t('Record collaboration')), fields, error);
        form.addEventListener('input', () => {
          Object.assign(draft, {text: body.value, member: refs.member.value, task: refs.task.value, skill: refs.skill.value, id: requestId()});
          error.textContent = '';
        });
        form.addEventListener('submit', event => {
          event.preventDefault();
          if (!body.value.trim()) { body.setCustomValidity(t('Enter a note.')); body.reportValidity(); body.setCustomValidity(''); return; }
          const data = {run: doc.run, swarm: group.id, id: draft.id, text: body.value.trim(), member: refs.member.value || null, task: refs.task.value || null, skill: refs.skill.value || null};
          write('/swarms/note', data, fields, error, () => {
            drafts.delete(group.id); noteForm = null;
            message.textContent = t('Note recorded.');
          });
        });
        noteForm = {groupId: group.id, refs, draft, first: true};
        noteSlot.replaceChildren(form);
      }
      const {refs, draft} = noteForm;
      updateSelect(refs.member, group.members.map(id => [id, who(id)]), t('None'));
      updateSelect(refs.task, group.tasks.map(id => [id, byTask(id)?.title || id]), t('None'));
      updateSelect(refs.skill, doc.skills.map(s => [s.id, meta(s.title, versionLabel(s.version), skillOrigin(s))]), t('None'));
      if (noteForm.first) {
        for (const [key, node] of Object.entries(refs)) node.value = draft[key] || '';
        noteForm.first = false;
      }
    }
    function render() {
      if (requests.signal.aborted || !doc) return;
      grid.hidden = catalog.hidden = false;
      runLine.textContent = meta(doc.writable ? t('Live run') : t('Archived run · read only'), doc.run);
      add.hidden = !doc.writable; add.disabled = busy;
      if (!pick(selected)) selected = doc.swarms[0]?.id || '';
      const group = pick(selected);
      renderGroups(); renderSummary(group); renderNotes(group); renderNoteForm(group); renderBoard();
      if (!doc.writable && editor) closeEditor();
      if (changed('skills', [doc.registry_status, doc.skills, doc.swarms.map(g => [g.id, g.name, g.notes.map(n => n.skill)])])) renderSkills();
      if (options.onData) options.onData(doc);
    }
    async function write(path, payload, fields, error, success) {
      if (busy || requests.signal.aborted || !doc.writable) return;
      epoch++; reading = null;
      busy = true; fields.disabled = true; add.disabled = true;
